Object.assign(window.__TXT,{"10000": "左喉风，红肿欲腐，脉数。阴薄肝亢，温邪内郁，势在方张，未可忽。", "10001": "右心肝不潜，风火郁肺，发为烂喉风，脉数不畅。防腐蔓延，不可忽视。", "10002": "右心肝不潜，风火郁肺，发为烂喉风，脉数不畅。防腐蔓延，不可忽视。", "10003": "右喉关红肿，哽痛妨咽，兼之痰核不一，左耳失聪，脉数。宜平肝泄风。", "10004": "张目：营虚肝亢，化风上升，头右半作痛，目起星，经居三月，头眩晕耳鸣，脉微滑，治在阴分。", "10005": "林目：阴不涵阳，颧赤目干，咽干，寐不安，脉软弦微数。治在阴分。", "10006": "朱鼻：鼻衄连日不止，头晕微热，脉数。防转重，弗忽。", "10007": "潘目：目赤、星翳稍愈，步履较前稍能轻便，脉弦，腰背痛。宜治所急。", "10008": "杜耳：气阴不足，由来己久，气虚则积痰，阴虚则火浮，痰与火上蒙清窍，耳鸣重听之所由来也。脉濡滑。治宜标先后本，俾无助火滞痰之弊。", "10009": "杜耳：肾开窍于耳，肾水不足，木火挟痰气乘之，遂成重听。脉左部软弦，右软滑实。积根深远，非标本治之不可。", "10010": "沈鼻：水不涵木，木火挟风毒结于眼胞，毒肿溃至甚，攻及鼻内，溃至鼻梁，牙关紧，半面尽肿，脉细数。内外同病，不易奏功。", "10011": "顾齿：牙槽风，内外肿甚，牙关拘紧，作痛焮热，表热脉数。风郁阳明络。治宜清化泄降主之。", "10012": "王齿：牙槽风，内外肿胀，稍有寒热，脉数带弦。当内外两治。", "10013": "沈齿：牙骱痈久伏，牙关紧，脉数。肝木不潜，风热上亢。宜泄化主之。", "10014": "张齿：穿腮牙痈外肿极坚，牙关启闭不利，头痛耳鸣，易于惊惕，脉细。法当先治所急。", "10015": "玉齿：齿痛较减，肝木未平，二便不流利，脉弦。宜平肝泄降。", "10016": "曾齿：风热入阳明络。左牙龈肿痛，曾有寒热，脉数。宜清化泄降。", "10017": "王（正号）齿：表热之后，肌灼口干，牙骱酸，启闭不便，头胀而晕，脉软弦微数。阴虚肝亢，伏风流走。宜内外两治。", "10018": "孔齿：脉弦沉。水亏肝旺，风复亢之，齿痛不已，连及头部，外寒内热，胸闷，不思食，大便多日未行，舌白。宜平肝火，泄风热，以冀借此应手。", "10019": "孙太太营虚水亏，痰气互阻，结为乳癖，脉弦细。阳明素有湿热，须肝胃兼治。", "10020": "项咳嗽不畅，胸痛咽痛，脉濡滑，乳块作胀。当治所急。", "10021": "宋郁火伤阴，痰气交结，酿成乳岩，溃腐流血，旁坚如石，脉细。此脏病也，为外症中之内病，理之不易。", "10022": "施（右）痰气入络：痰气流络，络气失宣，左腿骱酸痛，不能行动，盗汗，脉细弦。因虚而病，理之不易。", "10023": "江（右）疬痰：疬痰久积，中间软而且红，已有伏脓，势难消散，作寒发热，脉细。肝胃虚而营卫失调，收功殊非易易。", "10024": "陆流注：流注，腐肉尚未脱尽，新肉见而不多，脉濡。宜托未尽之毒，参以养营宣络，使气血和畅，以希早日完口。", "10025": "洪风痰：时毒风痰，大势初定，左边处坚硬，脉数而伏。风痰浊交阻胆胃，络气失宣。宜泄风清火进之。", "10026": "沈牙槽风：牙槽风，内外肿胀，稍有寒热，脉数弦。当内外两治。", "10027": "沈肺痈：肺痈脓血较减，臭痰尚多，舌黄质红，脉弦数。火升少寐，肢冷。体虚，病冗，理之不易。", "10028": "程疽：偏背疽，新肉红甚，四围孔多，脉软弦。气阴两乏，适当湿令，胃呆，不能重用补药，收口未免稍迟，宜起居慎之。", "10029": "方囊肿：溲痛得瘥，囊肿仍甚，表热脉数。湿热内恋，当以泄化。", "10030": "金肺痈：肺痈，近日又反复，且伤风，脉弦数，鼻塞手冷，腹痛。病绪见多，兼顾不易。", "10031": "戴脱囊：癣药咬破肾囊，借因延腐大痛。此中有湿热为患也，脉濡，头蒙，本体不足，既防脱囊，又虑别生枝节，急急解散湿热为要。", "10032": "金牙槽风：表热，牙槽风，肿胀作痛，纳少，脉数。风热走入阳明络，势在方张，未可忽视。", "10033": "杨癀痘：胸闷瘕攻，头晕，癀痘满布，舌白，脉微弦。宜兼顾旁。", "10034": "徐流注：病缠三月，形色脉俱惫，便溏，跨马流注，肿胀。内外同病，不易治。", "10035": "周痰痈：风湿痰浊交阻，痰痈肿胀，表热，脉数。最防痰升气塞。不可忽。", "10036": "刘流痰：气郁化痰，痰入筋骨间，发为流痰，溃头之后，气营交困，络脉失养，患处肿木，肿重手臂不能举动，脉右软左微弦，内因之症，不易速效。", "10037": "贵姑太太痔疾：据述痔疮纠缠，便后绕肛易肿。此气阴不足，湿热下陷所致，迩来肝脾不调，脘脐作痛，感冒咳嗽，脉沉滑，右带数。宜择要立方。", "10038": "邵湿毒流痰：湿毒流痰，腐久不敛，易于出血，两膝酸，脉濡。湿热走三阴络分，营络受损。一时不易速效也。", "10039": "陆疡：心肝不潜，蕴热上亢，后项脑际作胀，痛楚不能著枕，脉大微数。延防凝聚成疡，未可忽。", "10040": "程流痰：流痰复溃，脓多气秽，足膝无力，脉软少神。肝肾积虚，急当培补，以冀渐渐见功。", "10041": "林腰腿酸：脉软，咳嗽气逆，气短，腰腿酸软，积虚已甚，治宜求本。", "10042": "金山巨富家（姓名已遗录）少腹之下，胯弯之上，横肿僵木，确系横痃景象，子龙丸、犀黄丸均出《全生集》。服之未必得力，刻下所肿如卵，渐觉抽痛，此蒸脓也。由湿痰下注，肝肾络阻，痹阻气血而然。地处至阴，所以溃脓不透，非一定纯阴症也。方书有谓：溃而不敛，是说不确，惟刀针断不宜早用，熟透自溃，尤为稳妥。阳和汤，阴症药也，汤中熟地、鹿角胶，易滞痰湿，麻黄、桂、姜，易伤阴分，虽各有相济功用，而夏秋久服，究非所宜。（拙见）只须宣通血脉，疏解痰湿，以期可消。即或已有伏脓，亦足以定发越之势。悬拟方，附加减法。并候。", "10043": "李湿热入关节：湿热流入关节，两腿酸痛，痛入腿骱，舌白黄，脉数。毒郁不宣。宜清化分利。", "10044": "李防聚疡：两腿弯酸痛，不能履地，形寒微热，头胀胸闷，脉数。防转重弗忽。", "10045": "颜湿疹：头痛耳鸣失聪，便发湿疹，头项伏核不一，脉数。宜泄降法。", "10046": "和尚脱肛：气分不足，湿热下陷，始病痔坠，渐转脱肛，脉濡。宜先清利湿热。", "10047": "邓结疡：肝肾虚寒，寒湿下阻，右足肿痛，延防结疡，脉来濡。姑先急则治标。", "10048": "纪（正号）环跳作痛：三阴不足，痰湿逗留，左环跳，流走作痛，久不止，迩来神疲，嗜卧，脉左细不畅、右虚弦，腹中作胀。气机不舒，病绪杂出，当循序养之。", "10049": "刘口歪：湿疮不净，近又口歪，脉微数。宜泄风清热利湿。", "10050": "陆疬痰：疬痰受风复发，肿硬酸痛，头晕纳少，口干苦，脉数。防溃头。", "10051": "钱（右）鹤口疽（在尻骨之下，粪门之上）：据述鹤口疽，肿溃流脓，脉细。最防淹缠不已。", "10052": "严流注：流注发于左肩臂，痛楚著骨，舌黄腻，脉数。伏风深重，不易消散。", "10053": "丁体麻：疡症收口之后，痰浊阻络，气血不能流利，左半体麻木，脉软弦。宜标本两治。", "10054": "吴疮后：日来咳痰较浓，咳声时松，时窒，自患湿疮以来，形疲色夺，脉数，近增寒热，本症之外又有新感，须解散之。", "10055": "项骨槽风：肝肾不足，风入筋骨间，右牙骱酸痛著骨，脉细。此骨槽风也。", "10056": "龙病经两月余，仍是气机呆，默默无语，左脉细甚，右较大较弦，舌中裂，尖绛。心肾两亏，痰热挟肝胆气火上亢，本虚标实，风波易易也。", "10057": "姚虚损，百节尽痛，气急，夜卧如喘，胃呆不欲食，脉细。根本槁极，恐非草木可以为力者。", "10058": "文心神恍惚渐定，夜寐交安，便溏亦瘥，仍有往来寒热，脉细。", "10059": "孙（幼）风热客上焦，手太阴受病，发为喉疳，腐势甚盛，脉数。正当发越之际，非清化泄降不可。", "10060": "汪气营不足，神思倦怠，脉细，畏寒。宜从本原调理。", "10061": "陆脱力久不复，舌白，脉濡。宜通阳泄浊。", "10062": "撷（翁）脉软，气不足也；足底易痛，肾阴虚也，手足尚常少力。补气养营，化风痰，通经脉，标本兼治，方有裨益。", "10063": "张气郁，血滞经阻，寒热近又咳嗽，腹不舒，脉软弦细。积病深远，非易速效。", "10064": "朱恶寒恶心，少纳头晕，痰多，脉濡滑。颇有怀麟之状，须慎养起居。", "10065": "连心胸痛，气急，有汗畏风，热不透，脉弦。宜表里两治。", "10066": "朱脘痛大势得减，脉细弦，舌中剥。宜守前意增减。", "10067": "张惊恐抑郁，心肝交病，不得寐，咳不畅，心宕气逆，脉濡。须加意慎养。", "10068": "徐消渴渐瘥，便热，脉微滑，神疲。宜生津化湿热。", "10069": "益以当门□珠（金银）箔，转筋脉伏力能匡。", "10070": "闻之士生斯世。不为良相。当为良医。盖以良相良医皆可救斯人之疲癃残疾。而不忍坐视其颠连而莫告也。然非识学兼到。相固不能济世。即医亦不能济人。吾考古之名相。无识何以旌别淑慝。求贤以辅治。无学何以本仁祖义。监古以善今。古之名医。无识何以审病源之虚实。而调剂得其平。无学何以明脉理之精微。而制治有其要。是可知医国医人。初无二理。为相良固难。为医良亦不易也。无怪乎求良医于当代。不少概见。惟吴中天士叶老先生庶名克副实。不愧为良欤。粤稽叶老先生精通脉理。洞见病源。用药尤能心小胆大。当日之无远无近染疴求治者。日不暇给。症多怪异。而方亦新奇。每授汤丸。无不效验。所谓不笏而饶相业。有枢以转天心者。舍先生其谁属。所以仲升周子日侍左右。每见方案。无不汇而集之。积成卷帙。虽人之致病各殊。投剂亦异。未可以张冠戴李。致有毫厘千里之失。然读书临症之余。备以广博览。亦未始无旁通之益焉。其年顾亲翁。世叶岐黄。亦有见及此。因即假周子原本。细心抄录。持以示余。乞余为序。余于披览之下。见叶先生按症酌方。各有因心之妙用。子夏云、虽小道必有可观者焉。良不诬也。后之学者。苟勿视为古人糟粕。而能深求其精义。无负叶老先生揆方之精心。与周子汇集之苦志。则识学虽未必兼到。而亦稍稍有合乎不为良相当为良医之遗意。岂不大有功于斯世哉。余不揣固陋。冒昧为序。望勿以言之不文而姗笑之。幸甚。", "10071": "嗽而脉数。脏阴亏矣。金水同治。第参之色脉。恐延损怯。", "10072": "脉数咳嗽。盗汗形寒。营卫交虚矣。", "10073": "脉数无序。阴亏阳亢之象。虽血来点粒。春夏木火炎炎。焉得保其不发。", "10074": "脉弦且出鱼际。木火郁而不泄。阳明无有不受其戕。是以食下稍有不适。则为䐜胀。饥则嘈杂难耐。自宜肝胃同治。肝木宜疏。胃府宜降。乃其治也。", "10075": "脉细如丝。形神尩羸。嗽而气逆。下焦阳气颇衰。最虑喘脱。延至春和日暖。始可无虞。", "10076": "脉数而软。嗽逆暮盛。", "10077": "阅病原。望色萎黄。参脉微细。此中阳困顿之候也。是以烦劳病呕尤甚。法宜温之。", "10078": "脉沉弦。脘胀噫气。口燥不寐。宜和肝胃。", "10079": "脉微细。", "10080": "脉虚。知饥恶食。宜益营分。", "10081": "腹痛已止。左脉尚弦。", "10082": "咽喉如梗。脊热头旋。形神尩羸。脉来微细。经事如期。此属督脉空虚之候也。法宜温养。", "10083": "左脉弦。咳嗽。阳气偏亢。温邪侵之。宜用甘药。", "10084": "脉尚弦芤。初之气中乙癸同治。", "10085": "脉涩。食下拒纳。宜理胃阳。", "10086": "咳嗽失血。左脉弦数。少阴颇亏。厥阳不潜使然。", "10087": "脉细涩。咳嗽三月不愈。温邪伏于肺卫使然。渐延阴损劳怯。", "10088": "噫气脉弦长。此木火上逆刑金。清降之司失职。延久有噎格之患。开怀为主。", "10089": "脉出鱼际。吞酸神倦。此木火内郁。阳明受戕。所谓壮火食气是也。", "10090": "脉涩。便血心悸头胀。此营虚阳浮不潜为病。", "10091": "劳伤失血。脉细。", "10092": "脉微形痹。正气已亏。温邪未净。症势不轻。", "10093": "左脉数。咳嗽耳聋。", "10094": "郁则络瘀气痹。失血气逆。法宜宣通。但脉弦劲。正气已虚。当以甘缓。", "10095": "脉涩。痰多肢麻。虚风鼓动使然。", "10096": "头重脘闷。脉弦。", "10097": "络瘀泻之为但左脉弦劲。肝阴颇亏。厥阳偏炽。亦不宜以此为长计也。", "10098": "脉浮弦。", "10099": "脉涩。咳嗽背凛。", "10100": "脉沉迟。阳气殊虚。湿痰内阻经隧。右眶跳跃。乃类中之萌也。当戒酒勿劳动为要。", "10101": "脉弦数。咳嗽头胀。", "10102": "脉数。梦泄咳嗽。", "10103": "病后脉数不复。三阴亏矣。谨慎调理。弗致重损。", "10104": "脉细数。咳嗽音哑。此属阴损。金水同治。", "10105": "久嗽腰痛。行动气逆。脉细失血。", "10106": "温邪脉小。怕其内闭。", "10107": "脉弦涩。肢麻痰多。阴血颇亏。虽有痰阻。以末治之。", "10108": "脉数无序。上焦肺气燥矣。胸臆隐隐痹痛。怕其咳吐痰血。", "10109": "脉弦腹痛。便泄不爽。此下焦阳微。阴浊僭逆使然。", "10110": "脉歇。阳伤阴干。便泄腹膨。宜节食物。", "10111": "食下拒纳。左脉弦数。此属噎格。", "10112": "温邪郁于肺卫。咳嗽音嘶。脉微。", "10113": "脉弦而涩。肝阴颇亏。中气亦弱。肝胃同治。", "10114": "左脉数。", "10115": "脉微不耐按。真元已惫。何暇理邪。症危不易图治。", "10116": "脉弦滑。痰饮内阻。左肢麻木。疟后致此。由伏湿未净。升降之机失司。是以酿为浊邪耳。", "10117": "喜饮热酒。胃络积热血瘀。中脘痹痛。谷食渐减。脉来弦涩。年已望五。最虑营枯气结。他日有关格之患。", "10118": "形寒咳嗽。脉小。", "10119": "哕逆脉弦。胃虚木乘使然。", "10120": "脉小肢麻。属阳微失护。痰饮内阻。日久有类中之患。", "10121": "久利。脉涩腰酸。", "10122": "脉微阳伤。三疟形浮。", "10123": "易感客邪。肺卫虚耳。而脉细涩。少阴肾精亦亏。当以培补为妥。刻下且以滋养柔金。清肃卫热。", "10124": "左脉弦涩。心营暗耗。心阳不宁。寤多寐少。心悸怵惕。静养为主。", "10125": "左脉弦。", "10126": "脉微。", "10127": "脉弱带数。真元颇亏。内热咳呛。", "10128": "脉弦。胁痛绕脘。得饮食则缓。营气困耳。治以辛甘。", "10129": "疟伤脾阳。脘闷少运。脉细。法宜温理中焦。", "10130": "色萎。脉弦数。营损之象。益以甘缓。", "10131": "脉微。久泄瘕聚。", "10132": "有年气弱。食下少运。左脉弦劲。肝邪僭逆。将来恐有关格之患。", "10133": "嗽逆不得卧。短气脉涩。", "10134": "温邪作咳。脉弦数。恐咳伤阳络失血。", "10135": "肝风痉厥。今色萎脉软。气渐馁矣。宜甘缓益之。不必见病治病。", "10136": "脉数。失血咳嗽。", "10137": "脉涩。左肢麻。胁痛不能左眠。大便溏泄。此肾真空虚。木少涵养。厥阳冲扰。阳明失阖使然。无如乏力用参。惟摄少阴而已。", "10138": "咳嗽音嘶。脉细。宜摄少阴。", "10139": "少阴空虚。冲气上逆。卧则咳呛。咽干隐隐燥痛。少阴之脉循喉咙。阴少上承。阳乃亢耳。", "10140": "阳伤挟邪。形凛发热咳嗽。脉带歇。恐喘急。", "10141": "脉微按之数。咳嗽。食下便溏。此阴损及阳。殊不易复。须胃强能纳。庶可撑持。", "10142": "脉弦。", "10143": "络伤失血。脉弦而虚。恐其难耐夏热。", "10144": "噎格脉弦。胃气空也。乏力用参。如之何图功。", "10145": "精浊日久。咽干脉细。", "10146": "脉细而涩。脘痛食下拒纳。乃血格之候。症重。", "10147": "少阴阳虚。饮逆喘急。不得卧。脉微。法宜温纳。", "10148": "脉涩火升。食下稍有不适。即漾漾欲呕。究属下焦空虚。气冲无制使然。法宜填摄。", "10149": "虽属瘀血。上吐下泄。而中焦气亦为之暗伤。色萎脉涩。耳鸣神倦。行动气逆。当治以甘温益虚。不宜谓其瘀而攻之。", "10150": "脉涩。少腹症积。不时攻逆作痛。心中嘈杂。症积痹在血分。宜攻宜泄。第营血颇虚。只宜养之和之。", "10151": "脉弦饮也。饮阻则阳郁。是以背痛形凛。宜以温药和之。", "10152": "血止身痛。左脉尚弦。", "10153": "食下气噫胸痛。脉涩。此血阻气痹。乃高年噎格之渐。未易调理。", "10154": "胁痛继而失血。仍属络瘀。但气逆欲喘。背恶寒心中热。诊脉左弦。究属少阴不藏。肝阳扰络使然。切勿攻瘀。重虚其虚为要。嗜如酒浆。尤宜禁忌。", "10155": "嗽不减。左脉弦。", "10156": "脉弦劲。", "10157": "形丰脉小。的是阳气外越。阴湿下著。腿浮酸痛。在法自宜温阳泄湿。无如阳气外越。温药素所不宜。谅未能下达耳。", "10158": "梦泄盗汗。左脉弦数。脏真内亏。阳浮不潜。", "10159": "复胀色萎。脉弦气急。非胃府病。乃下焦阳衰也。与前胀满迥异。", "10160": "久嗽用肺药不应。脉数。金水同治。", "10161": "脉长鼻衄。阳升使然。", "10162": "脉动搏且长。相火偏炽。阴分失固。咳呛痰血。最易成损。全在自知病因。勿妄欲念。恐心动精摇耳。", "10163": "梦泄。脉虚尺微。", "10164": "脘痛脉弦。", "10165": "右脉尚弦。", "10166": "脉弦。头旋恶心。", "10167": "腿软头眩。脉细。", "10168": "脉弦。", "10169": "脉弦虚。", "10170": "左脉数。按之无序。阴亏阳动之象。日久恐有失血之累。但鼻血咳呛项核。先宜清理上焦。", "10171": "肝胃同治颇应。但脉数。耳鸣梦泄。当填补下焦。", "10172": "左脉数。渴饮晡热。脏阴失守。阳浮外泄。虚损致此。最不相宜。恐夏气泄越。阴愈耗也。", "10173": "脉数无序。色萎。形瘦身热。脏阴损矣。急急防维。勿忽视之。", "10174": "久嗽。左脉弦。", "10175": "温侵嗽盛。清之是适。而脉微涩。形瘦食少。真元颇亏。年未及五。乃未老先衰之象。", "10176": "食下格拒。痰涎泛溢。脉来歇。此阳气不宣。痰浊上阻使然。", "10177": "左脉弦数。", "10178": "脉缓。", "10179": "脉弦劲。咳嗽。宜摄脏阴。", "10180": "左脉弦。", "10181": "脉小。", "10182": "左脉弦数。咽痛如梗。", "10183": "形盛脉微。阴浊内盛。阳困不宣之象。食下䐜胀。中脘时作胀痛。阳以通为运。阳气流行。阴浊不得上干矣。所谓离炤当空。阴霾消散是也。而久痛非寒。偏于辛热刚愎。又非所宜。惟和之而已。", "10184": "脉细涩。带下赤白。", "10185": "左脉弦。不时神烦。头旋腰酸。食下少运。此少阴空虚。阳浮不潜使然。药饵弗宜偏于温热。", "10186": "脉小。阳未振动。自觉鼻孔凉生。肺开窍于鼻。主乎一身之气。气弱阳微。是其征也。", "10187": "咽痛暮盛。痰多脉小。午后形凛。水涸阳乃浮矣。", "10188": "脉数。内热背痛。", "10189": "身痛脉涩。宜和营卫。", "10190": "脉数。", "10191": "冲疝里急腹痛。法宜温养。但脉来弦涩。寤多寐少。营阴颇亏。偏于辛热不宜。", "10192": "久嗽。形寒身痛。脉浮弦。", "10193": "脉细。", "10194": "络痹。右胁癖积。脉涩。法宜通泄。", "10195": "脉弦。来去不调。营卫未和。是以不饥。胸臆时痛时止。法宜和之。", "10196": "左脉尚弦。", "10197": "脉弦数。", "10198": "晡热。右脉弦大。阴弱伏温。且养阴和阳。", "10199": "五志内燔。心悸舌糜。宜存阴泄阳。第脉弦涩。不宜过于苦寒。", "10200": "形丰脉微。阳气自薄。进以六味地黄。纯阴碍阳。是以心悸阳痿。议用通阳。以消阴翳。", "10201": "冷物伤中。脘痛脉沉。", "10202": "脉弦长。木火偏亢。嗜酒更助其胆热矣。是以口糜味甜。法宜苦辛泄之。", "10203": "高年病后脉歇知饥。营血枯矣。勿以便艰而攻涤。", "10204": "食下少运便泄。少腹气坠。脉细。命门火虚。清阳下陷。日久有腹满气急之患。", "10205": "嗽逆脉数。肺阴耗耳。恐延肺痿。", "10206": "脉涩不利。梦泄食少内热。此少阴阴亏。谷气水湿下注。乃阴亏湿热之候也。", "10207": "脉弦劲。木火偏亢。逼络血溢。血失反能食。阳明亦热矣。议用苦降法。", "10208": "血虽止。脉尚弦数。晨起咳呛。阴亏阳动不潜使然。静养为主。", "10209": "失血后。脉涩咳呛。宜养肺胃之阴。", "10210": "脉弦。身热从汗泄而解。此属伏湿。恐其转疟。", "10211": "劳伤肝阳络松失血。左脉弦。", "10212": "右关沉涩。左脉弦劲。此木火内亢。阳明络泣。脘痛嘈杂头旋。", "10213": "脉弦腹膨。气逆动怒致此。肝邪冲逆阳明也。切勿嗔怒。势恐变幻。慎之慎之。", "10214": "咳而呕逆。脉虚弦。宜益肝胃。", "10215": "脉细神倦。气弱也。气弱则不能统摄。精浊不已。先宜调益心脾。", "10216": "左脉弦数。头重味酸肢冷。病后致此。乃脾阳困顿。木火顺乘。阳明少降使然。东垣谓补脾胃必先远肝木。良有以也。", "10217": "脉细虽属少阴空虚。而中焦有伏饮。是以嗽逆呕恶。先宜理之。", "10218": "脉涩淋浊。法宜导火。", "10219": "疳积腹痛。形瘦脉虚。勿忽视之。", "10220": "音嘶咽痛。脉细涩。的是少阴肾真空虚。无以上承使然。切勿烦劳。夏暑炎蒸。宜绿荫深处静养为要。", "10221": "寒热胁痛。脉弦。温邪袭于肝络。吐血犹可。最怕成痈。", "10222": "咳嗽失血。左脉犹弦。此努力络伤为病。", "10223": "左脉弦。嗽血气逆。酒客动怒致此。当理肝胃。", "10224": "咳嗽失血。脉涩。下焦不纳。春深气泄使然。", "10225": "脉长弦数。阴亏阳不宁静。食下便溏。亦肾为胃关之义。", "10226": "脉弦而濡。气分殊弱。湿热不能尽泄。不饥少寐。神倦痰多。宜健脾和胃。佐以远木。", "10227": "脉沉小。久嗽足浮腹膨。少阴之阳已伤。故水饮欲泛。", "10228": "右脉尚弦。", "10229": "脉细数。脏阴下夺。虚损已露。", "10230": "脉仍弦数。", "10231": "舌黄脉缓。脾胃之气呆钝。湿邪未净。故不饥。", "10232": "脉细数。咳呛脘闷。宜清暑邪。", "10233": "暑湿上阻。头重脘闷。脉模糊。病势正在方张。", "10234": "脉细。食下格拒。宜理阳明。", "10235": "脉大乍小。邪伏于中。宜括痧。再服药。", "10236": "脉数。阴亏阳亢。气逆失血。", "10237": "脉微数。脏阴伤矣。冲气不纳。作为劳嗽。", "10238": "脉细数。岂有阴精不夺乎。以脉论之。虚损已露。自知病因。保真为要。", "10239": "脉细数。阴气颇弱。夏暑外逼。食减神倦咳呛。宜存阴清暑法。", "10240": "嗽减鼻衄。左脉弦。", "10241": "久嗽脉数。", "10242": "阴亏内热。左脉弦数。乙癸同治。", "10243": "暑湿下利。左脉弦。鼻衄。", "10244": "脉弦数。三阴颇亏。法宜填摄。", "10245": "暑湿成疟。脉虚。宜用和法。", "10246": "失血色夺。脉弦。恐其食减。", "10247": "脉弦数。", "10248": "脉弦涩。体质阴伤。阳浮不潜。咳嗽内热。法宜填摄藏真。", "10249": "脉数无序。阴阳挟邪难治。", "10250": "冲脉为病。逆气至咽。", "10251": "脘痞不饥。脉沉弦。味酸苦。疟后致此。宜苦辛开泄。", "10252": "吐血。脉空大。最不为宜。恐其暴涌气脱耳。当静养为要。", "10253": "血隶阳明而来。但脉芤而数。色痿少彩。少阴之阴伤矣。自知病因。葆真静养。庶几扶病延年。", "10254": "脉糢糊。欲成三焦疟。", "10255": "左脉弦数。肝阴不足切勿动怒。他日恐有失血之患。近今妨食恶心。暂和肝胃而已。", "10256": "咳嗽失血。脉大而数。由湿邪未净。延及少阴之损。将来有音哑之变。", "10257": "阅病原。参色脉。皆营阴不足。虚风萌动使然。法宜甘缓益阴。", "10258": "嗽久不已。病不在肺。而在少阴矣。且左脉弦数。法宜摄阴。", "10259": "肢麻肉𥆧偏左。脉涩。此虚风萌动。良由肾精肝血不足使然。", "10260": "下利半月。脉涩。此阴暑伤中。", "10261": "左脉弦数。阴亏气热。咳嗽口燥。", "10262": "脉沉细。胀渐甚。溺赤。", "10263": "疟虽止。色黄。脉呆钝。湿未净耳。", "10264": "络伤嗽血。脉弦。切勿动怒。", "10265": "脉弦呕恶。肝胃同治。", "10266": "脉数阴亏。气燥作咳。", "10267": "脉涩胃痛。此营阴枯槁。络气不疏使然。", "10268": "脉小。咳嗽背冷。", "10269": "此劳伤为嗽。脉来弦大。食减则剧。", "10270": "头风数载。不时举发。邪已入脑俞矣。且左脉沉细。岂三阳为患。隶在少阴也。弗至厥阴为妙。", "10271": "脉涩。背痛咳嗽。", "10272": "调理。近日呕恶脉弦。先宜降胃。", "10273": "肿满病。形羸脉微。二气交衰。治之岂易。所赖者、第以年富强耳。", "10274": "脉涩。", "10275": "经来腹痛。脉涩。宜两和气血。", "10276": "脉浮。身热头痛。", "10277": "此肾病也。腹胀腿麻。二便不利。诊脉沉细。法宜温纳。理阴中之阳为主。", "10278": "燥侵作咳。但左脉弦数。恐络动失血。", "10279": "脉数。少阴空虚。葆真为要。", "10280": "痛止脉弦。", "10281": "脉弦。", "10282": "左脉弦。瘅热知饥。色黄。", "10283": "咳嗽身热。脉弦数。阴虚挟邪。勿轻视之。", "10284": "究属肾病。肾为胃关。是以食少形倦。自宜温纳下焦为主。但右脉弦而有力。虚之实。未必无是理也。先宜疏胃益脾。", "10285": "左脉弦数。内热咳嗽痰血。脏阴暗耗。阳动不潜使然。", "10286": "脉弦数。先寒后热。头胀脘闷。属伏暑成疟。当分三焦。", "10287": "伏邪下利。脉弦。法宜和之。", "10288": "左脉弦。", "10289": "脉弦数。咳嗽虽缓。尚宜谨慎调摄。", "10290": "脉弦涩。舌苔腻。湿邪阻于中焦。木火不能疏泄。湿火内蒸。升降之机失职。为之胀满。法宜疏之。", "10291": "脉沉弦。腹膨不饥。", "10292": "左脉弦数。嗽逆气急盗汗。", "10293": "脉弦数。咳呛失血。", "10294": "诊脉软。心悸不耐烦。营虚气怯甚矣。", "10295": "哮逆不得卧。脉弦。", "10296": "子后咳逆嗽甚。汗多脉细。", "10297": "脉细。形神疲倦。显是命门真火式微。为之瘅胀肿满。王宇泰谓益火之源。以消阴翳。正此候也。", "10298": "脉象平和。热退头晕。宜调肝胃。", "10299": "身热头痛。身疼无汗。脉弦。", "10300": "三疟。色黄。脉弦偏右。", "10301": "脉右数。", "10302": "脉弦数。少腹气冲。映背交痛。此高年阴血槁枯。少阴肾气不摄。势欲为奔豚。法宜温养下焦。", "10303": "脉弦。不饥少纳。湿痰阴于中焦耳。", "10304": "脉数不宁。", "10305": "弦劲脉长。心悸嘈杂。此肝阳化风。冲激阳明所致。良由少阴不充。无以涵木耳。", "10306": "左脉弦。", "10307": "身热。头痛渴饮。脉浮弦。", "10308": "时病伤阴。阳浮不潜。神识时清时昏。脉来弦数。宜益阴和阳。", "10309": "脉不宁静。陡然失血。阳升扰络使然。", "10310": "脉弦。饮逆作咳。", "10311": "色脉皆不妥。胃强能纳。庶几望其痊可。", "10312": "脉涩心悸。内热。", "10313": "伏暑瘅疟。汗多脉细。", "10314": "胃痛便艰。脉涩。营虚络痹。恐延关格。", "10315": "脉涩下利。少腹啾唧。此阳微积著使然。法当温通。", "10316": "阴损及阳。寒热日加。脉数形瘦。其何以理。", "10317": "脉小。利止食少。", "10318": "失血每入秋发。脉细涩。属阴亏。气不收肃。扰络致此。", "10319": "客邪发热作咳。脉来细小无力。则为淹缠之候。", "10320": "脉弦涩。体质阴亏。阳易外浮。不时寒热。咳嗽失血。宜益阴和阳。", "10321": "脉沉弦。阴邪内郁。厥阴阳明不能疏泄。与泛泛下利不同。", "10322": "脉尚弦。", "10323": "神识虽清。脉象殊数。", "10324": "湿从下受。肿由足起。延及腹满食下胀痛。便溏不爽。脉来弦涩。其源起于三阴。而募原腑络痹不疏。宜从先治标之旨议法。", "10325": "脉不流利。气血痹矣。", "10326": "下利脉小而迟。食物不节。脾阳戕矣。", "10327": "脉迟。便血。心中嘈杂。由操劳使然。伤在心脾。", "10328": "脉长尺垂。下焦藏真不固。阳浮血溢神倦。属虚损。非瘀也。", "10329": "脏阴暗耗。气浮肤热。脉数腹膨。阴亏渐及阳位。此属虚损。最不易治。", "10330": "客邪咳嗽。今脉右弦数。嗽盛汗泄。上病延及下焦矣。是以音渐失也。", "10331": "脉细如丝。", "10332": "脉弦胃减。是以脘闷。食下䐜胀。便溏不爽。良由脾阳呆钝。不能点运水谷之湿滞。脾主升。胃主降。升降之机得宜。湿滞自宣。中脘自爽。莫谓体弱。即投以腻滞补药。", "10333": "色亮。脉弦涩。此饮阻于肺络。咳嗽不已。如以虚论。饮愈阻矣。", "10334": "脉数无序。里热甚矣。勿忽视之。", "10335": "形瘁脉数。阴枯气燥。络松失血。以形脉论之。病不易治。", "10336": "脉黄发热。咳呛脘闷。其开上焦。", "10337": "脉虚软。晨起恶心。胃阳薄也。", "10338": "左脉弦数。", "10339": "寒热经阻。形瘦脉涩。此属耗血。最不易治。", "10340": "脉弦数。禀赋阴弱。阳动不潜。络逆吐血。宜摄阴和阳。", "10341": "久嗽痰浓。胃中伏湿耳。但形神憔悴。脉微。最不易治。", "10342": "脉涩。经事先期。脘痛引及腰髀。不时寒热此二维为病也。良由营血不足耳。", "10343": "脉细。脘痛暮盛。吐出食物未化。此肾阳受戕。失宣降之司。所谓痛则不通是也。良由得之饥饱烦劳使然。以脉论之。日久恐有关格大患。未可不蚤为图之。", "10344": "尿血脉微。年已花甲。此肾阴下夺。阳失其化。是以血从小肠而下。肾藏失封固之本也。", "10345": "督虚背凛。脉来微细。此阴中之阳伤矣。法宜柔温养之。", "10346": "吐血脉歇。二气惫矣。谨慎调理。", "10347": "左脉弦。", "10348": "娠五月。足太阴司胎。太阴与阳明为表里。阳明隶乎冲脉。冲脉空虚。是以易于堕胎。法宜固之升之。", "10349": "胃痛数载。脉虚而涩。经事先期。此属营虚气痹。不宜过于辛燥。", "10350": "咳嗽盗汗鼻衄。脉数阴亏气浮使然。葆真为要。否则延怯。", "10351": "脉弦。嗽逆不得卧。属下虚不纳。乃虚症也。", "10352": "脉长而弦。不时梦泄。相火内炽。脏阴失守。入春大气发泄。最虑失血。", "10353": "劳伤肾。左脉弦数。", "10354": "左脉涩。按之跃。肾阴空虚甚矣。急急葆真。勿见咳投以清润肺药。", "10355": "湿郁蒸热。恶心。舌白。脉来弦数。转疟为顺。", "10356": "左脉弦。阴亏阳浮不潜。咳嗽盗汗。", "10357": "脉弦。胃痛年久。病在于络。", "10358": "脉涩。胁肘痹痛。此气血窒痹。营络不宣使然。日久有失血痈疡之患。", "10359": "脉涩。腿痛艰于步履。溺后如膏。小溲易癃。此属肾虚。延久恐成痿躄。", "10360": "阅病原。诊脉数。不独脏阴内虚。气亦少附耳。最虑食减喘急。", "10361": "湿郁成疟。脉弦小。宜辛温和之。", "10362": "脉涩。阴弱。气郁络痹。胸臆不爽。失血。养阴佐以辛润。与胃无碍。", "10363": "脉歇。饮邪内阻。咳嗽气逆。", "10364": "脉弦涩。阴液渐次枯槁。清阳势欲上结。脘膈不利。咽喉如梗。乃噎格之象。切勿动怒。", "10365": "复疟。舌黄脉弦。宜和肝胃。", "10366": "疟转下痢。脉细如丝。神倦不食。暑邪入里。正惫不能泄越。症险恐脱。", "10367": "脉弦数。利后发热。咳嗽头胀。", "10368": "脉数无序。少阴颇虚。", "10369": "舌白脉弦。", "10370": "左脉独弦。耳鸣偏左。木火无疑。", "10371": "脉数。阴液内耗。气燥化热。舌红苔黑。咳嗽渴饮。", "10372": "脉弦涩。嗽逆。此阴亏气浮使然。非客邪可散。先以胃药。", "10373": "左脉弦。疟来头胀。", "10374": "脉尚弦。", "10375": "湿邪内阻。腹痛下利。参之色脉。正气殊虚。勿忽视之。", "10376": "诊脉细涩。便血已二十余年。不时举发。近来头眩耳鸣。身若浮云。似难撑持。肉𥆧肢麻。此络血下渗。营阴暗耗。厥阳无制。化风内煽。此属脏病。关系甚巨。议用填固脏阴。收摄浮阳。以息内风。是其治也。", "10377": "三疟脉弦。", "10378": "脉数。努力劳伤失血。血去阴伤。气浮咳逆。渐延阴损。", "10379": "复疟。脉弦数。", "10380": "左脉弦数。咳嗽脘闷寒热。", "10381": "脉弦。胸胁痹痛引背。曾吐瘀食下拒纳。此属血格。", "10382": "脉涩。失血咳嗽。妨食盗汗。渐延劳怯之途。勿忽视之。须静养为妙。", "10383": "暑风上受。首先犯肺。执蕴不解。逆传心包。肝阳化风。盘旋舞动。神昏谵语。脉虚。急宜辛凉。开热疏痰。俾神魂复摄，斯无变幻。为今治法，须治上焦。苦降消克。是有形有质。非其治矣。", "10384": "黏痰咳呕外出。邪有外达之机。神识颇清。正有渐复之势矣。但筋惕脉虚。元气实馁。扶过秋分大节。得不变幻。方可。", "10385": "阳脉涩。阴脉弦。法当腹中急痛。今复沉郁暴寒。宜更进一筹。拟方备采。", "10386": "田展初五兄，予至好也。嘉庆十四年，伊远馆吴门。其内染时邪之症。医者皆用伤寒药，发散升提太过，其热不解减。又皆竞用寒凉，如黄芩、黄连、山栀、石膏之类。连进多剂，热仍不减。面转通红，头皮作痛，手不能近，近则痛甚，病势沉重。医皆曰：「邪已入里，无法可治。」又换某时医，于前药中加犀角、羚羊角。谓：「只此扳剂，再不应，即不治。」适其内兄李进之亦予至好，知予素解岐黄，邀予一诊，以决生死。予诊其脉，上脉浮大而空，两尺沉细欲绝。虽气微弱，不欲言语，而心尚明了，并不昏迷。询其：「欲饮否？」曰：「不欲。」询其二便，大便少而稀溏，小便清白，少腹有痛意。予急曰：「此戴阳症也。」此素本阴亏，不能潜阳。今时邪误作伤寒治，温散太过，虚阳上浮。治宜引火归原。医者见其烦躁，不知其为龙雷上升，侵犯清虚之府所致。反以为热邪传里，肆用寒凉，阳即欲回，归路已阻。再用寒药，不独腹痛，自利症必加重，而无根之阳，将一汗而亡。奈何？于是竞用真武汤，劝其速进。病者知用附子，断不肯服。以为我烦热如此，如何还服此热药？伊兄劝以汝服凉药已多，而转火炎于上，兹方称引火归原，或当有效。今已危急，何不试之？劝之再三，勉进半剂。本已十日不寐，进药后，不觉安睡两时许始寤，头皮不痛，面赤全退，腹痛亦止，心中不烦。乃复索药进剂。次日延予复诊，其病若失。细询平日本有上红之恙，生育亦多，其阴本亏，故阴中之阳易动也。改用附子理阴煎，服一剂，又专用理阴煎，服三剂后，以八珍加减调理全愈。半月后展初自吴门归，向予申谢。且言幸伊不在家，其妻得生，否则必死。予问：「何故？」展初曰：「如此热象，群医皆用寒凉，而子独用大热。且子又不悬壶，我岂能相信哉！」予曰：「然则，足下亦不必谢予也。是有命焉，不可强而致也。」", "10387": "田展初居荷花池巷，其比邻颜凤尧先生，丹阳名医，在此悬壶，医辄有效，诚老手也。其田姓之症，亦曾临视，惟为群医所哗，未能独出手眼。嗣闻余治法，深为佩服。适其尊阃亦染时症，先生年将古稀，本有半身不遂之恙，恐诊脉不准，转延医诊。而医者不识其病，先生亦不自解，乃延予诊。时当盛夏，病为时邪，人事昏沉，壮热口渴，渴欲热饮，虽热嫌冷，家人以炭炉面烹百沸汤与服，犹云不热。脉来洪数而滑，惟右寸见沉，实热症也。而见寒象，又非热极似寒，医者之不解在此。予也踌躇莫决，忽尔机来。因问主人：「尊阃有甚旧恙否？」主人曰：「无。」予曰：「非必有大恙，或年高多痰否？」主人曰：「此诚有之，每日约吐三碗许，转觉爽快。」问：「今病几日？」曰：「五日。」「病中吐痰否？」曰：「无。」予曰：「得之矣。」主人问：「何以得之？」予曰：「时邪乃热症，脉亦热症，而寸口独沉者，肺气为痰所遏也。一日吐三碗，五日不吐，积痰当有几许，阻塞肺气，上下不通。内虽甚热，气不得上，口鼻吸入，无非冷气，至喉而止，亦不得下。肺气通于喉，今为痰所阻，故肺以下则甚热，喉以上则甚冷，是非先用吐法，吐去其痰不可。虽然不易言也，沸汤下喉而不热，痰之胶固非常，肺之闭塞已甚。虽用瓜蒂散、栀豉汤等法，恐格之不入，不足以搜肺脏、提肺气，而鼓动其痰。是非仲景麻杏石甘汤不可。」主人曰：「麻黄乃夏令所忌，今值六月盛夏，虽时邪非伤寒，麻黄尚可服乎？」予笑曰：「药不执方，相宜而用，古之训也。今痰阻肺脾，非麻黄之大辛大热，不能搜肺活痰。且是方也，有石膏之寒，以制麻黄之热，有杏仁之降，以济麻黄之升，有甘草之甘，以缓麻黄之急。非同正伤寒之用麻黄汤，专取辛热表散也。」主人曰：「内人已过花甲，设服之而大汗不止，得毋有亡阳之虑乎？」予曰：「药有监制，既已申明。且麻黄肺之药也，下喉必先达肺，肺气开提，痰涎必活，活则涌吐，药随痰去。麻黄之性轻浮，岂能入腹作大汗哉！况时邪亦须汗解，吐中有发散之意。石膏乃白虎汤之主药，《金匮》治中暑之首方，色白入肺，兼清阳明之热，散清并施，邪热从而得解，未可知也。」主人曰：「此药准得吐否？」予曰：「麻黄大力入肺搜痰，痰结既开，势必上涌作吐。」主人曰：「理解明透，更无他疑，竞请立方。」予用麻黄八分、杏仁三钱、石膏五钱、甘草一钱，嘱其即服而去。次日未明即寤，回忆昨日之论，自笑愚忠太过，然细思无误也。清晨不待请，即唤舆往探。见其医室已开，急趋而入，主人出迎，予不及寒温，急问曰：「如何？」主人笑应曰：「其效如神。」予心乃定。细问服药片刻，立即吐痰升许，不过微汗，外感已退，人事全清。予入内复诊，改用犀角地黄汤，一服热减，再服全愈。是症也，非细心切问，安得其门而入哉。夫望而治之谓之神，闻而知之谓之圣，问而知之谓之工，切而知之谓之巧。神圣工巧，谓之四诊。缺一不可，吾见今之粗工，假装时派，每至人家诊病，仅一搭脉，遂即开方。主人欲细告病情，则曰我今日有数十家延请，岂能为一家耽搁。嗟乎！三部九候，全然不知，又不肯问。草菅人命，莫此为甚。虽庸医杀人，不闻偿命。然冥冥之中，罪安可逃哉？予自懔之，兼望医者共懔之。", "10388": "笪豫州患瘅疟，单热不寒，已经两月。从未有汗，每日壮热六时许，形瘦骨立，实已危殆。其堂弟笪东洲予友也。欲延予一诊，以定死期。予诊其六脉弦数，全无和柔之意，而按尚有根。予知其素来好内，肝肾俱亏，加以大热伤阴，阴不化汗，邪无出路。医者不知，所用不过达原饮、清脾饮、小柴胡汤等，如何得汗？予曰：「症虽审而从未服对症药，尚可为也。」乃用景岳归柴饮，柴胡一钱五分、当归一两、甘草一钱，加大生地二两，令浓煎予服，服后进热米汤一碗。不过一帖，大汗而解。", "10389": "大侄小村，小溲不通，已至三日，腹膨急胀，至不能忍。先有京医连进通利，不通愈甚，急觅予诊。予见其肺脉独大而数，知其素来嗜饮。因问：「连日饮何酒？」藤村曰：「近因酒贵，常饮烧酒，三日前有小集，饮烧酒且甚多。」予曰：「是矣。」时端阳节后，急令买大枇杷二斤，恣意啖食。另变补中益气方法，去党参、黄耆、白术、当归，惟用陈皮一钱、甘草梢八分、醋炒柴胡五分、蜜炙升麻三分，而加天冬二钱、麦冬三钱、北沙参三钱，车前草一颗，与服。一时许，小溲大行一大钵而愈。伊急遽中未暇问故，予亦未言。后至松江华亭县，刑席邵瓣莲有沉疴甚奇，每发当腹痛非常，而先必溲闭，百医罔效。必小溲自通，而腹痛乃止。其症少时即有，至四十外乃更甚，适当举发，延予一诊。肺脉独大而数，与藤村侄同，予问：「素嗜饮酒烟否？」曰：「皆有之，而水烟尤朝夕不断。」予曰：「是矣。」以与小村侄方，去升、柴，加黄芩、知母与服。服后小溲大行，腹痛亦止。伊问：「予病如何？何药之灵也。」予曰：「肺为气之主，又为水之上源。《内经》云：『膀胱为州都之官，津液藏焉，气化则能出矣』。有属中气者，中气不足，溲便为之变；有属肾气者，肾与膀胱相表里是也。而其实气化之权，肺实主之，肺在人身主乎天气，天气常清明而下降，肺气清肃而下行，上源行乎所不得不行，下流自有所不得而止。而有所不行者，虚也，热也。虚则气不足以行，热则气反逆而上。肺气不行，则诸气不行。通则不痛，痛则不通。今溲不通而腹乃痛，肺脉独大而数，症经三十年。此先天肺热，后天烟酒积热，日伤肺阴，肺失清肃之令，故病易发而亦渐重也。以后将此方常服，且戒烟酒，可望不发。」瓣莲佩服。请将所论书一通，并药方裱糊收藏。连服二十剂，后果不发。盖尝观群兽焉，有肺者有尿，无肺者无尿，知肺之关乎小溲者多矣。小村侄用升柴升提而邵兄不用升柴加黄芩、知母者，何也？小村曾服利药，愈利愈不通，气行更结，非加升柴以提其气，转不能通。如酒壶然，壶嘴不通，揭其盖自通也。邵兄未服利药，而热久而重，故不用升柴而加黄芩、知母也。虽然，勿谓癃闭之尽在清肺也。吾乡钱光斗之弟妇张氏，产育用力太过，正气大伤，三日小溲不通。予用补中益气汤全方，姜、枣引，加冬葵子三钱，一服而通。写真华秋岩内怀孕六七月，偶因下阶，一跌坐地，腹中坠胀，小溲不通半日。予知胎气震惊压膀胱，亦用大剂补中益气，姜、枣引，一服而通。此皆用温补升提，治在中气而不在肺气也。其冬葵子或用或不用者，一则癃闭三日，以葵子引经通之；一则仅半日许，提其气而溲自行，毋烦通利也。后又有丹徒县署吴晴椒明府所请钱席胡晴麓恙已愈后，大解数日未行，一日登厕数次，力努干结不出。是日晚登净桶约一更许，极力努挣，大便不来，而小便反闭。次日自用车前、泽泻等药通利之，而仍不通，腹加涨（胀）。又数日延予，予曰：「大肠膀胱相隔一间，分道而行，本不相碍，今因直肠涨（胀）满，挤合膀胱，小溲无路可出。此非膀胱自病，虽多方通利，终不得通，徒增涨（胀）满耳。予有一法。」众问：「何法？」予曰：「止有下法耳，下其大便，小溲自通。」时众人皆不以为然，以为小便不通，反通大便，殊难相信。且病者年已六十有四，又值病后，连日怕涨（胀），又不敢多进饮食，如何能受下剂？众口难调，予亦辞去。第三日又来敦请，晴麓本与予金兰契好，万不能辞。至则涨（胀）已至胸，盖又杂进单方，如促织草帽圈之类，有入无出。直至涨（胀）不能动。予曰：「在书大便不通，有四五十日无妨者，而小便不通，五日必死。今已三日，再延二日，神仙不治。此症下或不死，不下必死，奈何？必欲置之死地耶？」予言至此，众不复言。而其如君独奋然曰：「三日以来，愈治愈坏。今日竞请立方，虽死不怨。」予索纸开方，西潞参三钱、于术三钱、当归身三钱、陈皮一钱、炙草一钱、炒柴胡一钱、炙升麻六分、煨姜二片、大枣二（枚），众皆诧异曰：「先生说要用下法，何开此补中益气汤？」予笑曰：「诸公勿急，尚有加味。」爰加生大黄三钱、元明粉三钱。因告众曰：「大便阻塞小便，固非用下不可。然是病有三虚：年高，一虚也；久病，二虚也；不敢纳谷，三虚也。此三虚者，诸公曾言之，予岂不知之。故是症非下不可，而非用补以用下尤不可。古人黄龙汤用参以用下，玉烛散用四物以用下。今用大剂补中益气，然后用硝黄以推荡之。大解行，而膀胱路宽，小便亦自畅行，而正气不陷，相辅之道也。不然，予岂孟浪用下者哉。」其乃爽然，制药与服，一时许，大便畅行，小便随至，源源不绝，几半净桶，腹中畅快，病乃若失。以上五症，皆小便不通。四用东垣补中益气法，而变化不同，法则仿古，用则因心，神而明之，存用其人。", "10390": "吾友赵义之牙痛缠绵，月余不已。忽诣予要方，诊其脉，左关尺数，以六味地黄汤加升麻三分、柴胡五分，与之。曰：「此药服后，未免更痛，然片刻即止矣。」次日，告予曰：「昨服药而卧，忽然痛不可忍，急得骂汝，后竟安寐，天明不知牙痛之安往矣。药既对症，又多此一痛，何也？」予曰：「齿乃骨之余，而肾主骨。足下肾水太亏，肾火上浮而为牙痛，故用六味全剂，补之泻之。然其浮于齿牙之热，不能下降至肾，不若用升柴以透之。升透之时，未免较痛，然所用无几，而补泻之力甚大，阴能潜阳，火不复上作痛，且得安寐也。」义之本通品，闻之拜服。后予以此方治肾虚牙痛者，无不立效，更胜于景岳玉女煎。", "10391": "龚玉屏，予少时第一交好也。其子椿官十六岁，自在杨管店务，当事亦太早，忽受暑而归。发热头胀，倦怠少气，心烦渴饮，天柱倾欹欲倒。予用人参白虎汤，其家以时症用参为疑。予曰：「先天气弱，暑又伤气，脉象数而甚虚，非参不可，且必佳参。汝等不信，多请先生斟酌，当可决疑。」再三谆嘱而去。是时天气炎热，病症甚多，予至晚回家。则其叔坐等已久，予一见即问曰：「尔侄服药如何？」曰：「尚未。」问：「何以不服？」曰：「君教我多请先生斟酌，我连请七人矣。」问：「伊等云何？」曰：「止钱觐杨先生欲改用党参，徐寿东先生以为君当不错，其余皆以为不可用参。内有焦医尤以为不可。曰『时邪用参，如吃红矾，入腹必死。』众言如此，不得不疑。而寒家素服君药，亦有不效，又不敢服他人之药，特再请教。」予曰：「予只道此法平常，医者当无不解。今若此，更何言。但令侄今日不服此药，明日即不救。子速回家制药与服。尚有不测，余当偿命。」送至门，又嘱曰：「予愿偿命，君或不肯，此方人参一钱，银三十两。不测，予定当罚出。君纵不要，听凭散于穷苦，予决不食言。若不服，至不救，其责在子。」次日大早往视，已一药而愈矣。嗟乎！医道之不明竟至于是耶？《经》云：「热伤气，」又云：「壮火食气。」盛夏酷热，烁石流金，未有不伤气分者，故治之必顾气分。孙真人生脉散、东垣清暑益气汤、丹溪十味香薷饮，皆人人共见之方，未有不用参者也。至人参白虎汤，乃《金匮》中暍专主之方。《金匮》乃医圣仲景之书，是不足法，更何法也！且夫椿官之症，乃中暑，非时邪也。时邪者，春当暖反凉，夏当热反寒，秋当凉反暖，冬当寒反温，为四时不正之气。感而病者，谓之时邪。至风寒暑湿燥火，此六气者应时而至。本天地之正气，人或不慎，感之为病，直谓之中寒、中暑而已，不得混谓之时邪也。今椿官当暑中暑，而混指为时邪，病且不知，何竟谤予之用药哉。论椿官之虚弱，清暑益气可用，因其大渴欲饮，恐黄耆、白术过于温补，故用人参白虎。予本细心斟酌，尚几为前辈所误，椿官幸免矣。而当世之冤魂何可胜数哉！喻西昌曰：「医至今日，生民之厄运也。」诚哉！是言也。", "10392": "椿官廿一岁，自常贩布回家，自称有恙，延予诊治。时十二月初一也，其症外似洒淅恶寒，内则烦躁觉热，舌赤无苔，溲黄白浊，脉来洪数无伦，按之空象。谓之曰：「子如回家，一路恐有外感，而内又亏虚，攻补俱有未便，迟数日再诊可也。」因密告其叔曰：「令侄此症真不治矣。奈何？」其叔曰：「伊起居如常，饮食尚好，何至不治？」予曰：「子原难解，俟至春来，予言自验。」后屡请，予坚辞，且遇伊家亲友，遍告以椿官复病，予并未一诊，恐将来受谤也。伊家只得另延他医。初云无妨，继则无效而加重。至次年正月十八日溘然长逝矣。后有他医虚心问故，予曰：「此不难知也。冬见夏脉，书称不治。伊脉洪大无伦，在夏脉尚未太过，而见于冬令闭藏之日，且又无根，肾水告竭，肝火独旺，木生于水，无水之木，何以应春气之发生乎？如树木然，当冬令闭藏，莫能定其生死，至春则生者生，而死者死。人身一小天地，肝木应乎春气，根本既拨，故知其死于春也。」", "10393": "镇江北门蔡姓世出时医，友人戴半山蔡氏婚也。一日诣予曰：「有舍舅病重，请兄一诊。」予以蔡姓多医生辞之。半山曰：「其症诸蔡皆看过，均回不治。惟予叔岳欲以附子肉桂扳之，不能决，请兄一决。」随唤肩舆逼予同往。时病者在半山金珠店管事，故半山可以作主也。至其室，审其症，乃时邪十一日矣。大抵羌、防、柴、桂、枳实、楂炭、厚朴、苍术、草果、炮姜之类。其症则燥热非常，人事昏沉，耳无闻，目无见，舌卷囊缩，死象已具。其脉弦劲疾数，不辨至数，惟按之尚未无根，病中以未大解。诊毕，半山问曰：「桂附可服否？」予曰：「桂附万无服理。」然此药误已深，实属难治。姑请伊母出来商议。其母出见，予问曰：「汝家看此人到底是死是活？」其母曰：「先生何出此言？」予曰：「汝家若以为未死，则予不敢多事，恐药不能救，归过于吾。吾何为来担此恶名哉？若汝家以为必死，则予尚觉有一线生路。」其母曰：「吾家诸医皆已回绝，先生若能施治，生死不忘。」予乃曰：「时邪热症，治以辛凉，非比伤寒之症治以辛温。且伤寒下不厌迟，时邪下不厌早。三五日内热重便闭，即当用下存阴。今时邪误服伤寒药，佐以温燥，意在推滞。不知愈燥愈结，火愈炽而真阴耗矣。真阴根于肝肾，肾开窍于耳，肝开窍于目。肾脉挟舌本，肝脉络阴器，今目瞆耳聋，舌卷囊缩，大热伤阴可知也。症本不治，而予谓有一线生路者，幸脉尚有根。非症重至此，药误实多。为今之计，仍非下之不可。然古人急下存阴，阴未伤也。今下已迟，阴已伤矣。宜用玉烛散法养其阴以用下。于是用生地一两、当归五钱、加大黄三钱、芒硝二钱、甘草一钱，与服。夜下黑粪，次日热退，诸症皆退，仍进养阴清热。又次日往诊，半山出迎曰：「余亲又复发狂，奈何？」予入诊，见其骂詈不避亲疏，果有狂象。予曰：「无妨。」仲景曰，下后发狂，再下则愈，一下未尽故也。仍以前方与服。明日往诊，据其家云：「昨下更多，几半净桶，后继以血。」予疑此方不应动血，及见原方，忽有人添桃仁三钱。予曰：「此无怪乎有血矣。」伤寒有蓄血症，其人如狂，下其血则愈。重则用抵当汤，轻则用桃仁承气汤。今下后发狂，并非如狂，何必用桃仁动其血哉。所幸脉静神安，症已无妨，惟养血药要多服数帖耳。后代立方，总以地黄阿胶为主，幸无复参议者，而其疾乃瘳。", "10394": "包式斋患尿血二年未痊，后觅予诊治而愈。盖肾虚人也，偶然伤风，某医发散太过，转致喘不能卧者累日，急乃延余。余曰：「咳出于肺，喘出于肾。肺肾为子母之脏，过散伤肺，母不能荫子，则子来就母，而咳变为喘，肾虚人往往如此。今已肾气上冲，脉来上部大，下部小，而犹以为风邪未尽。更加发散，无怪乎喘不能卧也。」与以都气全方，加紫衣胡桃肉三钱，纳气归肾，一药而愈。越三年后，又因伤风，某医仍肆发散致喘，不能卧者三日。又请予治，曰：「此与前症无异，彼昏不知，子何毫无记性耶？」曰：「因伊在舍诊病，偶贪顺便，不意至此。」予曰：「无他，仍服前方可也。」其内因夫病著急，忽得笑症，终日哑哑不止，亦求予诊。其左关寸皆数甚，予曰：「膻中为臣使之官，喜乐出焉。此肝火犯心包络也。」与犀角地黄汤加羚羊角，次日复请予至，则笑病一药而痊。而式斋则夜仍喘不得卧，惟下半夜稍平耳。余曰：「异哉，何药之灵于当年，而不灵于此日哉。」细诊脉象，上部大，下部小，实属肾气不纳，毫无他疑。静思良久，因问：「昨何时服药？」曰：「晚饭后。」予曰：「是矣。今可于晚饭前服药，当必有效。」次日问之，则喘气下，一夜安眠矣。伊问：「何故？」曰：「药本纳气归肾，饭后服药，为饭阻不能直达于肾，故上半夜全然不效，下半夜药性渐到，故稍平也。今于饭前服药，腹中空空，药力直达肾经，然后以饭压之，肾气岂有不纳者哉。」嘱其多服数帖，后加十倍为丸，常服。并嘱偶有外感，不可任医发散，其症乃不复发。盖尝览《石室秘录》陈氏假托乩方，直至岐伯、雷公、华佗、仲景，古之圣神，无不毕集，可谓怪诞。至其方药议论，亦甚平平，而大其制，一药必数两，一方必二斤。万难取法，惟其主意先分治法，则群书罕见，可称独得之奇。如教包式斋饭后服药，即内卧治法，是下治法也。是故医书汗牛充栋，而除《内经》、《难经》，仲景《伤寒》、《金匮》二书，无可疵议。其余则各有所偏，亦各有所得。惟在学者自知所取，而勿尚其偏而已。然则不读书固不可，而读书亦岂不贵善读哉。", "10395": "厉登铭五兄，住城内演军巷，予后门外之贤邻，又予之密友也。初秋患疟少汗，予治之。始以和解，继以景岳归柴饮加生地一两，姜皮三分，得透汗而解。知其好内嗜饮，阴虚居多也。疟三次即已，精神亦甚减。是晚城南走火，伊命家人秉烛至大门口观看，忽谓家人曰：「适地坊老爷过去，汝等见否？」是夜遂疯，喊骂大闹，掷毁什物。且持厨刀欲杀其妻，妻躲至床下，伊更跳闹不止。次日大早急请予，予至其室，伊正持破碗欲伤人。见予至，忽然放下，称予曰六哥。予见其有怯意，似予有以镇之者，因更自提精神，正言厉色，谓之曰：「坐下。」伊即坐下，曰：「将脉来诊。」又问：「因何胡闹，欲杀尔妻？」伊则满口秽语，谓妻王氏与狐貍在墙内如何等疯语。予不复闻，惟嘱好好坐著，不许胡闹，否则予将治汝。伊亦应承。予至厅，家人出云又大闹矣。亲朋满座，问予何法。予曰：「诸病从虚而入，邪祟亦以虚而入。厉兄本疟症初愈，疟发于少阳胆经，疟后受伤，其胆必虚，适遇邪祟乘虚入胆而成疯。且厉兄平日之胆最小，一语不敢伤人，琴瑟之好，称为最笃。公忽欲杀人，且为素所爱敬者。疯则胆大，岂非祟据其中而有以使之耶？夫疯字从风，有风象。然疯之或重或轻，犹风之或大或小；疯之忽发忽止，犹风之忽起忽息。邪祟之中人而成疯也，未尝不凭借人身内风之力，而鼓动乎肝。因木生风，因风生火，因火生痰，痰火相搏，势乃大张，而令魂魄神明皆扰乱而不能自守。虽然，今幸邪祟初入，譬如匪人初至旅邸，左邻右舍，并无相识，其势尚孤，驱逐亦易。若夫今不治，盘踞既久，巢穴已固，风鼓其势，火张其威，痰助其力，如恶人居久定而党已成，则驱逐良难也。」于是用温胆汤，京制半夏三钱、化橘红八分、云茯苓三钱、生甘草五分、麸炒枳实七分、鲜竹茹三钱，加粉丹皮二钱、龙胆草一钱，同煎，外加朱砂三分、猪胆汁少许，和服。此方专于泻胆，使邪祟不能宁居。又兼清火化痰，使邪祟无所凭借。法虽平常，竟一药而愈。后以十味温胆，以沙参代人参，以生地代熟地，且重用之。以生地能补胆，贼去关门法也。连进四帖，神志如常。此嘉庆十六年事，时尚未识王九峰先生。后先生闻知，适见脉案，深蒙许可，遂相往来。予视先生为前事师，而先生以予为忘年友矣。", "10396": "吴预生，诸生也。在邹同裕淮北信阳盐店管书启。其店有空房，吴爱其静。一日忽大疯，屡用刀自戕，救之得不死，其店急用人送归。适其家与予相近，令人使来就诊。半晌数人将疯子扶持而来，舞蹈而入。予出，疯子即寂然不动。予如诊厉登铭法，予上座，使之下坐，正容壮色以诊其脉。脉象或大或小，或疏或密，或结或促，知其邪祟无疑。厉声谓之曰：「尔遇我即当去，不去，我将在鬼哭穴灸法针汝。虽然尔来路远，我当嘱伊父多赠汝盘缠。」予说一句，伊应一声，旁观无不称奇。予知其邪祟重而且久，气血暗伤，先以参地两补之。加犀角、羚羊、琥珀、朱砂、龙齿、虎骨、龟板、鹿角，诸多灵通宝贵之药，以通其灵性，以镇其神魂。譬如正人君子，巍然满座，邪人自不能安。此药入腹，邪祟自逼处不安而思去。又仿喻西昌法，用羊肉汤一碗为引，使邪祟借腥膻之气味而出。惟药不与病人知，恐二竖避入膏肓也。又嘱其父曰：「此实鬼祟，信阳来路甚远，务请高僧施食，多烧冥资，以践予多赠盘缠之言。」时四月十九也，二十日伊家旋食服药果愈。", "10397": "常镇道刘，名载，字竹湄，岭南人也。由山东济南府保举赴都，自都赴镇。刘公久病未愈，欲请一儒医诊治。当有王惹山明府保荐徼召，刘公即烦王明府先看，随后差内使持帖延请，予因往诊。询其病源，乃泄泻已四阅月。天未明泻起，至晚不过五六遍。而进京去京一路医治，总无效验。予诊其脉，诸脉皆平，肺脉独大，按之见数。予曰：「此肺移热于大肠，乃热泄也。」公曰：「予一路来往皆值冬寒，屡遇风寒，反致热泻乎？」予曰：「据公言当为寒泻，据脉象实为热泻。右寸属肺，肺与大肠相表里，独见数大，故知其移热作泻也。脉象大于他脉数倍，自诊可知。且公一路所服可系温燥药否？泄泻时可热有声否？」公曰：「皆然。」予曰：「岂有寒泻服温燥而不减者？岂有在腹为寒，泻出转热者？岂有寒泻急迫作声者？《经》曰：『暑注下迫，皆属于热。』岂有止有寒泻而无热泻乎？」公自诊其脉，亦觉肺脉独大，辨论既明，疑团尽释。予乃用天冬三钱、麦冬三钱、孩儿参三钱，以养肺阴。加泻白散、地骨皮二钱、桑白皮一钱、粉甘草五分，以泻肺热。又加茯苓三钱，以为分利，怀山药五钱，以顾脾胃。定方后，公问：「可服几剂？」予曰：「二剂后再诊。」公服一帖，日间泻止，惟余天明一泻，服二帖而天明之泻亦止。第三日因公无暇，未请诊，亦未服药。而次日天明之泻又来，又急请诊，问何以故。予曰：「一百三十日之症，可以一药而止，不能一药除根。再服二帖，病当霍然。虽然，诊公之脉，沉部颇有数象，似乎尚有伏热。泻不难止，恐春气大透，木来生火，变生他症。须预为诊治，不可大意。」公曰：「予急欲赴扬矣，月余乃返。再当请诊可也。」十日即返镇署，且急延予，称有重症。予往视，见其面左部自头至顶，半边全行红肿，左目肿合不能开，上下唇皆厚寸许，心烦意乱，自谓此次定当告病去官。予诊其脉，洪数有力，而无浮象。予慰之曰：「无妨也。此症似乎大头天行，而实非也。此久有郁热，热郁成毒，春透木旺，借肝气发生，热毒上达。肝位于左，气由左而升，故病在左。所喜六脉根本甚固，尚能胜病，月余可愈，无庸告病而去。」于是用东垣普济消毒饮子，而去其升柴。以症无外感，火发于肝，延炽于胃，其势已甚，不敢再为升提也。且加犀角、羚羊角，清肺胃以清肝，恐其上犯咽喉也。大便屡结异常，加调胃承气以下之。十日后，火势渐平，肿亦渐消，知其血热阴伤，加丹皮、生地以凉之。每帖药计四五两，始多苦寒，继加甘凉，而总不用发散。其始尚用桔梗、薄荷二味，取其辛凉疏解，后并此而去之。症虽日减，而刘公见予每曰：「我病莫非有风寒，先生何不散之？」予曰：「无有也，不可散也。」嗣后跟随诸人见余至，即扬言曰：「主人之病，只要发散即愈，惜未发散耳。」予若勿闻也者。惟每至署，见辕外有医轿一顶。密询之，乃李某也。其人虽医生而不务医学，专务结交各衙门号房，巴结家人，希图引荐。今问刘公病，无门可人，访予方药，不用辛散，乃扬言一散即愈。托其家人耸动其上，以图进见。刘公虽未之信，而无免有疑，啧啧者所由来也。至二十日病已痊愈，惟偏左头内，尚觉沉闷。刘公问予叹曰：「症虽承先生治好，但将来未免头风之患耳。」予曰：「何故？」曰：「先生总未代我发散也。」予曰：「诺。今日竟用发散何如？」公辗然色喜。予乃用小发散方，荆防不过数分，尚另加监制，谓之曰：「公恙实不可发散，服必无效，今姑用之，以除公疑。」又另开清凉养阴、镇摄肝风一方与之。曰：「服前方，平平则已。没有不适，再进此药则安。」次日进诊，公曰：「昨日了不得，服药无片时，即觉火势一轰，似觉头面复欲肿大，头晕眼花，急忙伏枕。虽然难过，幸后方亦已煎成，服下始定。看来不能发散，诚如先生之言。然窃闻风善肿，风宜散。又闻有大头瘟症，属乎风火，亦用发散。而予症似之，其风火独不可散何也？」予笑曰：「公之恙非『风火家人』，乃『火风鼎』也。风火者，因风生火，风为本而火为标，泻其火而风自息。试观天地之道，极热生风，得大雨施行，天气清凉，而风亦顿息。俗所谓煞风雨也。今火风之症，若误作风火论治，妄用发散，譬如炉火已旺，而又以大扇搧之，火岂有不更炽者哉。公二十日服寒凉重剂，统计约五六斤，而始进发散小剂，即如此火上头轰。若初起误进发散，将火势焮腾，焦灼肌肉，蔓延咽喉，虽有善者，奈之何哉？若夫大头瘟症，予岂不知。其初起也，恶寒体重，头面俱肿，必兼表象。两目鼻面肿起者，阳明也；耳前后并额角肿起者，少阳也；脑后项下肿起者，太阳也。三阳多表症，故可先加表散。公恙初起，毫未恶寒恶风，面肿于左，肝部也。公岭南人，地气温热，秉赋偏阳，京官十数年，饮食皆用煤火。官山东六年，亦用煤火。火毒积蕴已久，北地风土高寒，积而未发。今至江南水土不同，又值春深肝旺，肝火冲起，久郁之火，上犯阳明，致成此症。故治法只宜消毒泻火，《经》所谓『高者抑之，不可散也。』」公曰：「已病不知，经先生之论，恍然大悟。而今而后，直以性命相托矣。」调理十余日，头之沉闷亦愈。公意深为器重，乃后竟信李某之谗，与予绝迹。未一载，已知李某之诬，复延予，予却之。又二载，刘公卸事住扬，不知得何病症，后亦延予，仍却之，而刘公死矣。此中殆有数焉。", "10398": "宫保陶云汀夫子，于道光五年抚苏。适办海运，夏秋季往来上海，亲至海隅，相度机宜。旋又莅金陵临乡试。是岁阳明燥金司天，少阴君火在泉，秋热更甚于夏热。夫子重受暑热，非止一日。于八月初六日发为时邪，此宜治以辛凉者也。乃医者竟用伤寒辛温发散，且屡用桂枝，邪不能达，其热转加，致成热疟，寒少热多。医者改用柴胡，亦仍加桂，而其佐使者，无非厚朴、苍术、草果、青皮，一派温燥克伐。观察钱益斋夫子素知医道，时为监试，心窃非之。因在常镇道任内，知予善于治疟。回明宫保，专差菲请。十八日晚予到辕门，随即进诊。细询疟在阴分，不过微寒，旋即发热，壮热六时许，解时无汗，热时烦躁，至不能受，渴欲冷饮，饮亦不多，脉则十分弦数，舌则红赤无苔，溲则其赤如血，且不寐者多日矣。予曰：「此大热症。加以燥剂伤阴，阴虚作疟，阴虚不能化邪，无汗故热邪难解，阴虚故神烦不寐，治宜养阴化汗以化邪。」于是即据此立案开方。惟思进见之初，未便骤用大剂，故以小柴胡去参，加大生地五钱、当归二钱、赤芍一钱半、夜交藤三钱。三更后疟势减，进药，竟安眠至天明，可谓小效。次日，本地陈、林二医至，知服予药，密告宫保曰：「大人此症不可服当归，服则热必重出。」又谓予曰：「尊方用何首乌太早。」予曰：「未也。意者谓夜交藤乎？此乃首乌之藤，非首乌也。且此不过取夜交之意，为不寐而设。叶氏治疟亦常用之，以交通阴阳。用药之意，虚实皆宜。非如首乌之力能温补也，君得毋见《本草备要》不列夜交藤，其何首乌注内有曰一名交藤，遂认夜交藤为何首乌乎？」伊掩饰曰：「恐敝地药店止有何首乌，无此药耳。」予曰：「昨药系予亲见，其藤甚佳，君等或未用过耳。」予知道不同不相为谋。伊等亦公然开方，并不让予。惟是日尽去温燥，改用黄连、石膏，而宫保服之，燥热有加无已。盖伊等只知寒凉以治热，不知黄连苦燥仍然伤阴，石膏虽能清热，而不能养阴，虚人服之，转伐胃气。虽《本草备要》之语，伊等未能全览耳。然是时宫保未能信任，总服二人之方。予屡告辞，堂官不肯放行。予曰：「如此治法，必不能愈。设有不测，而余在幕中，将毋留以为二人归过地耶？」堂官转禀方伯张公，张公进见宫保，病固沉重，出见二医语言荒谬，遂往告唐陶山方伯，盖陶山方伯乃宫保之同乡，兼戚谊，而精通医理者也。廿二日早陶山方伯来，细切脉理，遍阅诸方，出与二医及予相见。先问二医曰：「先生们看大人究系何症？」陈医俯首无言。林医曰：「是疟疾。」方伯曰：「疟疾吾岂不知，但是何疟疾？」林医不能对。方伯转而问予，予对曰：「据愚见乃阴虚作疟耳。」方伯曰：「诚然，此当用四物汤合小柴胡加减，去川芎、重用生地。何方药并不及此？」林医曰：「服此即能愈否？」方伯曰：「汝等治已半月有余，愈治愈坏。吾仅一言即当全愈耶？虽然，如果重用养阴，症当大减，愈亦无难。譬如无气亢热已极，不得一场大雨，何以回凉。但可下雨而不可下冰雹，冰雹亦能伤人，如黄连、石膏，冰雹是也。」林医语塞。予问曰：「养阴必兼归地？或谓当归助热，不可用奈何？」方伯曰：「何来此不通之论也？阅诸方，前所服者一派温燥，不知助热，而当归反助热耶？当归虽微温而养阴，设使方中早能助以当归，当不至阴伤热重至此。且夫生地阴中之阴，当归阴中之阳，阴阳相辅，动静相生，用药之道也，何可偏废？此不过以生地为君，当归为佐耳。」言毕，扶杖而入。二医赧颜而去。方伯复出，谓予曰：「脉案方药皆极通，惟尚轻耳。吾已与大人说明，以后惟子是任，子好为之。」予以医多论杂为虑。方伯曰：「我自当之，我当间日一至，以辟群疑。」是日，予用大生地二两、当归三钱、柴胡一钱五分、黄芩一钱、赤芍二钱、赤苓三钱、甘草五分、合皮一钱，服后疟来不过两时许，即大汗热清，较前减四个时辰。热时亦觉能受，后总本此法为加减。阴亏太甚，生地减至一两即不复减，疟势渐轻。至月底疟作不及一时，陶山方伯果常来，予嗣闻方伯九月初三回楚，恐又为他医所误。回明公保，请九峰先生坐镇。先生九月初一日到，诊后亦谓养阴为是，仍命立方，稍为参酌，至初七日全愈。由此受公保知，遂相契合。究之此方亦不过本景岳归柴意变化而出，治愈数十百人。陶山方伯议论高超，予常志之不敢忘。", "10399": "道光五年八月廿三日，予因宫保初服予方，已有大效，予心亦定。是日午后，因往城北张佑溪协台处诊病，往来遥远，至起更方到察院，到则巡捕堂官群相问曰：「先生来何迟？日间监试钱道台有条子来请先生，进贡院代内帘刘奉贤县隔帘诊脉，因先生不在，辞去。傍晚又具禀刘令病已垂危，求大人格外施恩，让刘公出场就死，大人勉准，适已出场，大人意欲请先生去一诊，或尚有救，连问数次矣。」予问：「究竟何如？」众曰：「适伊家人亦来求请，据云仅一丝游气，半日不知人事矣。」予至上房，宫保曰：「先生来耶，我今日甚好，惟有内帘刘令亦于初六日得病，今已垂危。因先生高明，或能起死回生，亦大阴德。且吾亦同病相怜之意也。」对曰：「闻其病实已不治，治之何益？徒损贱名。」宫保曰：「此等病治之不效，岂能归过于先生。惟念此人乃吾所取帘官房首，其文甚佳，功夫尚在其房中，当可多几本好卷子，不意如此，然其文不似要死者。」因命人将其文与予看，题乃「举贤才，曰焉知贤才而举之」。予看毕，曰：「此文果不似要死者。」宫保问：「何以见得？」对曰：「其文清华，其气通畅，似有福泽之文，而又无发泄太尽之弊。且其书法端楷，到底不懈，未曾错落。其精神必素能完足，故论文字皆不当死。」宫保曰：「所论甚是，看文章面上，请去一看何如？」对曰：「诺。」时将二更，且大雨，予乘舆冒雨至承恩寺，曲折达僧舍。见旁空房一间，床架一张，堆草荐数条。床上靠一人，即刘公也。油灯一盏，灯火如豆，阴冷之气逼人。呼其仆秉烛至，见其大汗如雨，面白如纸，二目直视，牙关紧闭，喉中痰涌，口角流涎，全不知人事矣。使仆探其下体，则囊缩遗尿。予曰：「此死在顷刻，尚何治为？」即欲辞去。伊等坚阻不放，且有跪者。予忽转念，此文不死，何其人之多死象耶？问：「闱中服药否？」曰：「天天服药。」「方在否？」曰：「全在。」予索方细看，无非发散温燥，而热总不解。至十九日一方，麻黄一钱五分、羌活二钱、甘草五分、桂枝二钱。予想时邪十四日，忽服此方，其人即当死，何尚能活至今日，莫非与我意有医缘否乎？于是始为诊脉，细细推敲。脉来数大而空，俱欲离根，惟左尺尚有一线可按而得。予暗叹其真读书人，惟知用功，不贪色欲，根本素能保守，虽经群药刀斫斧削，而命根犹有存焉。于是用犀角地黄汤，通心达肾，养阴化热。镑犀角三钱、大生地一两、大白芍三钱、粉丹皮三钱。又思所服温燥一派伤阴，脉来甚数，阴不潜阳，当于养阴之中加介以潜阳法。非若大汗亡阳，脉仅空大，当以参附回阳也。于是加左牡蛎一两、元武版五钱、外加橘红一钱、竹沥五钱、姜汁少许，以达其痰。谓其家人曰：「既然服药，以速为贵，迟则不及。牙关紧闭，以乌梅擦之必开。惟咽喉痰涌，药恐难下。此药得一半下腹，即有转机，恐全不下而死，勿谤予也。」回时已近三更，宫保犹等信未眠，真菩萨心肠也。细询一切，色然喜曰：「如此尽心，或当有效。」明早伊家人来告曰：「主人已转过来矣。」予往问：「如何服药？」曰：「前三分皆不受，后得一匙下喉七分，皆顺流而下。」予见人事渐清，向予点头，但语言蹇滞耳。连进原方二剂，痰降能言，惟虽不大汗，而总未全止，知其表虚也。于主方外，另仿玉屏风法，用黄耆皮五钱、防风一钱、五味子七分，一服而汗全止。嗣后方去犀角，加大麦冬三钱、高丽参一钱，减竹沥二钱，约十剂。改用黑归脾调理而痊。盖盗汗心液也，补心则汗止。", "10400": "张伟堂二兄，吾乡南张榜眼公嫡派。先居城南塞上，太夫人患疟，服凉药太多，病剧。其戚严嘉桢素信予，荐诊。知其本体虚寒，始以温解，继以温补而愈。嗣迁居扬州，十余载不相往来。道光五年十二月十九日，忽接严嘉兄信，据云伟堂病已垂危，诸医朝至以为暮必死，暮至以为朝必死。惟病者忽忆当日母病，系兄挽救，思得一诊，虽死瞑目，务恳屈降，死生均感等语。因其言直谅不欺，二十日渡江，下昼到张府。即上楼诊视，见其痰涌气急，坐伏茶几，一人两手扶其头，不能俯仰，十余日不得一卧矣。人事昏沉，不能言语，诊其脉滑数而大，虽已空象，而尺部尚觉有根。遍阅诸方，自八月服起，皆作外感治，尽用发散消导。月余后，想觉人虚，易而为补，总以人参为主。后想因痰多气阻，又改用化痰顺气。又或疑外感，加用疏解。现在诸医皆云不治，无药可用。惟一朱医与伟堂至好，一日数至，以二陈汤作丸与服。见症愈坏，束手流泪而已。予乃曰：「此肾气上冲症也。诸气以下行为顺，今肺不清降，肾反上冲，气降则痰降，气升则痰升，故痰涌气急不能俯仰。且其脉象甚数，似杂湿热，阴虚湿热不化，亦随肾气而上冲。若能纳气归肾，气降痰降，湿热亦降，可以安卧，可以调理，症虽重，无妨也。」于是用六味为君，以都气法原本六味，而六味地黄古称为治痰圣药，且称为下焦湿热之圣药，有三善焉，而皆合乎此症，故特用之。大熟地八钱、山萸肉四钱、怀山药四钱、粉丹皮三钱、福泽泻三钱、云苓三钱，外加北沙参四钱、杏仁泥三钱，以润肺降气；胡桃肉三钱，以助纳气；福橘皮一钱，取其顺气而不燥。开方后，予往候九峰先生，因即止宿。次日复请，予至。讵料其尚未服药，问：「因何不服？」曰：「朱医坚称熟地不可服故耳。」又请上楼诊脉，太夫人曰：「昨方因有熟地不敢服，今恳另订良方。」予曰：「熟地乃此症要药，吾方君药，舍此更有何法？且闻所请先生不少，朝称夕死，夕称朝死，无药可治。今服熟地不合，亦不过死。况予尚许君家不死耶，此症服熟地则生，不服则死。服与不服，悉听君家，予无他方。」下楼予即欲行。严嘉兄曰：「今已将午，不及到镇，此地有好浴堂，陪兄一浴何如？」予曰：「甚好。」正欲偕行，忽一人出，告曰：「老爷过去矣。」嘉兄彷徨欲上，予笑曰：「予诊脉未久，岂有死在顷刻而不知者耶？此不过痰厥，片时即苏。其尺部根本尚在，保无虑也。」特拉嘉翁出浴。浴罢而归，曰醒久矣。至是伊家因予言有准，方肯服药，而尚止服一半，并能仰矣。迁延太甚，已二鼓后，复请予看诊。脉亦渐平，伟堂并能说话。谓予曰：「药真如神，但尚不能平卧，君能令我一卧，则快甚矣。」予曰：「惜君家不肯早服予药耳，昨肯服药，今日安眠矣。虽然，明日保君安睡无虑也。」次日依方再进，傍晚服药，旋即能卧，卧则熟寐，三更始寤。以后听予用药，而予总本初方略为加减，地黄则始终未解分毫。八剂后，其症大全（痊），予乃辞归。次年复请诊理，煎方膏方悉本原方。盖伟堂素嗜虾油，每食不撤，其湿热甚重。因热生痰，因痰致咳。取用辛散，既诛伐无过，取用人参，亦助热锢痰。因咳致喘，肾气上冲，犹以二陈丸治痰，岂不去题千里乎。惟六味地黄，三补可保肾气，三泻兼治湿热，于伟堂最宜，况痰之本在肾，肾安痰亦自灭也。", "10401": "李青原兄，病伤寒，头痛，项强背板，一身尽痛，甚恶寒而不甚发热，自服发散药无汗。予诊之，见其脉浮而弦甚，知其素来阴虚，不能作汗，以九味羌活汤去生地、黄芩，加当归八钱，一服得透汗而解。方本景岳归柴饮，景岳专用柴胡只治少阳症，不能治太阳症，特变而通之。陶节庵九味羌活汤，治江南伤寒最好，江南无正伤寒，不能用麻黄也。或议其黄芩生地，不应见面用凉，然已见口渴欲饮，用之有效。否则不妨易之。予自治李青原后，每遇伤寒夹阴虚者，即以节庵景岳法参用，去芩地加当归，少则五钱，多至一两，无不得汗而解。三载以来，取效不下数十人。然则斯方亦殆可传也。凡发散药太阳经居多，阳明胃经则白芷、葛根、升麻三味，少阳胆经则柴胡一味。仲景小柴胡汤为少阳症而设也，疟症不离乎少阳，今人用小柴胡汤治疟症，未尝不可。乃景岳五柴胡饮及正柴胡饮，皆用柴胡治太阳伤寒，恐不能散邪，而反引入少阳也。至叶天士治疟症，则又戒用柴胡，更不可解。今吴人患疟，不敢少用柴胡，以致缠绵日久，甚有死者，皆其遗祸也。景岳名医，叶天士医中翘楚，一则重柴胡如此，一则弃柴胡如彼，岂非偏之为害哉。", "10402": "予三十岁时，馆于京口旌营呼协领家。呼公六旬外，忽得类中症，眩晕非常，头不能抬，夜不能卧，面色浮红。适万廉山先生宰丹徒，荐其乡亲唐朗山先生诊治，朗山以为虚阳上浮，以真武汤坐镇北方，用附子至三钱，合家疑惧不敢服。朗山力主之，惟予赞之，一服而定，调理煎方百余帖，总用附子五钱，丸药亦重用附子，统计服附子十余斤。精神加旺后不服药，寿至七十七岁。江西宜服附子，而能用之于江南，朗山先生真大手笔也。一时称奇，予亦心服。十余年后，李进之兄油行徽伙余姓，年卅岁，六月出门讨账，抱恙而回。医者以为受暑，投以清凉，忽变周身寒冷，热饮嫌凉，诊其脉沉细如无，知其体本阳衰，虽当夏令仍属感凉，以桂附理中汤。用附子一钱如弗服也，加至三钱，身寒稍减，而热饮仍凉，直加至五钱，乃日见有效，计服附子二斤许，症乃痊愈。盖其家婺源皆服山涧之水，其性极寒。生斯地者，体多偏寒，以寒体受寒凉服寒药，故一寒至此。医贵审时兼宜度地，非易易也。然予之所以敢用重剂者，由先得叨朗山先生之教也。", "10403": "大凡脉沉多寒症，而亦有不尽然者。嘉庆十八年，予往常州。有朱某者小贩人也，忽得奇疾，周身畏寒，医投以温剂不应，因投以热剂如桂附之类，而其寒愈甚。爰求予，诊其脉皆沉，按之至骨，略见疾数，知其为同气相求症也，以犀角地黄汤与之。朱本贱业，以得予至为幸，见方即服，一服而寒减，三服而全愈。此等症确身寒，脉沉，未有不用热药者。不知其伏热在至深之地，一遇热药相引而入，并人身之卫阳亦随之而入，故外反憎寒也。幸朱服热剂不多，否则难挽救矣。", "10404": "李楚生三兄，患目，二目皆病，左目尤甚，红痛异常，瞑不能开，勉强开之，盲无所见。头痛难忍，亦左为尤甚，可怪哉。大渴欲饮，每日饮浓茶十大碗。蔡医以白虎汤投之。石膏每剂一两许，愈服愈渴，数剂后浓茶加至三十大碗。饮食不思，神烦不寐，终日终夜饮茶而已。两月有余，困顿已甚，乃延诊。脉皆弦数而大，而右关数疾之中尤见和柔。予笑曰：「此非白虎汤症也。白虎汤乃伤寒时邪，胃有实热，大渴欲冷饮症所用。今因患目而渴欲热饮，不饮冷饮，乃素嗜浓茶，克伐胃气，胃液干枯，求饮滋润。而其实润之者乃更伤之，故愈饮愈渴。彼石膏辈能治实热，而不能治虚热。《本经》载虚人禁用，恐伐胃气。彼庸庸者不知，以为渴饮则当用石膏，而不知外感内伤有天渊之别，热饮冷饮有毫厘千里之分。率意妄投，不独损人之目，即损人之命不难也。」其仲兄问曰：「闻目属肝，何患目而胃病如此？」予笑曰：「肝开窍于目，夫人而知之，乙癸同源，肝亏则肾亏，亦夫人而知之，不知五脏六腑十二经脉三百六十五络其血气皆禀受于脾土，上贯于目而为明，故脾虚则五脏之精气皆失所使，不能归明于目矣。然脾与胃相表里，而为胃行精（津）液。胃主降，脾主升，胃降然后脾升，饮食入胃，游溢精气，下（上）输于脾，然后脾气散精而上输于肺也。今胃汁干枯，胃气不降，脾有何精（津）液可升，尚能归明于目哉？况病者肝肾本亏，肾不养肝，肝虚生热，热盛生风，以久虚之胃，木火恋之，故不独热难堪，饮不解渴。且胃无和气，直致饮食不思，胃不和则卧不安，故夜不能寐也。至目痛自属肝火，头痛自属肝风。而今欲治之必先救胃，救胃必先戒茶，然后大养胃阴，并养肝肾。胃喜清和，得滋润而气自能降；木虑枯燥，得涵濡而火自能平。火平则风息，眼无火不病，头无风不疼，如此调治，症虽险无虑也。」病者虑茶不能戒。予曰：「非戒饮也，特戒茶耳。」于是以菊花、桑叶代茶，而先投以养胃阴扶胃气重剂。十日后即不思饮茶，然后兼调肝胃，并或清肺以滋生水之源，或清心以泻肝家之热，千方百计乃得渐痊。二年后其尊人亦得目病，蔡医以为能治，不必延予，而一目瞽矣。", "10405": "京口协领柏邃庵，方正人也。从无淫邪，奈廿余岁初次进京，未知检点，竟不知于何处旅店蒙其不洁。头生颗粒，有似广疮，急延外科医治，想用捺药随即痊好，而年余后下疳，外科调治久而不愈。予劝以仙遗粮下五宝丹，由渐而愈。邃庵最畏服药，愈后未经清理，后乃发为阴癣，腰以下腹以上蔓延无隙，其痒异常。然三十二年以来竟无他患。不意于道光十一年，忽有教以医癣者用紫荆皮为末，以白芨磨汁调敷。予闻之再三劝以勿治，盖疥癣之疾，不足忧也，设使治愈必生他患。奈邃庵竟为所惑，不纳予言。日以二药裱敷下体，自秋徂冬，癣竟全收，不复作痒，欣然得意。十一月望后，忽患耳痛，就予诊脉。其时适值云汀宫保忽患吐红，专札见招。是日诊脉后即束装赴省。予谓儿辈曰：「邃庵脉象大为不好，恐有重症，而予适不在家，奈何？」赴省一月，忽接家信，据云邃庵病势沉重，有朝不保暮之象，请予速回。余不胜骇然，幸宫保恙已全愈，随即买舟南下，一日达镇，即诣柏府看视。见其耳连项肿，稠脓淋漓，臭不可近，人则一丝游气，盖已米饮不下者九日矣。见予至，亦不能多言，惟曰：「君虽来，吾亦不吃药也。」询之伊子。据云：一月之中所请内外科服药不少，大抵清凉居多，以致胃败，故邃庵誓不服药矣。予因转为邃庵曰：「兄之病源，惟予深知，他人不及知也。不知者认为寻常之火毒必用凉药，须知此症不但不可用凉，且宜用温。兄如服弟药，三剂必然有效。如不效，再不服药，何如？」邃庵闻以温易凉，不觉首肯。予乃以归脾汤加减，另以五宝加西牛黄与服。三剂后臭味顿减，口味大开，精神渐振。邃庵问予：「何药之神也？」予笑曰：「兄之病根在三十年前，他医不及知，即兄亦念不及此也。兄当年曾沾染恶气，误服捺药，变为下疳。愈后未经清理渐化为阴癣，此癣为余气之出路，且周身之湿热皆以此出，原万无治理者也。奈兄误听人言忽然欲治，居然治愈。而究之风湿热毒从何而去，不觉上攻清窍。又值现与统军不合，告老罢官。虽素阔达，究非得已，心怀未免不畅。心寄窍于耳，故病发于耳也。医者不知，肆用寒凉，使热毒欲发不发，遏成臭气，异乎寻常。人之脾胃喜香而恶臭，此等恶臭积于胃中，胃气焉得不败，尚冀饮食之甘乎。且夫治余气之法以升透为主，尤以扶正气为主。盖余气即邪气也，正气衰则邪气陷而入内，正气旺则邪气托而达外。常见庸庸者，治湿毒之症专主苦寒，攻下百无一愈，诚昧于医理也。兄之症情节遇多，医更难明，动辄得咎。予用归脾汤法可以养心，可以健脾，可以扶肾，可以开郁，可以建中，可以托邪。而又用加味五宝丹诸多宝贵败毒搜毒，专使外达，不容内蕴，用药得当，似乎通神。虽然，现幸获效，仍须癣发，方许收功也。」数日后癣渐作痒，十余日后癣遍下体，而耳患全愈，饮食倍常。始终总此一方并未改易方。余自省回见其光景，亦疑不可救，而竟获速效。此其中殆有天焉，非人力所能致也。", "10406": "李曜西，吾长子之襟兄也。其子于初秋患疟，医者为徐医，延至八月中忽请予诊。据云疟本寒少热多，多汗而热难退。徐医连投白虎汤，石膏每用一两，热较减而寒较多。现则寒后不能转热，有气自少腹上冲，疼痛异常至不能受，然后渐渐转热，痛随热减，热壮而后痛止，胸次饱闷，饮食不进，神情疲败。徐医屡用顺气止痛等法，全然不应，故请斟酌。余问：「何以用白虎汤？」据云：因病者热多渴饮。予问：「渴饮几何？」曰：「热时约饮廿次，每次一茶碗盖。」予笑曰：「次数虽多，茶碗盖贮茶无几，虽廿次不足两碗，不算大渴。」再问病人欲冷饮热饮，则专用热饮。予曰：「据此则大错矣。书载白虎汤症必大渴欲冷饮而后可投。足见虽渴欲饮而不欲冷服，尚不可投也。况并非大渴，且欲热饮乎。且夫治疟之法必寒能化热而后可愈，岂有寒本少而欲其寒多者乎。夫白虎汤在疟门未尝不用，然必热疟而后可。今症汗多热难解，明系暑疟，暑中兼湿故也。暑乃阴邪，热乃阳邪，岂可徒见其热，遂以阴邪而用阳邪之药耶？此必误用白虎致寒转增而将暑邪逼入肝肾，以致肝气夹肾气上冲也。」曜西问：「疟乃少阳症，何以转入肝肾？」予曰：「五脏皆令人疟而不离乎少阳胆经，胆在肝叶之下，肝胆相为表里，胆经邪热为寒所逼不得外达，则内传于肝，乙癸同源则又内传于肾。予向诊令郎脉象，肝肾本亏，所谓诸病以虚而入也。当其疟来，寒固因寒药而加甚矣。至热邪为所遏，欲达不达，转将肝肾之气逼令上冲，以致疼痛异常，神昏气逆，久之而热渐透，疼亦渐止。久之又久，而热大透，疼乃全止，邪气透而肝肾之气乃宁也。至始尚能食，今则全不能食，皆因石膏诛伐无过，大伤胃阳之故。」曜西闻予议论，以为透辟，遂请入诊，诊得脉来沉象，按之弦数，左关（肝）尺（肾）尤为不静，右关（胃）沉而不数，按之无力。予闩：「症本暑疟，无服热药之理，奈遇服寒凉，邪陷肝肾，非附子理阴煎不可，虽然其法过火，诸公未免疑虑，权以当归建中改生姜为煨姜投之，以观进退。」一剂后痛较减而热较平，渐欲饮食。二剂后痛又减而热又易，然肾气仍冲而疟不能止。予竟用附子理阴煎，曜西尚在游移。予告之曰：「桂枝，附子之先声也；煨姜，炮姜之先声也；归芍，熟地之先声也。建中既已有效，又何疑焉，建中虽能温中，不能纳肾气补肾阴以托邪也。今用附子理阴，以熟地一两纳气归肾兼以平肝，即以托邪，加以附子五分、炮姜五分，温中散寒，领邪外透，当归三钱和阴化疟，斯方也，疟可以已。奈何不用而任疟之缠绵耶？」再三开导而后肯用。如方一服，不独肝肾安宁而疟竟止矣。知者无不以为神奇，适云汀宫保招赴清江，未能一手调理。半月后，予自清回，复请往诊，盖其疟已反，他医不敢用原方，虽轻不愈。予仍以原方投之，一剂而愈。愈后连服七剂，疟不复发而饮食香甜，精神如旧。古人称有是病即有是药，不我欺也。庸庸不知，伐人性命，如同儿戏，可不痛恨哉。", "10407": "吴泽之，吾婿也。甲午岁，馆于孩溪，夏秋之交，天时盛暑，致患暑疟。地无医者，唤舆来城，至晚到家。似无重恙，乃上灯时忽然昏厥，手足搐抽，不知人事，惟时作笑，旋又身热如炭，烦躁非常。其时城门已闭，余不及知，天明得信，随即往看。亲家慌忙，病者情形实已危急，诊其脉象洪数之中更兼躁急。夜间曾有刘医来诊，以为中暑。余曰：「非也，此中热也。此热中厥阴也。热中足厥阴肝经故抽搐，热中手厥阴心包故善笑。中暑之脉数而兼濡，暑乃阴邪也。中热之脉数而兼洪，热乃阳邪也。此又兼躁急乃素本阴亏又中阳邪，有孤阳无阴之虑。虽然，勿谓全未中暑也，其作疟也，其中暑也。因患疟而来城，由孩溪至城，几四十里四野中又无避处，以中暑之虚体，长行于炎热如焚之中，有不中热者乎？故此乃先中暑而后又中热也。为今之计且治中热，幸未服错药，似尚可救。」以大剂犀角地黄汤加羚羊片三钱，犀角入心包以清热，羚羊入肝经以治热，生地辈则养阴清热以化亢阳，外加竹茹、竹叶、西瓜翠衣凉心清热化痰以为佐。一服后人事渐醒，不复笑而抽搐仍然，尚神烦谵语，浑身不著一丝。三服后始知著裤，热退神宁，伊长兄以为全愈。予曰：「未也。中热虽解，中暑尚未全解，暑疟尚不得免耳。」后果复行作疟，其脉弦数之中总兼躁象，汗出不已。余知阴虚之故，于小柴胡汤多加生地辈甘凉养阴之品，真阴难成而易亏，又系胎疟，不能骤止，十数帖后始能霍然。至次年乙未，馆于东马头，夏间又患暑疟，张医投以清脾饮，更觉烦热异常，急急回家就医，予仍投以隔岁原方，二剂而愈。", "10408": "杭州进士吴晴椒宰丹徒。其夫人忽得异疾，每于梳头后胸乳间发紫斑，心中难过之至，约一二时许斑消心定，十余日不愈，乃请予诊。予问「何不早梳头？」曰：「早梳亦然。」「何不迟梳头？」曰：「迟梳亦然，曾迟至申酉梳之，亦无不然，第惟不梳头耳。」诊其脉皆沉象，两关按之则左弦数而左滑数。予曰：「此脾气也，而兼乎肝。左沉弦而数者，肝气郁而肝阴亏也。右沉滑而数者，脾气郁而湿热不宣也。夫脾主健运，肝主调达，今皆以郁，故土受木制，湿热亦郁于脾而不化。脾主四肢，梳头则两手皆举而脾气上升，湿热随之而升，故心胃之部外则发斑，内则难过。梳头之手下垂而脾气亦下，湿热仍归于脾不复上扰，故病象暂退而根未拔也。所幸湿热不重，只须和其肝脾，开其郁结，透其湿热，病自退矣。」予进以补阴益气煎，以熟地平肝，以山药健脾，以柴胡疏肝，以升麻苏脾，以陈皮、甘草、当归调和其中，一服而愈。再进二服以善其后，永不发矣。", "10409": "谢蕉石先生，江西人，原任开归道，现扬州安定书院掌教。其小胆怯多疑，适虞运司有七情郁结之病而爱吃热药，扬州医郑姓尽以桂、附投之，镇江府学司训陈君更加石硫黄丸，以致脏腑烧烂，大便下血如烂鱼肠，犹不肯稍服养阴而死。蕉石先生素所交好。因此伤怀转生疑惧，忽然间日不寐，不寐之日固属难过，而昼亦各病业生，如头晕、头痛、腰疼、腿疼、心跳、肉𥆧，腹胀、腹痛等症，或来或去，变幻无常，惟得寐之日较为安静。扬医无能治之者，先生更加惶惧。延一张医留住斋中，日夜医治，毫无效验，而病象更多，精神日减。隔江延予，即予初亦不解，不过育心宁神等药，亦无甚效。三日后予细想病情，审视脉象，不觉恍然大悟。盖其脉象三日以来大小疏数不能一致，有似邪脉，而察其神情并无外来邪祟，必三尸为之也。盖尝考之三尸，或称三彭，上尸彭琚（倨）住坭丸宫，中尸彭质住膻中，下尸彭矫住脐下丹田。三尸喜人为恶，不喜人为善，修炼家必斩三尸而后得道。然能斩之者何人？修炼反成疯魔，皆三尸为之也。至于人之运用总在一心，夜寐则神静心庄，何反多梦，亦三尸为之也。人有隐瞒之事，不肯告人，而梦中反自说出者，三尸喜揭人之恶也。夫心为君主之官，胆为中正之官，如果心正胆壮，三尸亦可安静。若心虚胆怯，疑惧环生，则三尸从中侮弄，病情愈出而愈奇，俗所谓疑心生暗鬼者实常有之。不必外来之鬼，大约即三尸耳。三尸谓之虫，又谓之神极，其灵异虽守庚申者不能斩也。今蕉石先生心胆本虚，又生疑惧，故三尸得间而作祟，此非治三虫不可。但用药不与病人知，病人知之则三尸虫拒之，二竖之伎俩可畏也。于是与四少君细剖其理，嘱以开方勿与尊人看阅，症始可治。少君有难色，谓：「家君不独阅方，且时对《本草》，焉肯不看方药。」予思方不与阅不可，药全与知亦不可。好在先生十分信予，当可进言，因于进诊时谓之曰：「大人此症调治良难，然能不究方药，则予煎方外予有丸方，可保一服即效。若大人必知何药，则药必不灵，予技已穷，只好告辞。」先生因予言激烈只得答应。予因另开丸方，皆杀三尸虫之药，加以宝贵镇邪宁心之品。是晚正值不寐之期，以二煎汤药下丸药三钱，居然一夜安眠。从此以后无夜不寐，精神如旧，二十日来并无反复，予即告辞归里。先生欲早晚得一人看脉才可安心，并愿送银一两，在此过夜。问予当请何人。予对曰：「府上本有张先生在此，何不仍请伊来，好在无须伊另用药也。」于是将张医请来。予告之曰：「大人此症甚奇，幸予猜著，特荐先生来此，万勿更方。先生住此，大人全愈，即先生看好，亦可得名，不与先生争功也。」伊似甚佩，再三问予究系何症，丸方何药。予如不告恐其多心，因大略告之曰：「此因疑生虫，不过用杀虫之品加朱砂、琥珀以宁心育神耳。但治法药不与病人知，本勿说破。」次日予即辞归。乃七八日又专差过江说病已反，逼予到扬。予至谢府先晤四少君，问病何故忽反。少君曰：「此张先生之害也。家君本时访丸方为何药？总对以冠仙先生不知在何处合来，实在不知。乃张先生来，家君再三盘问，伊即言略知一二，大抵朱砂、琥珀之类。家君即将予唤进，大声呼斥。谓予明知不言，朱砂如何吃得。从此以后不吃丸药，仍间日不寐，诸病业生。」张先生无法可施，只得又来奉请。予闻之亦著急之至，进见蕉石即恳予曰：「先生救我。」予曰：「予前本救大人病已愈，廿日予始辞归。予本嘱大人不问药始有效，奈大人多疑必访何药，张医不知医理告知大人，因此不服丸药，除此之外更有何法耶？」大人曰：「吾今再吃丸药何如？」予曰：「再吃亦断无效也。」是夜正当不寐，大人嘱煎药人加丸药三钱，在内临卧服之，依然不寐。次日难过异常，吃饭时忽请予进内。谓予曰：「先生看我何如？」时二月初，春寒不减，大人重裘，皆大毛也。乃忽皆脱去，止穿丝绵小袄，而大汗如雨将小袄湿透，胸膛坦开，热气腾腾。据云近日每饭必然大汗，今日仅吃饭一口而汗即如此，直截不能吃饭，奈何？先生务要救我。予想三尸虫因知昨晚药内有制它之药，故更幻出此象也。予因此转得灵机，因慰之曰：「不必过急，容予思之。」盖汗虽心之液，而饮食多出于胃。蕉石性多偏好，其饮食非极热者不吃，其胃本有积热，三尸故得借此作祟，今借治胃热暗加一治三尸之药，假设其词，使病人知其药而不知其用，三尸虽灵同二竖，亦不知所邂也。少间谓之曰：「大小不寐之症尚可缓治，而此大汗倒甚可畏，急须挽救，不然恐汗脱也。」伊本心虚胆怯，闻此急求治汗。予曰：「大人果然欲命，从此饮食不可过热，而胃中积热，热已多必须重用芦根，带凉带通，汗可渐少。但芦根必须常服，而其性过凉，恐服之又生泄泻，须更得一药可制芦根不至泄泻，如二术健脾而未免过燥，与芦根一合。再四思维止有黄精一味脾肾两补，可与芦根合用，不改其清凉之性，而又可不至泄泻也。」蕉石即要《本草》来看，予即将《本草》赞黄精功用处指点与看。而内有杀三尸虫一语，伊本不留意，而予不等看完即令拿去。伊怕出汗即令速买二味，芦根二两、黄精三钱，当晚与服。是晚吃饭亦即无汗，是日本当寐之期，夜固安静。明日当不寐之期，仍服二味，汗既不出，夜得安眠。从此煎方以二味为引，夜夜安眠，诸病皆无。予屡告归，伊家款留不放，一月后始得旋里。四少君问予前方何以不用黄精。予告之曰：「此用药之道也。此等怪症实不经见，予精思而得之。所用丸药十数味，多方以治之，以为当可有效，尚留一二以为后图，设使竟用完之后，被张医说破，岂不束手无策耶。」此道光十六年事也。越十五年咸丰元年，又有戴六兄之症。", "10410": "戴六兄，字槐卿。素亦心虚胆怯，偶住场下空房独宿，颇生疑惧。忽觉背心微寒，渐觉周身怯寒，因而睡去，似入黑暗地狱中，绳捆索绑，难过异常，欲喊不能出声，欲动如石压住，恶境多端不能细述。必待有人来带推带喊得以醒来，如出苦海，次日另移卧地而恶梦依然。从此神情恍惚，饮食不甘，睡则恶梦难受，或炎热时盖薄被犹嫌凉，或夜回凉不盖被犹兼热，或夜间大笑，或白日大笑，不笑时问之彼并不知。由场下回扬觅一汪医诊视，与以归脾汤，宜乎合式，乃二三剂后觉心忽然落下，自觉有声。以此五日不寐，全非归脾汤之过，只得过江觅医。先就蒋医某诊，蒋以为阳虚用桂附等药，正值长夏炎热非常，伊不敢服，转就予诊。予诊其脉大小疏数不一，知是三尸虫，因疑惧而生祟，与蕉石先生同因。告之此症非寒非热，奇幻百出，医家鲜能知之者。兄既遇我，可保必愈，但必不看药方，如看药方，予断不治。伊素知予，深信不疑，予见面即以补胆养心药中加以黄精，嘱临卧服，即得安眠不做恶梦。然其所现之症大有祟气，恐其所住空房本有阴邪之气，以致三尸借此作威。又另加丸方用黄精为君，佐以犀角、羚羊、龙骨、龙齿、鹿霜、虎骨、龟板、雷丸、朱砂、琥珀诸多宝贵灵通之品，壮心胆而通灵明，制伏三尸。又加箭羽、桃奴兼制邪魅之气，又嘱用上等朱砂大块包藏发内。廿日来，不独恶梦永绝而诸恙全无。固由予看出睡梦颠倒皆三尸为之理。亦由书称药有不与病人知者，真不我欺也。《内经》诊梦甚详，亦各有因，如阴甚则梦大水，阳盛则梦大火，上盛则梦飞，下盛则梦堕，甚饥则梦取，甚饱则梦与，皆有至理。夫人寐则心如死矣，神尽藏矣。梦又谁为之主，非三尸为之，而谁为之哉？予殆亦开千古不传之秘也欤！", "10411": "西门外打索街，邹宅有寡居八房次子吐红，请某医诊治不愈，转请王九峰先生诊视。一次亦未见效，转嘱请予。予见其子年将二十，生而肥白，病虽久并不消瘦，吐红不多已止。惟食入必吐，多日不纳谷食，神情疲惫，脉来不甚细数，而大小疏数不一。予细询其家曾有此症而死者否，则其父死于瘵，长子亦然，今及次子。本在中堂开方，即病者所住房外，其家房屋甚多，予拉某医及其陪医者另至一厅，去病者住房甚远。因告之曰：「此非寻常性症，乃传尸症也，此症内有劳虫，历代相传由长及幼可以灭门。其虫之灵甚于二竖，男子由肾传心，心传肝,肝传脾。至传脾则修炼已成，其先尚容人进食，彼亦资其精气，至修炼成则不容人进食矣，今食入必吐，无法可治，奈何？」某医问古人岂无治法否？予曰：「治法虽有，大概无效，惟仲景先师有獭肝丸一方最妙。予曾治过一泰州人，果然有效，系加獭肝于都六味中，三料而愈，共用好獭肝三个。然其病未久，虫尚未成，故可得效。后遇此症甚多，虫或将成，或已成，虽有獭肝亦不能治，今症已传脾不可为也。且獭肝一月生一叶，必至腊月十二叶变化始全，功用乃大。现在初秋其肝不过七叶，以变化未全之獭肝，治修炼已成之痨虫，有何益乎？论此症本无治法，果能纳谷不吐尚有生机。今再四思维，止有鳗鱼汤一法。予见《东医宝鉴》载人家染传尸痨相继死者不一而足，后传一女，虑其复传，竞将此女抛入水中，渔人网得，见其尚生。适值鳗鱼旺产，船上以鳗代饭。即以汤饮之，其女渐苏，后日以鳗首为食，其女获生，即为渔家妇。《本草》亦有载鳗鱼能杀痨虫者。今若觅鳗首一条煎汤与吃，但不可说是鳗鱼，只说是脚鱼汤用以滋阴，或可不吐。但得一日不吐，即日日以此汤饮之，连粥食亦可不吐矣。以此调理可望杀虫活命。俟至冬间再觅全獭肝合丸与服，可以除根。但制虫之品万不可与病人知，即传尸二字亦不可与病人说，二竖子之利害真可怕也。故今与诸君说话必远隔病者卧房，稍走风声，仙丹无用矣。」其家依言，觅有小鳗一条，煎汤作脚鱼汤进，居然不吐。另有煎方亦不吐，明日如法亦不吐，且能进粥。十数日来药食与鳗鱼汤杂进，全然不吐，纳谷渐多，居然望好。予适欲赴苏，特嘱其及某医药方不过敷衍，病人全靠鳗鱼，但不可与病人知一言，须牢牢切记，不可视为闲话也。予赴苏一月，中秋始回至家，则邹姓日日著人请予。至其家则吐病已反几十日矣，问何以故？则九峰先生到镇，某医欲恭维先生，逼伊家请诊，伊家不得已，听其代请。九峰到房中诊视后至中堂坐下，与卧房仅隔一板。而先生年老恍惚，忽大声曰：「此传尸症也。有虫为患，必得大鳗鱼一条，用老僧尿壶同陈仓米煨烂，合捣为丸，服尽则其病可愈，但不可与病人知。」九峰本重听耳聋之人，言语声高，病人朗朗听见。九峰去后，伊家如法合药，急与病者服，到口即吐。再以鳗鱼汤与服，亦到口即吐，病者亦知非甲鱼矣。伊家尚向予求救，予实无法只得告辞。后闻诸医杂进，日见其坏，即于八月内死矣。病者尚有一弟，予嘱其速速过江躲避，不可见兄之面，盖尸虫之传人往往即在人死之时也。今闻其弟尚未接此症，可谓幸矣。予思鳗鱼竟能治痨虫，只要于未成势时尚少知觉，未具神通，日食鳗鱼竟可治之，保人性命。所望人家有此害者早为防备耳。", "10412": "张瑞郊大兄，予世交也。忽得鼻渊症，伊家常延徐医，因请调治两月有余，浊涕鼻秽不减，更增鼻塞不通，头昏而痛。徐医自称所用之药皆古人鼻渊治法，查书可证，奈此症难治耳。张大兄不得已来就予诊。情形恍惚，予诊毕云：「症非难治，但治不得法耳。」初诊立方服药三帖鼻涕大减，鼻全不塞，头不昏痛。再诊原方加减令服七帖竟痊愈矣。照方令加二十倍熬膏常服以杜后患。有伊友问予曰：「他人医两月余无效而加病，君一见以为无难，一二诊而果然全愈，何其神也。」予笑应之曰：「此非足下所知也，行医必知古方，不知古方有合用者，有不合用者，全在医有灵机，可泥古欤？况鼻渊古方全不合用。予向遇浒关适有总办张姓正患鼻渊，诸医不效，乃延予诊治。予阅所服之方，无非泥古法者。盖古方治此症大抵用辛夷、苍耳辈通脑之药，殊不思《内经》云『胆移热于脑则辛頞鼻渊。』今不知热之来路，惟用辛热之药上通于脑，脑愈热而鼻涕愈多，日久脑虚头昏头痛所由来也，治不得效，甚有谓之脑寒者。《经》明云胆移热于脑，何得谓之寒？夫鼻渊由脑热而来，脑热由胆热所致，只须凉胆使无热可移于脑。脑虽有余热，自由浊涕而去，何愁病之不愈哉！」予竟将此理开于脉案，方用犀角地黄汤，以羚羊易犀角清补肝胆。盖胆在肝短叶之下，相为表里，清胆必先清肝，甲乙皆得所养则不生火而热自清。再合温胆汤，重用竹茹兼清肺胃以化痰，药煎成后入猪胆汁少许以为引，一药得效，数服全愈。今治张先生之病，予若不思而得者，盖有成竹在胸也。其友闻之称拜服而去。", "10413": "一女，年十二岁，日晡发热，多盗汗，达旦则止，日渐黄瘦，饮食减少，四肢无力。医以为童痨，辞不治。脉之寸关弦紧，余曰：此风寒客于肌肤，故蒸蒸发热，既久津液渐亏，当从内伤治而散其表邪。若用地骨皮、花粉、知母等药，是犹抱薪救火，何益于事？遂先以藿叶、生黄耆、怀山药、生谷芽、砂仁、谷神曲与之，盗汗渐止，复以六味加柴耆甘草饮与之，二剂而瘳。", "10414": "六味合生脉黄耆饮方治验案", "10415": "一室女，于午后虚火上炎，而面不赤，自汗如雨，手足厥逆，日四五发，脉之右寸浮而不敛，左脉涩；此阳虚阴亏之症，法当大补，与以六味合生脉黄耆饮，六剂而愈。", "10416": "一妇，傍晚即发热，止在腹以下，手心亦热，腹以上则与平人无异，脉右关微紧，左细而涩。此本营分数亏，兼之少阳之气又下陷于肝肾，郁者当达，非升不可，用薛氏法而少变也，制为六味智荷饮加姜枣煎，四剂而瘥。", "10417": "侄梦麟，甫五岁，染时疾，发痧毒，面上生赤疮，疮俱烂，服清火解毒药不下数十剂，方盈卷矣，而疾犹未已。一日忽目上视，脉之左弦数，右弦而豁然空，现慢脾风证，法当用参附，即命合千金散。千金散者，玉峰朱又渠所赠方也，方乃古法加减，可以备急。药未成而面色已转青，痰涎如潮涌，危在倾刻，延医诊视，俱谢不治，而药犹拟羚羊角等味，谓其痧后余毒未尽，故见症如此。余兄意其必不起也，预为置后事而悉听余治之。命以千金散灌下，痰愈甚，已而稍苏；又命灌之，势稍定。五更后忽发烦躁，声响而直目左右视，舌弄而不能收，扬手掷足，一如阳证，明日更剧，此虚阳外越，非重用温补则脱矣。与以六君子加姜附汤，傍晚腹泻，即以前法加重参、附，佐以丹皮、竹沥与之。明日唇燥烈，小便赤厚而浊如黄土色，举家怪之。余曰：无足异也，此心移热于小肠耳。命以茯苓、竹叶煎汤代茶，而仍用前方稍减附子与之，明日神气稍静，方见虚象，而昨宵竟不得寐；魂不归肝，当为敛之，于前方中加当归、枣仁、丹皮、竹沥，一剂而得睡，再剂而苏。", "10418": "一女，年九岁，于七月中发热不止，后则牙关紧，目上视，诸医或以为暑风，或以为惊风，愈治愈剧。余按其脉，实而有力；欲验其舌，舌缩不能出，撬其齿视之，上半截不可见，下半截舌心黄厚而边独红，挟口环唇皆见青色。夫牙关、颊车为手足阳明交会之地，今症如此，热邪已聚胃，不下不生，庸医犹妄引经论以暑风、惊风治，此真刻舟求剑，焉得不杀人。余遂以凉膈散去芒硝，加石膏，用生大黄同捣，加水研浆冲服。夜未半即大下，明日牙关宽，复以白虎合天水散汗之，遂热退身凉。明日视之，尚未能言，舌黄未净，再以小承气加青黛、石菖蒲、石膏，去其未净之邪；而其父母则谓其女已大虚，恐不可再下，遂不服。复延他医诊视，见余方咋舌，但言好大胆。服其药，腹中觉痛，后竟不可忍，旦夕叫号，渠告急于余。余恶其昧也，不往。后复托人来言，彼固自知其昧也，已大悔也。余笑曰：彼畏其虚，少用一帖硝、黄，谁知却是增病，若必欲余往，仍不变前日方也。渠许诺，遂与以小承气一剂而腹痛如失。", "10419": "冯静生久疟后，只寒不热，腹中作泻，不思食，耳聋，咽肿，脉沉细。一医以薄荷、牛蒡、山豆根等药与之。余谓之曰：此少阳之邪未尽，虚火上炎所致，非服姜、附不可，否则必毙矣。渠不信，服其药而弥甚。余曰：子咽痛红肿，喜寒畏热，固无足怪，请先为子治耳聋如何？渠许诺，因与六味加柴胡梢、甘草梢二剂，而耳已聪，咽痛稍可，后与以八味加麦冬，补中益气去甘草，加智、附、神曲二剂，而饮食倍进，腹泻亦止。后十余日，复往来寒热，盗汗如雨，胸膈痞闷，作泻并不能食。脉之，则以食复而又感于寒，始用桂枝汤加柴、耆、智、皮、芩、曲，而寒热悉退，继以补中益气合桂枝汤，去草加附、曲，而痞闷顿开。忽复咽痛红肿，此郁阳暴伸，阴亏所致，命以六味加甘、桔、连翘，多服数剂，闻五日内瘳矣。此症在前宜用辛温，在后宜用滋润，苟一错误，祸如反掌，医之所以难也，可不慎欤。", "10420": "江生仁源，馆于吴氏。其徒疟愈后复发，间日往来寒热，七日不更衣，仁源同其乃翁来邀余。余询其病势，则曰：医言此证极虚，汗下即恐脱矣，惟当专事补耳。愈后当酬吾三十金，否则不能医也。昨已服人参一剂，而势转剧，奈何？余曰：此非疫疟即常疟，药且不必服，俟明日诊后方定。翁急欲同往，余曰：无恐，此固缓症耳。明日诊视，舌苔微白，面色带青，脉之右关稍弦紧，此少阳兼太阳症而偶伤于食，法当和解。书桂枝汤去甘草，加参、茯、归、皮、益智、谷芽、姜、枣煎，并命服药后饮热稀粥，温覆以取微汗。翁见方即大骇曰：昨服人参一钱，寒热不止，汗且出，两医来皆言汗非所宜，当倍用人参以敛汗，遂加至二钱，今参止写五分，反用桂枝以解表，恐有虚虚之祸。余曰：吾岂不知人参为截疟之圣药，彼特未审其所因耳。今病之发也，由于风伤卫，疟邪之未尽者，遂来并合；桂枝者，太阳之专药，用以解肌，而假芍药以为监制，并佐以辛温之品，使之通营卫，调其阴阳，而少阳之邪不烦治而自解。此正如假途灭虢，因利乘便，可无亡矢遗镞之费，而又何汗之足虑乎。如余方服之，一剂瘥。", "10421": "王纶音忽得怪症，笑时即泪出，必大恸而后快，诸医不识。余脉之，左寸实。问其口苦乎？应曰：然。以生草、连翘壳、二茯、大枣与之，一剂而心中豁然开爽，病去八九，明日复诊，加小麦、萱花，命其多服数剂。人讶其愈之甚速，有问于余者，余曰：此手厥阴心包络之疾也。经云：心主舌，其在天为热，在地为火，在声为笑，在变动为忧。又云：膻中者，臣使之官，喜乐出焉。夫少阴、厥阴，体用虽分，而其象则皆应喜出，悲愁既久，所司亦失其职，火性上炎，变且百出，故其哭者，积忧之所发也。经亦云：肺在声为哭，在志为忧，忧伤肺，喜胜忧。今无喜之可胜，而忧之象适应肺，宜其号泣而不能自禁也。且夫笑者，心之本体；哭者，心之变象；泪者，肝之见端。彼以忧易喜，是犹将牿亡之性也。而清夜平旦之时，萌糵犹存，故先有笑，以呈其未亡之性，而即继之以哭，犹之乎牿之反复，其天真随现随隐，不能自持。此犹幸病之方发，其根未深。迨相寻既久，其先哭而后号咷者，将止见号咷而并无所谓笑者矣。至于泪随笑出，是心、肝二部之火所致，盖心忧则肝气必郁，以类相感，金从火化，故肺叶遂举而上溢为泪。且心与肝，实子母也，子病则母亦病，相因之理，势所必至。昔仲景治妇人脏躁症、用甘麦大枣汤，余师其意，一剂而愈，亦其常耳，而又何异乎。", "10422": "乙丑十一日，李八患赤痢腹痛，后纯下血水，或带紫，日夜十余行，畏寒，手足厥逆，脉之，右关沉细而无力。余谓之曰：汝症极险，所喜者从未服药，若使庸医治，鲜有不用芩、连矣，汝何得生乎？即为疏一方：以红曲、煨木香、炮姜、陈皮、茯苓、泽泻、谷芽与之，痢较前略减，而腹以下有气往来，并见其形，因用戊己汤（川连、茱萸、白芍）加红曲、骨脂、茴香、茯苓、谷芽治之，而痢竟止。乃即以前方加肉果，令其调理，自谓可无费经营矣，而渠一剂后果安适不可言，大便已易红为黄，至二剂则痢仍来，复诣余诊。余思前方已为辛温之剂，而终不止者，肠胃大伤之故；遂用伏龙肝为君温土脏，佐以炮姜，加炒枯砂糖去其瘀积之未行者，命浓煎代茶，日四五服，明日竟止，命再服。更为制理中加减煎方，自是遂不相复闻，后知其霍然久矣。经云：必先岁气，毋伐天和。今时届仲冬，火土退位，况太阴司天，寒水在泉，苟泥于热之一说，竟用寒凉以伐胃气，则祸不旋踵，医之难也如此。", "10423": "蠡市金姓，业农者也，患齿衄，四肢无力，饮食日减，业几废。诣余诊，按其脉，右三部俱洪，知其阳明经气独盛，于是用大剂六味加骨碎补、麦冬、川斛与之，三剂竟止。令常服除根，即将前方改作丸方。", "10424": "程亦曾乃郎，初患疳症，右目失明，以致脾胃虚弱，后忽染时疫，昼夜发热，经十四日不解，大便不通者七日。延余诊，余曰：正虚邪实，非下不生，下则恐脱，即不脱，胃气亦难复初，疳发于肝，失其滋养，木已槁矣，法庚日死。亦曾促余定方，余姑为背水阵，以求出死入生。因用人参四分、盐水炒，金汁小半杯，羚羊角一钱五分，滑石二钱，生草四分，瓜蒌霜钱半，玄精石一钱，肆中不备，以寒水石代之，加竹沥、竹叶使服之，即大下，得燥屎五、六枚，并有胶黏如漆者，胃气终不复，热终不解。乃知平日本善啖，凡所嗜食皆难化之物，乃翁弗禁也。以故脾胃大伤，兼之畏医如虎，视药如鸩，服一剂后，竟不肯再服，后渐不食，如期而殒。丙寅四月初九甲戌日诊，十五日庚辰日故。（此胃络脉绝也。）", "10425": "宋母患肝厥，延余诊。余始用煎剂治之，后定调理方，用六味全料，参用韩氏异类有情丸、加龙齿、牡蛎、龟板、阿胶、虎头骨，并为书案曰：头痛颈脉动，肝阳上冒至巅为厥，贼邪传子，舌生芒刺，脉之左寸关沉弦而横，水亏营弱，龙雷并发，非可以苦寒直折，宜以滋为伏，壮阴和阳。客有不达制方之意问于余者，余曰：六味丸乙癸同治之法也，然草根树皮，岂若异类有情之品其相入为尤速，夫天下之至变者，莫如龙，吾用龙齿先入肝以安其魂，从其类也，阿胶其佐也；牡蛎、龟板，一则顽钝无知，一则资性灵异，其质皆厚重，使就其窟穴而招之，导龙入海，即渐化其飞扬跋扈之性，虎为西方之兽，可以平木，用头骨者，取其象也。制即为生，引即为伏，龙蛰而不见，利其普哉。《经》曰：亢则害，承乃制，明乎此义，可以论方矣。", "10426": "沈佐周室，胸膈痞闷，心中时痛，夜不得寐，且神思不慧，饮食寒暖，几不自知，又不能食，食则䐜胀，群医投以补心安神之剂，皆不效。余按其脉，右寸忽起忽伏，即知其切脉时，气之升降有顺有逆，为肝叶抵胃所致，询之果然；左寸涩而郁，涩为血少，血不荣肝，则火上炎冲膈，天君亦为之震荡；郁为气结，气结则不宣畅，木下行克土，脾轮亦因之不运。治先宜安顿膈下，而膈上诸病可不治而愈，此导河自积石法也。因用白芍、炙草、茯神、神曲、香附、沉香和其肝脾，调其逆气。数剂而瘥。", "10427": "昔张子和论治目疾之法，凡暴赤肿者，有出血最急之语，故用针刺神庭、上星、囟会、前顶、百会五穴。考之于经，五穴俱督脉所至，神庭直鼻入发际五分，督、足太阳、阳明三脉之会，禁针，针则发狂、丧明，而子和独用针法以建奇功，术亦神矣。其次则用吐下二法，亦无不效。千载而下，读子和书者，固无其人，即读之岂能深信不惑，而能见之行事乎。余于针法，未曾深究，曾治一婢，却以下而见其愈之神速者，益信子和之不欺我也。婢瑶琴目赤肿痛，余治之，许以十日愈，始用导赤散加天冬、山栀、黄连、丹皮、连翘、灯心为引，一剂痛止。继用凉膈加黄连、竹叶、甘菊，大下六七行，目开赤退，两剂而病如失，未及四日而愈。", "10428": "尊证已食如饥，耳中作金鼓声，即烦重苦晕，日数十发，脉右尺弱，两关皆弦，络脉空虚，贼风数至，阳邪乘阳，重门洞开，将成风痱矣。治不出峻补命门四字，而按症施治，却有次第，不可紊乱。夫厥阴风木与少阳相火同居，火发必风生，风生必挟木势以侮脾土，理宜食减，而反已食如饥者，虚风入胃，适为胃阳增其火矣，此去病成为消中不远。昔嘉言曾有胃风汤一法，却未可遽施。胆藏肝短叶间，其脉上抵头角，下耳后，其支者，从耳后入耳中，出走耳前，至目锐眦后。肝脉循喉咙之后，上入颡，连目系，上出额，与督脉会于巅。二经本相连，故见症如此，是《经》所谓诸风掉弦，皆属于肝，而耳中虚鸣，又不可专责之肾也。然乙癸同治，必补肾以滋肝，则八味丸加沉香，在所必服；而斩关直入，摄纳虚阳，无如用真武汤加沉香、川石斛，降龙伏虎，在此一举，君其勉之。如余言服数剂遂愈。", "10429": "《易》曰：大哉乾元，万物资始，至哉坤元，万物资生。人身小天地，其藏象悉皆应之，故肺主气，其象如天，天道下济而光明，其在经曰：肺朝百脉，输精于皮毛。脾为孤藏，灌溉四旁，其象应地，地道卑而上行，其在经曰：脾气散精，上归于肺，通调水道，下输膀胱。若使土不生金，则肺气先绝，其见于外者，毛发憔悴，形容枯槁，咳嗽气促不能言，诸病丛生，变症蜂起，其祸可胜言哉。余深悯之，因构思一方，培补后天，以滋化源，名之曰四五培元粉。取地四生金，天五生土之义。其中药品之多少，分两之轻重，颇费斟酌，自谓得资生丸之遗意。方中用百合为君，山药为臣，是子母相生法；以莲肉、薏米、芡实、粳米，糯米为佐，饭滞、谷芽、神曲、砂仁为使，是补消兼行法。不温不燥，养胃生肺，升降之道通，地天之泰合，卫生之法，无逾于此。其或有未尽善者，更愿后人裁之。", "10430": "血症胃脉鼓指，右胁痛，此肝叶抵胃，势必妨于食，急宜乘其胃气未散，常服人乳、牛乳，以滋肝阴；并服此丸以使脾精四布，胶痰渐化，所全实多。其胃口素弱者，固未可一概治，宜加减焉。", "10431": "坎卦阳陷阴中，水中有火之象，水腾而上升，则为精为液，火之蒸动，而关门利也。水聚而上泛，则为痰、为饮，火无以熏灼而关门阻也。其注于下，则为白浊梦遗；移于膀胱，则为淋闭消渴；壅于内，则为水肿胀满。病因虽不同，而无火者居其大半，则补火为最急。然左右两尺，水火平分，真阳真阴，互为根柢，法当两建，以培本原，此补天丸之所以作也。方中熟地、天冬，金水相生，辅以龟板而冲任理；补骨脂、胡桃肉木火同气，佐以鹿角而督脉通；用二黄大建脾胃之阳，以补金之母；不用术者，恐伤肾也。余随方立法，妙合阴阳，虚弱者如能久服，填精益髓，却病延年，捷于影响。", "10432": "江女因失窃被惊，旋染时疫，医用发散、寒凉之剂，痞闷气逆，自汗，嗌干转甚。景贤延余诊，时乙丑八月初旬也。询其卧床自四月始矣，按脉左寸搏指，右关微实，此因少阴之火不降，故上焦之气壅；阳明之路塞，故太阴之化滞。以惊得之，还以惊治。初方用葳蕤、石莲肉、乌梅、陈皮、龙齿、茯神、谷芽、神曲与之，气稍顺，诸症仍不减；乃用附子理中加减出入，继服八味汤，共三十余剂。当其时口中干燥，几无点津，不更衣者十余日，服桂附后始津回肠润，因为定八味丸加麦冬，辰砂为衣，调理之后，饮食渐加，但卧而不能坐，坐即胸中甚闷；余静思其故，病在膻中，乃授以小丸二，细嚼之徐徐咽下，留恋于胸膈间，以察其动静。服十余日，胸前连两胁下甚痛，手不可近，脉之左寸结，余喜曰：得之矣。因书归身、赤芍、桂枝、桃仁四味与之，服二剂，下瘀血颇多，痛遂止，闷稍缓，然犹未尽除也。忽于丙寅六月中，又染时疫，舌苔黄黑，发热不止，病益剧，复延余诊。当是时，举家虎率以听，而凡余用药制方，如大将之旗鼓，进退从之，势不得不一力担当，以扫除贼寇。但吴俗扭于故习，视硝黄如砒毒，禁药者已数十年；今已经年卧床，奄奄一息之弱质，岂足以当此，使余力持是说，即素倾心相信者，闻之必惊且骇；依违不断，迁延日久，血与邪相搏，胃津告竭，惟有束手待毙，重云见𬀪无望矣。余既持脉，见右手关实，尺长，因与其兄信源密议，戒勿泄。三下，舌黑渐退，下后必休养，以鼓动其胃气，故一日休养，一日疏导，最后用生地汁、阿胶、瓜蒌实、芒硝等药以微利之，药不得下行，遂上涌连呕十余次，吐出胶痰无算，举家惊惶，余谓惊则痰积包络，非吐不能出，此亦去闷之一助也，可无恐。吐后果能食粥，两日后又不能食，热亦不止，此宿垢未清也。以虚体不可再下，晨用六味去萸、加葳蕤以养其阴，晚服资生丸以和其胃，半月后始能食粥。后命以六味，八味丸兼料服，午后仍服资生，饮食遂日进，痞闷渐开。余迩来临证，惟此为劲敌，其决策用余方以底于成者，则其兄信源之力也。信源，邑庠生，馆于城外，往来奔走，不避寒暑，真孝友士也。", "10433": "附：第一煎方经水适来脉微结", "10434": "丁卯二月，复延余诊，按其脉迟而少胃气，忽断忽续。余讶其何以至是，询之，则曰：一日只饮米汤两杯，已三月矣。余谓信源曰：此非参不可。信源贫士也，勇于为义，为其妹久病弗痊，又濒危，引为己任。余因命朝服理中汤加桂。夜服四神丸，四剂而能食粥，继用十全大补汤二十余剂而痊。", "10435": "顾宝善常患胁痛，痛则连少腹，后身热发黄则渐愈。脉之右关尺滑弦，此脾邪传子也；而其所以发黄病之故，则甚微妙。因论之曰：君之肾脏本寒，龙雷不安其位，故肝挟肾邪，往往乘衅而欲动，适寒邪偶中太阳寒水之经，内外合邪，水遂聚而上泛，惟肝为肾子，盗其母气，直冲两胁，土本足以制水，乃土衰木克，又被水气所乘，酿酝薰蒸，遂至发黄，是发黄固阳明湿热之征，实即太阳之出路，所以得此为愈期也。今试与子观天地之化，天地之化，不过阴阳二气而已，发育在春夏，保合在秋冬，此是老生常谈，人所共晓之论，合之于人身，则昧之者多。欲求治病，其可得乎？惊蛰后阳气毕宣，水泉寒，龙雷出，以龙雷属阳，恶阴寒之气，乘阳之动而俱升也。霜降后，阳气退藏，水泉温，龙雷伏，以龙雷恶阴，随温和之气而俱藏也。故春夏不见阴，非无阴，阴在地中。秋冬不见阳，非无阳，阳在地中。两气循环，相为起伏，往来屈伸，以成一岁。试使当藏伏之时，郁蒸异常，必有疾雷暴雨，此即上冲两胁之征也。地气上蒸，云雾四塞而础润，此即发黄之一征也。读坎卦一阳在二阴之中，阳陷而险，水中有火，宜顺导不宜直折，此中有元机也。子，肾脏无火，故土衰而水寡于畏，为今之计，先治太阳，后温补肝肾，斯二火自戢，病根永除矣。", "10436": "张妪病疟，发热口干，胸中甚热，按其心下至腹中则频蹙，且便血不止，肛门甚痛，脉之右滞而缓，左关微弦。此怒动肝火，阴络内伤，兼之中焦挟食所致。因书柴胡、淡芩、炒楂肉、木香、陈皮、炒黑柿饼、生白蜜与之。薄暮服药，至夜半诸病悉退，明日起于床，食粥如平人。越三日，其家复走告曰：近复变一症，面左半忽浮肿，左胁连上痛，心中震荡，即觉头重眩晕。予往诊，肝部按之搏指，知其必因暴怒，肝火上冲，询之果然。与以逍遥散去术，加薄荷、勾勾、生谷芽、沉香，亦一剂愈。", "10437": "《经》曰：一阴一阳结，谓之喉痹。一阴，肝与心主也。一阳，胆与三焦也。其脉并终于喉，火性急速，直犯清道，闭而不通，死不旋踵。近来乡村天行痧毒，互相传染，束手待毙，不知凡几，予深痛焉。因深思治法，大旨总在膈上著意，或以祛邪，或以凉肺，或以救败，攻补并施，温凉并用，法不胶一，中病而止。姑书治法数条，以备采择。昔明·楼全善治喉痹，有用姜汁一法，其意盖谓：寒闭为外，热郁为内也。予因悟辛开苦泄是大纲，凡为寒邪所郁，发毒痧喉痹者，即用此法从治，随手立愈。方意即从东垣普济消毒饮、吴又可达原饮化出，因名之曰：达原普济饮。", "10438": "热渴大汗，脉洪数有力，加味白虎汤主之。", "10439": "湖州书客方姓，目赤如鸠，梦泄不禁，夜不敢寐，足冷如冰，脉之左关沉细而紧。叶天士曾以异类有情丸治之不效，后用桂附亦不效。余知其病在厥阴，用鱼胶八两，菟丝子五两，茯苓三两，石莲四两，沙苑子四两，益智二两，归身三两、醋炒，枸杞四两、用青盐、小茴香、酒醋各制一次，鹿角胶三两糊丸。服后病势即减。", "10440": "姜义源胃脘痛，脾泄，梦遗，右脉弦紧，法当温中固肾，书丸方与之。于术、土炒二两，制附子一两二钱，干姜五钱，神曲半两，姜汁熟地四两，加益智四钱，龙骨、茯苓各二两，枸杞小茴拌炒，菟丝子酒炒，沙苑子、石莲各三两。蜜丸，服后诸症悉愈。", "10441": "沈生患奇疾，胸中常闷，饮食少进，已数月矣。诣余诊，脉则右关弦滑而紧。余曰：此胸中阳气不舒，阴邪微结，即仲圣所云胸痹也，法当通阳。授以瓜蒌薤白白酒汤加半夏。五剂瘳。", "10442": "宋天芬夫人素患癖，后忽有气从少腹上冲至心下，或从少腹之右起，痛不可忍，稍有惊恐即上升，一日数发。余诊其脉：心小而胆伏，气逆里急，冲脉为病，其为冲疝无疑；但所异者，稍有所闻即攻触作痛，心脉又如此，若徒治足经，不从手经著意，总难洞中要害，焉能除却病根。因构一方，统二厥阴而兼治之。枣仁、茯神、茯苓、白芍、炙草、小茴、橘核。二剂愈。", "10443": "冯大文素善咳，且病噎已半年矣，一日因冢孙暴亡，郁甚、病益剧，水浆下咽即吐，且艰涩异常，腹中微痛，大便秘结，如是者数日，延余诊。脉之，少和润之致。予曰：肠胃津液干枯，遂致传道下秘，浊气上升，呕逆亦势所必至。为今之计，非大养营血不可。为定煎方治之。", "10444": "又奇脉不司统摄，脾虚泄泻，气逆不得卧。议从中治，兼理奇经。", "10445": "又身热下痢，干呕而渴，胸中痞闷，诊脉不浮不沉而数，此风温症而邪有乘虚陷入之象，深为可虑。议从阳明升举，拟仲圣葛根汤之例，不必袭其方，此许学士法也。", "10446": "又脉象虚数，风阳频动，不食而眩晕，肝犯脾及胃，中无砥柱矣。议用四君子汤加入镇摄之品，以防其厥逆。", "10447": "李某脉滑多痰，痰即湿邪之出路，宣通湿郁，即不成痹。", "10448": "又：赵树诚：仲景《伤寒论》谓寒邪初犯太阳，见脉浮头项痛恶寒之证，传至阳明，则太阳证罢，而变胃家实，身热汗自出，不恶寒反恶热之证。各经见证，界划昭然。所谓伤寒多有变证也。惟少阴伏温则不然，《经》云：冬伤于寒，春必病温。又云：至春发为温病，至夏变为热病。其邪受于冬、藏于肾，至春夏阳气上升而始发，其郁伏有数月之久，而未发之前，初不转称于他经。不若伤寒之感而即发，发即传变也。此所谓温热虽久，在一经不移也。其发也，或由三阳，或由三阴，本无一定，但病虽由六经而外达，而少阴之伏邪，尚未能一律清透，则虽屡清屡泄，苔退舌淡，神清风平，乃逾一二日，而伏邪又炽，舌复干绛，苔复黄燥，痉蒙复作者，亦往往有之。盖至既发之后，其变证虽多，其原仍不离乎少阴也。此亦可谓虽久不移也。彼笠山、虚谷辈，妄为窜易，盖未能识叶氏之微意耳。", "10449": "温为阳邪，即暴感亦有两种，冬温兼挟寒邪，春温挟风邪，而均由乎外感。所见之证，不外肺胃两经。如头痛咳嗽，气逆痰多，寒热痞闷，烦渴呕恶，皆肺胃外感之证，脉象不外浮弦数大。用药以辛凉散风，或兼辛温祛寒，而必以清泄温邪为主。余则各随见证而施治焉。此暴感温邪初起之大概也。", "10450": "至于伏气发温，在《内经》谓冬伤于寒，春必病温，又谓冬不藏精，春必病温，即此两言推之，则此病必少阴阴气先伤，而寒邪袭之，至春夏化热而发。故又有先夏至为温病，后夏至为热病之文。可知此证随时可发，不拘拘乎在三春也。（［眉批］温邪随时可发，此层补得极圆。）热在骨髓，故骨节烦疼，昏昏欲寐，脉象愈按愈数，尺部不静，尺肤燥热，或渴或否，舌苔如平人，凡此皆热内郁之见象，与外感迥殊。其外达也，或出于三阳，则有三阳见证，或燔于肺胃，则有肺胃见证。其重者不外达于阳，而内陷于阴，在厥阴则痉厥昏蒙，太阴则黄浮腹满，少阴则热烁咽干。凡病入三阴者，无非液涸阴干，以致危殆。（［眉批］温邪变证繁多，虽未能阐发无遗，然大致亦不外乎此矣。）更有热伤血分，营络沸腾，在上则咯血、衄血，在下则溲血、便血。又或热壅络阻，为痈脓疮毒，为咽干口腐，为斑毒痧疹。此又伏气发温之变态，各随时令体质而转移变化者也。", "10451": "予看病三十年来，自著者两方。一方瘀热汤，用三味旋覆花汤加茅根、枇杷叶，治瘀热积胸痛最妙。一方未定名目，治痧疹后，邪恋正虚，将成劳者。倘神识脉情已脱者，无益也。方用四物加杏仁、苏叶、桔梗。", "10452": "石膏证：口渴、汗多、脉大，六字，尽之。过其时口不渴，脉细，便入血分。是犀角证。", "10453": "胸胃皆在中，胁肋在身之侧，故胁肋之证，在杂症门中以肝胆肺三经所主，外感门惟一少阳。盖表邪传里，必由胸以至胁，故胸满多是表证，腹满方是里证。若胁满胁痛，皆是半表半里之证。然伤寒发热胁满痛，亦有兼太阳阳明表邪者，故无汗脉浮恶寒胁痛，先用羌活、柴胡、防风汤，发散表邪，然后用小柴胡汤合小陷胸汤，加枳壳、桔梗、山栀、青皮治之。若有痰饮内结，再加豁痰药。另有一起即从少阳发寒热，或两肋或一肋刺痛，甚则痛极而死。此感时行，燥热伏积于中，又被风寒外束，郁于少阳，名肋刺伤寒，又名痧胀是也。若无汗，恶寒脉浮紧，先用羌活败毒散表邪，随用小柴胡汤加山栀、青皮、苏梗、木通疏散少阳。若是燥热，加知母、石膏，则汗出邪散。不愈，刺委中、三里，并刺十指出血，即名放痧法。另有胁痛寒热，又见咳嗽气逆，此肺受外邪，名金邪入木。有胆经有火，刑克肺金，名木火刑金。此二证最重。初起发热脉浮无汗者，防风泻白散加枳壳、桔梗。若无汗恶寒身痛，有表证者，加羌活、柴胡散表邪。若有汗脉沉数，用黄芩泻白散、合栀连枳桔汤。若燥热流年，重加知母石膏，即见少阳胸胁痛证，亦是金邪入木，仍以肺邪为重，当清肺燥，禁用辛温。若无肺经喘咳之证，则单治少阳。按外感胁痛，最重肋刺伤寒，以时行厉气，客人最速，宜详岁运何司政。予故分详少阳胁痛，肺邪胁痛二条。其下手认证处：以下咳嗽为少阳，以咳嗽为肺邪。以左胁痛为少阳，以右胁痛为肺邪。其认脉处以左手脉病为少阳，以右手脉病为肺邪。其论治法：以脉浮身热无汗，先散表。以脉沉里热，时时有汗，清里热。其有服发汗之药，汗大出，邪不解，表药中重加黄芩、山栀、枳壳、青皮，以清少阳；重加知母、石膏、枳壳、桑皮，以清肺邪。又有用一半散表，一半清里，重用木通、苏梗，疏通经络，得和解之力而愈者。予尝以木通、苏梗各五钱，加入和解方中，以治无汗胁痛身痛，汗必出，痛必减。以木通通窍，苏梗疏散耳。予尝以木通、苏梗各五钱煎汤，治发热胁痛，多有发斑痧而愈者。按此二味药未尝治痛，今以之疏通经络，通则不痛矣。按此二味药未尝主发斑痧，今以之疏通经络，则邪散而斑出矣。", "10454": "诒按：若发热咳嗽胸满，而两胁痛如挫者，此邪热挟湿痰攻注也，小柴胡去参、半，加枳壳、桔梗、栝蒌、杏仁、白芥子，竹沥、姜汁。若心下痛，其人曾闪挫，大便黑而胁下刺痛者，此有瘀血也，桃核承气加枳壳、柴胡；不应加生附子。胁下偏痛发热，其脉紧弦，此寒也，以温药下之，大黄附子汤。", "10455": "霍乱一症，上吐下泻，肢冷转筋，脉伏螺瘪。其外象历年相似，而所以致病之由，各年不同。刻下此症盛行，几于朝发夕死，不及延医。今姑就今年之病推论之，并拟治法如下。", "10456": "霍乱之最易误人者，四肢厥冷，脉伏汗淋，全是阳气欲脱之象。然其中有三证焉。其一：阴寒偏甚，逼阳外越。当用姜、附，以驱寒护阳。所谓中寒霍乱也。其一：真元被扰，虚阳外脱。当用参术桂附以固本回阳。此正虚霍乱也。其一：热邪深闭，阳气外厥，凡内闭者必致外脱。此须大剂清凉开泄伏热，俾内闭渐通，外厥自回，此是热霍乱之最重者也。此三证者，毫里之差，死生反掌，苟非临证细辨，难以刻定。", "10457": "暑为薰蒸之热，湿为黏腻之邪，由口鼻吸受，直行中道，漫布三焦。人在湿蒸热迫之中，无处可避，适或贪凉，夜当风露卧，日复一日，腠理致密，邪机深伏经络营卫之间，遇燥凉之气，感触而发，即为伏暑。初起形寒如疟，继则壮热烦冤，头昏恶心，痞闷时作，医治不中綮，遂变症多端，败坏难救者，不可胜数。大凡此症先明暑之气，何者为重，如兼外感，先散表邪，而解表之药，尤宜分别。如暑邪重者，舌必干燥，苔必起沙，边尖必绛，脉必弦数，头痛恶心，形寒无汗。治宜开太阴肺气，栀、豉、薄荷、连翘、蒌皮、郁金等。如湿邪重者，舌必黏腻，脉必濡滞，胸亦痞闷，形寒无汗。治宜辛温开解，如羌、防、蔻、壳之类。汗出复热者，宗诸竹叶石膏、白虎、羚羊之属。湿多者，宗诸二陈、达原、五苓之属。其天水散二症总可加入，使三焦通畅，营卫流行，丝丝入扣，自然逐日向安。病者再能潜心静养，茹素淡泊，不弥月而告痊矣。且暑为无形，湿为重浊，此类而推，治宜分别，混乱而施，焉能取效乎。医者但知湿邪伤气，为痞满呕泄，而不知燥邪伤气，亦能痞满呕泄耶。失之毫厘，谬以千里，可不慎哉。新凉外束，暑热内蒸，形寒无汗，舌白头痛，呕恶，壮热烦冤，治宜辛凉取汗。", "10458": "大凡六淫之邪，无论风寒暑湿燥火，温病、热病、瘟疫、发斑等，但遇口臭唇焦，多系挟食，医者不察，辄进寒凉，遂致胶结不化，大便屎如羊粪，苔黄痞闷，呕恶便阻，三黄、白虎、承气、陷胸历进不应，每每缩手待毙。是以病人之死，未必死于六淫之邪，死于挟食者为多。盖上唇属阳明大肠，下唇属脾胃，食在上焦，唇焦而燥，消渴；食在下焦，唇焦不燥渴，脉滑不数，汗出热不解。先贤主以保和丸，多加竹沥、莱菔汁，随症加减。", "10459": "一曰肝风之证：亦有虚实两种，而虚者为多。木郁则化火，火郁则生风，此实症也。血虚则木燥，木燥则生风，此虚证也。肝风上升于头者，巅痛、头晕、耳鸣、目眩，宜羚羊角、石决明、明天麻、滁菊、夏枯草、丹皮、黑料豆、刺蒺藜、钩钩。有内风燔于胃口，烦扰不寐，嘈杂呕酸；宜左金、二陈、木瓜、乌梅、竹茹、枳实、白芍、枣仁。有外感经络者，四肢痉掣，麻木牵强，宜羚羊角、刺蒺藜、当归、白芍、丝瓜络、木瓜。以上皆肝郁生风治法，是肝风之实证也。如肝血不足，而兼生火动风者，当于前法中参入滋肝之品，如归、芍、二地、阿胶、龟版、牡蛎、栀子、沙苑、桑椹、天麻、首乌、料豆等柔熄之品。甚则眩晕痉掣，肢厥多汗，急宜三甲复脉、大小定风珠参入珠粉等，以熄风固脱。", "10460": "史痢垢数日不止，状如休息，肠腑中积垢未净，必须疏化。但脉象软数，清晨气滞，脏真暗伤。当以温补为主，佐以疏通可也。", "10461": "陈（左）由疟转痢，经腑交病，所下垢腻如痰者甚多。神倦肢清，脉弱舌滑，苔色白燥，脾阳与胃阴两受重伤，而痰气尚阻而未畅。拟仿理中法加味。", "10462": "杨（左）瓜积伤中，腹痛泄泻，将及一月，渐觉气坠不爽，微有红垢。此脾营下陷，欲作痢疾也。舌苔白腻，脉象细数，气弱邪恋，恐其淹缠。姑与温通。", "10463": "二诊腹痛滞痢，得冷则剧，此脾气虚寒之象。诊脉左弱右弦，中宫并有暑湿，气弱邪恋，最易淹缠。拟方温中疏邪。", "10464": "刘（左）久痢不已，肝脾营气受伤，于是肝木失疏达之性，脾土少健运之力，当脐及脘左块痛，纳谷少而不畅，气机阻窒于中，滞陷于下，营分中余邪，至今未能尽化。脉象虚细弱数。正虚邪恋，奏效颇难，姑与疏肝运脾，冀其调畅乃佳。", "10465": "方中气虚寒由气分伤及血分，痢下瘀紫血水，肢冷腹痛，脉细弦弱。拟建中法，佐以温营畅气。", "10466": "赵便血颇多，肝脾营气大伤，脉虚细，神倦乏力。当从肝脾清摄。", "10467": "姜先患便血，腹中滞痛不爽，此湿热伤营之病，温之涩之，便血稍止，而湿热内踞。中气受伤，渐至脘腹胀满。刻诊脉象弦数，舌苔黄浊。法当清泄肝脾，勿容温补助邪也。", "10468": "孟便血不已，气坠肛脱，自属气虚下陷，宜用升补之法。但左脉弦数，腹中未和，舌苔带浊，仍有湿热留恋，浊痰上壅。宜先疏化。", "10469": "肝木犯胃，痛呕而胀，发必五日，甚则形寒汗出。脉象左手弦长，关部独大，肝木自郁于本宫，气侵及胃，设使胃病及脾，则胀增痛减，病情更重矣。姑先泄木安胃，冀得痛呕两平。", "10470": "脉象左弦右弱，肝气上逆，胃气下降，寒热虽退，而撑痛呕胀，舌中黄厚，时或吐红，胃气不得下行。当与泄肝和胃。", "10471": "撑痛当脘，旁及左胁，痛甚则呕吐酸浊，脉象细弦，病缘肝木犯胃，挟中焦之痰浊，上逆不降。营卫相忤，则形寒里热；风木浮扰，则耳鸣头眩，而总以肝病为主脑。拟方疏肝安胃，畅气化痰。", "10472": "关格已久，近复肝气横逆，撑痛作呕，脉细弱无神，病象已深。再与疏木降胃。", "10473": "病出肝脾两脏。肝营窒塞，则化火生风、而为眩运；血络不调、而为瘀阻；脾气不运，则腹闷色黄，舌浊肢冷。刻当吐瘀之后，咳逆喉鲠，胸膈板滞，肝气逆行于肺络，不得疏降，瘀阻于上，气窒于中，而脉象虚数，已有脏损之征，调治颇难。姑与和营畅气，泄肝通络之法。", "10474": "肝木郁陷，腹痛头晕，脉象弦数。用养肝调气法。", "10475": "再诊前与和肝通络，胀痛攻窜，减而未止，脉象弦中带数，木郁无疑。惟痛偏于右，木邪侵于肺胃之界。拟于前法中加入推气散意。", "10476": "肝木犯中，腹痛作呕，新产奇脉不充，冲脉因之上逆，遂致胸脘撑胀，上及于嗌。脉象左关浮弦而数，巅痛项强，风木化火，郁而上升。当泄木和胃，兼平冲脉之气。", "10477": "肝气逆则胀闷，肝风动则眩晕，脉象弦硬，木郁不达。用药以和肝为主。", "10478": "肝木犯胃，呕吐酸苦浊涎，脉细弦，舌红，气火上逆，肺金不肃。法当苦辛泄降。", "10479": "肝木犯胃，脘痛日作，此气分病也。惟脉细数右弦，内热咳嗽，肝营窒损，有阴血干涸之虑。", "10480": "吴向质气虚木旺，中气输运失常，湿热留恋，阻窒气机，脘腹胀闷，天阴则甚，即其征也。其经水淋沥先期，乃木火内郁，肝血不藏所致。脉象右弦左数，舌苔厚浊，病机偏重于气分。当与和中泄浊，清畅肝木为主。", "10481": "薛内热虽减，左脉尚数，肝经络气未和，胁左板窒作声。再与和络清肝，佐以滋养。", "10482": "王肝木郁陷，脾土受伤，其咳呛属于肺，疝坠属于肝，皆木气为患。泄泻内热，神瘁少纳，则中气被戕矣。左脉细数，右寸关浮弦。当与泄木培中，防其渐就损途。", "10483": "王痛由少腹上掣及脘，此肝肾内虚，寒邪乘袭，其侵及中部，则中阳亦虚矣。脉象濡软中带弦，肝邪上犯，最易变成冲厥。刻下痛势暂平，须及时好为调理，以预防之。", "10484": "徐血行清道而为衄血，其故由于肝火不平，蒸灼营阴，以致血络沸腾，屡发不已，阴血日耗，肝失血养，木火愈甚，驯至逆行，肺金喘逆鼻煽，神色枯悴，上损之候已深。而纳少、跗肿、便溏，中气亦坏。脉象细数，左尺浮数，所伏之肝火，不时上克肺金，而且下及肾阴，肝肾不主摄纳，病见于上，而根坏于下，在损症中为最深之候。姑与清肝肃肺，培土纳肾之法，气阴两顾，扶过炎夏伤金之令，方可从长议治。", "10485": "复诊吐血止后，牙床又肿，脉象左细右数，病因肝火窜于阳明之络，火随血泄。用清营泄肝法调理之。", "10486": "再诊肺气稍平，胃气尚未顺降，而病原实由于肺气之不平。脉象滞数，木火不化。以煎剂疏胃气，丸剂疏肝木。", "10487": "魏肝火不平，挟冲任之血上升为衄，脉象弦数，色黄内热。当用清火泄木之法。", "10488": "金痛由左胁及脘，掣及胸背，上引太阳。脉弦细右浮，余邪内伏，肝火上浮。当蠲饮泄木，两法并用。", "10489": "范脾虚湿郁，面色黄浮。近感新邪，兼增寒热，脉细涩不畅，苔晦。当与和中泄浊。", "10490": "病因痰饮内聚，胃气不得舒降，木气为湿土所郁，渐至化风生火。其呕吐痰沫、大便溏闭不时、气逆头痛诸病，概由乎此。左脉弦细而数，右寸关浮搏而数，肺胃之气，为木火所冲激，不特上逆为呕，抑且掣及经络。兼以阴虚之质，木火易燃，故有内热口渴之证。温中蠲饮，自属正治。但于阴虚肝热者，恐有劫阴之弊。拟仿喻氏关格治例，肝胃两调，寒热互用，冀得通降为吉。", "10491": "嗳哕硬噎，纳谷撑胀，右脉弦硬，肝胃气郁，逆而不降。", "10492": "肝气上逆，肺气不降，胃气被其搏激，失其通降之常。嗳哕不已，纳谷哽噎，脉形滑而神不爽，前医谓痰气相搏，信然。但治痰必先理气。拟与通降肺胃，佐以疏肝化痰。", "10493": "肝胃不和之病，久则胃气空虚，痰浊内阻，谷纳胀闷作呕，不得下降，大便坚少，渐有膈证之象。兼以肝气窜入络脉，腰腹撑痛，气病及血，癸水不调。当与通降胃气为主，而和营泄肝，则兼顾及之。", "10494": "三诊大便通降，胃气得以下行，故纳谷渐增。脉象左弱右弦，腹中撑痛，头眩耳鸣，癸水愆期，此皆肝气不和，气病则营窒，而化火生风，一切肝木之病，连类而起。治法当疏肝畅营为主。", "10495": "脘痛当心，甚则肢厥，呕水不能安谷，大便艰涩。始由肝气不和，久而气瘀交阻，脉象弦细而数，舌色偏红，木火内燃，胃阴渐涸，已属关格重候。姑与泄肝养胃，疏畅气瘀，然必宽怀调理，方能奏效。", "10496": "痛呕较减，但木火久逆，胃中气液两伤，而痰瘀所阻，未必遽能疏化。脉弦软无力，不能安寐。仍从胃腑清养疏降，佐以和肝。", "10497": "脘中痛胀，朝食暮吐，兼带酸浊，脉象弦数，四末不温，木火内燃，中阳不运。由肝气而成反胃，正属难治。姑仿喻氏关格治法。", "10498": "胸气痹窒，上迫于肺。脉象左虚右弦，舌苔黄腻，虽属宿病，而兼挟新邪。以疏降肺气为主。", "10499": "当胸气窒，状如胸痹，此由肝气逆行肺络，不能清降。脉象弦数，木郁生火也。仿《金匮》法，佐以清肝。", "10500": "痰气阻结，清阳被郁，脉数舌黄，兼有浊热蒙扰。当宣痹泄浊。", "10501": "脘腹胀满，半载于兹。据述其来无因，而亦无苦。脉象弦细滑数，舌苔白腻，想由寒湿内著，肝脾之气窒而不化，痰涎浊沫随气而结，病情与单腹无异。拟方用温化法，疏运肝脾，俾浊阴之气得以疏达乃松。", "10502": "方按：细绎病情，彻底澄清，用药亦虚实兼到，切实不浮。然据此脉象，是气阴两伤所致，非必定有浊热，先生之用姜附，是从证不从脉也。", "10503": "肝气郁陷，发热甚于两足，此即邪郁于厥阴之兆。其外达也，不能从经络疏透，而又内陷于脾，挟时令之暑湿，泄泻数日，转为腹胀，胀势甚于少腹，两便通而不爽，仍属木陷土郁之象。惟脉象软细而不弦，舌色乾红而少润，气液两亏，药难著手。姑拟肝脾两疏，录方于后。拟方用四逆散合鸡金胃苓之意。", "10504": "肝脾积热，气血两窒，脘腹胀满，时吐清水，渐至胀及少腹，经水亦停。脉象涩数不畅，病因肝木犯土而起。当舒怀调治，乃得全愈。", "10505": "土虚木乘，左胁撑胀，脉细弱舌白，中阳不能鼓运，气阻痰凝，最易陷成单胀。用温中泄木法。", "10506": "肝木侮中，撑痛胀闷，脉象细软而弦，舌苔黄浊，浊壅气阻，恐延腹胀之候。拟用泄木和中，调气泄浊之法。", "10507": "咯红虽止，而脘胀不减，不能纳谷。脉象软细不畅，肝脾之气，阻窒不化。法与疏木和中。老年病久，不易奏效。", "10508": "胀减而仍作痛，脾气未能舒调也。近日形寒晚热少汗，脉形虚数，肝脾阴气内亏，姑与和中法。", "10509": "脘右结痞，纳谷则脐下作胀，左脉微弦，右脉细弱，舌苔浊腻，病因肝气下陷，脾气不能输运，浊积停阻，将成腹胀之候。", "10510": "病后气机不化，肢面浮肿，而脘腹胀甚，脉象细涩不畅。当通降脾肺，疏泄肝木。", "10511": "腹胀筋青，脉弦细而数，胁左结瘕，病由肝木郁陷，脾气阻结，而湿郁化热，木郁化火，阻窒不达，中阳抑遏不畅，虽在髫年，而病挟情志，调治颇非易易。拟疏木和中法。", "10512": "再诊前与疏木清湿，腹胀减而复作，脉象虚弦无力。此由中气受伤，脾土无自立之权，故病势旋平旋发。拟于前法中参用培益中阳之品，标本兼治，庶几渐瘳。", "10513": "腹胀如鼓，小水不利，似属湿热为病。但脉象左关不和，右手按之弦而数硬，曾经吐瘀便黑，胀势稍减仍增。此由肝气内郁，气聚则血凝，复挟木邪乘土，脾伤湿壅，与痹病湿热者不同。所虑脏气内窒，难必其行动有权耳。", "10514": "经阻数年，渐觉腹胀如鼓，脉象细而数，营气内窒，肝阳浮越，此属瘀胀重证。", "10515": "再诊前与畅肝疏瘀，大解频见紫黑，渐得脉软胀松，于病情尚有转机，但瘀未全化，即病根未动。仍以前方增损。", "10516": "周身肤肿，起于疟后，数月不愈。脉象右寸关浮数而硬，此肺脾两经之气，失于舒运所致。用五苓五皮合香苏法。", "10517": "浊热蒸郁，脾病及肺，咳痰带红，气逆、面浮、肢肿，脉象细数。当肺脾两调，而以清降为主。", "10518": "气血两窒，周身浮肿，病起产后，已历两年，脉虚少纳，内热无汗，势必陷成肿满。姑与和中法。", "10519": "中气不化，浊邪下注，肿从足跗而起，上延脘腹，脉弦数，舌光白。宜和气泄浊。", "10520": "面浮略退，中气失于调畅，脉象左软右弦，湿邪留滞。仍当疏畅。", "10521": "阴经为寒湿所附，由跗肿而上及腿腹，脉象细数不鼓。病底颇深，经气不旺，调治非易。先拟培土温经之法。", "10522": "腹块撑痛，将及半载，病引经络，气窒血阻。凡瘕痛历久化热，亦能壅而成脓，脉象细数，形寒内热，痛处著于左旁。拟与畅气通瘀，疏调营络，取通则不痛之意。", "10523": "脘右瘕撑作痛，宿病剧发，脉弦而迟。法当温通气分，佐以泄降。", "10524": "再诊瘕疼略减，而足热头晕，中虚而木火浮注之象。脉象仍觉弦迟，用建中泄木法。", "10525": "院中瘕痞，攻冲作胀，脉象弦长而数，病由肝木乘土而起，胃虚则汗出头晕，此木火化风也。于泄木中当兼培土。", "10526": "张脘左痞结，数年不消，发则寒热痛胀，不纳不饥。脉象浮弦搏指，不耐重按，中阳已耗，不堪攻伐。姑与疏中化气法。", "10527": "再诊脉象浮搏较和，痞痛较减。惟宿瘕不化，中气久伤，不堪攻伐。再与两和肝脾法，渐渐疏化。", "10528": "某脘右瘕痞不化，舌红脉虚数。气病久结，阴液渐伤，正气渐削，未便攻伐。姑与畅气调营，勉期松展。", "10529": "再诊胃气略醒，精神稍振，但脉仍虚，而脘中瘕结不化，势难攻消。姑先养胃畅气，以扶正为主。", "10530": "唇舌紫暗，幼时已然。近来爪甲色青，营血凝涩已甚，年已及笄，癸水不通，而便下瘀紫，黑血甚多，少腹绞痛，冲脉之气逆升于上。脉象细涩而数，营阻血瘀，非温养疏通，不能奏效。病经十载，难冀速功。", "10531": "再诊瘀血上吐下泻，近日多吐气逆，脉象左手弦硬，右手细数，爪甲唇舌紫黑，较前稍活。惟气火上逆，目红喘促，血之壅滞者，尚未流通。仍当和营导瘀，佐以通降之法，伸得下行为顺。", "10532": "腰俞延及左胁，掣刺作痛，难于转侧，此血络瘀伤之病。脉软数，时有内热，阴气暗伤，当兼滋养。", "10533": "少腹偏左注痛，引及腰脊，寒热连绵。此病因血络瘀阻，邪机下注，热久阴亏，舌红脉数。姑与和络畅营，疏通邪滞。", "10534": "漏血不止，血不归经所致。脉左弦右弱，肝木不调，腹中撑坠。法当条木摄营，兼固奇脉。", "10535": "经漏数月不已，由瘀紫而转为鲜淡。脉象细软带数，腹痛止而腰脊酸，病象由实而虚。当滋养营血，固摄奇脉。", "10536": "经水淋沥不断，腰脊酸疼，奇脉不调，经络不畅，而痞块撑痛，兼见虚窒之象。用调畅奇经，兼疏血络。", "10537": "崩漏屡发不止，右关脉弦数壅结，肝火内扰，血不能安。据述起由经阻，营络先已不畅，当熄肝和营，勿遽用涩。", "10538": "再诊血漏未止，稍劳即发，下部经络不舒，奇脉不畅，肝火不平。宜以摄营法内，佐以清肝和奇。其上部之痰浊不清，当另化之。", "10539": "经停数月而作崩。六七日来崩势已定，而少腹酸楚，经漏淋沥，脉数疾微弦，右寸关尤觉锐快，舌苔满白，舌质不华，营血大伤，脾阳不振，而痰浊因之阻壅，故纳谷不旺也。形寒发热，是营阴之气，虚散不摄，乃失血后常有之证。所虑脾阳就损，恐其虚热淹缠，一时不能清复耳。拟方用养血摄营，温脾和中之法。", "10540": "先经停而后崩漏，腰脊酸痛，奇脉不调，冲任不固，头晕少纳，肝胃不和。当固摄奇脉，兼和肝胃。", "10541": "再诊崩漏之后，肝血必虚，其头晕嘈绞，乃肝阳上扰之病；脘块攻撑，木气不和也；带下腰酸，中气虚陷也。总以调补肝脾，固摄奇脉为主。", "10542": "奇脉不固，为木火所冲激，经漏不止，腰酸色瘀。法当清肝固奇，疏畅营络。", "10543": "崩漏后，晚热盗汗，脉象细数而弦，此必有微邪乘虚袭于营分；留恋日久，即为营损。舌心黄厚，兼有食滞不化。拟方养阴泄邪，稍兼化滞之意。", "10544": "左脉浮数，右脉虚细，经漏淋沥，腰酸嘈运，血不养肝，木燥生风，血不能藏，愈漏愈虚。当清肝摄营，用滋熄法。", "10545": "癸水停阻，但内热而不腹痛，脉象虚细数碎，此由营阴不充，本有枯涩之机。复值酸敛，因而虚涩生热，病虽初起，而根蒂颇深。先宜疏营撤热，冀得畅调为主。", "10546": "癸期迟而淋沥不爽，少腹气滞，奇经之气不得疏畅也。而脘闷纳少，头晕偏痛，则肝阴虚而肝阳上越矣。小便坠痛而涩，兼有血丝，病在气淋血淋之间。腰酸带下，又属脾虚湿陷，奇经不能固摄所致。纳谷作胀，肝脾不和，脉象虚细弦数，气虚而窒，血虚而瘀，病情虚实纷错，调治甚难得手。姑与气血两调，佐以上熄风阳，下疏瘀湿，冀其渐得向松。", "10547": "起由疟邪内陷，渐致寒热往来，经停盗汗。刻诊脉软细而数，右手带弦，脐右瘕痛日作，舌尖红苔黄，泄泻少纳，脉浮。统观脉证，因邪陷而伤阴，因阴伤而营损。最重者，刻已损及中焦，不能多进滋浓。用药殊难为力耳。", "10548": "晚热盗汗，气撑胁痛，病历一年，脉象虚数。刻下足冷颧红，气促不卧。肝气上逆于肺，木郁化火，阴血被耗，近来月事不通，即其验也。证属郁损。姑与熄肝肃肺。", "10549": "停经一载，而无块痛之证，脉象细弱，左手微弦，纳谷甚少，兼作胀闷。先天营气本弱，加以肝木失调，气窒而血液不畅，与瘀阻者不同。先拟畅肝和脾，纳谷渐旺，乃可渐进营分。", "10550": "向患肝木不和，今则肝火偏甚，不能藏血，癸水淋沥不调，时复逆行为衄。脉象虚，左弱右弦，遇节发热，营阴为木火所烁，阴血日亏，肝阳日亢，有延及营损之虑。拟用养血熄肝，调畅肝营之法。", "10551": "再诊衄血虽止，而营热未清，左脉涩数，右脉弦数，营血不充，肝火不静。再与养血潜肝，苟得营阴充足，则经自调而痛自止。", "10552": "经水先期，左脉弦数，此肝气不和，木郁生热，故血不能藏耳。当与凉肝泄木，清养营分。", "10553": "寒湿之邪，乘虚袭于奇脉，腰脊酸疼，癸期愈甚。法当温调奇脉。", "10554": "再诊经来腰脊酸疼，上引头痛，寒湿之邪，乘虚陷于奇脉。法当温经调营，兼和肝气。", "10555": "癸水逾期不通，少腹块痛，病在奇经，屡经攻克，肝脾受伤。脉象虚数，内热少纳，转见营损之象。实病未除，而虚证复起。当与循经和络，通调奇脉。", "10556": "再诊前与通调奇脉，少腹痛坠较甚，肢冷气秽，下焦营气不通，更兼肝木横克。再与温畅奇经，兼以疏肝和气。", "10557": "三诊少腹痛势略减，而癸水未通，营气仍窒，少腹块坠不化，此证虽有瘀血内阻，而内热少纳，脉数色浮，血之来源本少，专与消克，更伤正气。自当参用增水行舟之法，于养营中，复入和瘀畅气之品，乃为稳便。", "10558": "经来少腹滞痛，营气窒塞，奇脉不调。用温通法。", "10559": "奇脉隶于肝，以肝主血也。经来少腹滞痛，木气下陷，则营络窒滞；周身经络牵掣，以肝主经也。脉象虚软带弦。以和肝为主，佐以温通营络。", "10560": "肝木郁结，下陷于奇脉，经来时少腹撑痛，小便不爽。用清泄木火，通调奇经之法。", "10561": "重身六月，而病胎漏，右脉浮数，腰腹坠痛，胎元受伤。以右脉论，当兼凉胎为是。", "10562": "发热咳嗽，色黄盗汗，脉虚细而数，病起产后，邪恋致虚，将及蓐损之候。", "10563": "产后感邪，咳逆、气促、音破、肺气不能疏通，浊痰阻窒，脉细不畅，当与疏化泄邪。", "10564": "少腹响痛，由下而上，发则形寒内热，起于产后。此由寒气袭于下焦，营分阻窒，奇脉不和；而大解滞痛，则涉及肠腑矣。以温通营气为主。", "10565": "小产后瘀血未净，寒气窒于奇经，少腹撑痛，近增寒热。当畅气和营，通调奇脉。", "10566": "脘腹久痛不愈，脾气不舒，湿积交阻之象。面黄脉弱，舌色嫩红，不特脾阳受困，而胃阴亦伤矣。调治颇难，姑与疏调中气。", "10567": "脉象弦搏，右手较硬，四肢时或作冷，夜寐不安，此由肝阳内动之气，厥而不和。当潜肝和阳，兼清肺胃。", "10568": "少腹酸痛，牵引腰脐腿足，此由经络瘀阻，营气壅窒所致。近更寒热绞闷，恶心头痛，左脉弦数，肝气时邪，同时挟发，病机错杂，用药殊难。姑拟泄肝和胃，兼佐通络之意。", "10569": "痛由左胁及脘，掣及胸背，上引太阳，脉细弦右浮，余邪内伏，肝火上浮。当蠲饮泄木，两法并用。", "10570": "邪由肺俞袭入骨节，心痛彻背，脊骨外凸，痛连两胁，兼作咳嗽，脉象虚细而数，右手尤甚。近日胸脘刺痛，亦络气不通所致，正虚邪痼，不易得效。先与和络肃肺。", "10571": "咯血胁痛。项下有核。脉数恶热。咽痛便溏。此肝火乘脾之症。反能食者。脾求助于食。而又不能胜之。则痞耳。治在制肝益脾。", "10572": "肝藏失调。侵脾、则腹痛。侮肺、则干咳。病从内生。非外感客邪之比。是宜内和藏气。不当外夺卫气者也。但脉弱而数。形瘦色槁。上热下寒。根本已漓。恐难全愈。", "10573": "形盛脉充。两尺独虚。下体麻痹火浮气急。此根本不固。枝叶虽盛。未足恃也。", "10574": "诒按（如此脉症。似可参用肾气法、以温摄之。）", "10575": "类中偏左。于法为逆。犹幸病势尚轻。可以缓图取效。原方补少通多。最为合理。惟是阳脉则缓。阴脉则急。所以指节能屈不能伸。此亦病之关键处。不可忽也。经云、肝苦急。宜食甘以缓之。于前方中。增进阴药之甘润者一二。更为美备。", "10576": "脉虚而涩。左半手足麻痹。食不知味。此气血不能运行周体。乃类中之渐也。", "10577": "方书每以左瘫属血虚。右痪属气虚。据述频年已来。齿疼舌赤。常有精浊。纳谷如昔。卒然右偏肢痿。舌强口㖞语謇。脉浮数动。此乃肝肾两虚。水不涵木。肝风暴动。神必昏迷。河间所谓。肝肾气厥。舌喑不语。足痱无力之症。但肾属坎水。真阳内藏。宜温以摄纳。而肝藏相火内寄。又宜凉以清之。温肾之方。参入凉肝。是为复方之用。", "10578": "诒按（即古法而化裁之。参详脉症。斟酌尽善。）", "10579": "脉濡。按之则弦。右肩及手指麻木。两腿酸痒。难以名状。此脾饮肝风。相合为病。乃类中之渐。不可不慎。", "10580": "脉虚而数。两膝先软后肿。不能屈伸。此湿热乘阴气之虚而下注。久则成鹤膝风矣。", "10581": "惊悸易泄。腰疼足软。有似虚象。而实因痰火。盖脉不弱数。形不枯瘁。未可遽与补也。", "10582": "肝风与痰饮相搏。内壅脏腑。外闭窍隧。以致不寐不饥。肢体麻痹。迄今经年。脉弱色悴。不攻则病不除。攻之则正益虚。最为棘手。", "10583": "久嗽脉不数。口不干。未必即成损症。此为肺饮。郁伏不达故也。", "10584": "体虚邪滞。肺络不清。脉弦而细。幸不数耳。", "10585": "肺病以中气健旺。能食便坚为佳。兹喘咳已久。而大便易溏。能食难运。殊非所宜。诊得脉象与前无异。但能节饮食。慎寒暖。犹可无虞。", "10586": "久嗽便溏。脉虚而数。脾肺俱病。培补中气为要。恐后泄不食。则瘦削日增也。", "10587": "脉细数促。是肝肾精血内耗。咳嗽必吐呕清涎浊沫。此冲脉气逆。自下及上。气不收纳。喘而汗出。根本先拨。药难奏功。医若见血为热。见咳治肺。是速其凶矣。", "10588": "脉虚数。颧红声低。咳甚吐食。晡时热升。多烦躁。此肝肾阴亏。阳浮于上。精液变化痰沫。病已三年。是为内损。非消痰治嗽可愈。固摄下焦。必须绝欲。以饮食如故。经年可望其愈。", "10589": "脉微小。形寒。久嗽失音。是气馁阳损。议固胃阳。取甘温之属。", "10590": "用复脉甘润法。呛止音出。得益水濡润之力也。无如胃弱便溏。此药不宜再用。仿金匮麦门冬汤。义取养土之阴。以生肺金。", "10591": "久咳便溏腹满。脾肺同病。已属难治。况脉数。口干潮热。肝肾之阴。亦不足耶。", "10592": "脉寸关大而尺小。口干。上气不下。足冷不温。此阳气不潜。当用阴中阳药治之。", "10593": "脉数减。咳亦缓。但浮气不得全归根本。宜补益下焦。以为吸受之地。", "10594": "气喘足冷至膝。唇口干。鼻塞。脉虚小。下气上逆。病在根本。勿以结痰在项。而漫用清克也。肾气丸三钱盐花汤送下", "10595": "吐血、得劳与怒即发。脉小数。微呛。病在肝心。得之思虑劳心。宜早图之。勿使延及肺家。则吉。", "10596": "失血咳逆。心下痞满。暮则发厥。血色黯。大便黑。肝脉独大。此有瘀血。积留不去。勿治其气。宜和其血。", "10597": "脉寸静尺动。屡经失血。觉气从下焦上冲、则呛。劳动则气促不舒。此病不在肺而在肾。治嗽无益。宜滋肾阴。", "10598": "心脉独大。口干易汗。善怒血逆。此心阴不足。心阳独亢。宜犀角地黄汤。", "10599": "劳伤失血。心下痛闷。不当作阴虚症治。但脉数咳嗽潮热。恐其渐入阴损一途耳。", "10600": "阴不足而阳有余。肝善逆而肺多郁。脉数气喘。咳逆见血胁痛。治宜滋降。更宜静养。不尔。恐其血逆不已也。", "10601": "再诊热渐减。头中时痛。脉数不退。喉中痰滞不清。", "10602": "三诊体虽不热。脉仍细数。宜养阴气。", "10603": "面黧形瘦。脉虚而数。咳嗽气促。腰膝无力。大便时溏。此先后天俱虚。虑其延成虚损。清润治肺之品。能戕中气。勿更投也。", "10604": "络脉空隙。气必游行作痛。最虑春末夏初。地中阳气上升。血随气溢。趁此绸缪。当填精益髓。盖阴虚咳嗽。是他藏累及于肺。若治以清凉。不独病不去。而胃伤食减。立成虚损。难为力矣。", "10605": "汗出偏沮。脉来不柔。时自歇止。知肝阳有余。而胃阴不足。于是稠痰浊火。扰动于中。壅滞于外。目前虽尚安和。然古人治未病。不治已病。知者、见微知著。须加意调摄为当。", "10606": "四诊大便通。脉和。惟宜滋养。", "10607": "下既不通。势必上逆而为呕。所谓幽门之气。上冲吸门。是也。治法自当疗下。但脉小目陷。中气大伤。宜先安中止呕。呕定再商。", "10608": "痛呕之余。脉当和缓。而反搏大。头运欲呕。胸满不食。神倦欲卧。虑其土𬯎木张。渐致痉厥。法当安胃清肝。亦古人先事豫防之意。", "10609": "气郁痰凝。阻隔胃脘。食入则噎。脉涩难治。", "10610": "诒按（旋覆代赭、为噎隔正方。食入则噎。肺气先郁。故加郁、贝枇杷叶。惟脉涩者正虚。可加人参。）", "10611": "脉疾徐不常。食格不下。中气大衰。升降失度。", "10612": "中气叠伤。不能健运。朝食暮吐。完谷不腐。诊得脉虚色黑。腰脚少力。知不独胃病。肾亦病矣。此岂细故哉。", "10613": "肝阴素亏。温邪扰之。发为痉病。神昏骱齿。瘛疭不定。法当滋养肝阴。以荣筋脉。清涤痰热。以安神明者也。若能应手。尚可无虑。", "10614": "热伤津液。脉细口干。难治。", "10615": "诒按（此存阴泄热之正法。所云难治。想因脉细之故。）", "10616": "舌干脉数。汗为热隔。虽发之。亦不得。惟宜甘寒养液。虽不发汗。汗当自出。然必足温而后热退。乃吉。", "10617": "风温郁于肺胃。咳而胸满痰多。胁下痛。脉数口干。", "10618": "脉右大。舌黄不渴。呕吐黏痰。神躁。语言不清。身热不解。此劳倦内伤。更感湿温之邪。须防变端。", "10619": "脐中时有湿液腥臭。按脉素大。此少阴有湿热也。六味能除肾间湿热。宜加减用之。", "10620": "面黑目黄。脉数而微。足寒至膝。皮肤爪甲不仁。其病深入少阴。而其邪则仍自酒湿得之。及女劳也。", "10621": "诒按（寒袭于肾。而气上逆。故用温养。胀及腰背者。督阳不用也。鹿茸、温通督脉。麝香、开泄浊阴。故以之为君。）", "10622": "脉弦小腹痛。食后胃脘痛。上至咽嗌。肝火乘胃。宜泄厥阴。和阳明。", "10623": "心腹痛。脉弦。色青。是肝病也。", "10624": "脉虚数。色白不泽。左胁有块杯大。大便小便自利。病在肝家。营血不和。此为虚中有实。补必兼通。", "10625": "大腹右、有形为聚。脉大。食入即作胀。治在六腑。", "10626": "脉迟胃冷。腹胀。气攻胸胁。恶心少食泄泻。宜振脾胃之阳。", "10627": "脉微迟。左胁宿痞。腹渐胀大。便溏溺少。此是浊阴上攻。当与通阳。", "10628": "脉弦中满。病在肝脾。", "10629": "脉症合参。乃气结在上。津不运行。蒸变浊痰。由无形渐变有形。徐之才谓。轻可去实。非胶固阴药所宜。", "10630": "头疼偏左。耳重听。目不明。脉寸大尺小。风火在上。姑为清解。", "10631": "脾肾寒湿下注。右膝肿痛。而色不赤。其脉当迟缓而小促。食少辄呕。中气之衰。亦已甚矣。此当以和养中气为要。肿痛姑置勿论。盖未有中气不复。而膝得愈者也。", "10632": "背脊为督脉所过之处。风冷乘之。脉不得通。则恶寒而痛。法宜通阳。", "10633": "脉数、耳鸣、吐痰、天柱与腰膝酸痛。两足常冷。病属阴亏阳升。法当填补实下。", "10634": "少阳之脉。循耳外。走耳中。是经有风火。则耳脓而鸣。治宜清散。", "10635": "形伟体丰。脉得小缓。凡阳气发泄之人。外似有余。内实不足。水谷之气。不得阳运。酿湿下注。而为浊病。已三四年矣。气坠、宜升阳为法。非比少壮阴火自灼之病。", "10636": "恼怒伤中。湿热乘之。脾气不运。水谷并趋大肠。而为泄。腹中微疼。脉窒不和。治在中焦。", "10637": "又按（案中脉窒句。不甚明了。）", "10638": "气郁不行。津枯不泽。饮食少。大便难。形瘦脉涩。未可概与通下。宜以养液顺气之剂、治之。", "10639": "下血后。大便燥闭不爽。继而自利。白滑胶黏。日数十行。形衰脉沉。必因久伏水谷之湿。府病宜通。以温下法。", "10640": "鼻痒心辣。大便下血。形瘦脉小而数。已经数年。", "10641": "脉虚细数。阴不足也。鼠漏未愈。热在大肠。", "10642": "诒按（此肛门漏也。名为鼠漏。未知所本。脉症已属损象。故以滋补肝肾为主。）", "10643": "胎前病子肿。产后四日。即大泄。泄已一笑而厥。不省人事。及厥回神清。而左胁前后痛满。至今三月余矣。形瘦脉虚。食少。少腹满。足肿。小便不利。此脾病传心。心不受邪。即传之于肝。肝受病。而更传之于脾也。此为五藏相贼。与六腑食气水血成胀者、不同。所以攻补递进。而绝无一效也。宜泄肝和脾法治之。", "10644": "同龢按。道光五年。吾母许太夫人以欧血谒曹先生于吴门。先生切脉曰。夫人得无从高坠下乎。曰然。又曰、得无引重努力乎。曰然。是时吾母奉亲过岭。先生量药一裹。偻指计程曰。行至赣江愈矣。已而果然。昔母家居。尝左抱儿。右挈浆。下楼。颠。自初桄至不尽一级止。腰膂伤矣。而儿无恙。此欧血之因也。同龢熟闻此事。因谨识于后。", "10645": "心营与肾水交亏。肝气挟肝阳上逆。胸中气塞。口内常干。手震舌掉。心烦不寐。即有寐时。神魂游荡。自觉身非己有。甚至便溏纳少。脾胃亦衰。脉形细小无神。而有歇止之象。逐症施治。似乎应接不暇。因思精神魂魄。必令各安其所。庶得生机勃勃。否则悠悠忽忽。恐难卜其旋元吉。拟许学士真珠母丸法。", "10646": "再诊脉之歇止向和。便之溏泄不作。气塞稍平。手震亦定。但寤多寐少。内藏之魂魄未安。胸痞脘闷。上壅之浊痰未降。容将通阳镇逆法。参入前方。冀相与有成耳。", "10647": "三诊夜半得寐。心肾已交。肺魄肝魂。自能各安其藏。无如心易烦动。神反疲乏。气犹短促。胸还痞闷。脉仍细小。两足不安。脉虚症虚。是谓重虚。而兼有湿痰从之为患。夫痰即有形之火。火即无形之痰也。法当固本为主。消痰佐之。", "10648": "四诊风火痰三者之有余。留滞肝经。以致卧血归肝。魂不能与之俱归。筋惕肉𥆧而醒。前次气短等症。莫不因此。而又起于有年病后。气血两亏。何堪磨耐。所治之方。不出许学士法加减。现在脉息细小带弦。虽无止歇之形。尚有不静之意。究属难免风波。未可以能食为足恃也。", "10649": "五诊前夜熟睡。昨又变为少寐。寐之时。适在子时以后。肝胆两经。尚有余邪可知。更兼痰火阻气。时逆时平。其气逆时。必面赤心悸。甚则肉𥆧筋惕。烦热不安。脉亦随之变异。所谓心火一动。相火随之是也。调治之外。必须静养。俾心火凝然不动。方可渐入坦途。", "10650": "六诊所患小恙。无一不除。盖以清之、化之。补之、养之。无微不至。而得此小效耳。所嫌者。寐非其时。寤非其时。心阳太旺。神气外驰。是卫气独行于阳。阳跷脉满。满则不入于阴。阴分之虚、明矣。将滋阴之品。参入前方。未识能弋获否。", "10651": "诒按（此症不寐。乃肝胆有痰火所致。案中引内经、阳跷脉满之文。本属强为牵合。至以经言阴虚。指为阴血之虚。尤非经文本旨。）", "10652": "七诊人可以参天地之干者。莫贵于眠食如常。今食能知味。眠则未安。昨夜忽寐忽醒。醒则不爽。寐则不安。以昭卫气不得入于阴。独留行于阳之意。（按案语牵合支离、总由误认经文阴字、故说来总不入理）是阳跷脉满营血不能充足。肌肉不能润泽。苟非阳生阴长。阴足恋阳。何以渐入佳境。然营中之血。既不生之于心。乌能藏之于肝。统之于脾。而欲藉草木之无情。俾血肉之有情者。以生以长。谈何容易。况当此痰火易烦。得食暂安。以及虚风内动。筋惕肉𥆧。支体牵摇。大便难通之候。更难为力矣。急宜加意调理。", "10653": "八诊彻夜好眠。神魂已定。是佳兆也。但脉形细小而兼滑数。数为有火。滑为有痰。细属阴虚。小属气弱。虚弱之中。兼有痰火。有时面红。有时咳嗽。有时气痞而短。有时烦热不安。更兼大便燥而小便短。筋惕肉𥆧。支体动摇。神情困倦。语言无力等症。均未平复。还宜谨慎小心。", "10654": "阳络重伤。咳无虚日。而于五更为甚。口干盗汗。溺赤便溏。脉数而身热。欲成损症也。咽中已痛。虑其加喘生变。权以清热存阴。", "10655": "三诊溏泄已止。咳嗽未除。咽痛盗汗。脉数肺经尚有热邪。", "10656": "四诊便泄稀。身热轻。咽喉干痛。亦渐向愈。而咳嗽腹鸣。神疲纳少。脉小带数。想是风热递减。气阴两亏。而脾中之湿。又从而和之为患。补三阴。通三阳之外。更以崇土化湿佐之。", "10657": "八诊脾虚则便溏。肺虚则咳嗽。肾虚则虚火上炎。咽喉干痛。脉弱无力。元气伤矣。急宜补气育阴。", "10658": "先生之病。素禀湿热。又挟阴虚之病也。湿者、何。地之气也。热者、何。天之气也。天地郁蒸。湿热生焉。湿热禀于先天者。与元气混为一家。较之内伤外感之湿热。属在后天者。岂可同日语哉。设使薄滋味。远房帏。不过生疡出血而已。乃从事膏粱。更多嗜欲。斯湿热外增。阴精内耗。脏腑营卫。但有春夏之发。而无秋冬之藏。无怪乎风火相煽。而耳为之苦鸣也。当斯时也。静以养之。犹可相安无事。何又喜功生事。火上添油。致陡然头晕面赤。其一派炎炎之势。盖无非肝经之火。督脉之阳。上冒而为患。近闻用引火归原之法。以为甘温。能除大热。嗟乎。未闻道也。夫甘温除大热者。良以下极阴寒。真阳上越。引其火。归其原。则坎离交媾。太极自安。若阴虚湿热。蒸动于上者。投以清滋。尚难对待。况敢以火济火。明犯一误再误之戒乎。逮后、清已有法。滋亦频投。饮食能增。身体能胖。而坐立独不能久者。明是外盛中空。下虚上实。用药殊难。尝见东垣之清燥汤。丹溪之虎潜丸。润燥兼施。刚柔并进。张氏每赞此两方。谓必互用。始克有济。何故而不宗此耶。然犹有进于此者。治病必资药力。而所以载行药力者。胃气也。胃中湿热熏蒸。致吐血痰嗽。鼻塞噫气。二便失调。所谓九窍不和。都属胃病也。然则欲安内脏。先清外腑。又为第一要著矣。至秋末冬初病甚者。十月坤卦纯阴。天已静矣。而湿热反动。肾欲藏矣。而湿热仍露。能勿令病之加剧乎。附方谨复。", "10659": "身热。手心热。少力神倦。澼利脉濡。此脾阳下陷。阴火上乘。甘温能除大热。正为此等症设也。", "10660": "劳倦而招风湿。右脉濡小。左脉浮弦。舌苔薄白。溺赤便溏。肢体酸楚。神倦嗜卧。少纳口干。", "10661": "五脏六腑。皆有营卫。营卫不调。则寒热分争。此病分争之后。肌肉暗消。因思脾主肌肉。肌肉暗消。正所以昭脾之营卫虚也。无怪乎、脘痞纳少。力乏嗜卧。脉形软弱。有种种脾虚见象。于法当健脾为主。而八八已过之年。阳气必衰。又宜兼壮元阳。使火土合德。尤为要务。", "10662": "心脉宜大者、反小。肾脉宜沉者、反浮。浮则为伤。小则为虚。想是读书攻苦。心肾不交。失其封藏之职。夫心肾。即婴儿、姹女。欲其交者。须得黄婆为之媒合。黄属中央。脾土所主。舍补中宫之外。皆属徒然。", "10663": "昼为阳。阳旺、应不恶寒。夜为阴。阴旺、应不发热。兹乃日间恶寒。夜间发热。何以阴阳相反若是耶。此无他。阳虚、则恶寒于日。阴虚、则发热于夜。阴阳之正气既虚。所有疟后余邪。无处不可为患。足为之浮。腹为之满。溺为之短。一饮一食。脾为之不运。生饮生痰。肺为之咳嗽。脉从内变。而为细弦。夫形瘦、色黄、舌白、阳分比阴分更亏。极易致喘。", "10664": "类中之余。足不任身。手难举物。尺脉无力。阴阳并弱。拟用河间地黄饮子法。", "10665": "怒则气上。痰即随之。陡然语言謇涩。口角流涎。月余不愈。所谓中痰中气也。然痰气为标。阳虚为本。所以脉息迟弦。小水甚多。肢麻无力。法宜扶阳为主。运中化痰佐之。", "10666": "左肢痿而不用。口歪流涎。舌苔起腻。便溏溺少。脉形弦迟。以中虚湿胜之体。易于生痰动风。内风既动。未有不招外风者也。", "10667": "膝骨日大。上下渐形细小。是鹤膝风症。乃风寒湿三气。合而为痹。病之最重者也。三气即痹。又挟肺金之痰以痹肘。所谓肺有邪。其气留于两肘。肘之痹。偏于左。属血属阴。阴血久亏。无怪乎、腰脊突出。接踵而来。至于咳嗽。鼻流清涕。小水色黄。肌肉暗削。行步无力。脉形细小。左关独见弦数。是日久正虚。风寒湿三气。渐见化热之象。拟用痹门羚羊角散加减。", "10668": "神识不清。自言自语。起坐无常。寤寐失度。脉形小滑。舌苔白腻。此痰热内郁心包。无路可出。而作心风也。久久归入癫痫。毋忽。", "10669": "阳明之脉。环于唇。唇起红筋。即发牵动而厥。厥醒吐沫。咳血鼻衄。二便失调。脉弦滑数。显系胃有积热。动血生痰。又被肝火所冲激。乃痫症之根。毋忽。", "10670": "心悸、初从惊恐得之。后来习以为常。经年不愈。手振舌糙。脉芤带滑。不耐烦劳。此系心血本虚。痰涎袭入也。", "10671": "神蒙善忘。包络之病为多。然左寸脉息上浮。关部独带弦数。右寸与关。小而带弦。白苔满布。大便久溏。肢体无力。倦怠嗜卧。脾经之湿痰。被肝火所冲激。累及心包也。", "10672": "曾经失血。现在内热吐痰。夜来大魇。脉象滑数。阴虚挟痰所致。", "10673": "鼻血遗精。肺肾俱病。寒热盗汗。营卫并伤。必须大补为是。无如脉息细弦。舌苔满布。二便失调。饮食不舒。脾家又有湿痰为患。先宜化湿健脾。再商补剂。", "10674": "动则气喘。言则亦然。是下虚也。宜其俯仰不适矣。至于脘中拒按。隐隐作疼。筑筑而跳。脉息中部太弦。必有湿热痰浊。交阻。于胃。失下行为顺之常。未便独以虚治。", "10675": "年逾古稀。肾气下虚。生痰犯肺。咳喘脉微。当与峻补。", "10676": "金水六君煎（麦、地、橘、夏、苓、草）合生脉散加桃肉", "10677": "原注（补命门之火以生土。清其生痰之原。则肺之咳喘自宁。煎方金水六君煎。以治脾肾。生脉、以养肺。桃肉、以补命门。其奠安下焦之剂。另用丸药常服。斟酌可谓尽善矣。）", "10678": "交冬咳嗽。素惯者也。今春未罢。延及夏间。当春已见跗肿。入夏更增腹满。口燥舌剥。火升气逆。右脉濡数。左脉浮弦。风邪湿热。由上而及下。由下而及中。即经所云。久咳不已。三焦受之。三焦咳状。咳而腹满是也。际此天之热气下行。小便更短。足部尚冷。其中宫本有痞象。亦从而和之为患。用药大为棘手。姑拟质重开下法。佐以和胃泄肝之品。", "10679": "寒热后。咳嗽痰浓。头疼口渴。舌红脉数。大便溏泄。冬温之邪郁于肺分。而从燥化。当泄之清之。", "10680": "寒必伤营。亦必化热。咳嗽不止。呕吐紫血。咽中干痛。苔白边青。脉紧而数。近更咳甚则呕。气息短促。肺胃两经。皆失其清降也。郁咳成劳。最为可怕。", "10681": "伤风不醒。咳嗽呕恶。所见之痰。或薄或浓。或带血色。左关脉独见浮弦且数。小有寒热。此损症之根也。千金法治之。", "10682": "再诊进前方咳嗽大减。所出之痰。仍见青黄之色。身热虽轻。咽中苦痛。脉形弦细数。风邪未尽。中下两虚。制小前方之外。参入猪肤法。一治身热。一治咽痛。", "10683": "再诊进劳风法。咳嗽大减。红痰亦无。但痰色尚带青黄。左关脉息。弦硬不和。肝胆留邪。容易犯肺胃俞也。毋忽。", "10684": "右脉弦滑而数。滑为痰。弦为风。风郁为热。热郁为痰。阻之于肺。清肃不行。咳嗽自作。", "10685": "晨起咳嗽。劳倦伤脾。积湿生痰所致。久而不已。气喘畏风。金水因此而虚。补中寓化。一定章程。现在身热口干苔白。脉息细弦而紧。紧则为寒。寒风新感。必须先治新邪。权以疏化法。", "10686": "去冬咳嗽。今春寒热。至秋令、而咳嗽或轻或重。惟喉痒则一。所谓火逆上气。咽喉不利。此等症是也。最易成劳。未可以脉未促。气未喘。为足恃。", "10687": "肺经咳嗽。嗽则喘息有音。甚则吐血。血已止。咳未除。右寸脉息浮弦。弦者、痰饮也。良以饮食入胃。游溢精气。上输于脾。脾气散精。上归于肺。而肺气虚者。不能通调水道。下输膀胱。聚液为痰。积湿为饮。一俟诵读烦劳。咳而且嗽。自然作矣。补肺健脾。以绝生痰之源。以清贮痰之器。", "10688": "左脉浮弦。此脉也。感寒者。恶寒、体痛。发热脉紧。此寒之症与脉也。而风之中。又有辨。春则为温风。肝木用事。受风者。必伤肝。而又有中血中气之别。风伤卫。则参苏饮。风伤营。则芎苏饮。夏则为热。风伤心包。而亦有凉热之别。凉风、香薷饮。热风、鸡苏散。秋为凉风。伤肺、败毒散。金沸草散。冬为寒风。伤膀胱。桂枝厚朴杏仁汤。麻黄汤。傥冬时天热而感寒风。则当用葳蕤汤、阳旦汤。此冬温之邪也。惟秋分以后少暑湿。春夏无燥气。他如先伤风。而后伤热。为热包寒。葳蕤汤。肺素热而感寒风。为寒包热。金沸草散。一嗽而痰出稠黏者。脾湿胜。二陈之类。连嗽无痰者。肺燥甚。清燥救肺汤。此皆外感咳也。言风一端。而六气可类推矣。若夫内伤。大法惟痰饮、津伤、两种。痰饮、多阳虚。津伤、多阴虚。其阳虚痰饮尚浅者。六安二陈之类。有火者。温胆汤。夹阴虚者。金水六君煎。阳虚甚。兼夹痰火不可攻者。玉竹饮子。咸降法。喘者、降气汤、贞元饮。此阳虚痰饮一端也。他如阴虚者。阴火易于上升。胃气不清者。麦门冬汤。曾见血者。四阴煎。痰多而浓。无胃气者。六君子汤。痰少而嗌干。胃气未绝者。六味丸、都气丸、八仙长寿丸。此粗举内伤之一端也。此外又有劳风一门。咳吐浊涕青黄之痰。由劳碌伤风。恋而不化。最为难治。浅者、秦艽鳖甲。表虚汗多者。黄耆鳖甲。深则柴前连梅煎、千金法也。此皆劳风之治也。至于芎、枳、二味。以治寒郁化火之咳。合二母、以泻肺之母。泻白散、以清泄肺藏。四物桔梗汤。", "10689": "再诊接阅手书。知咳血、梦遗、畏火。三者。更甚于前。因思天符之火。行于夏时。可谓火之淫矣。即使肺金无病者。亦必暗受其伤。而况痰火久踞。肺金久伤。再受此外来之火。而欲其清肃下降也。难矣。肺不下降。则不能生肾水。肾水不生。则相火上炎。此咳逆梦遗之所由来也。至于畏火一条。内经载在阳明脉解篇中。是肝火乘胃之故。法宜泻肝清火。不但咳血、梦遗、畏火等症之急者。可以速平。而且所患二便不通。亦可从此而愈。悬而拟之。未识效否。", "10690": "三诊阳明中土。万物所归。现在肝经湿热之邪。大半归于阳明。以著顺乘之意。而逆克于肺者。犹未尽平。所以睡醒之余。每吐青黄绿痰。或带血点。其色非紫即红。右胁隐隐作痛。脉形滑数。独见肺胃两部。宜从此立方。", "10691": "咳嗽而见臭痰络血。或夜不得眠。或卧难著枕。大便干结。白苔满布。时轻时重。已病半年有余。所谓热在上焦者。因咳为肺痿是也。左寸脉数而小。正合脉数虚者。为肺痿之训。而右关一部。不惟数疾。而且独大、独弦、独滑。阳明胃经。必有湿生痰。痰生热。熏蒸于肺。母病及子。不独肺金自病。此所进之药。所以始效。而终不效也。夫肺病属虚。胃病属实。一身而兼此虚实两途之病。苟非按部就班。循循调治。必无向愈之期。", "10692": "再诊诸恙向安。右脉亦缓。药能应手。何其速也。再守之。观其动静。", "10693": "三诊右关之大脉已除。弦滑未化。数之一字。与寸相同。湿热痰三者。尚有熏蒸之意。肺必难于自振。", "10694": "六诊肺虚则易招风。偶然咳嗽加剧。而今愈矣。脉数。右寸空大。阴气必虚。自当养阴为主。然阳明胃经。湿热熏蒸之气。不能不兼理之。", "10695": "七诊右脉小中带数。肺阴不足。肺热有余。其所以致此者。仍由胃中之湿热熏蒸也。", "10696": "昨日所溢之血。盈盆成块而来。无怪乎、其厥矣。幸得厥而即醒。夜半得寐。其气稍平。今日仍然上吐。脉来芤数。火升颧红。咳逆时作。大便不爽而黑。阳明胃府。必有伏热。防其再冒再厥。", "10697": "久嗽失血。鲜而且多。脉数左弦。苔黄心𩠎。金受火刑。木寡于畏。以致阳络被伤也。防冒。", "10698": "阳络频伤。胸前窒塞。咳逆不爽。舌红苔黄。脉形弦数。此系瘀血内阻郁而为热。肺胃受伤。极易成损。慎之。", "10699": "痧子之后。咳嗽四月。颈旁疬串。咳甚则呕。纳少形瘦。肤热脉细。想是余邪内恋。阴分大虚。欲成损症也。", "10700": "温邪发痧之后。咳嗽失血。血止而咳嗽不减。所吐之痰。或黄、或白。或稠、或稀。舌质深红。其苔满白。喉痒嗌干。脉弦带数。渐作痧劳之象。", "10701": "子后咳嗽。天明而缓脉形弦数。声音不扬。肝胆之火未清。金受其刑。水必暗亏也。", "10702": "咳嗽失血。音烁咽干。近来小有寒热。头痛喉疼。脉浮促而数。肺阴久伤。又兼燥气加临。补肺之中。当参以辛散。", "10703": "阳络频伤之后。咳嗽痰浓。内热嗌干。脉芤数。左关独弦。此肝火刑金。金气不清之候。容易成损。慎之。", "10704": "失血后。咳嗽梦遗。脉数。左关弦急。必有肝火在里。既犯肺金。又泄肾气也。久延。势必成劳。", "10705": "失血久咳。阴分必虚。虚则不耐热蒸。食西瓜而稍退。脉数左弦。唇干苔白。色滞溺黄。加以咽痛。久而不愈。想是水不涵木。阴火上冲。胃气不清也。势欲成劳。早为静养。以冀气不加喘。脉不加促。庶几可图。", "10706": "再诊浊痰虽少。咳逆仍然。阴分之火上冲于肺。肺属金。金受火刑。水之生源绝矣。能不虑其脉促气喘乎。知命者。自能静以养之。", "10707": "原注（前两方。六味加减法也。脉数左弦。咽痛。水不涵木。阴火上冲。惟苔白二字。为胃气不清之症。此病头绪甚繁。方中一一、还他的对之药。）", "10708": "脉形细数。细属阴亏。数为有火。火上刑金。水即绝其生源。未可以咳嗽小恙目之。幸而气息未喘。脉象未促。如能静养。犹可以作完人。", "10709": "食则右胁下痛。痰自上升。升则得吐而安。右脉弦滑。左关坚急。寸部独小。此心气下郁于肝经。脾弱生痰为膈。放开怀抱。第一要义。", "10710": "食则噎痛。吐去浊痰而止。胸前常闷。脉象弦滑。舌苔满白。肌肉瘦削之人。阴血本亏。今阳气又结。阴液与痰浊交阻上焦。是以胃脘狭窄也。久则防膈。", "10711": "脉形细涩。得食而噎。胸前隐隐作痛。瘀血内阻。胃络不通。此膈症之根。", "10712": "诒按（此瘀血膈也。脉症均合。用药亦专注。在此。）", "10713": "瘀血挟痰。阻于胸膈。食则作痛。痛则呕吐。右脉涩数。惟左关独大且弦。是痰瘀之外。更有肝经之气火。从而和之为患。乃膈症重候。慎之。", "10714": "食已即吐。脉弦苔白。便溏溺清。湿痰内胜。被肝经淫气所冲。", "10715": "脾阳不足。湿浊有余。少纳多胀。舌白脉迟", "10716": "胸痛彻背。是名胸痹。痹者。胸阳不旷。痰浊有余也。此病不惟痰浊。且有瘀血。交阻膈间。所以得食梗痛。口燥不欲饮。便坚且黑。脉形细涩。昨日紫血。从上吐出。究非顺境。必得下行为妥。", "10717": "心痛彻背。是名胸痹。久而不化。适值燥气加临。更增咳嗽咽干。痰中带红。脉形细小。治之不易。", "10718": "心痛有九。痰食气居其三。三者、交阻于胃。时痛时止。或重或轻。中脘拒按。饮食失常。痞闷难开。大便不通。病之常也。即有厥症。总不离乎痛极之时。兹乃反是。其厥也。不发于痛极之时。而每于小便之余。陡然而作。作则手足牵动。头项强直。口目歪斜。似有厥而不返之形。及其返也。时有短长。如是者。三矣。此名痫厥。良以精夺于前。痛伤于后。龙雷之火。挟痰涎乘势上升。一身而兼痛厥两病。右脉不畅。左脉太弦。盖弦则木乘土位、而痛。又挟阴火上冲、而厥。必当平木为主。兼理中下次之。盖恐厥之愈发愈勤。痛之不肯全平耳。", "10719": "再诊据述厥已全平。痛犹未止。便黑溺黄。右脉反弦。想诸邪都合于胃也。胃为府、以通为补。悬拟方。", "10720": "诒按（诸邪都合于胃。从右脉之弦看出。是病机紧要处。）", "10721": "三诊痛厥已平。尚有背部隐疼之候。腰部亦疼。气逆咳呛。脉形细数。想肝肾阴虚。气滞火升。肺俞络脉。因之俱受其伤也。", "10722": "四诊腰脊尚疼。咳嗽不止。苔白底红。脉形弦细。是阴虚而挟湿热也。", "10723": "脾气素虚。湿郁难化。而木之郁于内者。更不能伸。所以酸水酸味。虽有减时。而灰白之苔。终无化日。无怪乎、脉小左弦。脘胁胀痛也。此臌胀之根。毋忽。", "10724": "病分气血。不病于气。即病于血。然气血亦有同病者。即如此病。胃脘当心而痛。起于受饥。得食则缓。岂非气分病乎。如独气分为病。理其气。即可向安。而此痛、虽得食而缓。午后则剧。黄昏则甚。属在阳中之阴。阴中之阴之候。其为血病无疑。况但头汗出。便下紫色。脉形弦细而数。更属血病见症。但此血。又非气虚不能摄血之血。乃痛后所瘀者。瘀则宜消。虚则宜补。消补兼施。庶几各得其所。", "10725": "原注（分明两病。一是脾虚。气分不能畅达而痛。得食则缓。宜补可知。然人每疑痛无补法者。以痛必有痰气凝滞也。先生用理中以补脾。即加青皮、陈皮、以通气。至便紫、脉弦数。肝家之血。必有瘀于胃脘者。此时不去其有形之瘀滞。痛必不除。病根不拔也。此种病、世医不能治。往往以为痼疾。不知不去瘀、则补无力。徒去瘀、则脾胃更伤。先生则双管齐下。立案清澈。度尽金针。非名家、恶能如是。）", "10726": "胃脘当心而痛。少腹气升。呕吐酸苦痰涎。脉形弦数。显系寒热错杂之邪。郁于中焦。肝属木。木乘土位。所有积饮。从此冲逆而上。病已年余。当以和法。", "10727": "胃脘当心而痛。脉形弦数。舌绛苔黄。口干苦。小便赤。一派火热之象。气从少腹上冲于心。岂非上升之气。自肝而出。中挟相火乎。", "10728": "脘痛下及于脐。旁及于胁。口干心悸。便栗溺黄。脉弦而数。此郁气化火也。", "10729": "原注（此景岳化肝煎也。必肝有实火者、可用。口干、脉数、溺黄。是其的症也。）", "10730": "当脐胀痛。按之则轻。得食则减。脉形细小而数。舌上之苔。左黄右剥。其质深红。中虚伏热使然。", "10731": "少腹久痛未痊。手足挛急而疼。舌苔灰浊。面色不华。脉象弦急。此寒湿与痰。内壅于肝经。而外攻于经络也。现在四肢厥冷。宜以当归四逆汤、加减。", "10732": "少腹作痛。甚则呕吐。脉右弦左紧。俱兼数。舌苔浊腻。口中干苦。头胀溺赤。此湿热之邪。内犯肝经。挟痰浊上升所致。泄之化之。得无厥逆之虞、为幸。", "10733": "再诊呕吐已减。白苔稍化。头胀身热亦缓。惟腹之作痛。便之下利。脉之紧数。以及口中之干苦。小水之短赤。尚不肯平。肝经寒热错杂之邪。又挟食滞痰浊为患也。仍宜小心。", "10734": "肝脉布于两胁。抵于少腹。同时作痛。肝病无疑。肝旺必乘脾土。土中之痰浊湿热。从而和之为患。势所必然。", "10735": "气结于左。自下而盘之于上。胀而且疼。发则有形。解则无迹。甚则脉形弦数。口舌干燥。更属气有余。便是火之见症。急须化肝。", "10736": "再诊病势不增不减。诊得左脉细涩。右部小弱。气血久虚。致使营卫失流行之象。非大建其中。不可。", "10737": "狐疝。原属肝经之湿。随气下陷。脾阳必衰。而今夏多食冷物。阳气又被所遏。苔白不干。指冷脉小。右睪丸胀大。当以温散。", "10738": "寒气客于肠外。与血沫相搏。脐下结瘕。胀大下坠。不时作痛。痛则气升自汗。脉形弦涩。此为鼓胀之根。毋忽。", "10739": "脉来细而附骨者。积也。已经半载。不过气行作响而已。而其偏于胁下者。牢不可破。是寒食挟痰。阻结于气分也。此等见症。每为胀病之根。", "10740": "食入而痛。是有积也。积非一端。就脉弦数。二便黄热。干咳不爽。面黄苔白言之。必有湿热痰食。互相阻滞。经年累月。无路可出。无力以消。", "10741": "寒热后。脘左隐癖作疼。脉形弦细。舌苔浊厚。湿热痰食。交相为患。", "10742": "脘腹膨胀。二便失调。经络酸痛。四肢无力。脉形弦细。舌苔白腻而厚。此湿邪内郁。当用苦辛宣泄。", "10743": "身热时作。脉息弦细。极易成臌。", "10744": "原注〔以上越鞠丸症。大约越鞠治无形湿热之痞。从泻心化出。鸡金治有形食积之癖。从陷胸化出。且如脘痛门中。郁痰作痛。脉数多渴者。用清中蠲痛汤。（山栀、姜汁炒。干姜、川芎、童便炒。黄连、姜汁炒。苍术、童便浸切、麻油炒。香附醋炒。神曲、姜汁炒。橘红、姜枣。治中脘火郁作痛。发即寒热。）中以寒热为主。即越鞠加姜、连橘、枣。可知此方、治气、火、湿、食、血、五者之郁。信极妙矣。说者以栀、主火。术、主湿。香附、主气。芎、主血。曲、主食。分为五郁。似可不必。正如五音必合奏而始和也。〕", "10745": "大腹胀满。已经四十余日。近来气更急促。足跗浮肿。溺黄口干。脉形弦数。湿热之邪。因气而阻。因食而剧。理之不易。", "10746": "大腹主脾。腹大而至脐突。属脾无疑。然胀无虚日。痛又间作。舌苔薄白。脉息沉弦。见于经期落后之体。显系血虚不能敛气。气郁于中。寒加于外。而脾经之湿。因而不消。", "10747": "生脉散", "10748": "大腹胀满。便溏。舌苔冷白。干喜热饮。肤热脉数。脾阳大虚。无力运化湿浊。而成臌也。理之棘手。", "10749": "太阴腹满。寒湿有余。真阳不足。脉弦。下体不温。干不欲饮。妨食气短。其势颇险。拟以温通化湿法。", "10750": "温补元阳。浮肿胀满。有增无减。阳之衰也。极矣。脐平脉迟之候。非温不可。非补亦不可。然温补、亦不见长。盖下泄者。肾更伤耳。", "10751": "中阳不足。寒湿有余。脘痞纳少。舌白便溏。脉细小。法当温化。即平为妙。", "10752": "素有隐癖。肝脾之不调可知。去年血痢于下。痞结于中。久未向愈。大腹胀满。溺赤舌黄。脉形弦细而数。湿热内聚。脾虚无力以消。极易成臌。毋忽。", "10753": "脉弦数大。苔厚中黄。头痛及旁。阳明湿热。挟胆经风阳上逆也。", "10754": "肝居人左。左胁不时攻痛。甚则厥逆。左关沉小带弦。是肝气郁而不升也。右脉弦滑。舌苔薄白。喜饮热汤。又有湿痰内阻。当兼治之。", "10755": "脉沉弦滑。腿骱刺痛。腰部酸疼。背脊作响。诸节亦然。舌苔白浊。风湿痰、三者。著于肝肾之络也。", "10756": "肾者、主蛰。封藏之本。精之处也。精之所以能安其处者。全在肾气充足。封藏乃不失其职。虚者、反是。增出胫酸、体倦。口苦、耳鸣、便坚、等症。亦势所必然。然左尺之脉。浮而不静。固由肾气下虚。而关部独弦、独大、独数。舌苔黄燥。厥阴肝藏。又有湿热。助其相火。火动乎中。必摇其精。所谓肝主疏泄也。虚则补之。未始不美。而实则泻之。亦此症最要之义。", "10757": "再诊大便畅行。口中干苦亦愈。左关之脉大者亦小。惟弦数仍然。尺亦未静。可以前方增损。", "10758": "四诊大便已和。脉形弦数。数为有火。弦主乎肝。肝经既有伏火。不但顺乘阳明。而且容易摇精。精虽四日未动。究须小心。", "10759": "再诊接来札、知所言梦遗者。有梦而遗者也。比之无梦者。大有分别。无梦为虚。有梦为实。就左脉弦数而论。弦主肝。数主热。热伏肝家。动而不静。势必摇精。盖肾之封藏不固。由肝之疏泄太过耳。", "10760": "三诊叠进封髓秘丸。而仍不主蛰。细诊脉息。左关独见沉弦且数。肝经之疏泄显然。", "10761": "曾经失血。现在遗精。精血暗伤。当脐之动气攻筑。漫无愈期。肢体从此脱力。语言从此轻微。饮食从此减少。无怪乎、脉息芤而无神也。病情如此。虚已甚矣。而舌苔腻浊。中宫又有湿邪。治须兼理。", "10762": "白浊久而不痊。以致肾失封藏。梦遗更甚。少寐少纳。面痿脉少。", "10763": "阴虚之体。心火下郁于小肠。传入膀胱之府。尿中带血。时作时止。左脉沉数。小水不利。", "10764": "再诊所下之淋。薄且少矣。而当便之时。尚属不利。既便之后。反觉隐痛。肢膝不温。脉小弦。唇红嗌干。热未全消。虚已渐著。", "10765": "曾患淋症。小便本难。近来变为癃闭。少腹硬满。小便肿胀。苔白不渴。脉小而沉。下焦湿热。被外寒所遏。膀胱气化不行。最为急症。恐其喘汗。", "10766": "飧泄不由乎胃滞。即系乎阳弱。此乃兼而有之。脉迟嗳腐脘痛。", "10767": "肠澼便血。时重时轻。或痛或否。脉形细小。饮食少。此虚也。恐增浮喘。", "10768": "便血之前。先见盗汗。盗汗之来。由于寒热。寒热虽已。而盗汗便血之症不除。脉小而数。气阴两虚之病也。", "10769": "湿热伤营。腹臌便血。久而不愈。左脉细涩。右芤。寸大尺小。加以浮肿。气分亦虚。不但不能摄血。而且不能清化湿热。防喘。", "10770": "病将一载。肝气横逆而不平。中气久虚而不振。惟肝逆、故胸脘阻塞而攻冲。惟中虚、故营卫不和而寒热。凡大便溏。饮食少。右脉细。左脉弦。是其症也。四君子合逍遥加左金。是其治也。", "10771": "骨格瘦小。先天元气不足。夏秋寒热。至今不已。脉细数弱。气血两亏。头不痛而但身痛。或口沃清水。此胃阳虚惫也。当商温补。仿东垣法。", "10772": "左脉空大。肾水亏也。倦怠无力。脾气弱也。食少则阴虚。阴虚生内热。症属内伤。", "10773": "诒按（补中益气、补脾气。六味补肾阴。立法颇切实。惟左脉空大。方中升柴两味。尚宜斟酌耳。）", "10774": "两手关脉。皆见一粒厥厥动摇之象。此土虚木胜。内风动跃之候也。左半肢体麻木不仁。头眩面麻。病属偏枯。虑延仆中。", "10775": "再诊动摇之脉大减。内风有暗熄之机。左手屈伸稍安。左足麻木未和。拟补肾生肝。为治本之计。", "10776": "再诊肺为水源。百脉朝宗于肺。犹众水朝宗于海也。肺热叶焦。则津液不能灌输于经脉。而为痿躄。卧床不能行动。形肉消削。咳嗽痰臭。舌红无苔。脉细而数。是皆津液消耗。燥火内灼之象。考经论、治痿独取阳明者。以阳明主润宗筋。胃为气血之源耳。今拟生胃津。以供于肺。仿西昌喻氏意。", "10777": "肝为风藏而主筋。心为火藏而主脉。心包络与三焦相为表里。俱藏相火心包主里。三焦统领一身之络。此病起于病后。心中𩠎热。胸前跳跃。继而气攻。背脊如火之灼。或大或小。或长或短。皆在经络脊脉之中。良由病后络脉空虚。相火内风。走窜入络。非清不足以熄火。非镇不足以定风。然而络脉空虚。使非堵截其空隙之处。又恐风火去而复入。故清火、熄风、填窍、三法。必相须为用也。第此症实属罕见。医者、意也。以意会之可耳。仿仲景法。", "10778": "久患肝风眩运。复感秋风成疟。疟愈之后。周身筋脉跳跃。甚则发厥。此乃血虚不能涵木。筋脉失养。虚风走络。痰涎凝聚所致。拟养血熄风。化痰通络。", "10779": "上年夏季。痰火迷心。神呆语乱。治之而愈。至今复发脉浮小弱。舌心红而苔薄白。语言错乱。哭笑不常。凭脉而论。似属心风。盖由风入心经。蕴热蒸痰所致。用本事独活汤法。", "10780": "寡居十载。愁惕苦心。牙龈出血。有时若痫。其病已久。兹一月前。猝遭惊恐。遂神糊语乱。口吐紫血腹胀不食。两脉模糊。难以捉摸。此乃惊动肝阳。神魂扰乱。血随气逆。是即薄厥之属。今两足常冷。阳升于上。急以介类潜阳。重以镇怯。冀其厥止。再商。", "10781": "心境沉闷。意愿不遂。近因患疟。多饮烧酒。酒酣之后。如醉如狂。语言妄乱。及今二日。诊脉小弦滑沉。舌苔薄白。小水短赤。大便不通。渴欲饮冷。昏昏默默。不知病之所的。因思疟必有痰。酒能助火。痰火内扰。神明不安。此少阳、阳明、同病。而连及厥阴也。少阳为进出之枢。阳明为藏邪之薮。今邪并阳明。弥漫心包。故发狂。而又昏昏默默也。仿仲景柴胡加龙牡汤主之。", "10782": "咳嗽口不渴。当脐痛。而脉细。头常眩运。此乃手足太阴二经。有寒饮积滞。阻遏清阳之气。不能通达。故一月之中。必发寒热数次。乃郁极则欲达也。病将四月。元气渐虚。寒饮仍恋而不化。先以小青龙汤。蠲除寒饮。宣通阳气。再议。", "10783": "脉沉取之数。其阴内亏。其热在里。病延日久。劳损之候。症见咳唾白痰。脘腹时痛。痛则气满。得矢气则稍宽。病由肝郁而成。据云、咳已三年。初无身热。是其根又有痰饮也。经训治病。必求其根。兹从痰饮气郁例治之。", "10784": "六味地黄丸合生脉散加青铅", "10785": "暑风从背俞而内薄于肺。湿热从胃脉而上熏于肺。外内合邪。其气并于胸中。气不得通。因而上逆。气升作咳。舌苔薄白。口腻不渴。治属饮家。", "10786": "再诊喘哮频发。脉形细数。身常恶寒。下焦阴虚。中焦痰盛。上焦肺弱。肺弱故畏寒。阴虚故脉数。喘之频发。痰之盛也。有所感触。病遂发焉。病有三层。治有三法。层层护卫。法法兼到。终年常服。庶几见效。否则恐无益也。", "10787": "五脏皆有咳。总不离乎肺。肺为娇脏。不耐邪侵。感寒则咳。受热则咳。初起微有寒热。必挟表邪。邪恋肺虚。脉形空大。前方降气化痰。保肺涤饮。俱无少效。据云、得汗则身体轻快。想由肺气虽虚。留邪未净。补虚而兼化邪。亦一法也。用钱氏法。", "10788": "脉虚软而似数。内伤虚弱奚疑。夫邪之所凑。其气必虚。虚处受邪。其病则实。咳嗽虽由外感。而实则因于气虚。以为风寒。固不可以为虚损。亦未必可。玉竹饮子主之。", "10789": "咳嗽四年。曾经失血。今已音哑。脉形细弱。真阴元气皆亏。劳损根深。药难见效。犹幸胃气尚可。大便未溏。姑拟甘润养阴。希图苟安而已。", "10790": "再诊咳嗽止而失血音哑。津液枯槁。劳损成矣。脉形细弱。精气两亏。内经于针药所不及者。调以甘药。金匮遵之。而用黄耆建中汤。急建其中气。俾得饮食增而津液旺。冀其精血渐充。复其真阴之不足。盖舍此别无良法也。", "10791": "咳嗽月余。痰腥带血。气升呛逆。脉弦滑数。风温久恋。化火蒸痰。灼金耗液。症属肺痈。非轻候也。", "10792": "再诊咳热痰腥带血。脉形弦硬。面色暗晦。肺气失降。木火上逆。防加喘急。", "10793": "脉数血不止。胃气大虚。胸中痞塞。大便常溏。是痞为虚痞。数为虚数。咳血三月。今忽冲溢。唇白面青。断非实火。大凡实火吐血。宜清宜降。虚火吐血。宜补宜和。古人谓、见痰休治痰。见血休治血。血久不止。宜以胃药收功。今拟一方。援引此例。未知有当高明否。", "10794": "再诊脉数退。血少止。药病相当。颇得小效。而反恶寒汗出者。盖血脱则气无所依。气属阳。主外卫。虚则不固。故恶寒而汗出。最怕喘呃暴脱。措手莫及。犹幸胸痞已宽。稍能容纳。仿血脱益气之例。经曰、阳生阴长。是之谓耳。", "10795": "诒按（以后方、均是复脉加减。）", "10796": "素患呕血。血止复发。现有胸痛。时时嗳气。舌苔白腻。脉细而迟。此胃中有瘀血。挟痰浊为患也。", "10797": "始由寒饮咳嗽。继而化火动血。一二年来。血症屡止屡发。而咳嗽不已。脉弦形瘦饮邪未去。", "10798": "去秋咳嗽。些微带血。已经调治而痊。交春吐血甚多。咳嗽至今不止。更兼寒热。朝轻暮重。饮食少纳。头汗不休。真阴大亏。虚阳上亢。肺金受烁。脾胃伤戕。津液日耗。元气日损。脉沉细涩。口腻而干。虚极成劳。难为力矣。姑拟生脉六君子汤。保肺清金。调元益气。扶过夏令再议。", "10799": "原注（生脉散、保肺清金。六君子去术、嫌其燥。加扁豆、培养脾阴。土旺自能生金也。不用养阴退热之药。一恐滋则滑肠。一恐凉则妨胃耳。从来久病。以胃气为本。经云、有胃则生。此其道也。）", "10800": "咳嗽内伤经络。吐血甚多。脉不数。身不热。口不渴。切勿见血投凉。法当益胃。拟理中加味。", "10801": "内则阴虚有火。外则寒邪深袭。失血咳嗽。又兼三疟。病已数月。疟来心口酸痛。胸腹空豁难通。经云、阳维为病。苦寒热。阴维为病。苦心痛。此阴阳营卫之偏虚也。拟黄耆建中法。和中藏之阴阳。而调营卫。复合生脉、保肺之阴。复脉、保肾之阴。通盘打算。头头是道矣。", "10802": "历春夏秋三季。血症屡发。诊脉虚弱。形容消瘦。年方十七。精未充而早泄。阴失守而火升。异日难名之疾。恐犯褚氏之戒。治当滋水降火。须自保养为要。", "10803": "阳维为病。苦寒热。阴维为病。苦心痛。阳维维于阳。阳气弱。则腹痛而便溏。阴维维于阴。营阴虚、则心痛而舌红也。脉微形瘦。阴阳并损。损及奇经。当以甘温。", "10804": "再诊但寒不热。便溏脉细。肢体面目俱浮。悉属阳虚见象。惟舌红无苔。此属阴伤之候。但口不干渴。乃君火之色外露。治当引火归元。", "10805": "左寸关搏指。心肝之阳亢。右脉小紧。脾胃之虚寒。是以腹中常痛。而大便不实也。病延四月。身虽微热。是属虚阳外越。近增口舌碎痛。亦属虚火上炎。津液消灼。劳损何疑。今商治法。当以温中为主。稍佐清上。俾土厚则火敛。金旺则水生。古人有是论。幸勿为世俗拘也。", "10806": "诒按（此阴亏而虚火上炎之症也。方以理中合生脉法。温中清上。两面都到。所云土厚则火敛。金旺则水生。见理极精。非浅学所能学步。）", "10807": "脉沉细数涩。血虚气郁。经事之不来宜也。夫五志郁极。皆从火化。饥而善食。小水澄脚如脓。三消之渐。匪伊朝夕。然胸痛吐酸。肝郁无疑。肝为风藏。郁甚则生虫。从风化也。姑拟一方。平中见奇。", "10808": "再诊服药后。大便之坚且难者。化溏粪而易出。原属苦泄之功。然脉仍数涩。究属血虚而兼郁热。郁热日甚。藏阴日铄。舌红而碎。口渴消饮。所由来也。月事不至。血日干而火日炽。头眩目花带下。皆阴虚阳亢之见症。补藏阴为治本之缓图。清郁热乃救阴之先著。转辗思维。寓清泄于通补之中。其或有济耶。所虑病根深固。未易奏绩耳。", "10809": "胃中素有酒湿。适因斗殴恼怒。引动肝胆之火。与胃中之痰相搏。致心跳少寐。食入则呕。两手脉沉。是气郁也。用温胆加味。", "10810": "再诊内经云、三阳结。为之膈。三阴结。为之水。此症反胃而兼浮肿。是三阴三阳俱结也。阴阳俱结。治法极难。前方用荜茇牛乳饮。调服沉香、血珀、末。拨动其阴阳俱结之气。幸反胃之势已平。是其三阳之结已解。今腹满虽宽。而腿足之肿仍若。是三阴之结。犹未解也。盖太阴无阳明之阳。少阴无太阳之阳。厥阴无少阳之阳。则阴独盛于内。而阳气不通。阴气凝涩。膀胱不化。而水成焉。其脉沉细。盖重阴之象也。凡补脾崇土。温润通阳。如理中、肾气丸、之属。固亦合法。然不若周慎斋和中丸之制。为尤妙。以其用干姜。能回阳明之阳于脾。肉桂、回太阳之阳于肾。吴萸、回少阳之阳于肝。则三阳气胜。而三阴之结解。水自从膀胱出矣。", "10811": "据述病由丧子悲伤。气逆发厥而起。今诊左脉。沉数不利。是肝气郁而不舒。肝血少而不濡也。右关及寸部。按之滑搏。滑搏为痰火。肺胃之气失降。而肝木之气上逆。将所进水谷之津液。蒸酿为痰。阻塞气道。故咽嗌胸膈之间。若有𪱥塞。而纳谷有时呕噎也。夫五志过极。多从火化。哭泣无泪。目涩昏花。皆属阳亢。而阴不上承之象。目今最要之症。乃胸膈咽噎阻塞。的系膈气根萌。而处治最要之法。顺气降火为先。稍参化痰。复入清金。金清、自能平木也。", "10812": "吐血后呃逆。作止不常。迄今一月。舌苔白腻。右脉沉滑。左脉细弱。其呃之气。自少腹上冲。乃瘀血挟痰浊。阻于肺胃之络。而下焦相火。随冲脉上逆。鼓动其痰。则呃作矣。病情并见。安可模糊。若捕风捉影。无惑乎、其不效也。今酌一方。当必有济。幸勿躁急为要。", "10813": "舌干而绛。齿燥唇焦。痰气喘粗。脉象细数。无形之邪热。熏蒸于膻中。有形之痰浊。阻塞于肺胃。而又津枯液燥。正气内虚。恐有闭厥之变。拟化痰涤热。以治其标。扶正生津。以救其本。必得痰喘平。神气清。庶几可图。", "10814": "再诊头汗淋漓。痰喘不止。脉形洪大。面色青晦。舌红干涸。齿板唇焦。此少阴阴津不足。阳明邪火有余。火载气而上逆。肺不降而为喘。症势险危。深防厥脱。勉拟救少阴之阴。清阳明之火。益气以收其汗。保肺以定其喘。转辗图维。冀其应手为妙。", "10815": "原注（此玉女煎、合生脉散。尽温病以救阴为急也。）", "10816": "三诊头汗稍收。痰喘稍平。脉大稍敛。但气仍急促。而心中烦躁。舌红干涸。齿垢唇焦。津液犹未回。虚阳犹未熄。上逆之气。犹未下降。虽逾险岭。未涉坦途。现今心腹。似有透喑之象。是亦邪之出路。仍拟救少阴。清阳明。再望转机。", "10817": "温邪袭肺。肺失清肃。湿夹热而生痰。火载气而上逆。喘息痰嘶。舌干口腻。昨日之脉。据云弦硬。现诊脉象。小而涩数。阴津暗伤。元气渐馁。颇有喘汗厥脱之虑。夫温邪病隶手经。肺位最高。治宜清肃。痰随气涌。化痰以降气为先。气因火逆。降气以清火为要。姑拟一方。备候酌夺。", "10818": "原注（凡时症之脉。先大而后渐小。先强而后变弱。其热不退。而病反增者。必死。。此死症也。无能为力。立方用药。无甚深意。）", "10819": "诒按（此要诀也。最须记好。。初病之脉硬大者。邪正相搏也。转为弱小。正气馁矣。而病象不退而反增。正气不能敌邪也。病日进而正日亏。不死何待。）", "10820": "诒按（葶苈、治痰喘症属实者。若身不热、而脉微者。忌之。）", "10821": "三诊战汗已得。脉静身凉。邪已解矣。舌黄未去。胃中余浊未清。尚宜和化。", "10822": "原注、凡战汗后。脉静身凉。用方大法。不外乎此。总以和胃气、化湿热为主。", "10823": "三诊得汗得便之后。用和胃化邪法。一剂颇安。两剂反剧。良以畏虚。多进谷食。留恋其邪。不能宣化。郁于心胃之间。湿蕴生痰。热蒸液烁。遂见烦躁、恶心、错语、等症。两手寸关、脉细滑数。两尺少神。舌边乾红。心苔黄腻。皆湿热郁蒸。将燥未燥。欲陷未陷之象。当此阴亏之体。能不虑其内陷乎。拟导赤泻心各半法。生津化浊。和胃清心。", "10824": "六诊口臭喷人。胃火极甚。斑疹虽见。透而未足。目赤神糊。脉洪口渴。急速化斑为要。古法化斑以白虎为主。仍参入犀、地。清营解毒。再复存阴。又适合玉女煎法。未知能应手否。", "10825": "八诊黑苔剥落。舌质深红。阴津大伤。燥火未退。左脉细小。右脉洪数。是其征也。此际阴伤火旺。少阴不足。阳明有余。惟景岳玉女煎、最合。一面泻火。一面存阴。守过三候。其阴当复。", "10826": "十一诊耳聋无闻。舌干难掉。阴津大伤。用复脉法。", "10827": "寤则神清。呃声徐而未除。脉象耎而小数。周先生清营泄卫。理气化浊。恰如其分。僭加一二味。仍候主裁。", "10828": "三诊热处湿中。神蒙嗜卧。呼之则清。语言了了。验舌苔之白腻。参脉象之耎数。知非热陷膻中。乃湿热弥漫于上焦。肺气失其宣布耳。呃尚未除。胃浊未化。拟从肺胃立法。", "10829": "凡症于阴阳虚实。疑似之间。最当详审。此症音低神倦、似虚。而便泄臭水。中脘按痛。实也。肢冷脉细、似阴。而小便热痛。阳也。至于舌白谵语。乃痰蒙火郁之征。而日暮烦躁。为阴虚阳盛之兆。鄙意百般怪症。多属乎痰。痰蒙火郁。清化不解。须从下夺。即使正虚。而虚中夹实。亦当先治其实耳。", "10830": "素有肝胃病。适挟湿温。七日汗解。八日复热。舌灰唇焦齿板。口渴欲得热饮。右脉洪大数疾。左亦弦数。脘中仍痛。经事适来。静思其故。假令肝胃病。木来乘土。气郁而痛。若不挟邪。断无如此大热。又大便坚硬而黑。是肠胃有实热所谓燥屎也。考胃气痛门。无燥屎症。惟瘀血痛门。有便血。而此症无发狂妄喜之状。又断乎非蓄血也。渴喜热饮。疑其有寒似矣。不知湿与热合。热处湿中。湿居热外。必饮热汤。而湿乃开。胸中乃快。与真寒假热不同。再合脉与唇观之。其属湿温挟积无疑。伤寒大白云、唇焦为食积。此言诸书不载。可云、高出千古。", "10831": "原注（病本湿温挟食。交候战汗而解少顷复热。为一忌。汗出而脉躁疾者。又一忌。适值经来。恐热邪陷入血室。从此滋变。亦一忌。故用豆豉、以解肌。黑栀、以清里。一宣一泄。祛表里之客邪。延胡索、通血中气滞。气中血滞。兼治上下诸痛。郁金、苦泄以散肝郁。香附、辛散以利诸气。二味合治妇人经脉之逆行。即可杜热入血室之大患。栝蒌、通府。赤苓利湿。加竹茹、连翘。一以开胃气之郁。一以治上焦之烦。外用葱、盐、热熨。即古人摩按之法。相赞成功。）", "10832": "再诊服药后。大便一次。色黑如栗者、数枚。兼带溏粪。脘痛大减。舌霉唇焦、俱稍退。原为美事。惟脉数大者。变为虚小无力。心中觉空。是邪减正虚之象。防神糊痉厥等变。今方九日。延过两候乃吉。", "10833": "诒按（大解后、热平。脉转弱小。倘内伏之热邪已净。或稍有余热。而不甚重。则从此各候俱平。只须清养而已。若停一二日。伏邪再炽。则脉随病变。或仍转数大。亦未可知。若热势盛而脉虚小。是邪盛正虚之重候。仍当随见症治之。不得以九日两候等语为凭也。）", "10834": "再诊投两解法。得汗得便。竟得安然两目。昨已起床。照镜、启窗、看菊。须臾之间。渐渐发热。热甚神糊。两目上视。几乎厥脱。迨至黄昏。神识渐清。热势渐减。然脉沉不起。据述热时。舌色乾红。热退、舌色黄腻。此乃湿遏热炽。将燥未燥。但阳症阴脉。相反堪虞。勉议河间甘露饮子。于涤热燥湿之中。更藉桂、以通阳。苓、以通阴。复入草果、祛太阴湿土之寒。知母、清阳明燥金之热。未识得奏肤功否。", "10835": "年过花甲。病逾旬日。远途归家。舟舆跋涉。病中劳顿。雪上加霜。欲询病原。无从细究。刻诊脉象沉糊。神识蒙昧。舌强色白。中心焦燥。身热不扬。手足寒冷。气短作呃。便泄溏臭。凭理而论。是属伏邪挟积。正虚邪陷之象。深恐有厥脱之虞。勉酌一方。还祈明正。", "10836": "三诊伏暑化燥。劫津动风。舌黑唇焦。鼻煤齿燥。神识昏糊。手指牵引。今早大便自通。据云、病热略减。然两脉促疾无伦。阴津消涸。邪火燎原。仍属险象。", "10837": "伏暑为病。湿热居多。阴虚之体。邪不易达。此其常也。然就阴虚而论。大有轻重之分。须知此症。虚亦不甚。邪亦不多。即据耳鸣眩悸。苔浊胸痞。微寒微热。脉形弦数。立方未便著手。大补、亦不可重剂。攻邪、但得脉情无变。可保无虞。慎勿徒自惊惶。反增他变。", "10838": "伏邪挟积。阻塞中宫。疟发、日轻日重。重则神糊烦躁。起卧如狂。此乃食积蒸痰。邪热化火痰。火上蒙。怕其风动痉厥。脉沉实。而舌苔黄。邪积聚于阳明。法当通下。仿大柴胡例。", "10839": "诒按（脉舌与症合参。大柴胡是的对之药。）", "10840": "三诊昨日疟来。手足寒冷。即时腹中气胀。上塞咽喉。几乎发厥。但不昏狂耳。此乃少阳疟邪。挟内伏之痰浊。上走心胞。为昏狂。下乘脾土。为腹胀。前日之昏狂。病机偏在阳明。故法从下夺。今腹胀、舌白、脉细。病机偏在太阴。法当辛温通阳。转运中枢为要矣。随机应变。急者、为先。莫谓用寒用热之不侔也。", "10841": "四诊投果附达原、神香、二陈、合剂。服药后。喉中汨汨有声。上逆之气即平。腹胀遂松。今脉缓大。神气安和。腹中微觉胀满。痰多黏腻。脾藏阳气虽通。寒湿痰涎未化。仍从前法。轻减其制。", "10842": "三疟久延。营卫两伤。复因产后。下焦八脉空虚。今病将九月。而疟仍未止。腹中结块偏左。此疟邪留于血络。聚于肝膜。是属疟母。淹缠不止。虑成疟劳。夏至在迩。乃阴阳剥复之际。瘦人久病。最怕阴伤。趁此图维。迎机导窾。和阳以生阴。从产后立法。稍佐搜络。以杜疟邪之根。", "10843": "素有痰饮咳嗽。近复凉风外薄。食积内停。寒热似疟。脉弦数。额角痛。胸脘痞胀。大便不通。是有表复有里也。拟以疏里解表。", "10844": "再诊脉弦数。两手掌心独热。大便五日不通。舌苔薄白不黄。燥屎尚未全结。欲通其腑。缓法为宜。", "10845": "三疟止而复作。腹满平而又发。今目黄脉细。面黑溺少。防延黑瘅。然瘅而腹满者、难治。姑与分消。", "10846": "再诊面色黧黑。腹满足肿。脉沉而细。此脾胃之阳不化。水湿阻滞于中。证防增重。且与通阳渗湿。", "10847": "再诊胸痹痰饮。脘痛。甚则呕酸。脉细。胃阳不布。先以通阳。", "10848": "肝胃气痛。痛久则气血瘀凝。曾经吐血。是阳明胃络之血。因郁热蒸迫而上也。血止之后。痛势仍作。每发于午后。诊脉小紧数。舌红无苔。乃血去阴伤。而气分之郁热。仍阻于肝胃之络。而不能透达。宜理气疏郁。取辛通而不耗液者、为当。", "10849": "脉双弦。有寒饮在胃也。脘痛吐酸。木克土也。得食则痛缓。病属中虚。当和中泄木祛寒。小建中汤加味主之。", "10850": "脘痛。肢冷脉伏。头汗淋漓。防厥。", "10851": "肝木挟下焦水寒之气。乘于脾胃。脘痛攻胁。呕吐酸水。脉细而弦。拟温中御寒。扶土抑木方法。", "10852": "素有肝胃气痛。兼有寒积。脘痛胀满。痛及于腰。刻不可忍。舌苔白腻。渴不欲饮。大便似利不利。脉象沉弦而紧。按症恐属藏结。颇为险候。非温不能通其阳。非下不能破其结。仿许学士温脾法。", "10853": "三诊两投温下。大便仍然不通。胸腹高突。汤水下咽辄呕。肢渐冷。脉渐细。鼻煽额汗。厥脱堪忧。按结胸藏结之分。在乎有寒热无寒热为别。下之不通。胀满愈甚。乃太阴脾藏受戕。清阳失于转运。崔行功、有枳实理中一法。取其转运中阳。通便在是。挽回厥脱。亦在是。", "10854": "用五积合通圣。温通散寒。便通、而痛未止。脉迟。喜食甜味。痛在当脐。后连及腰。身常懔懔恶寒。此中虚阳弱。寒积内停。拟通阳以破其沉寒。益火以消其阴翳。", "10855": "久患休息下痢。或作或辍。四月下旬。痢止数日。忽然气攻。胸脘板痛。上下不通。几乎发厥。及至大便稍通。板痛递减。匝月以来。大便仅通三次。今又不通十余日矣。而其脘中之板痛者。结而成块。偏于右部。是脾之积也。脉极细而沉紧。面色晦滞。阳气郁伏。浊阴凝聚。当与温通。", "10856": "再诊大便已通。脘腹之块未化。脉象沉弦而紧。面色之晦滞已明。阳光一𪾢。阴凝渐通之象。仍以温通。", "10857": "脉迟细。脘中有块。纳食撑胀。腹中漉漉有声。嗳腐吞酸。大便坚结。此脾胃有寒积也。当以温药下之。仿温脾法。", "10858": "脉右关滑动。舌苔黄白而腻。是痰积在中焦也。左关弦搏。肝木气旺。故左肋斜至脐下。有梗一条。按之觉硬。乃肝气入络所致。尺寸脉俱微缓。泄痢一载。气血两亏。补之无益。攻之不可。而病根终莫能拔。病根者何。痰积湿热肝气也。夫湿热痰积。须藉元气。以运之外出。洁古所谓、养正积自除。脾胃健。则湿热自化。原指久病而言。此病不为不久。攻消克伐。何敢妄施。兹择性味不猛。而能通能化者、用之。", "10859": "风湿相搏。一身悉肿。咽痛发热。咳而脉浮。拟越婢法。", "10860": "痢后阳虚。水湿不化。腹满面浮足肿。而色青黄。脉细。虑延鼓胀重症。拟温通脾肾之阳。疏利决渎之气。冀其胀消肿退为妙。", "10861": "病由肝郁。木横克土。湿热不化。先有淋浊。愈后。渐渐腹胀。左胁微觉隐痛。身微有热。脉象细弦。木郁不达。虑延鼓胀。勿轻视之。", "10862": "气郁于胸为膈。气滞于腹为鼓。饮食不纳。形肉顿瘦。阴气凝聚。阳气汨没。脉细如丝。将何疗治。姑与扶正培土。通阳化气为法。", "10863": "痞块、由大疟日久而结。多因水饮痰涎。与气相搏而成。久则块散腹满。变为臌胀。所谓癖散成臌也。脉细如丝。重按至骨。乃见弦象。是肝木乘脾也。口干。小便短少。是湿热不运也。匝月腹日加大。急宜疏通水道。泄木和中。", "10864": "暑湿挟积。阻滞肠胃。中州不运。大腹骤满。腹中时痛。痛则大便黏腻。色红似痢。小水短少。诊脉沉而滑数。是积之征也。拟大橘皮汤。送下木香槟榔丸。", "10865": "诒按（此养阴柔肝之正法。与前人复脉、定风、阿胶鸡黄、等法。用意相合。）", "10866": "少阴肾水不足。阳明胃火有余。牙宣出血。晡时微寒壮热。而其脉极细。此素体之阴亏也。当凭症论治。用景岳玉女煎。", "10867": "诒按（此症之脉细。想系素禀如是。若云阴虚。未必脉细也。总之、须见症确有可据。乃可舍脉从症。未可冒昧以将事也。）", "10868": "暑雨潮湿。湿从下受。入于经络。两足腿股酸楚。不能屈伸。起卧转侧。均觉艰难。此属脚气。适值经行之际。少腹窒塞。小便涩痛。湿热自气伤营。故舌苔白而底绛。脉形濡。身微寒热。虑其有气逆冲胸之变。拟东垣防己饮加减。", "10869": "左尺极细。寸关微而似数。右三部俱弦滑。下有遗精暗疾。肛门痒而出水。上则头眩耳鸣。舌苔粉白。以脉合症。肾阴下亏。而湿热相火。下淫上混。清窍为之蒙闭。法当补肾之阴。以清相火。清金和胃。分利膀胱。以化湿热。", "10870": "肾虚精关不固。湿热混于坎宫。精从溺后而出。左脉虚细。右脉洪大。阴亏而相火胜也。补肾阴化湿热。用凉八味法。", "10871": "原注（此病嫌其两脉虚濡。脾胃元气大弱。似乎宜参入扶正为善。然下痢一症。古称滞下。起于湿热居多。早补早敛。往往受累。此河间苦辛宣通府滞之法。所以为痢门必采之方。若夫深刻工夫。补阴补阳。治脾治肾。都为久痢而设。尚非此时议论。所以宁落轻浅。不用深重之剂。盖行远自迩之意云尔。）", "10872": "脉经云、代则气衰。细则气少。多指阳气而言。今下痢而得是脉。脾肾之阳微特著。况形衰畏冷。而小便清长乎。惟下痢赤者、属血分。腹中痛者、为有积。立方当从此设想。盖寻其罅。而通之、补之亦治病之巧机也。", "10873": "便痢白腻。如水晶鱼脑色。小便不利。少腹偏右板窒。诸医以为肠痈。固亦近是。然考肠痈为病。有寒有热。金匮并出二方。如大黄牡丹汤。薏仁附子败酱散。概可见矣。此症则属寒积。试观脉弦紧而不数。面色青而不渴。是其征也。鄙意宜用温通备候商订。", "10874": "休息下痢。延及半载。色红而黏。脉弦。是风邪久羁于肠藏营分之中。而莫能出。近日畏风身热。是又感新风于外也。补中升阳。兼凉血为法。", "10875": "红痢匝月。仍然腹痛后重。据云、先曾发疟三次。此属中虚。表邪传里。现今脉细肢寒。中焦阳气已弱。小便艰难。膀胱气化又钝。拟连理、兼化其湿热。柴苓、以解其表邪。是亦表里两解之法也。", "10876": "再诊痢减。腹中犹痛。肝胃不和也。现值经来。脉弦寒热。血虚木郁。拟以养血疏肝。", "10877": "便血肠燥。脉大气虚。补气。则清阳自升。清阳。则便血自止。", "10878": "肠痔脱肛便血。其根已久。有时举发。而脉象细数。营阴大伤。面黄少神。脾气大困。兼之腹中鸣响。脾阳且不运矣。一切苦寒止血之药。非惟少效。抑恐碍脾。拟东垣黑地黄丸法。", "10879": "多年湿毒。左足前臁腐烂。今则膝骨臀股。上及缺盆。疼痛而木肿。此湿得热而蔓延。循经窜络。病在阳明。名湿毒流注。口苦带腻。脉缓而小。湿胜于热。热伏湿中。仿防己饮法。", "10880": "痰疬二载。自颈延胁。或已溃。或未溃。或溃而不敛。或他处续生。累累然如贯珠。如叠石。溃后色黑而脓稀。外软而内坚。诊脉不甚虚。饮食尚可。细询病由气郁而起。郁则肝胆三焦之火。循经上走于络。结成疬核。小则为疬。大则为痰。收功非易。必放开胸襟。旷观物理乃佳。", "10881": "诒按（此病亦与失营症相类。幸脉实能纳。故用药专从痰火著想。）", "10882": "诒按（方以六味滋肾。生脉保肺。合柴、芍、以清肝。立方周到熨帖。愚意拟去温肝之萸肉。再加清胆之菇、芩。）", "10883": "三诊脉轻按虚微。是为元气之虚。重按细数。是属营阴之损。左尺细弱。肾水亏也。历诊病情。每遇经来。其热辄甚。舌止即布白苔。良以胃中湿浊。因里热熏蒸而上泛也。少腹有块攻痛。聚散无常。是名为瘕。瘕属无形之气。隶乎肝肾为多。揆其致病之由。因目疾过服苦寒。戕伐生生之气。胃受寒、则阳气郁而生湿。肝受寒、则阴气凝而结瘕。阳气郁于胸中。故内热。阴气凝于下焦。故腹痛。经事过。则血去而阴虚。故其热甚。甚则蒸湿上泛。故舌苔浊厚也。刻下将交夏令。火旺水衰。火旺、则元气耗而不支。水衰、则营阴涸而失守。惟恐增剧耳。图治之法。补脾胃以振元气。培肝肾以养营阴。是治其本也。稍佐辛温。宣通下焦阴气。是兼治其瘕痛之标也。", "10884": "再诊血虚木横。两胁气撑胀痛。腹中有块。心荡而寒热。病根日久。损及奇经。经云、冲脉为病。逆气里急。任脉为病。男疝女瘕。阳维为病。苦寒热。阴维为病。苦心痛。合而参之。谓非奇经之病乎。调之不易。", "10885": "诒按（古无专属奇经之病。亦无专入奇经之药。考内经、八脉行度。及前贤议论。均谓十二经气血有余。则溢入奇经。有病者、亦必日久病深。由正经而侵入之。然则用药治病。自当仍以正经为主。学者须明此意。勿为近贤议论所蒙也。）", "10886": "内热日久。经停两月。投养阴调血通经之剂。得热减经行。可谓效矣。然犹未也。脉数不和。舌仍光赤。乃阴津未充。虚阳未敛也。仍宜小心安养为善。", "10887": "再诊脉数已和。舌色光红已退。但有时尚觉微热。仍以前法增损。", "10888": "忧愁抑郁。耗损心脾之营。而肝木僭逆。胸中气塞。内热夜甚。经事两月不来。脉沉而数。热伏营血之中。拟用柴胡四物汤。和营血以舒木郁。", "10889": "经后。少腹痛连腰股。肛门气坠。大便不通。小便赤涩。拟泄肝经之郁热。通络脉之凝涩。", "10890": "年将五十。经事频来且多。是冲脉不司收摄故也。防其崩决。补之摄之。", "10891": "两次血崩之后。赤带连绵不断。迄今半载有余。脉象虚微。气血大亏。是以头眩、心跳。腰酸、足软、等症均见也。近日腹痛食减。恐其复致崩决。拟方固摄奇经。", "10892": "咳嗽发热日久。前投补益脾胃之药。六七剂。食谷加增。起居略健。但热势、每交寅卯而盛。乃少阳旺时也。少阳属胆。与肝相为表里。肝胆有郁热。戕伐生生之气。肺金失其清肃。脾胃失其转输。相火日益炽。阴津日益涸。燎原之势不至涸极不止也。其脉弦数者。肝胆郁热之候也。刻下初交夏令。趁其胃旺加餐。拟进酸苦法。益阴和阳。清澈肝胆之郁热。考古方柴前连梅煎。颇有深意。录出备正。", "10893": "寒气客于下焦。瘀凝停于少腹。阻塞胞门。膀胱阳气失化。以致癃闭。产后八日。而小便不通。脉细肢寒。腹中觉冷。恐其气逆。上攻发厥。法以温通下焦。化瘀利水。冀其应手为妙。", "10894": "前年小产。恶露数日即止。因而腹痛结块。心神妄乱。言语如颠。此所谓、血风病也。胞络下连血海。上系心胞。血凝动火。火炽生风。故见诸症。诊脉弦搏。肝阳有上亢之象。防加吐血。治法当以化瘀为先。稍佐清火。可也。", "10895": "体气素亏。频年屡患咳嗽。今春产后悲伤。咳嗽复作。背寒内热。气逆痰多。脉虚数。大便溏。延今百日。病成蓐劳。按产后血舍空虚。八脉之气。先伤于下。加以悲衰伤肺。咳嗽剧发。震动冲脉之气上逆。经云、冲脉为病。逆气里急。阳维为病。苦寒热。频进疏风清热。脾胃再伤。以致腹痛便溏。食减无味。斯皆见咳治咳之弊。越人谓上损及脾。下损及胃。俱属难治。姑拟通补奇经。镇摄冲脉。复入扶脾理肺。未能免俗。聊复尔尔。", "10896": "乳房属胃。乳汁血之所化。无孩子而乳房膨胀。亦下乳汁。此非血之有余。乃不循其道。以下归冲脉。而为月水。反随肝气。上入乳房。变为乳汁。事出反常。非细故矣。夫血、犹水也。气、犹风也。血随气行。如水为风激。而作波澜也。然则顺其气。清其火。熄其风。而使之下行。如风回波转。可也。正何必参堵截之法。涩其源而止其流哉。噫。可为知者道。难与俗人言也。", "10897": "再诊疟痢三年。脾胃元气大伤。脉数舌红。腹满足肿。小泄短少。前投升阳益胃。热势略减。今拟补益脾阴。兼以化浊。然童稚阴亏。病延日久。夏令防其增剧。", "10898": "诒按（小儿虚症。自以后天脾胃为主。然脉数舌红。阴液亦损。亦当稍参养阴之意。）", "10899": "病经匝月。表热解后。杳不思纳。脉静舌净。神倦言懒。既无外感留恋。又非老景颓唐。睛光流动。面色开旷。问所服之药。苦寒沉降者。多矣。谅系胃气为药所困。非病也。亦非衰也。且进和中醒中。以悦脾胃。令其纳谷乃昌。", "10900": "再诊胃气乍醒。脉形软弱。久饥之后。脏腑之气尚微。纳谷以匀为稳。至于用药。尚利轻灵。须俟胃气日隆。方可峻补。盖凡投补剂。必藉胃气敷布故也。经云、百病以胃气为本。又云、安谷则昌。其斯之谓欤。", "10901": "竟日悲思。半载纳减。询非恼怒感触所致。在病人亦不知悲从何来。一若放声号泣。乃能爽快。睡醒之际特甚。余如默坐亦然。韩昌黎云。凡人之歌也有思。哭也有怀。出于口而为声者。其皆有不平者乎。夫悲哀属肺。寝则气窒。醒则流通。想其乍醒之际。应通而犹窒焉。是以特甚。揆之脉象。右寸细数而小滑。伏火挟痰有诸。或更有所惊恐。惊则气结。结则成痹。痹则升降失常。出纳呆钝。胃气所以日馁耳。拟以开结通痹为先。毋急急于补也。", "10902": "再诊两进开结通痹之后。悲哀之态顿释。咯痰黄厚。胃纳稍思。脉之滑数亦缓。其为痰火痹结也。明矣。拟以清泄通降继之。补不可投。岂妄谈哉。", "10903": "眩晕多年。每发于湿蒸之令。今年初夏。潮湿过重。发亦频频。诊脉濡细。舌苔腻白。考古法、眩晕一症。概从内经诸风掉眩。皆属于肝之论。大旨不外乎风阳上旋。更辨别挟火挟痰以治之。今按脉症。乃湿郁上泛。挟浊痰腻膈所致。因前人未经论及。而临症、亦罕见也。拟辛香运中。以化湿化痰主之。", "10904": "再诊眩晕不复作。舌白依然。脉濡便溏。脘中较爽。信系体肥多湿。嗜酒多湿。卧于地坑之上。亦感湿。好饮冷茶。亦停湿。倘泥于古法。而投滋降。不亦远乎。再拟昨方加减。仍守太阴阳明主治。", "10905": "形凛汗渍。脉濡神糊。舌如傅粉。沉睡痰迷。素系嗜酒之体。湿痰弥漫。蒙遏清阳。扰乱神明所致非陷也。亦非闭也。慎勿开泄。拟达原饮意。", "10906": "再诊汗渍已收。神志转清。药后呕痰盈碗。呕出渐醒。脉犹濡细。舌苔白腻弥漫之势虽除。尚宜燥湿祛痰。从太阴阳明主治。", "10907": "鼻衄盛发。成流不止者。已三日。面赤。足冷至膝。脉数。寸关尤甚。血去过多。心荡神驰。阴亏内热之体。厥阳化火上逆。扰动脉络。血行清道。从高灌注而下。非若吐红之易定。血有几何。岂堪如此长流。拟仿志火升腾治例。用凉血滋降法。", "10908": "再诊鼻衄虽止。而面色唇口㿠白。虚阳虽降。而额汗心悸畏明。脉虚而数。舌光而颤。气乏血涵。血无气护。阴阳有离脱之象。气血有涣散之险。急进双补法。庶几有所依附。再佐咸降酸收以摄之。", "10909": "恼怒伤肝。木火犯胃入膈。支撑胸背。呕吐血块痰涎。不纳不便。舌白苔腻。胃为水谷之海。多气多血之府。性喜通降。所畏倒逆。经此气火冲激。湿浊乘机错乱。倘肆其猖狂。厥势立至。若再侮脾土。胀满必增。左脉弦硬。右脉细软。谷不沾唇者。已五日。胃气惫矣。而呕尚甚。中无砥柱。何恃而不恐。诸先生所进苦寒沉降。盖欲止其呕。而顺其气。诚是理也。然内经云。百病皆以胃气为本。苦寒性味。又属伐胃。胃不能安。药力何藉。拙拟苦寒以制肝之逆。苦辛以通胃之阳。而必参以奠安中气。庶几倒逆之势得缓。幸勿拘于见血畏温之议。", "10910": "再诊呕逆已止。胀痛亦缓。左脉弦硬固平。右脉歇止渐见。土德大残。中气亦竭。急进补中立中。仍参约脾制肝之法。惟望胃纳能醒、是幸。", "10911": "三诊胀痛大减。呕逆未平。稍能纳粥。脉俱濡细。胃气渐有来复之机。经云、纳谷则昌。信不诬也。", "10912": "得食则呕。已延月余。形神疲乏。宛如膈症。听其言。观其人。惟知明而动。晦而休。务农无怠者流。诊左关脉数。右关细软。舌白口苦。寒热往来。汗之有无。病者不知。盖少阳见症。原有呕恶。揆其病情。是任其呕逆。以致反胃厌谷。胃气日逆。似乎噎膈。实由邪蕴于少阳一经。胃被邪克。气不通达。据是脉症。宜先泄少阳之邪为要。拟小柴胡法。佐以辛通。", "10913": "再诊前方嘱服两剂。据述服后。壮热大汗。湿透衣被。即思纳粥。因其效验。连服一剂。今已吃饭。惟力不充耳。诊其脉。左关已软。右脉尚细。续与和中。", "10914": "发热恶寒。头项强痛。无汗胸痞。脉浮紧细。症属正伤寒。南方所罕见。询系连朝营墓辛勤。届在严寒。又居旷野。太阳表症悉具。宗仲圣不汗出而烦躁者。大青龙汤主之。", "10915": "三诊汗畅热解。烦躁已除。脉转细小。形疲体酸嗜卧。而思纳谷矣。其发也凶悍。其传也迅速。其退也亦易易。究属质弱者。易感易达。不若北方风气刚劲。禀赋厚而腠理实。必至传遍六经乃已。是症若宗三时六气治之。势必淹缠几候耳。拟和营卫法。", "10916": "表热九日。有汗不解。舌绛起刺。烦渴引饮。间作寒战之象。热甚下午。至夜。神志时糊。脉洪无力。阳明经分之邪。又传少阳。阳明府分之滞。灼伤津液。极似大柴胡症。而与脉情不符。细绎病情。正虚津竭。既非陷里之神糊。如何香开。致使内传。欲其府滞能通。必俟津回液复。拟宗仲圣人参白虎汤意。参入景岳柴胡煎。庶与脉症符合。诸先生以为何如。", "10917": "再诊汗热烦渴已减。舌绛淡而尖刺已少。津液稍回。正气较振。脉数未平。神志已爽。少阳阳明之表分既清既泄。而府分之滞。尚待清润育阴而下也。切勿因滞而遽投荡涤。审症二字。其难其慎。临时应变。平日之工夫也。", "10918": "表热四候。额汗如淋。汗时肤冷。汗收热灼。消滞泄邪。清补诸法。已遍尝矣。诊脉虚细。惟尺独滑。舌苔已净。胃纳稍思。细绎脉症。病邪不在三阳。而在三阴。考仲圣有反发热一条。是寒邪深伏少阴之阳分。今乃湿温余邪。流入少阴之阴分。良由少年肾气不藏所致。治当宗其旨。变其法。拟补肾阴。泄肾邪。一举两得。庶可许热解汗收。", "10919": "再诊热解已净。自汗亦收。脉滑已和。纯乎软弱。神情向倦。而虚象旋著。拟转用补养。", "10920": "壮热神糊。陡然而发。脉数大。而混糊无序。舌垢腻。而层叠厚布。矢气频转。小溲自遗。脘腹痞硬。气粗痰鸣。既非寻常六气所感。亦非真中类中之症。观其濈濈自汗。汗热而不黏指。转侧自如。四体无强直之态。舌能伸缩。断非中风。设使外感。何至一发便剧。而安能自汗。倘守伤寒先表后里。下不嫌迟之例。是坐待其毙矣。亦曾读吴又可先里后表。急下存阴之论否。盖是症也。一见蓝癍。则胃已烂。而包络已陷。迅速异常。盍早议下。尚可侥幸。诸同学以为然否。", "10921": "再诊神志得清。表热自汗。腹犹拒按。矢气尚频。便下黏腻。极秽者未畅。小水点滴如油。脉数略有次序。舌苔层布垢浊。胃中秽浊蒸蕴之势。尚形燔灼。必须再下。俟里滞渐楚。然后退就于表。吴又可治疫之论。阐发前人所未备。甚至有三四下。而后退走表分者。若作寻常发热论治。岂不谬乎。", "10922": "三诊大腑畅通。悉是如酱如饴极秽之物。腹已软而神已爽。表热壮而汗反艰。舌苔半化。脉数较缓。渴喜热饮。小水稍多。此际腑中之蒸变乍平。病已退出表分。当从表分疏通。先里后表之论。信不诬也。", "10923": "四诊表热随汗就和。舌苔又化一层。脉转细矣。神亦倦矣。病去正虚之际。当主以和养中气。佐轻泄以涤余热。守糜粥以俟胃醒。慎勿以虚而早投补剂。补之则反复立至也。", "10924": "间疟止后复发。发不归期。或二三日。或七八日。发则寒战热甚。两三月如此。从无汗泄。脉沉而细。形瘦骨立。胃纳式微。症由久疟伤阴。阴损不复。其为劳疟显然。现届夏令。已得可汗之时。且服存阴泄邪。以冀汗泄于表。阴复于里。转准疟期。庶有畔岸可依。拟少阳少阴并治。", "10925": "再诊药四服而值疟来。寒战依然。热势转短。热退时。汗已畅达。脉沉转出。神气觉爽。而食物有味。察其转轻之象。皆从汗后。究由外感。乘虚蕴伏。愈伏愈深。延为怯象。兹有向外泄化之机。仍宗前议加减。必得转为间疟乃安。", "10926": "三诊疟准日作。解后有汗。寒热之势大减矣。脉形细小。舌不生苔。久疟阴伤。复其阴可耳。症属转机。已得坦途。凡腥膻鲜发。以及麦食等。均须慎禁。拟清养法。参以泄化。", "10927": "瘅症多种。黑者属肾。肾气过损者。曰、女劳黑瘅。今肌肤舌质尽黑。手指映日俱黯。强壮之年。肾阳早已不举。体虽丰腴。腰软不耐久坐。脉弱神疲。纳减足冷。显属肾脏伤残太甚。尚谓北路风霜所致乎。昔有人患此。遍处医治。皆曰、风毒。后遇顾西畴。道破症名。宗湿热流入肾经主治。试以此症较之。症虽同而虚实又异矣。现届深冬。姑先治本。需春暖阳和。再商他法。", "10928": "三诊肤色花斑。症转阴黄。较之黑瘅。浅一层矣。培植脾肾之药。已进四十余剂。形神色脉。俱属平善。节令将交惊蛰。春暖之气已和。治当开泄腠理。以涤肤斑。内经云、必先岁气。毋伐天和。易曰、待时而动。何不利之有。拟宗仲圣茵陈四逆法加减。三剂即停。接服丸药可耳。黑色退尽之时。当在夏初。", "10929": "脾肾之阳素亏。醉饱之日偏多。腹痛拒按。自汗如雨。大便三日未行。舌垢腻。脉沉实。湿痰食滞。团结于内。非下不通。而涉及阳虚之体。又非温不动。许学士温下之法。原从仲圣大实痛之例化出。今当宗之。", "10930": "再诊大府畅行。痛止汗收。神思倦而脉转虚细。拟养胃和中。", "10931": "旬日内。遍体俱肿。肤色鲜明。始也、原有身热。不慎风。而即止。亦无汗泄。诊脉浮紧。气喘促。小便闭。舌白。不思饮症系水湿之邪。藉风气而鼓行经隧。是以最捷。倘喘甚气塞。亦属至危之道。治当以开鬼门。洁净府为要著。", "10932": "腹痛下痢。昼夜无度。汗冷肢冷。脉细舌白。暑湿热挟滞互结。病经五日不减。嗜酒中虚之体。邪不能化热外达。而见多汗伤阳。多痢伤阴之险。凡里急后重腹痛者。治法宜通。口燥烦躁溲秘者。又当清渗。此症中阳先馁。不能托化。邪滞未动。虚波已至。诚属棘手。姑拟温清并进。宗泻心汤意。参以疏邪化滞。若正气保和之类。何足恃耶。", "10933": "再诊下痢减半。赤白相杂。肢冷较和。汗亦稀少。舌白苔腻不化。里急后重已缓。诊脉沉细。腹中犹痛。究属中虚湿胜。暑积阻结。不能藉阳和运动。尚非坦途。再拟温中运邪一法。", "10934": "三疹。痢下大减。舌苔渐化。腹痛除而宿垢亦通。小溲赤而两三度。脉象起矣。谷食思矣。中阳既得运动。无虑邪滞不化也。尚当和中。", "10935": "三诊血下缓而大减。脉微神倦。气阴并乏矣。堵塞存阴之药。尚不可撤。拟就昨方加立中意。", "10936": "再诊通络化痰。理气开郁之方。已投七服。左项痰核软而可推。余络未窜。脉仍弦数。大便五日不行。内火犹炽。再议化痰通络之法。", "10937": "三诊前方五服。痰核已消三粒。所剩四粒。亦软而小。其势不至四窜矣。脉弦小软。大便已畅。再拟消痰。以冀速除。然方药虽效。亦半藉怡养工夫耳。", "10938": "经停三月。骤然崩冲。阅五月而又若漏卮。询系暴崩属虚。虚阳无附。额汗头震。闻声惊惕。多语神烦。脉微虚软。势将二气脱离。其危至速。拟回阳摄阴法。急安其气血。", "10939": "再诊脱象既除。经漏较稀。脉犹濡细。神思尚怯。气血乍得依附。再宗暴崩属虚之例。拟温补法。", "10940": "（案4）久痢脾肾两亏，复感新凉转为三阴疟疾。两脉弦细，拟合和解扶正法治之，速解乃吉。", "10941": "（案3）经停三月，怀孕未定。痢经月余，正气固虚，胃阴亦伤。口干舌赤，胸闷哕逆，谷食懒进，脉象空虚无神，虑增昏呃歧变。拟方以尽人力。", "10942": "（案7）痢经月余，阴阳二气俱伤。肛坠无休，腰胯酸痛，肢末时而厥冷，哕逆自汗，舌苔干白，谷食懒进，两脉按之无力。虑难骤效，兹拟参附六君子汤，多酌高明可也。", "10943": "（案15）暑湿下痢，红多白少，腹痛后重，两脉数大。仍宜清利治之。", "10944": "（案2）积湿成饮，积饮成痰。痰饮伏于肺胃，兼之火不生土，致五更泻利，脉象弦滑。拟姜附六君加味治之，仍须安闲静养为先。", "10945": "（案3）肝肾素亏，加之肠澼日久，中土亦虚。致饮食减于过半，虽纳亦属不运。胸脘腹闷，每利必带红水，脐腹㽲痛。营卫亦虚，此时乍寒乍热，左脉弦，右脉濡，虑有土败木贼之虞。", "10946": "（案1）由立秋湿热蕴于肠胃，日久未解，致成肠风。询血或紫或鲜，不分粪之前后。腹不痛，肛不坠，关脉滑数，仍当清理。必须慎口避风，方免肿胀歧变。", "10947": "（案4）素本体虚，又兼气虚肛坠，宿饮射肺，咳逆气喘。加以肝木侮土，火不生土，胃强脾弱，能容而不能运，甚则大便不实。湿热下注，酿成翻花痔，漏血射如箭，盈碗盈盂，流至脚跟而不知，气不摄血也。两腿酸软，间或抽搐者，乃血不荣筋，肌肤痿黄，曾经浮肿，舌中苔黄，脉象弦沉而细。总之，阴阳交虚而阳虚特甚，久则防成肿胀。", "10948": "（案1）嗜酒伤中，肝胆湿热下移膀胱，致成痛淋，已延十余年之久，时作时止，小便秘结，脉象弦细而滑。防成血淋。", "10949": "（案3）某翁大人阁下：昨接手书并厚仪一函，愧领，谢谢！展阅贵恙情形，其原责在水虚，是以木失涵养，火无所制，幻出诸症。兹以原方加以育阴潜阳之品，再服一料，雨水前后，该可服完。静候玉音。抑或枉临敝舍，脉症相参为盼。肃此敬复，即颂大安，惟望雅鉴。", "10950": "（案1）肺经湿热内蕴，致咳脓痰，色红味腥，胸胁隐痛，右脉濡数，虑成肺痈。", "10951": "（案2）风伤皮毛，热伤血脉，渐积成脓，酿成肺痈大证。脉象数实，身热自汗，谷食少进。人虚证实，调治殊难，姑拟一方，获效乃吉。", "10952": "（案3）由风温犯肺，郁而化热，致伤脉络，咳吐臭痰，脉象滑数。肺痈已溃，难以挽回，拟方以尽人力。", "10953": "（案4）客冬肺痈，未能收口，以致咳嗽至今未止。间有吐瘀，寒热往来，梦寐不安，善性多疑，天癸渐少，脉象虚数，气短汗少，再延防成肺痈。", "10954": "（案5）咳嗽起于春季，时发时止。入秋来操劳愤郁，兼之燥气内侵，咳嗽日重，涎沫频来。近日津液内竭，咳吐脓痰，声哑咽痛，骨中烧热，肌肉消瘦，两脉细数，肺痿之势已露。兹拟喻氏法，多酌高明可也。", "10955": "（案6）肝邪入肺，咳久化热，右胁痹痛，痰中带血，脉象滑数，虑其成痿。", "10956": "（案1）自幼多惊，十龄外多病，近或痫症又三四载矣。痫者发之有间断也，平时痰涎则藏于肝胆，故善性多疑也。发则犯于心包，故神呆痉厥也，上凌肺胃则吐涎沫血水也，脉象弦细而滑。今岁新婚则发之愈紧，肝肾乙癸同源也。拟方徐图之。", "10957": "（案2）喉痛宜凉，腹痛宜温。症当多歧，情同水火，兼有惊痫痉厥，数日一作，或一日一作，脉象弦细，拟方兼顾之。", "10958": "（案3）抑郁惊恐，肝胆受伤，致成痫症，已延多年，脉象弦滑。速当自开怀抱，尚可与药饵兼功。", "10959": "（案4）由惊恐而成痉厥八九载之久，肝胆痰热已深，稍有悒郁则风火并起，斯时人事不省，气阻痰壅，手足抽搐，口角流涎，良久方苏。询癸水先期而至，脉象弦滑。药难霍然，徐图可也。", "10960": "服前方惊痫未作，哕吐未来，营卫渐次向和，脉象弦缓。从此小心慎口，自可渐入佳境。", "10961": "（案8）郁怒伤肝，肝气郁则热自内生，胆府亦失其清净。目前化热皆厥，心志不灵，言语间有失序，身热渐作，舌黄尖绛，两脉滑数。速当安闲开怀，方免痰热互胶致生歧变。", "10962": "（案9）早年痫厥已止，从夏季操劳郁怒太过，致肝气直犯心包。斯时气阻喉间，不容升降，心中嘈杂，莫名其状，脉象弦滑。肝胆痰热内闭之征，犹恐痫厥乘举，致生歧变。", "10963": "（案1）风中血脉，右肢不遂，舌苔白腻，素多湿痰，致内风鼓动，脉象弦滑。速当戒怒远烦，庶得与药饵兼功。", "10964": "（案3）头晕手麻舌强，皆由气血不足。已现风痰之象，叠进温补之剂，头眩渐清，舌强亦和，惟手足麻木乃湿痰瘀血凝结筋络之间。时或神识不清，此湿痰流于心包，致心志模糊，右脉滑数，痰生热也，左脉浮大，热生风也。法宜水火两补，使火归水中，则水能涵木，自不生风。《经》又云，治痰先理气，气顺痰自消；治风先养血，血行风自灭。庶不致竞成类中也。", "10965": "（案4）肝肾素亏，多湿多痰之体。从春间风中于阳明脉络，致口眼歪斜，偏于面右，牵及肢末作麻，入冬面皮强急，口眼虽解，湿痰犹存。速当绝去尘氛，一毫私念莫起，佐之以药，庶免仆中歧变。", "10966": "（案5）阳明脉虚，周身脉络不和。更加肺受风邪，气痰内郁，一身之气更为不利。兹拟宣肺和络治之。", "10967": "（案7）内风鼓动，痰凝经络，右边肢末麻痹，头眩心悸，神识不安，两脉弦滑，有偏枯之患。", "10968": "（案1）忧虑烦劳太过，正气为风寒湿三气所乘，脑后痛入骨，欲按为虚，邪在为实。脉象弦数少神，有转痈疽之虑，扶正却邪为主。", "10969": "（案3）操劳太过，清阳致虚。暑湿风邪上混头元，郁而生热，脉象浮濡而数，舌苔黄而且腻。拟青空法增味，速解，可免昏厥之变。", "10970": "（案5）痰热扰乱，肝阳化风，心悸头眩，不能自主，神思恍惚，嘈杂易饥，脉象弦滑。上虚下实，有类中之渐，现值夏至大节，加意提防为要。", "10971": "（案6）郁损肝阴，化火生风，致气逆阻，头眩面热，愈逆愈眩。脉来强数，筋脉酸胀，亦由血不养肝，肝主筋也。拟和阳熄风为要。", "10972": "（案8）肝郁夹痰，生火生风，致左胁肝垂内煽，头眩目眩，乍寒乍热，肢末作麻，气逆吐沫，脉象弦滑，虑其昏厥。", "10973": "（案9）木火体质，善怒多郁。肝气易升，肝阳亦失其清净，致头目眩，心悸作烦，手足蠕动，两脉弦滑而数，心脉较大。须戒怒远烦，免酿痰歧变。", "10974": "（案1）肝肾两亏，夹湿夹痰之体，加以馆课劳心，营分暗耗。营主血，血不荣于筋脉，致左边肢体酸软无力，手足不耐久用。咳吐痰涎，头目时眩，左耳时轰。年过五旬，久则虑其仆中。兹仿络热则痿，拟虎潜法以消息之。", "10975": "（案2）操劳太过，血水内泛，致寒湿入于脉络，成为筋痹，延及日久，卫营失和。近来手指筋强而肿，伸屈似属不利，药难霍然，徐图可也。", "10976": "（案6）暑湿伏邪，内郁致成周痹。身热不寒，偏身筋脉酸痛，难以转侧，舌白口苦，入暮热重，神昏谵语，势属重候，虑其昏陷生变。", "10977": "始由木乘土位，久则火不生土，谷食不运，嘈杂嗳气频仍，延及二年之久，时作时止，脉象沉弦而细，较前稍平。此证缓图当可就绪，倘再反复，嘈杂即行，深虑愈作愈深，有反胃之患。果能破疑，见王道无功，多服自有效也。", "10978": "（案2）产育后阴亏未复，加以操劳恚怒，风伤内扰。胃阴内耗，脘中嘈杂，易食易饥，若饮食失节，则火生面热，关脉数急。已入中消之势，速当安闲静养，庶可挽回。", "10979": "（案3）肝胆不和，心肾不交，阳明脉虚。郁痰内扰，心神恍惚，善食易饥，善性多疑，肉𥆧筋剔，头眩耳鸣，脉象虚弦而滑。延久防成中消。", "10980": "（案1）肝肾乙癸同源，肝脉络于阴器。肝郁不舒，左肾筋高突，右侧睪丸下坠，是属筋疝。肾气虚寒，绕脐作痛，有同源之义，故相困而作也。致肝阳夹饮，上腾清窍，遂令头目不清，时咳凉痰，脉象沉弦而滑。拟方徐图之。", "10981": "（案2）肝虚气滞，癸水不调，或至或不至，来时又暴涌不已。经过带下绵绵，腹痛腰酸，少寐多汗，冲任督带，奇脉交伤。若不安闲调理，恐他日经漏成崩，经闭成蛊。", "10982": "（案3）女以肝为先天，月水全赖肝经条达，方能按期而来。此时肝虚气滞，胸脘为胀为痛，营卫不和，乍寒乍热，腰膂酸楚，脉象弦数。速宜静养调治，再延有损怯之虞。", "10983": "（案8）经频带下，肝脾既失统藏，任带又疏约束，而心落落，头目眩晕，肉𥆧筋剔，左肢麻痹。梦寐不安，其为肝胆内蕴痰热，奇经不和可知，脉象弦滑。症势多歧，用药殊难，拟方候酌。", "10984": "（案10）由去岁产育，赤白带下不止，腰脊酸楚，下焦八脉已伤，虑成损怯。", "10985": "（案11）从产后患伏邪，正阴交伤，下焦空虚未复，致带下无休。冲脉伏寒，加以肝木不主疏泄，脘腹患胀作痛，痛甚则肠鸣便泄，谷食不运，得嗳方舒，脉象虚弦。拟方温通奇脉。", "10986": "（案12）带下如注，方书谓之白崩。八脉交伤，治之不易，徐图可也。", "10987": "（案14）漏久仍防暴行，八脉无权，虑难调治，再拟益气摄阴之剂，得效乃吉。", "10988": "（案1）肝气结瘕，聚于少腹，状如鹅卵。夹冲脉之气上冲，则胸脘胀闷，谷食亦难下顺，脉弦而带滑。虑其浊阴凝互，有单腹胀之虞。", "10989": "（案3）脘中气结成痞，少腹血聚成瘕。从产所致脾伤，肿胀时轻时重，两脉弦涩，虑其增剧生变。", "10990": "（案2）天癸不调，先期而少。血分不足，骨中烧热。气虚带下，懊恼作烦，五心作热，脉象虚数，再延，防成损怯。", "10991": "（案9）胎前咳逆带红，延及产后，阴分大伤，热自内生，五旬未已。新加暑邪身热，大便泄泻。刻下邪少虚多，正气亦伤，脾土亦亏，脉象细数无神。虑由暑盛而成损怯。", "10992": "（案10）头眩耳鸣，心摇如悬，惊恐忧惧，多疑善虑，多食善饥，两脉虚弦而滑。均由产后致虚，真阴未复，肝阳化风，脾湿化饮，证情迭出，变幻无常，拟方缓图之。", "10993": "（案2）热入血室，身反不热，神志不清，脉象弦数，舌白口苦。兹拟仲圣法，即提所陷之邪，谨防昏痉暴变。", "10994": "（案3）内热未尽退，癸水适至。热入血室，神志模糊，面赤谵语，入夜尤甚。中焦结痞拒痛，口苦而渴，舌干白，苔淡黄，大便秘结，尿赤脉数。殊属险候，谨防昏厥暴变。", "10995": "（案1）喉疳日久，内外求治，皆无效验。予亦非专科，兹诊左右寸关脉数，显见心脾积热，从辛苦劳力而来。拟黄连凉膈法清之，另用珠黄散掺之，以观进退。", "10996": "（案1）温邪表尚未解，平素积劳伏火，因表沸腾，致舌本破烂，口干作臭，身热脉数。拟辛凉开泄法获效乃吉。", "10997": "（案2）肝旺胆怯，脾虚胃强，阴分固伤，阳气尤甚。于是两腿浮肿，腰下亦然，脘中懊𢙐，莫名其状，舌亦无苔，干而且痛，大便不实，形气消索，脉象沉细无神。其水溢高原，致生枝节，暂拟水火既济法，以冀舌和为妙。", "10998": "（案1）素本肝肾不足，自客秋肝郁不舒，两乳结核。辰下右乳虽消，左乳起于二月，脉象弦细且滑。速当自开怀抱，庶可与药饵兼功。", "10999": "（案1）脑漏多年，仍辛苦劳碌，风寒乘虚而入骨空。头元偏痛，筋脉牵掣不利，鼻窍渗涕较甚，清阳不升，湿浊愈重。近来舌本强硬，精神疲困，谷食减纳，舌苔腐腻，脉象浮虚。浮则为风，虚则气虚，能于安闲慎风邪，冀其永年而已。", "11000": "（案1）素本水不涵木，肝火过旺，加以外风触动，遂致右目红瘀，白翳已满黑睛似鱼胞。右头角及眉棱皆痛，不能安卧，脉象弦数，口中作苦。拟方先望头痛速止，可保无虞。", "11001": "（案1）癖积日久，现因劳过盛而发，致寒热往来，两脉弦数，大便秘结。拟大柴胡法，取其解表通里，以冀通则不痛。", "11002": "（案2）疟母多年，即《难经》名曰肥气，胸膛已占大半。近来郁怒动肝，络血外溢，去血颇多，营分大亏，致心悸头眩，身倦肤黄，脉象弦涩。拟柔肝和营，仍须戒怒远烦，方免络血复溢。", "11003": "（案1）七情不适，郁勃于内，致肝失调达之性，脾失上升之权。胸脘阻塞，气滞湿凝，脉象弦滑。速宜安闲勿劳，佐以药饵，方见功效。", "11004": "（案2）肝郁夹痰，互凝中焦，致上下不交而痞象成。胀痛并见，须哕吐痰涎或嗳泄方舒，两脉弦滑。倘再操劳郁怒，有中满痰膈之虞。", "11005": "（案3）肝郁日久，气久贯膈冲喉，加之湿痰凝互，项间瘰如串珠，气火复化风上扰，阳明脉络皆为不利。兹当清肝平风，佐理湿痰。但恙情从志内伤而起，非旦夕可图功效。尤当戒怒远烦为宜。", "11006": "（案5）脾土不足，肝木乘之。致胸脘胀闷，胸中时而热炽，寒热往来，两脉虚弦。拟逍遥散加味，所谓木郁达之。", "11007": "（案1）肝木侮土，支饮入络，左胁痹痛，脘腹膨胀，面色痿黄，谷食少进，脉象弦细。再延有土败木贼之虞，拟方徐图，戒怒远烦为要。", "11008": "（案2）火不生土，木来乘之，土湿内困。肝病善痛，脾病善胀，胀痛并见，肝胃不和也。大便间或溏泻，湿气下行，脉象沉弦而滑，怡情善调可愈此疾。", "11009": "（案3）肝气横久，克脾犯胃，胸胀胁痛，脘中聚痞，遇烦劳悒郁则痛，哕吐酸水痰涎，两脉弦滑。必须戒怒远烦，方免阴枯阳结歧变。", "11010": "（案4）操劳郁怒，肝木偏横，克脾犯胃。土受水制，阳明脉虚，致左肩臂脉络酸痛引胁脘，嘈杂时形，得食较安，否则自汗不已，食入又觉胀闷，右脉细濡，左脉弦劲。速宜安闲静养，以免增剧歧变。", "11011": "（案6）血不养肝，肝气横逆，脾土受侮。脘痛作哕，脉象沉细。延及年余，痛久入络。拟柔肝和脾合消瘀法治之。", "11012": "（案1）湿郁化热，袭入奇经，故季腹下及两腿胯渗入大肠，肛门裂痛后坠，苦不可言。胸中懊恼，谷食懒进，烦热熏蒸。前曾赤白带下，味兼腥秽。痛甚肢冷，脉象沉弦。再延防其胃气大伤，致生枝节。", "11013": "（案2）寒湿内伏，腹痛虽稀，寒热不清，舌黄口渴，脉弦自汗。拟乌梅丸为治，速解乃吉。", "11014": "（案6）抑郁伤肝，肝旺克脾，脾虚生湿，湿盛成饮，饮盛成痰。由肝传肺，痰与气凝，右胁作痛，呼吸不利，困倦思眠，气逼不舒，心烦嘈杂，脉象沉滑。书云滑主多痰，沉主多郁，乃属肝旺脾虚之证。温之不能，凉之不可，拟方兼而治之。", "11015": "（案8）操劳恚怒，肝气入肺。左胁痹痛，转侧呼吸皆为不利。寒热往来，但平素烟热酒湿内发，咳痰味腥，脉象浮滑带芤，虑其血涌肺胀暴变。", "11016": "（案13）由淋浊伤肾，肾气不和，内不交于心，外不通于络。凡心烦不寐则腰间作痛，必起坐方适，两脉弦涩。青娥丸合宣络为治。", "11017": "（案15）颓疝较轻，胃逆较平，惟水饮留连奇经，肝肾故乘受饮。刻下痛自腰胯起，痛归关元，上攻则吐，从前年调治，气痛有年余不发。今自夏五月愈发愈甚，逢感必作，阳气愈亏，水饮愈甚，脉象沉滑。拟方以进一筹。", "11018": "（案18）寒邪直中厥阴，少腹作痛，痛满小便不利，入暮则热，神昏谵语，囊缩茎短，两手循摸，胸脘痞硬，舌干苔白口苦，渴不欲饮。病经五日，早晨便溏一次，时加厥逆，两目上视，两手脉象沉迟。势属不治，姑拟四逆法以希万一之致。", "11019": "（案1）肝木横行克土，土虚不能制水，水饮痰热交致于中，悸稍逊而未平，胀前而尤甚，脉滑而弦。肢腿浮肿，已有单腹之虞，再拟一方，以冀挽回。", "11020": "（案3）休息痢三载，脾肺肾交亏。咳逆肿胀，已历百余日，脉象沉弦而涩。水臌已著，难以挽回，拟方以邀天相。", "11021": "（案4）由利而痢，戊病传癸也，不痛而坠是属里虚，白多于红，全在气分。自去秋延及十月，服药全无效验，兹虽不药而愈，究属便溏未止。正月间面浮肢肿，肚腹膨大，漉漉有声，乃水气湿邪未能分泄于小肠，内困脾土，外袭皮肤肌肉之间，兼之暴怒伤肝，肝气上逆，有升无降，动则气短，天癸愆期不至，仲景谓水分非血也。指交长夏，湿土司权，脉象弦涩，若不速图，有水膨之虞。", "11022": "（案6）挹郁伤肝，肝气犯胃，胃失下行之方，水饮停中，有升无降。脉象沉滑，形气消索，面浮肢肿，已历载余。肝胃气血皆瘀，恙有肿胀之虞。拟方尽人力而邀天相。", "11023": "（案8）饮食失节，寒温失宜，致伤脾土，转输失其运用。浊阴内踞，已成腹胀大证。两脉俱弦，难以挽回。", "11024": "（案10）去秋产后失调，饮食失节，寒温失宜，致血稽留少腹结瘕，脘中聚痞。水谷之湿不运，饮食日减，精神日疲。周身黄肿，脘腹膨胀，脉弦溺短，已成肿胀重症。拟调中化湿之剂，以观进退。", "11025": "（案1）肝气上升，胃鲜下降，兼之暑湿困脾，中州痞塞。谷食不思少纳，亦属不运。脉象弦涩，兹当开痞，拟仲圣泻心法，取其降阳和阴，佐以宣湿为治。", "11026": "（案2）肝胃气滞，滞久聚痞，脘中作痛，营卫两虚，为寒为热，脉象弦涩。治之不易，徐图可也。", "11027": "（案6）气短咳逆，足跗皆肿，脘中痞结，三焦不通，湿困固结，牢不可破。灸脐后得痰数碗，咳喘较平，脉象略起。今日未灸，呛咳复作，夜不能寐。证势若此，上下皆虚，中空独实，攻补两难，有岌岌可危之势。姑再拟消补兼施法，尽人力而邀天相。", "11028": "（案7）由利而痢，戊病传癸也。表邪未清，胸痞已著，按之触手而痛，邪滞互结，脉弦数。法当先治其外邪。", "11029": "（案8）肺脾两伤，气短似喘，胸次结痞，按之拒手。两胁作痛，足跗皆肿。不能安卧已四日矣。《易》曰：上下不交而痞象成。痞塞中宫，上下何能接续，肿何能消，食何能进。脉象细弱如丝，有外脱之虞。人虚病实，攻补两难。勉拟灸法以尽人力。近届小暑，加意提防为要。", "11030": "（案9）七情不适，气结于中，吸受新凉，引动伏邪。身热不清，脘腹痞痛，按之尤甚。思饮作哕，脉象左大于右，深虑正不敌邪，致生歧变。", "11031": "（案3）向来肝肾不足夹湿之体，此因肝气横逆，克脾犯胃，致清阳莫续。脘闷不舒，食入作阻，哕吐酸沫，痰涎上泛，肌肉日瘦，精神日疲，脉象弦滑。虑入神思间病，速宜怡情开怀为要。", "11032": "（案4）肺气不降，肝气不升，升降失常，食入作阻。阴络受伤，虽经便血，脉象沉弦。久则液枯气结，有关格之虞，姑拟一方，尽其人力。", "11033": "（案5）命火不足，不能生土。抑郁动肝，肝木侮土，饮食不归正化，遂变蒸而为痰。痰与气搏，升降失常，道路妨碍，食入则阻，向有脾泻，肌肉消瘦，脉象弦细而滑。久则防气结津枯入神思间病。", "11034": "（案5）肝胃不和，胀痛呕吐，甚则食入反出。脉象细滑，若不调治，有反胃之虞，拟不换金正气法合左金以佐治之。", "11035": "（案7）《经》云：胃乃卫之本，脾乃营之源。肝阳扰胃，湿痰困脾，遂乃营卫不和，时寒时热，哕吐频作，头目不清，身倦神疲。脉象细滑，拟方徐图之。", "11036": "（案8）肝气犯胃，胃失下行之顺，哕吐涎沫，脉象弦滑，若不速图，有反胃之虞。", "11037": "（案9）体质素虚，阴阳失职，脾虚胃弱，非一日矣。夏秋以来，感受外邪，愈而复作，已经四次，吐泻不已。辰下风寒虽解，呕吐未止，手足蠕动，脉象细濡，防其呕久胃伤，致生枝节。拟用附子粳米汤，获效乃吉。", "11038": "（案11）肝强脾弱，脾不能为胃行其津液，蓄而为饮。食入不运，每早脘中嘈杂，哕吐苦水。但脾脉连属于肾，肾为胃关，遗滑频见，怠惰嗜卧，日晡潮热。先理肝脾，佐以摄肾。", "11039": "（案1）久咳不已，肺虚不能下荫于肾，肾虚子盗母气，以致营卫两亏。寒热往来，遗泄频频，两脉虚弦，劳瘵已著。拟金水同治，多酌明哲。", "11040": "（案2）由子嗽延及产后，更加亡血过多，营卫两亏，即上损从阳，下损从阴。近来寒热不止，咳逆无休，侧眠食减，肌肉消瘦，脉象虚弦而数。损怯之势已著，拟金匮麦冬法，以尽人力。", "11041": "（案3）先后天向属不足，经营操劳过度，心脾两虚。此因悲郁伤中，致中气不振，心悸肉𥆧，食入易汗，卧不安眠。脉象虚弦，情志两伤之病。必须自开怀抱，安闲静养，方可与药饵兼功。", "11042": "（案4）郁怒伤肝，木扣金鸡，以致营卫交亏，乍寒乍热。更加阴不内守，癸水淋漓。脉象虚数，损怯根基已露。速当安闲静养，佐以药饵，方可化凶为吉。", "11043": "（案6）木扣金鸣，络伤血溢，日久未解，营卫亦失其职，为寒为热。此时肺阴不降，咳吐涎沫，谷食减纳，面热颧赤。脉象弦数，欲入损怯之途。", "11044": "（案8）居经三月，血不养肝，肝木肆虐，顺侮土位，倒克肺金。经痰饮内扰，于是懊𢙐难名，咳逆气促。痰中带血，胸胁胀痛时行，延久营卫两虚，寒多热少，自汗不已。心悸头晕，诸虚毕集，脉象弦细而数。久虚不复，防成损怯，然此际不可遽作怯证治也。", "11045": "（案10）水亏于下，火炎于上，咳逆失红，音哑侧眠，骨中蒸热，两脉细数。劳怯之基已著，拟方多酌高明。", "11046": "（案11）肺肾两虚，宿饮上干已有年所。近来咳逆气短尤甚。入秋后阳络先伤，阴络后继，由此大便不实而带血，又兼脱肛痔疮，面目痿黄，谷食减少，形气消索，脾亦受其累也。脉象弦细而数。再延日久，防成虚劳肿胀，慎之。", "11047": "（案12）小产后正阴未复，寒热时形。近来热多寒少，兼之木火凌金，脾虚湿甚，咳逆频来，面色痿黄，并带心悸。脉象弦数，诸虚毕露，难以痊愈，勉拟一方，尽其人力。", "11048": "（案13）痰饮年多，津液不足。脾胃不降，每咳必哕逆，谷少身热，间来潮热，右脉虚数，已属损怯之象。速宜安心静养，免其入伏生变。", "11049": "（案15）先后二天不充，加以操劳悒郁，心肾有时不交，精关不固，肝木偏横则脘痛嘈杂，化火生风则面热头晕，脉象弦数。虑延损怯，务须静养乃有济耳。", "11050": "（案16）肝郁化火，热伤阳络，络血外溢，每逢癸水至时，则络血不见。缠绵日久，营卫由此致虚。日晡所以寒热，头眩心悸，遇烦劳胸次胀痛，谷食不运，遂觉火升面热，脉象滑数。损怯之象已见，宜戒怒远烦，佐之以药饵，以冀转损为益耳。", "11051": "（案18）小产后伏邪伤阴，咳逆吐沫，骨中烧热，恶露淋漓不止，少腹胀痛，脉象弦数。由外感而成内损，难以调治，拟方尽其人力。", "11052": "（案1）素本气滞血瘀，加以暑湿伤络，络动血溢，脉象弦细，拟方徐图之。", "11053": "（案2）阳络受伤，血随火溢，咳逆肺气受戕已延二年。向应节发，时有梦遗。脉尚细软与症相合。惟近值夏至大节，不可不预为防之。", "11054": "（案4）肝邪入肺，咳久化热。右胁痹痛，痰中带血，脉象滑数，虑其成痿。", "11055": "（案5）素本二天不足，客夏六月，酒伤肺络，咳血频来，肺肾交亏，动则气短。每咳血之时，先行脘痛。脉象沉弦而数，若不调治，再延防成虚劳。务宜静养为要。", "11056": "（案6）产后致虚，致令天癸未至。前曾惊恐伤胆，抑郁动肝，木火凌金，遂令咳逆作哕。阳络受戕，痰中带血，肺阴交亏，侧眠于右。胸中懊𢙐，心悸头眩，渐虚毕露。脉象弦数，久虚不复，虑成损怯。然此时又不可实遽损怯治之。", "11057": "（案7）木火凌金，咳逆不已，阳络受戕，血随火溢，形气消索，脉象细数，延久恐成损怯。", "11058": "（案8）木扣金鸡，络伤血溢，阴分受伤，内热频来。肾不纳气，动则气短。脉象细数而弦，防其涌溢生变。", "11059": "（案12）阳气素亏，脾经多湿。辰下阳不卫阴，哕血颇多，入暮尤甚，脉象细濡。虑其外脱，拟仲圣柏叶汤，冀其挽回。", "11060": "（案2）症由惊恐伤胆，抑郁动肝，思虑伤脾。脾阳不运，因而谷食不归正化，遂令变蒸为痰。痰饮袭于奇经，溢于四末。六年前，肩井如折，背如负物，肢体麻木，右肩左体尤甚。初患此症，次年即患痰饮射肺，于是咳逆气促，延有两年之久方解。细审此症，非类中，亦非痹症，是属溢饮。至善怯多疑乃胆经症，易烦多恐乃肝经症也。脉象弦滑沉细，显系始于肝胆，中于痰饮，终于阳虚也，无疑矣，延久根蒂过深，体虚症实，攻补两难。能于戒怒远烦，打破疑团，尚可改重就轻耳。", "11061": "（案3）火不生土，木来乘之。水饮停中，痞结攻冲，吐痢并见，脉象沉弦。指日夏至一阳初生，症属阳虚气不虚，转机全系乎此。拟柔肝和胃，再冀时令阳生，自可有济。", "11062": "（案5）烦劳伤气，急躁伤肝。肝失调达，胃失冲和。五年前曾患胃痛，时发时愈，今春举发较重。命门火衰，火不生土，湿痰入络，水饮停中。遂致肠鸣漉漉，攻冲作痛。哕吐清涎水颇多。假火浮于上，故时而嘈杂。真阴亏于下，故小溲不多。胃虚则食少，脾虚则神疲，舌白脉浮。拟方速退乃吉。", "11063": "（案6）木火体质，善怒多郁。肝气易升，胆腑亦失其清净，致头目眩痛。心悸作烦，手足蠕动。两脉弦数，心脉较大。务宜安闲静养，方免酿痰歧变。", "11064": "（案7）积湿成饮，积饮成痰。痰饮伏于肺胃之间。每早必痰涎出方适。肌肤瘾疹屡发，头眩身倦，脉象弦滑。拟用外台茯苓饮增味治之。", "11065": "（案11）两脉滑数异常，按之舞指。昨服十枣丸，未见其效。可见痰热窠囊已固。是以虚里穴动，动则有形。书云：滑主多痰，数则为热。又云：面色鲜明为饮。其理也然。据此谅无误矣。", "11066": "（案12）肝旺胆虚，痰热内忧，喉间不利，胸中懊𢙐，多疑善虑，梦寐不安，神思恍惚，脉象弦滑。速当自开怀报，与药饵兼功。", "11067": "（案13）胸中懊𢙐嘈杂，头目眩晕，舌蹇便数，少腹膨胀。痰甚上阻于喉，睡卧不安，上实下虚，脉象沉滑。总由体虚痰热内扰，心肾不交，肝胆不和所致。速当戒怒远烦，庶免类中之虞。", "11068": "（案14）结缡十载余，从未得孕。冲任二脉之故。近来气化为火，液化为痰。痰热内扰，蔓延经络，遍身脉络酸楚。痛久营卫亦虚。热自内生，化风上腾，头目时眩，胸中嘈杂，寤不成寐，寐则多梦。癸水愆期色紫。脉象弦滑而数。速宜静养勿劳，冀其与药饵兼功。", "11069": "（案15）操劳过度，内郁生痰，痰凝清道，或右肢麻痹，或肩臂不适。甚则寤不成寐，思虑纷来。天癸未期而至，脉象弦细而滑。能于息心静养，佐以药饵可先免类中之虞。", "11070": "（案16）素有支饮咳喘，冬夏时作。客冬产后，百脉空虚，乘虚而作，延及五旬有余，今春方解。三月间饮邪留连经络，遂令指臂腰腿痛，痛虽皆痊而下部仍然不动不痛。治非温通经络不可。然痰中时带血丝，络中有热可知。脉象沉弦而滑。用药颇难，著手拟方，缓图可也。", "11071": "（案17）宿饮射肺，咳经日久。饮邪入络，于是遍身麻痹，两臂作痛，脉象弦软无神，防成类中。", "11072": "（案18）痰饮多年，肺、脾、肾三脏虚久。加以情怀挹郁，肝失调达，肝藏血，血主筋，血不荣于络脉，湿痰乘虚袭入。四肢作麻，肤肿筋痛，右胁气逆，难以转侧。口角时或流涎，虑有仆中之虞。今春虽经失红，温燥之品固忌。兹诊两关弦细，仍宜温通络脉佐化湿痰。", "11073": "（案19）体丰气虚，多湿多痰。阳明脉虚，虚里穴动，四肢酸软。气虚不能传送，大便难解，谷食不甘，脉象细滑。如此情形，所虑皆类中耳。能于善调，有备无患。", "11074": "（案1）齿垢舌黄，积之据也；热壮汗少，邪之征也。腹硬而痛，屡圊便少，可以下矣；脉浮而数，肤灼舌干，可以汗矣。症恰七日，伏邪为患，用下不可以承气，用汗不可以麻桂，姑拟辛凉开表，微苦通里，如得汗下双畅，或可不致昏闭。", "11075": "（案2）夏受暑邪，至秋而发，隔季而病，是名曰伏，病之难退，正理此耳。邪之所伏，必在募原。夫募原乃隔膜之称，居于少阳阳明之间。如伏邪归入少阳，则为寒热交作之正疟；走入阳明，则为不寒但热之瘅疟。是症始起微寒不栗，热退不清，的系募原之证，中途转为连热，因其挟积邪，并阳明与积合病故也。而今积滞已去，暑湿未化，仍然盘踞阳明，随卫气以出入。卫为阳气，行于周身者也，既为暑湿相客，其间必有聚处，至其所则起，过其所则伏。脉形细数，汗出不快，神倦懒语，有时谵言，病经十有七日，暑湿之未化，正由汗之不畅。而汗也者，乃阳气阴津蒸化浊邪而出。际此气阴俱伤，蒸化乏力，欲其有汗难矣，姑从暑湿著想，惟以清泄为主。", "11076": "（案5）初诊：风、寒、暑、湿、燥、火谓之六淫。六淫即谓之六邪，六邪之中暑湿两字每多连呼者，良有暑为天之气，而湿为地之气。天之暑热一动，地之湿浊自腾，人在气交中，强者可御，弱者易受。从口鼻吸入，内伏而发，秋凉引动，病于少阳则为疟，即《内经》所谓「疟不离胆」是也；病于阳明则寒不能栗，热不退清，虽亦名疟，然必呕哕、烦闷、胸痞。此症今五日矣，见象大概如是，而以脉象参之，左部见弦，右手濡数，弦则似有转疟之势，濡则仍居于胃。胃为中土，又为坤地，地气上腾，天气不肃，犹如隆冬之云雾迷空，日光被蔽，胸中清旷之地变成烟尘之区，烦躁难过，夜不安寐，势当然耳。刻交成败之际，正胜则邪达，自可日臻康壮，邪胜则正负，必致内陷神昏，扶正本非其时，达邪诚为要事。古云：急者先治。旨哉，斯言！但暑湿皆伤气分，暑居湿下，清之徒然，湿遏热上，开泄为主，且以苦辛使其气之升降，温苦解其湿之弥漫，轻淡宣其蕴伏，如能应手而效，尚属立阵布兵之时，何能一鼓扫荡？望其邪势折挫，能免变幻幸焉。", "11077": "（案6）不寒独热，今恰半月。刻见神识昏迷，谵语无音，面色青晦，目有白翳，六脉濡数而浮，舌苔灰黄似腐，热不外扬，渴不多饮。此由中阳式微，砥柱无权，暑湿不能达外，反致内陷。古云：陷者举之。东垣所谓补中益气是也。扶正达邪，本属善治，无如邪固可达，痰湿难化，尝考薛叶诸家每以辛香解逐，由此而论，扶正为督战之师，达邪作剿贼之将，然危笃若是，百中图一而已。商用", "11078": "（案7）初诊：热势轻剧无序，他症无起伏，即谓之起伏，惟伏邪能起伏者，须从伏字著意。盖伏即进，起即出，而进者能出。人身之气道，昼夜运行，循环不息，昼行二十五度，夜行二十五度以分阴阳。今因伏暑内蓄，邪与卫气并居，虽不能阻其往来之道路，而必随卫气以出入，至其所则起，过其所则伏。若论轻重长短，视其邪之多寡，正气之强弱为转移，其中夹他病，须随症参切。是症今恰半月，热仍夜甚，烦闷干哕，脘腹板痛，遍体透斑，斑色红紫，固是正理，兼有晦青不泽者，诚非佳兆。脉来濡滑而数，舌苔淡黄而垢，良由禀赋本亏，病初之际，经事适来，阴气暗泄，邪热乘袭，当此浊邪与积胶锢之时，宜出大队军兵。所谓无粮之师，贵于速战。姑用大黄黄连泻心合犀角大青之法，盖斑与疹㾦不同，斑宜清化，古人早已示后，原可一例施治，未识符否，备商。", "11079": "二诊：治病犹如敌寇，用药宛若用兵，应战则战，当守则守。是病邪积胶锢，而正阴素亏，无粮之师，贵乎速战。故昨用大黄黄连合犀角大青之法，幸得便已数行，腹硬较软，斑色之红稍退，脉象仍带滑数，舌转淡黄而露底，望之色干，红刺密布，想由肠胃之积滞下而未清，身中之阴液日伤一日，有限之阴液既伤，难胜无情之邪热，外来之病竟似盗寇，逐去即安。当此大战之际，对敌之寇苟能散而不聚，可无猖獗之势矣。", "11080": "（案8）初诊：《经》曰：夏伤于暑，秋必成疟。又曰：暑必夹湿。夫疟虽不离少阳一经，然与咳相类，脏腑皆有，赘在《素问》。是症始起，寒虽不栗，热可退清，仍属胆病。病尚未楚，即加跋涉道途，不慎于食，不安于居，所以转加腹撑便泄，形疲力乏。今诊脉象，左手弦数，右部濡滑，舌苔薄白，呃逆频见，纳食颇减，痰出黏腻。细思肝胆表里相应，又为甲乙之木，胆病则肝亦病；脾胃本属相联，又为戊己之土，脾病则胃亦病。迄今寒热止，而脉见弦数者，肝脏病也，腹撑便泄，火升面赤，是其征也。纳少呃逆乃木克土位，胆脾不能同升，肝胃焉能独降？脉见濡滑者，脾胃病也，便泄数多，纳不能饭，是其征矣。中少砥柱，气窜上下，是土被木侮，左道升之太过，右路降之不及。盖万物皆有五行，论病首先重此。金生水，则肺肾同旺；水生木，则肝得滋养；木生火，则心主安宁；火生土，则脾胃充足；土生金，则人病何来，名曰相生。金克木，则肺肝乖违；木克土，则脾胃受侮；土克水，则肾水枯槁；水克火，则心主无权；火克金，则肺损源绝，名曰相克。克无多见，一脏一腑已属难疗，人之至要，必在脾胃，所以自古圣人皆以后天为本。脾为营血之源，胃为卫气之根，方书所谓能纳者尚有返还之意，不能纳者，徒恃药力无功。前论木克土位为一忌，纳食迅减为再忌，便泄加呃为三忌，两脉弦滑为四忌，况年届杖国，轻重善恶毋庸言而可喻矣。姑拟一法以图弋获。", "11081": "二诊：《经》曰：脉为血府，百骸贯通，脏腑配合，可推病情。位分三部，息分九候。左寸属心，膻中配之；左关属肝，胆为其腑；左尺属肾，小肠同居；右寸属肺，胸中配之；右关属脾，胃为其腑；右尺属肾，大肠同居，此言其脏腑之配合也。又云：肝生于左，肺脏于右，心部于表，肾治于里，脾胃位中，胆寓于肝，小肠在大肠之上，膀胱傍二肾之侧，此言其脏腑之部位也。今诊左寸无神，心血久已不足；左关独弦，肝胆气火有余；左尺不鼓，是肾气之衰弱；右寸微滑，肺经素有贮痰；右关软濡，脾胃运纳无权；右尺乏力，乃肾阳之式微。际此少腹攻撑，下趋则便泄数多，上逆则气升胸窒，暮夜身热，两颧先见戴阳，纳惟汤饮，米粒不能咽下，慵于语言，声哑不扬，此皆今日病象。初诊因其呃逆不已，便泄不止而用六君柿蒂之法，据述药病相当，颇有转机之意，无如高年元弱，变端不一。前案已言，木克土位，不能纳者，徒于伤寒邪积盘踞之际，虽用承气攻伐，圣人尚言急下存正，所以七日不食，有肠胃固绝之戒。是症始起为疟疾，继则诸事繁冗，食物不纯，直至不能支持，而后已病象日变，元正日乏，竟蹈无胃不治一端。余本肤才浅见，焉能谬膺重任。既承推爱，勉再搜索枯肠，一则以尽下愚之忱，一则以邀彼苍之佑，铅刀袜线尽在于斯，即请明眼采裁。", "11082": "三诊：泄则伤脾，久则必伤于肾，盖肾主二阴，权亦不小，所以古人立胃关煎脾肾双补之法。脾为后天之本，肾为先天之源，脾伤则运化乏力，胃纳应减，胃为阳土而主容纳，脾为阴土专司磨运，一纳一运，互相资生，至于肾经一脏，内藏命火，火如充足方能熟腐水谷，生化气血。而今时寒，烘热已退，固是暑湿化解之征，无奈泄之不休，将及两月，饮食日减，心宕颧赤，脉来细弦，右尺虚散，舌质淡红，满布白疳，即此见端，已有药不胜病之忧。矧十日前陡增咳嗽气促，不但用药有顾此失彼之叹，抑且肺金因咳再伤。土本生金，金为水母，循环受伤，虚莫能支，漫拟引火归源，犹如釜底添薪，如能土仗火旺，泄少谷多，冬行春令，或有望耳。", "11083": "（案9）初诊：夏邪秋发，病已两候，始则微寒，继则足冷，热势起伏，间有轻重。初饮颇多，今反不渴，每痰必嗽，每醒必汗，舌苔满布淡黄，脘腹按之作痛，此皆伏邪夹积夹湿重症本有之事，无如六脉细数不耐重按，面色㿠白，天庭青暗，询之正元素乏，未病气郁，是以邪内郁而不得外达，并从虚而恐致内陷。盖时症一候之中，难分胜负，两候之内，可见成败。刻已将及三候，元正日有不支之形，邪客竟无纤毫解退之机。由此而论，虽用开泄疏化之法，窃恐其鞭虽长，其腹难及。", "11084": "二诊：《经》曰：因于暑汗，烦则喘喝，静则多言，体若燔炭，汗出而散。可见六淫之邪不从表汗，不得外越。前因暑湿混淆，气机窒痹，邪郁不达，湿遏不宣，以致足冷，身热起伏，轻重不一，不咳有痰，卧醒有汗，舌苔淡黄满布，胸闷腹硬作痛，前用开泄上中，疏化邪湿，竟得大汗遍体，㾦乃密布，热势居然退清，舌色已化七八，脉缓而胸次开展，无一不是佳景。惟腑道日久未通，脐间自觉阻滞，显系无形之暑湿可以表解，有质之宿垢必从里通。第症交三候，禀赋素虚，难任承气大攻大伐，且非急下阳明之际，既从无形而退，仍当专事气分。古人有言曰：治积先治气，气行积自去。此症殆有是焉。至于劳复食复两端，自宜存之左卷。", "11085": "（案10）人之智识灵慧，皆本乎心，心为君主之官，心包代君用事，诸病之糊涂呓语，无非邪热痰秽蒙蔽心包。心包用药难表难下，惟取精灵之品佐以涤痰之味，护内攘外，清热开塞。症方五日，肢冷身热，顿为神识不慧，糊语不休，苔黄边白，脉象滑数。此系暑湿入里，湿为热蒸成痰，暑为痰遏难解，痰热迷窍，秽浊上蒙，直迫心包，君主无权，闭脱之变，势恐接踵而至。", "11086": "二诊：症经七日，十龄童子已作一候矣，过候而诸恙不退者，尤非所宜。盖时症以一候为限期，如候上得松，其病渐退；如候上增剧，其势必有进无退。即如此症，闭象虽开，迷糊不清，手舞虽定，烦懊不平，腹时叫痛，按之板硬，脉来浑滑而带数，舌苔灰黄而垢腻，从其起伏而论，不见咳嗽，的是暑邪发于募原，因其积滞内阻，所以直抵阳明，痰蒙宫城，开手即闭。闭开舞定而他款不退，时轻时重，犹如邪势滔天，抑且面色青晦，厥阴所主。而厥阴乃至阴之地，内藏风火，邪如乘入，明早寅卯之间，恐有非常之变。", "11087": "四诊：六气为病，望问闻切四字不可缺一。即如此症，脉象舌色各居其半，为病确据，推之经义即是望切两字，寒热虚实轻重出入丝毫不错，复以一切见证合而论之，无微不显。脉数已和，滑象未退，舌霉已化，苔黄尖绛，的是邪火渐息，痰滞未清，所以神迷好卧，偶而狂起，脐之右旁按之尚痛也。当用泻心汤合白虎法两者并进，一清其在经之热，一通其在腑之积，经腑同治，邪积悉化，病魔自退矣。", "11088": "（案12）年已古稀之外，气液无有不虚，病患暑湿竟成瘅疟，今已十有三日。热势虽衰，尚未退清，脉象小数，舌色光红，有时神识不清，口渴颇喜汤饮，湿因液亏而化暑，由气虚尚逗。大凡暑病之不寒独热者，阳明症也。《经》所谓：阴气先伤，阳气独发。良有意耳。刻下虚多于实，正负于邪，古法本有扶正达邪之治，然胃气不振托邪难尽，胃阴不醒饮食难进，窃恐病去元败，临崖勒马收缰而有不及之叹。", "11089": "（案13）瘅疟一症，传书甚少，仲祖为历代之圣师，尚无专书，不过列于诸疟门中，似叙似释，亦未立方。后世喻嘉言立甘寒一法，此治瘅疟立论。现之论瘅疟者，不外暑湿二字。暑必伤气，症甫四日，当时凛发热，自午后而起迳至黎明，得畅汗而缓，以后至时复作，却不甚重，汗亦不多，此非邪达势轻，乃邪伏募原。气为邪遏不复宣越，所以昨日来势又甚，甚则胸闷烦躁，呕恶不止，脉象浑滑而数，舌苔黄厚而腻，数日未便，腹脘觉痛，良由暑湿内蕴为新寒新积触发，积系谷食所成而必在胃。胃为多气多血之乡，胃既受病则气血不得流畅，邪必因之而入，是以日轻日重成起伏也，恐淹缠生变。", "11090": "（案14）小儿蒸变之后，脏腑完备，喜怒自如，其生长犹如草木之欣欣向荣。惟小儿体属纯阳，必得纯阴之乳以配之，草木初栽根浮必得濡润之水以溉之，若曝于日必见枯萎，此小儿受热变经之喻也。年方四周，玉液初断，进谷未久，禀赋之阳，蓰倍于阴，概可知焉。是症始闻火惊，继吓锣鸣，夜即身热，误会受寒，褥以羊裘，被以重棉，陡发惊搐，气升痰鸣，四肢不温而面色青灰，六脉沉而微形弦数，两目直视，二便皆窒，呼之不应，饮之不啜，此名惊闭。盖闭乃手少阴之病，惊乃足厥阴之疴，惊则气乱阳升，闭则气窒阳伏，惊由热甚生风，闭由火蒙痰蔽，因惊而经络牵掣，从闭而智识全无，惊而神气清澈者方为轻兆，闭在惊厥之后者则为重候。大抵小儿之病，最怕其惊，五脏之疾，心可不犯。历考古人治惊以镇，治闭以开，再清其膈间氤氲之痰热，或可转险为夷，然虽取法圣贤，特恐病似祖鞭矣。", "11091": "（案15）童女风温，今恰一月，中途虽则转轻，而浊邪未清，余烬复焰，身热又起，咳嗽无汗，大便不行，脉弦数而带滑，舌淡黄而尖绛。此由邪积夹痰互阻，肺胃表里既无出路，自然郁蒸化热，蒸痰动风。风藏于肝，痰生于胃，胃为十二经之总路，肝为东方乙木。胃气不降，风火上升，所以至其时而益甚，惊厥生焉。刻虽针刺便行，然神识未清，手搐目窜，语言不出。胸中本属清旷之地，而今转为尘雾之天，机窍被其蒙蔽，经络被其阻痹也，势在险峻，难免复惊之变。", "11092": "（案16）乳儿未及载半，痃疟已延年余，幸而脾胃强壮，后天有权，仲春得以向愈。讵知感冒风温，染成顿咳，迩来热甚，三日即发惊厥，目窜睨视，搐搦反张，哭不转声，涕泪皆无，诸疑毕集，无端不作，作后神识似慧而屡发不已，良由病杂迁延，气阴俱伤，气伤则络脉空乏，阴伤则木失涵养，化无情之风火，夹有形之痰浊，蒙窍袭络。夫络为小路，窍乃空洞，非邪不进，非虚不入，所谓邪行如水，虚处则受也。思其既进不易外出，所服药饵，苟非直抵病所，安能转危为吉？是故为医者不得不倾心吐胆，搜索枯肠，勉拟一方，以期化险为夷。", "11093": "（案18）初诊：多病多虚之体，而患时令风温之症，始则寒栗而热，继则咳嗽多痰，今方三日，忽然热退咳平，面红转白，痰无吐出，旁观者皆为病去之象，主病者亦因多病多虚之体，虽患时症，不过尔尔。讵意神识渐渐不慧，糊语喃喃不已，及诊其脉，细数无神，左手搏指，舌苔浮白，大便溏泄，分明邪乘虚陷，痰蒙内窍，势属至危。姑拟扶正达邪，护里宣开一法。古人云虚人善变，此症殆有是焉。", "11094": "四诊：狂乱整日，继之以夜，直至今晨，二便并行乃止，止则其脉也宛如平人，未刻而大汗遍体，湿透重衾，遂为两目迷睡，隐隐叹息，循衣摸床，手指蠕动，面色如纸，脉细若无，舌苔光泽不红，言语声气不续，此名脱。本无治法，勉因脉未躁疾，汗未全冷，阳气虽欲离阴而飞越于外，阴精尚有涵养而交纽于内。然素伤之阴能有几何，如不汲汲敛摄补益，终归于脱。勉拟一方，亦属背诚矣。", "11095": "（案1）大凡时症，不外六淫。六淫者，风、寒、暑、湿、燥、火是也。燥火与风，阳多阴少，随感随发；寒与暑湿，阳少阴多，能伏能蕴，所以伤寒与瘅疟都有内伏而发者。秋季之病由于暑。伏暑必夹湿，湿能伤气，暑亦伤寒。是病不寒独热，今恰半月。刻见神识昏迷，谵语无音，面色青晦，目有白翳，六脉濡数而浮，舌苔灰黄似腐，热不外扬，渴不多饮。此由中阳式微，砥柱无权，暑湿不能达外，反致内陷。古云：陷者举之。东垣所谓补中益气是也。扶正达邪本属善治，无如邪固可达，痰湿难化，尝考薛、叶诸贤每以辛香能逐。由此而论，扶正为督战之师，达邪作剿贼之将。然危笃若此，百中图一而已。拟方即请有道商进。", "11096": "（案2）症恰半月，已属三候期日，际此中秋节令，向愈之期，似不为迟。然不但暑湿未化，抑且积亦未清，暑、湿、积三者已属鼎足之势，安可增一热字？所以热恋不退，稍动辄汗，汗不通体，睡中较多，咳嗽痰黏，烦懊夜甚。从脘至腹偏右一带按之板硬，问之略痛，脉形濡滑浑数，重按无力，舌色淡黄干垢，尖红心露。想其暑乃夏令之邪，天之暑热一动，地之湿气自腾，人处其间，无不感受。暑湿两字每多连呼，暑由三伏而受，故谓之伏，夏邪秋发，亦谓之伏。伏之一字，邪根深蕴，可知现已化热，热之性固速，而与暑湿为伍，亦不易化，且易伤液。症之口渴、烦躁、面赤、舌红，皆从此出。胸前刻虽红疹密布，而隐约未透，固是暑湿热之出路，然不足以挫其病势。昔谚云：透疹之际，不可下夺。非确论也。盖疹㾦之来，必从暑湿积热郁蒸而出，若得四者可以分化，何伤其疹与㾦哉？论变非昏即厥，须预防之。拟方请政。", "11097": "（案3）症恰三候，始起寒热似疟，得汗不解，继则热恋不退，入夜为甚，咳嗽痰黏，烦闷不舒，脉来郁涩而数，左部带弦，舌底光红干碎，苔如糜腐。此由浊邪交蒸化热，兼之情怀悒郁，木不条达，亦易化火，充斥肺胃，蒸浊成痰，上炽于华池，消灼于阴液也。当此时邪为病，自然持之于药，草木之功原可克奏，若论拂郁情伤，须期怡情畅怀，两者并行方合病机。拟方商进。", "11098": "（案4）症经四日，当时大寒大热，自午后而起，迳至黎明，得汗而解，以后至时复作，却不甚重，汗亦不多。此非邪达势轻，乃邪伏募原，气为邪遏不得外越，所以昨日午后来势又甚，甚则烦闷胸躁，渴难多饮，脉来弦滑而数，舌苔厚黄而腻，乃暑湿内蕴，为新寒新积触发。积乃饮食所成，而必在胃。胃属阳明，乃多气多血之乡，胃既为病，气血不得流畅，邪必因之而入，是以日轻日重，是起伏，惟恐淹缠生变。", "11099": "（案5）年纪甫冠，智慧过人，以致情窦早开，肾关不固可知矣。迩来不寒但热，今交三日，热势起伏。伏则犹可，起则烦懊胸闷，睡中背部出汗，涌吐涎沫，当脐跳跃，偏右按痛，脉来弦滑而数，舌苔淡黄而腻。此由夏令之暑邪内伏募原，新伤之寒滞盘踞阳明。若论动气，非大虚即大实，病甫起而见此，所谓未病先虚。当脐乃少阴地位，显系元海不藏，封固失司，体虚症实，不但用药殊难，更卜易生变幻。商进。", "11100": "（案7）初诊：症经四月有余，始起寒不能栗，热不退清。刻下寒热虽退，变为腹胀，得食脘痛，手按辄拒，舌苔满布浊腻，脉象右手沉实，小溲不多，大便艰行。《经》云：先夏至者病温，后夏至者病暑。病肇祭屈之令，竞渡之际，其为暑湿无疑，病于少明之间，名曰似疟。其时若能药当病情，风食禁忌，何致迄今不愈，反加成臌之险？邪湿既不能达，自然壅积为内伤脾土，中焦运化之机乃息，为肿、为胀，诸症纷起。《经》所谓，浊气在上，则生䐜胀。太阴气至，亦䐜胀也。为今之计不得不用疏逐一法。古人有言，两虚一实当开实面。且是症元伤成损，当可缓调，喘急骤加，危期至速。姑拟先贤刘河间神佑舟车为主，五皮泄水佐之，以望有形浊滞随便而去，无形清气由此而升，方可转机。然背水之战，即此一举矣，未识然否。即质高明。", "11101": "（案8）天气清明，地气安靖，气来如正则人民少病。今岁甫交夏至，天气暴热，吴氏谓之未至而至。气来不正，即谓之邪，人处其间，壮者自可运行，怯者著而内蕴，至秋而发，皆曰伏邪。观其时之早晚，邪之多寡，而伏必在募原，其发或入少阳，或归阳明。入于少阳则轻，可成疟疾，归入阳明则重。此症皆因胃腑伤积，所以甫发即阳明与积合病，病已十有三日，入暮四肢渐寒，继则甚热，烦懊头晕，腹时呼痛，从脘而至少腹俱为满硬，大便虽行，尽是稀水，脉来滑数而弦，舌苔黄而腻。热至寅卯之间，无汗而和。夫寅卯从阴转阳，身中之气循行注肺，所以无论伤寒瘅疟此时必和。盖邪犹如阴柔小人，一切转阳则伏，设使有汗当言其伏，况无汗乎？一切款端刻皆隐匿于后，恐其接踵而至，便成棘手重候，际此大战之秋，安可不出大队临阵？否则悔之晚矣。", "11102": "（案9）古云：体肥多湿。暑必挟湿，体肥则中气必弱，暑湿亦伤气分。夫气主于肺，邪从口鼻而入，内伏而发，名曰伏邪。六淫之邪，惟暑湿易伏，伏于脏为疟，疟之间作日作即邪之可浅可深耳。伏于胃亦为疟，疟之不寒起伏，乃两阳合明故也。是症今交十有三日，始今的是阳明疟症，所云暑湿皆病于气，肺胃见象无一不具。鼻窍霉黑，鼻尖不温，热势起伏，胸痞烦闷，皆其征也。盖暑为天之阳邪，湿属地之阴邪，暑欲化火化燥而不果者，湿遏故也，湿浊弥漫而内蒙者，暑之蒸也。舌苔灰霉，底质干燥，渴饮，脘痞，右脉濡小，皆其征也。暑湿相互必当开气，气开则暑湿不合，清气自升，津液乃复。法当开展上焦，宣化中焦，淡利下焦，俾得肺气清旷，化源自流，则暑湿之邪自然分泄矣。由此而论，治上为主，取微苦微辛条，参入芳香甘寒一二，以望应手。不尔，恐暑湿交蒸，热秽之气内冲心包，必至神识昏糊，四末清厥等险。拙见如是，即请有道商进。", "11103": "三诊：凡人生长皆在脾胃，所以五行配土，八卦为坤。胃司纳而下降，脾司健运而上升。水谷入胃，精液生脾，洒陈于六腑而气至，和调于五脏而血生，气血由此而生，百病从何而至？古之圣贤无不归重于脾胃，正所谓土生万物是也。刻诊自疟变痢，体本烟虚，初进逆挽之法，继投葛芩之剂，寒热神昏固退，下痢度数亦稀，未始不为美事。惟宿垢虽下，纳仍不加，红腻虽少，急重不除，四肢有牵振之意，遍体出溱溱之汗，时见呃忒，苔现灰浮，左脉弦数，右手更甚。暑湿积滞虽有分化之机，中土气阴已具败变之象，叔和云：胃见肝脉，木假土也。医书云：痢宜小脉与症符也。盖痢虽湿积所成，能成则愈。今则所纳之物止能米饮，稍多即觉停滞中脘，必借烟力抚磨而后方可。其胃之败，其脾之戕，朗若列眉，其病之凶，其款之忌，明如绘素也。自昔圣贤以药治病，无非补偏救弊而已，至于收功无一不以脾胃为主，前之李氏，后之叶氏，皆详论也。为今之计，宜先扶土以振后天，疏补以冀运纳，然袜线铅刀不足以济事矣。", "11104": "五诊：古云：泄久伤脾，痢久伤阴。昨用仲圣猪苓法益阴化湿，参以东垣之方补脾醒胃，服后竟得便行成粪之垢半碗之多，腐苔化去，绛底黑面，此等转机，确非浅鲜。无如阴液不能一时而复，元气难以顷刻即回，自觉烦躁，日常睡露，脉象仍见弦数，口渴时喜饮汤。以此而论，尚在险津。历考圣贤，痢久元伤之门，有用益阴，有用补气，虽能转险为夷，然中土弊败，药力难施，姑再出入前意而治，第恐杯水不足以救舆薪，虾力何能主任行舟也？再疏一方，仍冀亦兼之吉。", "11105": "（案11）向有停饮，外感风邪，表气束缚，不从汗泄，风气通肝，邪郁络阻，左胁作痛，邪郁生热与有形之痰积交蒸，神明为之扰乱，大便不解，头胀身热无汗，言语有时错乱，气逆嗳气，舌苔中心干糙。此风温夹积夹痰，不达不化，将显伤阴劫液之象，脉细数少力，是本质素亏。无粮之师，利在速战，管窥之见，请主翁裁夺。", "11106": "（案12）大概六淫之邪，上受者不离手太阴肺经，下受者不外足太阳膀胱经。《内经》云：清邪中上，浊邪中下。风燥为阳化之邪，自伤肺经，肺主一身之气，又司五音，在时为秋，在色为白，在变动为咳，在津液为涕。刻症肺病毕具，所重者鼻窍扇动，但坐难卧，热势重而脉象过数，咳嗽甚而舌苔黄浊。不离风燥为主，抑且痰积相互而闭，里痹表郁则动风生惊，气升喘促。谚所谓夹惊肺胀者是也。拟方备商。", "11107": "（案13）痢曰滞下，滞乃不通之谓。由于湿热食积阻于回肠屈曲之间，伤气则色白，伤血则多赤，伤于五脏，各随其脏色而异。治法暴则为实宜通，久则为虚宜涩。此病已愈两旬，始起寒热似疟，继则变为腹痛下痢，舌色灰黄而干，脉形濡数而实，所痢之物红胜于白，竟有形块，稍见秽腻，仍无宿垢，形神日削，纳只粥饮。湿热积滞互阻不通，脾土无消运之权，肠金乏传导之官。古云：两虚一实，尚开一面，标本同病，急在先治。明指实急于虚，通先于补之义。脉舌症象汇而合参，不得不假法于一下。如能湿滞分消，方可痢止痛停，二便如常，纳食复旧矣。倘言因其元虚而因循望愈，则呃逆、起腐，延恐不免，拙见如此，即请明商。", "11108": "（案14）《内经》论血，阳络伤则血外溢。又曰：阴气者，静则充长，动则消亡，所动之由，气也火也。所以古人治法不清其火，必降其气。徐之才、缪宜亭所谓气为血之舟楫，火能载血上浮是耳。刻下吐血虽止，脉尚带数，阴络固静，气火未熄。今宜安养以待其复，倘仍经营操持，必致由伤而损，自损成痨之险。", "11109": "（案15）夫痧必在于肺者，皆由痧从风温而成。盖风为有形之阳邪，温是化热之气，无形无质，其从口鼻而入，肺居上焦，首先犯之。肺为娇脏，又曰华盖，而司一身之气，气宜下降。肺既受病，则气道愤郁，浊聚成痰，逆而不降，以致喉间痰声漉漉，气粗宛如拽锯，脉来滑数，舌苔黄腻而厚，已成肺胀重症，病之重险可知。当用疏胃府而化其浊，宣肺气以彻其邪，使其邪达浊化，其气自降。如不应手，则变幻倏忽矣。", "11110": "（案16）大凡病中不能食者，脾胃必虚。《经》云：清气在下则飧泄。中气不足，溲便为变，皆指脾胃而言。便泄气滞溲清，舌淡面色无华，脉形小而无力，何一非中焦为贼蹂躏，仓廪久乏积贮之故。盖五谷入胃，磨运在脾，清者为营，浊者为卫，洒陈于五脏，和调乎六腑，诸经与络得以渗灌，内外表里皆能充实。所以体之壮者其食倍加，面有露桃之色，指有扛鼎之力；体之怯者其食减常，面具露气之痰，手乏缚鸡之能。至于脾胃之论，最重东垣，大旨脾宜升则健，胃宜降则和，和者取其甘温，升者必用温热。姑以耆附六君加减，俾得脾胃并复，谷食有增则病愈速矣。", "11111": "（案18）运筹握算，本伤心脾，脾伤则易生湿痰，心伤则不充神血。是以未病之前常有嗽痰少寐，今暑热伏邪已经匝月有余，其中轻重变迁不烦多赘，且就刻下而论，热不外扬，神识糊涂，呃逆频频，不嗜汤饮，舌苔渐黄而霉，脉象濡数，时见嗳气，大便溏薄。此乃平素痰浊与积为伍，伏暑之邪本喜入心，心经神血一虚则内走尤易，脾脏浊痰不化则窒塞益甚。顷见吐痰两瓯，呃忒，神识顿觉稍慧，其为上中清旷之地悉被痰湿蒙昧可知。盖时症患于元虚之体，已属不支易变，矧加呃忒糊涂之忌，险重何待余言？姑拟开泄涤化宣窍安护一法，窃恐投鞭不足以断流耳。", "11112": "（案19）今秋天过亢晴，晴则燥，燥乃温类所盛之邪，是以一热则甚，甚致言语糊涂，今得大汗遍体，热势已解大半，似有告痊之机。然左胁以及胸膺呼吸皆痛，舌苔淡黄而厚，脉象糊闷而数，此由邪热因汗而稍达，气闪于络而不和。《经》云：肝生于左，肺生于右。又云：肝脏血转司经络。昔贤治法，温邪当分感与伏，闪气宜辨肝与肺。今病温邪在肺，宜用辛凉；闪气在肝，宜和血络。姑拟一方，以望应手，庶免昏喘痰红之险。", "11113": "（案20）夏令暑湿，至秋而发，名曰伏气。夹积则病甚于里，腑受则泄矣，感风则病甚于表，经受则热矣。是症始起不觉寒热，即为便泄，其夹积也，昭如绘素。虽经调理而愈，未久即患寒热，似疟非疟，胆胃同病。据述中途寒热虽止，不免口腹未谨，皮毛未固，既感时令风温，复伤新食之积，是以病来两候，已见神识昏糊，不言不语，热势内炽，舌质灰黄，口渴饮少，汗疹全无，数日之前大便夹杂红秽，今按其腹板硬，两手推拒，眵障其目，目亦不开，焦燥其唇，唇干裂血，咳嗽不扬而声被痰黏，痛痒不知，而烦懊如故。呼吸气粗，面色晦滞，脉象右寸弦涩，右关数实，右尺重按似有搏指之意，左寸濡数，左关见弦，左尺嫌太露有不藏之象。此由风温蕴于肺胃，逆传宫城之内，痰积熏于脏腑之间，蒙迷清旷之地。盖风温本属阳邪，变燥化火，素为易事，痰积自有秽热之气，熏窍蒸络，尤属不免。大抵心主一脏义不受邪，人之聪明智慧，皆系于此。既被邪陷入，自然险象叠出，忌款毕集。聊作背城之计，窃恐画饼于纸，徒增想象之叹，得邀苍天默佑，或可转机一线否。", "11114": "（案22）初诊：夏令暑湿，至冬而发，始起为疟，继合成痢，腹痛攻撑，里急后重，舌淡黄而厚浊，脉弦而右实，纳少哕恶，寒热依然。伏暑必挟湿浊。是以日久不愈，复加郁怒异常，食物不谨，经病未已，腑病接踵。谚云：疟变为痢，最属大忌。窃恐转辗不愈，有猝变之险。", "11115": "大便虽行，尚未自然，六脉虽一，尚嫌弦大。得食则腹有胀阵，得饮则痰出较易，交寅则虚火上炎，至晨则咳甚汗泄，其为阴分日虚，阳不潜藏可知。盖人犹天也，天以春夏为生发，人逾四十，脏气渐衰，今则年已五旬外，时届秋冬，欲望生生，不亦难矣。前投潜阳之品，胃纳不减，古人立方，无非补偏救弊，阴欲其平，阳欲其秘则寿，阴竭于下，阳炎于上则病。法当加重前方，以冀阴充阳潜，纳食渐加，或可返秋冬而变春夏，则阳和之气充满乾坤。", "11116": "（案25）初诊：下江之地，湿邪恒多，况久居沪上，地湿尤盛。湿为土气，不在胃而在脾。胃居中脘，脾主肌肉，苟其脾胃之气充足，运化有权，安有浊留中脘，湿阻脾络之患？此症始起似属劳倦无力，继则不寒身热，已而两足酸重，步履维艰，迩来手亦如是，上举无力，转侧不能，脉来濡滑而数，舌色厚白而腻，咳嗽痰沫，小溲浑浊。良由冬令气暖，寒风外袭，肺经内应，肺属干金，以配为天，脾胃属土，以配为地，地湿已甚，天气复痹，竞为阴霾四合，清旷失司，燥烈之地变为沃壤之土。幸而风寒不多，尚可不成痛痹。且开天气，逐地湿，冀其内外分化，拟方候商。", "11117": "二诊：《内经》曰：人有五脏，外配五合，皮毛是肺之合，肌肉是脾之合，血脉是心之合，筋络是肝之合，骨髓是肾之合，营行脉内，卫行脉外，昼行二十五度，夜行二十五度，左升右降，回流不息，犹日月转旋耳。今因湿浊内阻，营卫失于流利，经络被其窒痹，牵掣转侧维难，咳不扬而痰黏，脘常痞而不畅，小溲虽浑，大便未行，脉象似大于前，舌苔已化其半，时觉烦懊，得汗不畅。前服五积散合活络丹一法，络隧稍通，蕴湿略化，无如中脘既为浊滞所踞，不能下降自然上泛，胃为阳土以通为主，脾为阴土以运为用，若得脾胃通运之有权，何患湿浊之不化？再拟一方，以冀渐入佳境。", "11118": "（案26）泄则伤脾，久则必伤于肾。所以古人立胃关煎脾肾双补之法。脾为后天之本，肾为先天之源。脾伤则运化乏力，胃纳应减，胃为阳土而主容纳，脾为阴土，专司磨运，一纳一运，互相资生。至于肾经一脏，内藏命火，火如充足方能腐熟水谷，生化气血。而今时寒烘热已退，固是暑湿化解之征，无奈泄之不休，今及两月，饮食日减，心荡颧赤，脉来细弦，右尺按之虚散，舌质淡红，满布点点白疳。即此见端已有药不胜病之虑，况十日后陡增咳嗽气促，不但用药有顾此失彼之虞，抑且肺经因咳再伤，土本生金，金为水母，循环伤虚，滋漫难图。拟引火归源，犹如釜底增薪，如能土健火旺，泄少谷增，冬行春令，或有望焉。", "11119": "（案32）闺秀十四，通经本属顺正，因肝气常郁，肺气不宣，藏统失职，冲任贮少，以致一潮即止，脉来细数，大腹旋满，忌款见矣，药恐难图。", "11120": "（案33）右脉稍扬，左关尚弦，肺气少宣，肝阳未平。肺属金，肝属木，木无所畏，则风阳上腾，金不能制，则子气亦衰，病非六淫，效焉能速。", "11121": "（案4）吐血大势虽定，而脉来数大不靖，舌苔淡黄，乃五志之火内炽，肺经为其蒸灼也。", "11122": "（案5）大疟五旬有余，脘胀痞痛而呕，汗少不便，脉数，舌黄。邪积阻痹气机，防其昏闭之变。", "11123": "（案10）脉形左手细小，右手带数，舌苔黄腻，无梦而遗者。气虚不摄，湿热浑窍，肾关不固也。", "11124": "（案16）病后热又一旬，两脉数大，邪受于表，积蒸于里，惊闭最易。", "11125": "（案30）淋浊似有若无，肛门近又作痛，脉来滑数，舌质光红。湿火下注，攻走不定也。", "11126": "（案32）月信前后，腹胀且痛，冲脉有寒，肝脾之气违和也。", "11127": "（案38）肝风夹痰，头晕舌黄，时觉烘灼，脉来弦滑。宜从肝胃并治。", "11128": "（案40）幼婴产未盈月，身热已经八日，热至似有寒意而不甚，得汗不畅，时而哕恶，大腹按之微膨，阴囊肿如晶球，脉滑数而带弦，舌薄白而腻。此由产母感暑，内胎应之，蕴于少阳之间，染成似疟时症。暑必夹湿，湿为水类，侵入囊中，幸而余处未肿，不致蔓延于上耳，免节外生枝。小儿体属纯阳，热甚之际，恐其暴风鸱张，即有牵引经络，为瘛疭之变。拟方商进。", "11129": "（案41）症经十有二日，伏邪夹湿，蒸遏气分。初则起伏，继而热盛，时见糊语，通宵不寐，曾得汗而不解，大便日泄数次，舌淡黄厚，脉至不扬，未病之前已觉不宁。良由心神不定，况又暑喜入心，所幸中焦尚健，未尽入内，恐其延久而变昏陷，则去生远矣，明见正之。", "11130": "（案42）风温袭肺，酿浊成痰，以致咳嗽痰白，脘痞气逆，脉数微热也。", "11131": "（案43）由疟而变连热，肤色萎黄，力乏，舌色浊腻，脉象濡数。疟本传脾，劳碌亦传脾，最恐淹缠入损。", "11132": "（案46）不咳而嗽，胃痰故也。痰中见红，肝火炽也。左脉弦数，右手濡滑，刻下血虽止，嗽未平，终属不宜，如此脉象，恐其久延为损。", "11133": "（案50）先咳后热，今又呕血，脉象左手数大，舌色光红，有汗。风热外入，宿伤在络，恐冲。", "11134": "（案58）脉数，内热，面黄力乏，是郁伤脾，脾不运湿，湿化为热也。", "11135": "（案70）大产两旬，而发寒热，汗出半体，衃血不多，脐下极痛，近又便泄，脉形弦滑而数，舌苔淡黄而腻。此由产后正虚，伏邪内发，留瘀结癖，名曰似疟，当从疏泄。", "11136": "（案72）疟势不退，脉小，色晦，慢惊、肺胀即在交睫之间。勉方以图幸。", "11137": "（案74）呕吐攻撑，从下而至脘者，为肝木犯胃。然脉已数，呕沫带酸，内郁化热，温方参以苦降。", "11138": "（案75）因伤见血，血止纳少，作呕，脉濡，舌浊者，痰湿内蕴，阳明气不宣降也。", "11139": "（案80）咳久，舌黄，脉仍右大，风燥外袭，湿热内恋。素有不梦自走，且以汤丸分治。", "11140": "（案90）病经五月，始起似属风温之象，而今气郁生火，火盛生痰，清灵之处日被痰火所蒙。是以喉中如痹，火盛气升，左脉如无，右手弦滑而数，夜不能寐，舌色渐减，此名痰火，须从气郁痰阻论治，开怀怡情，方显药效。", "11141": "（案94）滞下两季，仍见里急，脉舌相参，虚实各半，仿古散法。", "11142": "（案99）疟止复来，因劳而然，仲祖所谓劳复是也。脉小而数，虚实各半，拟小柴胡法。", "11143": "（案100）疟已五阅月矣。刻下寒热依然，舌光，脉小，咳嗽气逆，纳渐递减。有成损之险，无向愈之象。", "11144": "（案102）寒热，力乏，舌黄灰，脉象数，邪浊因劳而发，误食滋腻所致，非轻恙也。", "11145": "（案107）脉象未清，仍从手太阴肃降。夫肺为干天属金，必辛凉甘润为主。", "11146": "（案121）咳嗽虽爽，喉燥嗌干，身热不退，脉浮而数。乃风邪未散，犹然化热蒸痰也。", "11147": "（案122）怀妊而患起伏，瘅疟今已十有二日，夜分神糊，舌黄满布，烦闷无汗，脉象沉数。伏暑与湿皆重，最怕动胎神昏等变。", "11148": "（案126）辛凉甘寒治肺胃，热退脉缓，可知风温内蕴，非无征也。然咳痰尚多，前贤治其一面之例。", "11149": "（案127）疟久脾土受伤，伤则湿聚蒸痰，是以独热不寒，舌黄满布，脉象濡数，小溲混赤也，恐入损境。", "11150": "（案129）经行而停，寒热日久，得食脘腹不舒，脉象渐见细数，邪浊内恋，元正日虚，颇有成损之险。", "11151": "（案137）寒热咳肿，汗少脉浮，风水阻于肺脾，二经合病也。恐变喘促。", "11152": "（案139）脉细而弦，弦为肝气有余，细为阴液不足。补阴之药，味胜于气，疏气之品，辛多于甘，独顾一边，犹恐顾此失彼，姑选酸甘辛芳之品。", "11153": "（案156）脉象扬抑不齐，中气为痰所阻，阳不入阴。《内经》所谓胃不和也。仿黄连温胆法。", "11154": "（案157）胃司纳，脾司消，纳多而消迟，劳倦伤脾可知，脾属土，湿为土气。脉象之濡数，稍劳则溲赤，阳动则湿蒸为热也。", "11155": "（案159）五更寒暑，常为寒热，加以操劳不辍，月事不行，脉舌参之，元正固虚，邪浊尚恋。古云：鞭长莫及。此症是也。", "11156": "（案163）经事愆期，且兼寒热攻痛，而见右脉大者，先治其标。", "11157": "（案176）寒热而见咳嗽，必涉于肺，肺司皮毛，似可假汗一达，然右脉涩而不畅，诚恐昏喘之变。", "11158": "（案178）恶寒已罢，脉数亦静，至于邪去正伤，势所当然，犹乎贼到蹂躏，贼去自然修葺完固，正所谓医家如兵家耳。", "11159": "（案185）寒热咳逆，今恰七日，胸胁脘痛腹板，痰不爽而见红，脉形滑数，舌色灰黄。此伏暑为新风引发与宿伤同病，防其昏喘之变。候商。", "11160": "二诊：经漏渐止，脉常带数，数则为热，热从火生，正所谓血之动由乎火也。再拟清养之中佐以益气，气足而脾可固摄矣。", "11161": "三诊：经漏后甚，脘痞气逆，脉形左大于右，舌苔淡黄而腻，的系浊阻胃中，升多降少，肝气肆横，脾乏统摄也。", "11162": "四诊：漏红虽止，脉见滑数，数有热，滑有湿浊，显系所蕴之湿浊尚未尽化，虚则肌表失护，未免辐辏新邪也。", "11163": "五诊：脉症稍佳，立方似合，再从前意出入。", "11164": "（案196）经行落后，色殷而痛，舌苔黄腻，脉数而郁，是气滞血热，蒸湿成痰也。", "11165": "（案202）伏邪晚发，独热不寒，舌色干白，脉象濡数，阳明之症，逆传最易。", "11166": "（案204）寒热既系外邪，何得脉反左大，良由劳碌，湿滞朋比则气分不舒，脉道不扬也。", "11167": "（案213）凉营化湿，血淋已减，白浊未止，痛必有火，脉沉尺大，古人治法不外痛为不通，病日已久，当参脾胃，《经》旨所谓中气不足，溲便为变是也。", "11168": "（案215）先为胃痛，近又寒热呕恶，汗少，脉滑而数，当从少阳厥阴疏和。", "11169": "（案223）头摇目窜，两脉似丝，便泄五次，哭声呀呀，脾元大伤，恐猝然风动厥脱。", "11170": "（案231）脘腹撑胀痞痛，脉沉属气郁浊聚，女子以肝为先天，胃宜下降，且以温通疏达。", "11171": "（案233）咳不离乎肺，非外感即内伤。为日已久，迩来加甚，脉浮而滑，痰色带紫。想风邪久蕴化热蒸痰，再从肺胃清泄。", "11172": "（案237）痢成休息，脉数内热，咳嗽痰白，得汗不畅，是湿热不化，复感新风也。", "11173": "（案245）营亏未复，复聚浊邪，以致先为左肩膊不利，近又脉数，内热，苔黄纳少也。", "11174": "五诊：十一朝，疮至结痂，元气大伤，其倦怠嗜卧，似乎合理，但自早至暮，通宵达旦，竟无片刻举动，此为太过。至于不欲吸乳，但能食粥，良由鼻孔窒塞，转气不能故耳。论其脉象舌苔，内蕴之毒火尚炽，毒虽缓而火最迅速，易生反复，不得不预告之，抑不得不预防之。候商。", "11175": "六诊：十二朝，神识颇安，似乎倦怠，幸而稍动即觉，呼之即知，从正气衰惫而论原属正理，惟仍不食乳，粥食减昨，乃脾胃不运，生气不振，细以脉舌合参，现已成痂脱疕，毒火谅可外越，想无内窜之理，法当清解之中，兼以扶正。", "11176": "（案1）初诊：一热则惊，其故者何？盖缘邪积极甚，充塞于内，闭而生风也。惊后四肢反冷，热炽于内可知，舌苔黄厚，脉象数实，症之险重何辞？历考古人治法，都以凉膈散泄其无形之热，去其有形之积为主。然阳气能宣不闭，能行不冷，由此而论，治气亦为紧著，必得腑通表达，庶可截其驾轻就熟之路，或可不踏前辙为妙，是否商进。", "11177": "（案2）初诊：症延十有六日，寒来不过四肢，身热起伏，咳微不爽，从未得汗，脉来浮滑而数，舌质光红而干。前日陡加烦躁，竟无片刻可安，的是伏邪归入阳明，郁蒸化热。阳明本是多气多血之乡，经中气血既为邪热煎沸，变为多烦多躁之地。盖胃上覆肺，迫近心包，此处既为邪热所交迫，无怪其势益甚焉。如再进一层则不堪设想矣。姑拟白虎汤一法，救肺之品亦寓其中矣。", "11178": "二诊：烦躁又轻于前，今日脉象不静，腹痛时作，脐下膨满，舌苔黄而腻，中心一条光裂，乃湿温化热，分而后合。热则阴分受灼，久则木横乘土，脾胃虽皆属土，大腹乃脾土所主。养阴泄热，抑木和土乃一定章程。", "11179": "四诊：《经》云：药与病竟如对待，寒宜温，食宜消，窒滞宜通。此是寒滞阻气，阻痹不便，以温、化、通三法并行，得畅便数次，宿垢顿下，庶能腹痛大减，黄苔半化，脉象宣扬，正是阳明主腑，以通为用。况今气道虽曰：无论虚实皆贵乎通畅，而在实面尤甚，昔贤早已定例。刻下余浊未楚，气机未宣，还宜疏化，毋用通剂。", "11180": "（案4）初诊：邪痧一候，遍体色红，如涂胭脂，邪热分泄，但点粒不清，面部色淡未足，咳痰不爽，烦躁神糊，满口碎腐，汗泻不畅，脘腹板硬而痛，大便溏泄不实，脉濡滑数，舌尖布刺，乃邪不外达，积难下化，化热蒸痰，由肺胃而下趋大肠也。泄则伤气，恐无力托载，邪从内走，为昏闭之变。", "11181": "三诊：便虽两行，俱属不畅，有形之痰积仍与无形之邪火相蒸于表里，充斥于上下，无怪其壮热，烦闷，咳嗽不爽，喉间痰声宛如拽锯，口唇舌色竟如猪肝，满口腐烂，神糊目赤，脘腹按之板痛，脉形沉濡滑数，诸款毕集也。刻下一叶小舟行于万顷波涛之中，险莫甚焉。回思既业医者，何思束手望视，不得不曲运神思，搜索枯肠，勉拟一方，乞得神功默佑，或可有弋获之幸。", "11182": "（案5）《经》云：夏伤于暑，秋必成疟。疟不离乎胆者，犹咳不离肺也，盖咳有声音，疟有寒热故也。是疟已延两候有余，始起似有间日轻重之象，寒总不能栗，热不退清，阳明之病兼涉少阳，不曰似疟，名之起伏，起伏之由病居募原之间，相随卫气而发。古云：暑必挟湿，伤人气分。所以作则烦闷呕恶，非常难过，必然并见。刻下苔色黄而腻，脉象濡数不持，胸次痞窒，甚则觉痛，形似间日之疟，实则为起伏耳。怀孕八月，手阳明司胎，大肠与肺相为表里，胎为热迫，其气乃逆，逆则犹可，窃恐胎动下坠耳。总之暑为热气，胎宜凉安，用药从此著笔，佐以芳香化浊，苟能应手，方可把握，然否？商进。", "11183": "（案7）夏邪秋发，谓之伏邪。伏邪二字，邪根深蕴可知。况今岁，甫交夏天即暴热，吴氏所谓：时未至而气先至，此谓太过。人处其间，壮者犹可运行；怯者从此感受，至秋风而成病。病来寒热无序，起伏不一，汗不遍体，哕恶便难，胸闷烦懊，通宵达旦，无一刻可安之势，从脘至腹按之板痛，乃积膈肠胃之征。脉来滑数而浑，舌苔腻而心绛者，阴分素亏，阳邪独发，夹积阻气蒸浊成痰，内扰肺胃，上迫膻中。年虽不过五外，而早已未病先虚，当此之证，不但用药殊难，更卜其易生变幻。姑拟一方，若得如合其意，或有见长之地则更妙矣。", "11184": "二诊：热势轻剧无序，即谓之起伏。他症无起伏，惟伏邪能起伏者，须从伏字著想，盖伏即进，起即出，能进者能出，人身之气道，昼夜运行，循环不息，昼夜行二十五度以分阴阳。今因伏暑内蕴，邪与卫气并居，虽不能阻其往来之道路，而必随卫气以出入，至其所发，过其所伏。若论轻重长短，视其邪之多寡，正气之强弱。其中夹他病，须随症参切。此症素体阴虚，今为隔食阻气，气有余即为火，昨用大黄黄连法复入清泄气分，便已数行，腹硬得减，脉仍滑而带数，舌转花，淡黄而露底，望之质乾红刺密布，良是滞积下而未清，胃中之津液伤。有限之阴液，难胜无情之邪热，至于热起之时，时候常早，似难捉摸。外来之病犹如盗贼，逐去即安，当此大战之际，对敌之寇，若得散而不聚，应无猖獗之势矣。拟方高明商进。", "11185": "（案8）上吐下泻，名曰霍乱。霍乱者，霍然而乱之谓也。病有真伪之别，真者势不可当，险如朝露；伪者不过寒积交阻，中宫格拒。此症固然非真，上不得纳，便行如水，而今四日，指臂不温，脉来沉濡而滑，舌苔淡黄而腻，乃寒积夹湿，交阻中宫，升降失度，水谷不分。烟体当此，近则恐其闭脱，远则防转为痢。姑用芳开天气，温通地道一法。拟方候商。", "11186": "（案9）年已古稀之外，气液无有不虚。病患暑湿，竟成瘅疟，今已十有二日，热势虽衰，尚未退清。脉象小数，舌色光红，有时神识不清，口渴颇喜得饮，湿因液亏而化，暑由气虚尚逗。大凡暑病之不寒独热者，阳明病也，《经》所谓阴气先伤，阳气独发，良有以耳。刻下虚多于实，正负于邪，古法本有扶正达邪之治，胃气不振，托邪难尽，胃阴不复，饮食艰进，窃恐病去元败，临崖勒马收缰而有不及之叹。姑仿先贤两虚一实之例，然否？", "11187": "（案10）初诊：夫暑为天之气，湿为地之气，天之暑气一动，地之湿气随之，人在气交之中，触目口鼻，内伏而发，秋凉引激，病于少阳则为疟，即《内经》所谓「疟不离胆」是也。病于阳明则寒不能栗，热不退清，虽亦名疟，然必呕哕，胸痞烦闷。是症今五日矣，见象大概如是。而以脉象参之，左部见弦，右手濡数，弦则必有转疟之势，濡则仍居于胃。胃为中土，又为坤地，地气上腾，天气不肃，犹如隆冬之云雾迷空，日光被蔽，胸中清旷之地，宛如烟尘之处。烦躁难过，夜不安寐，势当然耳。刻交成败之际，正胜则邪达，似可日增康境；邪胜则正负，必至内陷神昏，扶正本非其时，达邪诚为要事。古云急者先治，旨哉斯言！但暑居湿下，清之徒然，湿遏热上，开泄为主。治以苦辛，使其气之升降，温芳辟其湿之弥漫，轻淡宣其蕴伏，希能应手而效，尚属立阵布兵之时，何能一鼓扫荡，如邪势折挫，能免变幻，幸矣。备方商进。", "11188": "（案11）今岁甫交夏至即为大热，吴氏所谓：时未至而气先至，乃太过之谓也。人处其间，壮者犹可运行，怯者著而成病。病恰半月，热仍夜盛，烦闷干哕，脘板而痛，遍体透斑，斑色红紫，固是正理，兼晦涩不泽者诚非佳兆，脉来濡滑而数，舌苔淡黄而垢，热由气胶锢不化之时，姑用大黄黄连泻心合犀角大青之法。盖斑与疹、㾦不同，斑宜清化，古人早已示后，原可一例而治，未识符否。备商。", "11189": "（案12）六淫，即谓之六邪，惟暑湿二字，每都连呼者，良由天之暑气动，地之湿气自腾，人处其间，气强壮者自可运行泄化，气怯弱者未免著而成病。病经一旬，热势虽为大戢，而退之不清，脉来濡滑而数，舌苔积白如粉。自汗溱溱，暑可从此而泄，湿仍留恋中土，且素来心力纷劳，肺之液，胃之津，不但不得上供，未免因病益伤也，姑用十味香薷饮出入。", "11190": "（案13）初诊：夏病秋痢虽属趱季为痢，然有其病者必有其因，抑且今岁天符热早，虽非夏行秋令，其气先至，显然人为一小天地，岂不随时更变？此症今恰半月，开手即痢，日夜竟有五六十度，里急后重，红白相兼，谷食宛如登仙，大腹竟似仰瓦，口舌满布糜腐，幸而脉濡沉细。想其肠胃中之积滞早已随痢而去，弥漫之湿热现被胃火充斥，升降失度，上冲则为腐为呃，下攻则为痢为泄。较之阴火为腐者，似轻一层，但年近花甲，症情已属上为实热，下为虚寒，上下宛如冰炭，用药之难何待言者？拟用连理汤出入，应如桴鼓，或可斡旋元吉。候用。", "11191": "（案14）夏令秽湿痹气，触自口鼻曰痧，当时针刮皆由散而不清，遂致似病非病者两月，其间食物必杂，至今变为寒热。热有起伏，寒无定时，舌苔淡黄而厚，脉象濡数右大，腹痛板硬，便泄似痢，腻哕恶，汗少头胀。先寒热而后泄者，古谓经邪入腑，属不顺而逆。夫经者，阳明之表；腑者，肠胃之里。胃为六腑之冠，肠为传导之首，胃病则热，肠病则寒，阳明半表半里，其名募原，募原为病，寒热不分。吴氏有达原饮一法，喻氏设逆流挽舟一法，罗氏参黄败毒一法。刻下经邪未达，府积未通，为疟为痢皆属易易。年适花甲，如不早为驱逐，必致近则内闭外脱，远则噤口昏陷。三子之法从中去取而治，必期应手，方为转机，即请有道政之。", "11192": "（案16）初诊：暮秋至今，天晴不雨，燥气流行，人处其间，感而受病，无有不袭肺。盖西方生燥，在时为秋，在人为肺，一定之理。所以先为咳嗽身热，汗泄不畅，痰白不浓，且不安易出，烦躁狂起，神糊乱语，脘腹板硬而痛，大便溏泄不实，脉来浮滑而数，舌干白而底绛，此风温化燥，浊未成痰与积交蒸，伤阴烁液，肺胃迫近心包，如再进一步则不堪设想矣。症经十有一日，本在波涛汹涌之际，抑恐狂澜莫挽矣。拟方候商。", "11193": "二诊：夹有时邪，治必散解。古人早已立论，盖风温口鼻而入，须从毫窍而出。所出者，汗也。积是谷食而成，定由糟粕而下。所下者，便也。前进麻杏甘膏汤复入槟榔丸一法，得汗透㾦，且已大便，表里似已通畅，邪积应可分化，无如既成时症大病，非一汗透痦，便行一次即可解散，所以势虽稍和，口渴舌干，脐上依然板痛，咳痰犹然不爽，脉滑而数，重按少静，乃所存之邪积仍然化热蒸痰，伤阴烁液。当此两候末期而正在进退之际，抑且邪积半留半化之时，若论其变尚易易，须得小心防护，始能挽入佳境。再拟凉膈散出入，以冀里通表达。", "11194": "（案17）冬令正病皆是伤寒。今因自秋至今，天符亢燥，燥气盛行，肺经感受所发见症，肖乎伤寒而实风温也。夫伤寒乃冬令寒邪，先伏太阳，继则循次传经，延至七日，经尽乃战，得汗而解；而风温一症，始终在肺，夹痰浊者，兼涉阳明，因不传经，故不外战，所以病经一句，表外似达，里热尚甚，咳不扬，痰如沫，神糊语乱，汗泄不畅，当脐膨满，大便欲解不行，脉来闷滑而数，舌苔淡黄而腻，此由风温为浊所恋，浊未成痰，欲化热而未化火，互蕴肺胃。而肺胃居于胸膈，迫于心包，心包为君主宫城，城外既为热灼，神明焉得不乱。抑且病前已见寒热，正气无有不伤，诚恐正不胜邪，为内陷昏闭之变。", "11195": "（案18）《经》曰：夏令汗出少者，至秋风而为疟。疟类有四，其因非一，此症不但发于冬令，抑且间日而作。夏邪秋发，已属隔季为病，安知交冬甫发乎？邪之深蕴何待言哉？夫间日疟者，其邪本不在少阳，而蕴于营卫之间。卫者阳气，行于脉外；营者阴血，行于脉内，而卫气一日一周力，左升右降，循环不息，气为血舟，血随气流行其间，既为伏邪所遏而不能与卫气俱行，邪亦不出，故间日而作。现已逾月，前日尚来，余浊故未扫清，而营卫亦可为寒热也。盖疟者，虐也，久则伤脾。脾统血，统摄无权，便血后发。脾属土，脾病则木来乘侮，以致满腹攻撑，当脐作痛，脉来细涩而弦，舌苔花白而底绛，血见粪后，仲祖谓之远血，此非大肠为病，乃从肝脾而来也。《金匮玉函经》详注最细，用黄土汤一法，补少阴之火，生太阴之土，抑且恐温药性烈，内有生地以益阴，阿胶以养营，冀其刚柔相济，火土合德，统摄有权，则血自归经矣。当宗其旨，略为扩充。", "11196": "（案19）初诊：症交七日，已作一候，起伏太甚，甚至谵语不已，起坐频频，四末乍寒乍热，脉象右小左大，舌苔满黄，大便直泄，伏暑夹湿夹积，颇有不得外达辗转入里之险。盖暑为无形之气，湿为弥漫之邪，同气相求，每伤人气。气分三焦，主宰在肺。肺气开展，则胸中清旷之处或可不成烟雾之天，心居其内方能君主有权，不为暑湿所侵，而致昏闭等险。", "11197": "四诊：人无根株，谷食为命。无病之人，七日不食则不堪下问矣。抱病之人莫言一朝，即二十一天不妨身体者，何也？盖病则邪势充斥，脏腑为其蒙塞，所有一线正气含蓄于内，俟其邪势一退，先以米饮，继以稠粥，使谷食之气接续，正气日长一日，勃然苏醒，犹如春节一到，草木荣华，气满乾坤，此生长自然之理也。至于此症虽未全愈，而已得痊，所谓小瘥也，惟胃气索然，杳不思食，继因服花露一杯，即为便泄，宛如痢然，且甚里急，脉来细弱无神，舌花白而底绛，的系胃经气阴俱伤，脾阳衰而不运，以致不饥、不食、不运三款叠见，生长无权，而欲其恢复难矣。反见神识不慧，两耳不聪，懒言慵事，恙后见此，皆非所宜。姑拟培中土以进谷食，开心气以通神明，冀其渐人坦道。高明商进。", "11198": "（案20）恙延月余，始起寒热夹痢，并驾齐至，延至两旬，即为分娩。夫疟与痢是秋令时病，岂可萃于一身。况妊娠下痢，谚云：井栏圈上钉铜钱，其钱无有不入于井者。胎之堕也，似在正理。然则疟痢久延，气无不伤，复又大产，血分亦亏。所以病至今日，疟意虽轻，痢仍不止，里急虽减，后重依然，且甚觉热，舌苔花白底露鲜红，脉来小数无神，杳不思食，小溲艰涩，乃邪固大半得退，其既化之热与湿浑合，由胃入肠，肠虽多气多血之乡，但缠绵不解，气血早已受伤，而阴与液焉得不为其燥，抑恐胃液告竭，竟至倾颓，转成噤口下痢则不堪下问矣。再转一法，以冀斡旋元吉。拟方候商。", "11199": "（案21）经事甫净，即发伏邪，阴分之虚不言而喻，况邪行如水，虚处则受，幸而年轻气足，尚可迎敌，所以热势夜甚，汗泄不畅，烦闷痞滞，脘腹板痛，大便难行，不甚爽畅，脉来郁滑而数，舌干白而心灰。阳明之邪积交蒸化热，肺胃之阴液无不受其蒸烁。急宜开气达邪，通腑化积，不至阴伤及气，托载乏权，或免昏陷两字。拟方留请有道之士商进。", "11200": "（案22）伏暑夹湿，今交七日，正在充斥之际，适当经事下行，是以神糊谵语，苔加灰色，脉象沉濡而数,心中烦闷不已，气血并病，其险何辞？勉拟桂枝白虎意，参入护里宣开之品，未识符否，明眼商进。", "11201": "（案25）初诊：阴分不足，木火凌金，不时吐血，玩忽未治，致木叩金鸣，咳遂不已，即此而论已足束手。秋间感触风邪，邪入太阴，咳剧凛热，热势稍减，旋即气升，胸间闷，脉数弦，舌红苔白而不甚厚，心胸之间，若有无数凝痰结聚攻劫，而致于保赤丹之猛烈，胸中并未得舒。非痰也，气也。夫肺为气出之户，肾为纳气之源，气但出而不纳，将至肾气日形空乏，暂以重镇塞责，日后调摄须任高贤，非庸者之所可诊治也。", "11202": "二诊：重以镇逆，气升减退什五，喉管结痹，大为宽展，无如呼吸之气依然入少出多，内热虽觉退轻，仍不能静，脉犹带数。勉再镇堕以冀喘平，调理功夫，务再择贤而任耳。", "11203": "三诊：重镇之剂，喘退什五，原意继进，理应续效，岂意初投则如桴应鼓，继进如石沉海。无论在肺在肾皆与中枢无涉，何至食入而脘中不舒，脉细数而关部带滑，舌红咽腻苔白。良以肾本亏于下，肺气壅于上，胃中之痰湿为热气所激，复注于肺，致肺胃下降之权全失，再从前意兼导湿热下行。", "11204": "（案28）经停七日，迩日汗多如雨，饮食减少，内热不退，右脉细涩，左脉弦数，屡投益阴固卫之品，未见所长。拙见经因病而不至者，非瘀也，虚也；汗不醒寐而出者，非虚也，火也。既非停瘀不必以攻，知是火迫不必以补。古云：先断经而后身热者，为干血；先时症而后经停者，为血亏。盖血属阴，阴为水类，气属阳，阳为火族，火烧则水涸，即所以益水灭火，必籍以苦寒。仿古四法之一。", "11205": "（案29）按脉中空边实，来往不利，此名芤涩，涩则有瘀，芤则血虚，胃络震动，诸经失养，不可堵截，且用和络。", "11206": "（案33）风温蕴肺，咳热并重，两感之症非轻可知，肺病逆传，必至心胞，脉数舌红。辛凉佐以甘寒方与春令风温合宜。", "11207": "（案34）大便两行，极少积滞，尚未尽下，脘右按之犹痛，哕恶稍减，汗仍未得，所蕴之邪亦未外赴，是以午后寒热仍起，起则烦闷更甚，脉来濡数，舌苔黄腻，症经九日，本在波涛汹涌之际，其势不剧即是退机，姑观两候期上动静，拟方候商。", "11208": "（案36）《经》曰：脉来数而中止为促，促为阳甚阴虚之病，咳热痰红而见此脉，推因外风入肺，已经化火内炽，古云水出高源，源病则水必日涸，凡为痨瘵者，比比皆是。", "11209": "（案37）久咳见血，本属极易之事，盖咳则诸络皆震，肺络受伤，则血溢于上。左脉弦数，咳血所忌者，有木火刑金之势。", "11210": "（案38）风入于肺，身热咳嗽，已经两阅月矣，脉数而滑，舌红而光，邪不外达，势欲内传，古人有咳嗽而成劳损者，此之谓耳。", "11211": "（案46）血败之后，淋沥不净，脉数内热，舌苔黄腻。是气虚血热，夹浊内阻也。", "11212": "（案47）寒轻热甚，头痛无汗，腰疼项强，脉形紧数，宛如巨阳初症，例用麻桂，然时当暮春，舌渐干黄，温邪为新邪所伏，宜用葛仙翁肘后葱豉煎之法，方不背于先贤。苟能应手，方免喘惊。", "11213": "（案48）初诊：花后气血两伤，外邪易入，咳热半月，右脉数大。乳儿当此，喘惊极速，慎之慎之。", "11214": "二诊：花后元虚火盛，玄府易开，卫不固，风温凑袭，咳热痰鸣，脉数舌干。辛凉佐以微苦，既得其效，当仍步其议，谚所谓：效边求是也。", "11215": "（案49）寒热无序，咳久不已，左脉大，舌黄腻，邪尚在肺。盖肺胃为卫气之主，尤能克制肝木，自然卫虚则邪易出入，肝横则腹满胀痛。前方既应，再当扩充而投。", "11216": "（案1）向来精神健旺，习于操劳家事，素无所苦，惟左足大指时常发麻，近连右足大指亦或发麻。考之丹溪、东垣诸论，谓麻属气虚。而足大指乃肝脾二经发源之地。今麻已一年，且渐延至足胫，是肝脾二经气衰而血亦耗，恐有风痱之患。《内经》云：肝藏血，脾统血。血虚则火易旺，故齿痛，兼生牙痈。血因痛而愈耗，遂有心悸不寐等症。近来闻响动心即惊跳，或遇恼怒，彻夜无寐。若使此夜不眠，明日诸疴竞作，盖不寐则阳不入于阴，阴愈衰而阳愈亢，种种不安矣。麻发之时，自觉头目虚眩，此血不养肝，肝风内舞。治法必以养血滋肝为主。而血从气生，须兼培补元气之药缓调以图渐痊。诊脉左手细涩，右寸大，右尺不应。先用宁神补心汤加减。", "11217": "（案3）谷纳渐减，步履如蹈空，此下焦衰乏，恐成类中之病。诊脉左大右软，宜补心脾。", "11218": "（案4）失血亦不过多，而左手麻木，午后神昏，视其气象，殊非憔悴羸瘦者比，则昏麻二症，乃内有积痰，肝风鼓动，上蒙清窍，将来痱中之机也。脉浊右手如促如动，往来之间，如有阻滞，痰血郁于隧道耳。宜补气血以疏通之，使其渐轻可也。（其病更有纳减便溏。）", "11219": "（案6）头眩，左肩臂麻而无力，是中风之兆，脉细。宜补以散之。", "11220": "（案8）当风淋浴，以致口眼㖞斜。虽用药得痊，而病根三载未除，近加吐痰，肋时痛，以风邪散入手足太阳阳明之经。脉象左弦右滑。宜大追风散加减。", "11221": "（案2）徐，二十。脉右大，脘中爽，口渴，肠风。", "11222": "（案3）凌，五五。木火形体，善动少静，操持拂郁频多，阳虚失卫。怕风畏寒，气塞不行，脉络痹痛。议补益阳气，疏通经络，勿令其痹。", "11223": "（案5）王。据说鼻塞若用力屏气，速耳窍失聪。左胁骨高突。气辛开泄，暂用不得除根，验脉是经络气分之阻，当以轻清为治。", "11224": "（案1）《内经》云：耳者宗脉之所附。又云：身中精阳之气上走于目而为之晴，其别气走于耳而听。此时目无神采，耳听不聪。由邪混三焦，出入靡常，忽轻忽重，反复变迁所致。脉象左手浮，右手虽略小而重按有力，知非阴症与虚寒，其躁扰不宁，乃湿痰挟伏邪，胶黏难达，则宗气别气隔塞不通耳。仲景栀豉汤乃宣达阳明伏邪之药，故以涌吐为法，用之而得效者，邪亦稍得舒泄也。此方甚善。但邪不仅在阳明，未必遽能霍然。兹仿达原饮之意，略为变通，冀其烦闷渐松，自当渐入佳境。", "11225": "（案2）夏日曾患痢疾，又于酒醉后仆水，此暑湿之邪蕴结已久。中秋加以感冒，遂寒热如疟，咳嗽吐痰，热久不退，身面发黄，是外邪合身，内湿热酿所致。向来体丰好饮，伏痰必多，此番纵啖生冷，痰与邪俱郁闭不通，故昏沉躁扰，神气蒙混，有如厥中之状。消痰滚痰，二便渐通，心神稍清，但舌本淡白，舌苔白厚，口仍作渴，四肢微冷，中脘痞硬，面黄带浮，尚属湿痰伏热未清。脉象沉弦，亦由邪陷，未可遽视为坦途也。治法当以利湿消痰为主，而兼透达伏邪之药，使表里宣通，清浊分疏，乃无反复耳。", "11226": "接方：清晨诊候左脉弦大有力，右脉细、软无神，此伏痰与邪胶黏不散，占据清阳之地。所以胸口板硬，即《伤寒论》中所谓结胸也。痰与邪既相结聚，正气不能流通，故右脉不能充沛而神色如昏如清，舌苔如灰如白，病情尚在出入之间，必得胸中宽松，面色红活，乃无反复。", "11227": "（案4）赤斑白疹密布周身，口渴发厥，躁扰不宁，而唇淡舌白，此邪毒未透，尚防反复。右关脉滑，体素丰肥，乃痰与伏邪合，风暑为患。宜化斑解毒佐以消痰之品，但得午后热不加重，即可渐松。", "11228": "（案5）身热不退而舌苔极薄，唇齿不燥，亦不作渴，则非阳明实热之症矣。常有噫嗳，兼带呃逆之象，里虚邪不能达也，略有谵语。合之脉右洪数，清补两难，养阴和胃为妥。（此症不治。）", "11229": "（案6）身热，口渴，烦躁，舌干，此阳症也。脉细，乃体质素虚，非阳症阴脉之比，但虚者不可过于攻击，宜养正清热为主。", "11230": "（案7）寒热如疟，中脘痞结，脉象左手弦数，右关滑大，是邪在阳明少阳，宜和解之。", "11231": "（案8）午后热重，口干，便赤，目黄，胸满，多汗，脉弦滑，少阳症。", "11232": "（案9）身热两月，无汗，舌黑齿燥，泄泻，危候也，脉小而滑。姑与河间双解散。", "11233": "（案10）身热不退，神思倦怠，左耳渐聋，舌白腻滑，胸中按之作痛，无汗，不渴，此表邪未解，挟中焦痰食为患，右脉滑数，宜清理阳明。", "11234": "（案12）少阳邪郁不解，内走而入厥阴之络，胁下支结，内热无汗，诊脉弦细且急。宜宣达肝邪。", "11235": "（案13）夏秋时行之病，原属客邪郁伏，汗出已多，邪当解散，乃自秋徂冬，身热不能尽退，近则午后寒热，寒重热轻，宛如疟状，迨汗出而热渐减，却仍不净。诊其脉象尚带弦数，但左手空软，右关滑大，此营阴已亏，阳明犹有痰气阻滞，所以胃脘左畔结硬成块，幸不作痛，惟按之坚硬，仲景少阳篇中所谓心下有支结也。此块不除，寒热不止，仲景本用柴胡桂枝干姜汤，今宗是方加减，可获愈。", "11236": "（案14）每夜热发，舌黄，口苦，脉象左弦右细。此营阴虚而少阳之邪未解。", "11237": "（案16）汗不出至足，营卫未和也。热已退而谵语，邪留心络耳。左脉犹弦，宜清养之。", "11238": "（案18）齿燥，舌干，神昏，口渴，乃热邪内陷，蒸灼津液而为痰，痰迷心窍，诸药不应，危候也。脉虽细，尚带滑数，宜清解之。（此证不治。）", "11239": "痰虽吐出，神犹昏愦，齿燥舌干，燥而不烦，皆至危之候，脉右滑数实，宜再下之，以图侥幸。", "11240": "（案19）伤风与痢疾同病，已属重症，况热久不退，痢下如蟹黄，兼紫血一团，邪火内燔，胸前痞闷，嗳呕不断，咽痛，口渴，肝叶胀痛，病多且深，殊属可畏，脉象左手弦细而类数，右手滑实而数，宜用血药加苦寒以下之。大黄黄连泻心汤合四物加减。", "11241": "又，身热颇轻，痢热亦减，俱为佳象。唯喉痛不退，痰涎上涌，视其喉间，两边白腐，乃喉痹也。一人而兼三病，所以难愈。今幸脉数稍缓，脉大稍平，重按尚觉有力，仍宜养阴清热，化痰解毒，可望渐安。", "11242": "（案20）向来精神不足，又兼蚕事劳顿，里虚而受客邪，寒热咳嗽，当时即宜避风静养，及以丈田出门，复风热之邪，邪乘虚而入，病益加重，身热不退，舌干苔黑，气急咳频，饮食不进，身上斑点未透，耳聋，齿亦干燥，是为真阴久衰，客邪内陷，殊非轻病。盖先曾鼻衄、便红，血虚则难作汗，此时形瘦，舌干，津枯则难退热，由伤而兼外感，用药殊为棘手。诊脉左手弦大带数，右手大而柔软，本虚标实，非提斑清火所能愈。惟有滋肝润肺之法，使木不燥则火不亢，金渐清则水渐充，庶望转危就安。", "11243": "（案21）彻夜看弈，已受阴寒之邪，又伤于食邪，与食结则神昏谵语，此亦不足为怪，但脉象沉细模糊，手足厥冷，躁扰不宁，舌红无苔，乃夹阴伤寒也。病前必犯欲事，阴邪必入于阴分，所以虚象火象合并，而现补之不可，清之不应，殊为危险，计惟。（以下恐原本本缺，以下所接之方亦非也。）", "11244": "病家来札云，犀角地黄汤服一剂，因病人不肯服药，暂止二日。然神色终不清，仍有谵妄搐搦之象，于原方少加制黄，服一剂，亦不见病之进退，然是夜更加发厥，口中糜白如鹅口。次日频进参须麦冬汤，至下午身有微热汗，次日又服阿胶黄连一剂，以后宿瘀渐止，神识亦清，夜忽起呃逆，服竹茹生姜合参麦冬而止，以后服养阴清热三四剂，口糜仍不退，反见咽干痛，因用甘露饮加黄连一剂，停药三四日，口糜已退，惟喉内尚有白点，耳亦能听，神气亦得清，饮食亦进，惟痰尚盛，声犹带嘶，时觉起坐不宁，脉象左弦软带数，右寸数而关尺细软。不大便已六七日矣，恐调理失宜，再酌一方。", "11245": "（案1）王润堂太太。今夏暑湿热甚而久，暑属无形，吸受其气，必入卫营，壅塞不行，则为痈疡，肢臂不举，经脉痹阻，热毒无由开泄，理必燎灼络中，络脉丽乎脏腑，烦躁腹胀，不食不便，热邪充斥三焦，彰明较著，夫蟾酥梅花点舌丹大辛大热，加以诸香，以之攻阴寒沉痼，方为对症，以之治暑热致痈，反为邪树帜矣。即参耆归芍只可调气血于邪尽之后，不能解热毒于方盛之时。病机十九条之诸疮痛痒皆属心火，诸痉鼓栗，诸胀腹大皆属于热。然久热必从燥化，形质暴大盛为消也。苦寒化燥，未可轻投，宗景岳玉女煎法。倘大便久闭，《局方》凉膈可暂用一服。", "11246": "（案3）恶寒，发热，咳嗽，盗汗，右脉无神，姑与建中汤。", "11247": "（案4）自八月至今已六十余日，其间寒热参差反复，而热退之后仍不能进食，口苦无味，唇燥舌苔，此余邪未清也。近来又发寒热一次，寒时小便涩痛，热时精漏不固，是元气大虚，脾肾两衰。皆因从前白浊已久，精关所以频滑耳。诊脉左手弦急，右手细软，亦为正气亏乏，邪气留连之候。治宜先清理，接用补养。", "11248": "（案5）左尺斜出脘侧，是为阳维脉，《内经》为阳维为病，苦寒热。今舌不退，而呕呃臭水，此难治之候，姑与镇降法。", "11249": "（案7）上年下痢，今春寒热又无定期，舌苔半边蓝半边红，此气血两伤也。咳嗽，盗汗，昨又咯血，脉左弦细，右寸软。宜仿双解饮子法。", "11250": "（案9）身热，呕吐，泄泻，兼发风饼，脉弦带数，暑风袭于阳明也。", "11251": "（案10）身常寒热，汗出如旧，饮食如常，夏月痊安，春秋反发，此外寒束其内热也。脉细，右手带滑，宜古方地骨皮散。", "11252": "（案11）病后微有寒热，盗汗，干咳，胁胀，溺赤，脉带弦，肝阳上扰也。", "11253": "（案12）仲夏疟疾，近复发热，心忡耳鸣，不食，左脉细涩难寻。此气血两衰，高年之重症也。", "11254": "（案13）向有咳嗽内热，乃阴虚体质，所以形瘦食少，已具怯症情形。七月前忽发寒热，过十日外竟不止，其热左边尤甚，夜间则周身壮热，舌干，耳聋，又加泄泻，脉左手弦细而数，右手细软。此以虚损之本病而兼外感之客邪，殊非轻候。盖前月余夜不能寐，身中酸楚，安乃血虚火扰，致起寒热，病中复感微风，热遂不退，热甚则干渴引饮，脾弱不能分渗而泄泻。今若清理客邪则真阴愈涸，热仍不去也；若滋养真阴，则滑润大肠泻必更增矣。病势之重在乎此。就脉论治，当扶正以托邪，庶使元气不陷，则伏邪自透，方可向安。", "11255": "（案7）计，廿七。体质阴虚，当夏秋暑热内侵，客于膜原，致寒热不欲纳谷，诊得阳明脉大，用养阴清暑方。", "11256": "（案8）王，五七。丰腴体质，适值过劳，阳气受伤，呕吐食物，身热而无头痛，已非外感风寒，间日烦躁渴饮，唇焦舌黑，是内伏热气，由膜原以流布三焦，亦如疟邪分争营卫者然。然积劳既久，伏邪客病，脉来小缓，按之不数，可为征验，且二便颇通，略能纳谷，焉有停聚滞积？仲景于痹热无寒之条不出方药，但曰以饮食消息。后贤参入圣旨，以甘寒滋养胃阴，其热自解，要知表散之辛与苦温苦寒，沉降消滞，俱犯圣戒矣。", "11257": "（案2）病后咳嗽，背恶寒，而脉弦数，舌苔微黄。此表寒热之候，法宜清解。", "11258": "（案3）背寒为肺虚，亦即卫阳虚也，乃脉不软而弦细带数，丹溪所谓恶寒非寒是火郁故耳。右脉独弱，下焦根柢衰矣。卫出于下焦，藩篱既撤，汗多寒甚所由来也。阴必生阳，阳必乘阴，宁无寒热之虞乎？救阴固阳，庶免阳越阴枯之患。", "11259": "（案5）右脉尚大而恶寒，仍属火郁，宜用桂苓甘露饮。", "11260": "（案6）病后畏风，精神疲倦，右手气口脉大于入迎，正合东垣补中益气汤症。", "11261": "（案2）咳嗽则头巅作痛连于脑后，此下焦龙火因督脉而上，金受火刑，不能生水，故目光昏花，骨节酸痛。法当潜纳虚阳。", "11262": "（案3）足少阴脉循喉入肺，足厥阴之支脉贯膈注肺。凡人肾气充足者，声音高爽，肾气亏损，声音低飒。不独金实不鸣、金破不鸣二义也。", "11263": "尊恙于烦劳之后，半夜忽然声喑，清理渐愈，越数日喑又如前。知非外感为病矣。劳心过度，心肾不交，水下心上，金受其刑。又加恼怒，肝阳直射肺中而肾脉不上循于喉咙，火位之下，无水承之。《内经》为内夺而厥则为喑痱，此其类也。今足冷面热，脚膝无力，夜不能寐，口干咽燥，全是下焦衰乏，阴精不主上涵，治肺无益，法宜补肾。右脉衰于左脉，六脉俱带微数。阳药难投，定当以壮水固金为主。", "11264": "（案4）肾开窍于二阴，其脉上循喉咙，或便结，或咽痛，或精滑，皆肾阴不足，相火内扰所致。", "11265": "（案6）水不涵木，木复生火。刑金，则清肃之令不行，面手渐肿；凌脾，则运化之脏失司，谷纳日减。每交丙夜，气升烦热，更兼癸汛频来甚少，此景岳所谓子午不交，阴竭阳孤，至危至险之候也。脉细而数，清补俱难收效，姑用潜阳镇肝方，以图侥幸。", "11266": "接方：火升未降，自觉内热（原作蛰）心即欲呕吐酸水，兼之目赤唇红，左乳缩小，总属肝阳亢极，火盛而水不能济，病情变幻愈多矣。大便溏泄，经频带下，木火交煽，脾伤肾涸，犯及奇经也。左脉弦数。依前法加直折肝火之品。", "11267": "（案7）冲任二脉与肾脉同起于下焦，肾虚则冲脉上冲，丹溪所谓火起于九泉之下也。肾热故玉关不闭，精常漏泄，虚阳上越，不肯潜降，所以面红舌糜，两足冰冷。肾脉循咽络肺，肾中真阴耗竭，其真阳无所依附，随脉而逆行，则咽燥肺焦，故声音不能朗亮，此皆本原重症。《内经》云：一水不能制五火，又云：诸逆冲上，皆属于火。斯症是矣。头眩者，肾火亢而肝火亦动也。治火之法，首辨虚实。此系虚火，断非旦夕所能平。脉象弦劲且大，幸不快数。须以甘寒之药滋养收摄，尤当耐性宁心以静镇之，使五志之火不生，则真水渐可积蓄，而诸疴徐退矣。", "11268": "（案8）此是少阴咽痛，盖肾脉络肺，肾水亏而坎中之火直犯肺金，肺热叶焦，脓血交出，肾脉上循喉咙，火亦上升不降，乃为咽痛，致险之候也。脉软而数，滋清无益，勉与仲景猪肤汤，以图侥幸。", "11269": "又，阴虚之病，脚软者不治，以足三阴之脉起于足，足痿且麻，三阴脉绝也。声喑咽痛者不治，以金为火烁，清降失司也。蒂丁下坠者不治，以元气耗败，脾肾两衰也。今兼诸症，药何能为？", "11270": "（案12）虚证势难愈，而脾肾两虚尤难兼顾，盖补脾药多温燥，补肾药须凉润也。今脉数象稍和，右寸仍然数大，水亏则肺热，肺热则痿，尚当以补肾为主。", "11271": "（案15）左脉细软无神，心肾两虚，头眩体麻，腹痛如欲泻状，是虚阳上扰，下焦不能吸纳耳。用阴药则碍脾，且仿潜阳法以变通之。", "11272": "（案17）脉数无神，最非佳兆，体倦食减，固由于元虚脾惫，补之犹恨其晚，无奈阴枯液涸，有壮火食气之患耳，姑与调停法，重补轻投可也。", "11273": "（案18）手战不可持物，舌痿不便语言，饮食大减，脉细无力，此大虚之症。右手痹痛，右足无力，有风痱之象，脉细，宜补。", "11274": "（案19）梦泄之后，咽中窒碍，两足无力，此肾脉不上循于喉咙，内夺而厥，虽未喑已成痱矣。纳减作胀，后天又衰，脉带数，真阴难复，非药所能奏效也。", "11275": "（案1）脉象左手寸尺细软，关部独弦，右手三部洪滑，关部尤甚，此平素心肾两虚，近则阳明痰火未清也。肾主水，水衰不能滋养肝木，以致肝阳易亢，怒火易升，而心君位司离火，又须坎水交济，水不足以制火，故向有背偻起及胁痛、吐、瘀等病，更兼操劳家政，烦劳太过，五志厥阳之火上扰，则五液为其煅炼而成痰火，与涎互相击搏，值今暑令忽发如狂之症，此与本病不同，所谓本虚而表实也。近已深秋，金水用事，则阳火渐降，病乃向愈，然余波未平，故肝胃脉偏强，现症口渴，便坚，溺赤，心烦，夜梦纷纭，肺俞中脊胀闷，均系痰火聚于肝胃之间，法当先清后补，标症既平，方可滋养心肾以为调理之计。", "11276": "接方：背上筋脉牵急，以冷洗手，自觉冷彻于背，即饮食入胃，亦著背而下，此皆积痰变幻，今脉象渐和，惟右关独大，仍宜清阳明。", "11277": "神昏如，牵掣如痉，脉细而弦劲，是水不涵木，肝木动摇，非比实症易治。", "11278": "（案3）寒热如疟之后，忽然神识迟钝，兼有盗汗，脉象左细右弦滑。此血虚而夹痰为病。", "11279": "（案4）病后目黄脚麻，神识呆钝，而饮食如常，肌肉不瘦。此湿热生痰为患，脉象滑大，清理可愈。", "11280": "又，左脉仍数大，右脉略小亦数，用清火消痰不应，由水亏无制火耳。议养阴兼渗湿。", "11281": "（案1）间日疟原非重病，但疟发之前口渴，疟发之后渴退，是邪伏于内，以渐外达，其势不能遽止。恶寒汗冷，脉沉弦数。宜和营卫以达邪。", "11282": "（案2）疟以禁止，邪从内传，遂发不退，面目黄色，饮食不进，脉象虚数。此温热为风阳煽动，法宜清理伏邪。", "11283": "（案3）疟来间日发不移时，邪留募原，不能与卫气偕出也。脉象弦迟，寒多热少，宜桂苓甘术汤加清散药。", "11284": "（案4）疟频发，谓之疟，邪留血分也。左脉弦大，右脉细软，和血以托邪则愈。", "11285": "（案6）但热不寒，胁痞，盗汗，脉而弦，法宜和营。", "11286": "（案8）疟病频作，身痛脉细，小劳即诸病皆来，虚故也。", "11287": "（案9）脉系侧关，界限难明，但细数无力，虚象显然矣。三阴疟久，因劳而连绵，身热兼咳嗽、喉痛，肺脾两伤，势必发肿，以避风静养为主。", "11288": "（案10）久疟延成劳怯，咽痛干咳，咳甚则恶心欲呕，此即劳疟之基矣。脉细，右寸关沉滑，是上年暑气伏于募原，渐传肺胃二经耳。宜清理，勿骤滋补。", "11289": "接方，服清理药，咳嗽咽痛不减，每交午后咽中如有物升，即燥痒欲呛。此由肾脉络肺，肾家水亏火旺，故循脉上冲，乃损症机关，即心嘈亦属火烁胃阴，自宜固本为主。", "11290": "（案11）三疟久而寒热日作，此营卫两伤，乃虚候，非变轻也。面浮色淡，全不纳谷，为脾败之象。咽痛，脉数带弦，则难投补剂，病势殊深矣。年犹未冠，尚属纯阳之体，姑与清养法，以望转关。", "11291": "又，寒热仍归三疟，此亦好处。左脉弦大，咽喉尚痛。宜滋肝补肾。", "11292": "（案12）三疟虽轻，两次发，脉象细软无神，乃大虚之候。", "11293": "（案13）疟疾四作，顿然形瘦，腹胀，脉象细弦，是土败木贼也。", "11294": "（案14）疟后心中冲悸，脉象左大右小。此元气阴不足，阴为火扰，宜补中寓清。", "11295": "（案15）三阴疟久，止才一日，发恰两日，此营卫俱伤，正气不能主持也。汗多脉软。治宜补养兼之。素有梦泄，下焦亏损，虽补不能速效。", "11296": "（案16）扬州黄府癸丑五月初七日诊。太翁向来阳虚体质，今癸丑岁湿土司天，寒水在泉，交芒种三之气，脾胃主候，遂发疟，初起寒胜，继而热胜，夫脾应乎营，胃应乎卫，二气遍造，邪正相乘，遂为寒热。诊脉右大少神，食纳不甚舒畅，略有嗳噫，如呃之象，汗出肢冷，溺频便溏，全是阳微少振。拟温理脾胃之阳为主，不必多歧缕治。", "11297": "初九日，凡疟邪由四末以扰中，胃最受戕，而胃为阳土，其用乃阴，疟热乘中，胃津被耗，理必烦渴，嗳噫，气逆上冲，皆劫津所致。脉数、舌赤，己见一斑。高年温补阳气，固本何疑。今以客邪未除，气从热化，只因体质阳微，不敢沉降清邪，姑与生津养胃，仿古酸甘化阴一法。", "11298": "初十日，寒热减半，舌心微黄，渴饮嗳气。诊两手脉来虚数，是胃中不和，津被热燥。议用《金匮》麦门冬方，养胃汁以供肺，兼治痰气蒙神。", "11299": "十一日，寒热未来，诊脉濡缓带涩，与昨诊数虚互异，此寒热稍退之象，第夜来寐不安逸，脘中痞闷，谷食无味，便泻两次，滑不自主，凡五窍不和，都属胃病，寒热从四末以交会中宫，胃当其冲，受困可知，夏至大节，脉症渐平，未必非调理中窍所致。今日议进温胆法，以胃属府喜通故耳。", "11300": "十二日，前晚寐寤不安，胸脘痞闷嗳噫，因思寒热邪乘，脾胃阳气健运失司，议用温胆汤理痰气以和中，服后胀减寐和，诊时正寒热初来，脉形小弱，是阳为邪郁，寒退自当复耳。再思中下皆虚，虚则邪陷难解，议以分治之法，午余服延年茯苓饮，理痰运阳，培扶脾胃。天明进露姜饮，壮气攻邪，三服可以止疟。至于小便不爽，高年虚人常有之证，勿用渗利再伐下焦。昨云九窍不和，是都属胃病也。", "11301": "十三日，两日议进通补，一理脾胃，一益气攻邪，已有小效，诊脉右虚软，左微弦而涩，歇亦少减，仍以茯苓饮方。", "11302": "十四日，连日进通补却邪方法，诊脉验症颇安，但病伤可复，而平素操持萦思，积劳致损，必须潜静旷达，方得生阳充沛。谚云：心病还须心药医也。若仍烦劳不节，斯心气愈伤，脾营更耗，必至病端蜂起。至若调摄药饵，全以后天脾胃为主，勿费多歧纷缕可也。", "11303": "（案18）□□□□面黄，苔白，脘中格拒，汤水都呕，三日疟一至，据色脉症，乃足太阳阴微饮结，当以温药和之。", "11304": "（案25）钱，五十。少阴疟两月，胃关衰不纳谷，神消形瘦，攻补不应，宜举八脉之阳，阳壮邪可托出。", "11305": "（案27）钱。三疟日久，奇经损极，邪乘攻络，血从便出，病为伏邪，而参苓乃理胃之品非锢邪之品。救逆汤，仲景治火劫惊狂阳亡外越之症，其意重镇之中引以飞走，由表由经脉以固束。余曾用之以治阴疟。至柴葛泄阳，尤非八脉方也。", "11306": "（案31）朱，四三。劳倦阳气先伤，营卫皆损，疟无止期，自述天暖可缓，阴晦病加，身中阳微已著。与壮脉护阳。", "11307": "（案32）杨，廿八。邪伏于阴，而成三疟，表散不应，脉缓，中焦痞闷。治在太阴。", "11308": "（案33）罗，三三。疟日发既而间日，寒多无汗，食进不运，诊脉缓濡，此阳微邪陷于阴，寒起四末，从太阴治。", "11309": "（案37）某。阴疟经年，寒热必喘逆痰升，左脉已结疟母，病在厥阴、少阴，邪混气血为难治。", "11310": "（案43）张。三疟屡止屡发，时见右臂、肩背、胸胁肿凸，旬日自散，络脉不和，必安间静养可愈，药未能速效。", "11311": "（案44）吴，三三。凡疟久，邪结必成疟母瘕，其邪深客于阴络，道路深远，肌肤无汗，能食，便溺通调，病不在府，从腹下升逆，贯及两膝腰中，推及八脉中病，理固有之，然立方无捉摸，议仲景转旋下焦痹阻例以通阳。", "11312": "（案47）居，廿八。脉右沉濡，左弦，疟经两月，止而复来，食入便出，腹中隐痛，宜谨慎食物，正馁邪陷，有三阴延绵之虑。", "11313": "（案50）叶，四一。诊脉右小弱，左空弦，视形色枯槁不华，舌白不渴饮，病及一月，寒热，干呕，神气欲昏，微呃，烦不欲寐，汗出。此伏邪久而伤正，阳气日漓，邪陷入阴，胃虚客犯，当邪乘攻触，见此昏烦呕呃，议温胃阳益虚镇肝逆，逆理呕烦，用旋覆花代赭石汤。", "11314": "（案51）张，四三。三疟，背寒骨束，并无汗战呕逆，治在少阳督脉。", "11315": "（案52）金，二十。太阴脾土性畏寒湿，暑湿既在深阴，疟三日一至，饮酒再助其湿，疟痢兼作，但肛坠而肠胃不痛，脉来濡弱，当理湿以生阳，用桂苓甘露饮。", "11316": "（案56）瞿。失血数载，经脉久空，瘅寒无热为牝疟，每发于阳气不足之人。柿味甘寒，蟹味咸寒，阳失行宣，是皆左券宜乎？日加寒懔而血络并逆矣。", "11317": "（案58）姚，十八。脉弱小促，疟不肯止，皆辛散过投，卫伤则寒，营伤则热。用补中益气汤，数日可愈。", "11318": "（案1）顾，三四。阳虚之体，迫受暑湿，气分窒塞，脉濡，舌白，头胀，心悸，口渴。治以桂苓甘露饮。", "11319": "（案3）祈，五二。脉缓濡，夏季过饥，吸受暑湿，膜原浊痹，清气不宣，脘胀腹满，阴囊、足跗皆肿，得泄气少舒，湿与热传至经腑，当分消其气分。", "11320": "（案6）时。刮痧震动经脉，体虚不耐，颇觉不安，亦无妨害，但暑湿皆伤气分，气无形质，流行则邪解，今以六味填阴，滞浊暑气，恐无此方法。", "11321": "（案7）钱，十六。脉左小坚劲，色苍，形肿，当午热灼口渴，晨必微寒，食物皆减，此暑邪乘虚致病，状如疟症，因吐血屡发，表散非宜，姑以玉女煎方，得热止再议。", "11322": "（案9）俞，四六。脉小，舌白，小溲淋闭，大便不爽。仍流此暑湿著于气分，气阻窍窒。当治其上，以水出高源也。", "11323": "（案10）沈，四七。阳虚不喜凉食，气阻膈间，脉沉，目黄，必有冷湿之气内著，用辛温补通之。", "11324": "（案1）无端眩晕仆厥，移时方醒，今面目黄色，口干溺赤，脉象左细右滑。此心肾虚弱，外受暑湿之邪，暑为火，湿生痰，故病形如类中。法宜与清理，继以补养，乃不复发。", "11325": "（案2）病后发厥，神昏口噤，痰响涎流，此五之类，脉细无力，乃虚也，补之则愈。", "11326": "（案3）头重如欲晕倒，冷汗大出，手足厥逆，脉细，右手尤觉微渺，舌苔白，起病不过八九天，小便不利，正值夏月辛苦作劳之时，作暑厥治。", "11327": "（案4）吴，三九。厥阴气冲昏厥，都因阳明脉虚，通泄和阳不能却病，议填胃土以熄虚风。", "11328": "（案10）某。诸动属阳，劳烦则扰于气，肝司藏血，拂郁则血菀于脘，午后气并于血，升降清浊为厥，脉来浮数而细涩，面黄唇白，热势少轻，神昏如故，胸腹隐痛，必非停滞，诊有瘀聚所致；目荒、舌缩为肾水竭绝之征；瘛疭不止，乃肝虚风动之象，病名暴厥。养葵所谓薄厥、煎厥之类。开心包不应，勉蒲黄散去瘀舒郁，续进滋养天一之水，以冀风糜火熄，此属不得已之想，未识以为何如。", "11329": "（案1）癫之症脉大易愈，脉细难痊。今脉细而目睛无神，交夜糊涂，口渴，是病在重阴，不能去根矣。", "11330": "接方：恼怒则肝火炽盛，又加惊恐，则肝胆俱病，木火交亢，以致癫妄神昏。今虽稍轻，而脉左弦右滑，是火郁生痰之故，故筋惕而胀，亦属肝火煽风。法以抑肝清痰为主。", "11331": "（案2）风乃难愈之候，脉数带滑，宜先清其痰。", "11332": "又，势稍轻，未能脱体，左弦脉尚存，宜佐以圣惠三丸。", "11333": "（案3）足麻至心，即神昏痉搐，喉有痰声，此症也。脉细而沉弦，宜归脾汤。", "11334": "（案4）肝风内舞，痰因火升，左边头顶、手足、肩、腹俱有牵绊之象，盖厥阴经脉所过地部皆为痰火缠扰也，痰火不清，症必然复发，清心戒怒，静养可痊。", "11335": "（案1）舒气稍长，胸脘即痛，仲景所为短气不足以息者，实也，此实字指痰饮逆气而言也。尊恙恰合是条，右脉细弱。法当温通。", "11336": "（案2）少年即有郁症，生阳不能舒布也，加之惊则肝胆亦病，自然寐少寤多，盖阳不入于阴，血不协于气也。今届六旬之外，血更衰，痰渐生，胸膈右边不能融畅，便燥，臂痛，著衣不便，鼻亦不知香臭，此由气馁则痰滞，升降出入之机针废弛，恐为厥中根基。诊脉左小右，宜补心脾，化痰利气，使营卫流通，乃无大患。", "11337": "（案3）怀抱不舒，气郁于中焦，五更将交寅卯时为木旺之候，故肝阳上冲，喝喝如太息，间有腐臭者，郁则成火也。脉弦带数，宜清理肝肺。麦门冬汤：", "11338": "（案4）心热汗出即不得寐，舌苔黄厚，又不作渴，脉细左弦，是心肝郁火症，病始齿痛。理宜壮水。", "11339": "（案5）腹鸣而气上冲心，此厥阴症也。脉右沉左弦，沉则气滞，弦则木郁，郁则少阳生气不伸，怵惕忧虑自不能禁，病由肝而及心肾。宜开宜镇为治。", "11340": "（案1）头眩脉弦，清晨呕痰，此肝阳上扰兼酒之湿热生痰助火耳。", "11341": "（案2）头眩心跳脉而软。", "11342": "（案3）头重眩，足软弱，左脉细而弦，是肝肾虚症。", "11343": "（案5）宋，四十。操持烦心，身中阳气多升，肝胆相火内风震动莫制，遂有眩晕惊惕，肉酒蒸聚湿热，由胃脉下注跗足，每多脓水，此痿厥中风之萌。秋冬务在藏聚，温养经脉佐以温通，加味虎潜丸宜用。", "11344": "（案6）某。阳气内风升举，眩晕肢麻，遗泄颇频，阴气先已暗伤，致二气失交，凡下虚必上实，诸脉废而不用，中年以后痱中厥仆至矣。诊脉小紧数，治在藏阴。", "11345": "（案7）刘，六三。脉得动博，劳心烦剧，阳易升越，内风陡起，遂致眩晕欲仆，据述上冬患此，春夏数发，盖冬季少藏，不耐天暖气泄。法当填阴收纳，以培风蛰。二陈汤只治痰眩，非摄纳方也。", "11346": "（案2）吴，五七。脾阳衰微，食入不运，汤饮更易壅积，脾恶湿也。当薄味令清气流行。脉小涩，非破气所宜。", "11347": "（案7）某。凡寒热疟气起于四肢，蒸及中宫，必满闷烦冤。气痹治肺，热灼清胃，皆是古法。首方兼理上中，转方专理气。无非气结宜开治法，只因病延多日，质薄胃弱，于寒热未止之时，频加呃逆。《经》言胃气以下行为顺。中乏谷气坐镇少权，胃土属阳，譬如雨露上施，阳土得濡润而禾苗蕃盛。今也日加热蒸，斯震动之气上翔，胃气不安其位矣。尝读仲景书，吐、狐惑、噫气、哕呃诸篇必系胃虚少谷，但须分在阴在阳之客为正，非案中稍申甘缓益胃，进以味轻气清以消息病情，盖志慎也。辰刻诊候，仪容清减，脉右虚数。法仲景「病邪未尽，正气欲衰，当与甘药」之旨。", "11348": "（案1）气上冲心，心内热疼，仲景例之厥阴篇。但暴病为邪热内陷，久病为水不涵木。脉弦而细，宜滋肾以生肝。", "11349": "（案2）咽喉如有线牵引，不便俯仰。脉象左弦大。此肝阳射肺也。", "11350": "（案3）肾阴不足，肝阳内扰，筋跳强中，多食易饥，皆水亏木亢之故。惊气亦从肝，入梦与人争亦属肝火。以木侮土则腹中如胀，气闭不爽。就脉象之左弦右细，宜益木培木。", "11351": "（案4）先天真阴不足，水亏则火易上炎，加以肝阳升逆，背心烘热，倏作倏止，常时干呕，痰带微血，此皆童弱之基。脉象左手弦劲。且与清肝，勿据用滋腻药。寐中惊惕出汗亦属肝病，宜温胆汤加减。", "11352": "（案5）颤振不止，脉细带弦，肝风为害也。", "11353": "（案3）嘈杂心悸，见人则畏，夜梦纷纷，皆心神受病。脉沉弦，兼痰滞胆经也。", "11354": "（案4）寐中惊跳，肝有热而魂不这发藏也。从前目晴忽陷，亦由肝窍在目，肝系了戾，筋脉为之挛钓耳，今病与昔病其因却相同。", "11355": "（案5）忧愁悒郁，心神受伤，肾不上交，故应酬无意绪，行动则气促，诊脉左弦右细，知非痰火为病，宜归脾汤、宁志膏之类。", "11356": "又，脉细弦，重按觉有力，肝阳上亢，暂进清肝法，前用补不应，症兼口燥，左胁胀。", "11357": "又，用清肝法又觉外寒，此亦气血久虚之故，但左脉尚沉弦，仍从肝治为妥。", "11358": "（案6）神气模糊，夜不能寐，心忡，腰痛，舌苔黄垢，脉象左弦细右滑大。此心肾两虚，痰涎沃胆之候，宜先清后补。", "11359": "又，心忡稍缓，心膈仍热，脊腰时痛，夜寐未安，脉之滑大虽减，犹带数象。此水衰不能制火，肝胆厥阳上冒，宜去痰药，佐以潜降品。", "11360": "（案1）右寸脉弱，左寸关弦滑，此劳心太过，心不摄肾，而为梦泄。又以思虑伤脾，脾虚则生痰，痰停心包，故不寐嘈杂。宜先半夏秫米汤，继以归脾汤调理，然后可以抛弃一切，安神忌食静养，则渐可向安无虑矣。", "11361": "（案2）某。按《灵枢经》云，凡人阳气暮必下交于阴，阴𫏋脉中气满，阴气包护阳气不令透泄于外，遂令熟寐，反是，寐不成寐者，阳动于外，神识焉得归著于里。《经》义用半夏秫米汤，藉半夏由阳气入阴中，更入𫏋脉，随以秫米奠安脾胃之气，为中宫砥柱，不令气升阳浮，然必多服，方有效验。", "11362": "汪周拔二令郎，年二十二岁，新婚之后，乃祖督课颇严，馆于别业，经年不入帏房，肝火抑郁而不舒，扰其精房而成梦遗。马元仪以补肾涩精之药治之，甚至厥逆不醒，谓其为虚欲脱，竟以参耆鹿茸河车等药补之。日甚一日，肌肉消瘦，卧床不起，已经一载，于是延余诊视。时八月下旬，见其饮食少进，嗳气而大便燥结，五六日一解，语言默默，小便黄赤，诊其脉息，沉细带数。察其形，唇口面色皆红，肌肉虽瘦，润泽而不枯，夜间坐而下卧，无倦怠之意，日间只食薄粥二盏，按其胸腹，板硬不和软。此因补药太过，壅塞肠胃，气道不行，不能宣通，正所谓大羸有实也。因投以二陈加莱菔子、山栀、枳壳、香附、厚朴，冲元明粉服之。三剂后，大便去结粪三五块，胸次稍宽，语言稍出，又进滚痰丸三钱，又去结粪五六块，再服前煎方五六帖，大便去黏腻而黑色者不计，间与滚痰丸及清火理气之药。如得通泰，自是可进稀粥六七碗，然亦不觉大饥，又以保和丸加黄连，早晚服之，两月后可进干饭。余往还两月，而门人蔡沧文居其家，常为调理，至冬至后，步履如常。居宿于内，新春到舍奉谢，酬以千金。此康熙四十八年之事，其人号丽夭，至今无恙。今元仪谓是渠调治而安，欺妄无耳。即此一案，可知其无不说谎，无一可信，而犹谬自著述，附会于他人之书尾，真鬼蜮也。雍正八年，海上沈璠，时年七十有八。", "11363": "天老久服右归饮，其中有桂附甘草，甘草甘缓，不能下达肾家，桂附之性，留恋胃中，其热性升而不降，所以两足不暖。河间云：两足冰冷者，此火不下降也，火降则足自暖矣。热药之性，积而不散，煅炼津液成痰。今交相火司天之年，夏暑薰赫之势，内伏之痰火，得外风所触，故胸膈不宽，呕吐痰涎，汗出过多。此汗系胃中湿热痰火，郁蒸而泄，即东垣所谓地之湿气，即为汗也。诊得脉息左手沉弦带数，此肝火不静也。右手滑大，关部尤甚，此胃中痰饮不清也。恐其大便燥结，痰涎上壅而呕吐，酿成噎膈、反胃之症。《内经》云三阳结谓之膈。丹溪云：噎膈之症，多起于血枯痰腻，多升少降，大忌香燥热药，惟以豁痰清火润泽之药，而使大便不燥结为第一著。", "11364": "在老向有咳嗽之疾，缘劳心过度，外为风寒所触，内郁之火窃发，上千肺家而咳嗽，已经四载。今交相火，司天之年，内外之火，交相煽动，咳久肺络受伤，痰中带血，脉息左手弦细带数，右手虚大滞滑。此系肾水不足，不能荣养肝木，肝火升腾烁金。《难经》云：东方实，西方虚，泻南方，补北方，理宜滋阴降火，纳气归源之药治之。煎丸并进，并宜寂静调摄，庶不致喉烂声哑，酿成劳瘵也。", "11365": "可老数年前曾患血症，服寒凉之药，得以相安，去年血症复发，他医误进热药，以致火来乘金而咳嗽，究其受病之源，肾水不足，不能荣养肝木，木火升腾，血随火沸而出。今岁少阳相火司天，内外之火，交相煽动，致频咳而咽喉痛。肺与大肠相为表里，火流于肛门而发毒。目前脉息弦细带数，此肾水亏损，相火上炎，肺金受困之症。反以桂附炮姜等燥之剂，耗其肾水，烁其肺金，意欲求愈，难之至也。今且用滋阴降火保肺之药，并应寂静调摄，不使咽喉作楚，庶有佳兆。", "11366": "因酒伤胃，胃中之血凝滞不散，随气上升，而吐黏腻紫色之血，此瘀血也。理应理气消瘀之药治之，使气顺而不上升，则血自下行，而不至上逆矣。误用滋阴之药，遂致胃中之痰瘀不清，随致上千肺家而咳嗽，胸膈不舒，脉息弦滑。此系胃中之痰瘀不清，肝家有火之故也。暂用理气消瘀清热和胃之药为治，俟胸膈舒畅，然后以滋阴之药，为善后之计。治血症必先理气为主，气顺则血自归经，此万古不易之法也。", "11367": "平素善饮，酒性大热有毒，贮于胃中，燔灼津液而发渴，因将寒凉生冷之物，恣意而啖，致火郁遏，不得发泄，流于经络，而环跳作楚，入于肠胃而作血痢，达于肌表，而皮肤作痒，干燥，内火不得疏泄，扰其津液而愈渴，脉息沉涩，此郁火未经发越之故也。理宜和胃清热疏理之药为治，并忌醇酒厚味生冷等物。", "11368": "季老受病之源，得之君火司天之岁，夏令炎热之时，感冒暑热之邪，以致大便泄泻，即《内经》所谓暴注下迫，皆属于火也。热邪上冲，心生血，肝藏血，肝为相火，两火相煽，则血随火沸而上逆。肝为将军之官，其性暴，主疏泄，其气郁而不舒，逆于腹中，则腹不宁，不时嗳气。《准绳》云：嗳气火土之气，郁而不舒也。气道不舒，故蹇于语言也。肝火不得疏泄，上升则头眩，下降则腹作鸣。胃主肌肉，犯胃则肌肉跳动。扰其精房，则梦遗泄滑。心藏神，肝藏魂，二火相煽，则神不宁，而卧不安也。阳事者，宗筋之会，肝之所循，火亢于上，故常举而不痿也。得以小便而痿者，肝火从溺而泄也。盖下有二窍，有水道，有精道，精道闭则水道开，水道闭则精道开。脉息沉而带数有力，种种诸症，皆系肝气郁而不舒，肝火不得疏泄之故也。理宜清肝火，疏肝气，利水道之药治之自愈。但时值冬令闭藏之月，木火内伏，不能条达，至春气发生，木得疏泄，自然却去病蒂矣。", "11369": "宾老平昔嗜酒，酒性湿热，积于胃中，薰灼于口，而舌为之糜碎，下注膀胱，而小便为之浑浊，绵延已久，脾气大虚，饮食减少，而觉无味，脉息短小，此脾虚而湿热未清也。理宜健脾气，清湿热，加味六君子为治。", "11370": "阴虚火炎而吐血，上烁肺金，腠理不密，外邪乘虚袭肺，而咳嗽入于大肠，腹中作痛，下利见血，脉息洪大，此火得风而炽也。理宜疏风理气之药为治，俟咳嗽稍平，然后以滋阴降火之药培其本。", "11371": "苏州吴佐臣案，经云：阳络伤则血外溢。因劳力过度，有伤胃络，血瘀胃中，则肝火上升而吐。所来之血，厚而黏腻，此瘀血也。理宜消瘀降火顺气之药治之。又因补之太早，余瘀未尽，所以今春复吐。既吐之后，阴血有亏，肝火上烁肺金而咳，脉息弦细带数，此肾水亏损，肝火妄动，肺金受困之象也。理宜滋阴降火保肺之药为治。", "11372": "嘉定王佩玉令姊，肝火郁于胃中，不得条达通畅，以致作胀攻卫作响，注于大肠，则为泄泻，脉息弦数，经事不至。此乃木郁土中，理宜扶脾疏肝之药。", "11373": "东山夏姓，胃中湿痰，随火下注精房而遗滑，误以补肾涩精之药治之，以致湿痰纠结于胃，饮食少进，难以运化，脉息弦滑，右手关部尤甚。胃中有湿痰，肝家有郁火也。理宜豁痰清肝之药为治。", "11374": "魏提台，年六十九，平日劳心思虑，气结痰凝于胃。春三月得不寐之症，每至夜间，胃中如焚，烦躁不宁，目不交睫，昼则稍安，毫不倦怠，饮食虽进而无味。诸医俱云心血不足，用天王补心丹。有议心肾不交，而用加味地黄丸；有议思虑伤脾，而用归脾汤。愈觉日甚，将有发狂之兆，如此者两月余。延余诊视，面色红亮而浮，脉息沉小滑而有力，关部尤甚。此乃肝火郁而不舒，胃中胶痰固结而不通也。经云：胃不和则卧不安。又云：阳明病不得眠，大便三四日一解，用礞石滚痰丸三钱。大便去黏腻之痰不计，二便如火，以二陈、石羔、黄连、山栀、石菖蒲、钩藤、栝蒌实、枳壳，连进四帖，即能安卧。然有时胃中如火，又用滚痰丸三钱，又去白痰碗许。仍用前豁痰清火之药，丸服二十日全愈。一月后又停食冒风，胃脘作痛发热，用消导之药平安，后用加味六君子汤调养，康健倍常。", "11375": "俊宜徐和修，平昔嗜酒，则知湿热之蕴于胃者久矣，加以夏令热邪侵袭，至收敛于内，交一阳和动之时，内敛之邪，流动发越而为痢，春夏邪气散漫，流注经络而作痛，俗名痢后风也。诊得脉息左手弦，右手弦且滑大，此湿热滞于肠胃，失于推荡，以致流注经络，而支节肿痛。治宜理滞气，清湿热之药。", "11376": "张寿南，肝火郁于胃中，不得疏泄，而寒热如疟，胃脘或时作痛，脉息洪大而弦滑，此胃中有痰，肝家有郁火也。宜豁痰理气疏肝之药为治，并宜清虚淡泊，则胃中清爽，而痰自无矣。", "11377": "松江张殿舟，天禀素弱，肾水不足，夏令兼暑热之邪，至秋发疟，疟愈而暑邪未清，补剂与荤腥太早，致余邪未清，流注于背脊支节之间作痛，扰其胃中之血下流，而为便红。至春令发生三月，余邪外达，复寒热如疟，交夏令内伏之火炎炎而炽，加之酒热助火，胃中之血随火而升，脉息左手弦数，此肝火妄动也。右手洪大，此胃中之火不静也。火来烁肺，故痰中带血，肺气布于胸膈，致气升不舒，目下降气清火，火降则血降，治血必先理气，气降则血自归经，而不致上逆矣。暂用理气清火，服四剂后胸次舒畅，气不上升，然后以滋阴降火、清金保肺之药治其本，并宜戒恼怒，忌一切肥腻辛辣醇酒厚味为主。", "11378": "娘娘，肝家之火，郁而不舒，煅炼津液成痰，随火上升，咽噎之间，结成有形之象，升降无时，上升则头眩耳鸣，降下则两足麻痹而热，脉息左手弦数，右手带滑且大，此乃郁痰郁火症也。理宜和胃豁痰清肝之药治之，并忌醇酒厚味，戒恼怒为要。（唐露玉令堂）", "11379": "太仓钱因之令媳，娘娘平昔有肝火，所以善怒，每每产后必作血晕，此因肝火而作晕也。怀娠之时，肝气郁而不舒，郁之既久，则产后空虚，其火上冲而作晕，平时两足冰冷，此火不下降，火气上蒸，于头则发堕目下，怀娠六月，腰痛而带下，饮食少进而作胀，脉息弦数。此肾水不足，不能荣养肝木，郁于脾土之中，恐火气扰其血分，而有堕胎之虑，理宜扶脾疏肝，清火之药治之。", "11380": "扬州东门外顾友仁兄，饥饱不时，恼怒伤肝，有伤胃络。经云：阳络伤则血外溢，致吐瘀血，已延四载，不时窃发，去血过多，阴分受伤，肝火上烁肺金而咳嗽，痰涎颇多。脉息左手弦而带数，此肝火妄动也。右手又见滑大，此胃中有痰也。先宜戒恼怒，省言语，调饮食，避风寒暑热，静养调摄，并服滋阴降火，保肺清金之药为治。", "11381": "昆山邵政平令郎，肾水不足，不能荣养肝木，肝火上升，外受风寒，胃中之痰，随火上千肺家而为咳嗽，用发散之药，升提其火，以致吐血咳嗽不止，痰涎颇多。至五月初复发，脉息弦数，此水衰火亢，肺金受困之症。理宜滋阴降火保肺之药治之。", "11382": "东山刘永传，疟痰之后，饮食不节，脾伤不能运化，而成积滞，胸腹胀满，按之坚实，日渐以大，大便或结或溏后重，不爽快，面色痿黄，脉息左手沉弦，右手滑大。此肝气郁而不舒，胃中积滞纠结不清也。理宜扶脾胃，疏肝气，消积滞药。", "11383": "濮院吴廷来，胃脘作痛而呕吐，乃肝火郁胃而成，误服热药，几至危殆。用清火和胃之药，呕吐已平。但郁久未清，有时上逆，脉息弦数，此胃不和而余火未清也。当以和胃清火之药治之。", "11384": "平湖陈晋公，平素多思多郁，肝火郁于胃中，不得疏泄，煅炼津液成痰，阻滞气道，饮食入胃，则作胀而痛，近因春令，肝木用事，恼怒伤肝，以致左胁作痛，以手按之亦痛。肝为藏血之脏，怒则伤肝，而血为之郁。经云：大怒则菀于上，令人薄厥。将来虑其随火上升而吐。脉息沉弦而涩，此瘀血阻滞，胃中作痛也。理宜行滞消瘀，理气之药治之。今先用一味大黄丸，以逐胃中之血，从大便而出，并虑其成噎膈之症也。", "11385": "服酒蒸大黄丸二钱，大便去结粪黑色黍腻之物不计，肛门觉热，则知郁与瘀血无疑矣。但胃中尚未清爽，所以胸膈不能宽畅，背心作痛，在此肺腧也。经云：诸气𪱥郁，皆属于肺。因郁之久，火气不能通达，以致作痛。今诊得脉息弦大带数，因服通利之药，火气得以发泄故也。调治之法，先讲开郁消瘀润大便为要，结则肺脘不通而痛。《内经》云：三阳结为之膈。三阳者，大小肠膀胱也。结于下则反之于上，而噎膈之症来矣。常将汤液滑润之物，滋其大便，并服蔗浆梨汁芦根汁，而使大便不燥结为妙。", "11386": "黄江泾沈上林令堂，娘娘受病之原，得之恼怒，抑郁之于胃中，煅炼津液成痰，随肝火上升于结喉，皮里膜外，结成痰块，气滞而日渐以大。《内经》云：荣气不从逆于肉，里乃生壅，肿因气滞，而痰凝不散所致也。脉息左手沉弦，右手关部独见沉滑。肝家有郁气郁火，胃中有胶痰纠结，理宜理气豁痰之药为治，并忌醇酒厚味等物。", "11387": "寿南兄，去冬感受寒邪，背脊恶寒，寒束其火，不得疏泄，流注于胸胁之间，攻冲于胃，或痛或不痛，寒热似疟，此冬令寒邪，至春发越，故为寒热也。误用参耆白术，闭其腠理，邪气内伏，故寒热虽止而不清，肺家则为咳嗽，脉息洪大而弦。此内火郁而不舒，理宜豁痰理气疏肝之药治之。连进数剂，自然全愈矣。", "11388": "常州江甸方，幼时有梦遗之病，此肝火妄动，扰其精房而来。医者俱以补肾涩精之药涩之，其火不得下降，反以桂附助其火，其火愈炽而上升，血随火沸而衄血。今值纯阳之月，内火与外火，交相煽动，而胃中之血，大吐不止，胸膈不宽，喉中作痒。此吐后不归经络之血，留滞膈间，肝火郁而不舒，脉息左手弦数，右手洪大有力。此胃中余瘀未尽，肝火不静，理宜消瘀清火理气之药治之，并宜清虚淡泊，一切醇酒厚味，暂宜停止，俟胃中气降火降，胸膈宽舒，然后议调补之法，为善后计。", "11389": "青浦潘丽文兄，饥饱不时，外邪乘虚袭肺而咳嗽，痰中带不鲜明之血些少。因不避风寒，不忌荤腥，误作劳症吐血而医治，郁其血邪在内，不得发越，绵延至今，咳嗽日甚，嗽极则呕，胸膈不舒，大便滑泄，小便黄赤，肛门发热，脉息左手弦大带数，右手滑大带数。此胃中有痰，肝家有火，郁之既久，乘夏令火气发越之时，肺家之火，流注于大肠，而为滑泄，并非脾虚作泻也。理宜降气豁痰，清火之药为治，俟胸膈舒畅，痰火下降，肛门不热，小便清白，然后以滋阴之药培其本，暂忌醇酒厚味等物为要。", "11390": "平湖王永年，胃中之痰，随火升降，昼则行阳二十五度，随火上升，滞于胸膈而作胀，按之有形，饮食难以下达，夜则行阴二十五度，随火降下，而胸次舒适，注于精房而为梦遗，脉息弦滑有力，此胃中之痰，随火升降而为患也。理宜豁痰清火之药治之。", "11391": "上洋马头渡李云甫媳，二十岁，于二月十四日，患胁痛气喘不得卧，数日，诸医皆以风寒发散，或用降气等药，不能取效。平希于以为肺胀，法在不治。余适往外家，经过门首，邀余诊视，见其面青气喘，两胁作痛，不能合眼而卧，其母其姑，俱备后事，在患者之旁，患者见之泪下。诊其脉，两手弦急，无痰声，鼻不煽，无汗出，即示未为绝症，后事且缓，病者安心，心安则能安枕，此亦法也。此症当春令肝木旺之时，木火垂金，因拟一方，用白芍、甘草、栝蒌、川贝、黄连、石羔、广皮、钩藤、苏子，用生铁二两，煎汤煎药，一剂后即能安卧。希于至，见其安卧，问余用何宗汤药。此症木旺，故用钩藤、生铁，助金以平肝，黄连清心火，石羔清肺平肝，苏子降气，贝母、橘皮、栝蒌降痰润肺，白芍、甘草缓肝，彼亦心服。后皆希于调治而安。", "11392": "浙江西新城李益书，平素服八味丸归脾汤，数年后觉胸中痰火郁结，大便五六日一解，头面烘热而红。此因桂附太多，积热于胃，煅炼津液成痰，脉息数大。用清火疏理之药，病势稍减，然苦于大便燥结，胸腹如燎。此郁火不能外达，用凉膈散一两，以泻其郁火。十月初旬用药起，至次年正月下旬，腹中舒畅，肛门不热，复服滋阴降火之剂而愈。", "11393": "川沙北门外金隆吉令郎，二十二岁，七月初旬，患时症发狂谵语，气急痰升，不能安卧，诸医以黄连石羔连翘等清火之药治之，半月不愈，迎余诊视。面色唇口皆红，身无大热，按之胸腹和软，大便滑泻，小便清利，痰声作齁，脉息虚大，不能安卧。细究此症，若阳明胃实，大便必结，胸腹按之必实，舌必黄苔。今无是证，观其小便不禁而利，惟痰声齁齁，此乃少年不谨，暑热之邪，伤其元气。清热之药已多，不能见效，难于下药，以人参一钱，橘红一钱，煎徐徐与之，以扶元气而化痰。服完平安，又复煎与之。一晚计服人参七钱，橘红七钱半。两日服人参橘红四两，痰声下降，人事清爽而熟睡。复用六味丸生脉散调理而愈。", "11394": "柴场湾唐虞在令政，怀娠七月，正月春初，倏而眩晕，两手瘛疭，不能言语，不省人事，面色红亮，脉息左手弦而带数，右手滑大有力。此肝火炽盛，上冲于胃，胃中之痰，扰心肺之窍，而昏瞆不省人事，因此而胎亦堕。用二陈加黄连、钩藤、山栀、鲜石菖蒲、胆星、枳壳、郁金，冲童便、梨汁、竹沥、姜汁，连进二剂，即能开口，而知人事。小产彼亦不知，后用凉血，生地、丹皮、钩藤、黄连、广皮、丹参、郁金、石菖蒲、甘草，加莲子调理而安。", "11395": "阊门外上津桥陈友文令郎，正月患咽喉作痛，用滋阴清火之药，咽痛已除，而胸膈满闷，痰涎上壅，饮食不进，不得安卧，已经两月，邀余诊治。门人杜良一同往。诊得脉息甚大，口亦不渴，唯见痰涎上壅，胸中满闷，而不能进饮食。此胃中有痰而不得卧，用滚痰丸三钱，下顽痰不计，即能安寝，而胸前舒适。复用二陈加石菖蒲、钩藤、枳壳，连进四剂而愈。", "11396": "苏州齐门外蒋奶奶，寡居七载，劳心抑郁，肝气不能条达通畅，以致滞下腹痛后重，胸膈不宽而恶心。时当初夏，叶天士以为不足之症，而用人参人乳等补剂。适余在吴门，延余诊视，门人杜良一同往。诊得脉息弦大带数，腹痛后重，肛门如火，口干气急，此肝家郁火，下注而为滞下，上升而呕恶，胸膈不宽。用黄芩芍药汤，加厚朴、枳壳、香附、山栀、黄连、木通、滑石，一剂腹痛顿除，饮食可进。连用四剂，痢止胸宽，复用香附、广皮、厚朴、枳壳、黄芩、黄连而病愈。", "11397": "上洋南关外周襄文，七月初往松江完粮，途中奔走，百有余里，兼之饥饿，发热自汗不止，倦怠乏力，语言难出，脉息虚大，诸医以为冒暑，议用香薷饮。延余诊视，脉息虚无力，汗出如注，无气力转动，即曰：此热伤元气，饥饿劳倦所致。即以黄耆五钱，人参三钱，白术三钱，麦冬一钱，五味子七粒，连进三服，汗敛神复。以粥食与之，始得安卧。后用归脾汤生脉散而愈。", "11398": "崇明沈尚其，三消之症不一，有火衰不能蒸其津液上腾，小便清白而味甘者。昔汉武帝患此，张仲景以八味地黄丸治之。今尚其正是此症，服药已稍愈，惟口内干燥，小便如膏，足痿乏力，乃虚火上炎，肺金受灼，《内经》所谓诸痿皆属于肺热。脉息虚大，理直生脉散治水之上源，八味丸补火为要。", "11399": "崇明黄土端，肝火郁于小腹，外为寒凉所遏，不得伸越，以致结成有形之象，稍有所触，上千肺家而作痛，攻冲不宁而呕逆，脉息左手沉弦带数，右手沉滑有力。此肝家有郁火，胃中有痰饮也。理宜清肝火，疏肝气，和胃豁痰之药治之。", "11400": "崇明沈天章，饥饱不时，胃络受伤，血瘀于胃，以致胸膈不宽，而吐黍腻之血，屡次窃发，脉息弦数。此乃胃中痰瘀，纠结不清也。理宜消瘀理气豁痰之药为治，今晚先服酒蒸大黄丸二钱，以逐胸中之瘀滞，使其下行，清晨方可以煎方服之。", "11401": "崇明袁达九，去夏感受暑湿之热邪，加之饮酒太过，蕴蓄于胃，不能通畅，以致胸膈不宽，饮食不进，面色带黄，小便短少而赤，大便燥结，脉息左手带弦，右手滑大有力。此乃胃中湿热积滞未清也，当以清湿热和胃理气之药治之。", "11402": "平湖江尚安，去春时症之后，不忌荤腥，致肺金不清，咳嗽吐血，延至冬令，火气潜伏之时，内热更甚，上升而烁肺金，咳嗽日甚，胸腹如燎，下注而肛门发毒，大便不实。目前夏令炎炎之势，不足之金，奚堪燔灼，脉息细数无神。此乃水衰火亢，肺金受困之象。虽大便不实，乃肺虚因热而跗踵，非脾虚之症。燥脾之药，不宜多服。惟以滋阴保肺清热之药为治。", "11403": "太仓沙头镇孙金祥，平素善怒躁急，内有肝火，得外之风寒所触，上干于肺，而咳嗽之极，则血随火沸而吐出，脉息弦数。此乃肾水不足，不能荣养肝木，肝火上炎而烁肺，肺金受困之象，理宜滋阴降火清金保肺之药，并宜戒恼怒，慎起居，不至酿成劳瘵也。", "11404": "下沙王敬哉，血症之后，肾水不足，虚火上炎烁肺气，不能纳藏于下，上升而咳。因肾纳气，肺布气，肾虚气不归源，故稍有动作言语，则气上升而咳嗽。脉息虚大，两尺尤甚，乃肾虚气不归源也。理宜补肾纳气之丸治之。", "11405": "五灶蔡六老，胃中痰火纠结不清，干清虚之府，以致不得安卧，神魂不宁，脉息弦滑，此乃痰火充塞于胃也。先以滚痰丸二钱，淡姜汤下之，使痰从下窍而出。然后用豁痰清火之药，并忌醇酒厚味为要。", "11406": "新场程君烁，先天肾水不足，相火妄动，上烁肺金，外邪乘虚袭肺，发为咳嗽。已服过疏之剂，外邪已去，惟有火气上炎而干咳，脉息弦数。此乃火亢肺金受困之象，理宜滋阴火清肺药为治。", "11407": "服滋阴清肺之药，咳嗽稍减，夜可安寝，脉息不数。此渐愈之佳兆也，但必得煎丸并进，并静养调摄，可免劳瘵之疾也。", "11408": "北六灶杨启林，去冬患疟，三日一发。此内伏之暑邪，与胃中之痰积，互为患也。又因饮食不节，郁而为热，胃中火气上升而鼻衄，绵延至今不愈。脉息弦大带数滑，此胃中痰积未清也。先宜清虚淡泊，临发之日，只宜以薄粥养之，并服豁痰疏理清热之药。", "11409": "金泽蒋元信，食入即吐，是有火也。脉息洪数，此肝火上冲于胃而吐也。理直和胃清火之药。", "11410": "嘉定西门外朱圣希，先天肾水不足，相火上炎，销烁肺金而咳嗽，午后发热，脉息虚大带数，此水衰火亢也。理宜滋阴降火保肺之药为治，并宜绝嗜欲，戒恼怒，静养调摄，不至酿成劳瘵也。", "11411": "平湖张御仁，饮食过饱，停滞胃中，纠结成疾，胸膈胀满，按之坚实有形，面色带黄，脉息沉滑带弦。此胃中湿热所积，纠结不清也。恐其成黄疸鼓胀之疾，理宜清湿热豁痰之药治之。", "11412": "同上后案，血证之后，阴分已亏，虚火灼肺而咳，面色萎黄，大便不实，脾肺之气虚也。脉息虚大带数，此真阴亏损，肺金受困之象。大凡咳嗽之病，当以生脉散地黄丸治之。赵养葵所谓咳嗽不治肺而治肾，肾气纳藏于下，不上升则不咳矣。暂以补肾纳气之药治之。", "11413": "新场闵若洲家一仆妇，为乳母，年满归，适中秋往候，因食梨藕生冷之物，一时喉间锁定，不能出声，不知痛痒，手足冰冷，面色白而带青，脉息沉伏，汤药不进，束手无策。余将紫金锭姜汤磨灌，渐渐喉门气降，有声宽舒。开口后用二陈加理气之药而安。亦因郁怒而食生冷之物也。又治裁衣费姓之女，年已二十外未嫁，忽然倒仆，手足冰冷，面色青，无痰声，不开口，脉息伏，亦用紫金丹开口进药而愈。如此症者甚多。凡遇不开口，无痛楚，忽然而起者，先以开通关隘为第一著。语言得出，可以得生。若认为虚，妄投人参者，无有不死。戒之慎之。（评张景岳咽喉条内）", "11414": "新场徐兴若，大病之后，脾肺之气已虚，所以大便作泻，而肛门下坠，四肢倦怠乏力，脉息数软。此气虚下陷之故，理宜加味补中益气汤治之。", "11415": "余治胡政之痢，其年七十二岁，先胸膈不宽，饮食不进者两月余。自以为膈症，与诸老友诀别，往太仓调理。至八月初患痢，血积稠黏，里急后重，肛门如火，诸医以为老年气血衰耗，以培脾胃为主，其痢更甚，且烦躁内热，饮食绝然不进，而兼恶心，延予诊治，脉息滑大，肛门如火，小便不利，后重逼迫。余用大黄、槟榔、枳壳、黄芩、厚朴为丸，服之大下红积不计，胸腹稍舒，热势更甚。用井水调益元散，连进三碗，其肛门之火热如焚，因凉水清其火而下降，仍用西瓜水不时呷之，服药以苓、芍、枳壳、滑石、木通、厚朴、槟榔、金银花，连进十五剂，月余病势平安，胸膈通泰，饮食大进而愈，寿至八十六。若此时以温补培其本，必然至死，然清火而不用黄连者，恐厚肠胃而大便愈难也。（原评，用药之不苟如此。）槟榔性如铁石，里急后重之圣药。（评张景岳痢疾条内）", "11416": "华玉英令郎琴五，患痢大便泻血水，一日夜五六十次，里急后重，肛门如火，小便不利，诸医用和血调气利水之药，不能取效。余诊视脉大而数，唇口俱红，余曰：如此暴注下迫，皆属于火，津液枯耗，焉得小便，惟以水能制之。用井水调益元散，并以西瓜不时与之，小便即来。用芍药汤加芩连枳壳之类，半月平安。计饮冷水益元散十三碗，西瓜四十余枚而愈。（评景岳痢疾条）", "11417": "芦店周西扶，因恼怒抑郁，动其肝火，上干胃家，痰随火升，闭其心窍，以致舌音不清，语言蹇涩，口流痰涎，脉息左手弦数，右手滑大。此肝家有郁火，胃中有痰饮，乃类中之基也。理宜豁痰清肝之药治之，并戒恼怒，忌醇酒厚味等物，面色亦红甚。", "11418": "吴江八拆镇钱士能，因感暑热之邪而血痢，愈后不忌荤酒，以致未尽之暑邪，留于肠胃而发疟疾。疟愈，其暑热之邪流于经络而作楚，小便黄赤，腹中尝不舒畅，似乎有形，脉息沉弦带滑。此暑热之邪未尽之故也，理宜清暑热之药为治。", "11419": "后案，伏邪已经三载，虽用疏通清火之药，其浊气攻冲为患，脉息带弦，犹恐饮食不节，复感暑邪而为疟也。理宜疏理清热之药治之。先用滚痰丸二钱，淡姜汤下。", "11420": "塘西顾刚宗弟妇，病起于产后，感冒风寒，胃中之痰火，上干于肺而为咳嗽，薰灼于上而口发疳疮，绵延一载，至春肝火上升，痰涎多而口干燥，咳极则呕，脉息弦数带滑。此胃中有痰火，得外邪触动为咳嗽，久则成蓐劳之症。暂用豁痰降气之药，继以滋阴保肺之剂治之。", "11421": "洞庭东山陈康源，去冬感受寒邪，胃中之痰火，为寒邪所郁，不得发泄，上干于肺而咳嗽，又不忌荤酒，不避风寒，误服滋阴凝滞之药，肺窍闭而声哑，已经半载，不能却去。脉息左手弦大，右手滑大有力，察其面色红亮，其痰亦不易咳出，乃郁痰郁火为患，失于调治而然也。理宜豁痰理气之药治之。", "11422": "千墩李伟生，胃中瘀血未尽，用补涩之药止之，所以连年不愈，屡次窃发。此肝火下注肛门，而肛门非气虚下陷之故。漫用补中益气，致肝火郁而不舒，所以后重逼迫，肛门愈坠。脉息滑大，此胃中余瘀未尽，肝火郁而不舒，去血而肛门不坠。若肠红无腹痛之理，此系血痢，故后重逼迫也。补药断不可服。", "11423": "乍浦路又高，向有咳嗽之病，遇风寒即发，此痰火咳嗽也。今交夏令火旺之候，胃中痰火，为外邪触动，上干肺家，而咳嗽愈作。误认为劳症，以何首乌熟地枸杞温补之药，闭其肺窍，加之肥腻不忌，咳嗽日甚。咳久火炎于上，扰其胃中之血而吐血，内火不清，销烁肌肉，凝滞之药入胃，纠结成痰，不知饥饱，饮食不进，已经两月，精神困惫，脉息左手带弦，右手滑大带数。此肝火妄动，胃中之痰火燔灼肺金，兼之舌苔紫色，知伏火在内无疑也。理宜和胃豁痰清火之药治之。", "11424": "青浦大西门徐锡昌，去夏感受暑热，又为风寒郁遏，不得发越，加之恼怒以动其肝火，上干于胃而呕吐，小便不利，肠中作泻，湿热郁于胃中而为腹肿，随肝火上升，而头面肿痛，脉息弦而大。此乃湿热肝火，蕴于脾胃之中，不得发越之故也。理宜清湿热，疏肝火，利小便之药治之。", "11425": "青浦大西门徐青岳，肾水不足，不能荣养肝木，肝火郁于胃中，煅炼津液而成痰，外为风寒所触，胃中之痰火，上干肺家，而为喘嗽，不得卧之病，脉息左手弦大，右手滑大有力，关部尤甚。此肝家有郁火，胃中有痰也。理宜豁痰理气疏肝之药治之。暂用滚痰丸，以逐胃中之痰瘀，从大便而去，以调补之药为善后计，否则恐成反胃噎膈之症也。", "11426": "上海东门张子敬，初因风寒袭肺而咳嗽，因不忌荤酒，不避风寒，日久伤肺，而痰中带红，已经数月，其咳不止，真阴受伤，虚火烁肺而咽痛，脉息虚细带数，面白色而无神，稍有语言动作，其气即上逆而咳，此肾气虚不归原也。理宜滋阴补肾纳气保肺之药，煎丸并进，静养调摄，不致酿成劳瘵也。", "11427": "黄维思令侄，血症之后，肾虚而肺气受伤，耳聋不聪，自汗不止，大便不实，脉息数大无神。夫耳聋肾绝也，汗出气脱也。大便不实，脾虚也。此皆不治之症，以补肾纳气之药，以安病者之心耳。", "11428": "北一灶张于冈夫人，肝火郁于胃中，不得疏泄，以致胸膈不宽，至春正月分娩之后，肝火上冲于胃而呕吐。夫食即吐，是有火也。脉息弦滑带数，此肝气郁而为火，以致结成有形之象，按之和软，流走不定。理宜和胃清肝之药治之。", "11429": "嘉兴戴天升案，先天肾水不足，不能荣养肝木，肝火上升，血随火沸而吐，屡次窃发。今春木气升腾之候，而吐血又作，脉息数而带弦，此水衰火亢之故也。理宜滋阴降火之药为治。", "11430": "初十午后，食物停滞胃中，以致恶寒，胃火上蒸而为汗，脉息滑而有力，似乎有疟之状。理宜豁痰疏理胃中之滞，胸膈舒畅，自然平安。", "11431": "二十日，脉息调和，胸次黄瓜之形已无，惟觉胸膈作胀不舒，舌色带黄，嗳气不减。此浊气欲散而不能，不得下降之故也。理宜以疏理浊气清肝火之药丸服。", "11432": "廿七日，寒热已止，气急亦减，但脉息弦大，至晚犹觉凛凛似寒，此内有郁火，外则凛凛，乃疟之基也。饮食须宜调节，风寒最要谨避，至于胸次不时作胀，此亦胃中余瘀未清，浊气壅滞不通之故也。当以理气和胃，疏肝之药治之。临卧服礞石滚痰丸二钱，以逐胸中之余瘀，从大便而出，则胃中清爽，而胸膈自宽矣。", "11433": "崔场官令堂，内有郁痰郁火，外受暑热之邪而成疟，痰所以胸膈不宽，热极则大小便下血，脉息滑大有力，此痰与瘀血，互相纠结于胃也。先以礞石滚痰丸，逐其胸中之痰与瘀，使其下行，然后以豁痰清暑之药治之。", "11434": "金山卫周伦序案，素有疮疾，此脾虚而有湿热也。迹来胃中有痰，肝家有郁火，暑热之邪，乘虚而袭。所以胸膈不宽，外畏风寒，脉息左手沉弦，右手滑大，恐其发疟而咳嗽，理宜豁痰顺气，清暑之药治之。", "11435": "嘉兴吴稼村，先天肾不足，相火上炎干胃，则唇口时肿，眼目多眵，脉息数大无力。此乃水衰火亢，正当十六成人之时，精气不足，理宜静养，戒醇酒辛辣之物，服滋阴降火之药，不致酿成劳瘵也。", "11436": "杨店孙允文令政，肝火郁于胃中，不得疏泄，以致嘈杂作酸，经事不调，脉息沉弦带数，此肝火郁而不舒之故也。理宜开郁和胃清火之药为治。", "11437": "嘉兴黄景章，初夏时症发热，两颐红肿，此少阳阳明邪热所致。理应疏少阳之邪，清阳明之热。因滋阴太早，致邪热凝滞，不得发越，上干肺家而咳嗽，痰中带红，脉息数大无力，已经日久，其阴为邪热所耗，酿成劳瘵。宜以滋阴降火保肺之药为治。", "11438": "嘉兴吴汝林案，胃中痰积，纠结而成形，阻其道路，饮食不得下达，月初连发疟疾。此因感受外邪，而胃中痰积窃发也。脉息左手弦，右手滑大，关部尤甚，此胃中痰积胶固不清。先用滚痰丸逐胃中之痰积，从大便而出，继以豁痰理气消积之药治之。", "11439": "崇明方集成，平素多思多郁，以致肝气不得疏泄，胸膈不舒，去夏感受暑热而咳嗽，今已渐愈。夏令咳嗽瘀血些少，脉息左手沉弦，右手滑涩有力，此肝气郁滞。肝为藏血之脏，气滞则血不流行，而停滞于中，随火上升而吐。盖治血必先理气，气行则血自化，理宜开郁疏肝清火之药为治，气行则血流而胸膈自宽矣。", "11440": "苏州杨安浜吕道原案，缘心事怫郁，肝胆之火上升，充塞耳窍而作响不聪，鼻窍亦不利。误用地黄丸补之，其窍愈塞，眉棱作痛，已经日久，投剂参差。脉息左手弦，右手滑大有力，此系肝家有郁火，胃中有痰饮。《内经》云：九窍不利，肠胃之所生也。理宜和胃豁痰开郁清火之药为治，并忌醇酒厚味，戒恼怒躁急为要。", "11441": "吕道原令郎，出痘之时，失于清火解毒，以致发毒，颈间结积累累而起，脉大而火旺，肾水为之耗消，留以滋阴清火解毒之药为治。", "11442": "苏州金维仁，胃中湿热痰饮，气滞不行，郁而为黄，胸膈不宽，饮食不能消化，脉息左手沉弦，右手滑大。此肝家有郁火，胃中有痰饮，湿热不清之故也。宜理气豁痰清湿热之药治之。", "11443": "徽州吴天具，天禀强壮，多郁善怒，性嗜酒，酒性大热，贮于胃中，夜不得安卧，脉息左手沉弦带数，右手滑大有力。此系肝胆之火，郁于胃中，煅炼津液成痰，以致胃中不和，而卧不安也。恐冬令之后，痰随火升而颠仆，为类中之疾。治法宜以豁痰清火，并忌醇酒厚味，戒恼怒，一交冬令，自然却去病蒂矣。", "11444": "嘉兴曹敬先，三年前曾吐下瘀血不计，左边结成有形之块，按之坚实不痛，郁而不舒。目下目睛见黄，小便亦黄，脉息左手沉涩有力，右手洪滑有力，此乃瘀血湿热，互相纠结，郁而为黄，将来鼓胀之基也。理宜清瘀行滞清湿热之药，煎丸并进，并忌醇酒厚味生冷等物，不致酿成鼓疾也。", "11445": "千墩徐楚揍，平昔好酒，湿热之郁于胃者日久，胸膈不舒，眼目小便皆黄，此乃黄疸之疾，恐实而为鼓胀。脉息弦滑有力，此饮酒过度，湿热薰蒸之故也。理宜清湿热利小便之药为治，并忌醇酒厚味等物。", "11446": "严长枢案，饱食用力，则胃络有损，血积不散，留于中宫，随火上升而吐血，血皆厚而黏腻者。此瘀血也。误以肾水不足，虚火上炎之吐血，而以补肾腻膈之药，填塞胸中，积而成痰，随火下注精房，则为梦遗。用补涩之药，则胃中痰愈郁而遗滑愈甚。脉息弦滑有力，此乃胃中之痰，与肝家之郁火故也。《准绳》云：遗滑之症，属郁者居大半。庸医不知其郁，用补涩之药补涩，愈觉郁而不舒，遗滑日甚，胸膈不宽，饮食少进，甚则实为鼓胀。理宜开郁豁痰清火之药为治，胃中清爽，则遗滑自止，所谓澄其源而流自清也。", "11447": "南翔杨简修，病起于思虑抑郁，肝木不能条达，郁于胃中，至去冬一阳萌动之时，木火发越，而胃脘作痛，流走不定，时发寒热，肝胆之火上升，左边头面肿胀，肿处出水，其火得泄而渐平，至今春正月，春令发生之时，木火升腾而冲胃，呕逆不止，而出大汗，木火得以疏泄而渐安。此汗系内火销烁而出，非气虚自汗也。痛则大便不通，所谓通则不痛也。痛则胸膈胀满者，肝木之性，善胀郁，而不得疏泄，故胀而满也。痛时作酸者。肝火郁于胃，亦以不得疏泄也。两胁与小腹，皆肝部之分，故痛则必连小腹，两胁痛时，作胀作呕作酸，皆肝气郁而不舒之故，治法惟以疏肝和胃为主。诊得脉息左手沉弦而小，所以知其肝气之郁而不舒，右手沉滑有力，所以知其肝木郁于脾土之中也。", "11448": "海宁徐南宾，胃中郁痰郁火，纠结不清，阻其道路，胸膈不宽，食物入胃，难以运化而作胀，流于四肢则为麻痹，达于肌肉，则发红瘰。而肌肉跳动不止，胸中时觉冷气上升者，此热极反寒，反兼水化之制也。脉息左手沉弦，右手滑大，此胃中郁痰郁火，纠结不清之故也。宜先服滚痰丸三钱，继以豁痰清火之药治之。", "11449": "杨简修令郎，病起于硝黄火气，冲入于肺，肺下无透窍，外为寒邪闭之。稍有所触，肺中之伏火上升，而为喘急，胃中之痰，随火上逆，则夜不得安寐，脉息左手沉弦，右手寸关沉滑有力。此乃肺中有伏火，胃中有痰饮也。当以清肺降气豁痰之药治之。", "11450": "芦店朱君彩，此症湿热蕴蓄干胃，发于肌肉而为红瘰，遍身搔痒，误以风治，以致多汗，而两足麻痹。此胃中之火上升而不下降之故。脉息洪滑，理宜清湿热凉血之药为治。", "11451": "太仓罗若洲，热而不寒者，瘅疟也。暑热之邪，蕴蓄于胃，食物阻滞而为热也。脉息弦滑，理宜清暑热和胃气之药治之。", "11452": "新场叶子敬，平昔有目疾，乃肝火抑郁所致，木郁于土中久矣。郁则气道不能流通，津液聚而为痰，胃中纠结不清，得外之暑热，互相为患而成疟，已经半月。据云小腹有动气，则知木郁不能条达。面色白而带青，胸膈不宽，则知胃中之痰积未清。服过滚痰丸，去结粪不爽快。又用凉膈散，大便犹不爽快。解得薄粪，始得通畅，口亦不渴，此胃中有痰之故。脉息弦滑，右关尤甚，此系痰食气滞，而不得通畅也。且无痰不成疟，无食不成疟，理当仍用滚痰丸二钱，使胸中痰积，可以荡去，万一疑其虚，而畏用去病之药。若至热不止而有谵语之状，则难于调治，小腹胸膈舒畅，则疟疾自止。孙一奎云：其病最难。故先用攻击，以去其病，病去而始补，方得治法。", "11453": "嘉善胡天球，抑郁不舒，气道不通，外为寒邪所郁，郁久生痰，阻滞经络，周身肌肉麻木，上升则头眩晕，冷汗时出，脉息左手沉弦带数，此肝气郁而不舒也。右手滑大有力，此胃中有湿痰也。理宜开郁豁痰，疏肝之药，并忌醇酒厚味等物。", "11454": "嘉定高溯源，读书作文，饭后写字，胃之上脘，屈曲不舒，有伤胃络，因而阻滞于上脘，非一日矣。今春为外邪触动，肺胃之火，上升而咳嗽，偶食肥腻之物，阻滞肺窍。其嗽停止。而痰与瘀血，互相纠结于上焦肺胃之间，凝滞不通，不能嗳气。至六月间炎暑薰赫，与内郁之火，交相煽动。痰与瘀血，得热则宣通流动，随火上升而吐紫黑黏腻之瘀血二三钟，胸膈稍宽，然余瘀尚未清爽，故不能豁然舒畅。今交秋令，收敛之时，脉息左手沉弦，右手滑大有力，关部尤甚，此肝抑郁，肺胃间痰火瘀滞不清之故也。理宜消瘀理气豁痰之药为治。大凡治血必先理气，气行则痰与瘀滞自解而下行矣。故血症有变而为恶痢者，吉兆也。", "11455": "崇明范锡凡，内有郁痰郁火，外受风寒，遏于肺胃之间，不得发泄，外邪触动胃中之痰火，上干肺家，而为喘急不得卧，嗽出黄痰，方得安枕。脉息左手沉弦，右手滑大有力。此乃肺胃中有郁痰郁火，纠结不清，稍有动触，即时窃发。此痰火之哮喘也，理宜豁痰降气清火之药为治，并忌醇酒厚味等物。胃中请爽，而痰不生，一交春令，病蒂却矣。", "11456": "崇明顾苍求，先天肾水不足，不能荣养，肝木上升，心神不宁，脉息虚大，两尺尤甚。又兼脾胃衰弱，以致饮食少进，四肢倦怠乏力。理宜加味归脾汤，培养心肝，加味地黄九，补肾益精，兼之保养调摄，不致酿成不足之症也。", "11457": "崇明熊天祥，肝家有郁火，胃中有痰饮，痰随火升，则头额作痛，痛极则呕吐酸水，肝火发越，则头痛止，脉息左手沉弦带数，右手沉滑。此痰厥头痛，俗名头风是也。理宜清肝火化痰饮之药为治。", "11458": "桐乡程丹宇，向善啖，家颇丰，膏粱不辍于口，致患郁痰郁火症，数年来不饥而勉食，每立秋则发疟，治疗者无非以六君子汤，补其脾胃，去冬又服鹿角胶数斤，至庚戌春初，潦倒不堪，不能步履，始就医于余。见其喘急异常，喉如锯声，口吐黄黑黏痰不计，按其腹胀大坚实，四肢头皮皆肿，大小便不爽，得成鼓胀，脉息滑大有力。余知其积年之痰，郁于中者既久，无从出路而为患，病势至此，无可奈何，且与豁痰理气之药两进，不见进退。因思数年积聚，胶固坚结，必非寻常，即用滚痰丸三钱以逐之。大便难去，不甚爽快，继又连服五次，大便去黏痰甚多，并以豁痰清火降气之药，早晚托化，胸次稍舒。时交清明节，其内郁之火外达，寒热大作，烦躁不宁，即用黄连清火之药两剂，得以安宁。但郁久之火，用疏而反炽，不能清爽，下注阴囊，肿痛难忍，小便点点不出，以滋肾丸与之，小便始得通利，而阴囊之肿渐平。其如外症除而饮食不进，精神倦怠，三月间初同伊归，途中忽患恶寒，面色无神，脉息虚滑，几几欲脱状，急与独参汤饮之。一晚计服人参六钱，神气稍复，抵家后，大便每日去纯白痰不计，四肢肿胀渐退，但神气不清，妄笑多怒，饮食不进。余曰：此久病之后，元气虚而痰火散漫，上干心主所致。宜用疏补兼施之法，遂以豁痰理气清心火之品，作丸服之，晚用参橘煎二钱。三日后神气清爽，脉亦有神，饮食有味，小便大利，肿势尽平，濒危之疾，至此始无虑矣。竟遵东垣先生疏补之法，调治而愈，三日后精神旺，饮食进而谈笑如常矣。以数年之病，来就余医，其间用药变化一则，知医贵乎圆通矣。噫，是役也。使虑其危殆，而攻伐不施，则病邪何由而去。若干疏导而不事滋补，则元气何以渐充，病势变易不常，方药随手撒换。是知胶固之士，未可与言医也。（原注，凡于久积之后，邪去反有别症，先以言明病家，可无怨语。）", "11459": "饮食阻滞于胃，郁而为火，煅炼津液成痰，外为风寒所触，上干于肺而咳嗽，痰带粉红色，此系咳伤肺络而来。左脉弦细而数，右脉寸关滑大，此乃肝家有火，肺胃之痰，纠结不清也。理宜豁痰降气清火之药治之。", "11460": "先天肾水不足，相火妄动，上炎烁肺而咳嗽，脉息数大，两尺尤甚，此乃水衰火亢下流于肛门而发毒。目下时令炎威，正肺金受制之月，先宜静养，毋躁急恼怒，省言语，避风热，然后以滋阴保肺，纳气降火之药治之。煎丸并进，庶不酿成劳瘵也。", "11461": "肺为娇脏，畏热畏寒，醇酒生冷，夹杂入胃，不得运行，酿成臭秽之痰，肺金受烁，因咳而出，似乎肺痈，实由胃中而来。但薰灼日久，肺气为之耗散，则水之上源已绝，肾水因之亏损，所以左手脉息虚软，右手滑大。此皆水衰火亢，肺金不足。理宜用豁痰清肺之药，以治其痰嗽，更以加味地黄丸，补肾降火，庶得奏效。", "11462": "天禀沉静，未免多思多郁，多思则气结，多郁则肝木不得疏泄，脾土受困，加之饮食不调，以致饮食不化，而致泄泻。经云：湿胜则濡泄。又云：诸湿肿满，皆属于脾。脾不运化，湿气聚而为肿。目下腹皮渐大，头面四肢阴囊阳道俱肿，脉息沉小，暂用东垣风能胜湿之治。然后以加减胃苓汤，作丸服之，缓著处治，庶可奏效。", "11463": "童年而小便浑浊，乃疳积也。热久则腹胀，肌肉消瘦，即幼科所谓疳火，且脉息数大，内火消烁，所以善食，理宜清火消积之药治之。", "11464": "病起于酒热伤胃，胃脘作痛，血热妄行而吐血，火来烁金而咳嗽，久嗽伤肺，不能清肃下降，小便不利，以致足跗浮肿，恐其渐升于上，脉息弦数，烦躁咽干。此乃胃热伤肺，宜清肺胃之热，降气豁痰为主。", "11465": "病起于抑郁不舒，郁则肝气不得疏泄，血为气滞而停蓄之久，则血大下。去血之后，肝火升腾，肺金受烁，以致咳嗽气急。肺失清肃降下之令，小便不利而为胀满，气喘不得安卧，脉息沉弦而数。此肝金郁火烁肺，而为喘急不得卧而肿。治法当以清肺为主，所谓先咳嗽，后肿满者治在肺，肺清则便利而肿退矣。", "11466": "去夏水衰火亢而吐血，今当夏令炎威，其气上逆，而不能下降，脉息洪大带数，两尺尤甚，此肾虚而气不归元也。治宜滋阴降火，纳气归元为主，并宜习静调摄，不然，恐其复发吐血，酿成劳瘵也。", "11467": "平素善饮，酒性大热，贮于胃中，薰蒸烁肺，扰其血分，胃中之血，随火上升而吐，既吐之后，肾水衰耗，相火上炎，而咳嗽作矣，下扰精房而梦遗矣。脉息弦数，两尺尤甚，此乃水衰火亢，肺金受困之象。调治先讲静养，毋躁急恼怒，服纳气补肾清火保肺之药，煎丸并进，庶几渐次奏效。", "11468": "用力过度，有伤胃络，阳络伤则血外溢。所来之血，不鲜明者，乃瘀血阻滞胃中，而不舒畅，加之醇酒扰其血沸腾，脉息滑大有力，此瘀血互相纠结于胃也。暂用豁痰理气消瘀之药治之。", "11469": "所患血症，已经多年，虽用滋阴降火之药，或愈或发，今交夏令，肺金受烁之月，咳嗽不已，血随火沸，上气喘急，午后发热，饮食少进而无味，脉息细数无神。此乃肾虚，而兼脾胃之气困惫也。目下当以胃气为主，先贤治血症，每以胃药收功，而滋阴寒凉之药，暂作缓图，俟饮食时，神气旺，然后再议滋阴可也。", "11470": "少年时用力过度，兼之饮食太过，胃络受伤。阴络伤则血内溢，停蓄于肠胃之中，而成便血。肝火下注，则发为痔疮，有时变为血痢。痢虽止而所瘀之血，逆上而吐，胸膈咽噎之间，窒塞不舒。脉息左手沉弦带数，右手稍大于左而带滑。此系肠胃瘀郁之血，尚未清爽，气滞痰凝，郁久成火。所以手足心烦热，胃中纠结，坚硬有形而痛也。理宜消瘀顺气清火之药治之。俟胸膈舒畅，咽喉清爽，然后以调理之药为善计。", "11471": "三月间木旺之时，脾土受制，得目疾数日，此皆肝火上炎之故。四月间，胃脘为物所触，虽觉不舒，然亦不作痛胀满。已服消瘀行血之药，而胸腹反觉满闷作胀，小便黄赤而短少，脉息弦细而沉，此乃肝木郁于脾上之中，湿热聚而为胀。理宜疏肝散湿热之药治之。", "11472": "咳嗽痰多，胸膈不舒，饮食少进，脉息虚弦，系脾虚不能运行其津液而为痰。土不能生金，肺虚不能固表，又当夏令湿热用事之时，暂以豁痰健脾保肺之药治之。候胸次舒畅，然后以加味地黄丸补肾，为长久之计。暂服煎方。", "11473": "奔走劳动，有伤于肾，肾水不足，相火上炎烁肺而咳嗽，今咳虽减，而真阴亏损，脉息细数，两尺尤甚。所以劳倦乏力，两足痿软，当以滋阴保肺之药为治。", "11474": "少腹右边，结成有形之块，日渐以大，上干胃家，则呕吐而发寒热。此乃瘕聚，借其气以成形，即为子疝也。近因散而至于左边，作痛不宁，脉息弦急，当以疏肝和胃为治。", "11475": "病起于肝气不舒，而成胀满，虽用行药通其大便而渐减，此肝气得以疏泄而退。然肝气郁于脾土之中而复胀，脉息弦数。此乃木旺火衰之象，理宜和胃疏肝为治。", "11476": "湿热郁蒸而为黄疸，因胃中有湿热，所以作胀作酸作肿，并有带下，脉息滑大，治宜清湿热之药为主。", "11477": "经云：三阳结谓之膈。三阳者，大小肠膀胱也。结者，热结也。热结于下，则反之于上。丹溪云：噎膈之症，多起于血枯痰腻。大忌香燥热药，惟以豁痰降气清火润肠之药治之。今脉左手沉弦，此肝气郁结也。右手滑大有力，此胃中痰火纠结不清也。郁则气结津液聚而为痰，阻滞食物，不得下达，随肝家之郁火上升，则呕吐而出。（原评，理明词达，言之了然。）先讲习静调摄，一切俗务，俱置度外，然后进药，庶几奏效。", "11478": "平素善饮，则知胃中湿热，纠结不清，湿胜则濡泄，所以大便泄泻，湿伤筋，所以手足牵引。湿生热，热生风，肝主风，肝开窍于目，所以左目小而右目大。脉息左弦右滑，此乃肝木乘脾也。（原评，语皆有本，如洞见五脏。）理宜扶脾疏肝为治。", "11479": "咳嗽之后，脾胃两虚，以致五更泄泻。此乃肾虚不能闭藏，脾虚不能健运之故也。脉息虚小无神，理宜健脾和胃之剂，先服煎剂以健其脾。忌生冷油腻，使易于运化也。", "11480": "咳嗽吐痰带血，尺脉不宁，夜卧不宁，梦寐颠倒。", "11481": "咳嗽已久，性情多郁，产后饮食少进，而胸膈不宽，或时作酸作胀，大便不实，脉息弦数而细，脾土虚而肝木郁，肝火来烁肺金也。暂用扶脾疏肝之药，使胸次舒畅，然后以滋阴培本，为善后计。", "11482": "胃中痰饮积聚不清，上泛于目，以致目睛昏瞀，胸膈不舒，饮食不能运化，脉息弦而带数，右手滑大。此系肝木郁于胃中，随火上泛而为呕也。理宜和胃豁痰燥湿清肝之药。", "11483": "胎前内热，肝火不得疏泄，下注而为泄泻。经所谓暴注下迫，皆属于火。既产之后，时当春令，正木火生发之月，未清之血，停滞下焦，发为肠痈脓溃之后，复为痢疾后重逼迫，腹中作痛。肝火上升，则目眵不清，且煅炼津液，而为带下之症。脉息弦数，面色白而带红，此皆肝火煽动也。治宜清肝火，疏肝气之药为主。", "11484": "经云：治病必求其本。本者谓究其治病之根蒂也。喻嘉言曰：先议病，后议药。先生之病，已经数载，而致病之源，缘先天肾水不足，不能荣养肝木，肝火上冲于胃，胃中津液，为火煅炼而成痰，纠结不清，薰蒸清虚之府，鼻窍闭塞，以致瘜肉内生。肺虽开窍于鼻，而其经络属胃，胃脉挟鼻孔，因胃中之痰火，闭塞其窍也。胃脉萦于面，环唇口，肝火冲动，则口唇与面，肌肉牵引而动。肺之脉络，从胸走手。经云：诸气𪱥郁，皆属于肺。肺气壅塞不通，则由其经而注于手，寸口鱼际之脉跳动，因肺朝百脉，合于寸口也。然肾为生痰之源，胃为贮痰之器，行则为津液，聚则为痰饮，得外风寒所触，痰火内发，则口眼为之歪斜。口属胃，眼属肝，木火煽动之故也。年来虽不为意，恐痰火郁于胃中，日久乘元气不足之时，外邪干入内之痰火，窃发升腾眩晕，卒然有颠仆之虞，乃类中之基。况向交秋即发疟疾，亦是胃中之痰。因夏令之暑邪，藏蓄于胃，得风寒所触而发，所谓无痰不成疟，疟外发则痰亦得以外达，不致攒而为患。诊脉左手弦大，右手骨大不静，此胃中之痰不清也。调治之法，必先清胃中之痰火，通其闭塞之窍，使肺气清肃下降，然后滋水荣木之药治之。", "11485": "孙特士，平素善饮，于三月间饮酒已醉，卧于桥上，堕水抱于桥脚一二时，邻人始得救起。觉浑身头项筋脉不舒，洒淅恶寒，即往松郡卖布。有医者不行疏散，竟以劳倦治之，归家咳嗽，继之吐血。又一医者用地黄汤治之，胸膈不宽，亦不沉饿，寒热如疟。又以疟疾治之。此乃形寒饮冷，肺受水注，郁而发热咳嗽，此时未免有伤瘀血凝滞胃家，咳嗽气逆，随之而出，不去消导行瘀，反用地黄凝滞之药，壅塞道路，其势更甚，其气愈逆。彼为无子抑郁，脉息数大无伦，余亦议其内败，虽用疏理之药，亦不取效。此症与少游相同，但其误用地黄凝滞，竟至不起。", "11486": "秦照临，夏月感受暑热之邪，至秋患痢，不数日下药行之，积物不忌，壅塞胃中，不得通泰。火邪不得发越，以致呃逆，面赤两目俱红，舌见黑苔，大便后重，小便黄赤，脉息沉细而数。此热邪为食物郁遏，不得条达通畅而为呃逆，暂用", "11487": "疏其胃中之壅滞，大便去结粪与积滞不计，胸次宽泰，伏火内发，舌愈黑燥，口渴喜冷。用六一散水调服，并西瓜汁、蔗汁陆续饮之，以石羔、黄连、枳壳、连翘、厚朴，朝服一剂。二日共计六一散二十余碗，西瓜数枚，舌退黑，而呃亦止，口亦不渴，面目之红皆退，小便清白，大便爽快，积滞已无，脉息反大而不伏。然后进以粥饮调胃。此因暑邪郁遏于内，寒凉太早，兼之食物壅滞而成此症。故必疏理肠胃之郁滞，使之宣通无阻，后用清火凉药，冷水西瓜，逐其火邪，使之下行，得以全愈。若不先疏理，而竟用寒凉，则热邪郁遏肠胃，必致败坏而毙。所以用药之法，先后不可紊也。", "11488": "上洋周湘文，年已五旬，三月间步至松郡，百里忍饥，面红脉大，汗出如雨，口不渴，神思倦怠，夜不能寐，诸医皆以石羔黄连清火为治。迎余诊视，余曰：此热伤元气，加之劳倦内伤，肺气不能固表，脾虚而倦也。", "11489": "宛老，患休息痢已经二载，脉息洪大带数，腹皮如络，小便黄赤而不禁，有时梦遗。恐其发热咳嗽，酿成劳瘵。因久痢伤肾故也，治宜补肾为主，此治本之法也。", "11490": "久痢伤肾，酿成阴虚之症，目下阴火上冲，饮食不得下达而呕逆，脉息细数，声音不出。此乃水衰火亢，肺金烁理，宜滋阴保肺降火之药治之。", "11491": "恪修兄，肾水不足，相火上炎，血随火升，继之咳嗽，已经半载有余。脉息虚大带数，尺部尤甚，此乃劳瘵之基也。理宜静养调摄，屏却俗务，服滋阴降火之药为治。", "11492": "血症之后，肺金受火燔灼而咳，此本原病也。目下感受暑风之邪，咳嗽而头痛，脉息浮大而虚。此外邪乘虚而侵肺也。暂用清肺理气疏散之药，俟前症减后，再进补剂。", "11493": "朱焕舆，四月起，右脚底肿痛，渐至四肢骨节疼痛，不随运用。八月又加干咳嗽，胃中常易受寒。目今头项不能转动，头俯不能仰视，两肩不举，转侧俱要人扶，两手无力，卧则臀压胁，难于移动，手指不能举捧，足心发热，午后更甚，且作痒，腰下至脚，皮肤绷急，骨节酸痛，不能步履，右脚更甚，嗽吐黏绵痰涎沫，大便干结，四五日一次，粪后间有红，语言多句，气即不能接续，必有干咳，尊体肥厚。丹溪云：肥人多湿痰。四月乃纯阳之月，热气薰蒸，下流于右足底，以致肿痛，右属脾胃，湿胜则肿，四肢亦属脾胃，胃中湿痰壅滞，无从出路，流于四肢骨节，而手足不能运用。此乃痿痹之症，属湿痰湿火，蕴蓄于肠胃，肠胃不能容受，流及于四肢肌肉之间，而为患也。（原评，能识病源，故许多病症皆滴滴归源，且有确据，非同俗医之循墙傍壁附会其说者比也。）其痰上干于肺，则为咳嗽。肺主皮毛，故易于感冒。肝主筋，头颈皆属肝，湿伤筋，故头不转动，俯不能仰视，两肩不举，湿胜则体重，故不能转输运动。湿热下流则脚底热。午后阳火亢盛，助其邪气，故其热更甚而作痒，湿热下注，故皮肤绷急，骨节作痛，不能步履。脾胃在右，病在脾胃，故右更甚。胃为贮痰之器，胃中热气薰蒸，煅炼津液成痰，随火上升而咳嗽。大便燥结者，热药补剂，壅塞不通之故也。血得热而妄行，热药扰其血分，则粪后见红。肺气壅盛，则语言不能通畅而接续，火气上炎烁肺，则干咳，脉息沉滑有力。种种见症，皆属湿痰湿火，蕴蓄于肠胃，流于四肢，而为痿痹之症也。服温补热药太过，壅塞经络，难于一时奏效。惟以豁痰清火，通行经络之药，煎丸并进，庶可渐次见功。一切醇酒厚味难化之物，并宜暂戒。", "11494": "林兄，因饮酒而伤胃，酒性大热，扰其血分，而吐血加之，抑郁不舒，胸膈不宽，气上冲逆而咳，浊痰，脉息沉弦带数，两关尤甚。此系气滞血凝于胃，上升而来也。治宜消痰降火理气之药为主。", "11495": "受病之源，得之恼怒郁结，以致肝火升腾，上干肺金而咳嗽。肝为藏血之脏，因咳极致血，血随火升之故，热极觉有腥秽之气。而肺金痿之病，自春至秋，金得令，肝木受伤，吐血复作，连日气逆于上，胸膈不舒。治血必先理气，气降则血自归经，俟胸膈宽畅之后，再议滋阴，此先后缓急之法也。脉息左手带弦，此肝火妄动也。右手滑大，关部尤甚，此胃中痰瘀纠结之象也。理宜豁痰降气消瘀之药，先疏其胸膈之滞，然后以清肺滋阴之药，仍兼消痰以治其本，庶可渐奏效。", "11496": "渭兄，受病之源，得之平素多思多郁，思则气结，肝气郁于脾土之中，不得疏泄，下注肛门而发痔。肝为藏血之脏，血得热而妄行，郁火妄动，扰其血分而下注。去血之后，面色自然㿠白。肝主疏泄，肝火扰其精房则梦遗。脉息沉弦带数，夜卧则口干烦躁，此郁火薰蒸也。语言响亮而不怯弱，饮食有味，多则作胀，此肝气郁于脾土之中，不得疏泄之故也。种种诸端，皆属肝气抑郁。时当冬令潜藏之月，正木火藏伏于内，不得泄越而致病，理宜加味温胆汤为治。", "11497": "沈益友夫人，受病之源，得之怀妊，胎气壅滞，加之夏令暑热之邪，蕴蓄于内，发为痢疾。至九月终分娩之后，腹中空旷，内伏之火，乘机外达，上干肺金，而咳嗽气急，肺受火烁，不能清肃下行，致小便不利而肿，嘈杂呕吐痰涎。《内经》所谓诸逆冲上，皆属于火。又云：诸呕痰喘，皆属于上。上者，上焦肺胃也。因肺胃薰灼之故，其气逆上而不得卧。小便热而作痛，大便后重逼迫，脉息弦数。种种诸端，皆由暑热之邪，伏藏于内而致。理宜和胃豁痰降火降气之药为治。", "11498": "千墩马九成，得痿症，每有所触，即卧床不起，痿软无力，饮食如常，亦无寒热，夜不得卧，神魂不宁，绵延几月，渐次步履而安。去冬火气潜藏之时，其病复发。究其受病之源，得之饥饱不时，胃气受伤，脾不能运，津液为火煅炼成痰。上干心窍，则神不宁而不得卧，头眩耳鸣。脉息左手微弦，右手独见滑大有力。此系胃中有郁痰郁火，稍有所触即窃发。经云：胃不和，卧不安。阳明之热，薰蒸肺金，则痿而无力。又云：诸痿皆属于肺热。故治痿独取阳明，当以和胃豁痰之药为治。", "11499": "唐册垂，湿热痢。医家唐若如用归脾汤，加苡仁、扁豆、干姜，丸方用白术、茯神、枣仁、黄耆、破故纸等药不愈。延余诊视。予曰：大凡治病先以议其受病之源，而用药庶几合式。如册垂兄之病，因平素嗜酒，则知肠胃间湿热蕴蓄不清者久矣。加之夏令外受暑热之邪，内伏之湿热，乘机而发，为痢绵延连岁，每至秋冬起病之期，必然复作。仲景云：下痢至其时复发者，此下未尽，复下之。因脾主信故也。前者又有黄疸之病，则知湿热为患无疑。目下发而难愈，腹中作痛，后重逼迫，所下者皆赤白，面色痿黄，两足浮肿，倦怠乏力，小便短少，脉息洪大有力，此湿热之邪未清也。理宜清湿热，利小便，理滞气为治，乃为对症之药。今阅前方参耆术补气，则湿热之邪，何从出路；用枣仁远志，似乎养肝安神，而并无此症；既用扁豆苡仁实脾，又用当归润肠，自相悖谬如此；赤水下迫，而用干姜助火；至于九月终，又用破故纸补肾火；肉豆蔻暖脾止泻，又加当归润肠之品，不知何故。况痢与泄泻两症，大不相同，竟将混为一途，大非前肾之法，乃张景岳混同立论之谈也。", "11500": "骏老，平素畏寒恶风，此内有郁火也。郁火发越，则又畏热，胸膈阻滞不通，大便燥结，食物入胃，至晚作酸而呕。脉息沉弦而数，两关尤甚，此系肝火郁于胃中，煅炼津液成痰，而作酸，随肝火上冲而呕吐。并有白沫而冷者，乃热极似冷，非真寒也，是乃噎膈反胃之基。经云：三阳结谓之膈。三阳者，大小肠膀胱也。结，热结也。热结于下，则反之于上。治之法，先宜和胃豁痰开郁之药，理其中焦，然后以养阴之品，润其大肠，庶得奏效也。", "11501": "茂兄，平素嗜酒多怒，此胃中有湿痰湿火，肝气郁而不舒，湿火上蒸则多汗。怒伤肝，肝血为之上升而见红，脉息左手弦大，此肝火妄动也。右手滑大有力，此胃中有湿痰湿火也。下流于大肠，则为痔疮。理宜豁痰清火之药治之。", "11502": "胃中有郁痰，随火上升，闭其心窍，则神昏而咽喉塞碍，脉息弦滑带数。此系肝火薰灼津液，口干舌燥，上蒸而为汗，乃类中之基也。理宜清火豁痰之药为治。", "11503": "德言兄，天禀肾水不足，不能荣养肝木，肝火妄动，血随火升而见红。见红之后，未免忧思抑郁，胃中津液，煅炼成痰，纠结于中，饮食少进，胸次不舒，痰随气逆而咳嗽。脉息两关沉滑带弦，此肝气郁于胃中，不得条达之故。今值君火司天之年，又际春夏之交，正炎炎之势日炽，虑其肺受火灼，而咳嗽更甚。惟以凉血清火开郁之药，为善后之计。但治血必先理气，气降则血自归经而不升，痰亦随气而下降。肺主气，卧则肺叶布散，则气为之上升，非肾虚而气不归元也。", "11504": "娘娘受病之源，缘肾水不足，不能荣养肝木。肝火升腾，颈间结核，累累甚多，肝火上冲则呕吐。用八味丸服之相妥者，因胃中痰火，得热药开通隧道，同气相求，似乎相安。然积之已久，助火消阴，交君火司天之年，积热窃发，火气上炎，汗出发热，痰中带红，寒热如疟，经事不来，脉息弦大带数。此系水衰火亢，肺金受伤之象。理宜滋阴清肺，豁痰降火之药治之。", "11505": "士老向有痰火，郁于胃中，上升则眩晕，不得疏泄，则嘈杂似饥。上烁肺金，则痿软乏力。散于四肢，则手足心烦热。脉息沉数带滑，右关尤甚，此系胃中郁痰郁火，所以结成有形之物。理宜豁痰清火理气之药为治。", "11506": "案龙为兄受病，得之外伤暑邪，内伤食物，停滞胃中，煅炼津液成痰。至冬令为外邪所触而发疟，四五发即止者，冬令潜藏故也。至来春，其余邪留滞，加之郁怒伤肝，交春令发陈之月，肝木用事，木性善胀，食后胃中胀满，不得下达，肝火上冲而呕吐，其时即应疏达肝火，兼扶脾胃，则吐可愈。乃服资生丸，内中参术山药莲肉扁豆芡实等药，皆闭气凝滞之品，其肝气不得下达，而至病之不愈也。又服八味丸香燥等药，肝火愈炽。大凡疝症，系内有肝火，外受寒凉，抑遏而成，反用八味助火，甚悖谬。内有地黄，乃凝滞之药，故胃中壅塞不通而痛，阳明旺于申金，故胀满而痛更甚。肝气上逆冲胃，胃中之食物吐尽，交五更阳气，肺金主事，金旺则木平，故能安睡。此皆肝气郁于胃中，不得通泰而致病也。交春令木旺生发之时，肝气得以疏泄，至夏令木性垂枝布叶，尽发于外，所以疝气全愈。然其余波尚未尽除，故有时胃痛呕吐。是岁十一月，正一阳初动之时，胃中所伏之火，外为风寒所触，饮食不进，其火流注腰背，不能外达而作痛。冬至遏郁不舒，郁蒸而为黄疸，胃主肌肉，湿热薰蒸则发痒，小便短赤。黄疸时其湿热得发于外，故胃痛呕吐不发，黄疸愈，则湿热之邪，复留于内，所以胃痛呕吐复作。若遇膏粱厚味，壅滞胃中，则蒸而为汗，发于肌表，而作瘙痒。种种诸端，皆属胃湿热痰饮纠结不清，肝火郁而为病，所以脉息左手沉弦，右手滑大有力。治法先讲薄滋味，戒恼怒，避风寒，并服豁痰清肝理气之药，自然却去病蒂矣。", "11507": "以兄，右半唇与发际牵引作痛，至春则发，秋冬则愈，已经三载。诊其受病之源，乃少阳之火，郁于胃中，不得疏泄，至春发陈之月，内伏之邪，应时而外达，秋冬则为之敛藏故也。脉息沉弦带数，乙木郁于坤土无疑矣。治宜疏肝火，使其外达，自然平安也。", "11508": "南兄，少年时多饮火酒，酒性大热有毒，积于胃中，下流而发毒，脓溃之后，余毒未消。补之太早，热邪流注于膀胱，而小便为之淋漓作痛，结为沙石，屡次窃发。今交君火司天之年，其发频而尤甚，小腹胀满不舒，脉息弦数。此系肝火郁于膀胱，煅炼津液，而成黏腻之物，瘀塞溺道，而淋漓作痛也。理宜清肝火理滞气之药为治，急戒醇酒厚味恼怒，则胸中清爽，而小便自利矣。", "11509": "平素多思多郁，郁久成火，得风则炽，而发寒热，交春发陈之月，内郁之火，因时窃发，无从疏泄，则皮肤之间，流走作痛。郁于内则胸膈胀满，而口干气急，饮食不得下达，郁火煅炼津液，大能荣养大肠，则大便为之燥结，五六日解一次。脉息沉弦带数，此乃郁火煅炼津液成痰。阻滞胃中，所以不饥不食。理宜先通大便，则上焦之郁火，从此下降，并以理气清火之药，使其经络宣畅，所谓通则不通也。", "11510": "策兄，有胃脘作痛之病，缘醇酒厚味，积于胃中，扰其血分，停滞不通。值今君火司天之年，血随火升而吐，其色黏腻而红者，此瘀血也。脉息右手弦数，左手沉滑，此乃肝火妄动，胃中之痰，与瘀血互相纠结，上干肺家而咳嗽，胸膈不舒，饮食减少。暂用滚痰丸二钱，郁金汤送下，以逐胃中之痰瘀，从大便而出。然后以消瘀豁痰清火顺气之药，去其余波，则胸次宽舒，不致上升而咳嗽吐血矣。", "11511": "圣翁，天禀素弱，暑热之邪，乘虚袭入而发疟。疟止之后，暑邪未尽，下流于两足而作痛。服八味丸补中益气丸，若果系虚症，服之宜气体健旺，何至愈加疲惫而作痛，则知邪气未尽，而误补之故也。疟之发，亦因胃中有痰，暑热之邪，互相结成而起。因服补药，胃中之痰，郁遏不清，积之已久，至春令发陈之月，内伏之火窃发，上升则齿痛，因阳明胃脉，环唇口入齿，伏火由其经而泄。胃为贮痰之器，津液为火煅炼成痰，至清晨阳气升腾，痰随火升，所以语言不能。大凡痰病得热药开通隧道，似乎相安。旋即热势愈盛，真阴愈耗，反令内火薰灼，所以畏热，热极消烁，下注而小便为之多。火升则齿痛，火降则痛止。积热之久，消烁津液，而为三消之症，久之实为鼓胀，或发痈疽，则为不治之症。目下胃中之火炎于上，则齿痛耳痒，脉息沉涩。此痰火郁结于胃，不得宣通之故。理宜豁痰清火之药为治。", "11512": "陆占贤令媳，平素肝家有郁火。肝主疏泄，为藏血之脏，肝火扰其血分，血得热而妄动，故易于堕胎。所以小腹攻冲不定，小腹者，肝之部分也。胆为肝之表，肝病而及于腑，则上升于头，而为头痛。因少阳之脉，起于目锐眦，而抵头角也，痛则昏沉而不清。因胃中之痰，随少阳之火而上升，故饮食少进而无味。肝为风木之脏，肝火消烁，则肌肉为之消瘦，即《内经》所谓风消也。每至午后火升者，盖肾肝为阴脏，肾肝之阴，不能荣养，故至阴分，而少阳之火上升，而头痛也。种种诸疾，皆由肝胆之火，郁而不舒。理宜暂用疏肝清火开郁之药，俟发热头痛已愈，气不攻冲，然后再商调补之策。", "11513": "季先之病，得之饥饱劳役，有伤胃络，以致瘀血凝滞胃中，结成有形之象，按之而痛，痰中所带黏腻不鲜明之血。食物阻滞，难以下达，郁而不舒，则作酸嘈杂。大便艰涩，小便黄赤，脉息沉弦带数，此系瘀血纠结于胃。理宜消瘀行滞之药，逐其瘀血，从大便而出，自然奏效。", "11514": "嘉兴杜景山，景老胃中有痰，肝家有火，下注精房而为梦遗，误用温补涩精之药，痰火壅塞，下行薰灼血分，而为便血。血虚不能荣润大肠，则大便燥。痰火上升于头，则眉发为之脱落。肝火下注，则小便频数。种种诸端，皆属痰火郁于胃中，误用补涩之药，无从发泄，而诸症蜂起。时交相火司天之年，夏令炎热之月，所以脉息左手弦大，右手滑大。理宜暂用豁痰清火之药，以治其郁结，俟爽之后，再以滋阴药为善后计。", "11515": "胃中食积，与肝火郁滞不通而为胀满，肝火薰蒸于上，则两目昏暗，脉息弦数不静。此系肝火郁于脾土之中，湿痰食积，互相为患也。理宜清湿消道之药治之。", "11516": "久疟之后，胃中顽痰未清，郁而为火，上炎于面而红，下注手足而肿，闭其经络而麻，脉息两关滑大。此系郁痰郁火为患，宜以豁痰清火为治。", "11517": "疟疾而兼咳嗽吐血，脉息细数而侧眠，此劳疟也。理宜滋阴保肺之药治之。", "11518": "胃中有胶痰，肝家有郁火，肝主疏泄，其火上升，则头角多汗。肺胃居右，其火旁流，则两手亦多汗。胃为贮痰之器，得肝火煎熬津液成痰，胶固难出，得火之上升，其痰随之而出。自觉畏冷，此热极似寒，非真寒也。肺主皮毛，主宰一身之气，而外卫皮毛，稍有不足，其邪易于侵袭。痰气流于四肢，则手指麻痹，肝气下流于阴囊，无从疏泄，则肾子胀痛。上升则有头晕目眩耳鸣等症。诊得脉息左手弦大不静，此肝火之妄动也。右手滑大有力，关部尤甚，此胃中有胶痰，肺气壅滞不行，故胸膈不宽而胀闷，得气展舒运化，则觉舒适。种种见症，皆属痰气凝结，肝火郁而不得条达、通畅之故也。先宜豁痰理气降火之药，使气行而不滞，火降而不升，庶不致猝然颠仆而成类中也。又恐其痰气留结而为噎膈反胃之症，故不得不防微杜渐，而预为筹划也。", "11519": "少阴所至为疡疹，少阳所至为疮疹。少阴者，君火也。君火为当令之火，或上下左右间主步之火，亦为当令，故诸痛痒疮疡，皆属之少阳者相火也。相火为不当令之火，游行于木土金水之时，不期而至，即四时非节之暖也。少阳与厥阴为合，肝与胆其潜使之乡，胞络之焦，其游行之地。其势一至，则胞络之间，膻中之位，不啻积薪厝火，其人必郁郁不乐，寒不甚而热不甚，口干烦冤，目泪颧红，或四肢微厥。其热上薰于肺，肺主皮毛，故发红点，是为赤疹，赤疹必无汗而毛燥。若有汗者，热势已达，其点淡红而稍大。若重感于邪者，于表症中兼见前证，亦必俟其透达而后得解。故初时禁用苦寒，恐其冰伏耳。世人皆知癍疹初起，忌用寒凉，殊不知忌用凉药者，疹证而非癍症也。治少阳疹症，始终不可离凉膈之剂，亦不可加引经药。果见兼症，悉照下论，加入于本方。非若治他症表下和为各别也，其症非比癍症，同看甚至连六七次者，后发白色者方止。其主洁古消风散，即凉膈去硝黄，取甘桔荆翘芩栀薄荷赤芍木通，直达膈间，消风散热，毒气自然解散。已出之后，再加大力僵蚕元参之类，以化其蕴蓄之毒。兼表者合香苏芎苏之类，势甚者十神汤。然隆冬初春，庶几相宜，春夏秋三时，在所禁用。因麻黄为寒伤荣者之专司，而葛根升麻，虽轻扬解表，实阳明经药，但可借用，非本症药也。火势甚于内，目赤唇焦，口干谵语，本方加黄连。热甚于表，口渴而脉大汗出者，本方合白虎。往来寒热，脉弦不解者，本方合小柴胡。府实内结者，本方硝黄以润下之。余热不退，本方加生地丹皮之类，以养其阴。此用药之概也。至若历来方书，皆云癍出于阳明，疹属于太阴，癍主于火，疹主于湿。湿之一字，大谬不然。夏月暑热合邪而发疹者，或有之。脾经湿热，兼发水疹，久之为疥疮者，或有之。此外无疹症之理。盖皆误认膈热薰肺之手太阴症，为足太阴症耳。膈热薰肺四字，为疹症之准绳，发前人所未发，其辨点之法，方书皆云癍无头粒。殊不知癍无头粒，反湿于皮肤之上，历历可数，其重者如云如锦，而于云锦之中，必有点如朱笔点就者。疹有头粒，反若隐若现，辨之不甚分明，随出随没。癍本于胃热，见点便忌升提，急急化癍，尚虑胃烂。疹则先出者已化，后至者尚多，惟有始终清解而已。故凡大青犀角石羔黄连，癍症药也。升麻葛根为失表为癍之表药也，承气汤治失下成癍之里药也，人参白虎汤，体虚发癍者之对症药也。总之，四时六气，感之皆为外感，皆能兼见癍疹。一见癍疹，便不复传经转属。盖阳明土也，药物归之，无所复传。邪形似水，望其低下处而就之。膈间既热，无邪不入，无入不成温热之邪，一发为疹，疹为病本矣。但发疹之症，冬温与春温之症最多，不知何故。意者，冬时寒为正令，温暖之令，反为异气，岂即所谓少阳所致耶。冬伤于寒，寒毒藏于肌肤者，每多连膈耶。近老月令广言，冬时醇酒厚味，向火围炉，过于温热者，多病于春，多发麻疹。真先得我心矣。又癍疹决非阴症，决无热补之理。方书虽有阴症发癍一条，然必症阴脉阴。内真寒而外假热，癍色淡而面戴阳，善于临症者，自能辨之，但治其病，而癍自愈矣。又有内伤发癍一症，亦必勤劳之辈，体虚之人，而又过食冷物，迫阳气浮于肌表，而发淡红点。内伤外感，判然不同，细考东垣法，自能辨之。前辈尚有极癍之说，病至既危，身有几点赤癍，与癍无异，气血浇漓所致，非癍症也。小儿疟痢临危极多，予见之数矣。", "11520": "外舅沈菊人先生，工诗善画，而尤肆力于岐黄，凡经络、脉理、药性、病情，无不讲求而熟习。疗人疾苦，响应如神，无他，其用药当也。李莜云茂才，吕伯纯上舍，为先生及门高弟，尝勖之曰：「医虽小道，实为苍生性命所关，务须明辨慎思，思必求确切，然后已。盖所谓知之明而处之当也。」二子禀承师训，精思力索，融会贯通，抉奥阐幽，洵足传先生之衣钵。讨论之暇，尝选先生近诊之方，汇为一帙，朝披夕览，以为临证权衡。余受而读之，分门别类，朗若列眉，论证精详，制方工稳，不胶成见，不泥古书，辨异中之同，审同中之异，得心应手，处之泰然，诚足与《肘后》、《千金》并作枕中之秘矣！虽寸鳞片爪，不足尽先生之长，而缕析条分，实足启后人之悟。苟能循诵习传，由是而进求经旨，则沿流溯源，亦可日进乎高明，倘亦二子之所志乎？读既竣，因书此以质二子。", "11521": "（案2）顾。夏秋痃疟，延及半年，真阴被劫，而又封藏不固，精摇乎寐，阴精日夺。古人云：冬不藏精，春必病温。吸感温邪，遂为咳嗽。胁痛，身热，自汗，热解不尽，风阳上烁，阴气重伤，致虚焰之火升腾于上，口糜滋腐，妨谷，神疲，脉虚数，两尺空。此根本先拨之兆，难免虚脱之虞。既承相招，勉拟泄化救阴，以冀挽回于万一。", "11522": "又：温邪劫烁阴津，阴乏上承，少火悉成壮火，虚火上焰，蒸为口糜牙疳。昨进泄化救阴，病情稍有转机，惟脉象虚数，无神，两尺全不耐按，则仍根本之未固也。至于神倦嗜寐，仲圣所谓少阴病，但欲寐，是肾经见证确矣！今宗其法，拟救阴护阳，以冀阴津来复，脉象有神也。", "11523": "又：进救阴护阳法，阴气似乎稍复，脉象略有精神，惟两尺仍不耐按，是积虚之阴骤难恢复，已亢之阳仍在上腾，故口糜龈腐，犹未退也。仍宜毓阴泄化。", "11524": "又：上腾虚炎之火，得滋而熄，下焦久涸之阴，得补而复，口糜渐退，胃气稍苏，此佳境也。惟咳嗽痰稠，小溲短赤，上焦清化之原犹未肃也。脉见右寸独数，左尺尚不耐按，乃肺有余热，肾乏阴精也。上实下虚，金水同源，法当清上实下矣。", "11525": "又：肾为水脏而司二便，小便频数，腰酸且痛，脉左尺独弱，右关独大，此肾阴亏而胃有余热也。法当壮水之原，兼泄阳明客热。", "11526": "（案3）张。温邪挟湿，病来五日。神志乍昏，呓语寒战，肢冷囊缩，头痛，舌红，苔白，口渴不嗜饮，饮下即吐，脉沉数，咳嗽气急便溏。此肺胃温邪因病前夺精，阴气先伤，阳邪乘虚内陷阴经而致。阳独治上，阴独治下，营卫二气不和，邪不达表而陷于里，阴道虚之故也。以仲圣黄连汤两和阴阳，非偏寒偏热之法也。", "11527": "又：肢温寒热稍轻，咳嗽气急，苔白舌红，呕恶面赤，呓语夜重日轻，脉右浮数，疹点隐隐，便溏，是肺胃温邪欲达未达也，仍以和之。", "11528": "（案4）瞿。温邪最易消烁阴津，火升气逆，阴气不为我用。痰稠溺赤，气化失于清肃，寐后神识似乎模糊，此心阴虚而神不内守也。脉象左弦沉数，右细。心肝之阳未平，肝肾之阴已虚，以清上实下为治。", "11529": "（案5）张。冬温始起，寒后发热，呕吐痰涎，食物带血，咳嗽胁痛，胸闷，便溏，头胀，脉浮数，无汗，此里热外寒，郁表络伤，失血，病在肺胃，防其昏重。", "11530": "（案6）陈。温邪两候无汗，咳嗽痰稠，口糜牙疳，午后火升气逆，此阴气空虚，肺失清肃，夜则呓语，脉沉弦数。邪火逼烁阴津，慎防喘脱。", "11531": "（案8）宋。温气内伏，被寒邪所遏，形寒无汗，口渴舌灰白，脉浮数。气逆火升，老年胃津阴液皆虚，恐其液涸。", "11532": "（案9）奚。温邪十六日，从未有汗，表邪因而不达，逆传入里，神昏谵语，脘中拒按，舌红苔白，脉来浮数，咳嗽不畅。此肺胃温邪蒸灼气营。曾经便泄，邪滞于里，表里同病，法当表里同治。但里未结实，热亦未衰，姑以清解气营。", "11533": "（案10）周。温邪十六日，曾经便泄，虽属邪从里泄，而热邪易于内传。咳嗽不畅，舌白苔干，口渴自汗，脉沉数，神志乍有昏蒙。肺胃温邪煽烁阴津，风阳化燥也，防其风动。", "11534": "（案11）张。病前向有梦泄之疾，已知精气空虚，又感秋温，至冬发泄，形寒身热已及旬日，头痛且眩，耳鸣惊惕，风动肢牵。呕吐酸苦痰涎，舌红且干，苔白而剥，口渴。脉软数，全不拒按，溲赤便溏，呃逆。此热灼阴伤，厥阳化风上扰，胃虚挟饮，阴涸风生，势有痉厥、汗脱之险，且拟和阳熄风。", "11535": "又：昨投和阳熄风，肝风未定，呃逆稍正止，身热亦解，自汗，惊惕，肉𥆧，头眩，目花，耳鸣，肢搐，神识寐则模糊，心虚，吐蛔吐水，小便不爽，脉象虚弦，左寸涩，右尺空，此中下虚，肝风冲侮阳明，胃虚积饮，肾水上泛，痰黑味咸，木火烁液，舌赤津涸。病情肾阴虚馁，木失水涵，汗脱痉厥，势属可虞。议填纳下焦，壮水涵木，仍参熄风和阳。", "11536": "又：呃逆呕吐皆止，风阳鼓荡不息，时有肢牵，心神模糊，寐则呓语，神明涣散，自汗，懊𢙐，舌光液涸，头晕目花，脉虚弦。水亏木旺，内风未靖，仍属阴阳撒失乖离之象，宜固摄潜阳，敛神熄风，望其风定神清，汗止。", "11537": "（案12）蒋。温邪触发伏邪，寒热咳嗽，胸闷气逆，少腹胀痛，眉心痛，便溏溲少，脉弦数，阴气素虚，肝阳化风挟痰火上逆，痉厥连次，鼻煽自汗，神识模糊，此厥阴肝风，阳明热炽，未能布㾦，以泄邪，症势颇重。治以和阳熄风，辛泄上焦，以期厥止。", "11538": "（案14）沈。伏邪为疟变病，兼以风温上袭，咳嗽不畅，痰亦难咯，神识昏昏如寐，时有形惊栗神烦之苦，病延匝月，热邪内炽，肺胃津伤，阴气拖虚，以致耳聋，舌干，苔灰，口渴。脉象虚弦，无神。白㾦屡布，而未透达。寒热依然蒸灼太甚，阴气重伤，忽忽奄奄告变在迩，未可泛称无事也。拟承阴、救津、化邪，以冀挽回于万一。", "11539": "（案15）钱。始起三疟，疟止邪未尽泄，又感风温，触发内伏之余邪，遂有寒热似疟，不分界限。内蕴之湿，蒸变化热，热炽伤阴，液涸风动，肢搐。舌红光亮，口干渴饮。脉弦数，按之豁然而空，寐则呓语，此神不内守。小便欲解而茎缩，阴气消耗，泉源欲竭之象也。况布空壳，口生糜疳，一派阴尽阳升之征，恐其转剧濒危。勉拟扶正、救阴、撤热。", "11540": "（案16）顾。伏邪内蕴，感冬温触发，寒短热长，不分界限。头痛咳嗽，溲赤舌白，口腻，渴不多饮。脉浮弦数，湿郁气分未泄也，治以分泄。", "11541": "（案1）符。暑湿热兼感温邪，身热旬余，曾先衄血。气分无形之邪，已见逼动营阴，今则热邪乘虚陷入营分，发为紫斑。腑气五日不行。咳嗽不畅。舌红苔黑，口干不嗜汤饮。胸闷，神识昏蒙，沉沉欲寐。脉数。此邪灼心包，势将昏蔽，非轻候也。治从肺卫、心营、清解气阴之热。", "11542": "又：清解气营，斑点渐化，续布白㾦。腑通连次，热邪虽有暗泄之机，而蒸灼之余，胃液受劫，舌红苔黑而干，脉数。咳嗽不爽，时有呓语，神志沉倦。病情如旧，尚在险途。以气血两燔治法。", "11543": "又：斑点虽化尚未了了，白㾦已回。舌津亦润，微有黄苔，口渴，脉来数疾，胸闷，神识尚蒙，乃热邪挟痰上薰所致。咳嗽痰咯不易，肌肤燥灼，气营邪火仍未清泄，以致劫烁胃津阴液也，以承阴撤热。", "11544": "（案2）戈。温邪七日，神志或轻或浑，唇燥，齿血，目赤舌绛，苔黄口渴，脉濡数，便溏。遍体赤斑，此温邪由气入营，燎原之势，内逼膻中，势将昏闭，涸液之机已著。急宜清营中之热，以冀斑透神清。", "11545": "又：清解营分络热，斑点较透，其色带紫，神识似乎略清。舌绛苔黑，便溏。脉来外数内柔，而不鼓指，乃邪火劫烁阴津，不能御邪外出，而致内陷膻中。急急救阴泄热，以冀神清。", "11546": "（案3）王。温病八日，蓝、赤斑并布，目赤龈血，舌红苔黄，口渴，频频呃逆，大便溏泄，色赤而热。是阳明温热内逼营分之故。虽外得斑点，内得便泄，似乎表里热邪已得分泄。而脉来细数无神，最为可虑。阳病见阴脉，古称不治，涉险何疑？勉拟清解营热。", "11547": "（案4）戴。酒客中虚湿胜阳微之体。感受暴寒，致形寒身热，热不甚扬，呕吐苦水，显然饮积中宫，寒郁反从热化，逼其无根浮游之火，发为虚斑，色淡不绽。脉沉细迟滞，舌黑苔，干渴喜暖饮，胃寒客气上逆，呃忒频频，惟大便紫色，小便浑赤，阳明必有湿热内蒸，病甫半月，已涉险途。拟宗仲景法，以图侥幸。", "11548": "又：昨投仲景重镇法，呃忒减半，苔色已转为黄腻垢浊。斑点较繁，四肢仍冷。脉左细，不耐按，右部弦细。便溏，咳嗽不畅，此寒湿化热，蕴蒸无形之邪，逼虚阳无根之火上泛所致，元气津液业已两亏，病经十七日，尚在险中。", "11549": "（案5）许。温邪旬日，咳嗽、神烦、呓语、舌苔灰黄、渴不多饮、脉数、斑点、汗少，肺胃风温挟湿，内蒸阳明，气营交病。法以清解，佐以宣泄。", "11550": "（案6）夏。休息利后阴气内伤，又夹湿热，发斑色紫、舌尖干、口渴、不寐、呃忒，脉弦数而空。此真阴已伤，恐其劫津，正不敌邪，虚脱可虑。", "11551": "（案7）张。温邪十三日，斑疹仍然，咳嗽气急，大便泄泻，夜烦少寐，口渴舌红，脉软数，肺胃津液两虚，热炽阴空。法以泄热救阴，明朝两候，望其热解，若再迁延转虚，可虑。", "11552": "又：病交十五日，斑点未化，气促似喘，咳嗽，苔薄白，口渴，脉浮数。便泻腹痛，澼澼不爽，且有痰沫，里急后重，觉热。此阳明温邪乘阴之虚陷入厥、少两经，法当咸苦泄热、坚阴。", "11553": "又：前议咸苦、坚阴，下利略减。里急后重，肛热且痛。咳嗽气逆，苔白口渴，脉浮虚数，肺胃温邪，乘虚陷入阴经。湿热无形之邪，变作有形之滞，议从厥阴热利一条。", "11554": "（案8）何。暑湿热浑蒸阳明，分布三焦气分，由气入营，直逼膻中，神昏聩乱，目窜鼻衄，舌红苔灰黄，渴饮，脉象沉数。身半以上暑㾦四肢，蓝斑隐隐，紫斑已露。热邪化火，势如燎原，劫烁阴液，况又病中夺精，曾经泄泻，阴气大伤。当此燔灼之际，津存几何？焉能不涸？风生瘛疭，厥闭可危，急宜化毒、清营，以冀神清斑透。", "11555": "（案9）戴。身热不扬，胸闷、咳嗽、痰咸，脉迟细、尺微，舌白、渴不多饮、四肢逆冷、溲清。寒湿内郁营分，真阳自虚，逼其浮游无根之火，发为阴斑，色淡而微，治宜温经通阳。", "11556": "（案1）沈。湿招暑气，暑湿交蒸，无形黏腻之邪，与外风相搏。始则形寒身热，脘闷，咳嗽，邪凑于肺胃两经，渐次蔓延入三焦气分，上熏于肺，发为疹㾦，色不光泽，点不畅达。此热久正虚，不能使邪尽出所致。大便泄泻，是湿热之邪不从表里，而向下趋也；既泻而病不甚退，是邪亦欲出，而不尽出也。日暮热甚，阴气灼伤也。脉来浮数，按之细弱，正虽虚而邪亦渐退也。法当养阴和津，参以泄化，冀热缓思谷，庶免风波。", "11557": "（案2）孙。风温郁于内，秋燥遏于外，形寒身热，咽痛，遍体风疹，鼻衄便泄，少腹痛。病属阳邪，反见沉细涩之阴脉，于法为逆，况且邪从里泄，不经汗解，恐有猝变。", "11558": "（案3）周。风温挟湿十七日，先见白疹，续发红疹，透而渐回，反致神识模糊，呓语喃喃，昼轻夜重。咳嗽，痰鸣，舌白尖红，脉浮数。大便泄泻。风动肢牵。风温欲达不达，而致乘虚内陷，非轻候也。拟承阴泄邪，以冀转吉。", "11559": "（案4）吕。温邪旬余，疹点已回，神识不清，夜烦不寐，呓语，遗尿，肢搐，自觉心神不安。脉软数，尺部独弱。此温邪内炽伤阴，风阳煽烁，水不济火，心神浮越，心气不能下交于阴，乘虚内陷，有内闭外脱之象，议进和阳熄风。", "11560": "（案6）孙。暑湿风邪内蕴肺胃，咳嗽痰多，舌白口腻，脉沉弦数，白㾦式微，此邪郁气分，不能畅泄，反致淹缠，病经十八日不解，治当宣泄气分。", "11561": "（案7）盛。伏邪五日，热势暮甚，舌白溲赤，脉左虚数，右沉数，布白㾦，肺胃气分之邪，渐入阴分，正虚邪恋不化也。", "11562": "（案8）王。风温挟湿，郁伏肺胃，咳嗽身热，入暮为甚，咽梗音闪，溲赤脉浮数，白㾦不多，口干。病已五十日，肺胃津伤，邪不外达，以辛凉轻泄。", "11563": "（案9）张。湿热下移阳明，泄泻咳嗽，舌白腹痛，脉弦数，三焦湿热，白㾦不透，伏邪为病，最属淹缠。", "11564": "（案10）章。伏邪身热咳嗽，便泄，舌白，脉细数，邪郁三焦气分，白㾦未畅，治以分泄。", "11565": "（案1）张。饮积中央，客气上逆为哕。宗仲圣镇逆法病减，明呈中虚无疑。中气既虚，脾胃不运中阳，日渐消索，生气日羸。水谷之湿易聚，湿胜濡泄之后，倦怠嗜卧，神识模糊，脉来洪数，按之虚细，不饥不渴，渐渐蒸热。此蕴伏之湿与既衰之元不能两立。拟扶正化邪，以冀神清脉敛，与六和汤。", "11566": "又：脾胃为后天资生之本，脾胃健运，则水谷之精气可以养五脏之元神。戊己一虚，则健运失常，中气日馁，胃中无形之客气上逆，而为嗳噫，脾中无形之湿气下夺，而为泄泻，泻后神疲嗜卧，元气耗乏之明征也。昨进益气化邪，神清、泻减、呃稀、脉转沉细，正复邪退之机也，拟戊己法。", "11567": "（案2）顾。暑湿内伏，兼夹秽邪，形寒身热，舌白带灰，头疼气闷，便溏溲赤，脉沉数而滞，神识稍有不清，起坐无定。此秽湿内著也，最易昏闭，勿轻视之。", "11568": "（案3）金。淋雨湿衣，寒湿之邪束于肌表，与内蕴之暑湿相合，发为寒热，形懔自汗，头痛胸闷欲呕，舌白脉沉数。外寒而内热也，治以两顾。", "11569": "（案4）沈。暑湿内伏，触凉风而外发寒战鼓栗，先寒后热，头痛胸闷，呕吐泄泻，口渴，脉沉弦数。邪郁脾胃，游行中道，过膜原而寒热作矣。欲疟之机大著，法应提邪。", "11570": "又：提邪外达寒止，但热。吐泻亦除。舌仍白，脉尚弦滞不前。此暑邪虽从汗泄，湿邪亦得便泄。而究其蕴伏，尚恋未尽也。仿吴又可法。", "11571": "（案5）周。吸受暑湿、秽邪，徒然形寒，身热，胸闷，头痛，体膝酸疼，神烦，起卧不安，提手掷足。舌光苔白而微黄，不渴，无汗。脉象右数于左，是时邪浑淆中宫，当芳香宣窍，分泻三焦，以防内闭。", "11572": "（案6）沈。暑湿风热杂感溷淆中宫，分布三焦气分，上为呕吐，下为泄泻，且热阻中而胸闷，越外而身热、头疼。舌白腻，口渴不多饮，脉数。当以芳香宣泄，俾中宫浑处之邪，一时分解。", "11573": "又：身热吐泻之后，脾胃已伤，中阳运化之机不健，气道转输之枢亦钝。神疲脉迟涩。务宜节食。《经》曰：「食肉则复病，慎之。」", "11574": "（案7）刘。进芳香宣窍，少焉神清，旋即昏闭，神烦。自利赤水。四肢仍然逆冷。脉小数、左寸伏暑湿热邪内闭心包之象，就脉论证，危如朝露春冰。勉拟幽香宣窍法。", "11575": "（案8）顾。暑、风、湿三气杂感，身热自汗，口渴舌黄，体酸胸闷，脉数，泻止，小便不利，邪郁太阴、阳明。治从分法，宗河间法。", "11576": "又：暑风湿热转疟，寒从背起，舌白腻，口渴喜饮，脉来关数，小便赤痛，邪郁阳明，法宗仲景。", "11577": "（案9）张。暑风湿热杂感，病经十三日。神昏呓语，舌白苔垢、口渴，布白㾦，脉数，咳嗽不畅。病在肺胃气分，痰热内阻膻中。病已涉险，姑拟幽香宣窍，佐以辛苦寒，燥湿清热。", "11578": "（案11）顾。暑湿伏邪，身热五十日，形懔，胸闷，舌白，渴不多饮，脉数，白㾦屡发，未曾畅透，内蕴之湿未化，外感之风未泄，与暑湿浑蒸三焦气分，治当分泄。", "11579": "（案13）沈。去年六月淋雨后身热，渐至形消骨立，延及于今。少纳，四肢浮肿，舌白，脉细弦。气虚湿郁不化，恐难支撑，拟东垣清暑益气法。", "11580": "（案14）陈。复热，头痛，舌白，脉弦，劳力耕耘，即所谓劳复病也。", "11581": "（案15）王。伏邪为疟已止。早食荤腥，湿遏不化，神疲力乏，脉弦数，溲赤。即所谓食复病也。", "11582": "（案1）杨。霍乱吐泻转筋，四肢逆冷，音闪舌白，脉细微。暑湿浑淆中阳，邪已陷入三阴，证属危险，勉拟一方，以图侥幸。", "11583": "又：投转运清浊、通阳撤阴，霍乱、吐泻、转筋皆止。脉转弦细而数，身热。邪势已转入阳分，惟骤然呃忒，中阳因吐、利受戕也。法当和平。", "11584": "（案2）汤。霍乱吐泻，肢冷音哑，脉伏微有一线，暑湿寒邪直入三阴，重证也。", "11585": "又：霍乱呕吐已止，泻势未定，肢冷温而复清，脉细弦迟。神烦口渴，阳气未回，尚有变态。", "11586": "（案3）顾。霍乱，吐泻，四肢逆冷，脉伏，腹痛，麻木。邪入阴经也。", "11587": "又：服药后右关尺脉微续、细、弦，余部不起。吐泻稍止。神烦、口渴、舌白、腹痛、瘕攻，病情略有转机。再拟通阳，以冀春回寒谷。", "11588": "又：霍乱吐泻俱止，独呈左手不温。脉右三部软，左手微见一丝若无若有，应指不清。口渴不多饮，神烦。清浊浑淆之后，气阴不和，阳未全回也，拟再撤阴回阳。", "11589": "（案4）高。霍乱吐泻，肢冷，音闪，脉细，自汗。暑湿浑淆肠胃，疟势非轻。", "11590": "（案5）奚。转筋霍乱，胸闷，吐泻，腹痛，头痛，脉迟。寒湿入三阴，当以温之。", "11591": "又：霍乱之后寒邪未散，头晕足酸，脉象迟弦。法以疏补。", "11592": "（案6）王。转筋霍乱，吐泻，风来胜湿，湿胜濡泄，火窜筋挛，脉迟弦细。病邪未尽也，法以疏和分利。", "11593": "（案1）某。伏暑伏湿似疟之作，而无汗泄，其邪因此而不达，烦热痞闷，自食瓜梨，以致阳气被寒凉遏伏，肢冷呕逆，神昏，舌白色带青灰，泄泻，湿遏伏里，身热不扬，幸脉尚带数象。宜急通其阳气，泄其湿气，俾得神清热壮，方可无虑，不尔昏闭可危。", "11594": "又：昨进温通药，未见所长。神志依然不清，言语仍旧错乱。舌白厚且缩，脘中拒按，呕恶神烦。脉数而空，此因伏邪内踞，被西瓜之寒冷遏伏其阳，所以四肢逆冷，湿踞中宫，欲呕不能呕，欲泄不能泄，身热愈不显扬，寒凝湿阻痞结，中焦漫无出路，病已转剧转危，岂敢妄称无事。且拟大顺散、冷香饮子辈，撤阴通阳以冀挽救。", "11595": "又：真阳大虚，脐中动气筑筑，舌白积粉，脉弦，神志虽清，懒言、烦躁、自言，胸中懊𢙐，肾中之真阳虚而水气凌心，水火相激，水寒之气壅遏中宫，以致肢冷，屡进通阳，阳不肾复，奈何？然舍此别无他法，仍宗前意，以冀转轻。", "11596": "（案2）陈。寒湿鸣聚中阳，腹痛绕脐，脉迟弦，此因入水捕鱼，致寒湿之邪十年蕴蓄。病时发作，沉寒锢冷，非辛热之剂不能除，师仲景法。", "11597": "又：进辛热通阳，沉寒锢闭之邪不泄，少腹仍痛，脉迟。十年之病蒂固根深，非至刚气雄之剂，焉能斩关夺将，破其深伏之邪，反佐苦寒以向导，亦古人成法也。", "11598": "（案4）徐。阳微寒湿凝聚，曾先腹痛，呕吐清水，四肢逆冷，舌苔灰白，干恶气逆，六脉皆伏，二便五日不通，阳衰浊聚，病情极险。勉宗仲景通脉四逆辈，以冀脉复阳通，若脉得微续者生，暴撤者不治。", "11599": "又：昨进白通及通脉四逆法，脉渐微续，四肢未温，舌苔灰色已退，口干恶心，脐下痛，二便虽通，大便黑水，寒湿凝聚，痞塞不通，阳衰浊聚，脉虽复而虚弦兼数，右寸未起，病虽转机，一派阴霾之气，尚未消除，若非离照当空，阴霾何能退邂？仍守前法。", "11600": "（案5）沈。厥阴寒浊上潜清阳，胸痛嗳噫，卒然寒厥之后音哑，厥阴脉循喉咙，为浊邪所阻，音不显扬，脉迟弦，肢冷，少腹胀痛，议进辛泄温通。", "11601": "（案6）赵。脘胀呕恶，泛清水，脉细迟。寒邪内踞，阳明得热饮即泛者，寒热两途格不相入也。治以辛温，反佐苦寒为向导。", "11602": "（案8）李。暑湿寒挟秽邪内蕴中宫。头痛，胸腹痛。即时神迷，继以痉厥，连次口涌血沫，又吐黑水，神昏，舌缩，苔白，脉迟、浮、虚。邪入厥阴，挟阳明有形之痰上蒙神明，灵机闭塞，内风鼓动，病情危险极矣。拟芳香宣窍，以冀挽回。", "11603": "（案9）方。新婚欲后受寒，少腹作痛，舌白，呕吐酸水，脉迟弦，寒湿入厥阴络也。", "11604": "（案10）陆。夏日阴气在内，氧气在外，自饮梅酱冷水后，阳气为酸寒所收缩，腹痛脉细迟，病近半载，当以辛热温通。", "11605": "（案11）李。日薄西山，阳光衰歇，阳衰则寒浊凝聚少腹，入暮膨满，腑气不爽，脉弦尺细。病在下焦肝肾，以温通阳气为法。", "11606": "（案1）丁。孟夏作疟，非夏秋暑湿蕴伏之疟所可比，乃温疟也。延及于今，已经八月，寒热羁縻，营卫偏损。疟来自汗溱溱，胸闷，上热则下寒，下热则上寒，此阴阳两气不和，脉象沉细弦数。口腻。少寐。近有腹大坠满，食则䐜胀。久疟脾胃被戕，脾气不运，胃气不和，升降之机已失职矣！久病中伤，营卫俱偏，须得和协其阴阳，调和其中气，使寒热渐除，为第一要旨。议用仲景黄连汤两和营卫，使升者自升，降者自降，升降和而营卫亦和矣。", "11607": "（案2）周。湿遏膜原。膜原者，阳明之半表半里，三焦之门户。过此而为寒热，则成疟。舌白，不渴，背胀，头痛，溲赤，脉弦数，皆属风邪湿郁，宗吴又可法。", "11608": "（案3）龚。阴出之阳则寒，阳出之阴则热，阴阳相争寒热交作，脉弦数。溺赤，邪伏太阴之分。惟失血之体，方书中皆禁表散，所谓血家忌汗，汗之则痉，是也。阴虚之质，似宜养阴化邪，宗景岳何人饮。", "11609": "（案4）王。伏邪为疟，日重日轻。诊脉沉细微弱。眩晕，胃呆便溏，无汗，气阴两虚，营卫不和。正虚，无以运邪外达，久延恐有虚变。", "11610": "（案5）顾。三疟寒起四末，扰及中州，胸闷，便泄、腹膨，脉来弦数不和。疟作转双，俗名双三疟。此太阴伏湿郁而不达，深恐脾伤腹满，务须慎食为宜。法当提邪外出，若得转为间疟，则邪达矣。", "11611": "又：诊脉弦象，较前稍和，则知邪势稍达，而正气亦随之而虚，舌质微黄，疟来稍缓，口渴喜暖饮，乃湿伏太阴未化，留恋于中。欲其湿化，必得疏湿，欲其疟止，须得正旺，拟扶正达邪。", "11612": "（案6）沈。久疟未清，陡然泄泻，脉左沉细，右伏，如有如无，四肢逆冷，胸次痞闷，此阳气随泄，欲绝之象。如此重证，岂可跋涉就医？勉拟一方，望其侥幸。", "11613": "又：六脉沉微无力，似有若无，久病正乏，不能鼓动其血脉，当责之于虚，肢冷腹痛，疟势错乱，按正论脉，总呈邪退正虚，阳气不复之象。", "11614": "（案8）谭。三疟疟发，寒热虽微，热时神志模糊，此属暑湿郁伏，未能宣化外达，以致逼乱神明，便溏、溲赤，脉来细弦，正虚邪恋，湿阻中焦。法当扶正化邪，仍从暑湿门主治。", "11615": "（案9）张。询病情，昔年伏邪蕴蓄，发为三疟，因无汗泄，致邪不外达；表邪传里，与肠胃积滞浑结，而为下痢。痢时用药，涩止。表里之邪均无出路，挟痰气内蒸，遂为腹满，时肿时退，四肢面部皆然，形浮气逆。疟作依然寒热，热时神志似乎模糊，脉象滑实而坚，舌质微黄，大便或下痰沫，腹觉松动，此有形之滞得以下趋。论脉合证，似乎虚实互见。拟用助脾胃化痰湿，和营卫之品，使疟邪渐泄，胃气渐充，则运用之机得以转输敷布，而痰湿自化矣。", "11616": "（案10）吴。疟作之后不慎口腹，致气血痰滞交黏内结，疟母且痛且胀，脉弦动，此邪不清泄也。木邪贼脾，便溏、䐜胀。病属肝脾，法宜煎、丸并治。", "11617": "（案11）顾。久疟之下脾胃受伤，以致水谷精华不化，气血反与湿气相搏，化而为痰。痰多稠腻，舌厚且浊，脉弦滑，囊湿，畏寒。此属阳气衰微。法当崇土以制湿，运用坤阳，阳旺则湿不聚而痰自消矣。", "11618": "（案12）张。三疟，进扶正达邪后，渐次轻减。微有形懔，是邪渐清澈之机也。惟大腹膨满依然，午后胀甚，正脾阳不运时候也。间或起核坚硬，面浮足肿，盛衰无定。此久病气虚，内夹湿痰，痰邪随气流行所致。诊脉仍滑而实，滑主痰，又主气虚，虚中夹杂之象也。法当理气化痰，以煎剂益气和脾，以丸药涤痰、降气，庶有益乎？", "11619": "（案13）钟。三疟五月不愈，以致疟伤脾胃，内蕴之邪外溢于肌表，遂为一身浮肿，水气上凌犯肺，咳嗽，气化不宣而致。小便短赤，大便反溏。脉见沉数。舌白口干，里湿颇甚，逆趋三焦气分，随疟往来，转重转轻，全无定准。病属棘手，深虑增喘，且与分消方法。", "11620": "（案14）金。伏邪三疟无汗，邪不外达，日益错乱，不时寒热，营卫偏而邪踞不达，溲少，舌腻，脉弦迟。邪势尚盛，入冬不易宣达也。", "11621": "（案15）蔡。素有失血证，阴气已伤，又经三疟，三年休作无定，体虚邪恋不达。咳嗽、痰绿、涎沫，脉细，色㿠。中阳久困，以致生痰，宜先治中宫，脾为生痰之源，无痰不成疟也。", "11622": "（案16）金。三疟九年，正虚邪恋，脉象弦迟，以扶正化邪。", "11623": "（案17）右。伏邪为疟，营卫争胜，寒热休作不定，胸闷、头眩、心悸、带下、腰酸，引及环跳、𫏋维脉少扶持，阳陷入于阴，脉象弦数，客为内蕴，伏邪未尽，正阴拖虚。以何人饮，佐以提邪。", "11624": "（案19）姚。三疟半年，热轻寒重，阳衰。邪郁不达，脾伤腹满，疟邪与痰血浑聚，内结疟母。脉迟，以温药通阳逐邪。", "11625": "（案20）方。久疟无不伤阴，营虚湿郁，两足浮肿，兼挟肝气，阳气化风上逆，头眩耳鸣，鱼尾穴痛，脉小滑。病情虚中挟实，养阴必佐以理湿。", "11626": "（案21）徐。暑湿风邪，为疟间作，头疼、胸闷、呕恶、口苦、舌白、腹痛、滞下赤白，脉沉弦数。疟、痢虽属两途，其邪则一，痢作休息，蕴伏之邪在于肠胃间也，先理疟邪，痢亦可从表达而轻减。", "11627": "（案1）方。入暮身体灼热，头痛，胸闷，脉涩，阴虚，暑湿热内蒸阴分，阴气孤绝，阳气独发，而为瘅疟。仲景有论而不著方，近代喻嘉言，以甘寒泄化为治耳。宗其法以消息之。", "11628": "（案2）王。但热不寒，汗多脉数，瘅疟也。以泄卫透营。", "11629": "（案1）徐。寒热泄泻，泻后变痢，乃脾传肾为逆，延及两旬，依然腹痛，痢下五色，舌白不渴。病在太阴、阳明。暑湿无形之邪，酿成有形之滞下。胃不知肌。面浮色㿠，形神俱夺。正气既虚，无形之邪气遂迫既虚之肺气，发为虚，脉浮大虚㾦，按之豁然而空。内蕴之元气已衰，而外受之暑湿弥盛。《内经》云：肠澼身热，脉大者难治。拟扶正达邪，投之以觇进止。", "11630": "（案2）谭。下痢系湿热邪滞蓄积于肠胃之间，治法不离乎通涩，自用兜涩升提之法，邪滞未清，依然腹痛下痢。脉左沉细、右弦，恐有休息之累。", "11631": "（案3）何。久痢无不伤及脾肾，肾真之阳乏蒸腐之力，痢下如鱼脑，脉沉细弱。此脏寒阳虚所致，法当升举。", "11632": "（案4）赵。痢久伤阴，脾虚不运，䐜胀，滞下色赤、黏腻、腹痛，诊脉弦数。此邪不化而正气拖虚，湿热无形之邪逗留不清，恐致休息痢。", "11633": "（案5）邹。脾寒痰滞，郁阻阳气，食不运行，脘痛腹胀，便行带积黏腻，脉弦。此阳不通运，失其宣化也。", "11634": "（案6）徐。寒邪挟湿内蒸，少腹痛，小便不利，滞下色白，脉弦大，按之细软。邪滞不化也，从仲景温下之例。", "11635": "（案7）杨。寒湿滞下，色赤腹痛，舌白根厚，脉弦迟。厥阴气不疏泄，阳明湿滞寒邪，治以温通。", "11636": "（案8）王。身热，恶心，腹痛，滞下，澼澼不爽，脉象缓大，舌白口干。暑湿无形之邪酿成有形之滞下，法当通泄阳明。", "11637": "（案9）何。暑湿热壅滞阳明胃口，干恶拒纳，是胃气不下行也。所以口淡舌腻，滞下里急后重，脉左弦数，右细。初利邪势尚盛，治当通之。", "11638": "（案10）徐。暑湿酿成滞浊，窃据中宫，下行肠胃，以致身热头痛、胸闷、腹痛、便泄之下转而为利，黏腻，澥澥不爽，脉缓大而滞，病势初张，恐其增剧。", "11639": "（案11）庄。湿邪夹滞夹寒内蒸。滞下腹痛，澥澥不爽，舌白口腻，脉弦滞，溺赤。法以疏泄。", "11640": "（案12）顾。疟痢虽分两证，其邪则一，总由暑、湿、风蕴蒸中宫所致也。今病者寒热乍来乍止。滞下或利或粪。汗伤营阴，神疲力倦，寐则惊恐。胃气少纳，舌光液涸。脉左细弦兼弱，右关一部独见滑数，此中焦邪未清澈，下利虚坐努责，此利久伤营，正气之怯不待言矣。治以调胃和营。", "11641": "（案13）潘。休息利七年，腹痛在脐下，利色赤，澼澼不爽，脉迟，寒湿伏于营分，宜温下之，无谓久病正虚，便投补剂。", "11642": "（案14）姚。下利先红后白，营分转出气分。腹痛。自汗。脉弦。伏邪内蕴中宫，法以疏理。", "11643": "（案15）褚。先泄泻而利，脾传肾为逆，色赤，腹痛，澼澼不爽，脉沉数，舌黄少纳，风邪实热伤于营分也。", "11644": "（案17）张。暑湿寒邪浑蒸中宫，酿成滞下，色赤，腹痛。脉大而迟。舌白，干恶拒纳，脘闷，邪郁胃阳，壅遏气机，不能转运，恐成噤口，勿以鸦片升提，以致邪恋恶不泄，至属至属。", "11645": "（案18）章。去春便泄，直至秋间，变为滞下，腹不痛，延至于今，里急后重，痢不自禁。脉弦洪数。气分湿热风邪伤于肠胃，气陷不升，能食口淡。宗活人逆流挽舟法。", "11646": "（案21）幼。利下赤白，腹痛，口渴，脉虚数。小质重载，恐其不耐支持。", "11647": "（案22）徐。休息利起已十年，或作或止，近四年来终年滞下，间或泄泻腹鸣，瘕聚有形。脉沉细迟弦。寒湿蕴蓄中宫，凝滞肠胃，胃呆䐜胀，舌白溺赤。体虚邪实之象也。病来有年，非旦夕所能取效。", "11648": "又：内风痰阻，舌强肢麻，口眼㖞斜。脉两关滑而尺弱。溲多，筋酸。此系肝肾两虚，虚风煽络，遂致左手不仁，肝主筋，由乎血不养筋，《经》云：「营虚则不仁，卫虚则不用，营卫俱虚则不仁不用矣。」治法务在益肾之阴，水壮则木涵，而肝风自熄，风定痰消，诸症不攻而自罢。", "11649": "（案2）瞿。阳升极而不降，阴沉郁而不附。面色油亮，汗泄津津，中风复发，牙关紧闭。脉左寸细、关劲，右尺空。少阴之虚，水不涵木。阳气浮越，阴不涵阳，阳不根阴，阴阳散失乖离之象。诘朝一候，喘汗可危。用药聊尽人心，绝症除非天佑矣。", "11650": "（案5）沈。产后诸经之血无一不伤，营虚阳旺变化内风上冒，卒然厥中偏枯，手足软痿，便艰。脉弦缓，欲语舌头蹇涩，心神呆钝，内风鼓荡之余，气衰络热冲阳，亦少护持。近日天寒，畏风怕冷，是因产虚空窦多隙也，饮食寒暖宜格外慎之。", "11651": "（案6）吴。《内经》曰「内夺而厥则为瘖痱」。左手足偏废，缓纵不仁，口㖞头痛，脉数，肢麻，病得之少年精血之损也。心火妄动，相火随之，时常梦泄，由此精空，水不涵木，当此春升，阳气变化内风，卒然中厥，病来已非朝夕，岂旦晚所能卒愈。治法不外乎摄阴、潜阳、熄风、化痰，大忌风药升阳。", "11652": "（案7）金。体丰多湿多痰，痰随内风上扰，偏中于左，左臂无力，口歪舌强，脉来洪数。风火痰相煽中络，不易脱体。", "11653": "（案8）唐。烦劳阳气则张，精不养神，内风焮动，左面部牵引。脉缓、滑，中风之根也。", "11654": "（案9）陆。中虚湿胜，脾阳自衰，口角流涎不能约束，口甜便溏，湿困不运，脉实而大。中风之后不忌酒醴荤腥，致脾胃之气机呆钝，水谷精微不化，气血而蒸作甜痰。宜进薄味，以清养胃口，庶不湿胜气壅，猝然复中。", "11655": "（案10）胡。高年气血两亏，肝肾阴虚，阳化内风，右手麻木冷热不知，得热则指尖刺痛。脉形细弱，偏中之基也，急宜和养肝肾。", "11656": "（案3）金。内风挟痰，营血内痹，四肢麻木不仁，不知痛痒，脉数。治以化痰养血，血行风自减也，仿朱雀法。", "11657": "（案4）高。年刚舞象，质小体弱，阴虚木火素旺，阳易升动，鱼尾穴痛，厥阳化风旋动，脘痛，胃呆，脉弦数。治以平肝、熄风、和胃。", "11658": "（案6）卫。病后阴虚，曾先腰痛如折，阳气化风挟痰上旋，闭塞清窍，舌强不能言，痰声如锯，眩晕肢麻，脉细结弦，考《内经》云，三阴脉循喉咙挟舌，本内风挟痰闭塞虚窍也。", "11659": "（案7）吴。经行腹痛，头晕心嘈，饮以甘草汤其痛即止，显然营液内虚，肝风戕贼，肝为藏血之脏，脾为生化之源，凡经行之际，诸经之血交会于冲脉，冲脉隶胃，阳明所司，肝胃膜本相连。下血则血舍空虚，肝阳化风得以戕贼其土，肝性刚苦急。法当以甘缓之，故得甘而痛缓也。", "11660": "（案8）郁。肝血少藏，阳化，内风上旋，直升颠顶百会穴。痛风。阳木火上陵心阳，惊惕怔忡，彻夜不寐，火升足冷。肝木左升太过，右降不及，轰然上冒，自觉热焚。眩晕，肢麻筋掣，遍体收引。舌红心干咽燥，脉细。病情一派风阳煽动，营液皆被木火所劫之象，胃气不下行，便燥艰难。论脉合证，治法不外乎潜阳熄风，养津安神。但病已久延，阴气虚极，一时难复，须得安寐津回，方有转机。", "11661": "（案5）万。心风挟痰火上扰神明，错乱病发，必以烦扰，乃动则阳生，静则阴生，脉象滑数。治当潜阳涤痰镇摄神志", "11662": "又：痰火扰乱君心，病发则狂言詈骂，不避亲疏，寸关脉滑，此属心风挟肝火上逆也，仍当镇摄神志。", "11663": "（案6）吴。至疾莫如风火疾发，突如其来，卒然痉厥，不知所苦，涎痰上涌口沫，脉大。病属肝阳风火痰上旋，壅塞灵机，法宜潜阳熄风化痰。", "11664": "（案8）冯。肝营不足，木火凌心，上扰神明，语言舛错，眩晕耳鸣，少寐，烦恼，多梦纷纭，筋脉抽掣。病属营虚火郁，不生痫症即生外疡。", "11665": "（案9）朱。气从下逆，上至心胸，一团热气。心悸、项痛，即头重而眩，神志模糊，口涌血沫，四肢搐搦，便溺乃苏。此厥阳木火上凌心胞，直升巅顶，脉数牢实，病属痉厥，重治。", "11666": "又：风气通肝，肝属木，在卦为震，震为雷，雷气通心，象火有声。病发猝然，神志模糊，口涌血沫，心悸眩晕，则痉厥立至，溺而得醒，此肝之得以疏泄也。脉象转为弦数，厥阳风火挟心火上充，直升无制。咸苦直折有余之火。病魔已退三舍，乘其旗靡辙乱而逐之。", "11667": "（案1）陆。失物之后气郁不舒，木失条达，郁则生火，火生痰，痰生热，上凌心阳，扰乱神明，言语舛错，脉弦数，溲色赤。自觉或热或冷，经来落后，色淡。肝阴素虚，木郁也。从《内经》：木郁达之。", "11668": "（案2）朱。阅病原产后殇子悲哀，肝气逆郁，木失条畅，郁则生火，时有火升一团，郁结咽间，胸次不利，气逆上攻。火气下降，则二便通利，此木火无制，直上直下之明征也。是以汗泄乃松，郁火得以发越，脉见两关弦滑数，以咸苦直折其上腾之威。", "11669": "（案5）龚。木失条达，肝郁胃热。郁则生火，气火上逆犯肺，咳嗽痰中带血，血缕潮热，脉左弦右数，心悸眩晕。阴虚木火上充，恐成郁劳。", "11670": "（案6）叶。怒则气郁，郁则生火，木火横逆。胁胀、脘痞、噎塞、鼻燥，舌黄、口腻、脉弦数。阳明胃精不降，木郁不达，治在肝胃。", "11671": "（案1）张。丹溪曰：「食不得人，是有火也。」呕吐酸苦，噫气便艰，脉弦数，木火上冲犯胃，胃气不降，失循序之司，津液无以润下，老年关格大症，不易理也。", "11672": "（案3）某。膈症，食入脘中刺痛，肺失清肃，脉数。", "11673": "（案2）桑。病后动怒，抑郁，木失条畅，横逆中宫，瘕聚脘痛，得食则呕，苦酸痰涎，食物觉冷。脉迟延虚，翻胃半年。中阳挟饮也。", "11674": "又：翻胃，朝食暮吐，食则䐜胀，运用失常，脾不磨谷，火衰气郁，脉迟延，法以降逆。", "11675": "（案3）张。病起去夏霍乱之后，中气被邪混淆，胃虚气逆不降，干恶嗳噫，秋间变为翻胃，食入倾囊吐出，酸水痰涎，腹鸣便泄，此中有寒饮内积，故脉迟细弦劲也。", "11676": "（案4）某。性躁多火，木火易动，上冲犯胃，呕吐泛恶，脉细弦数。以辛苦宣泄，通降阳明翻胃。", "11677": "（案5）俞。酒客湿胜湿蒸生痰，积饮中阳，入暮呕泛痰涎，脉弦数，舌黄，若不节饮，后月必成翻胃。", "11678": "（案1）顾。营分伏热，血汗染衣，心悸气逆，脉象浮数，汗为心液，心阳热郁也。", "11679": "（案1）潘。久病元气拖乏，卒然音闪，痰声漉漉，汗出如雨，脉燥散乱，此脱象也。旦晚可危，勉拟以尽来意。", "11680": "又：卒然寒战，即汗泄如雨，痰声如锯，脉左三部绝无，右寸关惟一丝沉数。", "11681": "此肺气大虚，阳气脱离之象，危险两字不待言矣。勉拟复脉法以冀侥幸。", "11682": "（案2）周。肛漏久溃不敛，滋水日益下渗，漏卮不已，身中五液全亏，下焦气阴由此日耗，肾阴日不支持，收摄无权，水气上泛为痰，痰胶气逆喘急，动则更甚。精耗气怯，舌剥咽干，脉息虚弦兼涩。涩则阴伤，阴伤则精却，精空则气怯，气怯则神衰，精气神无一完固，而致神明孤露。合目欲眠，喃喃呓语，寐则神魂缥缈，一派阴阳离决脱象，显然草木之功难许见长。急宜收摄下焦，敛液安神，以慰望治，敷衍日期而已。", "11683": "（案1）李。营分伏热，鼻衄，中心宕漾，即时而出，八日不止。脉数，头汗，足冷。明是肝胃气火载血上溢，恐其狂出虚脱。", "11684": "（案2）张。鼻衄如注，少阴不足，阳明有余，脉象右数，舌白腻，温热内蒸，熏灼营分也。治以气营两顾。", "11685": "（案3）许。童真纯阳禀质阴亏，阴亏则内热，内热则营不足，热郁气分迫动营分，时常鼻衄，脉见细数，面黄形瘦，木火体形也。法以养阴。", "11686": "（案4）梁。鼻衄三载，时作时止，脉形细涩，阴分伤矣。", "11687": "（案4）吴。风郁少阳、阳明，牙关不利，耳聋，鼻渊，头胀偏痛，脉弦。辛凉宣泄。", "11688": "（案1）张。齿者骨之余，龈属阳明。牙宣五年，营阴大夺。虚火日旺，脉见寸关独数。宜治心胃与肾，宗景岳少阴不足，阳明有余例。", "11689": "（案2）徐。久病半载，湿热内盛，热伤营分，牙宣如注。脉象细数，自汗黏手，若不血止，恐难支持。", "11690": "（案4）陶。厥阴浮阳上扰，阳化内风旋动，头偏痛，牙宣，脉虚而细。营虚风旺不潜，以潜阳化风。", "11691": "（案5）王。阴虚阳逆，牙宣频来，脉细而迟。法以养阴。", "11692": "（案1）徐。阳明之脉起于鼻之交頞中，旁约太阳之脉，下循鼻外，上入齿中还出，挟口环唇。邪火相搏，蕴结不解而成牙漏，时或头胀脘痛。法当养血熄风，治风先治血，血行风自灭。", "11693": "（案2）秦。阳明湿热内蒸，齿匿蠹牙痛，脉弦，舌黄腻。以泄化法。", "11694": "又：风热郁于少阳、阳明，耳胀，流水，脉弦数。以微辛宣泄。", "11695": "（案1）某。心痛彻背，背痛彻心，仲景主以胸痹，如以锥针刺其心；《内经》主以脾心痛，病起背寒，寒邪挟饮，脉弦便溏。治在中焦。", "11696": "（案2）段。清阴结痹胸胁，痞胀彻背。诊脉弦数。嗳噫，矢气稍松，气机不司流利。宗仲景滑利通阳。", "11697": "（案3）姚。云门之上天气主之，咽间噎塞不利，胸中清阳结痹，上焦痰热郁于阳位，气机失司，少寐，脉滑。阳明不和，肺失清肃也。", "11698": "（案4）瞿。心痛彻背，寒气结痹阳位，阳郁不宣，脉迟细涩。以清利通阳，流行气机。", "11699": "（案5）某。胸痹胸中起痞。背痛，脉数滑。阳气结痹不宣也，以滑利通阳。", "11700": "（案6）倪。心痛彻背，背痛彻心，病发于春夏之交，阳气升动木旺之时，胸痞泛水。脉右关滑，阳微饮聚，结痹清阳。辛滑流利，开拨气机。", "11701": "（案1）张。木失条畅，肝气横逆犯胃，脘痛，呕吐酸苦，舌黄泛恶，脉细弦，少纳，神疲。中土受侮，先以泄肝和胃。", "11702": "（案2）朱。久疟致肝木阴亏阳旺。木旺则乘脾犯胃。脘痛，胁痛。呕吐少纳，脉左弦右虚，中伤何疑！舌质苔白口腻，面色萎黄，大便溏、结不定，皆属脾土失与转运不宣。法以和脾胃养肝阴。", "11703": "又：复诊脘胁痛止，纳谷稍增，惟脉象仍弦，此肝木有余，脾土阴弱。当宗景岳法，和养肝阴。", "11704": "（案3）杨。痃疟一载，疟后伤脾，脾伤肝木乘之。无形横扰之气，与内踞有形之痰，互相结聚成瘕，逆阻中脘而痛，延及半年。少纳形削，大便溏薄，已见脾受戕贼重伤其伤矣。但脉见弦长，遇指按之，软弱无神，外刚内柔，显然肝气有余，肝血不足，血不足无以培肝之气。气愈横扰，则脾愈困，脾困则水谷精华不运，而升降失其常度，脾胃困惫岂能支撑？拙见凭脉论证，和肝之气以养营，运脾之阳以化痰，未识能稍奏肤功云。", "11705": "（案4）周。诊得脉象左关双弦如芤，左关滑大，则知病在肝胃，肝不疏泄，胃有积痰，脘痛三月余未止。中伤木旺，理宜制木通胃。", "11706": "（案5）朱。肝木风阳戕胃，脘痛胁胀，呕吐绿水、蛔虫。舌干拒纳。脉细弦，此胃汁受戕，难投刚药，柔剂缓肝之急。", "11707": "（案6）倪。积饮中宫，肝木乘脾犯胃，脘痛吐酸水。脉弦劲不和，前法制木，病不减松。当进一筹以守之，安胃法。", "11708": "又：进许叔微辛苦酸泄，呕吐虽止，脘痛依然，脉象弦劲不和，状如新张弓弦，久病见此，全无冲和之象，究属不宜，仍守前法。", "11709": "（案7）徐。厥阴气不疏泄，寒浊内踞，瘕聚有形，攻逆胀痛。脉弦数，按之细，舌黄腻。此中阳湿郁不化，治当疏泄肝脾。", "11710": "（案9）顾。脘痛久延，九月不愈，肝木横逆犯中，胃气逆行不降，得食即吐，夜则寒热，胁痛，鸣响，胃虚，积饮痹络，脉数大，木火上冲于胃，久病正虚，拟仲圣法。", "11711": "（案10）朱。厥阴浊聚气痹，无形之气似乎有形，攻逆不已，上至胸背脘宇；下腹坚结，噫气，矢气。诊脉弦数，病情一派气滞，以疏理其气，佐以宣泄厥浊。", "11712": "（案12）王。肝脾寒邪结瘕，脘痛脉弦，病延三年，治在营分。", "11713": "（案13）戴。左胁下瘕癖，时常䐜胀，脉弦数，肝脏积聚，病经有年，难许除根。", "11714": "（案14）李。痰血气滞凝聚为瘕，结于左胁下，渐次消散，大便滞下，赤白黏腻，脉弦，乘其势而逐之，斩其根。", "11715": "（案15）顾。室女先天不足，营虚阴弱，脘痛收引，痛引两胁，腰楚如折。脉数，少纳，䐜胀，脾胃不和，肝木乘之，胸闷便薄。以泄肝和中，与生生子法。", "11716": "（案16）惠。肝胃不和，右胁痛，引及脘，瘕攻，脉弦虚数，病在气营，以通络泄肝和胃。", "11717": "（案17）温。肝逆犯胃，脘痛呕吐，倾囊而出，色赤，脉大而虚，胃津不足，阴亏木旺，以温中泄肝。", "11718": "（案18）朱。寒湿鸠聚中肠，少腹痛，脘痛，瘕攻，脉迟弦，肝木犯脾胃也。", "11719": "（案19）戴。素有肝逆，木乘风冷寒邪得以乘之，绕脐腹痛，便溏腹鸣，脉细弦。拟刘草窗法。", "11720": "（案20）夏。厥阴寒浊锢蔽脏络，腹痛，瘕攻绕脐，脉迟弦。治以温通。", "11721": "（案22）周。入暮阳衰痛甚，阳微之处即阴甚之处，饥不欲食，食则䐜胀，脉迟寒邪内踞，阳衰不运，病在肝脾，屡进温中，泄肝不应，痛仍如故，治肝不应，治脾亦良。", "11722": "（案23）张。真火衰微，不能腐谷，人入阳衰，胃气杳然，绕脐痹痛，尺脉细微，坎中一画，真阳不可任其汨没。急宜益火生土。", "11723": "（案1）张。肺消，饮水小便多，下白垽，脉数，舌红。阴亏，阳失其基，先与许叔微法。", "11724": "又：消渴小溲多，吐白沫，心中窒塞，脉弦而数，火邪上炎，求救于水。前法咸寒制火，病情未见所长。当进一筹以熄燎原。", "11725": "（案1）黄。厥浊无形之气结聚有形，大如鸡卵，卧则入腹，立则坠囊，睪丸胀痛，脉象迟弦。老年疝病，气血皆衰，除根不易也。", "11726": "（案2）朱。七疝皆属肝病，厥阴上逆，呕吐蛔虫，小腹胀痛，脉迟弦。以泄肝通胃，痛甚防厥。", "11727": "（案3）马。厥阴寒浊一遇寒劳，疝气即作，从少腹直攻肾囊，胀痛，痛引及脘，肝脉绕阴器环贯膈也。", "11728": "（案1）沈。汉曰缓风，唐曰脚气。两足浮肿，肿上及腹，四肢麻木，干恶胸闷，脉缓便燥，且挟风寒湿三气袭络，渐次化热，病来由渐，不易理者。", "11729": "又：脚气肿势渐消，少腹䐜胀，脉弦数，三阴寒湿渐化热矣，仍以通络。", "11730": "（案2）彭。三阴寒湿，脚气，麻木，胸闷。病经五年，屡发。邪已深入脉络，以搜剔其邪。", "11731": "（案4）陆。汉曰缓风，唐曰脚气。两膝麻木，肢痿不用，肌肤不仁，溲赤脉弦细。寒湿袭三阴脉络，不易即愈。", "11732": "（案5）李。寒湿下著左足跗及指经，酸痛麻木，脉迟细，此脚气也。", "11733": "（案6）陈。寒湿下著脚气，酸楚，小便浑浊，气急，脉弦细。三阴寒邪乘之，恐其脚气上入少腹，喘急。", "11734": "（案7）屈。流火脚气肿势渐退，又生火丹，红肿而痛，脉沉，溲赤。法以清泄。", "11735": "（案1）黎。风性善行数变，腿酸流走不定，上行环跳，下至腿䟰，脉细带弦。三阳邪袭脉络，三阴阴虚。法拟通络和阴，佐以搜风。", "11736": "（案2）郁。风寒湿三气杂至，合而为痹，四肢屈伸不利，皮搔肤痒、风块。脉细血虚，风来袭络，法以疏通和阴。", "11737": "（案3）陈。寒邪久袭脉络，锢蔽不泄，左肩髃酸痛而不举，脉细迟，病经一载，不易速愈，或延针师宣导，使气血流行，病自可复。", "11738": "（案4）吴。皮肤瘙痒，痒者为风，风湿袭于肌肉，瘙痒浮肿，流水，或发风块，或发隐疹。脉缓，不纳，老年气血两虚，虚风煽动，病来有年，难许无事。", "11739": "（案6）王。素体营虚，风寒湿邪入于脉络，久痹不宣，肩髃、腰背、尻骨酸楚，脉沉弦迟。入络之病，化邪必佐养营。", "11740": "（案7）卫。近耄之年营血自衰，血虚生风，风生热，皮肤燥痒，热灼肌干，脉细迟弦。法宜养血熄风。", "11741": "（案9）夏。风疹屡发，八年之久，发时寒热，腹鸣便泄，太阴、阳明、脾胃伏风，脉弦细迟。与消风散。", "11742": "（案2）沈。风寒湿三气流络，鹤膝风肿痛，伸屈不利，两臂筋脉痛楚，肝脾肾三阴邪庳脉络，舌白尖红，便溏，溲少。入络之病，岂易效哉。", "11743": "（案1）沈。肠痹，腑阳窒塞，二便不通，脘胀少纳干呕，少腹旁痛，脉弦细。此属血虚不能灌溉其腑阳也，大肠与肺相为表里，养血中佐以开肺，以肺主气化故也。", "11744": "（案1）吴。肛痔系湿热下注，大肠之火相激而成，痔坠、下血，湿热迫血下注也。脉见寸关弦象，按之细弱，心肝脾三脏已虚，故时有心宕嘈杂，目眩便溏，心不生血，肝不藏血，脾不统血，血液已亏，法当补益，但肛痔滋水颇多，湿热尚甚，先以清理湿邪，续商进补。", "11745": "（案1）唐。失血之体阴气自虚，咽燥舌红，肾阴已乏上承，得食䐜胀，脾阳滞运用之机，饮食少化，精微变而为痰，流入脉络，环跳部位结为痰核，惟恐久延成痈。拟养阴化痰，以冀消散。", "11746": "（案1）徐。阴虚木火炼液为痰，痰疬结颈，脉细以养阴化痰。", "11747": "（案2）方。肝逆挟痰，气痹胸膺，痰疬时痛，心嘈，脉滑。治以平肝化痰。", "11748": "（案1）朱。宿疾失血，复发胁痛，不得左眠。咳嗽痰臭脓血。诊脉左部弦大，溲赤。此内痈生于肝脏也，非轻恙。", "11749": "又：失血瘀凝下趋，黑粪自下，痰臭，脉浮大，肝络阴脏已伤，气不摄血，尚虑狂溢。", "11750": "（案1）邵。肺为娇脏，畏乎寒，更畏于热，热郁肺金，皮毛焦热，咳嗽痰臭，脉细数。缺盆下痛，病情见证，皆属肺热，治以甘寒，佐以辛苦。", "11751": "（案2）王。脾为生痰之源，肺为聚痰之器，久咳络伤，曾先咯血，肺虚失清肃之令，乏制木之权，木反侮金，气火浮肺，呛甚。于亥戌寅卯木火用事之时，脉来右寸带弦而数，法当清金制木。", "11752": "（案3）万。呛甚于寅卯木旺之时，痰不易咯，脉象右寸关弦，此木入金乡之候也。", "11753": "（案4）董。酒客湿胜湿蒸生痰，风邪又感乎上焦，咳嗽延绵两月，舌白口腻，溺赤便溏，湿邪内壅之征，但脉象弦数，呛独甚于黄昏，乃木入金乡，不易即愈。", "11754": "（案5）支。诊脉右部弦数，甚于左部，咳嗽年余，甚于晨昏，肝阴肝阳用事之时，乃木火上扣金鸣，金虚反受木侮，即《内经》所谓反侮其所不胜，木入金乡之证也。宜清金平木。", "11755": "又：右脉依然弦数，咳嗽，寅卯为甚，此木火上扣金鸣，金无制木之权，木反为金所侮，故一载不愈。欲制其木，必先清金；欲涵其木，必先壮水。姑与煎丸分治。", "11756": "（案6）张。肺肾两亏，咳嗽失血，甚于夜分木火升动之时，脉数虚弦，素有遗精之病，精遗则阴空，阴空则木失涵养，木火于是扣金。治宜益水之源，以养肝木。", "11757": "（案7）仲。黄昏气火浮与肺，咳呛突甚，脉弦数，肝木上犯肺金也。", "11758": "（案8）陆。风寒郁肺，偶食酸果，酸能收敛。咳嗽音闪，金实无声也，脉迟细而涩，宜启之。", "11759": "（案9）薛。邪感于风池、风府，脑后痛，咳嗽、便泄、脉迟弦。以泄风化湿消痰。", "11760": "（案10）周。肝胃郁热，木火乘之，干呛，眩晕，甚在昏暮，气火浮肺，脉数弦长。木扣金鸣，慎防络伤见血。", "11761": "（案11）陆。三年前秋凉风冷袭肺，咳嗽至今，晨起呕痰，痰黄咽痒。脉数，风邪久郁成热，热复与湿交蒸，炼液成痰，蕴蓄中焦，胸闷窒塞，久病邪郁，尚宜清泄。", "11762": "（案12）温。阳明旺于未午后，灼热脉数，溲黄，咳嗽，苔灰。肺胃湿郁热蒸不化，仍以清泄。", "11763": "（案13）金。上实下虚，咳嗽咽梗，腰痛如折，脉细，阴乏上承，肺气痹阻，少阴阴虚也。", "11764": "（案14）唐。肺脉弦数，咳呛甚于天明，气逆无痰，舌黄溲赤，木火上逆扣金，木入金乡之候。《经》曰，五脏六腑皆令人咳，非独肺也。", "11765": "（案15）李。久咳，肺肾阴亏，咳呛气逆，肾阴虚不能上交心阳，心神恍惚，语言呆钝，似乎健忘，脉细虚弦。治从肺心肾，盖五脏六腑皆能令人咳也。", "11766": "（案1）朱。气火上载，狂溢盈碗，吸短，咳呛，胸闷，溲赤，舌苔灰白，脉来数疾无绪，血脱气空，气不摄血，有汗脱之象。勉拟血脱益气，以冀血止。", "11767": "（案2）钱。肝胃气火载血上逆，狂溢，火升足冷，咳呛，咽痛，脉数。阴空，气逆，法以降逆，佐以益气，因气为血帅，失有形之血当培无形之气，以生血也。", "11768": "又：气火上载阳络，失血狂溢，溢则阴空，空则气逆，脘为之闷，咳呛咯痰白沫，脉来数疾，阴气大伤，阳气独冒，法当潜阳育阴。", "11769": "（案3）俞。诊脉两关弦劲不和，肝胃络伤，失血气火上逆，咳呛，胁痛。既经失血，肝营自虚，法当和养肝阴，佐以通络理气，气和则血自降而火自平矣。", "11770": "（案4）王。肝胃气火上载，血溢频频，额热足冷，咳嗽，脉数，溺赤。宗缪氏法治之。", "11771": "（案5）潘。询病原，吐泻后先见咳嗽，痰吐绿色，乃阳明湿热蕴蒸津液所化。咳必伤络，湿甚化热，无形之气迫其有形之血上泛狂溢，胸闷眩晕，脉沉数。上升之阳不降，下陷之阴已空，势必渐吐渐瘀，一时难止。法当先降气清营，气降营清其血必止。", "11772": "又：清营泄热血溢稍止，咳呛痰多，咽痒，气火上逆未平，脉细数。仍以降气并清营中之热。", "11773": "又：失血已止，血去阳升上冒，眩晕耳鸣，面赤足冷，少寝，脉数。此阴空阳越，最易血冒，况病者心常自忧病不能愈，但忧越甚则阳越升。务宜静养为要，静则阴生，而阳气亦能自守矣。至嘱至嘱。", "11774": "（案6）蒋。夏至阳气极甚，阴未来复，失血复发，痰中缕缕。眩晕，脉数，此系阳升所致。年近弱冠，务宜保真，孔子所谓血气未定，戒之在色也。", "11775": "（案7）夏。中虚气弱，气不摄血，痰血兼集，咳嗽气短，脉细弦迟。降气建中，药不应病。寒热头胀，失血已多，阳气上逆，再以养肝降气，以期血止。", "11776": "又：咳嗽痰秽，咯血已多。吸短，脉沉细紧。中寒，气不摄血，与金匮法。", "11777": "（案8）朱。气火载血上溢速行，震动阳络。咳嗽咽痒，舌黄气逆，脉弦。与缪氏法。", "11778": "（案9）李。屡次血发，气阴两虚，咳呛气逆，脉芤下虚，不纳。法以摄下。", "11779": "（案10）杜。失血后痰咯黄脓而臭，肺胃湿热熏蒸，脉数。法以清化。", "11780": "（案12）沈。失血后狂溢，额热舌白，脉芤。气载上逆，肝胃络热，恐其血冒。", "11781": "又：肝胃血泛，狂溢。脉缓而芤。咳呛，溲黄，气火未平，阳络乃伤。宜养肝阴，佐以降气。", "11782": "（案13）钱。失血止而复作，阳气上逆，头重足轻，咳嗽，脉弦数，溲赤，阳气不潜，防其狂溢。", "11783": "（案14）陆。咳嗽失血，月余未止，劳力即吐。脉形迟滑，中虚，气不摄血。治以益气降气，以气为血帅也。", "11784": "（案15）骆。气火载血上溢，失血鲜明，脉数而疾，血泛，阴虚，热郁。以清营降气，气降血自归经。", "11785": "（案16）朱。操劳血发阳动内升，诊脉数大，肝火载血上溢也。宜养阴平肝，使肝有藏血。", "11786": "（案18）庄。失血后咳嗽，脉数，肺胃郁热未清，阴气自虚，五心燔灼。以养营泄热。", "11787": "（案19）徐。冬至一阳萌动，失血复发，阴不主守，阳不潜藏，脉数疾。以潜阳育阴。", "11788": "（案20）叶。肝胃血泛，咯血屡发，阳络乃伤。咳呛痰多。诊脉弦动，素有便血，脾脏亦伤，阴络亦损。病经有年，阴阳二气已困。土不生金，金火相刑。宜培中土，所谓上下失血当治其中也。", "11789": "（案22）朱。轰然背热，血即泛出，足冷，督脉阳升上载血溢，黄昏咳呛，脉芤数疾，舌剥苔黄，溲赤。阴虚络热，气火上炎，慎防狂溢，治以潜阳。", "11790": "（案23）陈。素有便血，今又痰血，脉细弦。上下交病，当治其中。", "11791": "（案1）徐。曾经寒热白㾦，原属湿热熏蒸于肺，是时咳嗽，延及于今，久咳不已，肺不生水，水气不衡，肾气上冲，不能偃卧。痰咯颇艰，味咸。胸中窒塞，夜不安寐。便溏少纳。一派阴空气怯之象。肺、脾、肾三脏皆虚。肺主出而肾主纳，肾不纳气，元海无根。脉来疾而转指，全乏冲和之气，乃阴极阳亢之脉，太刚必折。按证论脉，不外乎导气归元，收摄填纳，气若不平，恐其喘汗而脱。", "11792": "（案2）俞。肋痛失血由于木火上载，血泛狂溢，血脱气空，肝阳化风旋动，头痛胸闷，少腹痛，皆是厥阴脉络所过之地。火气上逆扣金为咳，咽痒，脉弦，便溏，不但肝病，肺脾亦同病矣。面色无华，神气消索，少纳，火升阴虚而阳气上潜，按证论脉，安得无咎？谓之入损，谁曰不然？拟和养肝阴、并润肺和脾，以冀胃旺呛减。", "11793": "（案3）褚。积虚之阴不复，累及于阳，阳亦随之而虚。畏寒肢冷，肢者，阳气之本也。人身之阴阳枢纽不相失，乃可长生。一有所偏，百病即集，此自然之理也。迩有筋骨酸疼，手足屈伸不利，乃营虚不养筋脉，脉络机关不束，病属气血大虚。治当大补气血，与温以煦阳、柔以和阴法。", "11794": "又：质薄如花，寒暄不耐，体虚，易于感冒，一有所触，即病重如山。此由阳不外卫，营不内充，故面色枯槁，形容憔悴，舌白液干。脉细虚弱，四体百骸，仅存虚气。《经》云：卫虚则恶寒，营虚则发热；恶寒发热，营卫俱虚也。夫营卫者，阴阳之基，水火之本也，二气交虚，日就消烁。草木无情，岂能养身中真水火耶？姑议复脉汤救阳和阴，不过尽其治法而已。", "11795": "（案4）钱。失血后阴虚阳旺，肤热灼手，咳嗽侧眠，脉数疾，便溏。肺脾肾三脏皆虚，怯象大著。", "11796": "（案5）汪。失血后咽痒，咳呛痰多，是气火上烁，搏激肺金之液，与胃土之津皆化为痰。夜寐侧眠稍可，已见脏阴先亏，又复寒热，身中营卫亦偏，便溏溺赤，舌质微黄，脉数。阴气已伤，损途可虑。", "11797": "（案6）曹。失血之后，阴气大伤，则生肌热、形憔肉削，肌肤甲错，咳嗽便溏，溺赤少纳，脉数。肺、脾、肾、三焦俱病，劳瘵如此，其何以堪。", "11798": "（案7）顾。入幕肌肤灼热，夜来汗泄而解。脉细数，咳嗽痰多，气急少纳，便溏。肺脾肾三阴皆虚，虚劳大著。", "11799": "（案10）陈。呼出心与肺，吸入肾与肝，呼吸气粗，肺气亏而肾气虚也。水亏不能上交心阳，时有少寐，惊悸，胃少纳谷，脉数而疾，劳怯何疑。", "11800": "（案11）顾。肝胆相火直上直下，上则失血，下则遗泄，脉数，咳呛。肺肾阴虚，劳怯之根也。", "11801": "（案13）朱。失血后阴亏阳亢，咳呛，潮热，脉数疾。便溏，舌光咽干。肺脾肾三焦皆损。劳怯已成。冬至一阳生，恐其增重。", "11802": "（案14）蔡。阴虚火焰烁金，喉痹，咽干，音嘶，脉数，肌灼。精摇乎梦，龙雷不静，肺肾阴伤，劳怯难免。", "11803": "（案15）孙。失血之后肺肾暗虚，金不生水，水乏上承，阴气不立，少火悉成壮火，消烁阴津，口糜舌干咽痛，脉数，溲赤。况当春令，阳气极升，万花烂熳之时，身中阴气正涸。勉拟甘凉生津、咸寒益肾，冀壮水以制阳光也。", "11804": "（案16）陈。寒热延久，营卫气偏，卫疏阳微，易于客感。且有梦泄、盗汗，阳为之虚，阴为之弱，脉虚数，恐其因病入损。", "11805": "（案17）孟。温邪寒热又兼利下，阴气重伤，肛疡成溃。咳嗽多痰。脉来数疾，阴虚挟湿热，恐其见血成劳。", "11806": "（案19）蔡。露秋燥气上临郁肺，肺气失宣，遂为咳呛，呛甚络伤失血。右肩络痹，酸痛不举，脉沉数，舌黄腻，时或泛水，阳明不和，脾弱不运，液化痰涎上泛，病在肺胃，脉象阴虚，按证论脉，有入损之虑。", "11807": "（案20）龚。痧后咳嗽，肌肤如烙，脉数疾，便溏黏腻，温邪兼凉秋燥气蕴伏肺胃，延及一载。阴气为热气消烁，汗泄乎寐际。此炎蒸金不敌火，童子痧劳，理之不易。", "11808": "（案21）吴。阅病原起于风寒袭肺，咳呛，肺与大肠为表里，寒热之余，风邪下陷，泄泻、腹鸣且痛。寒热时作，久热阴伤，盗汗。胃气渐呆。脉来数疾，舌红尖刺。一损在肺，二损在脾，三损在肾，肺、脾、肾、三焦同病，因病成劳，证属棘手，既承跋涉远来，姑拟东垣法，升泄下陷风邪，以冀泄止，庶或少有把握。", "11809": "（案22）张。冬至一阳生动，阳气上逆，失血复发。呛逆侧眠为甚。潮热盗汗火升。脉虚数疾，嗌干，肺肾阴虚，有入损之虑。", "11810": "（案23）吴。肾虚气不收摄，动则气舞，咳逆，溲多，脉弦大。肝肾两亏，治以纳气归肾。", "11811": "（案1）郁。《经》曰：「一阴一阳结，谓之喉痹。」一阴者，少阴君火；一阳者，少阳相火也，君相二火纽结，上焦上熏。咽痛，红丝缕缕，日晡潮热，脉象左寸独弦，显然金水两虚，虚不制火。法当壮水之源，以制阳光。但病来一载，损怯之根已深矣。", "11812": "又：金水两虚，虚不制火，火炎金伤，发为喉痹，红肿嗌干，日晡潮热，少寐，脉沉细。此阴气久耗，元阳不潜，法必先滋其阴，壮其水，水旺乃可制火，火制则君相自安，水火交而成泰矣。", "11813": "（案2）胡。久咳肺肾阴虚，咽痛，由来三载，烦劳为甚，经事乍停乍止，脉滑而数。少阳相火上煽，喉痹已成，病入损途一门矣。", "11814": "（案3）周。一阴一阳结谓之喉痹，一阴少阴也，一阳少阳也，木火上逆，炎上冲肺，喉痹，红丝缕缕，肺失清肃，湿郁不化，内蒸生热，舌苔灰黄，脉细，溲赤。先以轻扬清上。", "11815": "（案1）林。金空则鸣，金实无声，金破亦无声，是失音有虚邪，实邪。病起卒然，决非虚证。咳嗽痰多，咽鸣喉痒，脉虚数。肺失清肃，阴乏上承，病情渐恐入怯。然上焦清肃失职，药宜轻清。宗钱仲阳法，佐以咽痛生疮例治之。", "11816": "（案2）吴。《灵枢经》曰：「寒气客于会厌，故卒然无音也。」诊脉迟而紧大，以清扬开肺法。", "11817": "（案3）陆。风寒郁肺，饮酸，酸能收敛，咳嗽失音，右寸脉迟细而涩。此金实无声也。", "11818": "（案1）黄。阴虚体质，感受风邪，曾先咽痛滋腐，继又伏邪为疟，疟虽止肌肤灼热，咳嗽，痰咯白沫，脉象软弦而数。肺胃两伤，阴气拖虚，渐延至怯。法以清肃上焦，以冀热止嗽缓为幸。", "11819": "（案2）夏。肺有宿饮，遇寒即发，咳逆气冲，痰中带血，脉弦不得卧，此肺肾为病。肺肾子母之脏，肺主出气，肾主纳气，气不收摄，由是而气冲也。治当清上，先治其标，次当培本。", "11820": "（案3）汪。脾为生痰之源，肺为聚痰之器，肾气上逆，痰亦随之而升，气升逆痰，味咸，脉细沉数，腹中觉胀，此肺脾肾为病，暂与泄降法。", "11821": "（案4）李。下虚上实，积饮，哮喘咳嗽，痰咯白沫，脉迟。寒饮蓄积所致。法当宗生生子。", "11822": "（案5）王。阳明积饮，肝木乘之。脘中痛，呕吐痰涎，三年频发。脉来迟滑，中虚。痰饮，肝胃不和也。", "11823": "（案6）任。中阳积饮，心悸脉弦，脘痛，漉漉有声。以刚药劫胃水法。", "11824": "（案7）沈。寒饮积中，漉漉有声，呕苦吐酸，舌白脉迟弦，气从少腹上升，病由肝胃，泄木通降为宜。", "11825": "（案8）杨。去秋吐血之后，咳呛，呕吐白沫，动则气舞，脉细沉数。积饮在肺，肺肾两虚，治痰在肺，治虚在肾。", "11826": "（案9）张。土败木戕，阳衰不振，致饮积中阳，漉漉有声，少纳䐜胀，饮食入胃，蒸变酸浊腐秽，下午为甚，日中而阳气隆尚可支持，日西而阳气衰阴邪用事，故病增剧。脉象迟弦，便溏，脾胃中焦一派阴霾浊聚，若非离照当空，刚药劫饮直捣坚冰之地，阴邪何能退避。", "11827": "又：刚药劫饮复阳，病减，脉弦已退，迟细仍然，此久病所致。少纳䐜胀，漉漉有声，仍在入暮阴气甚时，饮邪属阴，阴与阴合，故病增剧矣。通阳蠲饮，振复坤阳，是合病之法也。", "11828": "（案1）马。痰哮遇寒而发，遇热亦发，肺为娇脏，畏乎寒更畏乎热。痰鸣喘迫，脉象见数。法当苦以降之，辛以泄之。", "11829": "（案3）陈。寒风兼受，蕴伏肺底，哮喘五年，越发越勤，脉迟虚细。发则寒热，汗亦不解，喘亦渐除，显然内蕴之邪从表而泄，此邪之蕴伏何疑。宜先撤其风寒，然后培补，譬如逐贼，贼出可关门也。", "11830": "又：哮喘五年，发时寒热，此风寒之伏于肺底，不得宣达也。诊脉迟而弦劲，邪未撤而欲补之，不但无益，反致邪蕴。宜搜剔其邪，是治病之本也。", "11831": "（案1）顾。肾为胃关，关门不利，聚水而从其类也。诊脉迟弦，一身悉肿，便溏溲少，口干纳少，䐜胀，脾肾阳虚，湿困水气，横溢肌肉，慎防喘逆。", "11832": "（案2）万。脾虚不能行运，水谷之湿阻遏流行气机，湿蒸化热，氤氲伤脾。筋青脐突，溲少便溏，脉沉数。土虚不能敌木，木火上冲犯肺，干呛。脾为本，肝为标，治其脾，求本之法也。", "11833": "（案3）林。脾胃湿热蕴蒸发黄，遂致脾伤不运，腹大䐜胀，囊肿，小便涓滴，大便闭塞，脉象迟弦。水气流溢肌肉，一身悉肿，不易理者。议开太阳一法，分清湿热。", "11834": "（案4）吴。阅病原：昔年三疟，不忌荤腥，脾阳从此日困。饮食水谷之湿与痰血凝聚成瘀，结于腹左，遂成肿满。开泄放水三次，至今腹大依然，杳不思谷，脾胃生阳已败。脉象沉细无神。既承跋涉远来，勉拟以慰望治。", "11835": "（案5）杨。开太阳小便得利，益肾阳水气渐消。脉虚弦。前法既合，无庸更张。", "11836": "（案6）姜。暑湿热浑蒸中阳，脾不化湿，水气逆趋肌肉，自下肿上，囊大，脉数，舌红咽闷，咳嗽。湿热蔓延三焦气分，慎防厥逆。", "11837": "（案7）孔。暴腹胀大，皆属于热，脾湿内蕴，蕴蒸不化，腹胀溲赤，便艰，脉弦数。臌胀已成也。", "11838": "（案8）潘。脾阳湿困，肝木乘之。脉弦。单腹胀大，脐突，背平，青筋已起，理之不易。", "11839": "（案9）盛。肿胀久延，一身悉肿，小便不利，脉沉，水气泛溢，逆趋肌肉，气化不利。理之不易。", "11840": "（案10）赵。从下肿上，而甚于下，阴囊更甚。小便不利，大便艰涩，咳呛。水气不能下输膀胱，气化不宣。脉数，口渴。不易理者。", "11841": "（案11）周。从上肿下，囊下为甚，便溏溲少，脉弦数。此风水为病也，勿轻视之。", "11842": "（案12）陈。肿胀咳逆不得卧，气促，溺少，胸闷，腹膨，脉沉弦细。病由肺风脾湿逆走肉里，肿胀已成之候也。", "11843": "又：喘急稍平，不能右眠，肺气不降，小便稍利，大便溏薄，脉沉数，恶风，肿势面部依然，当实肝泄肺。", "11844": "（案13）朱。外疡未愈，又感风邪，与内蕴之湿相搏。足浮，囊大，身热，咳嗽，气逆，便溏，溲赤，脉数实。风袭于肺，湿伏于脾，为水肿病也。", "11845": "（案14）蒋。风水一身悉肿，咳嗽，恶风，胸闷，气急，脉数。病在肾本肺标，理之不易。", "11846": "（案15）唐。昔年失血，虽经调理而愈，去夏腹满气胀，左右腹结癖。左是疟母，右属疟气，脾积至今未得消散。近又腹胀而痛，曾下黑粪瘀血。脉弦细，系肝脾瘀凝，痰湿鸠聚互结。病已有年，根深蒂固，未能一击可破，恐有单腹血臌之虑。且进温通，以脾为阴脏，得阳乃运耳。", "11847": "又：进温通疏补，中脘突形满势似乎渐平，痛亦稍减，而䐜胀仍然。诊脉弦细。此脾湿日踞，阻塞中焦，流运之机越痞，升降不利，干运之阳不振。必得阳通浊泄，庶几痞气渐消。", "11848": "又：肝之气不疏泄，脾之气不健运，肝脾两郁而不行，由乎浊痹，则阳不通，流脘中结痞，䐜胀且痛。脉弦滞而软，便溏，此肝脾为病也。《内经》曰：「坚者削之。」其痞气已消，佳兆也。前法已合，仍宜守之。", "11849": "（案18）徐。腹满，背平，脐突，气急，囊肿，脉沉迟弦，便溏，溺赤。此脾阳不运，水湿无以运行，真阳火衰，病属肿胀不易理者。", "11850": "（案19）龚。三阴久疟伤肝，肝伤运行失常，中焦蕴伏之湿内渍不化，溢于肌肉，遂为浮肿，朝宽暮急，病在营分。大便或溏或泄，寒热或作或休，疟热之表邪虽经紊乱，内蕴之寒湿尚未外泄。舌白浊，喜热饮，脉细软滑。脾胃之阳湿渍而困，营血之阴随病而虚，如此病情大为棘手。", "11851": "（案20）何。无形湿热困中，中虚脾不健运，少纳，胀满，大便溏结不定，脉数心悸，中焦升降失常，有肿满之象，仿朱丹溪法。", "11852": "（案23）方。条畅肝脾，依然腹满，脉象弦长不和，木旺土衰无疑，每晨必便，便后腹觉松动，不但脾病，腑亦病矣。", "11853": "（案3）陈。湿热肠红腹痛，澼澼不爽，紫赤兼行，脉数，病经年余，饮食如常，非不足之症，乃湿热交逼，血渗下行也。", "11854": "（案5）陆。暑湿风浑蒸中焦，身热之下触发便血，腹鸣且痛，初色淡，后鲜红，脾虚、营血为湿所逼迫而下渗。脾阳呆钝，早食荤腥，致身热复作。脉弦口干舌白，法以养营化湿。", "11855": "（案6）张。脾不统血，肝不藏血。血液下渗，而为肠红，或紫或鲜，其色不一，脉弦。肝脾两伤。法以引血归经。", "11856": "（案7）钱。便血红紫不定，腹中鸣响且痛，脱肛，疝气，脉弦。治从肝脾。", "11857": "（案8）张。便血六年，营虚脾损，腹痛，血紫，舌光且红，脉虚数，少纳，溲赤。中焦湿郁，面肿足浮，近有寒热似疟，伏邪乘虚而发也。", "11858": "（案4）曹。无梦遗泄属肾虚，腰臂酸痛，脉象虚弦。治法不外乎固其精关。", "11859": "（案7）吴。心君一动相火随之而施泄，时或倾炉覆舟。肾阴即耗，阴火上炽铄金，为咳痰壅，肺气自虚，盗母气自益。土衰神疲，四肢乏力，便溏，木失水涵，厥阳变化内风上旋，头眩耳鸣。病本在肾，他脏皆末。今诊脉象，数大而疾，舌质碎红裂纹，一派阴火虚阳上逆。所幸胃气尚强，可以摄纳，所谓壮水之源以制阳光。", "11860": "又：先天不足，肾阳暗亏，气不收摄，小便淋滴，寐则遗尿，阴亏阳虚，膀胱不约。宜温补肾阳，兼升督脉。", "11861": "（案2）姚。先天禀赋质薄，内热遗尿，脉数，以养阴固摄。", "11862": "（案1）金。素体阴虚湿热，间有遗泄，深秋客感伏邪，兼受风温寒热，咳嗽布㾦，邪泄而解。上焦之温气虽泄，中焦之湿下流，遗泄转甚，阴精愈耗，阳火随之，以致精关不固，不交自泄，阳强不痿，病名强中。乃属阳明湿热，阳明之脉主润宗筋，是以精出不痿，或赤、或白、或浑、或精、或淋，脉象数疾，口燥，盗汗，足软，病情虚中夹实，阴精虽虚，内留之湿热未化，久病阴伤，不得不补，欲固其精，必先益气，盖有形之精必赖无形之气固之也。若论固下，非通不固。至于温涩，恐碍留邪。未识弋获否？", "11863": "（案1）某。少壮情念正萌，心君一动，相火随之。精浊茎痛，脉来细数。病情恐从露行蔓草而来。", "11864": "（案2）陈。君火一动，相火随之煽惑，梦泻后败精转浊，溺管痛楚，脉数。瘀浊阻窍，通利皆不获效，与虎杖散。", "11865": "（案6）高。湿热无形之邪，下注于阴，淋浊，梦泄，十载不愈，溺滴，茎管肿痛，脉数。此涩愈甚精愈虚矣。与生生子法。", "11866": "（案8）萧。淋浊复发，茎管中痛，腰酸脉弦，水液浑浊，此败精尚未清泄。法当宣通为主，无因虚而止涩。", "11867": "（案9）高。离火下吸阴精转为赤浊茎管，溺痛，脉沉弦数。君相火燔，治当复心肾之阴。", "11868": "（案10）汪。触（触）秽败精转浊，茎管痛，溺涩，脉弦。与通利方法驱秽。", "11869": "（案11）高。素有肝逆，肝之疏泄太过，遂有精淋。每便努挣，小溲淋滴，诊脉弦数。病在肝肾，久淋久浊皆属气陷，不但精关不固也。", "11870": "（案1）朱。巢元方有五淋之分，下白物如脂，小腹痛，乃属膏淋。脉细、腰痛、体酸，身中阴液消耗。阳气上冒，头疼且眩。议潜阳摄阴。", "11871": "又：小便先下，血瘀成块，继下白物如脂膏，此先血淋而后膏淋也。腹痛，脉数，肝肾阴亏，湿热未清也。", "11872": "（案2）萧。膏淋久延，精关不固，海底胀痛，乃精空气急以致如此。脉数，腰痛，溲多，阴气自虚，君相两火不靖，益阴清火为宜，佐以滑涩。盖欲固下非通不可也。", "11873": "（案4）某。湿火下注，淋滴带浊带血，茎中痛，脉滞。且以通利，慎防癃闭。", "11874": "（案5）右。血淋两月不愈，溺塞而赤，腰酸，脉弦，阴气已空。《经》曰：胞移热于膀胱则溺血。宗仲圣猪苓汤，从阴之化，以冀血止。", "11875": "（案7）某。胞移热于膀胱，则溺血精淋，茎管中痛，脉数，舌白。酒客湿热化火伤营，年逾古稀，营阴已亏，岂可渺视？", "11876": "（案1）陆。膀胱湿热内蒸肝经，相火煽烁，蒸变瘀腐化虫，小便混浊，溲出长虫六七条，形似蛔虫，脉数，舌白。当以清理湿热。", "11877": "又：火腑湿热下流膀胱，蒸变生虫，形如疳蚀，溲液混浊，脉象弦数。再以清湿分利。", "11878": "（案1）潘。冲为血海，经行则诸经之血交会于冲脉而下。经行骨节酸痛，趱前，色紫。此属营虚伏热，法当和营清热，佐以理气。", "11879": "（案4）徐。先起指麻，后觉筋脉掣痛。眩晕䐜胀，脉滑数，经事趱前。病属营分有热，肝风煽络，挟痰所致。", "11880": "（案5）陈。病起伏邪内发，适值经行，经水过多。肝少藏血，化风上旋，头晕且痛，气逆上升，厥逆遂作。厥后不语神呆。进以平肝熄风之品。言虽已开，而神志未慧，心中模糊，问其所苦，但嘻嘻而笑，此非邪陷心包，乃心阴虚而神机失职也。脉见外刚内柔，舌黄口渴，阴液亦乏上承，是湿热无形之气未化耳。拙见舍标治本，盖古人本有先补后泻，先泻后补之法，兹且仿而行之。", "11881": "（案8）李。经来一日即止，瘀凝未尽，少腹结瘕攻痛，呕吐酸水，胸闷，肝脉弦急。厥阴气不疏泄，病甚防厥。", "11882": "（案9）万。湿热伤脾，腹胀之后饮食虽旺，经事不行，脾脏为湿困，生化之源已衰，是以营气虚而经事不行也。脉数疾，阴气亏而热郁于里也，以清热养阴。", "11883": "（案10）潘。经事后期腹痛，紫黑成块，腰酸背胀，足软筋掣，脉小滑，营虚阴亏，内热，五心燔灼，肝脾血虚，以胶艾汤法。", "11884": "（案13）张。经阻七月，食则䐜胀，腹满足浮，睡则腹足皆瘪，脉弦数。舌白，气阴两虚，湿热中阻，以理气化湿和营。", "11885": "（案14）金。经来受寒，脉迟细，腹痛。", "11886": "（案15）吕。营虚气滞，经阻。脉涩而速，胃减，少腹痛，手足入暮烦热，阴气自虚，脾胃生阳不振，痰气流溢结于颊车。治以调气养阴。", "11887": "（案19）高。肝木气滞不行，气为血帅，气行则血行，气机失畅，遂致瘀凝肝络，左胁下结聚有形，时时作痛，腹亦痛。室女经阻一载未行。脉象左关弦滞，此肝留有凝瘀，气不宣泄也。近又恶心吐涎沫，厥阴寒浊上逆犯胃。治以泄肝化痰，疏和血气，俾得经行，不致诸证蜂起也。", "11888": "（案1）顾。淋带绵延一载，气阴久耗，八脉不司约制。腰臂、尻骨皆痛。脉来数疾，阴虚湿热蕴伏，病情久延，入怯门径。久淋。治法宜用清药。", "11889": "（案2）唐。八脉𫏋维少护，腰酸，带下，胫骨酸痛，脉虚弦。以固摄下焦。", "11890": "（案3）汪。带下有年，腰骨节酸痛。下焦、肝肾两虚，湿热留著。两足浮肿，朝退夕甚。近复小便频频，下虚。肝肾不司约制，八脉空虚，阴亏气弱。以收摄下焦。", "11891": "（案5）姚。经来腹痛，气滞，营涩，带下，脉涩数。经行寒热，气营不和也。", "11892": "（案6）褚。经事参差，来时色淡且少，营虚之明征也。带下，腰酸，妨纳，䐜胀。乃冲任不调，血虚气衰所致。冲脉隶乎阳明，先以中宫为治，盖脾胃为后天生化之源，营气所由出也。", "11893": "又：经来色淡，营虚何疑？䐜胀胃呆，腰酸带下。冲、任、督、带、奇经皆病。冲脉隶胃，胃为水谷之海，营与卫皆出其中，胃旺则气充，气旺则血长，宜仍注意于胃。", "11894": "（案8）钱。经事不调，常常趱前，腰酸，带下。咳嗽，痰中挟血。木火上扣金鸣，金受火刑，脉数阴虚，八脉冲带为病。著紧调治，免入损途。", "11895": "（案9）金。带脉不固，阴伤湿热内郁，带下腥秽，腰酸眩晕，心悸，脉数，肤热，胃呆。肝胃阴虚，仍以咸苦坚阴法。", "11896": "（案10）江。经行紫色已止，带下，少腹胀，胃呆，脉数疾。阴虚挟湿，带脉不固，以通补奇经。", "11897": "（案11）徐。肝肾阴虚，阴精为火所吸。赤带，腰酸，心悸，脉沉弦数。以养阴固摄下焦。", "11898": "（案12）钱。湿困伤脾，脾不统血，湿邪迫血下行，冲脉气不收摄。经淋两月有余，带下，心悸，眩晕，耳鸣，腹大，足浮，胃呆䐜胀。病属肝胃，不易疗治，且以引血归经，再商别法。", "11899": "又：经淋虽止，营阴过虚，浮阳上扰，头眩，耳鸣，心悸，带脉不固，带下频多。治宜养阴固摄下焦。", "11900": "（案13）潘。冲任不调，气滞血涩，经来带下腹痛，脉沉细涩。以调气营法。", "11901": "（案14）瞿。露秋崩冲，并非下血，所下黄水臭秽而腥，淋滴溺涩。经事仍行，趱前，腹痛，其色亦正。误作血崩，投以温补，温涩。黄水淋沥延至于今。少腹痛，溺淋，内热，脉数，胃呆。此肝胃湿热内蕴。鄙见，久崩久淋，宜清宜通，望其病缓淋通。", "11902": "（案16）徐。肝阳上逆，心宕，即时头痛，脉滑数，体酸腰痛，带下，动则气逆，肝肾两虚也。", "11903": "（案1）徐。三阴不足，心不生血，肝不藏血，脾不统血。诸经之血失守，冲脉不司约束，遂为经崩。崩后神色俱夺，头痛眩晕，心悸耳鸣，由营阴内亏，以致阳气逆升，加以腹胀膨满，食下䐜胀，足肿，便溏，是脾阳之不振也。脉象数疾，是阴气之已亏也。治宗《内经》，从阴引阳，从阳引阴，佐以转旋坤土，以冀肿退。", "11904": "（案2）沈。经停三月，徒然崩冲，瘀块如拳，下其五六枚，脉迟细涩，腹痛、自汗，面青。肝无藏血，慎防阳升厥逆。", "11905": "（案3）俞。营分伏热，经来骤崩，色紫瘀块杂下，头痛眩晕，耳鸣，腰痛，脉数，此肝胃气虚，冲任不调所致，师葛可久法。", "11906": "（案4）何。肥人多湿多痰，茹素中虚气馁，脾失守御统血之权，胃气亦随而衰弱。冲脉隶乎胃，因此不司约制。经崩直下，血脱气空，气随升逆。肝失营养，阳亦化风，挟冲气直升无制，遂为卒厥。耳鸣头眩，自汗，心宕，诸证在所必见。少腹痛，便泄，腰痛，不寐，此皆营虚气弱所致。治以固摄，益气和营，惟脾胃素虚，湿痰素盛，深恐土不制水，湿气下趋而为水肿耳。", "11907": "（案5）方。经停五月，积瘀崩冲，紫块杂下，脉沉细，冲任不调。以和营法。", "11908": "（案6）冯。年交花甲，经事崩冲，连行数次，血去过多，气亦随虚，神疲心宕，眩晕耳鸣，彻夜不寐，脉细虚弱。一派气阴两虚，三阴交亏气象。", "11909": "（案7）宋。经停月余，而崩冲淋漓不尽。腹痛。冲脉不司约束，冲脉隶乎阳明，阳明主束筋骨而利机关，营虚则不仁，卫虚则不用，不仁不用而诸节皆痛矣。", "11910": "（案10）顾。经崩后溺痛，小便淋滴，脉细沉数，近又经行紫色。肝经郁热，治以泄化。", "11911": "（案1）黄。重身努力负重，以致胎元受伤，少腹痛，脘痛，引及胁背。胎气下坠，身热头痛，脘闷，舌白，口干，脉来弦数而涩。此伏邪为病也，深虑邪迫胎元，致成小产。", "11912": "（案2）陆。屡屡小产，八脉无有不损，此次怀娠又忽腹痛，坠下，带多如崩。委中、环跳酸痛，八脉不司担任，小产之象也。急宜固胎。", "11913": "（案3）周。经阻三月，脉来动滑、停、匀，的是毓鳞之兆。其呕吐苦水、痰涎，心下悸。此饮停中脘，少阳木火相激，上逆使然。当与驱饮。", "11914": "（案4）雷。怀孕七月带脉不固，带下如崩，气怯，此奇经为病也，带若不止，偏产堪虞。法以养阴固摄。", "11915": "（案7）瞿。妊娠六月，时常腹痛，胎动，气滞不和，脉右大。以安胎理气为要。", "11916": "（案8）王。重身，滞下色白。脉迟弦，胸闷，纳少，恐其利下伤阴，以致偏产。", "11917": "（案1）俞。产后八脉交虚之际，适感寒邪遂致形寒、身热。又因早食荤腥，致脘中作痛而胀，积聚成块，得食更甚，乃气血大虚之时而与食滞瘀凝互结，阻于脾胃之络。治从《内经》，坚者削之。佐以和养营分，俾得积消为妙，不尔，恐成膨胀。", "11918": "（案2）高。产后三朝即有身热，头痛，恶露不下。得汗身热已减，脉象洪大，眩晕耳鸣，时有谵语，神不守舍，少腹胀，大便溏泄。大余行此胎产，脾湿致产后不愈，又复营阴大夺，带脉不固，腹痛带下。病情虚实互见，理之不易。", "11919": "（案3）凌。产后恶露不通，三朝即止，继后神昏狂乱，此属蓄血如狂病象，错认遇祟，实非祟也。乃瘀凝阻于肝脉，扰乱神明。时有心烦意乱之状。少腹结块，疼痛，痛连环跳。寒热，咳嗽，胸闷，亦由瘀阻肝经而致。脉弦数，法当通瘀，必得块消瘀下，方可无虞，否则恐有外疡之累。", "11920": "又：产后瘀阻，蓄血如狂，通瘀宣导之后，病减，块消，肿退。胃风又复，寒热火升，狂诟，不避亲疏。少腹仍痛。此属瘀凝未尽，流注肝经，故小便赤而大便闭，脉来弦带数也。", "11921": "又：卒然偏产后汗泄，瘀下如崩，去血过多，血晕不省人事，口噤风痉，脉亦散乱，频频昏厥，汗脱可危。", "11922": "又：血晕稍定，恶露，瘀块如崩，气逆上升，厥逆若痉，神志模糊，牙关不利，脉数尺弱。产后暴虚，风阳上冒，下虚，少收摄之权，深虑厥汗而脱，宗黑龙丹意。", "11923": "又：昨进镇摄之品，神清厥止，瘀下亦少。营阴大夺，风阳煽动逆升，头痛，眩晕，心悸，耳鸣，脉数，皆属虚象。摄下和营，与清魂散意。", "11924": "又：新产营血下夺，血去阳升，头痛，眩晕，身热，蒸灼，脉细数，按之濡。此属暴虚，法当再以镇纳空隙，使阳静阴闭。", "11925": "（案7）顾。风热上郁清空，耳窍流脓且胀，心宕，头眩，脉弦细。此属产后营虚也。", "11926": "（案9）陈。产后八朝全带恶露，三日即有寒热，五朝气从少腹上逆，且痛而厥，风痉咬牙，自汗淋漓，头晕耳鸣，心悸，脉洪数。病从惊恐而作，惊则气乱，而血郁于上，遂致痉厥，产后营虚，虚则肝气自动，与阳气相并，逆升使然。治当理气、降逆。因气为血帅也，须得厥止瘀通为吉。", "11927": "又：产后败血冲心，肝风上扰，痉厥之下神志昏愦，彻夜不寐，昨议交阴和阳，镇摄神志，病情似乎略减。欲寐不寐，热解，脉缓虚。此阳气欲交于阴矣，佳境也。", "11928": "又：神志稍清，询其病情，耳鸣心宕，眩晕，脉象左寸细弱，左关虚弦。显然产后营虚，肝风上冒，神不守舍。", "11929": "（案10）沈。产后营虚气弱白汗，产后病之一也；便难，二也；小便不利，是膀胱素有积热，与瘀相搏，水气相凝也。脉数大，身热，恶露色淡且少，营虚何疑。汗多口渴，阴弱不振，宜养营佐以通利，宗《金匮》法。", "11930": "（案11）范。产后营阴两虚，维𫏋少护，腰腹腿膝酸痛，形寒身热。治从八脉。", "11931": "（案13）许。胎前湿热内郁，难产六朝，内蕴之邪外发，身热，头疼，胸闷，舌灰黄白，口渴且腻，体疼腹痛，泄泻，脉数，阴脱，玉门不闭，恶露稀少，乳亦乍断。此产后气营两虚，湿邪内蕴，病情虚实皆见，用药殊多掣肘，且大虚之时，尚虑气逆骤厥也。", "11932": "又：产后玉门已闭，腹左旁痛。便泄，澼澼不爽，舌灰已化，脉弦，少纳。寒热之邪郁于肠胃，不得宣达，法当温通疏泄。", "11933": "（案14）陆。胎前下利，产后不愈，寒热腹痛，利下五色。形浮舌光，口碎拒纳，脉浮洪数，按之细涩。此系产后营虚大夺，外感之暑湿风邪因虚而不达，内蕴之气血精华随利而致虚，虚则外感之邪易侵，又复咳呛，形寒，病情越转越剧。证殊棘手。且拟调营卫，以冀热缓益气阴，望其利减。", "11934": "又：下利五色渐减，腹尚微痛，内蕴之积滞渐消，外感之暑风未泄，转为间疟。咳嗽，形浮，胸闷，脉浮数，按之细弱，此产后营虚而表邪里邪不得畅达。病延月外，真阴不免拖虚，非偏补偏泻所能疗治，拟以扶正逐邪。", "11935": "（案16）汪。曾先寒热，头痛，骨节烦痛，恶寒，咳嗽，渐次神昏，狂乱，致伤胎元。偏产之后，不省人事，牙关紧闭，目瞑，遗尿失便。按脉缓中带滞，舌白。论脉合证，初必受寒，寒邪内郁不化，胎气逆升，致产后瘀凝上扰，病情甚险。姑拟交加散参味，以图侥幸。", "11936": "（案17）陈。小产后恶露未尽，少腹痛瘀下。复感新风，身热，头胀，胸闷，脉数，营虚之际，邪势乘之，小心为要。", "11937": "（案18）沈。偏产后受寒，厥气不泄，少腹痛，攻逆不已，脉沉数。内有郁热，外束寒邪也，法当疏泄。", "11938": "（案20）沈。昔年产后早投补剂，营分素有伏热，热郁不泄，上冲，以致喉腐，蒂丁脱落，喉痛时发，口鼻如火，咯吐红色臭痰。脉象左三部洪数，三阴伏火不泄，久病之下蒂固根深，难许痊可，按法当清泄阴分之热。", "11939": "（案21）庄。产后足一朝恶露颇多。腹痛，耳鸣，脉细。去血过多，虚阳欲越。治以和营潜阳。", "11940": "（案22）王。产后两月，恶露淋漓，腹痛腰酸。八脉气血不能相摄也。", "11941": "（案23）张。怀孕七月，劳力勤织伤胎，卒然下血盈桶，胎损腹中，胞浆已破，胎已横逆，自汗神疲，耳鸣头晕脉细欲绝，干恶。证在临危，药难挽救，勉拟一方，不过尽人事以待天命而已。", "11942": "又：偏产逆生，产后头晕，耳鸣，心悸，目暗，自汗。营血大下，阳气上冒，气随血虚。脉数而涩，势恐血虚风生，致发痉厥，拟和阴潜阳益气。", "11943": "（案24）郑。血崩偏产，营阴大夺，产虚不复，八脉亏损，所致赤白带下，阴空阳逆上冒，耳鸣，眩晕，纳少，食则䐜胀，腹膨。冲脉隶胃，阳明既伤，宜调胃气。", "11944": "（案25）朱。产后正虚神疲，少纳，脉速涩，当以温中。", "11945": "（案26）顾。胎产感受伏邪，产后而发，寒热羁麋，头眩少纳，食则䐜胀。脉软数，脾阳不运，营卫不和也。", "11946": "（案28）吴。春间产后，五朝遂有寒热，休作不时，热时胸闷，腹痛，当脐痛则必利，利色白脓。脉数，舌白。此产后风冷克于太阴，营卫不和，卫疏汗泄，邪实正虚，理之不易。", "11947": "（案29）俞。漏胎之后，产后血虚。痉厥阴亏，阳无依附，变化内风上窜，神昏，口噤不语，即或能言，音低不爽，神呆，询其所苦，尚未明晰，言语不甚了了。晨则便溏，脉细而虚。此心脾营虚，神无主宰所致。", "11948": "（案30）金。产后十朝恶露颇多，腹痛，舌白腻，纳少，脉大。湿郁太阴，冲脉不摄也。", "11949": "（案31）张。产后风寒袭肺，背寒且痛，脉沉速细，晨起呛甚。邪郁肺底，恐难脱体。", "11950": "（案32）蔡。难产后阴器受伤，致腐，现虽已愈，而带下频频。寒热，腹痛，胸闷，便泄，少纳，脉沉弦数，久虚不复，易于外感。", "11951": "又：产后阴器受伤致腐之后，脐旁腹痛，四五日一发，发则如淋臭秽水下，即有寒热，此由冲、任、带脉皆伤，而𫏋维亦少护持耳。", "11952": "（案33）范。产后尿脬损伤，小便淋漓，纳少，脉细。下虚，膀胱已伤，理之不易。", "11953": "（案34）王。产后感受风温，郁于手太阴肺部，咳嗽，寒热将及一年，脉弦数。此即《难经》所谓「阳维为病苦寒热」是也。", "11954": "（案35）余。产后恶露淋漓，四月不止，腹痛，头眩，心悸，脉缓。营虚，冲任不司约束也。", "11955": "（案36）王。产后半日卒然风痉，厥逆十余次，后头肿呕逆，眩晕。新产暴虚，厥阳化风，上旋，冲逆犯胃，所幸恶露仍通，脉左涩。可以熄风潜阳，以冀厥止风定。", "11956": "（案38）张。胎前久病，气阴未复，产后又复便溏，日行数次，下多阴伤，阳无依附，浮越发热，自汗气逆，心悸宕漾，惊惕，舌红。脉如奔泉外涌十里，乃产后暴虚，虚阳上冒，阴不涵阳，脱象大著，急宜固摄，必得脉数渐退，方为佳境。", "11957": "（案39）范。询病情起于产褥，营虚，感受风邪，未经清彻而致外风引动，内风阳气鸱张，风阳旋扰不息，以致头痛，遇风为甚，腹痛休作，带下。此系肥人多湿多痰，流注于带脉使然。论证当以养营熄风，佐以固摄其下，况有怀麟三月，必得根固蒂坚，不致胎元有损为妙。", "11958": "（案1）陆。去冬产后下利、脓血，久利清浊混淆，以致阑门水谷不分，直走小肠，阴阳易位而出，变为交肠。病延十月，形瘦神夺，寒热，舌光，腰痛，脉弦数。脾肾阴虚，理之不易，昨拟开太阳，佐以堵截阳明一法，以冀分清清浊。", "11959": "葑门金姓，早立门首，卒遇恶风，口眼㖞邪，噤不能言。医用人参、桂、附诸品，此近日时医治风证不祧之方也。趣余视之，其形如尸，面赤气粗，目瞪脉大，处以祛风消痰清火之剂。其家许以重赀，留数日。余曰：我非行道之人，可货取也。固请，余曰：与其误药以死，莫若服此三剂，醒而能食，不服药可也。后月余，至余家拜谢。问之，果服三剂而起，竟不敢服他药。惟腿膝未健，手臂犹麻，为立膏方而全愈。此正《内经》所谓虚邪贼风也，以辛热刚燥治之固非，以补阴滋腻治之亦谬，治以辛凉，佐以甘温，《内经》有明训也。", "11960": "运使王公叙揆，自长芦罢官归里，每向余言，手足麻木而痰多。余谓公体本丰腴，又善饮啖，痰流经脉，宜樽节为妙。一日忽昏厥遗尿，口噤手拳，痰声如锯，皆属危证。医者进参、附、熟地等药，煎成未服。余诊其脉，洪大有力，面赤气粗，此乃痰火充实，诸窍皆闭，服参附立毙矣。以小续命汤去桂附，加生军一钱，为末，假称他药纳之，恐旁人之疑骇也。戚党莫不哗然，太夫人素信余，力主服余药。三剂而有声，五剂而能言，然后以消痰养血之药调之，一月后步履如初。", "11961": "张由巷刘松岑，素好饮，后结酒友数人，终年聚饮，余戒之不止。时年才四十，除夕向店沽酒，秤银手振，秤坠而身亦仆地，口噤不知人，急扶归。岁朝，遣人邀余，与以至宝丹数粒，嘱其勿服他药，恐医者知其酒客，又新纳宠，必用温补也。初五至其家，竟未服药，诊其脉弦滑洪大，半身不遂，口强流涎，乃湿痰注经传腑之证。余用豁痰驱湿之品调之，月余而起。一手一足，不能如旧，言语始终艰涩。初无子，病愈后，连举子女皆成立，至七十三岁而卒。谁谓中风之人不能永年耶？凡病在经络筋骨，此为形体之病，能延岁月，不能除根。若求全愈，过用重剂，必至伤生。富贵之人闻此等说，不但不信，且触其怒，于是谄谀之人，群进温补，无不死者，终无一人悔悟也。", "11962": "东山席以万，年六十余，患风痹，时医总投温补，幸不至如近日之重用参、附，病尚未剧。余诊之，脉洪而气旺，此元气强实之体，而痰火充盛耳。清火消痰以治标，养血顺气以治本。然经络之痰，无全愈之理，于寿命无伤，十年可延也。以平淡之方，随时增损，调养数载，年七十余始卒。此所谓人实证实，养正驱邪，以调和之，自可永年。重药伤正，速之死耳。", "11963": "叔子静，素无疾，一日，余集亲友小酌，叔亦在座，吃饭至第二碗仅半，头忽垂，箸亦落。同座问曰：醉耶？不应。又问：骨哽耶？亦不应。细视之，目闭而口流涎，群起扶之别座，则颈已歪，脉已绝，痰声起，不知人矣。亟取至宝丹灌之，始不受，再灌而咽下。少顷开目，问扶者曰：此何地也？因告之故。曰：我欲归。扶之坐舆内以归，处以驱风消痰安神之品，明日已能起，惟软弱无力耳。以后亦不复发。此总名卒中，亦有食厥，亦有痰厥，亦有气厥。病因不同，如药不预备，则一时气不能纳，经络闭塞，周时而死。如更以参、附等药助火助痰，则无一生者。及其死也，则以为病本不治，非温补之误，举世皆然也。", "11964": "湖州副总戎穆公廷弼，气体极壮，忽患牙紧不开，不能饮食，绝粒者五日矣。延余治之，晋接如常，惟呼饥耳。余启视其齿，上下止开一细缝，抚其两颊，皮坚如革，细审病情，莫解其故。因问曰：此为恶风所吹，公曾受恶风否？曰：无之。既而恍然曰：诚哉！二十年前曾随围口外，卧帐房中，夜半怪风大作，帐房拔去，卒死者三人，我其一也。灌以热水，二人生而一人死。我初醒，口不能言者二日，岂至今复发乎？余曰：然。乃戏曰：凡治皮之工，皮坚则消之。我今欲用药消公之颊皮也。乃以蜈蚣头、蝎子尾及朴硝、硼砂、冰、麝等药擦其内，又以大黄、牙皂、川乌、桂心等药涂其外，如有痰涎，则吐出。明晨余卧未起，公启户曰：真神仙也，早已食粥数碗矣。遂进以驱风养血膏而愈。盖邪之中人深，则伏于脏腑骨脉之中，精气旺，则不发。至血气既衰，或有所感触，虽数十年之久亦有复发者。不论内外之证尽然，亦所当知也。", "11965": "西塘倪福征，患时证，神昏脉数，不食不寝，医者谓其虚，投以六味等药。此方乃浙中医家，不论何病，必用之方也。遂粒米不得下咽，而烦热益甚，诸人束手。余诊之曰：热邪留于胃也。凡外感之邪，久必归阳明，邪重而有食，则结成燥矢，三承气主之；邪轻而无食，则凝为热痰，三泻心汤主之。乃以泻心汤加减，及消痰开胃之药，两剂而安。诸人以为神奇，不知此乃浅近之理，《伤寒论》具在，细读自明也。若更误治，则无生理矣。", "11966": "雄按：韩尧年年甫逾冠，体素丰而善饮，春间偶患血溢，广服六味等药。初夏患身热痞胀，医投泻心、陷胸等药，遂胀及少腹，且拒按，大便旁流，小溲不行，烦热益甚，汤饮不能下咽，谵语唇焦。改用承气、紫雪，亦如水投石。延余视之，黄苔满厚而不甚燥，脉滑数而按之虚软，不过湿热阻气，升降不调耳。以枳桔汤加白前、紫菀、射干、马兜铃、杏仁、厚朴、黄芩，用芦根汤煎。一剂谵语止，小溲行。二剂旁流止，胸渐舒。三剂可进稀糜。六剂胸腹皆舒，粥食渐加。改投清养法，又旬日得解燥矢而愈。诸人亦以为神奇，其实不过按证设法耳。", "11967": "郡中蒋氏子，患时证，身热不凉，神昏谵语，脉无伦次。余诊之曰：此游魂证也。虽服药必招其魂，因访招魂之法。有邻翁谓曰：我闻虔祷灶神，则能自言。父如其言，病者果言曰：我因看戏小台倒，几被压受惊，复往城隍庙中散步，魂落庙中，当以肩舆抬我归。如言往招。明日延余再诊，病者又言：我魂方至房门，为父亲冲散，今日魂卧被上，又为母亲叠被掉落，今不知所向矣。咆哮不已。余慰之曰：无忧也，我今还汝。因用安神镇魄之药，加猪心尖、辰砂，绛帛包裹，悬药罐中煎服。戒曰：服药得寝，勿惊醒之，熟寐即神合。果一剂而安，调理而愈，问之俱不知也。", "11968": "扬州吴运台夫人，患消证，昼夜食粥数十碗，气逆火炎，通夕不寐。余诊之，六脉细数不伦，神不清爽。余曰：此似祟脉，必有他故。其家未信，忽一日仆妇晨起入候，见床上一女盛妆危坐，以为夫人也，谛视则无有，因以告。夫人曰：此女常卧我床内，以此不能成寐，而烦渴欲饮耳。服余药未甚效。一夕夜将半，病者大呼曰：速请三舅爷来，切不可启门，启门则我魂必走出。三舅爷者，即其弟唐君悔生也。卧室辽隔，呼之不能闻，女仆私启门邀之，魂即随出，遍历厅堂廊庑，及平昔足未经行者，遇唐君趋至，魂坚执其辫，仍返房，见己身卧床上，唐君抚之，魂遂归附于身。问所寓目皆不爽，细考所见之女，乃运台聘室也，未成婚而卒，卒之时，嘱其父母，谓吴郎必显贵，我死须恳其血食我，而葬我于祖墓。运台服官后，未暇办，故为祟。运台谓余曰：君言有为祟者，考果验，真神人也。将何以慰之？余曰：鬼有所归，乃不为厉，公当迎柩厝墓，立位而祀之可也。运台依余言以行，然后服药有功，而病根永除矣。", "11969": "雍正十年，昆山瘟疫大行，因上年海啸，近海流民数万，皆死于昆，埋之城下。至夏暑蒸尸气，触之成病，死者数千人。汪翁天成亦染此症，身热神昏，闷乱烦躁，脉数无定。余以清凉芳烈，如鲜菖蒲、泽兰叶、薄荷、青蒿、芦根、茅根等药，兼用辟邪解毒丸散进之，渐知人事。因自述其昏晕时所历之境，虽言之凿凿，终虚妄不足载也。余始至昆时，惧应酬不令人知，会翁已愈，余将归矣。不妨施济，语出而求治者二十七家，检其所服，皆香燥升提之药，与证相反。余仍用前法疗之，归后有叶生为记姓氏，愈者二十四，死者止三人，又皆为他医所误者，因知死者皆枉。凡治病不可不知运气之转移，去岁因水湿得病，湿甚之极，必兼燥化，《内经》言之甚明，况因证用药，变化随机，岂可执定往年所治祛风逐湿之方，而以治瘟邪燥火之证耶。", "11970": "同学赵子云，居太湖之滨，患暑痢甚危，留治三日而愈。时值亢旱，人忙而舟亦绝少，余欲归不能。惟邻家有一舟，适有病人气方绝，欲往震泽买棺，乞借一日不许。有一老妪指余曰：此即治赵某病愈之人也。今此妇少年恋生甚，故气不即断，盍求一诊。余许之，脉绝而心尚温，皮色未变，此暑邪闭塞诸窍，未即死也。为处清暑通气方，病家以情不能却，借舟以归。越数日，子云之子来，询之，一剂而有声，二剂能转侧，三剂起矣。", "11971": "芦墟迮耕石，暑热坏证，脉微欲绝，遗尿谵语，寻衣摸床，此阳越之证，将大汗出而脱。急以参附加童便饮之，少苏而未识人也。余以事往郡，戒其家曰：如醒而能言，则来载我。越三日来请，亟往。果生矣。医者谓前药已效，仍用前方煎成未饮。余至，曰：阳已回，火复炽，阴欲竭矣。附子入咽即危，命以西瓜啖之，病者大喜，连日啖数枚，更饮以清暑养胃而愈。后来谢述昏迷所见，有一黑人立其前欲啖之，即寒冷入骨，一小儿以扇驱之，曰：汝不怕霹雳耶？黑人曰：熬尔三霹雳，奈我何？小儿曰：再加十个西瓜何如？黑人惶恐而退。余曰：附子古名霹雳散，果服三剂，非西瓜则伏暑何由退，其言皆有证据，亦奇事也。", "11972": "毛履和之子介堂，暑病热极，大汗不止，脉微肢冷，面赤气短，医者仍作热证治。余曰：此即刻亡阳矣，急进参附以回其阳。其祖有难色。余曰：辱在相好，故不忍坐视，亦岂有不自信而尝试之理，死则愿甘偿命。乃勉饮之。一剂而汗止，身温得寐，更易以方，不十日而起。同时东山许心一之孙伦五，病形无异，余亦以参附进，举室皆疑骇，其外舅席际飞笃信余，力主用之，亦一剂而复。但此证乃热病所变，因热甚汗出而阳亡，苟非脉微足冷，汗出舌润，则仍是热证，误用即死，死者甚多，伤心惨目。此等方非有实见，不可试也。", "11973": "洞庭后山席姓者，暑邪内结，厥逆如尸，惟身未冷，脉尚微存，所谓尸厥也。余谓其父曰：邪气充塞，逼魂于外，通其诸窍，魂自返耳。先以紫金锭磨服，后用西瓜、芦根、萝卜、甘蔗打汁，时时灌之，一日两夜，纳二大碗而渐苏。问之，则曰：我坐新庙前大石上三日，见某家老妪，某家童子，忽闻香气扑鼻，渐知身在室中，有一人卧床上，我与之相并，乃能开目视物矣。新庙者，前山往后山必由之路，果有大石，询两家老妪、童子俱实有其事。此类甚多，不能尽述，其理固然，非好言怪也。", "11974": "阊门龚孝维，患热病，忽手足拘挛，呻吟不断，瞀乱昏迷，延余诊视，脉微而躁，肤冷汗出，阳将脱矣。急处以参附方。亲戚满座，谓大暑之时，热病方剧，力屏不用。其兄素信余，违众服之，身稍安。明日更进一剂，渐苏能言，余乃处以消暑养阴之方而愈。", "11975": "洞庭姜锡常长郎佩芳，体素弱而患久疟，时余应山前叶氏之招，便道往唔，佩芳出，诊色夭脉微，而动易出汗。余骇曰：汝今夕当大汗出而亡阳矣，急进参附，或可挽回。其父子犹未全信，姑以西洋参三钱，偕附子饮之，仍回叶宅。夜二鼓叩门声甚急，启门，而锡常以肩舆来迎，至则汗出如膏，两目直视，气有出无入，犹赖服过参附，阳未遽脱，适余偶带人参钱许，同附子、童便灌入，天明而汗止阳回，始知人事。然犹闻声即晕，倦卧不能起者两月，而后起坐。上工治未病，此之谓也。如此危急之证，不但误治必死，即治之稍迟，亦不及挽回。养生者，医理不可不知也。", "11976": "崇明施姓，迁居郡之盘门，其子患暑毒血痢，昼夜百余行，痛苦欲绝。嘉定张雨亭，其姻戚也，力恳余诊之。余曰：此热毒蕴结。治之以黄连、阿胶等药，一服而去十之七八矣。明日再往，神清气爽，面有喜色。余有事归家，约隔日重来。归后遇风潮，连日行舟断绝，三日后乃得往诊。病者怒目视余，问以安否？厉声而对曰：用得好药，病益重矣。余心疑之，问其父，曾服他人药否？隐而不言。余甚疑之，辞出。有二医者入门，因托雨亭访其故，其父因余不至，延郡中名医，仍进以人参、干姜等药。绐病者曰：视汝脉者此地名医，而药则用徐先生方也。及服而痛愈剧，痢益增，故恨余入骨耳，岂不冤哉！又闻服药之后，口干如出火，欲啖西瓜。医者云：痢疾吃西瓜必死。欲求凉水，尤禁不与，因绐其童取井水嗽口，夺盆中水饮其半，号呼两日而死。近日治暑痢者，皆用《伤寒论》中治阴寒入脏之寒痢法，以理中汤加减，无不腐脏惨死，甚至有七窍流血者，而医家病家视为一定治法，死者接踵，全不知悔，最可哀也。", "11977": "嘉善许阁学竹君夫人抱疾，医过用散剂以虚其表，继用补剂以固其邪，风入营中，畏风如矢，闭户深藏者数月，与天光不相接，见微风则发寒热而晕，延余视。余至卧室，见窗槅皆重布遮蔽，又张帷于床前，暖帐之外，周以擅单。诊其脉微软无阳。余曰：先为药误而避风太过，阳气不接，卫气不闭，非照以阳光不可，且晒日中，药乃效。阁学谓见日必有风，奈何？曰：姑去其瓦，令日光下射晒之何如？如法行之，三日而能启窗户，十日可见风，诸病渐愈。明年阁学挈眷赴都，舟停河下，邀余定常服方。是日大风，临水窗候脉，余甚畏风，而夫人不觉也。盖卫气固，则反乐于见风，此自然而然，不可勉强也。", "11978": "雄按：今秋藩库吏孙位申，积劳善怒，陡然自汗凛寒，腕疼咳逆，呕吐苦水，延余诊之，脉弦软而滑，形瘦面黧，苔黄不渴，溲赤便难，以二陈去甘草，加沙参、竹茹、枇杷叶、竹叶、黄连、蒌仁为剂。渠云阳痿已匝月矣，恐不可服此凉药。余曰：此阳气上升，为痰所阻，而不能下降耳。一服逆平痛定，呕罢汗止，即能安谷。原方加人参，旬日阳事即通，诸恙若失。", "11979": "雄按：今夏刘午亭，年六十三岁，久患痰喘自汗，群医皆以为虚，补剂备施，竟无效。徐月岩嘱其浼余视之，汗如雨下，扇不停挥，睛凸囟高，面浮颈大，胸前痞塞，脉滑而长，妻女哀求，虑其暴脱。余曰：将塞死矣，何脱之云？与导痰汤加旋覆、海石、泽泻、白前，一饮而减，七日后囟门始平，匝月而愈。继有顾某年五十六岁，肥白多痰，因啖莲子匝月，渐觉不饥，喘逆自汗无眠，以为虚也。屡补之后，气逆欲死，速余视之，苔黄溲赤，脉滑不调，以清肺涤痰治之而愈，旋以茯苓饮善其后。", "11980": "苏州沈母，患寒热痰喘，浼其婿毛君延余诊视。先有一名医在座，执笔沉吟曰：大汗不止，阳将亡矣。奈何？非参、附、熟地、干姜不可。书方而去。余至不与通姓名，俟其去乃入，诊脉洪大，手足不冷，喘汗淋漓。余顾毛君曰：急买浮麦半合，大枣七枚，煮汤饮之可也。如法服而汗顿止，乃为立消痰降火之方二剂而安。盖亡阳亡阴，相似而实不同，一则脉微，汗冷如膏，手足厥逆而舌润。一则脉洪，汗热不黏，手足温和而舌干。但亡阴不止，阳从汗出，元气散脱，即为亡阳。然当亡阴之时，阳气方炽，不可即用阳药，宜收敛其阳气，不可不知也。亡阴之药宜凉，亡阳之药宜热，一或相反，无不立毙。标本先后之间，辨在毫发，乃举世更无知者，故动辄相反也。", "11981": "雄按：吴馥斋令姐体属阴亏，归沈氏后，余久不诊，上年闻其久嗽，服大剂滋补而能食肌充，以为愈矣。今夏延诊云：嗽犹不愈。及往视，面浮色赤，脉滑不调，舌绛而干，非肉不饱。曰：此痰火为患也。不可以音嘶胁痛，遂疑为损怯之未传。予清肺化痰药为丸噙化，使其廓清上膈，果胶痰渐吐，各恙乃安。其形复瘦，始予养阴善后。病者云：前进补时，体颇渐丰，而腰间疼胀，略一抚摩，嗽即不已，自疑为痰。而医者谓为极虚所致，补益加峻，酿为遍体之痰也。", "11982": "雄按：痰喘碍眠，亦有不兼虚者。黄者华年逾五旬，自去冬因劳患喘，迄今春两旬不能卧，顾某作下喘治，病益甚。又旬日，迓余视之，脉弦滑，苔满布，舌边绛，乃冬温薄肺，失于清解耳。予轻清肃化药治之而痊。至参不入煎，欲其下达，与丸药噙化，欲其上恋，皆有妙义，用药者勿以一煎方为了事也。又有虚不在阴分者，余治方啸山今秋患痰喘汗多，医进清降药数剂，遂便溏肢冷，不食碍眠，气逆脘疼，面红汗冷。余诊之，脉弦软无神，苔白不渴，乃寒痰上实，肾阳下虚也。以真武汤去生姜，加干姜、五味、人参、厚朴、杏仁，一剂知，二剂已。又治顾某体肥白，脉沉弱，痰喘易汗，不渴痰多，啜粥即呕，以六君去甘草，加厚朴、杏仁、姜汁、川连，盖中虚痰滞也，投七日果痊。", "11983": "雄按：今夏江阴沙沛生鹾尹，患胸下痞闷，腹中聚块，卧则膊间有气下行至指，而惕然惊寤。余谓气郁饮停，治以通降。适渠将赴都，自虑体弱，有医者迎合其意，投以大剂温补，初若相安，旬日后神呆不语，目眩不饥，便闭不眠，寒热时作，复延余诊。按其心下，则濯濯有声，环脐左右，块已累累，溺赤苔黄，脉弦而急，幸其家深信有年，旁无掣肘。凡通气涤饮清络舒肝之剂，调理三月，各恙皆瘳。", "11984": "雄按：吴雨峰大令，年七十一岁，今秋患感发热，而兼左胁偏痛，舌色干紫无苔，稍呷汤饮，小溲即行，不食不便，脉洪且数。余知其平素津虚脾约，气滞痰凝，连予轻肃宣濡之剂，热渐缓，胁渐舒，而舌色不润，仍不喜饮，溲赤便闭，呃忒频来，举家皇皇。余曰：无恐也，便行即止矣。逾二日，连得畅解，脉静身凉，舌色有津，呃仍不减，人皆谓高年病后之虚呃，议用镇补。余曰：此气为痰阻，升降失调，得食不舒，平时无嚏，是其征也。授以枳桔汤加蒌、薤、菖、茹、橘、半、柴胡，果一剂知，二剂已。", "11985": "苏州黄四房女，年十二，患腹痛，愈医愈甚。余偶至其家，昏厥一夕方苏，舌俱咬破，流血盈口，唇白而目犹直视，脉参错无常。余曰：此虫痛也。贯心则死，非煎药所能愈，合化虫丸与之，痛稍缓，忽复更痛，吐出虫二十余条，长者径尺，紫色，余长短不齐，淡红色，亦有白者，自此而大痛不复作，小痛未除，盖其窠未去也。复以杀虫之药，兼安胃补脾之方调之，而虫根遂绝。盖此证甚多，医者既不能知，惟认为寒与食，即以为虫，又无杀虫之方，在精力强旺者，久能自化；其不足者，变为丁奚、劳怯、痞臌等证，至死而人不能知，亦可哀也。余治此证不一，姑举其最剧者以明治法。", "11986": "姻戚殷之晋，年近八旬，素有肠红证，病大发，饮食不进，小腹高起，阴囊肿亮，昏不知人。余因新年贺岁候之，正办后事。余诊其脉，洪大有力，先以灶灰、石灰作布袋，置阴囊于上，袋湿而囊肿消；饮以知母、黄柏泻肾之品。越三日，余饮于周氏，周与至戚相近半里，忽有叩门声，启视之，则其子扶病者至，在座无不惊喜，同问余曰：何以用伐肾之药而愈？余曰：此所谓欲女子而不得也。众以为戏言。翁曰：君真神人也。我向者馆谷京师，患亦相似，主人以为无生理也，遂送我归，归旬日即痊。今妻妾尽亡，独处十余年，贫不能蓄妾，又耻为苟且之事，故病至此，既不可以告人，亦无人能知之者。言毕凄然泪下，又阅五年而卒。盖人之气禀各殊，亢阳之害，与纵欲同，非通于六经之理，与岐黄之奥者，不足与言也。", "11987": "洞庭吴伦宗夫人，席翁士俊女也，向患血证，每发，余以清和之药调之，相安者数年。郡中名医有与席翁相好者，因他姓延请至山，适遇病发，邀之诊视，见余前方，谓翁曰：此阳虚失血，此公自命通博，乃阴阳不辨耶！立温补方加鹿茸二钱，连服六剂，血上冒，连吐十余碗，一身之血尽脱，脉微目闭，面青唇白，奄奄待毙，急延余治。余曰：今脏腑经络俱空，非可以轻剂治。亟以鲜生地十斤，绞汁煎浓，略加人参末，徐徐进之，历一昼夜尽生地汁，稍知人事，手足得展动，唇与面红白稍分，更进阿胶、三七诸养阴之品，调摄月余，血气渐复。夫血脱补阳，乃指大脱之后，阴尽而阳无所附，肢冷汗出，则先用参附以回其阳，而后补其阴。或现种种虚寒之证，亦当气血兼补。岂有素体阴虚之人，又遇气升火旺之时，偶尔见红，反用大热升发之剂，以扰其阳而烁其阴乎！此乃道听途说之人，闻有此法，而不能深思其理，误人不浅也。", "11988": "嘉兴王蔚南，久患血证，左胁中有气，逆冲喉旁，血来有声如沸。戊子冬，忽大吐数升，面色白而带青，脉微声哑，气喘不得卧，危在旦夕。余以阿胶、三七等药，保其阴而止其血，然后以降火纳气之品，止其冲逆。复以补血消痰，健脾安胃之方，上下分治，始令能卧，继令能食，数日之后，方能安卧。大凡脱血之后，断不可重用人参升气助火，亦不可多用滋腻以助痰滞胃。要知补血之道，不过令其阴阳相和，饮食渐进，则元气自复，非补剂入腹，即变为气血也。若以重剂塞其胃口，则永无生路矣。况更用温热重剂，助阳烁阴而速之死乎。", "11989": "洞庭张姓，素有血证，是年为女办装，过费心力，其女方登轿，张忽血冒升余，昏不知人，医者浓煎参汤服之，命悬一息，邀余诊视。六脉似有如无，血已脱尽，急加阿胶、三七，少和人参以进，脉乃渐复，目开能言，手足展动，然后纯用补血之剂以填之，月余而起。盖人生不外气血两端，血脱则气亦脱，用人参以接其气，气稍接，即当用血药，否则孤阳独旺而阴愈亏，先后主客之分，不可不辨也。", "11990": "淮安程春谷，素有肠红证，一日更衣，忽下血斗余，晕倒不知人，急灌以人参一两，附子五钱而苏。遂日服人参五钱，附子三钱，而杂以他药，参附偶间断，则手足如冰，语言无力，医者亦守而不变，仅能支持，急棹来招，至则自述其全赖参附以得生之故。诊其六脉，极洪大而时伏，面赤有油光，舌红而不润，目不交睫者旬余矣。余曰：病可立愈，但我方君不可视也。春谷曰：我以命托君，止求效耳，方何必视。余用茅草根四两作汤，兼清凉平淡之药数品，与参附正相反。诸戚友俱骇，春谷弟风衣，明理见道之士也，谓其诸郎曰：尔父千里招徐君，信之至，徐君慨然力保无虞，任之至，安得有误耶。服一剂，是夕稍得寝，二剂手足温，三剂起坐不眩，然后示之以方，春谷骇叹，诸人请申其说。余曰：血脱扶阳，乃一时急救之法，脱血乃亡阴也。阳气既复，即当补阴。而更益其阳，则阴血愈亏，更有阳亢之病。其四肢冷者，《内经》所谓热深厥亦深也。不得卧者，《内经》所谓阳胜则不得入于阴，阴虚故目不瞑也。白茅根交春透发，能引阳气达于四肢，又能养血清火，用之，使平日所服参附之力，皆达于外，自能手足温而卧矣。于是始相折服。凡治血脱证俱同此。", "11991": "洞庭葛允诚，患血痢五年，日夜百余次，约去血数石，骨瘦如柴，饮食不进，举家以为必无生理。余友姜君锡常次子萼芳，从余学医于山中，病者即萼芳妻弟也。锡常怜之，令同萼芳寄膳余家，朝夕诊视。余先用滋补之剂以养其血脉，复用开胃之药以滋其化源，稍健而能食。久痢至五载，大肠之内必生漏管，遂以填补之品塞其空窍，痢日减，饭日增，不半年而每食饭必六七碗，至冬病全愈。丰肥强壮，归至家，亲戚俱不相识认，无不叹以为奇。", "11992": "余往候族兄龙友，坐谈之际，有老妪惶遽来曰：无救矣。余骇问故，龙友曰：我侄妇产二日不下，稳婆已回绝矣。问：何在？曰：即在前巷。余曰：试往诊之。龙友大喜，即同往。浆水已涸，疲极不能出声，稳婆犹令用力迸下。余曰：无恐，此试胎也。尚未产，勿强之，扶令安卧，一月后始产，产必顺，且生男。稳婆闻之微哂，作不然之态，且曰：此何人，说此大话。我收生数十年，从未见有如此而可生者。其家亦半信半疑。余乃处以养血安胎之方，一饮而胎气安和，全无产意。越一月，果生一男，而产极易。众以为神，龙友请申其说。曰：凡胎旺而母有风寒劳碌等感动，则胎坠下如欲生之象，安之即愈。不知而以为真产，强之用力，则胎浆破而胎不能安矣。余诊其胎脉甚旺，而月份未足，故知不产。今已摇动其胎，将来产时必易脱，故知易产。左脉甚旺，故知男胎。此极浅近之理，人自不知耳。", "11993": "苏州一小儿，甫九龄，颇聪慧，而患流注，肩背腰胁十余处，百端医治无效。余视之曰：此惟大活络丹能愈。服至三十余丸，未破者消，已破者收口。更服补气血之药而愈。盖流注一证，由风寒入膜所致，膜在皮中，旁通四达，初无定处，所以随处作患，此真脉络之病，故古人制大活络丹以治之。其余煎丸，皆非正治。所谓一病有一病之法，药不对证，总难取效也。", "11994": "本邑刘近曾夫人，患虚痰流注，色㿠脉虚，发无定处，病极危险，非旦夕可奏功，余辞不能治。郡中一医以百金包好，因留在家治之。闻余有不能治之说，笑曰：我医好后，更请徐君质之，当无言可对耳。月余，刘君之兄元谷招余诊，近曾出曰：流注之疾，虽向愈而未收口，托在相好，肯一观否？余因视之，肩后疮孔大如钱，内膜干空，与皮不连，气促脉微。诊毕而出，近曾求方，余笑不答，书「危在顷刻」四字。刘不信，少顷内呼，刘父子入，已气绝矣。群执包好之医，欲加以无礼。余晓之曰：此病本不治，非药误也。但不知生死，为无目耳。乃释之。盖流注之证，其类不同，大段皆津液枯而痰流膜内之证，当内外交治，而祛邪补虚，亦另有切病方药，蛮补无益也。", "11995": "南濠徐氏女，经停数月，寒热减食，肌肉消烁，小腹之右，下达环跳，隐痛微肿。医者或作怯弱，或作血痹，俱云不治。余诊其脉，洪数而滑，寒热无次。谓其父曰：此瘀血为痈，已成脓矣。必自破，破后必有变证，宜急治。与以外科托毒方并丸散，即返山中。越二日，天未明，叩门甚急，启视则徐之戚也。云脓已大溃，而人将脱矣。即登其舟往视，脓出升余，脉微肤冷，阳随阴脱。余不及处方，急以参附二味，煎汤灌之，气渐续而身渐温。然后以补血养气之品，兼托脓长肉之药，内外兼治，两月而漏口方满，精神渐复，月事以时。大凡瘀血久留，必致成痈。产后留瘀，及室女停经，外证极多。而医者俱不能知，至脓成之后，方觅外科施治，而外科又不得其法，以致枉死者，比比然也。", "11996": "郡中唐廷发，偶过余寓，时方暑，谓背上昨晚起一小瘰，搔之甚痒，先生肯一看否。余视之骇曰：此对心发也。唐不甚信，曰：姑与我药。余曰：君未信余言，一服药而毒大发，反疑我误君矣。含笑而去，明日已大如酒杯而痛甚，乃求医治。余曰：此非朝夕换方不可。我不能久留郡寓，奈何？因就医余家，旦暮易法，其中变迁不一，卒至收口。其收口前十日，忽头痛身热，神昏谵语，疮口黑陷，六脉参差。余适出门两日，归而大骇，疑为疮证变重，几无可药。细询其仆，乃贪凉当风而卧，疮口对风，膏药又落，风贯疮中，即所谓破伤风也。乃从外感治法，随用风药得汗而解，身凉神清，疮口复起，仍前治法而痊。若不审其故，又不明破伤风治法，则必无效，惟有相视莫解而已。", "11997": "葑门金姓，早立门首，卒遇恶风，口眼㖞斜，噤不能言。医用人参、桂、附诸品，此近日时医治风证不祧之方也。趣余视之，其形如尸，面赤气粗，目瞪脉大，处以祛风消痰清火之剂。其家许以重赀，留数日。余曰：我非行道之人，可货取也。固请，余曰：与其误药以死，莫若服此三剂。醒而能食，不服药可也。后月余，至余家拜谢。问之，果服三剂而起，竟不敢服他药。惟腿膝未健，手臂犹麻，为立膏方而全愈。此正《内经》所谓虚邪贼风也。以辛热刚燥治之固非，以补阴滋腻治之亦谬。治以辛凉，佐以甘温，《内经》有明训也。", "11998": "运使王公叙揆，自长芦罢官归里，每向余言：手足麻木而痰多。余谓：公体本丰腴，又善饮啖，痰流经脉，宜撙节为妙。一日忽昏厥遗尿，口噤手拳，痰声如锯，皆属危证。医者进参、附、熟地等药，煎成未服。余诊其脉洪大有力，面赤气粗，此乃痰火充实，诸窍皆闭，服参、附立毙矣。以小续命汤去桂、附加生军一钱，为末，假称他药纳之，恐旁人之疑骇也。戚党莫不哗然，太夫人素信余，力主服余药，三剂而有声，五剂而能言，然后以消痰养血之药调之，一月后步履如初。", "11999": "张出巷刘松岑，素好饮，后结酒友数人，终年聚饮，余戒之不止，时年才四十。除夕向店沽酒。称银手振，称坠而身亦仆地，口噤不知人，急扶归。岁朝遣人邀余，与以至宝丹数粒，嘱其勿服他药，恐医者知其酒客，又新纳宠，必用温补也。初五至其家，竟未服药，诊其脉弦滑洪大，半身不遂，口强流涎，乃湿痰注经传腑之证。余用豁痰驱湿之品，调之月余而起，一手一足不能如旧，言语始终艰涩。初无子，病愈后连举子女，皆成立，至七十三岁而卒。谁谓中风之人不能永年耶？凡病在经络筋骨，此为形体之病，能延岁月、不能除根。若求全愈，过用重剂，必至伤生。富贵之人闻此等说，不但不信，且触其怒，于是馅谀之人，群进温补，无不死者，终无一人悔悟也。", "12000": "东山席以万，年六十余，患风痹，时医总投温补，幸不至如近日之重用参、附，病尚未剧。余诊之，脉洪而气旺，此元气强实之体，而痰火充盛耳。清火消痰以治标，养血顺气以治本。然经络之痰，无全愈之理，于寿命无伤，十年可延也。以平淡之方，随时增损，调养数载，年七十余始卒。此所谓人实证实，养正驱邪，以调和之，自可永年；重药伤正，速之死耳。", "12001": "叔子静素无疾，一日，余集亲友小酌，叔亦在座吃饭，至第二碗仅半，头忽垂，箸亦落，同座问曰：醉耶？不应。又问：骨哽耶？亦不应。细视之，目闭而口流涎，群起扶之别座，则颈已歪，脉已绝，痰声起，不知人矣。亟取至宝丹灌之，始不受，再灌而咽下。少顷开目，问扶者曰：此何地也？因告之故，曰：我欲归。扶之坐舆内以归。处以驱风消痰安神之品，明日已能起，惟软弱无力耳，以后亦不复发。此总名卒中，亦有食厥，亦有痰厥，亦有气厥，病因不同。如药不预备，则一时气不能纳，经络闭塞，周时而死。如更以参、附等药，助火助痰，则无一生者。及其死也，则以为病本不治，非温补之误，举世皆然也。", "12002": "湖州副总戎穆公廷粥，气体极壮，忽患牙紧不开，不能饮食，绝粒者五日矣。延余治之，晋接如常，惟呼饥耳。余启视其齿，上下止开一细缝，抚其两颊，皮坚如革，细审病情，莫解其故。因问曰：此为恶风所吹，公曾受恶风否？曰：无之。既而恍然曰：诚哉。二十年前曾随围口外卧帐房中，夜半怪风大作，帐房拔去，卒死者三人，我其一也。灌以热水，二人生而一人死，我初醒，口不能言者二日，岂至今复发乎？余曰：然。乃戏曰：凡治皮之工，皮坚则消之，我今欲用药消公之颊皮也。乃以蜈蚣头、蝎子尾及朴硝、硼砂、冰、麝等药擦其内，又以大黄、牙皂、川乌、桂心等药涂其外，如有痰涎则吐出。明晨余卧未起，公启户曰：真神仙也，早已食粥数碗矣。遂进以驱风养血膏而愈。盖邪之中人，深则伏于脏腑骨脉之中，精气旺则不发，至血气既衰，或有所感触，虽数十年之久，亦有复发者。不论内外之证尽然，亦所当知也。", "12003": "西塘倪福征，患时证，神昏脉数，不食不寝，医者谓其虚，投以六味等药，此方乃浙中医家不论何病必用之方也。遂粒米不得下咽，而烦热益甚，诸人束手，余诊之曰：热邪留于胃也。凡外感之邪，久必归阳明。邪重而有食，则结成燥矢，三承气主之；邪轻而无食，则凝为热痰，三泻心汤主之。乃以泻心汤加减，及消痰开胃之药，两剂而安。诸人以为神奇，不知此乃浅近之理，《伤寒论》其在细读自明也。若更误治，则无生理矣。", "12004": "雄按：韩尧年，年甫逾冠，体素丰而善饮。春间偶患血溢，广服六味等药。初夏患身热痞胀，医投泻心、陷胸等药，遂胀及少腹，且拒按，大便旁流，小溲不行，烦热益甚，汤饮不能下咽，谵语唇焦。改用承气、紫雪，亦如水投石。延余视之，黄苔满厚而不甚燥，脉滑数而按之虚软，不过湿热阻气，升降不调耳。以枳桔汤加白前、紫菀、射干、马兜铃、杏仁、厚朴、黄芩，用芦根汤煎。一剂谵语止，小溲行；二剂旁流止，胸渐舒；三剂可进稀糜；六剂胸腹皆舒，粥食渐加。改投清养法，又旬日得解燥矢而愈。诸人亦以为神奇，其实不过按证设法耳。", "12005": "郡中蒋氏子，患时证，身热不凉，神昏谵语，脉无伦次。余诊之曰：此游魂证也，虽服药必招其魂。因访招魂之法，有邻翁谓曰：我闻虔祷灶神，则能自言。父如其言，病者果言曰：我因看戏，小台倒，几被压受惊，复往城隍庙中散步，魂落庙中，当以肩舆抬我归。如言往招。明日延余再诊，病者又言：我魂方至房门，为父亲冲散，今早魂卧被上，又为母亲叠被掉落，今不知所向矣。咆哮不已，余慰之曰：无忧也，我今还汝。因用安神镇魄之药，加猪心尖、辰砂，绛帛包裹，悬药罐中煎服，戒曰：服药得寝，勿惊醒之，熟寐即神合。果一剂而安，调理而愈，问之俱不知也。", "12006": "杨州吴运台夫人，患消证，昼夜食粥数十碗，气逆火炎，通夕不寝。余诊之，六脉细数不伦，神不清爽。余曰：此似祟脉，必有他故。其家未信，忽一日仆妇晨起入候，见床上一女盛妆危坐，以为夫人也，谤视则无有，因以告。夫人曰：此女常卧我床内，以此不能成寐，而烦渴欲饮耳。服余药未甚效，一夕夜将半，病者大呼曰：速请三舅爷来，切不可启门，启门则我魂必走出。三舅爷者，即其弟唐君悔生也。卧室辽隔，呼之不能闻，女仆私启门邀之，魂即随出，遍历厅堂廊庑，及平昔足未经行者，遇唐君趋至，魂坚执其辫，仍返房，见已身卧床上，唐君抚之，魂遂归附于身。问所寓目皆不爽，细考所见之女，乃运台聘室也，未成婚而卒，卒之时，嘱其父母吴郎必显贵，我死须恳其血食我，而葬我于祖墓。运台服官后，未暇办，故为祟。运台谓余曰：君言有为祟者，考果验，真神人也。将何以慰之？余曰：鬼有所归，乃不为厉，公当迎柩厝墓，立位而祀之可也。运台依余言以行，然后服药有功，而病根永除矣。", "12007": "雍正十年，昆山瘟疫大行，因上年海啸，近海流民数万，皆死于昆，埋之城下，至夏暑蒸尸气，触之成病，死者数千人。汪翁天成亦染此证，身热神昏，闷乱烦躁，脉数无定。余以清凉芳烈，如鲜菖蒲、泽兰叶、薄荷、青蒿、芦根、茅根等药，兼用辟邪解毒丸散进之，渐知人事。因自述其昏晕时所历之境，虽言之凿凿，终虚妄不足载也。余始至昆时，惧应酬不令人知，会翁已愈，余将归矣。不妨施济，语出而求治者二十七家，检其所服，皆香燥升提之药，与证相反。余仍用前法疗之，归后有叶生为记姓氏，愈者二十四，死者止三人，又皆为他医所误者，因知死者皆在。凡治病不可不知运气之转移，去岁因水湿得病，湿甚之极，必兼燥化，《内经》言之甚明，况因证用药，变化随机，岂可执定往年所治祛风逐湿之方，而以治瘟邪燥火之证耶？", "12008": "同学赵子云居太湖之滨，患暑痢甚危，留治三日而愈。时值亢旱，人忙而舟亦绝少，余欲归不能。惟邻家有一舟，适有病人气方绝，欲往震泽买棺，乞借一日不许。有一老妪指余曰：此即治赵某病愈之人也。今此妇少年恋生甚，故气不即断，盍求一诊？余许之，脉绝而心尚温，皮色未变，此暑邪闭塞诸窍，未即死也。为处清暑通气方，病家以情不能却，借舟以归。越数日，子云之子来，询之，一剂而有声，二剂能转侧，三剂起矣。", "12009": "芦墟迮耕石，暑热坏证，脉微欲绝，遗尿谵语，寻衣摸床，此阳越之证，将大汗出而脱，急以参附加童便饮之，少苏而未识人也。余以事往郡，戒其家曰：如醒而能言，则来载我。越三日来请，亟往果生矣。医者谓前药已效，仍用前方煎成未饮。余至曰：阳已回，火复炽，阴欲竭矣。附子入咽即危，命以西瓜啖之，病者大喜，连日啖数枚，更饮以清暑养胃而愈。后来谢述昏迷所见，有一黑人立其前，欲啖之，即寒冷入骨，一小儿以扇驱之，曰：汝不怕霹雳耶？黑人曰：熬尔三霹雳，奈我何？小儿曰：再加十个西瓜何如？黑人惶恐而退。余曰：附子古名霹雳散，果服三剂，非西瓜则伏暑何由退，其言皆有证据，亦奇事也。", "12010": "毛履和之子介堂，暑病热极，大汗不止，脉微肢冷，面赤气短，医者仍作热证治。余曰：此即刻亡阳矣，急进参、附以回其阳。其祖有难色。余曰：辱在相好，故不忍坐视，亦岂有不自信而尝试之理，死则愿甘偿命。乃勉饮之，一剂而汗止，身温得寐，更易以方，不十日而起，同时东山许心一之孙伦五，病形无异，余亦以参、附进，举室皆疑骇，其外舅席际飞笃信余，力主用之，亦一剂而复。但此证乃热病所变，因热甚汗出而阳亡，苟非脉微足冷，汗出舌润，则仍是热证，误用即死，死者甚多，伤心惨目。此等方非有实见，不可试也。", "12011": "洞庭后山席姓者，暑邪内结，厥逆如尸，惟身未冷，脉尚微存，所谓尸厥也。余谓其父曰：邪气充塞，逼魂于外，通其诸窍，魂自返耳。先以紫金锭磨服，后用西瓜、芦根、萝卜、甘蔗打汁，时时灌之，一日两夜，纳二大碗而渐苏。问之，则曰：我坐新庙前大石上三日，见某家老妪，某家童子，忽闻香气扑鼻，渐知身在室中，有一人卧床上，我与之相并，乃能开目视物矣。新庙者，前山往后山必由之路，果有大石，询两家老妪、童子，俱实有其事。此类甚多，不能尽述，其理固然，非好言怪也。", "12012": "阊门龚孝维，患热病，忽手足拘挛，呻吟不断，瞀乱昏迷，延余诊视，脉微而躁，肤冷汗出，阳将脱矣。急处以参附方。亲戚满座，谓大暑之时，热病方剧，力屏不用。其兄素信余，违众服之，身稍安。明日更进一剂，渐苏能言，余乃处以消暑养阴之方而愈。", "12013": "洞庭姜锡常长郎佩芳，体素弱而患久疟，时余应山前叶氏之招，便道往晤佩芳出诊，色夭脉微，而动易出汗。余骇曰：汝今夕当大汗出而亡阳矣，急进参、附，或可挽回。其父子犹未全信，姑以西洋参三钱，偕附子饮之，仍回叶宅。夜二鼓叩门声甚急，启门而锡常以肩舆来迎，至则汗出如膏，两目直视，气有出无入，犹赖服过参、附，阳未遽脱，适余偶带人参钱许，同附子、童便灌入，天明而汗止阳回，始知人事。然犹闻声即晕，倦卧不能起者两月，而后起坐。上工治未病，此之谓也。如此危急之证，不但误治必死，即治之稍迟，亦不及挽回。养生者，医理不可不知也。", "12014": "崇明施姓，迁居郡之盘门，其子患暑毒血痢，昼夜百余行，痛苦欲绝。嘉定张雨亭，其姻戚也，力恳余诊之。余曰：此热毒蕴结。治之以黄连、阿胶等药，一服而去十之七八矣。明日再往，神清气爽，面有喜气。余有事归家，约隔日重来，归后遇风潮，连日行舟断绝，三日后乃得往诊，病者怒目视余，问以安否？厉声而对曰：用得好药，病益重矣。余心疑之，问其父，曾服他人药否？隐而不言。余甚疑之，辞出有二医者入门，因托雨亭访其故，其父因余不至，延郡中名医，仍进以人参、干姜等药。绐病者曰：视汝脉者，此地名医，而药则用徐先生方也。及服而痛愈剧，痢益增，故恨余入骨耳，岂不冤哉！又闻服药之后，口干如出火，欲啖西瓜，医者云痢疾吃西瓜必死，欲求凉水，尤禁不与，因绐其童取井水嗽口，夺盆中水饮其半，号呼两日而死。近日治暑痢者，皆用《伤寒论》中治阴寒入脏之寒痢法，以理中汤加减，无不腐脏惨死，甚至有七窍流血者，而医家病家视为一定治法，死者接踵，全不知悔，最可哀也。", "12015": "嘉善许阁学竹君夫人抱疾，医过用散剂以虚其表，继用补剂以固其邪，风入营中，畏风如矢，闭户深藏者数月，与天光不相接，见微风则发寒热而晕，延余视。余至卧室，见窗槅皆重布遮蔽，又张帷于床前，暖帐之外，周以毡单。诊其脉，微软无阳，余曰：先为药误而避风太过，阳气不接，卫气不闭，非照以阳光不可，且晒日中，药乃效。阁学谓：见日必有风，奈何？曰：姑去其瓦，令日光下射晒之何如？如法行之，三日而能启窗户，十日可见风，诸病渐愈。明年阁学挈眷赴都，舟停河下，邀余定常服方，是日大风，临水窗候脉，余甚畏风，而夫人不觉也。盖卫气固，则反乐于见风，此自然而然，不可勉强也。", "12016": "雄按：今秋藩库吏孙位申，积劳善怒，陡然自汗凛寒，脘疼咳逆，呕吐苦水，延余诊之，脉弦软而滑，形瘦面黧，苔黄不渴，溲赤便难，以二陈去甘草，加沙参、竹茹、枇杷叶、竹叶、黄连、蒌仁为剂。渠云阳痿已匝月矣，恐不可服此凉药。余曰：此阳气上升，为痰所阻，而不能下降耳。一服逆平痛定，呕罢汗止，即能安谷。原方加人参，旬日阳事即通，诸恙若失。", "12017": "雄按：今夏刘午亭，年六十三岁，久患痰喘自汗，群医皆以为虚，补剂备施，竟无效。徐月岩嘱其浼余视之，汗如雨下，扇不停挥，睛凸囟高，面浮颈大，胸前痞塞，脉滑而长，妻女哀求，虑其暴脱。余曰：将塞死矣，何脱之云？与导痰汤加旋覆、海石、泽泻、白前，一饮而减，七日后囟门始平，匝月而愈。继有顾某年五十六岁，肥白多痰，因啖莲子匝月，渐觉不饥，喘逆自汗无眠，以为虚也。屡补之后，气逆欲死，速余视之，苔黄溲赤，脉滑不调，以清肺涤痰治之而愈，旋以茯苓饮善其后。", "12018": "苏州沈母，患寒热痰喘，浼其婿毛君延余诊视。先有一名医在座，执笔沉吟曰：大汗不止，阳将亡矣。奈何？非参、附、熟地、干姜不可，书方而去。余至不与通姓名，俟其去乃入，诊脉洪大，手足不冷，喘汗淋漓。余顾毛君曰：急买浮麦半合，大枣七枚，煮汤饮之可也。如法服而汗顿止，乃为立消痰降火之方，二剂而安。盖亡阳亡阴，相似而实不同，一则脉微，汗冷如膏，手足厥逆而舌润；一则脉洪，汗热不黏，手足温和而舌干。但亡阴不止，阳从汗出，元气散脱，即为亡阳。然当亡阴之时，阳气方炽，不可即用阳药，宜收敛其阳气，不可不知也。亡阴之药宜凉，亡阳之药宜热，一或相反，无不立毙。标本先后之间，辨在毫发，乃举世更无知者，故动辄相反也。", "12019": "雄按：吴馥斋令姊体属阴亏，归沈氏后，余久不诊，上年闻其久嗽，服大剂滋补而能食肌充，以为愈矣。今夏延诊云：嗽犹不愈。及往视，面浮色赤，脉滑不调，舌绛而干，非肉不饱。曰：此痰火为患也。不可以音嘶胁痛，遂疑为损怯之末传。予清肺化痰药为丸噙化，使其廓清上膈，果胶痰渐吐，各恙乃安。其形复瘦，始予养阴善后。病者云：前进补时，体颇渐丰，而腰间疼胀，略一抚摩，嗽即不已，自疑为痰。而医者谓为极虚所致，补益加峻，致酿为遍体之痰也。", "12020": "雄按：痰喘碍眠，亦有不兼虚者。黄者华年逾五旬，自去冬因劳患喘，迄今春两旬不能卧，顾某作下喘治，病益甚。又旬日，迓余视之，脉弦滑，苔满布舌边绛，乃冬温薄肺，失于清解耳，予轻清肃化药治之而痊。至参不入煎，欲其下达；与丸药噙化，欲其上恋，皆有妙义，用药者勿以一煎方为了事也。又有虚不在阴分者。余治方啸山，今秋患痰喘汗多，医进清降药数剂，遂便溏肢冷，不食碍眠，气逆脘疼，面红汗冷，余诊之，脉弦软无神，苔白不渴，乃寒痰上实，肾阳下虚也。以真武汤去生姜，加干姜、五味、人参、厚朴、杏仁，一剂知，二剂已。又治顾某体肥白，脉沉弱，痰喘易汗，不渴痰多，啜粥即呕，以六君去甘草，加厚朴、杏仁、姜汁、川连，盖中虚痰滞也，投匕果痊。", "12021": "雄按：今夏江阴沙沛生鹾尹，患胸下痞闷，腹中聚块，卧则膊间有气下行至指，而惕然惊寤。余谓气郁饮停，治以通降。适渠将赴都，自虑体弱，有医者迎合其意，投以大剂温补，初若相安，旬日后神呆不语，目眩不饥，便闭不眠，寒热时作，复延余诊。按其心下，则濯濯有声，环脐左右，块已累累，溺赤苔黄，脉弦而急，幸其家深信有年，旁无掣肘。凡通气涤饮、清络舒肝之剂，调理三月，各恙皆瘳。", "12022": "雄按：吴雨峰大令，年七十一岁，今秋患感发热，而兼左胁偏痛，舌色干紫无苔，稍呷汤饮，小溲即行，不食不便，脉洪且数。余知其平素津虚脾约，气滞痰凝，连予轻肃宣濡之剂，热渐缓，胁渐舒，而舌色不润，仍不喜饮，溲赤便闭，呃忒频来，举家皇皇。余曰：无恐也，便行即止矣。逾二日，连得畅解，脉静身凉，舌色有津，呃仍不减，人皆谓高年病后之虚呃，议用镇补。余曰：此气为痰阻，升降失调，得食不舒，平时无嚏，是其征也。授以枳桔汤加蒌、薤、菖、茹、橘、半、柴胡，果一剂知，二剂已。", "12023": "苏州黄四房女，年十二，患腹痛，愈医愈甚。余偶至其家，昏厥一夕方苏，舌俱咬破，流血盈口，唇白而目犹直视，脉参错无常。余曰：此虫痛也。贯心则死，非煎药所能愈。合化虫丸与之，痛稍缓，忽复更痛，吐出虫二十余条，长者径尺，紫色，余长短不齐，淡红色，亦有白者，自此而大痛不复作，小痛未除，盖其窠未去也。复以杀虫之药，兼安胃补脾之方，调之而虫根遂绝。盖此证甚多，医者既不能知，惟认为寒与食，即以为虫，又无杀虫之方，在精力强旺者，久能自化；其不足者，变为丁奚、劳怯、痞膨等证，至死而人不能知，亦可哀也。余治此证不一，姑举其最剧者以明治法。", "12024": "姻戚殷之晋，年近八旬，素有肠红证，病大发，饮食不进，小腹高起，阴囊肿亮，昏不知人。余因新年贺岁候之，正办后事。余诊其脉，洪大有力，先以灶灰、石灰作布袋，置阴囊于上，袋湿而囊肿消；饮以知母、黄柏泻肾之品。越三日，余饮于周氏，周与至戚相近半里，忽有叩门声，启视之，则其子扶病者至，在座无不惊喜，同问余曰：何以用伐肾之药而愈？余曰：此所谓欲女子而不得也。众以为戏言。翁曰：君真神人也。我向者馆谷京师，患亦相似，主人以为无生理也，遂送我归，旬日即痊。今妻妾尽亡，独处十余年，贫不能蓄妾，又耻为苟且之事，故病至此，既不可以告人，亦无人能知之者。言毕，凄然泪下。又阅五年而卒。盖人之气禀各殊，亢阳之害，与纵欲同，非通于六经之理，与岐黄之奥者，不足与言也。", "12025": "洞庭吴伦宗夫人，席翁士俊女也，向患血证，每发，余以清和之药调之，相安者数年，郡中名医有与席翁相好者，因他姓延请至山，适遇病发，邀之诊视，见余前方，谓翁曰：此阳虚失血，此公自命通博，乃阴阳不辨耶！立温补方加鹿茸二钱，连服六剂，血上冒，连吐十余碗，一身之血尽脱，脉微目闭，面青唇白，奄奄待毙，急延余治。余曰：今脏腑经络俱空，非可以轻剂治，亟以鲜生地十斤，绞汁煎浓，略加人参末，徐徐进之，历一昼夜尽生地汁，稍知人事，手足得展动，唇与面红白稍分，更进阿胶、三七诸养阴之品，调摄月余，血气渐复。夫血脱补阳，乃指大脱之后，阴尽而阳无所附，肢冷汗出，则先用参、附以回其阳，而后补其阴。或现种种虚寒之证，亦当气血兼补。岂有素体阴虚之人，又遇气升火旺之时，偶尔见红，反用大热升发之剂，以扰其阳而烁其阴乎？此乃道听途说之人，闻有此法，而不能深思其理，误人不浅也。", "12026": "嘉兴王蔚南，久患血证，左胁中有气逆冲喉旁，血来有声如沸。戊子冬，忽大吐数升，面色白而带青，脉微，声哑，气喘不得卧，危在旦夕。余以阿胶、三七等药，保其阴而止其血，然后以降火纳气之品，止其冲逆，复以补血消痰，健脾安胃之方，上下分治，始令能卧，继令能食，数日之后，方能安卧。大凡脱血之后，断不可重用人参升气助火，亦不可多用滋腻以助痰滞胃。要知补血之道，不过令其阴阳相和，饮食渐进，则元气自复，非补剂入腹，即变为气血也。若以重剂塞其胃口，则永无生路矣。况更用温热重剂，助阳烁阴而速之死乎？", "12027": "洞庭张姓，素有血证，是年为女办装，过费心力，其女方登轿，张忽血冒升余，昏不知人，医者浓煎参汤服之，命悬一息，邀余诊视。六脉似有如无，血已脱尽，急加阿胶、三七，少和人参以进，脉乃渐复，目开能言，手足展动，然后纯用补血之剂以填之，月余而起。盖人生不外气血两端，血脱则气亦脱，用人参以接其气，气稍接，即当用血药，否则孤阳独旺，而阴愈亏，先后主客之分，不可不辨也。", "12028": "淮安程春谷，素有肠红证，一日更衣，忽下血斗余，晕倒不知人，急灌以人参一两，附子五钱而苏。遂日服人参五钱，附子三钱而杂以他药，参、附偶间断，则手足如冰，语言无力，医者亦守而不变，仅能支持，急棹来招余，则自述其全赖参、附以得生之故。诊其六脉，极洪大而时伏，面赤有油光，舌红而不润，目不交睫者旬余矣。余曰：病可立愈，但我方君不可视也。春谷曰：我以命托君，止求效耳，方何必视。余用茅草根四两作汤，兼清凉平淡之药数品，与参、附正相反。诸戚友俱骇，春谷弟风衣，明理见道之士也。谓其诸郎曰：尔父千里招徐君，信之至，徐君慨然力保无虞，任之至，安得有误耶？服一剂，是夕稍得寝，二剂手足温，三剂起坐不眩，然后示之以方，春谷骇叹，诸人请申其说。余曰：血脱扶阳，乃一时急救之法，脱血乃亡阴也。阳气既复，即当补阴。而更益其阳，则阴血愈亏。更有阳亢之病，其四肢冷者，《内经》所谓热深厥亦深也。不得卧者，《内经》所谓阳胜则不得入于阴，阴虚故目不瞑也。白茅根交春透发，能引阳气达于四肢，又能养血清火，用之，使平日所服参、附之力，皆达于外，自能手足温而卧矣。于是始相折服。凡治血脱证俱同此。", "12029": "洞庭葛允诚，患血痢五年，日夜百余次，约去血数石，骨瘦如柴，饮食不进，举家以为必无生理。余友姜君锡常次子萼芳，从余学医于山中，病者即萼芳妻弟也。锡常怜之，令同萼芳寄膳余家，朝夕诊视。余先用滋补之剂以养其血脉，复用开胃之药以滋其化源，稍健而能食。久痢至五载，大肠之内必生漏管，遂以填补之品塞其空窍，痢日减，饭日增，不半年而每食饭必六七碗，至冬病全愈，丰肥强壮，归至家，亲戚俱不相识认，无不叹以为奇。", "12030": "余往候族兄龙友，坐谈之际，有老妪惶遽来曰：无救矣。余骇问故，龙友曰：我侄妇产二日不下，稳婆已回绝矣，问：何在？曰：即在前巷。余曰：试往诊之。龙友大喜，即同往，浆水已涸，疲极不能出声，稳婆犹令用力迸下，余曰：无恐，此试胎也，尚未产，勿强之，扶令安卧，一月后始产，产必顺，且生男。稳婆闻之微哂，作不然之态，且曰：此何人？说此大话，我收生数十年，从未见有如此而可生者。其家亦半信半疑。余乃处以养血安胎之方，一饮而胎气安和，全无产意。越一月，果生一男，而产极易。众以为神，龙友请申其说。曰：凡胎旺而母有风寒劳碌等感动，则胎坠下如欲生之象，安之即愈，不知而以为真产，强之用力，则胎浆破而胎不能安矣。余诊其胎脉甚旺，而月分未足，故知不产，今已摇动其胎，将来产时必易脱，故知易产。左脉甚旺，故知男胎。此极浅近之理，人自不知耳。", "12031": "苏州一小儿，甫九龄，颇聪慧，而患流注，肩背腰胁十余处，百端医治无效。余视之曰：此惟大活络丹能愈。服至三十余丸，未破者消，已破者收口；更服补气血之药而愈。盖流注一证，由风寒入膜所致，膜在皮中，旁通四达，初无定处，所以随处作患，此真脉络之病。故古人制大活络丹以治之，其余煎丸，皆非正治。所谓一病有一病之法，药不对证，总难取效也。", "12032": "本邑刘近曾夫人，患虚痰流注，色㿠脉虚，发无定处，痛极危险，非旦夕可奏功，余辞不能治。郡中一医以百金包好，因留在家治之。闻余有不能治之说，笑曰：我医好后，更请徐君质之，当无言可对耳。月余，刘君之兄元谷招余诊，近曾出曰：流注之疾，虽向愈而未收口，托在相好，肯一观否？余因视之，肩后疮孔大如钱，内膜干空，与皮不连，气促脉微。诊毕而出，近曾求方，余笑不答，书「危在顷刻」四字，刘不信，少顷内呼，刘父子入，已气绝矣。群执包好之医，欲加以无礼。余晓之曰：此病本不治，非药误也。但不知生死，为无目耳。乃释之。盖流注之证，其类不同，大段皆津液枯而痰流膜内之证，当内外交治，而祛邪补虚，亦另有切病方药，蛮补无益也。", "12033": "南濠徐氏女，经停数月，寒热减食，肌肉消烁，小腹之右，下达环跳，隐痛微肿，医者或作怯弱，或作血痹，俱云不治。余诊其脉，洪数而滑，寒热无次，谓其父曰：此瘀血为痈，已成脓矣。必自破，破后必有变证，宜急治。与以外科托毒方并丸散，即返山中。越二日，天未明，叩门甚急，启视则徐之戚也。云：脓已大溃，而人将脱矣。即登其舟往视，脓出升余，脉微肤冷，阳随阴脱。余不及处方，急以参、附二味，煎汤灌之，气渐续而身渐温；然后以补血养气之品，兼托脓长肉之药，内外兼治，两月而漏口方满，精神渐复，月事以时。大凡瘀血久留，必致成痈。产后留瘀，及室女停经，外证极多。而医者俱不能知，至脓成之后，方觅外科施治，而外科又不得其法，以致枉死者，比比然也。", "12034": "郡中唐廷发，偶过余寓，时方暑，谓背上昨晚起一小瘰，搔之甚痒，先生肯一看否？余视之，骇曰：此对心发也。唐不甚信，曰：姑与我药。余曰：君未信余言，一服药而毒大发，反疑我误君矣。含笑而去，明日已大如酒杯而痛甚，乃求医治。余曰：此非朝夕换方不可，我不能久留郡寓，奈何？因就医余家，旦暮易法，其中变迁不一，卒至收口。其收口前十日，忽头痛身热，神昏谵语，疮口黑陷，六脉参差。余适出门，两日归而大骇，疑为疮证变重，几无可药。细询其仆，乃贪凉当风而卧，疮口对风，膏药又落，风贯疮中，即所谓破伤风也。乃从外感治法，随用风药得汗而解，身凉神清，疮口复起，仍前治法而痊。若不审其故，又不明破伤风治法，则必无效，惟有相视莫解而已。", "12035": "一、字之书写错误。如卷上胡雍甫题词，有「析疑辨难最艰辛」句，误写为「折疑」。温病门案一，诊视「六脉洪大无伦」，误写为「无论」。其他案中有「拒按」误写为「惧按」。", "12036": "君姓翟氏，青云其名，竹亭，字也。先世居山西洪洞，洪武初迁杞，旋移直隶长垣大翟庄；咸丰壬子，避河患复来杞，遂家焉。祖明亮，父兴治，母氏韩。君性沉挚，有毅力。家固贫，父患瘫痪，卧床数年，八口之家，恃君以养。时方童稚，不任力作，为小负贩，以博微利。值年凶荒，生计益窘，煮藜藿为食；四、五两妹，童养于人。光绪甲午，君年十六，有通许医生游先耕者，至杞悬壶隍庙；君敬其人，因从习医，游以孺子可教，授方脉及针灸术。钻研数载，尽得其秘，遂出问世。师殁为营丧葬。乙未春，父殁不能具棺殓，赖亲邻资助，草草薄葬，恒用疚心。甲辰冬，君娶李氏，越五年病殁，无所出。庚戌夏，母以积劳罹疾弃养，君哀毁几至灭性。服阕，续杨氏，生子夔龙，女五。长、次皆适人，余待字。君性孝友，亲殁后，诸妹以次遣嫁。长适李，不能自给，助以赀，俾之营运。次适刘，早丧所天，依君以居，又嫁其甥女。胞叔兴国早世，叔母张，婚居茹苦，迎养十余年；迨其子成立，始别居。堂侄见龙，伶仃无依，招使习医，教养兼至。先世墓碑阙如，君植树立石，以展孝思，建祠修谱，胥君创办。迹君生平，殆所谓孝慈兼尽，内行克敦者欤！君少失学，未尝读书而好问，遇名医宿儒，辄虚心造访，以蕲教益。久之能自诵习。于《灵枢》、《素问》、《难经》，张、刘、朱、李诸名著，致力尤深。心折濒湖、景岳，自号湖岳村叟，业医数十载，活人无算，治疗奇症甚多（详见所著医案，兹不复述）。", "12037": "吾友湖岳村叟，杰士也。心折濒湖、景岳两医家，因以自号。医生胡以杰目之，曰：「孟子言豪杰之士，虽无文王犹兴；叟无所凭借，以劳心苦思，竟成国手，目为杰士固宜！」叟姓翟氏，字竹亭。祖籍洪洞。明洪武初，以迁民来杞，旋移直隶长垣之大翟庄，咸丰壬子，河决铜瓦箱，复来杞，遂为杞人。祖寅功，父化醇，母氏韩。君鲜兄弟，有妹五。家世贫，仅负郭田数亩，幼从父作小负贩。十五岁时，父患瘫痪疾，八口之家，恃五尺之童以养。母每日造煎饼，使君游市卖之，博蝇头利。又值大旱，田尽售，仍不给。时煮椿叶为食，四、五两妹，皆许人为童养媳。十六岁，有通许医生游先耕来杞，悬壶隍庙，君从习医。游以为儒子可教，指授脉理，外教以针灸之术。从师五年，尽得其传，即出而问世。师殁，尽力助葬费，不忘本也。十七岁，父卧床二载，又患瘟疫，遂逝世。无以为葬，叩求亲邻，得微资薄葬之，用是疚心焉。二十九岁，始取李氏，越五年以疾殁，无所出。三十二岁，母以操劳过度，遇疟疾弃养。是时后丧逾前丧，力所能及，不忍薄也。迨服阕，续娶杨氏，生子夔龙，女五。君性孝友，亲殁后，诸妹以次遣嫁。长适李，不能自给，助以货，俾营运糊口。次适刘，所天早丧，依君以居，又嫁其甥女。叔母张，年老家贫，迎养十余年；其子能自立，始令去。堂侄见龙无依，招使习医，教养无异所生。在杞祖茔，向无碑志，君为立石植树。宗族戚友，皆时通有无，赡其不足。又念翟氏族大散居，谱系无考，倡首修谱建祠，独出巨货，不辞劳勚。迹君平生，殆六行兼备者欤！君未尝入塾读书，而勤学好问，遇名医宿儒，必质疑问难，以故《素问》、《难经》等书，皆默识心通，于《濒湖脉诀》、《景岳全书》，尤有心得，至《温病条辨》、《伤寒论》，则参以己见，融会而变通之，故施方辄效。积四十年经验，汇集所著奇症，作医案二卷，类别门分，言病症治法甚详，名《湖岳村叟医案》。一时名宿，竞为作序、题词。将以付梓，欲公诸世，非以炫名也。君生于光绪乙卯，今年六十有四，可谓于此道三折肱者。仆与之素契，知君之增益所不能者，实由饿体肤，苦心志，动心、忍性而来。故独不谓君谓国手，且以君为杰士也。", "12038": "邑西梁堂村，邢君少白之弟，十七岁。于腊月患疫，初得寒热往来，头疼身痛。某医认为伤寒表证，用麻黄桂枝汤，大剂连进，谓得汗即解。乃不止无汗，转烦躁不宁，大渴思饮，日哺潮热更甚。某医又谓病入阳明之腑，本宜用大承气汤。仲景云：倘有一分表证未罢，不可骤攻。遂用白虎加减，连服二剂，大渴虽止，每日至戌时，发狂詈骂，不避亲疏，夜无少停。少白邀余往诊。诊得六脉洪大无伦，中取不见。误服表药凉药，逼阳外越，危殆极矣。辞不治。少白恳求不已，曰：「倘有一线生机，岂肯坐视？」予感少白恳切，勉开桂附八味汤重剂加减，令其热药冷服，以敛真阳。服下二时许，少白自内出，面有喜色，告余曰：「吾弟狂躁将止，昏昏欲睡。」余知是神归气复，令勿惊动。日晓方醒，饮食少进。至戌时前证不发。后改八味出入加减，服四帖，出战汗而愈。", "12039": "按：六脉洪大无伦，中取不见，知是逼阳外越，用桂附回阳愈。若非见证的确，温疫中不敢冒味用之，再六味加减滋阴甚为合法。", "12040": "少白族叔，年七十余，同时患疫，误治失下，遂大渴饮水，心胸胀满，谵语狂躁，小便赤涩，大便闭结。少白邀余往诊，诊得六脉洪大有力，此应下实证。余告少白曰：「此当用大承气汤。」少白面有惊色，遂云：「老人岂敢攻乎？余应之曰：「《内经》云：「有故无殒，亦无殒也。」倘惜老人，岂不误事，遂投一帖，半日许，方下燥粪五六枚，黏滞秽物，约有斗余。至夜，病减六七。后改用四物汤加减，以培根本，服五帖，得自汗，旬日平复。", "12041": "少白佃户，王姓，母年六十余。三月间染疫，数医不愈，危殆已甚。迎余往诊，观其满面通红，言语喃喃，胸腹拒按，形如死人，不饮不食，业已数日，余辞不治。其子叩首求救，碍于人情，实难脱身。据伊六脉按至伏滑微细劲硬。知是老人阴虚，津液枯竭，邪毒结于肠胃。遂用扶正攻邪之药，煎成与服。一时许泻下臭水秽便。明日手足少能动移，略进汤水，后改用养阴退热解毒之味，调理月余方愈。", "12042": "少白令爱年十七，染时疫，初得，邀余往诊，见神色已脱，如梦如醉，其脉细弦，真绝证也。后殁。", "12043": "邑庠生朱晓亭之女年十八，于四月染疫，邀余时已病旬余日矣。诊得尺脉沉数，病势大热不止，每日哺时，如见鬼神，狂言乱语，竟无宁刻。问其母：「病前见天癸否？」伊母云：「未病前一日适逢，天癸刚过。」始知热入血室，遇此险症，若不明治法，一用下药无不立死。余用吴又可小柴胡汤加减。服二帖，后发鼻衄而愈。", "12044": "按：此经脉适断，又染疫邪，大热不止，日晡时如见鬼神，狂言独语，此阳明病热入血室，仍宜和解少阳，兼以清热行血，使热从和解及鼻衄而解。", "12045": "城东南丁楼村，邑庠生。杜耀光之令郎，于仲春患疫，初得憎寒壮热，头痛身痛。某医作伤寒表证施治。用麻黄、桂枝、十神、葛根等汤，立求汗解，不止无汗，转见躁扰不宁，大渴谵语，思饮冷水，日哺更甚，某医技穷。耀光邀余诊治。诊得阳明胃脉洪大无力，肺脉数而且虚，作伤寒治，误也。此乃温疫邪热入于胃腑，如贼入室，此时此证，非用攻补解三者兼施不可，故用大承气，以攻邪热。加人参、当归，以补气血。因误服前药，脏腑已受其害，气足则邪自退，补气正所以攻邪。用金银花、玄参、连翘、甘草以解温疫，如此则邪有不退者乎？倘不如是，何异闭门击贼？耀光深以为然，九死一生，转危成安，后用平补之剂，渐获痊愈。噫！耀光能信余言，可谓余之子期也。", "12046": "梁堂村梁其材，年三十余。于四月间患疫，数治不愈，迁延十日，请余诊视时，见家人环绕哭泣。余诊得肾脉细弱无力，心脉甚虚，脾肺脉涩，知是阴虚血少，不能作汗。吴又可云：「养阴即是发汗。」用六味四物汤，略加生津液之味，服五帖，忽得战汗，身热已退，惟饮食不能多进，胃脘按之疼痛，乃表证虽解，里证未除也，用调胃承气汤一帖，下秽物碗许，干粪枣大者十余枚，数日平复。", "12047": "胡观察霖峰之夫人，年五十余，七月病疫，屡治未愈，危殆已极，邀余往诊时，送棺服已备五日，诸医俱各束手。余诊得肺胃脉隐然有力，心脉急数，问之不语，按胸腹间，似有疼痛状，大便六七日未解，午后潮热。吴又可云：「阳明实证也。」视彼药方，发表清热，杂然乱投。辗转详诊，据此脉证，确系温疫误治，变成结胸，非下不可，但下焦无病，若用芒硝恐伤下焦之血，用大承气汤，去芒硝，加洗肠胃清温化毒等味，煎成令先服一盅，不见动静，又服一盅，二时许，泻下秽物三次，极臭难闻。由此神志清爽，身热渐退，饮食能进。后改柴胡养荣汤出入加减，调理两月，方获痊愈。此证若泥老人不宜下之说，岂不殆哉？", "12048": "按：温疫误治结胸，非下不可；下后宜和解调理。此案见证的确，认脉明晰，用法有步骤，立方有变通，胆大心细。", "12049": "按：翟氏善于急证急攻，患疫后自作伤寒表证治，致谵语大渴，大便七日未解，再验胸腹，按之坚硬极痛。急用大承气汤，一日服三帖，日夜服四碗，至夜半下黏胶恶物，病势方衰。吴又可曾有数日之法，一日行之，因其毒甚，传变亦速，用药不得不紧的说法。此案即是一日数下佐证。翟氏攻下法可概括为：六脉洪大；胸腹满痛。大便闭结，大渴饮冷，或烦躁谵语。三者不必悉具，以脉与腹痛为重。", "12050": "邑西关庠生刘培棠之子，年三十余，四月患疫，请诊视，胃脉实而滞涩，心肺脉俱洪数。患者身目如金，知是土实肺燥，心火上炎，邪郁胃腑，因此发黄，投以茵陈汤，以攻阳明实邪，辰刻服下，午后泻下三便，宛如黑泥污水。至戌时，脉证均为稍减，次日照前方又服一帖，黄色虽无尽退，而神志清爽，饮食能进。后改柴胡养荣汤，服六帖自汗而愈。", "12051": "毗邻周华堂妻，年三十余，身孕五月，患疫。初得寒热往来，某医投以解表辛散之药，而病日剧，兼大便脓血，日夜二三十度，胎儿上冲心，思饮冰水，腹疼如锥刺，又请某医，以为痢疾，急于安胎，遂投十全大补、八珍、胶艾等汤，泄泻胎动，竟无宁刻。不得已迎余往治，诊得六脉同等洪大已极，知邪流入大肠，乃挟热下利证也。吴又可云：「古有悬钟之喻，梁腐而钟未有不落者。」更加某医发表温补，大剂连进，火上添油，能无坠胎之虞，非大下决无生理。此时，芒硝、大黄即是安胎良药，治乱能将也，用大承气汤加减，辰时服下，午时大便不解。又服一碗，至戌时泻下，如坏瓜烂肉者甚多。至夜渐能安枕，热去六七。《内经》云：「大毒治病，衰其半而止。」后改四物汤，加养阴退热清温化毒诸味，十日外，方得战汗而愈。子母两安，儿子己十余岁矣。某医生只知安胎，不知通因通用，有是证则投是药，智圆何碍行方。", "12052": "按：先生特别是对温疫论的攻下逐邪法体会尤深，方法灵活，即使是妊娠时疫，亦放胆用硝黄攻下。瘟疫本为急证，妊娠瘟疫尤为险候，古人有悬钟腐梁而钟未有不落之喻。翟氏抓住六脉洪大己极，腹痛如锥刺，急用承气攻下，非有胆有识，何敢遣硝、黄于孕妇？", "12053": "丁炳文，东郭外王堂村人，四月患疫。邀余往诊，六脉皆无，腹疼如锥刺，大泻倾盆，色如败血，神情如塑。余曰：「速备后事，此证决无生理。」彼不信余言，又请他医，竟指为霍乱，投藿香正气散，煎成未服，患者竟作古矣也。", "12054": "本邑西门内，有步清者，年近六旬，偶患疫证。愈后，每日潮热，饮食难进，强食呕吐，骨瘦如柴，危困于床，屡请医治，有云「噎膈」者。有云「反胃」者，杂药乱投，毫无效验。邀余诊治，脉细如丝，幸而有神。详察胸腹间，按之胃脘微疼。此乃疫病虽愈，燥粪结存胃脘故也。用调胃承气汤，内加蜂蜜60克。越日下燥粪十余枚，干黑极硬，诸症若失，不数日即平复矣。", "12055": "按：疫病愈后，燥粪结存，按之胃脘微疼；每日潮热，饮食难进，强食呕吐，脉虽细而有神，又其证也。故宜调胃承气汤润下燥粪而愈。", "12056": "边君静一，余厚友也。于三月间患大头瘟证。头面肿如瓜瓢，身热烦躁，饮食锐减，心中难受，至夜又剧。诸医皆云：「最高之处非风不到。」又云：「风胜者肿。」由此风药频进，火借风势，风助火威，危迫万状。请余诊断，寸脉洪数，关脉沉滑。乃温毒壅遏上焦，非下不可。大承气汤加犀角、黄连、栀子、龙胆草、石膏，煎成碗许，日午服下，夜间秽粪臭水泻三、四次。越日再诊，肿处略消，脉势大衰。后用普济消毒饮，服五帖二十余日，方获十全。", "12057": "余邻人朱学文之父，三月患大头瘟证。因某医误治，头面肿大如斗，下至胸腹，亦如抱瓮，神志恍惚，饮食不进。请余诊治，六脉如丝，证与脉违。又看服过药方，尽是除风之品，病重药误，逆证已现，未及用药遂殁。", "12058": "邑东关饭店，魏姓失其名。年近七旬，患疫。迎余诊治，六脉不鼓，四肢微凉，神志昏愦，形容枯槁，种种虚象。知老人气血俱亏，疫邪沉匿，膜原不能托送。遂用六味汤、达原饮加减，连服三剂，疫邪显露，微渴微热，脉稍洪滑。后纯用六味汤又服六剂，偶得战汗而解。此证倘作寻常疫证治法，吉凶未可知也。", "12059": "邑东北二十五里王楼村，李子贞之嫂，正月感疫。子贞亦颇知医，以为中风邪证。邀余时，已服祛风药三帖矣，日加沉重，头面如斗，肿处含无数水泡，挑破俱流清水，六脉洪数，按之有力。此妇禀赋甚厚，遂用普济消毒饮，加芒硝、大黄、犀角、羚羊角服一帖，大便解下三次，病不减轻，脉势不退。原方又加大黄24克，芒硝15克，又投一帖，大便泻下六七次，肿亦略消，脉势渐衰。照原方去大黄，芒硝又服两帖，肿消脉退，始获平复。", "12060": "邑西南阎王庙，李维栋之父，六十三岁，患疫甚重，身如被杖。迎余诊视，大喘不息，脉如鼎沸。余命速备后事，后遂殁。", "12061": "按：身如被杖，为疫毒侵袭血脉，瘀血凝滞，阻塞不通，血液流行不畅，故遍身疼痛如被杖一样。大喘不息，脉如鼎沸，为孤阳不能返本，故命速备后事。", "12062": "南郭外李庄村，李玄之母，年四十余，于七月患疫。邀余时，误服祛风药三四帖，头面胸腹两乳肿甚，阖家惊恐。余诊六脉沉滑有力，用大承气汤。", "12063": "按：六脉沉滑有力，疫毒内盛，大承气汤重剂连进，非有胆有识者，不敢为也。", "12064": "岁贡生步纶五之令郎燕初，于甲戌年三月患疫。初得寒热往来，周身疼痛，心胸满闷，饮食减少。某医谓伤寒，投发汗开胃之药，大热不止，烦躁不宁，夜难安枕。请余治疗，胃脉洪数，肾脉虚弱无力，知先天不足，津液枯稿，不能作汗。吴又可云「夺液无汗」正谓此也。余用六昧汤加清温化毒之品，投一帖稍轻，二剂服下，至夜半忽得战汗而愈。越六日，肾囊肿大如斗，又邀诊视，见囊光明，颜色紫红，热极疼甚。此因三阴亏损，湿热流注，结成囊痈。虽能痊愈，但非月余不能。用仙方活命饮，服三帖后热疼略减，惟肿仍甚，又服二剂，疮似出头，毒气外泄，乃佳兆也。五日疮溃，黄白脓甚多，每日早晚上红升丹两次，以膏药盖之。内服托里排脓之药，嘱以应禁戒者，燕初深信恪守，始终未变，将近两月，方获全功。", "12065": "按：胃脉洪数，肾脉虚弱无力，知是津液枯竭，不能作汗，见证何其明白。", "12066": "邑东关李兰之母，禀赋甚厚，年七十余。于四月染疫，初得六脉闭绝，四肢厥冷，已过膝肘，气喷如火，大渴思饮，操扰不宁，小便赤涩，大便闭结，唇红舌刺，真阳证也。余至时，某医用附子理中汤，业已煎成，尚未进口，请余诊断可服与否。余云：「内实真热，外观假寒，倘若服之，何异火上添油，抱薪救火？恐汝有终天之恨，悔之何及。」余知此证乃阳毒发厥。经曰：「热深厥亦深」，此之谓也。遂用大承气汤。", "12067": "煎服半碗，一时许，大便解下三次，厥回大半，脉现滑数。又煎服一碗，至夜解下五、六次，色似坏瓜，气极臭秽，渐渐舌苔亦退，热渴大减，险证皆无。后用柴胡养荣汤加生四物汤，五帖后，发鼻衄甚多，越二日，周身发出红斑极稠，调理三十余日，平复如常。", "12068": "邑西北十五里于庄村，教谕韩孝廉振东之孙，年十二，于三月染疫。泄泻甚重，所泻之物，如鱼脑豆汁，兼杂脓血，日夜二十余次，已十二日矣，每日饮冷水五六盅，全家俱知不起，不忍坐视。半月后，邀余诊治，以为尽人事而已。六脉细数劲硬，沉取有力，确系大肠胶闭证。细审气血，精神犹存，此作坏证，因误治大下，邪毒仍在故也。余用大承气汤加减。", "12069": "同邑吴君聘儒，体弱患病。某医用麦冬清补等药，已服过四剂，患者满面通红，口吐白沫，两手抓心，声言「内热如火」，躁扰不宁，苦欲冷饮，夜间益甚，危迫已极。请余往诊，六脉细数，重取不见，此乃阴极似阳之证，作阳证治误矣。余用张景岳左右归饮加减。伊父见热证又投热药，恐有不测，置之未服，仍请某医调治，诸症无不增加，伊父悔悟，遂踵余庐，再次诊毕，仍照前方。热药略加分两，因彼服凉药过多故也。此药煎成，令其冷服，即《内经》「用热远热」之意也。先服半碗，亦无多效，全剂服尽，狂躁稍定，诸症俱失，昏昏欲睡，至戌时饮食略进，转见生机。此方无大增损，服三帖后，病去八九，后改用平补之剂，调理旬余，诸恙全廖。", "12070": "余谓阳盛者，脉必洪大，至阳盛之极，而脉反伏匿。阳极似阴，此干之上九亢龙有悔也。阴盛者，脉必细微，至阴盛之极，而脉反躁疾。阴极似阳，此坤之上六龙战于野也。凡过极者，反兼胜已之化。", "12071": "蒋君选儒，吾挚友也。岁在摄提（寅年），设帐梁垣，嘉平（腊月）染疫旋里。请余诊治，痰声如锯，面似涂朱，汗雨淋漓，饮食锐减，六脉洪大无力，渴欲热饮，此是孤阳外越、阴阳脱离之证，险哉！又看服过药方，俱是清热化痰、养阴止渴之剂，隔靴搔痒，治法误事。余用桂附八味汤加减，令其煎成冷服。即《内经》「热因寒用」之谓。辰刻服下，至戌时，痰声略退，面红稍减。又投一帖，诸症若失。后改平补剂，服十余帖，渐痊愈。调理三月，步履如故。", "12072": "按：证似实而脉虚，知是假证，用桂附回阳是认证真处。", "12073": "邑人余廷贞之妻，因患肺病，体弱感寒。初得寒热往来，饮食减少，后加咳嗽短气，四肢无力，即往西医院调治。据西医云：此证乃是肺结核，业已到第二期，已成为险证。非注射药水数十针不可。徐君愿治，共射二、三十针，病仍如故。又请余治，诊肺胃二部脉，弦紧沉细，微带滑象。经云：「形寒饮冷则伤肺」。滑主有痰，非大补脾土以生肺金、兼固命门之火不可，能使金土有源，方可渐愈。用桂附八味汤加减，服二十余帖，始获痊愈。", "12074": "余友屯庄村魏兴治，年二十八。于腊月出外讨账，偶遇风雪，感受严寒，头疼身痛，冷似水浇。误服冯了性药酒两许，戌时服下，身冷倍增。又一时许，大汗如雨，衣被透湿，胸膈极疼，遂吐鲜血两三碗。从此饮食日减，咳嗽日甚，痨证成矣。时轻时重，后有声哑，卧床不起。招余诊视，神色已败，脉见屋漏。执余手泣曰：「此生已矣。」余虽爱之，莫能助也，越二日果殁。", "12075": "按：风雪严寒，辛辣烈性药酒杂至，搏击肺脏，致肺脏崩裂破离，血汗大下，形神已去，败脉己现，何生命之有乎！", "12076": "陈州东南胡桥村，有刘其生。患病三年，身瘦骨立，黑如生铁，每日吐痰约有碗余。迎余往诊，肾脉虚细无力，脾肺脉微缓，少有滑象。经曰：「胃为肾关，肾虚者，关不闭，痰饮泛上，呕吐不止。」经又云：「治病必求其本。」用景岳左右归饮加减，阴阳双补，乃纳气归肾，引龙归海之法。大剂煎服一帖，呕吐渐减，又投一帖，饮食大进，服之八剂，诸症若失。调理月余，始复原状。", "12077": "东郭外边继勋，初感寒甚重，未曾服药。月余后，咳嗽发喘短气，饮食减少。迎余诊治，肺脉沉迟，脾胃脉细弱，此因禀赋不足，中气不能送出寒邪，寒邪仍在肺经，久则变成肺劳，实难治疗。今虽不能速愈，倘肯服药，或可望好。治宜十全大补汤加减，服十帖痊愈。", "12078": "邑西南十五里王氏寨，王国安之妻，年三十余。产后体虚，午后恶寒，两颊发赤，饮食渐减，潮热自汗。请余往诊，肺脉微数，脾胃脉虚。乃寒化为热，金受火刑，恐肺痿将成矣，此症非服药数十剂不能愈，彼信任不疑。用大补脾土以生肺金，内加清金宁肺之味。五帖后，寒热稍退，喘呛如故。又服十帖，饮食大进，喘呛渐轻。原方出入加减，共服四十余帖，始收全功。经云「虚者补其母」，信哉。", "12079": "赵瑞亭，年十八岁，从余学医。家贫甚，终日苦读，余戒之不听，三年即能应世。又二年，在邢口村行医，患咳嗽，吐痰，短气，饮食日减。就诊于余，心脉微散，脾脉虚弱，少神。余谓少年见此脉，决非佳兆。此为习医、行医操劳过度，致伤心血。心火虚则不能生脾土，脾土虚则不能生肺金。三经俱虚，则心火上炎，肺金最怕火灼，是以咳嗽成焉。治宜子母俱补，使肺金有源，肾子不盗母资，有不愈者乎？方用子母两济汤，服十帖，略有转机。奈彼性急，欲求速效，又投别医，指为心火，用黄连泻心汤，遂渐加重，形体日削，精神日减，危困于床，不久告绝。", "12080": "按：家境贫寒，案读劳形，心脾肺俱虚；心血暗耗，心脉微散，故非佳兆。子母俱补，肺金有源，肾子不盗母资，故可有转机。别医泻其心火，心气更耗散不收，故形神日衰而告殁。", "12081": "邑北十八里陈寨村，余友夏殿三君。腊月赴汴返里，偶逢天变，北风大雪寒甚，彼恃健强，冒雪至家。从此每日咳嗽，少有寒热，不以为意。又月余，嗽略带血，寒热如疟，饮食减少。邀余诊治，肺脉紧数，脾胃微细。土不能生金，乃元气大虚之兆。非服药数十剂，温补脾胃，培养后天，使肺金有源，断难痊愈。伊以余言太过，乃更某医，某医不明经旨「虚者补之，寒者温之」之义。但见吐血，便指为血热妄行，遂投麦冬、丹皮、黄芩、桑皮、枇杷叶之类，服十余帖，吐血虽止而音哑矣。又见寒热如故，复用柴胡、黄芩、地骨皮、鳖甲、龟板之类，专务清热，由是大便洞泻，虚汗似雨，面如枯骨，青色绕口，危困于床。重邀余诊，肺脉散乱，脾脉已见雀啄，形色脉象，死证俱见，万无生理，越二日而殁。书此以为延医贻误者戒。", "12082": "按：风寒犯肺，延迟时日，脾胃受损，更不能长养肺金；元气大虚，温补后天脾胃为先。某医竟以苦寒折之，大败脾阳而洞泻，阳脱则虚汗似雨。面如枯骨，脉见散乱、雀啄，形神、脉象死候俱现，怎有生理。延医贻误者，应引以为戒。", "12083": "邑西北三十五里王庄村，王金山，年三十余，家贫劳甚。季秋出门作小贩，饮食不足，斯年十一月间，天气分外寒冽，口积月累，形寒伤肺，从此咳嗽吐痰，亦无甚痛苦。至腊月病势大作，冷热无时，吐痰如涌，饮食日减，头目眩晕，四肢懒动，自知不能支持，雇人送回。迎余诊治，脾胃二脉极细，肺脉劲硬，此壮年当忌之脉，余辞不治。伊母含泪告余曰：「吾寡居三十年，所盼者此儿。若有不测，阖家零散，老命转沟壑矣，望先生垂怜老妇孤苦，救我子命，不借倾资以报。」余闻惨然，勉开一方，先固先后两天，加以宁肺之药，嘱以服八帖后再诊。伊果如数服完，诸症均去大半。原方未改，又服十帖，饮食日增，诸症尽去，脉象精神俱复原状。始终共服药二十帖，不大加减。", "12084": "陶陵岗杨某性嗜酒，年三十余，多饮冷酒。酒性阳而体阴，热毒攻于上，寒湿留于下，面红气短，二目虚肿，心胸病满，足肿难移，小腹膨胀，小水赤涩，每日食面不过三、四两，如此两月余。迎余诊视，脾脉缓而无力，心脉虚细，乃湿伤脾土，酒散心气，子母不能相生之故。古人云：「万物隆盛，皆属于热」。又云：「诸症肿满，皆属于湿」。余用茯苓180克，黄连6克，栀子30克，白术30克，木通10克，滑石15克，黄柏10克。共服八帖，诸症若失。", "12085": "西郭内陈庄姜明远之内人。操劳过度，心肾不交，得游魂证，每夜不能闭目，交睫即游魂出舍。或操作女红，或务农田野，醒来劳苦不堪，通身是汗。由此饮食减少，形体日削，求神拜佛，觋巫并至，毫无功效。迎余往诊，心脉微数代散，肾脉虚细。此乃肾水不能上潮，心火不能下降，坎离不交，水火未济，古人云：「水升火降，须赖黄婆转运。」遂用二交汤加减治之，服一帖略有效验，二帖后病去二三。原方稍为变动，共服十帖，通宵熟睡，神志安宁，诸恙皆瘳。", "12086": "贺明三幼失怙恃，十五岁即应世理家，遗产又薄，老幼十余口，衣食窘甚。至三十岁，怔忡惊悸，恒如讼事未了，有人来捕之状，最怕见人，似痴似迷，低头言语喃喃，觋巫百治无效。请余诊治，心脉散乱，胆脉微细，脾脉沉滞。此乃操劳过度，惊恐伤胆，脾气郁结，幸脉有神，尚可治疗，非服药数十帖，难见功效。伊信而不疑，先服十帖而病不减，又服十帖，诸症稍轻。四十帖后，神志清爽，言语有序。伊欲备礼叩谢，余曰：「吾借汝坚信以成功，倘不浅信，即卢扁何能为哉？何谢之有？」", "12087": "邓圈村王凤山，年弱冠，患虚证二载余，服药罔效。就诊于余，面现红光，色燥暗淡，肾脉虚数，脾脉虚弱，少腹时疼，饮食大减，四肢困惫。余谓伊曰：「此症根深蒂固，难见速效，理当缓图。」用景岳右归饮，大补肾气，壮火以生脾土。经曰：「寒者温之」，「虚者补之」，又云「塞因塞用」。服十帖诸症少退，又服二十帖病去大半。共服七十帖，始获安全。倘若信不坚，中道而变，未有不归于败者也。", "12088": "按：素患虚证，脉证皆虚，根深蒂固。右归温补肾阳，兼益精血，纯补无泻所谓「扶阳以配阴」者此也。", "12089": "邑北朱寨村，朱某之子十余岁，禀赋不足，常咳嗽发闷。又于八月间随父农作，偶逢天变，北风大雨，感受寒邪，自此加重。三月后身皆浮肿，面色黄如橘皮，饮食大减，就诊余家。肺脉细涩，脾胃脉沉滑，乃寒痰结于胃脘之中，脾胃虚弱不能运化，土不能生金，因此气短食减。内经云「脾虚则肿」。以上诸症，皆是寒痰为害。但此痰非寻常之痰药可除，惟有吐之一法。遂用景岳先生参芦饮加减。", "12090": "水臌之为病，莫不由脾肺肾三经之亏。肾为水脏，肾虚者，邪水横逆泛滥，平地已成泽国。脾为水堤，脾虚则堤不固，何能防水患？肺为天地肃杀之令，虚则不能下降，膀胱因之不能化水。故水臌之证，十有九虚。经云：脉坚大者，邪盛也。脉涩者，气虚而不流利也。余治此证，所以多用金匮肾气汤，视证加减，治愈者颇多。至于攻伐之药，亦有时而用，只要认清脉实证实，直决水口，顺流而下，何尝不可，然禹功散、舟车丸，虽是夺命之药，此治百人中，不过三五人而已。余论是否，深望高明者正余之谬，幸甚。", "12091": "邑南十二里杨大庄，李清河之妻，年三十九岁，患水臌证，业已三月。迎余往诊，肺脉沉滑，胃脉沉滞，肝脉弦急。腹肿如抱瓮，腿肿似冬瓜。按之如泥，窝而不起。此证得之郁怒伤肝，木旺克土，土伤肺弱，因此肺气不能下降为膀胱。经云：「膀胱者，州都之官，津液藏焉，气化则能出矣。」今气不能化水，留于腹中而臌证成矣。治宜平肝补脾，渗湿攻水。方用", "12092": "邑北十二里寨，贾世道年三十余，腊月患水臌证，将近两月。迎余治疗，但见周身壅肿，肾囊肿如斗，腹皮欲裂，小便极涩，饮食减少，脾胃二脉虚细，肾脉劲弦。按病状脉象合论，二者俱在不治之例。余辞欲去，伊妻跪下涕泣告余曰：「吾家上有七旬老毋，下有三子，长者十二岁，次者八岁，小者在抱。家无隔宿之粮，栖于土室之中。倘吾夫去世，阖家零落矣。」余闻此言，忽动恻隐之心，谓伊曰：「此是水膨证，极难调理，至少服药需数十帖，或可望愈。」伊妻恳其堂兄，其堂兄慨然允诺曰：「请先生费心调治，至于药资，鄙人担任。」余用仲景十枣汤：", "12093": "本城内小西门街袁旭东先生之佃户，年三十岁。自乡赴县，七月初，天气炎热，路过菜园中，渴甚饮冷水三、四碗，路旁有大树一株，伊于树下睡熟。醒来觉腹胀难受，不甚在意，越旬日，目下如卧蚕，腹内有水声，饮食亦减。就诊于余，脾肺二脉沉滑有力，知系实证，治以攻邪为先，方用十枣汤加葶苈煎服，攻下水桶余，病去八九。又服半帖痊愈。", "12094": "按：病因积水，脉证俱实，故攻邪逐水遂愈，无需它治。", "12095": "邑内蔡隅首街，有张某者，年五十二岁。患水肿证，腹肿如盆，腿肿似腰，饮食难进，危迫已极，昼夜不能卧眠，将近三月。芫花、甘遂、大戟、商陆、大黄、葶苈、二丑等药，服过十余帖，愈服愈胀。请余诊视，脾肺肾三部脉皆濡细无力，幸而有神，尚可缓图，倘不多多服药，难保痊愈。患者闻多服药，面有难色，阖家劝勉，患者应允。余用金匮肾气汤少为加减，服五帖不见功效，患者有性急不愿服药意。余云：「再服五帖不效，另请高明。」伊果服五帖，饮食渐进，肿胀渐消。三十帖后，能出外行走，由此日轻一日，共服三十八帖，诸症痊愈。又诊其脉，仍嫌无力，余命再服金匮肾气丸二斤，以固根本，而免后患。患者执意不服。至来年三月，旧病复发迎余再治，脾肺肾三部脉更不如前，余坚辞不治，至四月果殁。", "12096": "按：腹腿肿甚，肾虚水泛，屡用峻药攻伐，非其治也，故其二脉濡细无力，翟氏以加减肾气汤，两补脾肾，利水消肿，病可日轻而告愈。奈无巩固治疗，再发者，本气更虚，则难治也。", "12097": "邑庠生王楚才之侄，年五十，患水臌证，家贫甚，就诊于余。肺脾肾三部脉，皆虚细无力，此因饥饱劳役亏损而成，非先攻后补不可。先用十枣汤攻水后，用肾气汤补虚，服二十帖渐获平复。逾年前证又发，复迎余治，病势脉状更不如前，辞不治。楚才苦求勉为之治，余想一方。十枣汤合肾气汤煮红枣令食，每日数次，泻水甚多，共食枣一斤余，诸症如失。", "12098": "东郭外农人边兴才，年三十余，患水臌证腹如抱瓮。就诊于余，肝脉弦数，脾脉虚弱，此证因郁怒伤肝，肝克脾土，脾土受伤，失其转运，肝失其疏泄，肝肾同源，肾气虚而不化水，于是水势壅留腹中，而臌证成矣。余用肾气汤加减，服六帖病去一半。伊信巫言，竟不服药，又月余，迎余再诊，辞不治，逾三日果殁。", "12099": "邑东五里前营村黄某，年二十三岁，患水臌证，两月有余。请余治疗，脾脉极细无力，此少年当忌之脉，恐非吉兆。看服过药方，尽是大攻大伐之剂，病势甚重，余辞不治。伊母泣诉曰：「吾夫去世，儿方周岁，我寡居二十余载，儿才成立，倘有不测，何以为生，祈先生怜念，勉书一方。」言罢涕泣不止，余见此情景，无可奈何，告伊母曰：「我非有回生金丹，但尽心而已。」遂用金匮肾气汤加减，服十帖病去六七，前后共服二十余剂，竟获全安。此证虽愈，想是此妇守节之报，余何敢居功。", "12100": "邑北李庄李子贞妻，年三十，患水臌证三月有余，就诊于余。肺脉浮数，脾胃脉缓滑，此证因脾胃受湿，肺脏受风，风湿交加，所以头面肿如瓢，四肢肚腹无一不肿。治宜利水祛风，遂用风湿两彻汤。", "12101": "按：肺脉浮数，肺脏受风。脾胃脉缓滑，脾胃湿滞。风湿交加，斯现是证。祛风利湿，风湿两彻，故能从速告愈。", "12102": "馨山按：痢疾之名，古无今有，古之肠癖、大瘕泻、大肠泻、小肠泻，即今之痢疾也。而今之痢疾，又分为红痢、白痢、休息痢、噤口痢、水谷痢、五色痢数种，总而言之，不外乎湿热之所致。然湿热之因，每于长夏之时，人食生冷瓜果，积久而生湿热，又受天地之暑邪，至秋而发。然痢疾之症，实内伤湿热，外感暑邪，相合而成者也。治痢疾者，初宜清热之剂，久宜补气补血之药，此皆普通之痢疾，普通之治法也。然痢疾亦有特别者，不生于秋夏，而偏生于冬春，夏秋人啖生冷致痢，而冬春饮食不节使然，莫谓夏秋有痢，而冬春无痢也。前人云：「无痰不生疟，无积不成痢」，岂不信然乎。至于痢疾治法，亦不可泥，间有特别者，如红白痢之热伤气血，似乎当下，噤口痢之热伤津液，休息痢之邪毒已尽，似乎当补，然红白痢脉症果虚，亦有当补者，休息痢、噤口痢，脉证果实，亦有当下者，治法岂可拘乎。至于五色痢之当下，水谷痢之当补，又不可不审也。行医者临证详视，视而后问，问而后诊，诊而后断，断而后药，不沾不脱，温凉补泻，因证而施。所谓医者意也，神而明之，存乎其人，岂不信然。", "12103": "余姨丈王某，年五十二岁。素有鸦片瘾，于四月患痢，初得寒热往来，大便脓血，昼夜二十余次，里极窘迫，腹内疼痛，某医以为烟后痢，正中病者之惑。遂用婴粟壳、诃子、肉蔻、龙骨涩大肠之类，一剂而痢止。反加心胸胀满，腹内痛甚，闻食则呕，大便重坠，渴燥已极。此时脾胃之脉沉滑有力，肺脉沉数，确系湿热、邪毒正盛，误投堵塞之药，古云「实其实而死者」即此类也。余用涤洗汤：", "12104": "本城小西门内，曹玉，年三十余，素有烟瘾。五月间患休息痢三日，以为烟后痢，遂破老烟枪取膏，用开水冲服6克，痢虽止而心腹胀满，呕吐，饮食不进，业已四日。迎余诊治，六脉微细无神，知是鸦片之毒，深入脏腑，真气已败，不可救药，辞而不治，越三日而殁，殁后周身皆青。书此以为有烟瘾患痢，急于塞补者戒。", "12105": "邑东朱岗有王世钦者，年逾知非。五月患痢，所下之物，如水中白沫，大便艰难，少腹疼痛，如刀割肠，每日夜二、三十次，服某医药无效。迎余诊治，胃脉浮数有力，浮则主风，数则主热，此乃胃经风热传于大肠，非寻常痢也。遂用羌活除风汤早晨服下，至晚间白沫减去，腹痛如故，原方加入月石15克，以涤肠胃秽腻，夜间泻下秽物极多，遂获平复。", "12106": "按：胃脉浮数有力，大便白沫而艰难，脉证俱见风邪之兆，用羌活除风汤疏风散热，再服加入月石以涤肠胃秽腻之物甚妙。", "12107": "南郭外八卦亭，崔振铎之父，年六十有二，于四月间患痢。所下之物，形同败血，少有白脓，昼夜十余次，腹痛重坠，每日饮食，谨可养命，骨瘦如柴。五月间邀余疗治，脾肾两脉极细，此先后两天将败，所下之物乃脏腑脂膏。盖此症乃延误所致，辞不能理，后越十日而殁。", "12108": "邑内廪贡生周廉卿，平生善饮酒，年五十余。于四月患痢，大便鲜血，下坠腹痛，每日夜三十余次，饮食大减，邀余诊治。胃脉洪大有力，肺脉洪数，此因酒湿生热，又感酷暑，血得热妄行，故为红痢。治宜凉血逐湿之药，方用：", "12109": "沙土岗楚姓妇，年近花甲。于大怒后，二月患痢，初病左脇大痛，饮食少进，所下尽是鲜血，寒热口苦，渴欲冷饮，每日夜五、六次，每次下血约盅余。某医以为红痢，用治痢等药，三服无效。请余诊疗，肝脉弦数，脾脉细弱，此因怒气伤肝，木旺克土之故。经曰：「肝藏血」。怒则肝叶开张，血不能藏，脾不能统，血流入大肠，大肠原非藏血之处，顺流而下，必然之势也。治宜平肝为本，健脾为标。方用：", "12110": "按：本案患者，病于大怒之后，诊得肝脉弦数，脾脉微弱，木克土证甚明，方以归芍为君，柔肝养肝，柴胡青皮为臣，疏调肝气，诸药重用可谓得法矣。", "12111": "西关马有才之女，八岁，三月患痢，大便白脓，下坠腹痛。某医用槟榔芍药汤不效，迁延月余，始邀余治，两尺脉细弱无力，脾脉更虚，此因中焦有寒不能消化，五谷尽化为白脓而下，故为白痢。治宜温补下焦元气以健脾土。余用右归饮加减，共服七帖，诸症痊愈。", "12112": "按：两尺脉细弱无力，脾脉更虚，下为白脓，知是脾肾阳虚，寒邪作祟，急用温补兼以助阳之品施治，何其通达切当。", "12113": "邑人赵文祥，年过不惑。七月患痢，红白并下，腹痛非常，寒热如疟，渴思冷饮，每日夜三、四十度，如此半月，几无宁刻。迎余诊治，肺脉数而有力，脾胃脉缓而滞，此系瘟痢，当通因通用治法，遂用槟榔芍药汤加减，水煎服。二时许泻下乌泥色便甚多，明日病去四五，共服二帖而愈。", "12114": "按：肺脉数而有力，脾胃脉缓而沉滞，乃胃肠中有积垢不去，郁而化热，热邪上逆故尔。积垢不除，其病难廖，虽痢下，必用通因通用之法方可取效，舍此则不能倾其孽巢，遂遣大黄、枳实、月石之品，以荡涤积垢，二剂而愈，足资效法。", "12115": "北门内杨姓妇人，年七旬，禀赋甚厚。六月患痢一月未廖，某医用十全八珍等汤，服十帖不愈。清余诊治，六脉有力有神，年虽老确属实证，如贼在室，理应驱逐，用大承气汤一帖，泻下燥粪如核桃大五、六枚，饮食大进，不治痢而痢自止。", "12116": "王风山，西南苏木岗人。八月患痢，昼轻夜重，便时大肠脱出，小腹奇疼，冷汗如雨，面色晦暗，迎余诊治。六脉细弱，大虚之证，幸王某壮年可治。余创一方，曰补气固肠汤：", "12117": "馨山按：天下患病最速者，中风而外，厥惟霍乱。夫霍乱一证，乃风寒暑湿饮食之邪，糅莒杂投，挥霍变乱，吐泻交作，得病于须臾之间，而人之生死存亡系焉，甚可畏也。治此症者，古人用磁锋刮痧，今人以针代之。盖上吐下泻，药不能入口，非针不可。医云：「一针二灸三用药」。惟霍乱更得先用针以止呕吐，后用药以止泄泻，此一定治法手续，而不容或紊也。要知霍乱之病有三种焉，曰湿；曰干，曰温毒。能吐泻者为湿霍乱，不能吐泻者为干霍乱，亦称绞肠痧。湿则有暑邪，干则有寒邪，暑则利湿，寒则温中，此藿香正气散、附子理中汤，治干湿霍乱之良方也。至于温毒霍乱，辛苦劳力之人，肾水受伤，津液不足，内有蕴热又加六淫外感，得病如迅雷烈风，猝不及防，愈者甚少。民国七年秋，吾杞温毒霍乱流行，多系粗人，当时用针药治愈者，十分之二三，于此见温毒霍乱之不易治也。总之，霍乱病症先针后脉，针而不愈，参之以脉，脉实则泻，脉虚则补，如此调治，对于霍乱一门，庶乎不误矣。", "12118": "余友蒋君王如之令正，患霍乱。招余诊视，六脉欲绝，冷汗似雨，四肢如冰，满面浮红，声音已哑，大渴思饮，看服过方药，皆止渴清热之味，吁！误也。此乃毒邪已尽，不知温补，变成元阳失散、真火飞越之证。倘再不以引火归源、纳气归肾之法，决无生理。即用参耆桂附汤：", "12119": "按：夫霍乱之为病，多骤然发作，呕吐下利，倾刻间呈挥霍撩乱之状，故名霍乱。《灵枢？五乱篇》：「清气在阴，浊气在阳，营气顺脉，卫气逆行，清浊相干，乱于肠胃，则为霍乱。」霍乱吐利后，伤阴亦亡阳，是案乃阴竭，元阳浮越于外，与《伤寒论》338条之证治颇相似。翟氏洞悉毫厘，遂投参耆桂附纳气回阳之品，二剂而愈，足见其学术造诣之深矣。", "12120": "北郭外童庄童姓小儿，年八岁，患霍乱。余至时脉见屋漏，二目直视，口张不合。出门十余步，儿竟呜呼矣。", "12121": "童庄樊姓妇，患霍乱。迎余疗治，入其室见停棺三口，俱系霍乱病死，令人寒心。诊得妇人之脉细劲有力，知是瘟毒蕴藏，用景岳刮痧法，将前后背心刮十余次，遂出许多紫泡黑点，皆用针挑破，流出黑血。又针足三里、内关两穴，服解毒活血汤三帖而痊愈。", "12122": "邑增生李蓬仙先生，于七月患霍乱，上吐下泻，滴水不能入口，腹内疼痛非常。邀余诊治，六脉沉迟，内有阴寒，吐泻不能服药，先针尺泽穴放去毒血，次针三里穴调阴阳，再针中脘穴，泻止吐停。用霍香正气散加减，一帖遂愈。", "12123": "吾杞典史任照恩先生，八月间患霍乱。邀余诊视，只见满面灰黄，指甲皆清，四肢抽搐，上吐下泻，腹疼欲绝，六脉按至附骨无有，真逆症也，纵有仓公卢扁无能为矣。去后遂殁。", "12124": "东郭外史庄李其兴之妇，年四十余。偶患霍乱，诊得六脉细弱，幸尚有神，邪毒已尽，元气不复，无须用针，又见室内停棺四口，问系何人，言是父子四人，皆患霍乱而死者。余知此妇操劳过度，恸伤心血，宜用参术枣仁汤。", "12125": "陶凌岗杨某，于八月初夜间患霍乱。天明请余疗治，但见冷汗如雨，四肢抽搐，精神昏愦，声音已哑，六脉微细，幸而未绝，此因邪尽正虚，非大补回阳不可。伊父曰：「倘补住邪气如何？」余曰：「脉现微细，显然无邪，抽筋音哑，乃气虚血亏，不能荣养经络，现存一点元气，若再不补元气，已绝无可为矣。」治以参耆桂附汤。", "12126": "四科柳村李邦兴之孙媳，患干霍乱。欲吐不能，欲泻不得，绞肠疼痛，面白唇青，冷汗如雨，坐卧不安。请余诊时，六脉闭绝，几次发昏，余命急炒大盐60克，开水冲服，饮半碗遂大吐大泻。又针尺泽、委中穴，放去恶血，病势少停。用藿香正气散加减：", "12127": "唐寨袁某，年三十余，八月患霍乱。邀余诊治，六脉洪大，吐泻交作，绞肠疼痛，两腿抽搐，指甲发青，瘟毒正盛。先针尺泽、委中穴，放出毒血，次针足三里、内关、中脘、昆仑、承山各穴，内服解毒活血汤。一帖见效，二帖痊愈。", "12128": "邑北柿园村李文祥，二十一岁，秋季患霍乱，三日未愈。迎余往治，见患者身带二十余针，某医云：「须隔一夜，方可起针」。患者呕吐泄泻不止，腹疼如故，而脾脉虚细，肝肾脉濡弱，此邪尽正虚，补犹恐不及，何可再针。余将针概为起去，用十全大补汤三服而瘳。夫针用以杀毒，毒尽当止，隔夜起针，庸医惑众，令人费解。", "12129": "余表侄年六岁，于五月间患霍乱。吐泻二日不止，脉皆细小，幸喜有神，面无败色，此时气血双亏，先针足三里、中脘二穴，俱行补法，复针内关穴，吐泻稍止。用参苓桂附汤：", "12130": "西堤外杨拔贡庄杨某，年五十余，六月患霍乱，迎余时亦已三日。二目天吊，角弓反张，冷汗淫淫，面色如土，唇青似靛，六脉细濡，虚证俱现，众医纷纷，有云「折背风」者，有云「看天风」者，有云「吊眼风」者，有云「白眼翻」者，此等鄙理之言，令人可笑，不知足太阳之脉，起于目内眦，终于足小趾，行背后，吐泻太过，气血少而不能养筋，令人反弓上视。据此确系虚证无疑，遂用十全大补汤加减，连服二帖，眼不吊，背不反。更进二帖，脉复元，冷汗收矣。四帖痊愈，若作风治，死生尚无可定也。", "12131": "邑北赵寨黄姓，七月初患霍乱，三日未愈。迎余治时，吐泻已止，惟虚汗淫淫，精神恍惚，四肢冰冷，饮食不进，六脉虚细，此因吐泻太甚，元气大伤，非补不可，遂用参苓桂附汤加减。", "12132": "务岗村务姓妇，年七十余，六月患霍乱。迎余治时，泻止而吐不停，胃脉极细，此因邪去正虚，火性炎上，所以呕吐不止，饮食不进，命如游丝。又看某医之药，尽是半夏、砂仁、紫豆蔻、陈皮之类，意在降气，不知气足者降下，气虚者泛上。古人云：「寒就湿，火就燥，自然之理也。」遂用参苓桂附汤：", "12133": "西肥寨有秦风山者，以事赴县，正走间，即云腹痛，晕倒在地。请余往诊，见面唇极青，四肢冷过时膝，六脉皆无，又无家人在侧，吉凶无人作主，余辞欲去。众人曰：「医者济人之急，救人之危者也，倘治不愈，以后有事我大家均愿作证。」余只得从众之请，先针委中、尺泽，尽放出毒血，又针十宣穴，皆令出血，复针人中、内关、中脘、承山、关元、昆仑诸穴，鼻内又吹红灵丹，遂将雷公散15克灌下。半时许，病者遂能呻吟，次能言，又待二时，竟获痊愈。由此看来，急病针法必不可少也。", "12134": "余毗邻冯泽臣，于八月间患喉证。请余诊治时已六、七日，六脉洪数，温毒正盛，咽关下有一核大如枣许，时时吊眼，喉内几乎肿闭，再三参想，喉内结核必是喉痈，若不用刀刺破，放出脓血，断无生理。当时与患者言明，用小尖刀刺核上十余下，即吐出恶血若有盅余，不多时见效，即能饮食，后用清温化毒三帖痊愈。", "12135": "泽臣病愈后二日，其妻又患喉证，初觉形势大恶，身如被杖，寒热如疟，非常疼痛，饮食锐减，日哺更甚。迎余诊治，六脉洪数浮沉有力，发闷极重，余曰：「此证感邪太深，内藏红痧之毒，最难透出。」遂用清肺汤，两帖病情稍轻，又两帖红痧透出，喉疼略减，原方又服三帖。每日午后发热，改用调胃承气汤，大便泻下滞枯秽物极多，诸症痊愈。后月余头发、皮肤均脱，危乎幸也。", "12136": "按：《素问？阴阳别论篇》：「一阴一阳结谓之喉痹」。本案乃湿热疫毒，纵贯三阳，故见「身如被杖，寒热如疟」的太阳少阳证，以及「饮食锐减，日晡更甚」之阳明证。治以清热解毒透表兼攻里实之法而收功，足见翟氏技艺高明矣。古人云：「圣人百虑，终有一失。方翟氏此案诊得「六脉洪数浮沉有力」，似欠妥当，证之于临床脉既浮不应沉，即沉不应浮，若作浮取沉取有力解，亦不甚通，是千虑之一失也。", "12137": "邑南阁老庄石某，年七十余，染白喉十日外。迎余诊治，肾脉虚弱，中取不见，肺脉虚极而数，此乃肺受疫邪，肾水又亏，毒气不能传送，所以缠绵不已。肾为子，肺为母，母受人辱，子想救而不能。试看患者，口干无津，舌生芒刺，肾水不能上潮以救肺，即子不能救母之明验也。余用子母两济汤：", "12138": "本邑文孝廉胡雍甫先生，春月阖家染温毒喉症，独二公子百森甚重，约余诊时己六、七日矣。诊得六脉细微无力，病证确系疫喉，因某医用凉药太过，阳变为阴，不明《内经》中病即止治法，所以致此。此时不敢再用凉药，非格外治法不可。遂用桂附汤加减，煎成冷服，因满喉皆烂，桂附味辣，服之甚疼。后著一人用手按其头部，嘱令勉强饮咽。服完头煎，病无增减，再服不甚疼，二剂服尽，喉内略轻，后去桂附又服三帖，方获十全。", "12139": "按：温毒喉证属于温热疫毒所致，六脉细微无力乃是真阳衰，证见满喉皆烂乃是虚火假热。翟氏剖析于似疑之间，把握症结之所在，舍证从脉，投以桂附汤加减治之获效，足证其医术高人一著矣。", "12140": "本城内李金镇，于四月间，阖家均患白喉。金镇有两女，大者十岁，次者岁余，同时而病。小者不甚在意，及已剧乃迎余治。时败证俱见，辞不治，次日而殁。大者天性执拗，死不尝药，病至五日，夜间鼻孔忽流鲜血，约有半碗，自觉不了，未晓即邀余往，及诊六脉皆无，痰声如锯，天庭黑暗，不可救药，当日而殁。金镇之弟金镜，禀赋极薄，亦病白喉，鉴侄女日前车覆，初得即为诊治，用养阴清肺汤加减，一日两剂，二日痊愈。又二日，金镇之母年六十余亦病，白喉甚重，寒热如疟，周身骨节酸疼，昏不知人，全家惊恐，急备后事。余诊脉尚有神，亦用养阴清肺汤，四帖痊愈。", "12141": "北门内李姓老妇，患白喉。延余诊治，肺胃脉洪大有力，年虽老病属有余。用养阴清肺汤，加大黄15克，连翘12克。水煎服一帖，大便泻下二次，满喉白膜已退，又服养阴清肺汤三帖而愈。", "12142": "邑南关张某，女方九龄，七月间，染白喉五日。迎余诊治，满喉皆白，呛食声哑，幸脉有神，生机或在。于是余用养阴清肺汤，守定不移，每日二帖，两天后病势减半。又服二帖，白退能食，声已不哑。独大便燥且难，又服小承气汤一帖，方收全功。", "12143": "邑东北店有朱明伦者，年二十余，患喉证。就余治时，咽痛发闷，饮食难进，午后潮热，肺胃二脉沉数有力，此系温毒喉症，非下不可。用调胃承气汤，一服而愈。即：", "12144": "按：是案系温毒证，证见饮食难进，午后潮热，肺胃二脉沉数有力，知是温热之毒伤及津液，阳明燥实，故服调胃承气汤一剂而愈，真谓妙手回春也。", "12145": "彭庄宗德全女，八月间，染白喉甚重。五日就诊于余，满喉皆白，二目天吊，湿汗淫淫，痰声似锯，六脉微细，余辞。伊父母恳求甚切，无奈，勉为先针十宣穴，又针尺泽穴，均令出血，以泻肺经温毒。内服养阴清肺汤，加大黄15克，芒硝10克，犀角6克，黄连6克。服一帖，大便泻下臭秽极多，由此稍轻。原方去芒硝、大黄，又服三帖痊愈。养阴清肺汤方见前。", "12146": "腹痛之证，有虚痛，有实痛，有内伤而痛，有外感而痛，证虽不一，不外虚实，实者易治，虚者难医，此尽人而知也。然此外有因邪祟而痛者；有延绵终年累月，时疼时止者；有发于仓猝，一疼即毙者；有因气滞而疼者；有因血瘀而致痛者。种种不一，无不由于内伤外感之所致。余行医四十年来，惟治腹疼，所遵书并无一定，皆审其病源，因势而调治之。如内伤七情虚也，治宜补中带调，外感六淫实也，治宜去邪固本；至于为邪所祟，外邪乘虚而入也，治宜逐邪，有多年不愈者，虚中挟实，攻补兼施；气血郁结者，确系实证，开瘀行滞，若仓猝暴发，药所不能及，非是阴阳闭绝，即属性阴阳暴脱，此系天命之安排，良医无如何者也。总之，腹疼诸症，或外感，或内伤，因虚因实，诊脉用药，罔不即廖。可见行医一道，当使一团活泼之气，常存于胸中，能如此，则终身运用无穷矣。", "12147": "邑北十二里寨贾某，年三十余，在田耕作，偶经大雨，身冷衣薄，受寒腹疼。初不为意，日久重甚，饮食渐减，面黄肌瘦，三月未愈，始迎余治疗。六脉浮中沉皆无，推筋著骨，指下劲硬，似有若无，知是沉寒痼疾，非大热药不可。遂用祛寒温里汤，服一帖减半，二帖痊愈。", "12148": "按：《素问？举痛论篇》云：「寒气入经而稽迟，泣而不行，客于脉外则血少，客于脉中则气不通，故卒然而痛。」又云：「寒气客于肠胃之间，膜原之下，血不得散，小络急引故痛。」是案因冒雨受寒腹痛，久之成「沉寒痼疾」。翟氏诊脉真切，遣药处方精当，故投药而病廖矣。", "12149": "官林寨村刘开业者，年三十余，患腹疼证二年余，百治无效。请余诊疗，面黄肌瘦，腹大如盆。诊其脉，乱无统绪，古书云：「乱无统绪者，虫积也。」彼云：「饥时疼甚，饱时略减。」此虫积无疑也。余用杀虫汤，辰时服下，午时腹疼更甚，余命速服二煎，至戌时，大便解下蛔虫近千条，腹痛消去七八分。隔日又投一剂，又下百余条，服第三剂虫尽无也。后服八珍汤，调理脾胃，月余始获平复，方开于后。", "12150": "本城宋庆云之母，年六十余，素有胃气疼疾，每犯疼痛几死，二十年来无药不尝，终不除根。迎余往诊，六脉参差，又见唇现白点，间伊饥时疼否？答曰「饥时疼甚」，始知确系虫疼。用雷丸扫虫汤，一帖服下，至夜半疼痛略轻，天未晓伊子来告，言大便二次，泻下红虫尺余者共六条，其病如失。", "12151": "南郭外有朱六合者，年二十五岁，患少腹疼证，疼时四肢厥逆，冷汗如雨，唇口皆青，病半载，服药不效。邀余诊治，肝肾二部脉极虚细，肾主少腹，肾虚不能养肝，肝亏则多燥，燥则暴怒，疼痛生焉。乙癸同源，肝肾同治，宜用母子两济汤：", "12152": "按：少腹痛者，多属于厥阴肝经之病；肝肾同源，肝为肾之子，肾为肝之母，在生理上，肾水盛则能涵养肝木，肝气盛则可以抑制脾土，使其不至于克伐肾水，在病理上母病可以及子，子病可以窃母气。是案患者，由于肾水亏不能涵养肝木，使肝脏暴燥，从而失去条达柔和之性，其气妄行，故其经脉所络之少腹痛。翟氏用子母两济汤，滋水以扬木，令肝木条达，以治其病源，故不治疼而疼自止。", "12153": "邑西门内李王松，年八十二岁，患腹痛十余日，呕吐不止。延余诊治，肝脉弦紧，乃木克土之证。况肝性最急，急则易于作痛，能制肝木者肺金也，补肺以平肝木，则腹自不疼矣。方用百合补肺汤：", "12154": "西关王其良，年三十余，五月患腹痛。请余时病已半月，调气止痛疏肝之剂，服十余帖均无功效。余诊脾胃两脉，浮中不见，惟重按至筋骨沉滞有力，知是胸膈停食之故。更有可证，见食发呕，疼处拒按。遂用六神汤加减：", "12155": "坡吴村吴姓业农，其子四岁，患腹疼。每发必先潮热，吐痰不止，脾胃脉沉滑，此是湿痰郁结所致。用瓜蒂散加减：", "12156": "按：脾胃脉沉滑，乃湿痰结于内无疑，涎郁气机不畅故腹痛。湿邪郁而作热，故见潮热。治用瓜蒂散加味涌吐以去其病源，甚妙。后用八珍汤以扶其正，甚妥。", "12157": "西关张自立之妻，年五十余，患腹痛，每疼时腹内气上下奔响如雷鸣。迎余诊治，六脉和平，无药可用，辞而不治。患者曰：「我若无病，疼自何来？」余细揣其故，忆本草云：「丹参一味能治腹疼如雷鸣。告伊曰：「有丹参一味，能治汝病，愿试之否？」伊曰：「愿试」。遂用丹参240克，煎成两碗，一夜服尽，疼已稍减，腹鸣已去。又连服四帖，其病霍然而愈。", "12158": "官刘寨刘某之妻，年二十余，患少腹疼痛，寒热往来，属治不愈。迎余诊治，肝脉弦急，脾脉滞涩，此系气郁血滞之故。遂用归附调气汤：", "12159": "南门内史兴春，年三十余，患腹痛证，每日午后必犯，痛苦万状，呕吐酸水。诊其脉，太阴脾脉郁滞，确系实证。用枳实厚朴汤，加大黄15克，服一帖无效，又加焦山楂、神曲各15克，服下腹内响如雷鸣，移时泻下乌粪似泥，内有燥粪三枚，破开似血类，不知何日所食停留肠胃之间，今得药脱然而下，病证若失。", "12160": "邑东台屯村蒋某，年将弱冠，患腹痛证，时痛时止，痛时手足皆青，冷汗淫淫，呼天喊地，求死不得。诊其脉知系肝气郁结，木不条达。遂用小柴胡汤：", "12161": "城西南门内王凤山，年近花甲，腊月羁旋外方，路受风寒，冷热腹痛，饮食锐减，小便艰涩。众医皆谓热传膀胱，用利水止痛之药，服六七帖俱与病左。邀余诊治，肾脉沉细无力，命脉极虚，此系老人肾虚受寒之故。肾与膀胱为表里，肾经受寒则膀胱之津液不能化气，以致小便艰难而腹亦疼。余用金匮肾气汤加减，熟地24克，山药15克，山萸肉12克，茯苓12克，泽泻10克，丹皮10克，川牛膝10克，巴戟天12克，破故纸12克，丁香3克，油桂10克，炮姜10克，附子6克，炙甘草6克。水煎服，三帖痊愈。", "12162": "西郭外陈庄有张克明者，年五旬余，患少腹疼证，寒热并作，四肢厥逆，小便赤涩，痛苦万分。某医用行气散寒之药，三剂不效，更加渴思饮水，大肠脱肛，日夜哭泣，后事已备。迎余往诊，两尺脉洪滑有力，此系湿热壅遏下焦之故，若使湿热一行，病当霍然。遂用清肠汤一帖，晚间服下，夜半大便泻下两次，内有脓血甚多，病去大半，又改清湿利热解毒之剂，服四帖渐次痊愈。", "12163": "南马庄马明三先生，年逾不惑，舌耕为业。孟秋患右肋疼痛，服药少效，至中秋肌肤锐减，阖家惶恐。迎余诊治，脾脉涩而中实，《濒湖脉学》云：「涩主宿血。」疼不移处，定是病血作祟，遂用：", "12164": "邑南聂王村刘某妇，年二十余，八月间患腹痛，痛时呕吐不止，渴思饮冷，业己数月，服药罔验。延余往诊，胃脉洪大有力，余脉和平，经曰：「火胜则痛，此因胃中积热，火炎土燥之故。用大承气汤加减：", "12165": "按：胃脉洪大有力，痛时呕吐不止，乃胃家实无疑。服大承气汤，使胃气下行，塞者通，闭者畅，实热去，积滞除，不治痛则痛自廖。", "12166": "古云：「宁治十男子，不治一妇人，宁治十妇人，不治一婴儿」。甚言小儿之病不易治也。因小儿脉不可凭，问不可问，一见生人，啼哭不止，闻之一道无可用矣。惟望之一道可用，乘小儿不哭，看气血之刚柔，神情之胜馁，禀赋之厚薄。再察天时之寒温，时证之有无。问其父母，得病新久，何时轻重，寒热多寡，乳食何如，再参以三关之经纹，详推细看，与彼所言合否。凭我阅历，运用在心，大概小儿之病无大实者，不可妄攻。因小儿初生，如二月萌芽，怕经风寒暴日，保护尚虑不及，何能任其克伐！娇嫩脏腑，果铁石乎。常见今之医家，一见小儿之病，不曰食积，便云惊吓，竟为幼科通套，如此误治，岂不终归于败。余治小儿独遵《幼幼集成》一书，可为幼科之慈航，济世之宝筏。余临证四十寒暑，见误治者极多，不觉情动于中，为之辩论数案。知我者必能亦宥我也。", "12167": "馨山按：今之行医者，皆曰大人病易治，小儿病难理。以大人气血病多实，小儿气血恒虚，大人病能望闻问切，小儿惟三关虎口，所以古今相传「能治十男子，不治一妇人，能治十妇人，不治一婴儿」。噫！此世之行医者，通例语也，而抑知不然，天下千病万状，不外内伤七情，外感六淫。以内伤外感相较，则外感为客邪易治，内伤为主邪难医。小儿之性情无善恶，故知简单，饮食以外，毫无他求，不过嬉戏液耍而已。无七情之病，其所病者，皆风寒暑湿燥火之六淫也。至若婴儿赤子，生不满岁，虽脏腑娇嫩，而乳食不缺，寒温得当，六淫亦不易侵。偶尔侵之，则外来之邪，较大人之内伤为治易。然而初生之婴，赤游、胎毒、鹅口、天花、痘疹者多。果能初生时，用药以去胎毒，则百病不生。特后人不知用，以致小儿多疾，惜哉。况望闻问切，知脉之浮沉迟数，病之寒热虚实，治大小病固不可少，治小儿病更不可离，何则？小儿脏腑与大人同，脏腑同而治病亦同。病同而脉亦同，脉同而望闻问切不得分也。而或者曰：小儿未过周岁者，可以不切脉。吁！此不通之论也。要知脉生于气血，气血生于脏腑，大人有脏腑，小儿独无脏腑乎！既有脏腑，则切脉一层更为要端。不过小儿之脉，则一指定三关。再望其颜色，闻其声音，问其父母，或强或弱，或虚或实，然后用药，未有不愈者。若过此以往，小儿之脏腑渐强，气血渐旺，此时人事不接于世，浮沉七情毫无，焉有内伤！无内伤气血何虚！即有外感，随手奏效。由此视之，小儿之病与大人之病，何虚何实？治小儿之证与大人之病，孰难孰易？当必有辨之者矣。", "12168": "煎成徐徐饮下，一日夜共服五六酒杯，越日病状减轻，又投一帖，气血充足，乳食大进。古云「治小儿如哑科」。只因脉不可凭，又无可问，愚父愚母，妄言病源，如同呆子说梦。医者无所适从，再无阅历，捕风捉影，虚实颠倒，婴儿之命，岂可问乎！", "12169": "南黄义岗黄文祥之子，年方岁佘，患肿病三月，面黄身肿，饮食仅可养命。消食消肿之药，服二十余帖皆无效。迎余诊疗，小儿脉如悬丝，声音低馁。此乃先天薄弱，非本实症，又服克伐药太多，所以重上加重。若再不改用温补，速收散失之元气，决无生机，余用十全大补汤加减治之。服两帖稍效，又服二帖肿渐消，饮食加增，共服十余帖，月余气血红和，肌肉复生，由是方获痊愈。古云「病伤可疗，药伤难医」，信矣。", "12170": "按：面黄身肿，若无实证可及者，可按虚证论治。不可一见肿证，陡用消散药。本例诊为虚证，其据有二，脉细、声低、面黄一也，服消药不效二也，故改用温补剂取效。案中以服消肿药不效为镜，足见问诊之重要。", "12171": "邑北李庄李玉林女，三岁余。于二月间随母探亲，偶受大寒，由此得病。寒热往来，腹疼咳嗽，吐痰日多，至五月肉脱骨立，卧床不起，饮食大减，服某医药无效，迎余往诊。六脉沉紧，重取微滑，此乃大寒积于肠胃，非温中散寒元气何从而复。余用桂附汤：", "12172": "按：「大寒积于肠胃，非温中散寒则元气何从而复」，即《内经》「寒者热之」之法。元气之本在肾，其源在脾，故舍温补脾肾则元气难复。翟氏从脉沉紧著眼，诊为大寒证，这与《金匮要略》寒疝病的「脉沉紧」同义。", "12173": "马南庄王姓，家甚贫，其子近三岁，终日衣不当寒，食不充饥。初病时发寒热，四肢懒惰，渐至腹大疼痛。迎余诊治，六脉沉而有力，浮取不见，外虚而内实，即大实有羸状也。余用补中消积汤：", "12174": "高阳周凤书之子，三岁余，与他儿戏耍，木棍误触头面，破皮出血甚多。六七日后，渐觉口噤，言语赛涩。又二日，两手握固而难伸，角弓反张，饮食难进。邀余往治，六脉浮紧，此为破伤风也。余曰：「此证最为凶险，十中不过愈其四五。」周曰：「此证虽凶，情属父子，人事不忍不尽。乞先生念余年四十余，惟有此子，万一痊愈，没齿难忘。」怜其恳切，遂制一方，名曰逐风丹。", "12175": "王性初，邑北王庄人。其子三岁时，患泄泻症，每日夜五、六次，自二月至八月不愈，寒热药服过数十帖，均不效。迎余往诊。脾脉滑数，它脉和平，此证因脾有湿痰积热作泄。古云：「五泄皆属于湿」，又云：「火泻者肠鸣」。问儿之父母，果然。遂用化痰清热汤，连服二帖，病去六七，又服二帖痊愈。", "12176": "按：《医宗必读》提出治泻有九法，即淡渗、升提、清凉、疏利、甘缓、燥脾、酸收、温肾、固涩。本例是清凉与燥脾两法的合用。惟诊为湿痰积热作泄，仅凭脾脉滑数理由似欠不足，以药测证，当有泻而肠鸣，大便不爽，粪黄而臭，舌苔黄腻等。", "12177": "朱本良女，于十一岁时，患疟疾半载方愈。腹内左脇有块，其大如碗，按之则疼，饮食日减，面目黄肿，每日午后冷热，肚大青筋，消积破块之药服二、三十剂，如石投水，一毫无效，卧床不起。邀余诊疗，六脉虚细欲绝，元气亏损已极，徜不急补养，女命休矣。余自制一方：", "12178": "邑西莲坡村，工广文子，年七岁，六月间随母吊丧，归家即病。上吐下泻，指甲微青，精神昏愦，如中鬼祟状。某医以为霍乱，针十余处，又服霍香正气散，病如故。迎余诊治，六脉离乱，毫无统绪。王肯堂先生云：「脉无统绪离乱者，乃客忤病也」。余想客忤属秽恶之气，人中此气，闭塞心窍，神明昏乱。奈小儿正在吐泻，药不能进，欲辞不治。儿母含泪苦求，余不得已，忽忆古云「香能辟秽气」。遂用：", "12179": "按：以六脉离乱毫无统绪，悟到客忤秽恶证；从患儿正在吐泻，悟出用药末熏面法，堪为诊治之妙。", "12180": "本城大士阁街路西，冯先生女，年六岁。三月患泄泻证，百治不愈，九月瘦至肉脱骨存，命如悬丝，二目上视，口紧不开，两手握固，湿汗淫淫，抽搐频作，他医误作风治，几濒于危，始请余调治。余见此证，诊其脉，断为柔痉。冯某乃辨为风，余引证前医为之辨论，以释其惑。仲圣曰：「太阳病，发热汗出，而不恶寒者，名曰柔痉。」王肯堂先生云：「小儿大病后，抽搐口噤身有汗者，人曰慢惊，即柔痉也。」宋太医贾才云：「小儿柔痉而作风治，未有不毙者。」李东垣先生云：「小儿柔痉，多见于吐泻、天花、痘疹、大病后，庸医误作风治，实杀之耳。」伊曰：「先生既云非风，因何有抽搐口噤现象？」余云：「胃属阳明而荣于口，主宗筋，至于口噤、四肢抽搐，皆阳明血虚不能荣宗筋故也，二目上吊者，足太阳膀胱脉起于目内眦，行头后而走脊，上视者证明是膀胱气血双亏也。」伊闻余言，请赐妙方。遂用参附回阳汤加味，水煎成，令徐徐服之。投一帖少效，二帖诸症均减半。原方共服五帖，方获十全。", "12181": "南郭外腊梅庄，卞凤魁次子，乳名二成。二岁时患痞块症，肚大青筋外露，每日午后发热，消积破块之药，服过无数。饮食渐少，形容日见憔悴，无奈就诊于余。六脉紧细，乃虚中挟实之证，攻之元气不支，补之块从何消。左右掣肘，忽忆李东垣先生枳术丸，诚古今消积之妙方。遂用枳术丸加穿山甲15克，三味药共为细末，掺入饭内。日服10-12克，初服60克，发热稍减，饮食渐增。又服120克，腹块消去四、五，似有若无。后又服120克，大便脓血四、五次，由此块无体胖，气色红融，已复原状。儿父十分感激。", "12182": "余毗邻张姓，与余素有小隙，伊女五岁，四月染疟疾，至十月百治无效。骨瘦如柴，面目浮肿，腹内左脇下有块，大似碗许，按之微疼，伊无奈，托人求余诊治。诊得脾肺脉有力，肝脉虚数。古云，疟本属肝。胆者肝之府，乃半表半里，所以寒热住来也。肝脉虚数者，可知肝病。脾为肺母，肺为肾母，脾母受伤，肾肺二经有连带关系，欲补肾子，先补脾母。余制一方，名子母两援汤。", "12183": "雎县西岭寺村，马姓夫妇，家贫甚，夫以笔耕，妻以针耨，生一子，方四岁，得痿证，卧床年余，调治乏资，终日忧虑，适逢临证彼处，趁时请疗。诊得小儿肝肺脉均滑数，此属湿热为病，非清热除湿不廖。遂开一方，名曰起废汤，二帖见效，八帖痊愈。儿父曰：「此儿余以为终身作废人，蒙先生一医而愈，大德大恩，恨今生难报于万一也。」", "12184": "按：《素问？痿论篇》有筋痿、脉痿、肉痿、皮痿、骨痿之称。并指出：「阳明者，五脏六府之海，主润宗筋，宗筋主束骨而利机关也。」患儿肝肺脉均滑数，知是湿热伤津所致。因此，翟氏从清热利湿、柔筋养阴著手，自拟起废汤治疗。方用三黄、木通清热，苍术、防风、茯苓祛湿，玄参、生地养阴，葛根柔筋，郁李仁润筋。湿热除，筋脉柔，则痿证自痊。", "12185": "空桑高氏者业农，伊子三十二岁出痘。余至时痘出五日，诊得六脉洪盛有力，沉取亦然。问其二便，大便秘涩，小便点滴极臊，其热非常，口气又臭，渴欲冷饮。痘色紫红，板滞不起，形证相参，确系实证无疑。余用二花解毒汤加大黄，煎成一帖，辰时服下，至申时病势如故。二煎又服一碗，天未晓大解一次，由此热证均去三四，痘转红和，已有白脓，此药不敢再服，恐伤元气。经曰：「大毒治病，衰其半而止。」改用平淡之剂，又服三帖，结痂而愈。如此实证，治数百人，仅遇二、三。余用凉药乃一时权变。敬告同道君子，勿谓凉药解毒，即可治痘之逆证，以误生民，当慎之。", "12186": "按：痘疹属实者甚少。此案六脉洪盛有力，便秘溲赤，渴欲冷饮，痘色紫红，脉证相参，确系实证无疑。遂用自拟二花解毒汤清热凉血，犹重解毒，不注重攻实，深得治痘之要。待热毒衰其大半，改用平淡之剂，始终以顾护元气为本，这正是翟氏的胆大心细处。", "12187": "医者活人之事，若粗而不精，亦杀人之机也。妇人之情，隐微难见，有病则一委诸医，医不能得其隐微，望闻问三者对于妇女诸多不便，惟凭切脉，可尽凭乎。惟是妄意揣度，聊复从事焉，嗟呼！此何等事，仅以意度之，而曰想当然乎。余应世以来，惟仗临时制宜，当从证从证，当从脉从脉，不拘纸上陈言。大概妇女之病，每由内伤，因思虑不遂、郁怒伤肝者居多，外感者不过临经感受风寒暑湿，初不为意，久成宿疾，变生诸症，笔难尽述。古云。「宁治十男子，不治一妇人」。甚言妇女病不易治也。能于妇女专书深心研究，虽不能生死肉骨，亦可告无罪于上帝。若目不睹歧黄先贤诸书，只图蝇头微利，一旦误治，或孝子慈亲，或人之贤妻爱女，复水难收，退而自思，宁无愧乎。余治妇女诸症，独重《济阴纲目》一书。此书对妇女之病，大者无所不包，小者无所不有，详切简当，登妇女于寿域，拯坤道于春台，无能出其右者也。", "12188": "余友索文萃令正，因郁怒伤肝，天癸四月不行。一日忽大下死血成块者十余枚，立刻昏倒于地，四肢厥冷，目闭口开，急迎余往治。诊得六脉极细欲脱。张洁古云：「血脱者补气」。急用：", "12189": "彭庄宗得玉妻，年只十余。二月经行，于坑边洗衣，此时天气尚寒，及归寒热似疟，天癸停止，亦无痛苦。又二月余，经水暴来，一时许，昏晕数次。某医用十灰散加收涩之药，两剂而止。经血虽住，少腹苦疼，饮食不进，身发寒热，夜间谵语。迎余治疗，诊得六脉沉涩，少腹拒按，此瘀血不尽，补益之害。张景岳先生云：「实其实而死者」即此类也。余用攻血汤服一帖，瘀血下两碗许，诸症少轻，腹疼如故。原方又投一帖，又下死血，如桃李者四、五枚。共服二帖，诸症皆痊。", "12190": "按：出血昏晕，不知补气摄血，只知炭类收涩，必生它变。此案少腹拒按，六脉沉涩，即炭类止血后的瘀血证。翟氏凭脉识证，凭证处方，改用养血活血剂，二剂血和。", "12191": "东关王明升妻，因经水适来，夫妇闹气，大怒之后，天癸遂停，由此腹疼，亦不甚重。至五月急下败血臭物，如梅杏者二十余块，立时昏晕欲绝，急迎余疗。诊得六脉如丝，余知气随血奔。时珍曰：「血脱补气」。遂用黄耆补血汤：", "12192": "邑庠生步苑仙令堂，年七十余。禀纯阳之脉，脏腑多热，可知屡患病热，后因郁怒伤肝，经曰「肝藏血」，肝属木，木喜条达而恶抑郁，郁则肝叶开张。血不能藏，赤带成矣。此证自三月起九月方剧，止血之药服数十剂，殊无效。迎余诊治，诊得六脉洪大且数，肝脉弦急，余用完带汤加减治之。二帖少效，六帖痊愈。", "12193": "北门内陈姓老媪，年六十余。患白带，所下之物如稀脓，少腹疼如锥刺，饮食日减，每天午后潮热燥渴，日轻夜重，卧床半载余。利湿清热之药，服过无数，均罔效，奄奄待毙。伊子请余往诊，六脉极虚无力，幸脉神不脱，或者生机在斯。看服过之药，均系逆治，不知从治之理。遂用", "12194": "按：只知逆治，不知从治，则大证痼疾难除。本案从六脉极虚无力及服过药味分析，知潮热燥渴为虚阳外越，脾湿不化。故放胆用术、苓、桂、附等治之，药投病机，其效如应。", "12195": "邑西南罗庄李姓幼妇，二十余岁。遭逢不偶，姑悍夫拙，终日诟诅挞楚，渐渐经水不调。每逢行经三日之前，先发寒热，腹疼非常，经水虽下，其色深紫，瘀而成块，七、八天后，经水方净。归宁，请余诊治，诊得脾脉虚弱，肝脉沉滞而弦。此因郁怒伤肝，木旺克土，经曰「肝藏血」。经水将行，先发寒热者，肝病确然可知。腹疼者是经水欲下，而肝气不肯疏泄，譬如客欲去而主欲留，不免有牵掣之势。所以每逢经行七、八日方净者，即此理也。倘肝气一疏，脾气自旺，饮食日增，何有经水不调之病哉。余用小柴胡汤合四物汤加减，服八帖痊愈，越一年又生一子。方开于后。", "12196": "按：凭脉识病，凭证立法，这是翟氏诊治疾病的特点。", "12197": "腊梅庄卞凤魁妇，年三十有二。患泄泻三年余，每日夜三、四次不等。由此经水三、五月一行，面黄肌瘦，短气无力，十指甲均秕，奄奄卧床。迎余诊视，诊得脾脉虚极，肝脉细急，此因泻伤脾肾，肝水为贼，耗肾水而克脾土。男精女血，乃五谷之宝秀。饮食既减，血从何生，所以经水三、五月一行也。看某医方，作经水不调治之，用破血开郁诸方，经水仍旧，泄泻更甚。余曰：「洁古谓决干河求长流何得也。」余用景岳先生左右归饮加减治之，服五帖稍效，二十余帖痊愈。待三月之后，经度如常矣。", "12198": "北朱寨朱姓农妇，年三十六。八月行经，在田适遇大雨，寒甚，经水遂止，腹疼，寒热往来，迎余治之。诊得六脉沉紧。丹溪先生云：「血得温暖则流通，寒冷则凝滞」。遂用四物汤加减，二帖稍效，四帖经水复行矣。", "12199": "邑西林庄林玉升妻，患白带三年余，屡治不愈，迎余诊疗。诊得脾肾脉虚而兼缓，肝脉弦劲，此因肾水不养肝木，木旺土衰，脾不传变，五谷之精不能化血，反协同脾胃湿下走膀胱，所以白滑之物时下也。治宜大补脾土，兼养肾水，水足而肝木自平，脾土无克，饮食之实秀，自然化为血矣。不治白带而白带不绝者，余不信也。因制一方，名曰化带汤：", "12200": "邑西林庄林姓女，十八岁。因气郁经闭五月余，少腹时疼，身发寒热，午后尤甚，鼻孔不时流血。余诊得肝脉沉弦，它脉平和，用开郁和血之剂，四帖痊愈。", "12201": "西门内王泰冉妇，二十余岁。五月临产，产后于院内取凉，至夜寒热交作，与疟相似。某医以治疟方治之，二剂罔效。迎余往诊，诊得六脉沉滞，此系寒凝血滞之故。用：", "12202": "按：病系受凉而得。六脉沉滞，为寒凝血滞无疑。故用温经补气活血之味，羌活祛全身之寒，均是根治之品。", "12203": "本城内吴姓女，年十九岁。被诬奸情事，出堂就审，女恃理直气壮，触犯县尊，恼羞变怒，横加五刑拷打，任死不屈，三堂后无二词。大冤昭雪归家，愤恨郁怒，大病在床，两脇疼如刀刺，时上冲心，口吐鲜血。每日夜四、五发，每一次辄疼死，约半小时方能苏醒。诸医治法，均是止血止疼之药，服二十余剂罔效，后事已备，待死而己。又过三日，病仍旧，无奈请余诊疗。诊得肝脉沉弦有力，直冲至寸部，脾脉滑数微虚，知属郁怒伤肝，木旺土衰，脾虚生痰。此证第一疏肝调气为主，清利脾热化痰为标，用小柴胡汤重剂加减。服一帖病去三四，共服四帖，诸症十全。", "12204": "邑西七里岗李玉琴妻，三十岁禀赋甚弱，怀孕五月，时常有病，最后又患泄泻，饮食日减，胎动不安。某医用凉血安胎之药治之，不只胎不能安，反泄泻加重，腹疼难忍，似有小产之兆。急迎余往治之，诊得六脉极虚细欲脱，此因某医泥于胎前不宜用热之说，以至于此。只知养阴凉血即是安胎之法，而不知孤阴不化之为害，只知有母而不知有父者也。余遂用十全大补汤加减治之，服二帖有效，五帖全廖。", "12205": "余毗邻潘传国妇，怀孕四月，请某医诊断，某曰，「此是气滞经闭之症，决非孕脉，通经破血药，十剂即可痊愈」。服至四剂而腹疼下坠，饮食大减，头晕目眩，不敢再服，迎余往诊。诊得左关滑数极虚细，两尺重取虽无力亦不绝，孕脉无疑，且男也。倘作病治，恐母子不祥，当急服安胎药，三帖孕妇饮食大进，诸症均瘥。十月胎足，果生一男，今已十八岁矣。", "12206": "开封曹门内路北，协盛布行伙计，长垣人，伊妻三十六岁，天癸三月不行。请本城第一名医诊断，言是经闭证，非破血通经弗愈，服药二帖，腹疼下坠，适逢余有事往伊号内，恳于决断。诊寸洪关滑，两尺不绝，真胎妇脉也。左手大于右手，确属男也。令勿药善调养，十月胎足，果产一男，今已十岁矣。笔此，并祈同道君子，倘遇少妇经闭，慎之！慎之！！！不为过也。", "12207": "郑寨黄姓室女，年二十，经闭三月，每日寒热往来，日晡更甚，咳嗽短气，大渴饮水，满面燥红，项间有瘰鬁五六枚，大如核桃，不疼不痒。某医作气滞经闭，服药十余帖不效。邀余治疗，诊得心脉沉滞而数，脾脉数而有力。「二阳之病发心脾」，知是心气抑郁，思虑伤脾，二阳郁结之故也。治宜开心窍，养脾阴，解肝郁，调气和血，自然有效。如不愿服药，少思虑则病自轻矣。伊母然其言，因伊不惯服药，故未出方。", "12208": "城内文化街孙兴冉妻，二十余岁矣，患水臌证，请余往疗，至时见患者卧床，周身头面肿似水晶无异。问其病天数，伊言二十三个月矣。诊其脉肉肿甚厚，浮中沉均不得，推筋著骨，诊得寸洪关滑，两尺不绝，左手大于右手，男胎也。告伊曰：「勿作病治，确系喜兆」。伊姑闻言冷笑曰：「先生差矣。世间哪有怀胎二年不产之妇。再者肿形如此，非水臌之明证乎！」余曰：「非也，此因当受孕时，肺经有水气之故。及受孕后，精神气血齐去养胎，水仍在肺，无气血传送，不能自行，其肿虽胜而水在表，内无大病。迟延不产者，一经有病，互相关连，它经不能不受其累，受累即是虚，所以不能比常人也。再待一月，必产无疑。」伊始以余言为是。又半月许，产妇之婿，执一请帖，言请余赴喜席。余曰：「何喜之有？」伊曰：「前贱荆之病，先生决断是喜，果产一男，今已九天。」余问临产情况如何？伊云：「产时先下浆水斗余，移片时儿下，发黑明，长寸余，声音洪亮。」", "12209": "葛寨王姓农人，妇四十余。五月临产，误听信婆言，坐草太早，产时用力过劳，小儿下地后，阴户内突掉出一物，色黑紫大如茄，不疼不痒，十余日不上。请余诊治，诊得脾肺二部脉濡细无力，此是气血双亏，乃子宫脱出，俗呼为阴茄是也，非大补升提不可。遂开十全大补汤加减，服二帖见效，五帖完全收入。", "12210": "葛岗李世清妻，患产后痢，日夜十余次，三月未愈，服药不下四、五十剂，均无效验。迎余治疗，至时见病者肉脱骨存，面黄唇白，绝无血色，言语低微，每日食面不过三、四两，诊其六脉虚细欲脱，辞不治。伊夫泣告曰：「堂上有七十双亲，下有二子三女，家贫如洗，井臼之操，全仗贱荆一人。倘一病不起，床前蹀躞之役，岂男子所为。祈先生大施仁慈，既不愈不敢归咎，万一全病，没齿难忘。」余曰：「既诚心恳求，以穷吾术，吉凶不敢预定，试治之何如。」遂用桂附八味汤加减。服二帖后，病虽不轻，亦不加增。又服二帖，略有效。十帖之后，病去五六，二十余帖，诸症如失。又调养月余，方能行动。", "12211": "余胞妹家住长垣，二十四岁。腊月临床后，受寒，大解时有泄泻，不甚介意。由此渐加沉重，每夜间泻三次，日间一、二次，百方调治，服药无算，有效有不效，终不痊愈。适逢余子完婚归宁来杞。诊得脾脉虚弱无力，命门脉细微，幸而均有神。此因火衰不能生土之故。命门火乃水之火，东垣先生云：此火乃雪里花开，水中火发，生命之根，元气之本，人生莫大之关要。倘专补火，恐阴有告竭之患，但补阴恐火有衰灭之虞。余用景岳先生左右归饮加减作丸药治之，初服半斤，稍有效验。一斤服尽，病去二三。共服五斤余，十八年沉屙已获十全。", "12212": "西陶凌岗贾姓室女，年十七岁，患呃逆证，三月不愈，远近医治无遗。迎余诊治，诊得肺脉沉涩，脾脉虚弱无力，经曰：「诸气𪱥郁，皆属于肺。」此因思虑伤脾，脾气郁结，肺为脾之子，母病及子，肺气不降，所以呃逆之证生焉。宜用苏子降气汤，服二帖有效，四帖痊愈。", "12213": "崔学易余盟弟也。伊妇天癸五月不行，迎余往诊。诊得孕脉俱现，惟虚弱过甚。余告伊曰：「此非病脉，乃喜脉也。」所以胎不长者，经曰：「冲主血海，任主胞胎」，冲任皆属阳明也。速补脾养血，培养胎元，以固根本也，免小产之患。用十全大补汤，服十余帖，气血日旺，精神日强，伊不善服药，幸无小产。至十三个月，产一女，今已二十余岁矣。", "12214": "余姨母五十五岁，患噎膈证，自觉咽喉间有物挡塞，吐之不出，咽之不下，气上冲逆，嘈杂难受，饮食减少，形容憔悴，口吐痰涎约碗许。招余诊治，诊得胃脉沉实有力，肺脉洪大，此是子母俱实之证。肺主肃杀下降，脾主津液，肺气不降，则脾之津液不能独行，津液化为痰涎。究其本源，实因大肠之燥而成，余用大承气汤服一帖，大解二次，下干粪三十余枚，坚硬如石子，病去二三。又服二帖，燥粪已尽，后见溏便，诸症十全。此证倘作真噎膈治之不愈，死者无言，医者不醒，必归咎于命。命之一字，乃医家借口，以谢病人，告无过者也。", "12215": "按：上病治下，为反治法一种。此例若取上舍下，陡用化痰降逆开结之品，不惟咽喉不开，魄门也闭塞不通，必成关格之证。翟氏善依脉认证，此例胃脉沉实有力，肺脉洪大即为立法之准绳。", "12216": "阳堌集士人潘姓妻，二十八岁小产。一连四胎，又怀胎三月，惟恐小产，就余诊治。诊得肝肾二脉濡细无力，古云「肝为血脏，肾主胞胎」。二脏虚亏，胎赖何养？遂用大补肝肾之品，每月服三剂，至十月胎满，果产一男，今已十岁余。方开于后。", "12217": "楮皮岗胡姓妇，年近七旬，患反胃症。每日饭后不一时许，呕吐不停，所食之饭，尽净吐出。某医作倒食治之，行气调胃止呕之药，无非香燥顺气之品，服过无数，四月不愈，邀余诊治，诊得肺胃脉洪数有力，年虽老而病有余。此是大肠有结粪，停滞不行，下窍不通，必反于上，肺脉之洪数，实由此也。胃为仓凛之官，大肠不通，胃中之水，不能由小肠传入大肠，胃有入无出，所以尽净吐出也。倘治肺胃，此是舍本求表，如何能愈！余用：", "12218": "沙窝集郑子和妻，年三十二。患齿箭证，每日出血碗许。某医用十灰散治之，殊无效。迎余往诊，病已六日。诊得脾胃脉洪盛有力，症系阳明胃经实火。胃乃多气多血之府，齿龈又属于胃，胃火上冲，血随火升，所以从齿龈中流出。若不泻去胃中之火，病从何已。张洁古云「血得热妄行」正指实火而言也。余用：", "12219": "马抡升先生，余同道友也。其令正性质朴，因家务琐碎，素积郁怒。偶于仲秋患病，如痴如迷，问之不语，不问则有时自言喃喃，与之饮食亦不食，两手摇自己头发，抡升行医多年，自开一方，大概是顺气开郁化痰之品，服二帖无效。招余诊视，余按痰火治之，服两剂绝无效。又请某医治之，仍如前。渐加沉重，奄奄待毙，后事已备。有一息之生，不忍坐视。此时病八日矣。晚间抡升又招余诊治，余曰：「若有妙术，何至今日而不用也。」抡升曰：「早知不起，再为诊之，以决死期耳。」余往诊，六脉无败象。余告曰：「与其坐以待亡，不如冀其不亡。余再为之针中脘、足三里试之如何？」伊曰：「可」。中脘针二寸，足三里针一寸，俱行泻法针。又开一方与前方大同小异，渐渐灌之。至二更时，饮食略进，神思微醒，由此日轻一日。又服二帖，渐获十全。由此看来，初服之药，皆是对证，并非妄投，只因郁结深久，坚固难破，所以不效者药力不敌也。而后效者，药借针力以为先锋，药力后进，斩杀群妖扫荡魑魅，一阵成功。华元化曰：「针无药稳，药无针捷」，信夫！", "12220": "邑庠生魏馨山，余友也。伊令正年近四旬，禀赋极弱，平素多疾。于七月间，猝患类中风证，招余往诊。目闭口开，痰声如锯，脱汗似油，精神全失，诊其脉已见鱼翔。余曰：「形脉俱败，不可救药矣。」纵有扁卢，亦无能为力，急备后事。果殁。", "12221": "馨山继室，年三十余，八月染病。招余往诊，得肝脉弦数已极。余告曰，肝之一脏，在天为风，在四时为春，在五行为木，在人为肝。又云：「诸风掉眩，皆属于肝。」今肝脉如此弦数，惟恐风将作矣。馨山不甚介意，后于来日午时怆惶招余往，至时，但见目闭口开，两手握固，六脉洪大无伦，形如死尸，问之不语，此是类中风之热也。又恐药不济急，用针刺少商、厉兑、少泽、人中、上星、百会诸穴，以泻脏腑之热。刺已，人事稍醒，又服平肝清热药，一帖痊愈。方开于后。", "12222": "俗称治疡医者，中士下士之学即可，皆于内科别之。然未有不明内科而擅长于外科者，如仲景治伤寒，有汗、吐、下三法。东垣治疮疡，有疏通、托里、和营卫三法。其事各殊，其源则一。譬如，树木有果结，人有疮疡，其理一也。至于疮疡之生，又分险顺逆三种之吉凶。何以知之，总不出纯阳、纯阴、半阴半阳。倘能悉此三者，再明经络脏腑之部位，熟烂胸中，病之生死，无不立判。常见不明内科之疡医云，某穴生疮主吉，某穴生疮主凶，此乃守株待兔，按图索骥之流，不足道也。余自治疮疡数十年来，按穴生疮之说，历年既久，不敢坏古人成法，亦不泥古人成法。每逢疮疡，先为诊脉，再与五善七恶，互相校参，虽不尽善尽美，自问可无大过也。", "12223": "按：背疽有阴证阳证之分。阳证红肿痛甚，脉数有力；阴证漫肿色黯，脉数无力。阳证宜清解，阴证宜托补。本例仅依几乎一背尽满诊为阴证，当有肿处色黯不红、痛微，脉数无力等为是。", "12224": "彭庄宗国亮之兄，年六十二，患唇疽。迎余往疗，见唇肿有二寸厚，二目脱神，诊其脉杂乱无统绪。余命速备后事，越三日而殒。", "12225": "按：本例为茧唇，即唇瘤，多因脾湿胃热薰蒸所致。目脱神，诊其脉杂乱无统绪，说明已至晚期，故不日而损。", "12226": "五堂村王绍轩之嫂，右耳下生一疮，迎余往治。病三月余，溃破甚险，脓水清稀，六脉虚细无力，饮食减少。看所服药，是凉血解毒，损伤脾胃，不知虚实之过也。余用十全大补汤，外上红升丹，十日后新肉渐生，饮食日增，始终调理，月余方愈。", "12227": "按：脓水清稀，六脉虚细无力，是阴证非阳证，故服凉药不效。", "12228": "万春堂学徒孟生，十八岁，患中脘疽。某医误作痞块治之，服消积破块药十余剂，自觉食减气短，不敢再服，请余诊治。诊得关脉芤，按其胃脘，果有一块，大如碗许，无怪某医作痞块治也。余告伊曰：「此证确属中脘疽无疑。速服托里之药，令疮头回转向外，方是吉兆。若以内破，再不得其治法，恐有烂胃腐肠之忧，悔之晚矣。」伊深信。遂开仙方活命饮加减。服五帖后，中脘穴上肿出一块，大如覆碗，又服五帖，高三寸余，按之大软，脓已熟矣。用尖刀刺破，红白脓交流不已，约五、六碗许。上以红升丹、服气血双补之药，近三十帖，始终无变证，方获痊愈。", "12229": "邑东宋湾宋国选，年近七旬，患少腹痈。迎余往治，病已月余，命似悬丝，后事已备。伊云：「自知难愈，只因幼乏子嗣，五十方生一子，现十余岁，老妻五十余，其他无人。倘余不起，留下孤儿寡母，虽有几亩薄田，必不能守，将来不知留流何所。每念及此，肝肠寸断。祈先生大施仁慈，万一得愈，阖家不散，德戴二天矣。」余问曰，「出恭如何」？伊云：「每逢出恭用力，疮口出血如注，大概约有一茶盅许。」诊其脉幸有力有神，许其可治。遂用十全大补汤服之，外上红升丹，化腐生肌，提脓拔毒，以膏盖之。由此饮食日增，精神日强，疮日渐敛，大便时亦不出血。共服药二十帖，调治月余，诸症全瘳。", "12230": "杨大庄周姓妇，年二十余，生一乳疽，先往西医院调治。他医云：「业已腐坏，非割下别无良法。」患者闻此，任死不治，就治于余。诊其脉弦细劲硬，此因郁怒伤肝，思虑伤脾，肝脾两亏，必服内治药，外上红升丹，约月余方可收功。遂用健脾疏肝之药，服五帖后，腐肉尽脱，新肉日生，上药每日两次，又服药十帖，已轻四五。共服药二十余帖，始终近五十天痊愈，且无分毫残废。方列于后。", "12231": "西关杨姓妇，二十岁。生一托腮疔，初得寒热大作，呕吐恶心，精神昏愦谵语。迎余往治，见其疔色红紫，以指按之，坚似钉尖，此真疔也。诊其脉，心、肝二部洪数有力，此因肝木太旺，木生心火。经云：「诸痛痒疮，皆属于心。」又云可泻者泻其子。遂用犀角黄连汤加减服之，以泻内毒。先服一帖，大解一次，病无增减，再诊脉仍如故。大黄加至36克，大泻二次，寒热已去八九，精神清爽，疼痛尽消，从此消散乌有矣。", "12232": "按：疔色红紫，脉洪数有力，为阳证无疑，故予清热解毒之犀角黄连汤加减，肿痛尽消。", "12233": "南门内赵洪范之妻，患三里发，十三日，迎余往治。诊得阳明脉洪数有力，疮形如酒杯，疼痛非常，日夜恸哭。以手按之，坚硬如石。此证乃胃经之实热邪火，经曰：「诸痛痒疮，皆属于心。」当急泻胃经之火毒，以保无筋腐骨折之虑。外擦以琥珀蟾酥散，令毒不能走散，急速溃出脓血，以免内攻。遂用二花大黄汤，服一帖大便泻下三次，疼痛稍减，又服一帖，又泻三次，疼去七八。待四日，疮已大熟，用利刀挑破，流出尽是黑血，毫无脓意。书云「实而疼甚内是血」。信不虚也。外上黄灵药，每日二次，后服二花解毒汤六、七帖，病已。", "12234": "邑东岗李姓小童，八九岁。头上生一肉瘤，大似核桃，根如指粗，不痛不痒，有时误触动则流血不止。余再三详看，患处无赤脉，必非血瘤。遂用药线将本根扎紧，每日紧线一次，七、八天后，患根尽成腐黑烂肉，如瓜熟蒂落。后上玉红膏，收口痊愈。", "12235": "管守仁年三十二，患腹疼，请余诊疗。诊得关脉犯芤，右腿难伸，少腹右生一疙瘩，大如覆碗，疼痛难忍，日轻夜重，饮食减少，寒热交作。告伊曰：「书云大肠痈者，右腿难伸。又见孔脉，《脉诀》云：关内逢芤肠胃痈。以脉证合参论，确属大肠痈无疑。急服苡大黄汤。脓从大便出者顺，若少腹攻开口者为逆。」伊谓余言过缓，急求速愈。赴开封美国医院调治，西医用利刀将疮开四瓣，疮口大似碗许，每日三次洗之，然后上药。此疮开五日后，少腹之上又起疙瘩三枚，大如核桃，遂又尽开之，每日出鲜血碗许，由此饮食大减，凶证齐现，不得已出院。又请中医调治，百方无效，不数日而殒。由此看来，西医精于有形，略于气化，不知阻阳进退消长之机，所以治内生之疮，多不愈也。", "12236": "邑北窦贵寨曹长贵余仁侄也，其妻患乳疽。赴他医调治月余无效，迎余往诊。见一乳烂去一半，脓水交流，其色紫黑，骨瘦似柴，言语低微，面色焦黄，诊其脉濡弱虚细。告伊曰：「乳者属肝脾胃三经。此证因郁怒伤肝，思虑伤脾，肝脾气郁，结于乳房，血为之不行，结而为患。」此证非从内治弗愈，先后服药疏肝健脾以绝根株，患处上大金丹，提脓拔毒，化腐生新，经曰：「治病必求其本。」即此谓也，遂用八珍汤加减，服五帖，脓渐稠，新肉渐长，饮食日增，共服十五帖，月余痊愈。此证倘不服药，专用外治，舍本不问，吉凶不可知也。", "12237": "城内银子井黄姓翁，七十岁，患承山发。邀余往治，见躺卧于床，满面通红，疮大似盘，腐肉肿有寸余，绝无脓意。诊其脉洪数有力，审其形亦无败象，年虽老病却有余。内服仙方活命饮，外上白降丹，以膏盖之，每日一次。三日外腐肉脱尽，正脓以生，遂换红升丹，每日两次。二十余日，病去五六，改服十全大补汤。二月外共服药二十四帖，遂获平复。", "12238": "李岗李姓妇，四十岁，患偏对口，月余，迎余往治。见肿势甚大，上至巅顶，下连至脊，坚硬如石，绝无溃意。告伊曰：「正对口属督脉为阳，自下行上，易于肿溃；偏对口属膀胱为阴，由上行下，月余不溃者，纯阴无阳也。有人患此，先将生死置于度外，不误治法，亦有得生者。倘不得治法，服败毒之药，如冰上加霜，不知急令阴变为阳，未有不毙命者。」遂用黄耆托里汤加减，服五剂，疮根日收，焮肿日消，正疮渐长，又生大疼，时轻时重。原方又服五剂，浮肿消净，以指按之，遂按遂起，脓己收矣。用尖刀挑开，红白脓出两碗余，即时轻爽。外上红升丹，每日两次，又服黄耆汤七、八剂，渐渐痊愈。外科一门，不明脏腑经络，阴阳表里，寒热虚实，全恃上药、膏药，有不误人命者，余不信也。", "12239": "域内土地阁街马姓妇，年近八十，患正对口，二十余日请余往治。疮口大似茶杯，脓色稠黄，腐肉尚未脱尽。诊其脉洪而有力，问其饮食，喜凉恶热。伊子问曰：「日夜疼痛不止，何也？」余云：「内经曰诸痛痒疮，皆属于心。汝母年虽老，而禀赋甚厚，又属阳脏之人，以脉证并参，此证非大凉兼泻不愈。」遂用内疏黄连汤，服一帖大泻两次，内热已减，疼已稍止，脉洪而有力，比前略退。原方又投一帖，余症尽除，停药不服，外上大金丹，每日两次，以膏盖之。自诊起日近月余而愈。", "12240": "按：正对口又名项疽，生于项之中，因与口相对，故俗名对口，属督脉阳热火盛。焮红肿痛易治，根大坚硬者难疗。本例脉证悉属阳证，故遣用凉血解毒之味而愈。", "12241": "张显亭患中脘发，屡治不愈，二十余日。迎余诊治，见其疮头大如汤碗，焮肿似盘，疮口深有寸余，腐肉不脱，新肉不生，诊其脉洪盛有力。此系脾胃火毒结聚而生。当先服仙方活命饮，三帖以解内毒，外上大金丹，化腐生肌。日有佳兆，三十日而愈。", "12242": "管狱员王子勉，年五十余，一子三龄，患瘟疫后，毒气不尽，结于左腮之下生疮，中、西医百治无效。邀余诊视，见小儿身体极瘦．诊其脉亦无凶象。再审疮形，口深寸许，色又暗淡，脓水清稀，真虚证也。幸无臭气，虽属危证，尚且可治，惟费时日耳。子勉曰：「但求能得性命，实属万幸，迟速何妨。」又喜小儿善于服药，每日一帖，外上红升丹，掺玉红膏。余爱子勉忠厚长者，惟此一子，每日一次，亲自上药调理，共服三十余帖，近五十天方搏瘳。方开于后。", "12243": "城内耿顺德，年二十余。患玉枕疽，疮形甚恶，大如瓜蒌，疼似火烧，硬如铁石，半月后不溃，诊其脉皆虚细无力。此系督脉受寒湿凝结而成，久之寒化为热，阴变为阳，方能成脓。目今之治，先服仙方活命饮，令其速溃，以免毒气蔓延。伊亦信服。三帖疮已半软，又投四帖，疮已熟矣。用刀取破，脓血各半碗许，上以红升丹，每日两次。共服药十帖而愈。", "12244": "西门内王姓小儿，五岁患手背发，屡治不愈。邀余诊视，见小儿手背筋骨尽露，所流俱是臭水，并无脓意，小儿体极瘦弱。伊母又云：「大便日泻三、四次不等，夜间疼痛不止。」余诊其脉，六脉皆虚细无力，此因久病失于调补。疮科又属破漏之证，如同居家，每日非用钱十串不能过活，若仅有进款五串，不止日贫，且有冻馁之虞。此儿之疮，三月内臭水淋漓，非虚乎！饮食减少，非虚乎！大便滑，非虚乎！由此思之，臭水无脓者，正见元气亏损，不能化毒之明证。今治法宜先服十全大补汤以壮气血，气血壮自然化毒变脓，外上红升丹，提脓拔毒。各外科书皆云，有脓则生，无脓则死，此千古不易之言。伊父母闻余论深以为然，遂服十全大补汤，五帖后，疼痛稍止，似乎有脓。又投五帖，泄泻自止，饮食大增，脓变稠黄，臭气已去，生机日多，脱去危险。此证自余治，始终四十二天，共服药三十帖而愈。倘若不从内治，全恃外治之法，恐终不免亡。常见有患疮者，连年不愈，外科家不间新旧虚实，满口谓毒气不尽。至于用药，轻者凉血解毒，重者硝黄乱投，犹言宜清内毒，竟使元气日消，毒气日盛，不死不休。如此而死者，不胜屈指，皆因不明《内经》虚实大论之误也。", "12245": "按：乳岩即乳腺癌，属难疗之疾，古有「百无一效」之说，多由忧郁损于肝脾所作，并提出「清心涤虑」为治疗之一要。本例针药并治，补中有消，消中有补；养血不忘调气，止痛不忘通络。所列方药，平淡无奇，但非如此，实不能渐消，虚不能见回。可见即是疑难重证，亦不可猎奇，始终要遵循仲景所说的「观其脉证，知犯何逆，随证治之。」才能化险为夷，转危为安。", "12246": "余友栗守道患头疼，脑如破，项如拔，头肿似斗，他医作脑发炎治之，一日连射三针，殊少效。中医作风寒治之，大概川羌活、藁本、细辛、荆、防之类，服二剂其疼转剧，日夜无宁刻，二日又起云翳，对面失明，目疼如抉。迎余往，诊得心肝二脉洪数且实，经曰「肝开窍于目」，木为火之母，火盛者肿，是木火通明之象，作风寒治之，正是风助火势，火借风威，助纣为疟，无怪乎病之加重也。宜凉开泻心更兼走空窍之药，服一帖头疼愈，二目己轻，二、三帖后，改治眼退云翳之药，渐渐见功，服药十余帖，二目复明如旧。方开于后。", "12247": "邑西七里岗胡姓，年六十余。头疼如碎，呕吐不止，二目数日失明，眼科专家百治罔效，伊转托栗守道先生恳求余治。伊云：「自知二目难愈，但望头疼稍止，苟且得活，迁延余生足矣。」余曰：「此证勿须诊脉，余对此病，颇有阅历。此因肝火上冲，脑户受风，风火混合，狐假虎威故作祟，甚恶也。倘误用羌、荆、防、天麻之类，无不加重，治宜甘寒凉润之品，无不立验。」余用：", "12248": "南门韦姓，患头疼证，每日卯时其疼如碎，误作太阳寒证治之，令发大汗，不但不轻，反而沉重。迎余往诊，肝脉弦数，此因怒动肝火，火性炎上，直冲巅顶。古云「火盛者疼」。治宜疏肝清热，头疼自止。遂用：", "12249": "按：卯时疼重，卯属木，又肝脉弦数，是肝火上冲证，治以清肝火甚当。", "12250": "本城人李书林，作小贩贸易，头疼欲死，百治无效，请余诊治。肺脾二部脉极细无力，此上焦元气不足者令人头疼。徜不明此，误作他证治之，其病必重。治以大补元气，头疼自愈。遂用：", "12251": "东郭外边庄边广照，余友一也，伊令侄患真头疼，百治绝效，迎余往治。至时见患者侧卧于地，头上放一棉衣，一人坐于患者头上，两足悬起，头疼稍止。诊得两寸脉俱细，其余两关、两尺皆已无神。此真绝证，脑已坏矣，即扁卢亦无如何，越日而亡。死后十指皆青。此证四十年来，仅见一人而已。", "12252": "西门吕姓妇，年近七十。患脑中风，头疼殊甚，某医误作上焦火治之，大概服药俱属芩、连、栀、柏之类，三剂无效，请余诊治。诊得两寸脉浮紧，此属上焦中风寒之故。遂用：", "12253": "邑东官庄梅姓妇，产后出房太早，患头疼，半年治不廖。迎余往治，诊得六脉皆虚细无力，此因新产，气血双亏，风寒乘虚侵入脑户，正气不能托送。宜用十全大补汤。气血充足，风寒不能停留，自然解散，有何头疼不愈也。共服十二帖而愈，永不再发。", "12254": "北吕寨村王姓，年五十余。夏令务农，身出大汗，乘凉躺卧大树下，自此两腿疼痛难移，日轻夜重，病证日重一日，无奈迎余往治。诊得肝肾脾三部脉均沉紧，《脉诀》云：「沉者主寒，紧者主疼。」此属寒邪无疑。遂用温散寒邪和通经络之剂，服一帖无效，又服二帖，夜疼减半，共服八帖，平复如故。方开于后。", "12255": "吕寨王子明女，年八岁。中风寒半身不遂，用人扶持，仅能移步，三月余屡治不验，迎余诊疗。诊其脉，因虚弱中风寒之故，经络被寒邪滞塞，气血不行。治宜先用针开通血脉，然后回其虚，逐其邪，徐图缓愈可也。遂针足三里、阳陵泉、太冲、委中诸穴，各灸十壮，后服黄耆除风汤，十五帖渐获平复。", "12256": "薛楼薛某，舌耕为业，年五十二岁。禀斌甚弱，久坐伤脾，又逢夏令暑气炎炎，乘凉太过，渐觉半身麻木不仁，微有不遂之兆。迎余往治，诊得肺脾之脉极虚兼紧，脉诀云；「紧者主寒」。遂开十全大补汤加减，共服二十帖，平复如旧。后患者问余曰：「服除风之药十余剂无效，今先生亦用除风之药而痊愈者何也？」余曰：「伊虽用除风之药，内无补药，中气不振，邪气沉匿于血脉之中，如何能去？经曰：不能回其虚，安能攻其余？，景岳先生云：正足者邪退，又云：补正即是发表，灌根即是洒叶。余尊古人成方，所以有效也。」", "12257": "北郭外范庄胡姓妇，年二十余两腿、两足疼痛非常，两足如站火中，每日至申刻，大哭不止，至明方已，卧床二月余，数治不愈。请余往疗，诊得肝脉甚虚，两尺脉洪大且数，中取不见，此证乃系阴火太旺之证。余用知柏地黄汤重剂加减治之。古云：壮水以制阳。先服一帖，似乎有验。又服一帖，疼去二三。速服八帖，其病如失。", "12258": "西北黑木岗人杨逢春，冬令出外贸易，偶逢大雪，困于店中，半月方晴。在店内受寒，初觉两腿麻木，又十日后，酸疼不止，渐至腰间，不能举动，痿卧于床，饮食日减。迎余治之，诊得肺脾肾三部脉沉迟，此是寒邪入筋骨之中，非旦夕可愈。遂用大活络丹治之，二帖后病如故，命伊再服三帖，虽无大效，略能转侧。又服八帖，病去六七。共服二十一帖，方收痊愈。", "12259": "西门内陈老白，年四十二。患周身筋骨酸疼，但不麻木，每遇怒气，其疼更甚，腰又独重于他处。三年之内，百治不愈，恳余诊疗。诊得肝脉弦数，脾脉洪缓。此因肝经之怒气与脾经之湿热，合而为一，流入筋骨之间，所以疼生焉。作风寒治，无怪乎病之不愈也。治当疏肝调气为主，清利脾之湿热为标，标本同治。每帖药用好酒二两，与药同煎。余深有用意。酒属湿气化成，又借物有同气相求之理，引之以作向导，直攻入湿邪之中，岂有不效之理。两服后略有效验，更进三帖，病去五六。共服十三帖，三年沉屙，一旦扫除矣。", "12260": "按：何以知肝经怒气与脾经湿热流入筋骨之间？每遇怒气，其疼更甚，肝脉弦数，脾脉洪缓，足以为据。", "12261": "济南人庠生李松岩，在杞县署管帐房。伊患腰疼证十余年，屡治不廖，迎余治疗。诊得两关、两尺之脉沉缓，重取微数。又问善饮酒否，伊云：「前数年每日饮酒不下十两，近因腰疼，每逢少饮，即觉加重，故以此断绝不饮。」余曰：「今虽不饮酒，而病尚在。酒者性属阳而体属阴，阳邪升于上，呼吸之间，从口鼻而散，湿邪留于中，先伤脾胃之中气，中气已伤，不能送酒之湿邪，缠绵难已，又未能得治此证之善法，何能愈也？今对此证虽能治疗，难求速愈，非服丸药五、六斤不可。伊云：「倘能愈疾，即十斤有何难哉。」余遂定解酒除疼丸：", "12262": "邑南毛岗有农人何姓者，甚贫，年六十岁。患两腿连腰疼痛，更兼麻木，半年治不愈。诊得脾肾二部脉沉迟无力，因气血虚弱，风寒袭入脾肾二经。欲治此证先补脾肾，能令先后两天气血完固，何邪尚能留而为病也。古云补正即是驱邪。不能补其虚，安能攻其余。遂用先后两补汤，二帖稍见效，八帖痊愈。", "12263": "雎县袁雨峰，年三十二。禀赋极弱，瘟病之后，遂得筋骨酸疼之证，二载不愈。迎余往治，诊得六脉虚细无力，此因瘟病初愈，房事太早，气血双亏之际，复伤肾水。经云肾主骨，水亏则骨不得其养，而疼痛生焉。此证除补肾之外，皆非正治。伊云：「先生之论甚合鄙怀。有云疼痛无补法，信乎？否乎？」余曰：「此言固书于前贤，亦不可执著。譬如伤寒初得病在太阳，其人又憎寒，寒热往来，头疼如破，此时正当用麻黄汤以发汗，而头疼寒热即解，此是疼无补法也。又如小儿偶逢适口之物，一时贪食过度，又属脾胃之阳虚最多，过食而不能消化，即是伤食之实证，壅塞上焦，上下不通者而疼痛生焉，治宜消导推荡，宿积已除，诸症皆愈。此又疼无补法之一端也。类此者极多，一隅三反，存乎其人。」彼方深信不疑，遂用补肾汤，服五帖见功，病去一二。共服二十余帖，诸症皆廖，身体强壮胜旧，始终亦无改方。", "12264": "吕屯潘姓妇，年五十二。每逢郁怒，周身筋骨疼痛难忍，日夜啼哭，数治不愈，迎余往疗。诊得肝脉弦数有力，此因久积郁怒，肝气不伸。古云，肝性急为病多疼。许学士云：「肝无补法。」易老云：「东方无补。」似此肝病，非泻不可，然而泻肝，又必须补水，因水能生木，水亏则肝燥，水足则木得其养而不燥，不燥者性平，而郁怒自解矣，何患疼痛不解也。余用六味汤加减治之，服二帖疼去二分，服五帖后，疼去大半。共服十二帖，病良已。再逢郁怒，永不发矣。", "12265": "邑西十里岗邵姓妇，产后月内，周身疼痛，迎余诊疗。诊得六脉细数无力，余认为产后气血双亏之证。用十全大补汤加减，服一帖虽未见效，而病亦未增。余谓药剂太轻，原方加重份量。又服一帖，至夜间病势大剧，疼痛难忍。大哭不止。患者云：「自服此药觉得心胸满闷，更添少腹疼胀。」余知乃用药之误也。再为详诊，脉比前三日虚者变实，数者更数。余明告伊曰：「此证是产后恶露未尽，因一时误认为虚，反用补药，以实填实，治之不当，故此加重。余虽有过，其心可原，倘肯再信，定能使病随药减，若再不验，甘愿受咎。」幸患者信而无疑，余即用失笑散加玄胡一味，共三味为细末，用酩流酒四两，煎滚冲服。二时许，少腹大疼一阵，遂下黑血块如桃李者六、七枚，病去五六。又服一帖，恶露始尽，三、四日竟获十全。因一时之误认，几乎令入夜台含冤，至今思之不免愧汗淋漓。敬告同道君子，每临证时，详细诊视，勿似余庸鄙误人，此又切切厚望也。", "12266": "按：六脉细数无力，故用十全大补汤，因服药增剧，脉虚变实，而悟到恶露未尽，遂用失笑散加玄胡一味，热酒冲服，三、四日而获十全。初治诊为产后气血双亏，亦无大错，若能于补中兼活，庶几细微。但误治不讳，笔录在案，可谓治学精神之笃实。", "12267": "邑东郭庄孟生，年十六、七，患阴黄年余，治之未愈，邀余诊疗。见患者骨瘦似柴，面如烟薰，声音低微，诊得脾脉极虚，细问所服药，皆系茵陈、栀子、黄柏、黑矾，大概除湿退黄利水之类。而病毫不见效，日有加增，何也？余曰:「子之病阴黄也。所服药物，均治阳黄之品，于病相左，不重而何哉？治宜大健脾肾二经，先使元气充足，自能生血，血足自能华肉，勿须治黄而黄自化于乌有矣。」遂用键脾补肾汤。服三帖黄虽未退，饮食日多。又服五帖，黄退三四。更进八帖，面色变为红活，神气复扫，病痊廖矣。", "12268": "余友彭续亭，二十余岁，患阳黄之证。月余外身目黄如金，体重难移，小便之色如黄柏水，饮食大减，短气懒言，诊得脾经脉沉数兼滑。此因湿结于脾土之中，湿化为热，故土色外现也。短气者，湿滞气遏也。饮食减少者，脾土喜燥而恶湿，脾失转运之职，故食减也。治宜利湿退黄之品，指日可愈。用茵陈柏皮汤加减，服三帖而愈。", "12269": "邑北尹店马之才，年三十二，家赤贫。因出外作小贩，偶遇阴雨，连绵逾月不晴，困于店内，食不充饥，衣不避寒。后天晴归家，染病在床。但觉胸腹满闷，身重难移，饮食日减。小便色黄，身目如金，远看黄中似有灰黑之色。诊得脾胃脉，沉细无力，此乃饥饱劳役以伤脾土，乃阴黄之证。治宜温中健脾，兼利小水，似易可愈。遂开一方，名曰温中除黄汤。服三帖后，病去四五，更进四帖。诸症痊瘳。此证若作阳黄治之，愈否尚在两可。余认为阴者，因远看面有灰黑之色，脉色相合故也。", "12270": "按：从远看，面有灰黑之色，辨出阴黄，又与脉相参，精细，精细！于疑似之间，辨其真伪，堪称高手。", "12271": "边兴云之姑丈，年近五旬，患阴黄病，三年内百治不廖。气色灰黄发暗，略有动作，短气不易接续。邀余治之，诊得脾肺脉虚细无力，肾脉濡弱。此证等于劳苦过度。古云：「劳则伤肾。」又云：「劳则伤牌」。此是先后两天并伤。若不从根本治起，专务除黄，惟恐愈治愈危。宜急固先天根本，再补后天之源，徐图渐愈可也。用先后两补汤，服五帖少效，又十帖全廖。", "12272": "邑南街有商人刘春明者，年二十余。患黄病年余，服除黄健脾利湿之药，不下百剂，毫不效验。病势危急，后事已备，阖家不忍待亡。迎余往治，诊得肾脉微细无力。此证得于房劳太过，伤肾之故。古有「房劳疸」之名，即此证是也。当大补肾水，收复先天元气，以生脾上。土自能生金，肾水有源，不必治黄而黄自退矣。六味地黄汤加减，原方服三十帖而愈。", "12273": "邑西南门内赵凤桐，年三十二，患黄疸证，半载不廖，邀余治之。诊得脾脉洪滑有力，面色黄明，声音壮厉，小便赤黄微疼。此系湿热壅遏中焦，结而不通，所以发黄也。治宜攻其湿热之邪，利其脾胃之湿，未有不愈者。", "12274": "南马庄王青山妻，年三十余，妊娠五月，患黄病。诸医作湿热治之，所用之药，茵陈、栀子、木通，黄柏、黄芩、槟榔、枳实、滑石之类，服五、六剂后，患者饮食渐减，胎气时动不安。迎余治之，诊得六脉虚细无力，似有散意。告伊曰：「此是湿热发黄诚然也。所服之药，内无安胎之品，寒利太过，已伤胎元。顾此失彼，故胎动不安也。今治宜安胎为主，除黄为标，或可望愈。若再专务治黄，不惟黄不能愈，胎亦不保矣。」遂定一方，名曰安胎除黄汤。二帖有效，又三帖大效，共服八帖，胎安而黄除矣。", "12275": "余友常伯石令正，患湿热发黄病。某医误认经病发黄，服调经调气之热药，数剂不验。迎余诊断，诊得脾脉滑数，肺脉亦然。此是母令子实之证。经曰：「治病必求其本。」余用：", "12276": "按：黄疸病诊得「脾脉滑数，肺脉亦然」，乃脾胃实热证无疑，实热上逆，故肺脉亦见滑数。翟氏用清热利湿和泻实热并重之药投治而获效，可谓认证真切，遣方精当矣。", "12277": "北关江姓妇，年七十余，染黄病，卧床半载，数治乏效。邀余往治，见病者面黄如土，又诊其脉，脾脉已见屋漏，知后天将绝，不易救治。后越三日而殁。古人云：「五脏之真色见于外者死。，噫！信矣。", "12278": "按：年逾古稀，染黄日久，后天衰败，真脏脉见，命在垂危，病情危笃。临证诊治，慎之，慎之！", "12279": "兰阳县城内崔子明，年八龄，患黄病，身肿时作，腹疼，治黄之药服过无数，终不验。赴杞请余调治，诊得小儿之脉，均有细紧之象。又问腹疼时别有状况否？伊父云：「大半饥时疼者为多，饱时轻减。」又问疼时有块凸起否？伊云：「无块，淮长条如指许者有之。」余详此病状，似乎有虫。一转念各书又无虫黄之名，偶忆景岳云：「医之一道，运用存乎一心。遂开：", "12280": "邑人管青山，年三十余，患呃逆证二十余日，饮食难用。某医云呃逆病多危，辞不治。患家固求，伊始开方。用药大概柿蒂、藿香、半夏之类，服二帖无效，又迎余疗。诊得脾胃脉沉实有力，此证得之于饮食塞胃，中焦停滞不行，阻碍胃气不能下降。下既不通，必反于上，自然之理也。但使宿食一下，三焦之气上下通顺，不治呃逆，而呃逆自除矣。某医云多危者，乃久病忽加呃逆，谓之后天已败，故多危。此是新病，不能同论也。遂用：", "12281": "按：呃逆一证，久病为胃气绝，新病形实，为伏热攻发，有胃中伤食者，有心气不舒者，须审脉证，因病施治。此案脾胃脉沉实有力，知是食停胃中，用消积攻下法，立愈。明乎治矣！", "12282": "邑北关梁姓女十七岁，患呃逆，终日连声不绝。三月内服药不下二十余帖，殊无验，延余治之。诊得肝脉弦数，脾脉虚弱。此因肝郁生热、火性炎上之故，木旺土衰。倘得肝郁一解，土不受制，何病不除！余用：", "12283": "按：肝脉弦数，脾脉虚弱。木胜克土，胃气不得下降，故呃逆终日连声不绝，翟氏重用柴胡、青皮、郁金，疏肝解郁，令其条达，解除肝木对中土的克伐，是谓不治呃逆而呃逆自止矣。", "12284": "邑西和寨王姓妇，年二十余。因天癸正行，偶逢大怒，经血遂止。至三个月时忽然鼻孔流血，复加呃逆，五日连声不断，饮食难进，奄奄待毙。他医作气上冲逆治之。均以木香饮顺气之类，无验。迎余往疗，诊得肝脉沉滞且数。此肝气郁结生热，肝为藏血之脏，肝郁而经血不下。肝热上冲呃逆者亦属火证，治先解肝郁，并凉肝血，使血下行，天癸一见，诸症尽扫，有何病魔之不除也。余用通经转逆汤，服二帖呃逆、鼻血皆愈，饮食大进，后又服五帖，经水始下，而获十全。", "12285": "西门内丁鸿宾之妻，年五十二，患呃逆月余，治之不愈，迎余往治。诊得肺脉洪大无伦。此是肺火上冲。治宜清金宁肺，一药可愈。用", "12286": "按：肺脉洪大无伦，肺火上冲则呃。以清金宁肺治之，合乎法也。", "12287": "邑北郑寨黄姓老翁，患呃逆十余日。有曰气滞者，有曰胃寒者，有曰虚火者，有曰危证者，纷纷不一，用药均无效验，延余诊治。诊得脾胃之脉沉滑有力，此乃寒痰为病，又实证也。治宜温胃祛痰。用", "12288": "邑北毛楼杨姓女，年十八，天癸二年不行，骨瘦似柴。大肉已脱，卧床不起五月矣。忽加呃逆，延余诊治。脉见鱼翔，危证也。余勉开一方，服之不效，越日而殁。", "12289": "周岗周姓子，年六龄，患呃逆证十二日，饮食难进，强食则噎而呛。他医认为食积，治之不脸。延余往疗，诊得肺胃之脉均沉迟。此是肺胃之气被寒邪凝结，不得下降之故，何食积之有？无怪乎治之不愈也。遂投温胃降气汤，一帖见效，二帖痊愈。", "12290": "按：肺胃寒邪凝结，则肺胃之气不得下降，亦能令人呃逆，是从肺胃脉之沉迟见到。知脉知证，故治以温胃降气立愈。", "12291": "邑南张山头王某，年六十岁，久病忽添呃逆。某医认为久病呃逆者死，辞不治。邀余往疗，诊得六脉虚数无力，此乃孤阳不敛，虚火冲上之故。治宜纳气归肾，引龙归海。遂用：", "12292": "按：久病脉虚数无力，脉病相符。孤阳不敛，虚火上冲致呃逆，非为绝证。故用金匮肾气汤加味，助阳以生气，滋阴以化水，使阴阳相济，水火交泰，阳不得上越，火不得上冲，呃逆则发无由，归于和平。", "12293": "余友张耀朗，舌耕士也。以劳心过度患失眠证，彻夜不眠。某医曰是心火妄动。用犀角、黄连、竹叶、石膏、灯芯之类，服数帖不效。请余往治，诊得肝脉弦数有力。经曰肝藏魂，肝热则魂不守舍，如何得睡？用宁睡清肝汤，一服见效，二服痊愈。前医云心火妄动者，诚然，惟知正治，不知隔治之妙也。", "12294": "邑内孔姓妇，六旬外，患失眠证，月余不愈。某医作阴虚治之不效。请余治疗，诊得心脉、命门脉俱虚细无力，此证乃阳虚不能济阴之故。当用阳药以济阴，使阴阳平均，自然睡熟。遂开桂附八味汤加减。服一帖无效；又投一帖，能少眠，更进二帖，竟得通宵清眠矣。", "12295": "按：是案翟氏诊得心脉、命门脉俱虚细无力，乃是心肾不能交泰，水火不能既济所致失眠证，用桂附八味汤，意在使心肾相交，水火相济，阴阳平衡，引火归元，失眠自廖。", "12296": "邑西平厂村，余瓜葛亲李姓妇，年五十外，失眠。治皆用平肝泻心火之药不效。请余往诊，左尺脉细弱无力。经曰「阴虚不寐」，此证是也。用六味汤合四物汤，服二帖见轻，又三帖得熟睡矣。", "12297": "按：左尺脉细弱无力，属肾水亏而致失眠，用六味扬合四物汤壮水制火，补血养阴，甚合病情，故服药立见功效。", "12298": "玉皇庙王姓妇，四十余，患怔忡惊悸病。自觉心中惕惕，少闻物鸣之声，即时惊恐汗出。渐至面黄肌瘦，饮食减少。三月内服药不下三、四十帖，均无效。看彼药方，大概麦冬、朱砂、清半夏、川黄连之类，意在清热镇惊化痰。诊其脉，肾脉极细弱，心脉洪数无力。此乃水亏不能济火之故。某医之治，不知抽坎塞离之法，所以不效也。余用六味汤加远志、菖蒲、玄参，服三帖有效，十帖痊愈，永不发矣。", "12299": "伯牛岗张姓，年三十余，患怔忡惊悸证。夜不安席，每闻人言物鸣，惊恐不定，神情立变，屡治不验。请余往疗，诊得心肝二脉洪数有力，察其气色，满面燥红。又问能饮水否？答曰：「善饮」。此乃肝木太旺，心火妄动。经曰：「心者，君主之官，」君喜静而恶动。按五行，肝为心之母。世间未有母害子者。此有两说焉，五行得其平者生，亢者害也。欲安国，必先除贼，贼除则君权自复。权复则令行，君明臣良，纷乱之世，化为清平，有何惊悸怔忡不除也？余用四物汤加减，服一帖微效，二帖大效，五帖全瘳。", "12300": "沈玉魁年六旬余，素有劳疾，忽加怔忡惊悸，昼夜不寐，屡治不愈。迎余往疗，诊得心脉虚极且数。此因劳心过度，心火有升无降之故。但使心火下降于肾宫，阴阳交泰，而谓通夜不能清眠者，余未信也。", "12301": "西门内赵姓，年十九，患梦遗，无隔宿。三月后面黄肌瘦，虚汗似雨，短气喘促，骨蒸潮热，饮食减少。涩精之药，服过无数，殊觉罔效。迎余往疗，诊得心脉虚数，肝脉又洪。此乃肝火过旺，心火上炎，不能下降，肾水亏极，难于上潮，成坎离不交之象。某医不明阴阳之理，若使坎离交济于肾宫，有何梦遗不除也？自制一方，名曰阴阳两交汤。四日服二帖，又遣两次。原方又服四贴，更轻。共服十贴，遗精已痊愈，以上诸虚证全瘳。", "12302": "甲申冬，挚友翟君竹亭，以所著医案见示，曰：「是编虽云成案，固不效示人以法，窃以数十年之经验，供诸同人以作参考。」且属正焉。余不精医学，虽稍涉猎医书，以未有经验，不敢出而问世。时尝聆君绪论，略知医理之大概，而临证则绝无把握，视君之富有经验，而诣极精微者，望尘弗及。对君医案，何敢妄加品题？乃既受嘱托，不得固却，览读数过，凡上、下二卷，都十七门，二百三十五案。分门别类，朗如列眉。每门总论一篇，解某种证之原理。每案叙某病之脉证与治方。不惟见著手成春之效，且公善于人，一片仁慈之心，蔼然纸上。此余所私心钦佩者也。细审其临证处方，温疫则得力于吴又可，杂证则得力于张景岳；用药则得力于景岳之左右归饮。又能于此两方中，悟出无穷妙义，化出无穷奇方，治愈无数险证。古所谓得其要者一言而终，君其然乎！且案中所治各证，有隔治之法，有从治之法，有从证不从脉，从脉不从证之法。急证则注重针砭，疮疡则注重服药。用重方则重至数两，用单方或检取一味。有变独参十枣汤法者，有改煎为丸者，有采取薰法者，有两方合用者。种种变化，临时制宜，灵敏活泼，得心应手。凡一切补虚、泻实、滋阴、回阳之剂，无不遵从经义，依据圣方。至辨别阴阳、虚实之真假处，尤为特长。诚于此道三折肱者也。尤其审辨温疫，或滋阴，或攻下，均得其宜，更见其高明过人。近时医生，不明温疫，往往以温疫为伤寒，误治者甚多。盖疫之一证，今多古少，是感天地之戾气，入从口鼻，病藏膜原。疫从役，如摇役之役，为不正之戾气所役使，故名疫，俗曰时疫是也。治法详于又可书。至于温证，按《内经》云：「冬伤于寒，春必病温。」又云：「冬不藏精，春必病温。」俗曰春温、风温之类是也。冬伤于寒之温，是寒化为温，总属于外感而得，治宜清热微带搜寒，冬不藏精之温，是耗去真阴之温，治宜养阴益精为主。可知温与疫非一证也。世多混温、疫为一，实不察之过。总之，温、疫二病，初得时，其脉证类似伤寒，最难辨别。毫厘之差，则致千里之谬，杀人最易也。以伤寒为法，法在救阳，温疫为法，法在救阴。阴阳两大法门，犹冰炭之不能相容也。君为治温疫妙手，又发明医案，公诸同人，庶医生遇类似伤寒之温疫证，知从温疫证治之，不似从前之昧昧矣。君诚医界中之功臣，患温疫者之慈航。其他男女杂证，内外各科，无不药到回春，各著明效。呜呼！君诚神乎技矣。余谨就各案，略加品评，以备一得之愚。至君之出身事略，传、序中言之详矣，勿庸再赘。", "12303": "（案1）质本阴虚，涵濡少上承之用；感由秋燥，清肃失下降之权。邪实正虚，恐愈伤而愈损；阴虚阳旺，必化火而化痰。风趁火势而益张，痰因火蒸而上扰，蕴结肺胃之经，酿成喉风之候。身倏寒而倏热，火势鸱张；咽忽阻而忽疼，毒邪蜂起。上壅呼吸之门，窃恐饷粮不济；内阻饮食之路，还虞庚癸频呼。痰嘶气逆，天气之开泄失司；溲涩便难，地道之通调失职。火炎则土燥，口随饮而随干；火盛则水亏，齿或焦而或垢。犹是燎原之火，扑灭难图；几同久旱之苗，枯憔安保？脉弦数而未得冲和，相火有升腾之象；舌光绛而又兼燥刺，阴津有立涸之虞。邪乘虚而内陷，无殊社鼠城狐；正几败而难持，岂等杯蛇市虎。于此存一线之危，而要出万全之计，不啻鳌载之重；抑同弋获之期，将投以辛温乎？乃是抱薪救火；抑济以轻清乎？亦同杯水车薪。竟委穷源，随症施治，必得泻离位之丙丁，救坎宫之壬癸，庶可汲西江之水以滋干涸之鱼。聊著病情于前，并附药方于后，浅见如是，尊识若何？", "12304": "（案1）素来阴分不足，热邪内蕴。近感风温，引动伏邪，郁蒸化火，火升而为痰，痰火上攻，逆于肺胃之脉，遂成喉蛾之症。几经旬日，仍然咽喉红肿，甚致汤水难下，项外微肿。夫咽喉为一身之总要，百脉之关头，又为呼吸之门户，饮食之道路，方寸之地，所关甚大。幸而痰来且爽，阴液未涸，犹可无虞。按脉洪数带弦，舌苔边红根腻，究系邪踞肺胃为多而未至于心营。拙拟辛凉清解佐以消痰一法，冀其邪有退避三舍之势，庶无他变之理，否则，愿夫子明以教我。", "12305": "复诊前拟清火消痰之剂，诸症仍不退舍，究系邪势鸱张，如火之始燃，难撄其势也。况体热不凉，有邪伏阳明之象，痰多且腻，是热留太阴之征。咽喉红而且肿，热邪兼挟毒邪；脉息数而带弦，风火引动郁火。经云：火者，痰之本；痰者，火之标。痰火盘踞，图治不易。骤寒则邪郁而内溃，过散则火焰而腐增。先散后溃，洵属至理。迩来大便旬不更衣，项旁肿痛上引头额，显系火性上炎风性善窜故也。风驾火威，火乘风势，风火相煽，是以扰攘无休也。既承雅招，不弃鄙陋，勉尔挥汗撰方，以为虾力行舟之助耳。", "12306": "三诊喉蛾已溃，毒邪有外泄之机；肿势渐消，痰火无稽留之患。惟喉旁尚有硬块，大便坚结，脉息细数带弦，舌质微红尖绛，此阴液受伤也。而肺胃之热究属有余未净也，斯时养阴清热以救津液，势所必需；而肠胃以通为用，养胃润肠亦不得不兼顾之。若骤进滋腻，犹恐余烬复燃，余焰复腾，合当与否？侯尊丈裁之。", "12307": "（案1）体素阴虚血少，流行之用，时逢金旺，木失畅达之机。因感风热，遂化火而化痰；阻痹少阳，致伤营而伤卫。逗留肌肉之间，酿成颈痈之候。症起未经一候，疮形已肿四围。外倏寒而倏热，营卫之调和失职；身时疼而时痛，经络之灌溉无权。肿见焮红，渐显酿脓之象；根形散蔓，未得托毒之征。脉来细数带弦，风火兼挟相火；舌色微黄近燥，热邪蒸化毒邪。口渴胃呆，癸水亏而阳土嫌燥；痰稠咳逆，甲木旺而阴金受伤。治宜辛凉清解，泄热即所以保阴；佐以顶托透邪，攘外即所以安内。既承雅招，不弃浅陋，非敢说梦，聊以解嘲。", "12308": "（案1）齿乃肾之余，龈属胃之脉。想骨槽风之症，邪深著骨，每多成漏之虞，良由元本不足，肾水素亏，外束风邪，袭入阳明胃络，乘虚而邪伏于骨，酝酿而成。据述症起二月，先自内溃，后复外穿，溃后脓秽难净，牙床骨露，甚至积成脓骨，内外肿势未能全消，此系正不托邪，邪蕴难清之故。症源弥深，势恐难以奏效。所幸者饮食如故，胃未受伤，中气尚能扶持。兹拟标本兼顾，缓缓图之。", "12309": "（案1）体素阴虚，血少循环之职；感由风燥，营无灌溉之权。阴虚则生热，蒸动花柳之梅毒，由筋骨而外达皮肤，遂成鹅掌风之候。现形肌肉麻木，阻痹无形之气；皮肤燥裂，致伤有形之血。近日来破津黄水略兼痒痛，良由阴虚内劫，鼓动花柳之余毒，熏蒸外达使然。诊脉涩而少力，舌尖红而苔黄，营阴所以受伤，即卫阳亦未能滋养。经云：阴虚生内热，阳虚恶外寒。寒热不调，乃阴阳二亏之候。症属根深，非但难以速效，且恐由虚成损，有意外之忧。兹拟调气养营顾本治主，以冀一元来复，庶期佳征。", "12310": "（案1）手背冻疮屡发，显系血因寒滞，营气失调。夫血脉营卫周流不休，寒气客于经络之中则血泣，血泣则不通，不通则卫气归之不得返。故手背疬核累累叠起，延及肩臂。经云：痈疽者，寒气之所变也。又云：寒伤形，形伤则肿。考厥病源，的系寒凝而致，但六淫之邪皆从火化，由火化毒，蕴酿成脓，致疬核次第穿溃，溃出败浆，可见元本不足，气血两亏。想无形而痛者，其阳完而阴伤之；有形而痛者，其阴完而阳伤之。乃既手背胖肿，脓多秽浊，筋骨作疼，有形而且痛。阴阳两伤，正虚则邪不能托，毒蕴难宣，如有城狐社鼠之可患。毒邪久扰，山筋而伤及于骨，血枯髓涸，致筋骨、肌肉不相营养，经脉败漏，熏于五脏。脾胃主肌肉，形羸体瘦，中气未始无伤。肝藏血，肾藏精。有形精血既亏，肝肾安保无恙乎？经云：肝肾同位，乙癸同源。水亏不能涵木，土虚不能御木。木失荣养，肝火不平，势必升腾无制，犯胃则呕吐痰涎，乘脾则腹胀欠运。虽未至谢谷废纳，而所进水谷之精养义未能化津化液，徒酿痰浊。邪气日益扰攘，正气日益消磨。正所谓邪气胜者，精气衰也。现诊脉象细弦，重按少力，舌苔黄薄带灰，质红起刺，此由阳而伤及于阴，由外而伤及于内。久虚不复，防有成损之虞。据愚见，阴阳并补，扶正以却邪。譬如君子盈庭则小人退而无位矣！慎弗专图外治而冀速效，窃恐剑关苦拒而阴平非复汉有也。拙拟候清眼裁政为是。", "12311": "（案1）乳房乃阳明所属，乳头乃厥阴所居。夫阳明，胃也。厥阴，肝也。肝失畅达，乳络因而壅塞；胃乏冲和，肌肉从此疏豁。豁则口热易入，壅则营气不从，胶固不宣，郁蒸化毒，此外吹之所由成也。初起如粟，渐大如瓜，轻按则木硬应手，重按则痛楚难鸣。看肿势而惊心，非比冰山之易解；睹红形而触日，岂同萤火之无忧。身倏寒而倏热，有火伏阳明之状；经适来而适断，有热入血室之征。肿势渐增，乳络愈形壅塞；饮食较减，仓廪又显困呆。据述症起旬日，医更数人，投消散而无功，进顶托而罔效。脉象细而兼数，舌苔腻而且黄。挹脉察舌，凭症拟方，治宜甘凉清解，泄热即所以保阴；佐以顶托透邪，攘外即所以安内。聊出数语，并附一方。理之是否？还望高明采夺。", "12312": "（案2）产后血液亏损，肝经失其荣养。肝为将军之官，其性甚急，一有不调，势必化火犯胃，阳明脉络亦从而阻遏。是以左乳木硬红肿，致成外吹之症。溃经半月有余，仍然脓水连绵，根脚肿硬，脉息细数带弦，左关更甚，舌色淡红，苔薄，中间微黄，身热纳少，头眩耳鸣，种种症情皆由营阴未复，肝胃邪热，究属有余未尽也。图治之法岂可偏废乎？若徒进苦寒解毒，非惟外疡无益，且恐胃气受伤；骤投滋腻养阴，不特余热难清，且忧余烬复然。姑拟调和肝胃，参入养营解毒一法。冀其余邪尽化，肝胃渐和，再商救本穷源之法。理之是否？候诸翁裁之。", "12313": "（案1）先天不足，少阴失封蛰之司；寒湿深沉，命门无内融之力。毒阻肾俞，小啻城狐社鼠；投治非法，无殊市虎杯蛇。㗖夫人之气血，如天地之循环不已，今为寒湿所阻，经脉壅塞，营气不从，遂成肾俞虚痰之候。穿溃以来已经月余，依然清水连绵，宛若漏卮之难塞；形容瘪瘦，几同枯木之无荣。想七节之旁，原是肾经之道路。盖肾为性命根本，藏精、藏气、藏神；又为先天真阳，育女、育男、育寿。生生不已，化化无穷，多由此而致也。乃今漏泄已久，不特技巧难出，而肝木亦失其涌濡。经云：肝木亦肾同位，乙癸同源。肾水既亏，肝木安得无恙平？迩来两足屈而不伸，时有气冲之象，则木失荣养，已露其端倪。虽胃气尚未全败，中阳犹可支持，而源远根深，图治甚难。若过投辛热，深恐阴液愈耗；徒进寒凉，更虑元阳骤脱。今将投甘温扶正者乎，抑以甘寒育阴者耶？静坐以思，必须阴阳并补，参入精血有情之品，或可汲西江之水聊滋干涸之鱼耳。理之是否？候高明采夺。", "12314": "（案2）年近六旬，阳气日就亏损。阳虚者，湿必胜。湿邪久踞，气血为之壅遏，遂成肾俞发之候。症起未经旬日，而根盘几同覆碗，木硬隐痛，皮色如常，脉息细涩欠利，舌苔淡白且腻，间有寒热。种种症情，总不外乎阳虚湿胜使然，况平素恶寒喜暖，声发不扬，下体时有酸痛，湿盛阳浮已露端倪，以脉参症，深恐难以消散，拙拟和阳利湿兼谓调气血一法。冀其移深居浅之意，愚见如是，未识当否。", "12315": "（案1）燎原之火本不可向，兹因失火焚山肆横无制，当局者能无忧危之心哉？忧心一起，竟忘生死之关，强绝其源，被火燃伤，焦头烂额。原属好肉，做疮本无内症，但迩来增寒壮热，大便秘结，脉息沉数带弦，舌色尖红，中焦间有神昏。想胃主肌肉，肺主皮毛，邪伤肌表，肺胃内应，是以兼有咳嗽气急，口渴烦闷等症。经云：火盛生风，风驾火威，火乘风势，风火相煽。深恐内窜心营，姑拟清营解毒兼通地道一法，冀其釜底抽薪，庶免内陷之虞。", "12316": "（案1）性本操劳，阳气先衰于平素，端由火毒，阴津复损于当时。夫人之气血周流不息，兹为毒邪所害，难免腐烂之虞，是以有烂皮疔之患也。症起未经旬日，而疮形已有尺余，此处属阳明之脉，阳邪攻于阳经，即所谓两阳相灼矣。故其烂可立而待也。脉浮洪而且数，邪势方张；舌焦黑而尖红，营阴几劫。身热口渴、谵语神昏皆由是而蜂起，势已重极危险无疑，而图治之法最难恰当，况用药如用兵，得则其兵也，不得则其寇也。若投轻清解毒，无殊杯水车薪；妄用辛热驱邪，不啻抱薪救火，必得大剂清营解毒，以为背城借一之计。", "12317": "（案1）疽名偏脑，原是火毒之疡。经属膀胱，曾为寒水之腑。夫脑疽一症有内因外因之异，有正轻偏重之殊。由六淫外感者轻，从五脏内发者重。外感者多生于正中，内发者每起于项旁。疽生偏左，非内因而何？所谓内因而成者，其源有五：或由心绪烦扰，煽动不宁，以致火旺而沸腾，行于项间与寒水交滞而成者；或因恼怒伤肝，项乃三阳统筋之所，肝伤则血脉不朝，筋失荣养，凝滞为肿而成者；亦有思虑伤脾，脾伤则健运失职，营气不从，逆于肉里而成者；又有恣欲伤肾，肾伤则真阴之气败，真阴一败，相火即生，亦能致此。仰屋图维，良由操劳过度加以情怀不畅，则肝胆之火勃动于中，逆于太阳之脉，与内蕴湿邪熏蒸化毒，遂成斯症耳。迄今几经二旬，仍然木硬漫肿，根脚色紫甚，至浆水稀少，间有嗳气，脉息沉数少神，舌苔淡白根腻，以脉参症，显系正虚邪实，一时不能托邪外达而然。年尊得此，深恐难以支持。拙拟扶正却邪，标本兼顾一法，冀其裂缝来浆，根盘收束，庶几有安澜之庆，否则虑有意外之变。拙见如是，未识尊意若何？", "12318": "二诊前拟扶正却邪之剂，痛势稍缓，浆水渐来，似乎有见松之象，但根脚犹硬，毒邪有盘踞之征。新腐未分，元气少流行之用，正虚邪滞，非已露其端倪乎？大凡外症正重偏轻，独有脑疽正轻偏重。尝阅吴鞠通论云：正属督脉，督脉为纯阳之经，起于尾闾，贯脊而上，毒气乘之，每能外达，故高肿易腐，为易治之症也；偏属太阳，太阳为寒水之腑，始于晴明，夹项而下，邪气客之，最易内侵，故平塌难腐，为难治之症也。况七旬之高年，困一月之大患，末学浅陋，而欲借著代筹，计出万全，不啻鳌戴之重矣。而干旋之法最难洽当，使徒进苦寒，恐犯虚虚之戒；而专投滋腻，难免实实之忧。兹拟此方必欲两不相害，或可挽扶中流之砥柱，挽既倒之狂澜。是以聊释症情于前，杂配药方于后，然欤？否欤？请君政之。", "12319": "三诊脓水虽多，而疮头塌陷，红肿蔓延，脉息右部少神，左关弦数，究系近增郁怒，肝火妄动，挟毒肆横之故。古稀患此，岂可不深虑乎？夫人之体，有虚亦有实。以言乎高年，其实也与哉？其虚也，虚则精神日馁，元气就衰，使治匪根源，不啻杯蛇市虎。抑症有轻亦有重，以念夫偏脑疽，其轻也与哉？其重也，重则毒邪逗留，纠缠不已，觉邪踞经络，无殊社鼠城狐。假令邪实而正未亏，犹可用三黄解毒以衰其势也。何虑乎毒邪鸱张而扰攘无休耶？假令正虚而邪已净，便可投十全大补以扶其本也。何虑乎元气亏损而流行不健耶？兼之传道之官恒固守，庚金不及生扶，而仓廪之令有专权，戊土却能化育。不然则中流乏砥柱坐镇，将何所恃而不恐？", "12320": "（案2）质本丰腴，湿邪逗留，可见性情急迫，郁火内蕴无疑。况节届天中，正当阳气大泄，湿热升腾之候，偶感时邪引动蕴蓄之湿化火，毒逆于太阳之脉，致令升降失调，遂成偏脑疽之症。盖疮头塌陷，毒邪开盘踞之端，根脚旁流，火毒有肆横之兆；四肢清冷，阳虚而表不固也；五志昏蒙，邪盛而神无依也。症既如是，安能无内陷外脱之虞哉？如其不陷，则君主灵明，心神内守。焉能有神昏妄语？安有自汗肢冷之症欤？以七旬之高年，困一月之大患，何堪支持？末学浅陋，而欲借箸代筹，计出万全，不啻鳌戴之重矣。但死生虽有天命，医治聊尽人工。勉拟—方，以冀万一。", "12321": "（案1）症起多年，显系沉寒之疾。疽名附骨，原是痼冷之邪。背如鳖背，督脉已露其虚端倪；胸若鸡胸，仟脉自形其损象。脉息虚而少神，先天已经告惫；饮食少而欠运，后天未常非亏。形羸肉削，由于元气之难荣；膝屈筋伤，不外营阴之失养。脓水连绵，宛若漏卮之难塞，皮肤枯槁，几同败鼓之无修。邪踞筋骨，无殊社鼠城狐；病入膏肓，谁曰杯蛇市虎。深察症情，不独身躯生废；参究脉理，且恐性命难全。拙拟固本之方，聊为延年之计。", "12322": "（案2）据述，病情自去年七月间，左股先觉隐痛，不红不热，皮色如常，延至冬底，穿溃，脓水清而且多。静思其故，显系寒湿深伏筋骨，致成附骨疽之候。穿溃以来，屈指已经半载，仍然脓水连绵，疮口细小，形羸肉削，饮食少思，按得脉息细数少神，舌色淡白。夫细为气虚，数为血虚，舌苔白。中气已惫矣。症情一派虚象，非补不宜。拙拟调养气血兼救胃阳一法。", "12323": "（案1）毒阻育门，气血之循环莫展；邪壅脉络，太阳之道路难通。无怪乎下搭手之所由生也。根脚红而兼紫，毒邪开盘踞之端；疮头硬兮且疼，营气有稽留之兆。是以外则浆水稀少，内则呕恶烦冤，前则溲溺赤热，后则地道不通。表里俱不宣畅，邪热无从开泄。炎蒸不熄，不但疮口腐烂，且恐有内窜之忧。兹拟清解火毒兼通地道一法，冀其毒邪渐退，大便堪通，庶无意外之变。", "12324": "（案1）据述去春偏中以来，左足臂俱不能用，肌肉不仁，痰多言蹇，显系不足，下元痰火中络之候。至今春来复中之后，左肩忽觉红肿，疮头延烂。此是肝火挟痰上扰，逆于太阳之脉，阻遏营气，郁蒸化毒，遂成上搭手之候。刻下腐肉虽脱，而根脚仍然紫硬，不觉疼痛。脉息细数带弦，重按殊无神韵，舌质光绛且干，气急自汗，种种症情良由痰火久踞，元气愈虚而阴液愈损矣。高年患此，岂可不深虑乎？即承雅招，不弃鄙陋，勉尔挥汗撰方，冀其一阴得来复之机，元气有生振之兆，庶无意外之变，否则虑其虚脱。", "12325": "红形已退，毒邪有宣化之机。新肉齐生，气血得流形之用。脉和缓而且匀，痰火亦似乎下降。舌淡红而潮润，胃津已得以上乘，仓廪之令有专权；戊土却能化育，传道之恒未失守。庚金尚得升扶，惟寤寐少宁。身躯仍难以转侧，语言蹇滞，手足犹不能举提，究系津液素虚，加以痰火久扰，脓浆大溃，则虚者愈虚，不能内济心阳以安其宅，外灌百脉以利机关也。况元虚挟痰挟火之体，图治极难。若过投降火消痰，犹恐虚虚之戒；骤进滋阴扶正，且忧实实之候。兹拟补而不滞之方，冀其阳生阴长，坎离既济，则心君泰然而百体从令矣。即外疡亦不期愈而自愈矣。", "12326": "（案2）体素阳虚，湿邪内蕴，平居劳碌，郁火恒多。湿邪阻于太阳，气血之循环莫展；火毒壅于脉络，营阴之灌溉失司。火因湿而愈炽，湿得火而更张，湿火交结于肺俞，疽名遂成上搭手。据云症起未至一旬，而疮形已经数寸，黑烂无休，恐犯三陷之局；红霞散漫；尽有肆横之征。肌肉不仁，正气失流行之用；浆稀水少，脓毒开盘踞之端。脉细数而带弦，虚火更兼实火；身微寒而兼热，湿邪且挟风邪。大患缠身，颇为棘手。虽未呕恶神昏，形其恶候而已见。疮平根散，渐露凶端，宜未雨而绸缪，毋临渴而掘井。必得扶正却邪，标本兼顾，庶乎渐臻康泰矣。弟愚粗暗方书，稍明药性，命含毫而施治，勉濡笔而撰方，愧拙陋之无能，候高明以斧政。", "12327": "（案1）寒凝脉络，少阳之道路难通；湿阻肌膜，气血之循环莫展。寒邪乘气血之窒碍，盘踞筋骨；气血因寒邪之扰攘，堵塞流行。盖六淫之邪皆从火化，即《内经》所谓：阴极生阳，寒郁为热，热甚肉腐为脓。此环跳疽之所由生也。据述症情起自胎前，溃于产后。针溃以来，屈指已经二月，犹然脓水连绵，无殊漏井；形躯瘪瘦，宛若枯蔗。甚至数孔相串，转侧艰难。况饮食少思，中气已经告惫；翻覆不已，余邪犹未全消。身热脉弦。由真阴之下竭；耳鸣头晕，属肝阳之上浮。仰屋图维，良由产后营阴大耗，加以脓水久溃，则虚者愈虚而肝阳愈旺矣。兹拟阴阳并补，参入熄肝养胃一法，俾既伤之津液缓缓回生，使已败之精神徐徐恢复。庶几其旋元吉，否则虑其虚脱。愚见如斯，尊意若何？", "12328": "（案2）体质向亏，旧岁适逢妊娠，则气血愈虚。血虚则涵养失令，筋脉从此不舒；气虚则外卫不周，寒湿因而侵袭。内不得入于脏腑，外不能越于皮毛，凝于骨髓之间，阻于少阳之脉，致使营卫欠流行，经络都阻碍，如土之堵水，石之投泉，积久不化，致延成环跳疽之候。迄今已越二月，仍是脓水淋漓，状若漏卮之难塞；根脚板硬，犹是石硬之无情。兼之疮孔深远，时觉疼痛。想此处系少阳之过脉，盖少阳相火内寄，又为多气少血之经。经云：气有余，便是火，火炽则痛，血不足则肌肉难长。故取效如斯之难也。至于头眩耳鸣，肝阳有上僭之势；胃呆纳减，戊土乏冲和之权。况乎身热若潮，阴分早显其损象；腰疼如折，八脉已露其虚端。按得脉象细数而少神。夫细为气虚，数为血虚。少神者，元气不足也。舌苔淡而尖绛。尖绛者，津液已伤也。症情如此，难治何疑。勉拟阴阳两顾兼参清营养胃一法，俾得阴阳有来复之兆，胃气复生振之权，庶无意外之虑，否则深恐鞭长莫及矣。然欤？否欤？还望质诸高明。", "12329": "方用首、地以养阴，又取参、术以壮气。一阴不足，赖元母以扶助；八脉空虚，藉归、龟以调剂。欲肝阳之潜伏，非钩、菊而不能期；胃阴之上承，无斛、谷而难济。山药甘濡，肾弱所宜。杜仲甘温，水亏当取。媲茯神以定志，寤寐自安；配莲肉以清心，虚热自能去。略考十剂之方，聊仿七方之意，并方案统希教益。", "12330": "（案1）风温外袭，肌肤失周流之度；痰火内蕴，肺胃失清降之权。脉洪数而带弦，火邪方炽；苔老黄而尖绛，阴液已伤。是以咳嗽欠爽，痰稠如胶。虽已针溃而根脚仍然木硬，甚至肿延胸胁，焮红疼痛，寤寐不安，间有神昏，此系肺胃邪热渐欲入营之象。高年患此，甚属棘手，姑拟大剂清营解毒兼化痰火一法，以冀弋获。", "12331": "（案1）体归阳盛，诚为松柏之资；质本阴虚，未得涵濡之用。况乎权操国政，地僻事繁，条教所施，悉本精神所注。即使节性提躬，怡情静养，犹惧不济，而复加以湿温久扰，则虚者愈虚，余湿不能尽化，注于会阴之间，酿成肛痈之候。起经两月有余，仍蔑一毫之效。根脚仍然木硬，脓流状若漏卮。脉细数而带弦，肝阳失潜。舌微黄而根腻，湿热未清。想下焦为深远之乡，药力难至；肛旁乃至阴之域，气血罕来。此虚处患症，不特难期速效，抑且有成漏之虑。幸而胃气无伤，中流犹可支持。附骥芜词舜臣翁教政。", "12332": "（案2）一诊症起略有半年，翻覆已经数次。静究其源，总由正气衰惫，余邪不宣化耳。想肛旁属太阳，与少阴肾相为表里。盖膀胱为聚湿之腑，少阴乃藏精之脏。此处生痈，每多翻花。况乎质本阴虚，肝肾早失涵濡之用，加以宵旰勤劳，以绥安黎庶，则虚者愈虚，余邪更难宣化矣。是以疮口不能痊愈，时有头晕气冲之患，按脉虚弱少神，左关独见弦象。以脉参症，日久根深于此，而谓能骤愈者，非也；于此而谓莫能愈者，亦非也。必得大剂穷源固本，阴阳并补而复深于涵养之功，以冀气机流畅，精血两充，自克渐臻康泰矣。复方呈政。", "12333": "二诊前拟阴阳并补一法，福体稍强，新肌略长，头晕气冲之患亦见渐平，此乃正复邪退之兆也。刻按脉息细数犹见少神，左关仍留弦象细数者，余邪未净也；少神者，元气未充也；带弦者，肝阳未熄也。度势揆情，总不外劳心所致耳。经云：君火一动，相火随之。二火频升，一水不能相济耳。虚体患此，奏效最难。非难以敛其疮口以治其标，实难以复其真阴，以固其本也。若夫徒进辛温以补气壮气，即以助火；专投滋腻以养阴，一阴不能自生，必得阴阳并补，庶乎阳生阴长而无偏胜之虞矣。仍宗前策增损，须臾更张，未知有合于尊意否耶。", "12334": "（案1）肺主五脏之华盖，出声音而泽逮皮肤；又为百脉之朝宗，通呼吸而权归清肃。若元气自强，皮毛固密，纵有客邪，安能内侵？尤如暗室潜修，阴液早伤于平素；风尘劳瘁，风温复感于今时。以致肺机不畅，降令失权，酿成肺痈之患。于兹半月有余，蔑一毫之效，痰涎漉漉，咳嗽频频，或脓或血，时秽时腥。中府时觉隐痛，左卧常叹不宁。脉右大而左弦，肝火有上升之兆；舌微黄而尖绛，肺津无下降之征。必须畅彼情怀，济以药饵，庶乎渐臻康泰矣。第愚粗谙方书，稍明药性，命含毫而施治，勉濡笔而撰方，愧拙陋之无能。候尊翁以斧政。", "12335": "二诊前进肃肺清金兼熄肝阳一法，身热稍和似有转机之象，但痰多气急，金府之右降失权，肋痛头眩，肝垣之左升太过。脉左弦而右大，邪热未平；舌边绛而中黄，阴液暗损。假令胃阳受伤，子母少相生之力，大便溏泄表里无相助之能。幸而仓廪之令有专权，戊土恰能化育；传道之官恒固守，庚金尚得升扶。据云夜寐少宁，此非胃不和而卧不安之理，良由肝阳之未静，肺火之难清耳。《内经》云：肝热则魂不归舍，肺热则魄不归藏，即此之谓也。面带萎黄，湿邪未化。口不燥渴，蓄饮内留。仍清肃太阴以冀余邪之宣化，加以安舒静养，可望肝火之渐平。非敢说梦，聊以解嘲。", "12336": "（案1）漏蹄风，由风湿下注，气血稽留，筋脉失荣而致，迄今一载之久，依然反复不已。口僵孔深，有妨步履，症源弥深，难许脱体。拙拟方，以为虾力行舟之助耳。", "12337": "（案1）症起先咳后胀，由肺及脾，脾主运化，脾病则消磨失职，饮聚于中土，虚不能安木。肝木乘隙而侮，中气欠和，是以肠鸣作泻胀痛交加，显系肝脾不和之故。想肝脾为仇雠之藏，风木主令，客气少阳，厥阴少阳同司相火，相火扰动，内引浊饮上升，营卫留止，厥气逆上，真邪相攻，此胀痛所由来也。现下常咯浊饮，胀痛仍不能和，甚则痛引腰间，下连少腹。肾亦未免暗伤，非但脾土失调，肝肾亦为同病。经云：肝胀者，胁下滞而痛引少腹；肾胀者，腹满引背央央然。腰骱作痛，症形与经文相符。诊脉细弦而近数，舌苔薄而根带腻白，此脉之数乃系相火扰动，作邪热之相干，恐其木旺无制上犯阳明，有呕逆胃呆之虞。拙拟温脾肾佐以平肝，非敢过投燥热反动其阳耳。附方候高明裁之。", "12338": "（案1）夏暑伏中，秋凉束表。暑为阳邪，而其中又挟阴湿，蕴久势必蒸热。所谓六淫之邪皆丛火化也。是以初起畏寒，继即发热，昏烦不卧，脘闷口干，此旧湿挟新凉，交蒸氤氲于气分，胸中之清气被蒙。虽得屡进宣解而汗出不畅，白㾦隐而不明，甚则讝语躁扰，便结脉沉，此由气分之邪不得从汗而解，势必致蕴结于中，症颇棘手。拙拟外解内清，表里两治，预防痉闭一端，附方侯政。", "12339": "（案1）质本阴虚，营分少以充养；体偏阳旺，相火未得安宁。夏令炎炎，正值暑邪用事；热蒸勃勃，何堪炎帝加威？暑或挟风，因风而熏蒸转速；暑必挟湿，因湿而宣解殊难。真阴既少内涵，时气未免外感。先伤肺胃之地，渐入营卫之间。身热口渴，少火悉成壮火；神昏肢痉，心阳扰动肝阳。白㾦明而红疹续现，由气分渐入营阴；舌苔燥而脉象甚弦，损胃津亦伤肾液。夜不安寐，坎离无以既济，胸时潮闷，营卫尚有余邪。咳痰红而气逆，金受火刑；齿垢黑而便难，火炎土燥。阴虚阳亢，一阴何以滋荣？邪盛正伤一症将安固守？症形危笃，防有内闭外脱之虑，治必探源，庶几夺命斩关之兆。浅见如是，尊意若何？", "12340": "（案1）高年冬令，下痢赤白稀艰。轩岐称曰：滞下明是内伤不足之候，而不知不足中有余湿也。前诊脉左弦右涩，舌厚腻中灰，肢倦少寐，溲涩胃呆。考厥源委，半由于积劳损于前，肝脾不和，是病之本；半由于湿邪困于内，消磨失职，是病之标。经云：中气虚则溲便为之变。又云：胃不和则寤不安。即此之渭也。拟用香砂枳壳佐以和胃平肝，标本兼顾。曾得便下燥矢数粒，小溲为之通利，大便为之调和，饮食知味，舌中灰腻较除。一症而见此数善，诚为佳征。但肝脾为雠之脏，又脾胃为表里之腑。诊脉弦象较和而带虚数，纳食不当，寤寐不安，耳鸣肚痛，此脾胃阳气不足，肝肾相火不冲，有余未尽之湿尚留于肠胃曲折之间。现今冬为藏阳之令，少阳相火在泉，乃阳气既受其困而真阴又属不足。若因脾胃柔脏，过用刚药，窃恐土燥木虚，有由脾及肾之虑。譬如剑关固守而阴平非汉有也。转展无可借箸，勉拟和胃扶脾调补肝肾，俾中阳动则冀运，相火静可望藏。王道无近功，宜抚安以缓图其效，附方以备采择。", "12341": "（案1）体素三阴不足，湿蕴未清，相火未能静熄，湿因火而上升，熏蒸化毒，致头面叠起湿毒，如蔓缠扰，一时难以宣解，奈因猛药强绝，遏其外泄之机，蕴而难化。想湿为黏腻之邪，其性下流，乘下虚而注于肝肾，遂致少腹作胀，溲涩欠调，变成淋浊，继而遗精。盖淋在浊窍，遗在精窍。浊窍不开则精窍为之不固矣。是以症见如此。自前秋至今春，精浊混来如漏卮之无底。现诊脉沉弦，未甚虚弱，舌尚腻而未清，小溲时赤，赤则精遗转甚，寐多梦扰，精力日衰，的系漏泄多月，有形精血受损，无形神智欠安。以脉论症，由外而至于内，由实而挟于虚。图治最难洽当，将以填精固本乎？而滋腻犹恐碍邪。将以利湿去邪乎？而淡渗又虑伤正。必得竟委穷源，两无妨碍。慎弗任朝章言热，暮李论寒，补泄杂投，致有药伤之患。夫精之藏，制在肾；而精之主宰，则在心。乃既精泄已久，阴失固守，阳少潜藏，水亏不能济火。经云：君火一动，相火随之。又云：阴虚者，火自旺。君相二火兼升，定然余湿内蒸，摇精而泄也。欲强止焉，恐不能也！据愚见，宁心坚肾，育阴潜阳，仿金匮八味主治。再得怡情静养，勿劳神智，庶望安澜。录方候高明裁正为是。", "12342": "（案1）咯血屡发，甚于春分。显系阴失固守，阳失潜藏。当春厥阴司令，客气又属少阳，厥阴少阳同司相火，二火升腾，辛金未免受克，此咯血所由成也。但诊脉细弦，右寸关独见弦大。舌边尖色绛，中苔腻黄，面色滞而不开。右胸时觉胀闷，知饥纳食不调。此肝肾之真阴不足，而肺胃之痰热未清。虚在下而实在上，图治甚难。古人谓：二虚一实，先治其实，因去邪即所以扶正也。据愚见，清理肺胃主治，俾养金即所以制木，和土即所以安木。火不妄动而血自安宁，何患红痰之不止哉？虽然，病经一载，翻覆再三，有形之精血受伤，药饵恐难奏效耳。附方，候高明裁之。", "12343": "（案2）肝肾之阴素亏，脾胃之痰素盛。病自秋徂冬，屈指已越三月。形寒形热，乍往乍来，阴阳交错，营卫交乱，正气如何维持？津液如何敷布？君火炽旺，相火炽动，神为不宁，魂为不藏。加以触受惊恐，遂使神志混淆，寐不安稳，错语喃喃，手有振动，肢末掣掣，肝胆之风阳走入经络，脾胃之湿痰扰及清灵。左手脉弦细而劲，右手脉数细而滑。舌尖燥绛，舌中干白。风胜则津干，热胜则液涸。肺失清肃，胃失濡养。现在幸无汗泄，阴阳尚有枢纽。转瞬冬至大节，恐有一番剧烈，治法甘凉，承津养液，参用介类潜阳育阴法。", "12344": "（案1）邪之所凑，其气必虚。卒然倾跌，神识不清，口眼㖞斜，语言謇涩，溲赤而浑，苔黄而厚，脉来沉数。阴亏水不涵木，七情郁结化火，风邪乘袭厥阴，横扰阳明。目为肝窍，胃脉挟口环唇，肝在声为呼，胃受疾则哕，诸汗属阳明，谨防呃逆鼾呼大汗。拟玉屏风散升麻葛根汤二方加味，外以桂酒涂颊。", "12345": "昨药后，夜来神志渐清，语言渐爽，黄苔渐腐，身有微热微汗，大解一次，溲转浑黄，沉数之脉依然，口目㖞斜未正。证本阴虚火盛，情志乖违，腠理开疏，为风所袭，扰乱厥明之络。原方加减，仍以桂酒涂颊。", "12346": "厥阴为风木之脏，阳明为十二经脉之长。真阴素亏，肝木自燥，木燥召风，虚风直袭，攻其无备，是以卒中之也。连进玉屏风散升麻葛根汤二方加减，神识已清，语言已爽，饮食渐进，身热得微汗已解，大便如常，溲色较淡，黄腐之苔渐退，沉数之脉亦缓。惟口目仍斜，风淫未尽，真阴未复。原方加减，仍以桂酒涂颊。", "12347": "诸恙悉平，惟口目之斜较前虽好，未能如故。口目常动，风生故焉。耳鼻常静，风息故焉。肝气通于目，胃脉环于口，必得肝胃冲和，口目方能平复。原方增损，仍以桂酒涂颊。", "12348": "恙原已载前方。惟口眼仍斜，未能如故。肝为藏血之脏，胃为水谷之海。症本血燥召风，风翻胃海，气脉为之动变，霾曀上冒清空，分布不周于本络，以故口目㖞斜，斜乃风之象也。服药以来，风淫虽解未尽，阴液虽复未充，气脉未能流畅。水能生木，土能培木，当以脾肾为主。拟六味归脾加减为丸，以善其后。", "12349": "（案2）年近七旬，天令暴冷。炉火左侧，太白频浮。酒渍于内，热炙于外。左颊汗出如浆，虚风得以乘之，扰乱三阳之络。口㖞于右，目眇于左。脉来浮数，按之则缓。拟玉屏风散二陈汤加味以辅正散风。是否，候酌。", "12350": "叠进玉屏风二陈加味，左颊之汗已收，口目之斜俱正，浮数之脉已缓。风淫已散，第因年高，二气本亏，是以风邪易袭，宜常服十全丸，以杜未来之患。", "12351": "（案3）遍身麻痹，口目蠕𥆧，眉棱骨痛，按之益甚。年逾四旬，形丰脉软。风袭阳明，营卫俱伤，血凝气阻，名曰肉苛。慎防倾跌。", "12352": "经以营气虚则不仁，卫气虚则不用，营卫俱虚则不仁且不用，肉如故也。服补中益气加味，半月以来，苛痹渐苏，𥆧动渐止，营卫风淫渐散，眉棱骨痛已平，软散之脉已敛。胃者卫之原，脾乃营之本。升补中州，以充营卫，前贤良法。原方加减，为丸缓治。", "12353": "（案5）形充脉弱，气歉于中，分腠不固，常多自汗，为风所引。肾水上泛，脾液倒行，凝滞成痰，隧窍阻塞。卒然昏聩无知，气促痰鸣言謇，舌苔白滑，胸次不舒。木旺金衰，正不敌邪，防其汗脱。", "12354": "正气散护卫外以祛风，六君汤益中土以清痰。服后神识已清，夜来安寐，身热退，自汗收，舌强和，痰声息，脉弱起，邪退正复之兆。惟右肢苛痹，乃偏枯之象。证本脾肾双亏，气虚夹痰，分布不周，风淫末疾。前方加减为丸缓治。", "12355": "（案6）二气贯于一身，不必拘左血右气。偏枯于右，痛无定止，逢阴雨烦劳益甚，乃风痹之属。延今二载有余，脉沉涩无力，食入作呕，大便恒溏。风淫于胃，湿著于脾，分布不周于脉络，致有阴阳易位、更虚更实、更逆更泛之患。外以晚蚕沙煎水洗患处。", "12356": "（案8）曾经伤风，咳嗽痰多，渐至步履欹斜，语言謇涩，痰涎上溢。三载以来，痰嗽由渐而止。现在涎唾不禁，舌蹇难言，身形强直，脉来弦数。肾阴素亏，子窃母气，肺损于上，为风所引，传之于肝。肝主一身之筋，筋弱不能自收。肝复传之于脾，脾伤则四肢不为人用。脾复传之于胃，胃缓则廉泉开，故涎下不禁。所服之方，都是法程。寡效者，病势苦深也。长沙云：病势已成，可得半愈；病势已过，命将难全。勉拟一方，以尽其心力。", "12357": "（案1）舌强语言謇涩，右臂麻木不舒。言乃心之声，赖肺金以宣扬。脾主四肢，其用在右。心火盛，肾水虚，将息失宜，五志过极，湿土生痰，机窍不利，脉来三五不调，类中复萌已著。理阳明，和太阴，佐化湿痰，不致阴阳离决，方克有济。", "12358": "类中复萌，舌强言蹇，右臂屈伸不利，心火暴甚，肾水虚衰，智意不和，湿痰阻窍，本拟泻心法，缘脉来甚慢，如结代之状，尺部尤甚。仍从中治，理阳明，和太阴，亦可保其心肾。", "12359": "两进理阳明、和太阴、佐化湿痰，舌强渐和，语言渐展，右肢麻痹亦舒，胸次反觉不畅。清涎上溢，湿痰未化，心火未平，脉仍三五不调，未宜骤补，原方加减。", "12360": "病原叠载，前方服用以来，舌强渐和，语言渐爽，肢痹已苏，胸次渐畅。经以心脉系舌本，肾脉循喉咙、夹舌本，脾脉连舌本。太阴不营，湿痰自生，肾水不生，心火自盛，必得三经平复，水升火降，中土畅和，机窍自展。现湿土用事，肝火司权，暂以桑麻六君加味，崇土养营，和肝熄风，引益肾水。", "12361": "（案2）偏枯于左，口㖞于右，舌强语謇，涎下不禁，脉来甚慢。大筋软短，小筋弛长，湿热不攘，中虚痰郁为患。", "12362": "（案4）《经》言阳之气以天地之疾风名之。卒然昏聩无知，柔汗，溲便遗失，四肢不收，口噤不语，脉来迟缓。因烦劳太过，扰乱二十五阳。阳气变动，气不归精，精无所倚，精不化气，神无所倚，乃阴阳离决之危候也。勉拟景岳回阳饮，追敛散亡之气。未识阳能回否。", "12363": "午正进药，申未汗收，神志渐清，语言渐展，肢体自能徐转，脉象小驶于迟。惟心烦意乱，莫能自主，乃阳回阴液未复。进锐退速，危症得安，乃天幸，非人力也。", "12364": "阳回阴液未复，心中愦愦不安，肢体虽和，语言尚謇，脉小驶于迟曰缓。《经》以无阳则阴无以生。连进回阳生阴之品，颇合机宜。安不忘危，善后更宜加意。", "12365": "（案8）素耽酒色，心肾本亏。精损于频，气伤于渐。卒然神志沉迷，口眼㖞斜，语言謇涩，慎防汗脱。脉来微细如丝，当从色厥论治。", "12366": "生脉散加熟地、山药、山芋、制附子", "12367": "（案9）《经》以暴病暴死，皆属于火，火性疾速故也。卒然昏聩无知，脉象洪空，劲直口开，手撒遗溲，自汗，痰鸣，气促。真阴枯涸，心主自焚。五绝之中，兹见三证，虽司命不可为也。所议人参竹沥苏合香丸极是，愚见更益以镇固之法，以副或免之望。", "12368": "（案1）伤寒恶寒，寒伤营，血涩无汗，皮肤闭而为热，头身腰背俱痛，脉浮紧，溲色澄清，大便五日不解，尚属太阳经症。宜麻黄汤。", "12369": "（案2）苔白脉浮，巅痛身疼，恶寒发热，溲便自调，痰溲气促，有汗不透。风寒两伤，营卫俱病。法宜解肌兼汗。", "12370": "（案3）发热恶寒者，发于阳也。巅痛身疼，无汗，苔白，胸痞，脉象浮紧。宜先开其表，遂取九味羌活汤。", "12371": "（案4）脉体尺寸俱浮，证势头身俱痛，翕翕发热，啬啬振寒。禀赋虽充，寒邪甚厉。星驰无寐，二气乖违，正逢月郭空虚，遂罹霜露之疾。谨拟南阳败毒饮，祛邪返正，得汗便解。", "12372": "（案1）气虚脉虚，身热恶热，烦渴，巅痛，神倦，火盛乘金，热伤元气，古名中暍。寒以取之。", "12373": "白虎汤、生脉散加淡竹叶、卷心", "12374": "（案2）暑必夹湿，气之熏蒸，著而为病。湿寄望于四季，随六气之变迁，因暑而为热，伤阴伤气，神倦脉软，身热自汗，恶风口渴，溲便自调，不思饮食，心脾肺三经互病。拟东垣清暑益气略为加减。", "12375": "（案1）脉来滑数无力，证本湿热伤阴，五液日耗，形神慵倦，竟若骨痿不能起于床。法宜补阴化湿。苦寒虽效，究非常服之方，拟甘露饮加减。", "12376": "（案2）湿热蕴于阳明，熏蒸肝木，耗损肾阴。肝主一身之筋，肾统诸经之水，阳明为十二经脉之长。譬如暑湿郁蒸，林木萎弱，以故体倦多眠，热蒸气腾，上干清窍，唇疡流液，目涩羞明，颊肿咽痛，苔黄舌绛。服养阴渗湿之品共六十余帖，病势退而复进者，证延六载之久，药浅病深之故也。仍以补肾渗湿为丸缓治。", "12377": "（案1）第二日，憎寒发热，头痛，腰背俱痛，苔白，溲赤，无汗，脉数。邪伏膜原，外越太阳经也。", "12378": "第三日，恶寒自罢，昼夜发热，日晡益甚，头身之痛较轻，眉棱骨痛甚，鼻干，不得卧，苔白，汗出不透，脉洪长而数，溲浑而赤。伏邪外越，阳明经腑不和。不致神昏呃逆为吉。", "12379": "第四日，得汗虽透，热仍不解，反觉憎寒，目沉不寐，心烦喜呕，胸满胁痛，苔淡黄，溲浑赤，脉弦数。伏邪并交少阳阳明。小茈达原加减。", "12380": "第五日，烦呕稍减，夜得少寐，寒热依旧，耳聋，胸满、溲浑赤，脉弦数。原方加味主之。", "12381": "第六日，昨进小茈达原饮加减，服后大解一次，色如败酱，浑赤之溲较淡。夜寐稍安，四更后心烦作呕，饮陈米汤，少倾即止。天明自汗，身热乍退，唇燥舌干，脉仍弦数。伏邪渐溃，阴液耗伤，虑生歧变。", "12382": "第七日，热退脉不静，大便如败酱，溲浑如豆汁，夜寐不沉，胸痞不食，心烦作呕，舌燥作渴，苔黄不腐。伏邪化热伤阴，最忌神昏苔剥呃逆之剧。", "12383": "第八日，脉数，便未解，溲反浑近赤，额前心下俱热，有汗，肢微冷，苔黄，舌尖赤微有刺，口燥作渴，反喜热饮，神烦少寐。邪伏少阳，倒入阳明，化热伤阴，热极反兼寒化肢冷。大便不解，腑气不通，邪无出路。原当承气，下结存阴。二气素虚，姑从缓治。", "12384": "第九日，服药后更衣两次，色黑如漆，中有瘀血，额前热退，苔剥回润，烦渴减，四肢和，夜寐安，数脉缓，溲色渐淡，苔黄渐腐。伏邪赖腑气宣通而渐化。后阴为里之表，邪伏膜原转入阳明，由大肠传送变化出焉，其路甚近，与表邪从汗解之意。同故，大便解，诸症减；大便秘，诸症加。六淫在表，当从汗解；伏邪在里，当从便解。攻下与发汗何殊，伏气与表邪一体。胃为多血之腑，脾为统血之脏。便黑带血，胃热迫血，流入大肠，病及至阴，脾伤失统。虑其大便复闭，阳邪复聚，仍以养阴通腑。", "12385": "第十一日，两进养阴通腑，登圊三次，色紫黑有块，纯是停瘀。诸症悉除，宵眠呼吸自若，醒后神智安舒，知饿思食，身凉脉缓。惟溲色犹浑，胸前尚热。余气未尽，伏邪解于血分，真阴五液俱伤。在内为血，发外为汗，汗即血也。病从血下而瘳，犹表邪随汗而解。后阴为里之表，于兹可见。遂补阴益气，以善其后。", "12386": "（案2）始得病，不恶寒，发热而渴，溲赤不寐，服发表消导等剂，汗不出，热不退，延今四十余日。形容枯削，肢体振掉，苔色灰黑。前后大解共十三次，酱黑之色，逐次渐淡至于黄，溲亦浑黄不赤，昼夜进数十粒薄粥四五次，夜来忽寐忽醒，力不能转侧，言不足以听。脉微数，按之不鼓。年及中衰，体素羸弱，伏邪虽有欲解之势，元气渺无驱逐之权。邪热纵横，真阴枯涸，势必邪正俱败，危如朝露，急宜峻补，冀其五液三阴一振，正复不能容邪，从中击外，庶几一战于表，得战汗则解。", "12387": "生脉散加生地、归身、茯神、远志、枣仁、芦根", "12388": "（案3）六脉俱数，浮取不足，沉取有余。十日以来，神昏如醉，间或独语，苔淡黄不润，板齿无津，目赤唇焦，不饥不渴，与汤饭亦受，心下至少腹按之无痛满，大便如常，溲色红浑，伏邪盘踞太阳，热入膀胱。壬病逆传于丙，丙丁兄妹，由是传心，心火烁金，清肃不行，犯经旨死阴之禁，虑难有济，勉拟犀角地黄汤合导赤散加山栀，取清心保肺、导引邪火、屈曲下行之意。", "12389": "伤寒汗出淋漓则病不除，伏邪汗出淋漓则病将解。昨暮服药，汗更大出，发背沾衣，通宵达旦，凑凑不已，遍体凉和，六脉俱静，溲色澄清，惟中胃未醒。宜养胃生阴。", "12390": "（案5）诸气𪱥郁，皆属于肺。诸逆冲上，皆属于火。肺司百脉之气，肾藏五内之精。肾水承制五火，肺金运行诸气。悲则伤肺，恐则精却。思为脾志，忧本于心。思则气结，忧则耗气，郁化心阴，真气潜消，邪气日进，亢则为害。五志之阳，与邪浑一，俱从火化，烁阴耗液，所谓热蒸气腾，壮火食气是也。屡寐气屡升，不分左右，似呻吟而近太息，又非短气。寐则阳气下交于阴，血归于肝，气归于肾。清肃不行，蒸热不退，肾水不升，肺气不降，金水交伤，水火不济，肺热奚疑。饮入于胃，输于脾，归于肺，注于膀胱，溲赤是其明验。水出高源，拟用一味芦茎，取其清空之气，甘平之力，以达清虚而益气化，若雨露之溉，荡涤伏热即是，补阴清金，且兼开胃，不亦宜乎。", "12391": "（案6）脉伏而数，巅痛身疼，无汗，翕翕发热，啬啬恶寒，腠理致密，玄府不开，乃三阳表证也。拟九味羌活汤加味。", "12392": "服冲和汤加味，得汗遍身悉润，寒热已除，巅疼已止，浮数之脉已缓，惟身痛不休，乃表气未和，宜桂枝汤小和之。", "12393": "服桂枝汤，入夜神烦不寐，身反大热，脉反滑数，苔白如积粉，板滞不宣，汗出如浴，恶风不欲去衣，溲赤而浑，间有谵语，此伏邪内动，盘踞膜原，化热伤阴之渐。《经》以冬伤于寒，春必病温，夏必病热，盖始为寒而终成热。同气相求，伤寒遇寒则发。前服冲和汤，诸症乍退者，新感之寒邪从汗而解。身痛未除者，伏邪乘表虚而外越，与卫气相争，致令营卫失其常度。得桂枝诸症蜂起者，非桂枝之过，乃伏邪化热，直贯阳明，液耗阴伤，而祸乱起于萧墙之内，有神昏如醉、阴枯发痉之虑，故仲景有急下存津之旨。暂以吴氏达原饮观其进退。", "12394": "昨进达原饮，舌后之苔转黄，身热不从汗解，溲赤而浑，便溏色绛，竟夜不寐，神烦谵语，心下拒按，脉来滑数，腑浊虽行，液耗阴伤，可虑原方加减。", "12395": "昨药后，熟寐通宵，寅初忽觉憎寒，须臾寒战如疟，引被自履，遍身悉冷，四肢厥逆，脉细如丝，神情萧索，卯正遍身灼热，屏去衣被，躁扰不安。欲起者，再忽然大汗淋漓，始自头项，下溉周身，汗到之处，灼热遂除，如汤沃雪，食倾脉静身凉，神清气爽，诸症若失，此非转疟，乃战汗也。得战汗者，以其人本虚，内伏之邪既从腑气宣通而溃，则在经之邪孤悬难守，不攻自散，仍从表解，外与正争，邪正交争则战，邪退正复则已。正气不支，是以发战。宜安神养营。", "12396": "（案7）潜伏夹脊之内，横连膜原，去少阴尚近，离阳明不远，故溲浑而赤，神烦不寐，身热汗自出，不恶寒而微渴，显系邪气先从内出之于外也。所服之方多从表解，延今念三朝，身热转为潮热，如瘅疟之状，反无汗，大便易色如漆，中有血块。䐃肉全消，筋脉动惕，苔剥唇裂，神昏如醉，伏热稽留无由以泄，夺血无汗，夺汗无血，表液已枯，里血复竭，邪正两亡，殊难奏捷。勉拟一方，质诸明哲。", "12397": "（案8）达原饮达膜原之邪，冲和汤开太阳之表。大汗淋漓，衣被俱湿，身反大热，消渴引饮，舌苔根黄尖绛中央白而不润，溲浑赤，便不解，脉长洪而数，复邪中溃，郁热暴伸，散漫经中，不传胃腑，欲作战汗。宜人参白虎汤。", "12398": "小柴胡（汤）手少阳之枢，小陷胸（汤）抑纵横之热。服后熟寐，移时大便，迁延而解，从初更至平旦共六次，俱如败酱。溲频数，浑赤之色渐清。寒热往来，热势减半，濈然汗出，遍体凉和。数脉已缓，黄苔立腐。伏邪中溃，表里分传，正复不能容邪，余气散漫，击其惰归。宜开鬼门洁净腑。", "12399": "（案11）病经念八，口禁不语，身卧如塑，溲浑如柏汁，便解如猪肤，脉空弦无力，肉全消，皮肤甲错，舌卷目上视，心下热炽手。伏邪深陷厥阴，液脱阴枯已著。攻之不可，补之不及，两无生理。勉拟黄龙汤，取攻补兼施之意，以副百一之望。", "12400": "昨服黄龙汤，燥屎仍不下，溲浑赤如故，口禁不能言，身强直，形消，脉夺，目眩然不瞑，舌翘而不下。液脱阴亡，髓热发痉，化源已绝，无复资生，神机已息，枯魄独存。虽扁仓复起，乌能措其手足。仍以原方，再服一帖。", "12401": "（案1）疟邪之后，留热未除，先天固不足，后天亦不振。肾为先天，脾为后天，脾肾不足以化精微，酿生湿热，湿遏发黄，五液不充，热留阴分，致生潮热，阳明气至则啮齿，肾虚肝热则抽搐，脉来滑数无神。滋少阴理阳明，化湿浊清留热，顺其性以调之。", "12402": "小柴泻心加减共服十有二帖。痎势十去八九，当期似有如无，口干微渴，小溲频数，黄而不浑，脉象尚带微弦，目眦黄侵白眼。湿运余热未清。《经》以疾走汗出于肾，奔驰多汗，气喘耳鸣，左疝大如鹅卵，鼻中常流清涕，乃素来本症肾肺不足可知。平补三阴，为丸缓治。", "12403": "进补肾阴养心脾，阴黄已退，饮食颇增，二便如常，脉神形色俱起，既获效机，依方进步。", "12404": "（案4）三阴痎疟，寒热俱重，已经八次，发于深秋，溲清脉软，邪伏太阴，极难奏效。", "12405": "《经》以夏伤于暑，秋必痎疟，间二日一发之老疟也，起于客秋，延今不已。脉来迟缓，寒重热轻，精神疲倦。脾肾双亏，未宜止截。拟进东垣法。", "12406": "（案7）脉来软数无力，证本脏阴有亏，疟后中土受伤，怒郁肝阳苦逆，土不载木，肝病传脾，阴不配阳，水不济火，乃见竟夜无眠，食少无味，体倦神疲，虚阳上越等症。前进交通心肾，熟寐连宵，总服壮水之主，形神复振。曾患血崩，素多抑郁，肝木久失条舒，木郁化火，耗液伤阴，以故气从胁肋上升，贯膈冲咽，环脐作胀，仍以壮水济火为主，崇土安木辅之。", "12407": "（案1）肠癖赤白，气血俱伤，后重腹疼，溲赤脉数，暑滞俱重。河间云：溲而便脓血，气行而血自止，行血则便自愈，调气则后重除。宜芍药汤。", "12408": "（案2）因热贪凉，人情之常。过食生冷，脾胃受伤。值大火流西，新凉得令，寒湿得以犯中，下传于肾，致成肠癖。溲色清澄，是其明验，脉来缓弱，温中为主。", "12409": "二气素虚，七情不节，致伤脾胃，传化失常，清不能升，浊不由降，清气在下，则生飧泄，戊邪传癸，转为肠癖，色白如脓，日十余次，下时里急后重，脾阳肾水潜伤。舌苔色常黧黑，中寒格阳于上，腹中隐痛，癖久剥及肠胃脂膏，食减神疲，夜多噩梦，肾不交心，而中虚气馁。因循怠治，希冀自瘥。病情转剧将近一载。前进补中益气、归脾、六君等汤，以行升降之令。总服胃关煎、四神丸、五味子散，温固三阴，病势退而复进。脉体和而又否，病势若深，殊难奏捷。免拟温固命门，引火归窟，冀其丹田暖则火就燥，下元固则气归精。然否，质诸高明。", "12410": "客忤霍乱，内有所伤，伤其七情，外有所感，感于六气，阴阳乖错，吐泻交作，吐则伤阳伤胃，泻则伤阴伤肾。吐泻时，幸服理中，得有转机。今经念日，胸次胀满，口干非渴，脉弦无力。阳不生阴，阴不化气，阴阳俱亏，五液俱耗，乙癸同源是理。第肾阴不足以制肝阳。肝志为怒，怒则气上，气填胸膈，非食滞可比。肝无补法，补肾即所以补肝。人身之阴阳，阳则亲上而外卫，阴则亲下而内营，难成而易亏，补之非易，无阳则阴无以生，无阴则阳无以化，必得益气生阴，阴从阳化，肾气通于胃，阴精上蒸，清阳开展，自入佳境，二气两协，其平上下，互相流贯，自无否象。公议生脉八味，益火之源，壮水之主，从阴引阳，从阳引阴。是否，备政名哲。", "12411": "参脉散阳八味地黄丸", "12412": "肝脉渐和，胃脉尚软。夜来半寤半寐，二气渐有和顺之机。素本肾亏，虚寒之体，真阳不健，值大病之后，二气交伤，五液互损，脏腑之气，何由骤复。补阴之品，无过地黄，但守补则中枢易钝，得桂附走而不守，达肾火之窟，蕴生中土，方能化液生阴，不独不闷不滞，且于肾胃有潜襄之功，所谓补肾则胃开，补命门则脾健。清晨用原方略为加减，培补肾命之阴阳。午后以养胃生阴之品，阴阳交济之法。循理之至，似无背谬。是否，备政之于通明。", "12413": "立秋后四日，脉神形色俱起，脾胃渐苏，大病新瘥，脏腑初和，二气未定，全在静养工夫，当守摇精劳形之戒，澄心息虑，恬淡虚无，乃善后之良谋，五内得太和之气，自臻康豫。拟方仍候酌。", "12414": "（案1）客忤沙气，挥霍撩乱，吐泻交作，三焦俱伤，身冷脉伏，柔汗不收，目赤如鸩，溲红如血，浑如中毒，危在须臾。勉拟元戎法，尽其心力。", "12415": "（案2）沙气袭络，遍身苛痹，肢尖逆冷，胸喉气不展舒，六脉细涩无力。拟正气六和加减。", "12416": "（案3）烦闷欲吐，巅痛，肢尖冷，脉细涩，沙候也。", "12417": "（案3）天一生水，生人男女皆同。女子以血到为始，名曰天癸。男子以精到为始，亦名曰天癸。幼年通精，过早加以情欲之偏，剥丧频频，导致真元损耗，液络大亏，六脉洪大而急，咽嗌结核，瘰疬串久不消。今春左足溃脓血，上下左右四肢串肿而痛，昼夜无眠，不能反侧，每至睡将熟则肢节挛搐动摇。夫生人起居动息，卧则血归于肝。《经》云：肝为刚脏。又云：肝苦急，急则酸燥。阳生风动，善搐善摇，水不荣木，静不能藏，是以目瞪神迷，一哭而散。哭之所以能散者，上窍宣泄，清气有时而升，暂可平静，久之非所宜。症势棘王，滋水养肝为主。", "12418": "据云，服药数帖，症势未见动静。此症系肝血不充络，气燥不养筋。《经》云：软短为拘，陷脉为偻者是也。兹拟滋肝养血舒筋。盖水能涵木，缓缓培养。仍外加以熏络，庶不致增剧，清气活络无裨也。", "12419": "（案1）头风起自幼年，不俱四季皆疼，疼时太阳发胀，牙关亦然，饮热茶汗出则止。每晨起，午后渐止。延今多载，饮食如常，不能充养形骸，精神日减，脉弦无力，肝扰阳明。", "12420": "恙由耳后冲及巅顶，项强神烦，不能起坐，六脉细数而软，食减作痛，时作时止，初起似属偏头风证，补散难投。虚风游走，风化为火，风愈高火愈炽，阳不能固，阴不能敛。拟扶阳敛阴，俾气行血流，风行水动，庶可获效。", "12421": "（案1）水亏于下，火升于上，壮火食气，上虚则眩，头晕足软，如立舟车，咽喉干燥，梦泄频作。少阴肾脉上循喉，有梦而泄主于心。精不化气，水不上潮之明验也。清上实下是其大法。第水亏必盗气于金，金衰不能平木，水虚不能涵木，木燥生火，煎熬津液成痰。丹溪所谓无痰不作眩是也。脉来软数兼弦，值春令阳升，防其痉厥也。法宜壮水，佐以化痰。", "12422": "（案2）《经》以上气不足，脑为之不满，耳为之苦鸣，头为之苦倾，目为之眩。素本脾胃不足，抑郁不宣，气郁生痰，上扰清明之府，颠眩如驾风云，卒然溃乱，忽而神清，非类中可比，脉来软数无神。原当壮水之主，上病下取，滋苗灌根。第痰伏中州，清气无由上达，下取无以上承，拟以治痰为主。", "12423": "（案1）心为主宰，肾为根本，曲运神机，劳伤乎心，心神过用，暗汲肾阴，子午不交，寤而不寐。《经》云：经脉横解，肠癖为痔。亦由湿热伤阴，气虚不化，右脉虚大而弦，左脉濡滑。肾之阴亏，肝之阳强，心气不足。脾为太阴湿土，虚则生湿。利湿伤阴，清热耗气，阴虚忌燥热，阳虚忌苦寒。宜从心脾肾进补。", "12424": "（案2）年甫廿三，脉不应指，二天不振，心肾交亏，瘰疬难痊，气血伤而未复，心跳作呕。先养心脾，兼调肝肾。", "12425": "（案3）经以喜怒伤气，寒暑伤形，冲脉起于气街，夹脐上行，至胸中而散。冲脉动，诸脉皆动。少腹属厥阴，厥阴者，肝气也。从少腹跳动，冲逆上行，心慌意乱，虚里跳跃如梭。肾不养肝，气失摄纳，皆根蒂之亏。寡欲固精，清心尤要。", "12426": "（案4）年经廿旬，先天薄弱，后天不振，盗汗梦泄。上年六月，奔驰辛苦，痰中带血，每逢节令举发。去冬感寒停滞，病中又伤，盗汗甚多，昏沉似脱，病中走泄，曾服参附回阳，渐渐向安，卧床月余。今交夏至，饮食不香，午后肩背似乎拘束不舒，食后嗳气，肢体无力，筋骨酸痛，腰膝尤甚，若稍烦心，即觉心中疼痛气闷，小溲黄色俱多，清时日少。舌根之苔，病后至今未化。面无华色，脉来虚数。正气肾气伤而未复，少壮年华，必得清心静养，冀其复元，进后天以培先天。", "12427": "（案7）咳嗽夜甚，劳动气喘，夜卧不安，手心蒸热，精神不振，巅顶疼痛，形容日羸，脉来弦数，按之无力。三阴内亏，金水交伤。阴虚忌燥热，阳虚忌苦寒。虚劳内损，二气皆亏，全赖脾胃资生化源。拟以小海参丸加减", "12428": "（案8）诸风掉眩，皆属于肝。左脉甚小，心肝肾三阴皆亏。肾不养肝，心气益虚。右脉濡而且慢，真阳亦衰，头目眩晕，不耐操劳。寒凉者，真气之虚也。经以劳者温之，损者益之，本拟龟鹿二仙胶。现在中虚寒痰，先拟参附理阴合归脾。", "12429": "脉神形色俱起，眩晕渐减，中气、心气、肾气皆亏，水不涵木，木火交并，二气俱损。补阴不易，补阳尤难。阴从阳长，血随气生。前进黑归脾尚合机宜，今拟参附斑龙加味。", "12430": "水不配木，肾不纳气，气不归元，气有余便是火。右肾热气常漫，带多走泄，精神不振。肾属水，虚则生热。补阴不足，补阳尤难。脉象六阴，按之虚数不静。心肾两亏，今拟黑归脾合斑龙两仪起元法，培命肾之阴阳，冀其水火既济，自然纳气归窟。", "12431": "年已二旬，尚属童年，毫无知识，灵机蒙蔽，小解如常，脉来细小。先天不足，神识不开。开窍不能，必得神志充足，灵光自透。养先天、炼后天，徐徐调养。", "12432": "生脉散加陈仓米", "12433": "（案11）上损于下，损及于中，最属可虑。男子脉大为劳，三阴内损，下患痔漏，咳嗽气急，呕吐酸水。补土则金生，金生则水旺。诸虚百损，不舍脾胃。有胃气则生，无则死，洵不诬矣。", "12434": "顷奉手教，敬念令媛，恙原春分节令，未有变动，药分三次，徐徐服之，未作呕吐，仍觉胸中饱闷，渐渐方舒。每日食粥三次，每食一茶杯，不能多进，大便间或溏泻，小便畅行。阴阳渐分，夜眠较安。面色黄瘦，饮食不为肌肤。颧红渐退，咳痰稍减。脉症渐定，即是转机。徐徐调治，渐入佳境。拟方酌候。肃此奉复，并璧尊谦。", "12435": "（案14）脉来细涩，形容消瘦，脏阴营液俱亏。食少运迟，不为充养，卧则气促，三刻腹右气坠，兼有偏坠。脾胃不健，先天不足，后天不振。养先天炼后天，冀真元来复，是其大法。", "12436": "脉来细涩，眠食虽安，运纳不健，二天不振。养心脾兼和肝胃。", "12437": "脉神形色俱起，眠食俱安，运纳健旺，二天有振之机，原方加减。", "12438": "服药以来，脉神色俱起，胃口大开，生气来矣。以丸代煎。乘鸾之后，虫斯衍庆，益当加意节制。先天源源而厚，百福骈臻兰征。必矣。", "12439": "（案15）心脉短，肝脉虚，尺脉小，性燥多虑，心气亏虚，不耐操劳，客秋疟后失调，右脉濡滑，湿郁气虚，神倦无力，时发寒热，多走气急，二气亏虚，喜怒伤气，寒暑伤形。拟何人六君加味。", "12440": "精神不振，饮食不甘，五心烦躁，寤而不安，脉来虚数。三阴不足，心肾不交，水火不配。以丸代煎。", "12441": "三进阿胶鸡子黄汤，脉神色俱起。原方进步。", "12442": "（案18）忧思郁结，心神不宁，惊悸慌乱，肢颤发抖，饮食不思，咳嗽痰多，形容消瘦，脉见双弦，犯五行之忌。拟方多酌明哲。", "12443": "（案1）三经半产，阴阳未复。经来色淡，血虚可知。阴亏水不济火，血少木失敷荣。肝病传脾，脾伤不能为胃行其津液，荣养诸经，以故精神不振，动劳发热，脉来软数无神，有经闭血枯之象。法当静养培补真阴为主。", "12444": "（案2）肾为元阴之根，统五内之精。肺为元阴之本，司百脉之气。半产后阴伤精损，阴不敛阳，水不配火，精不化气，气不归精。壮火食气，火灼金伤。肾虚必窃气于金，精损必移枯于肺，肺肾俱困，他脏不充。肝病传脾，土不生金。清肃不降，金不平木，木复生火，火性炎上，上扰君心，心烦意乱，不知所从，竟夕无眠，悔怒数起，虚里穴动，食减神疲。壮水济火，补阴潜阳。以丸缓治。", "12445": "六味地黄丸合生脉散，加龟板蜜丸。", "12446": "（案3）脉来软数无力，证本脏阴有亏。阴亏，有阴中水亏、火亏之分。少年真阴不固，真阳失守。肾兼水火之司，水不生木，肝病传脾，火不生土，脾伤及肺。《经》以中气不足，溲便为之变，肾开窍于二阴，肾虚则水反为湿，脾虚则土不制水，水澄如膏糊，乃水液之浊，非白浊可比。宗气无根，虚里震动。肾为先天，脾为后天。脾土之健运，赖肾气之充盈。肾中水火不能上蒸中土，何由健运。中虚不能交通心肾，精无所倚，夜卧不安。脾之与胃，以膜相连。胃为水谷之海，前阴为宗筋之会，会于气街，冲脉贯于阳明。《经》所谓二阳之病发心脾，有不得隐曲是也。诸汗属阳明，卫气行于冲，气失卫外，故多汗。阳欲上潜，阴下摄之；阴欲下脱，阳上吸之。阴阳本不相离，水火同居一室。阴阳离决，精气乃绝。阴平阳秘，精神乃治。无阳则阴无以生，无阴则阳无以化。治宜从阳引阴，从阴引阳。", "12447": "（案5）真阴下亏，虚阳上越，水火不济，心肾乖违。五志过极，俱从火化，火愈炽水愈亏。曲直作酸，阴不敛阳，竟夜不寐，甚至心烦意乱，莫能自主。盖阳统乎阴，精本于气。上不安者，必由乎下。心气虚者，必因于精。脉软而弦。爰以六味三才加介类潜阳，专培五脏之精，冀其精化气，气归精，阴平阳秘，精神乃治。", "12448": "阴亏于下，木失敷荣。木乘土位，脾困于中。脾之与胃以膜相连。胃者卫之原，脾者荣之本。卫不外护则寒，营失中守则热。健运失常，饮食减少。水源不足，瘦削日加。奇脉有亏，经候不一。脉采虚数而弦，症本辛苦操劳所致。法当脾肾双培。", "12449": "（案6）少年白发，咽嗌不爽。六脉细数而软，咽属少阴，发乃血余。少阴主水，水不荣木，阴液久亏。丹溪谓壮水之火，血行气流。缓缓调养，庶可获效。", "12450": "（案2）咳嗽气喘，胸中气急且闷，多食不舒，甚则头面上火。脉来沉滑而疾。气闷痰郁，肺胃不展。暂以外台茯苓饮加味。", "12451": "（案3）左脉涩，右脉沉，按之颇不宁静。心肝肾三阴内亏，疟后又伤湿热，郁而不化。中虚肺虚，劳动气喘，面带阳光。素有疝气，不能温补。客冬牙疼，火炎于上，咳嗽不宁，两胁微疼。金水交伤，气火升腾莫制。肺为娇脏，恶寒恶热，恶风恶燥。病延已久，虑难奏捷。", "12452": "（案5）左脉沉涩，右脉沉滑，推之不静。痰郁咳嗽，阴亏虽虚，肺气不展，久咳不已，则三焦受伤。慎勿轻视舒肺胃，以展气化。最怕心令司权，致有音哑之患。", "12453": "（案6）脉来滑数，肺有郁痰，咳喘不宁，口干身倦，不思饮食。病久人虚，极难奏效。", "12454": "（案7）咳嗽痰多，脉来濡滑，气虚痰郁。脾受湿侵，渍之于肺。杏苏二陈加味。", "12455": "服药四剂，咳嗽稍松，肺气已舒，腋痛已止，脉尚未清。", "12456": "（案13）左脉沉小，右脉濡涩。肝阴不足，气虚痰郁，肺为娇脏，不耐邪侵，犯之毫毛必咳。肺不和则鼻不闻香臭，冒风则咳甚，卧时喉中有水鸡声。肺虚治节不行，肝虚气冲于上。本用金水六君，现肺郁风邪，先以清疏为主。", "12457": "咳势大减，夜能安寐，痰涎已少，舌苔已化，饮食稍增，语言如常，脉来甚小。正气已虚，仍宗前法，助以辅正。", "12458": "咳为肺病，喘为肾病，五脏六腑皆令人咳，不独在肺，明矣。咳嗽痰涎白沫，音岚日哑，饮食日少，形容日羸，舌白脉弦。土败金伤，肾虚水泛为痰，中虚积饮水湿，浸淫渍之与肺，肺伤于肾，三焦俱病，殊堪大虑，谨防喘促。", "12459": "复脉汤去桂枝、姜、枣，加黄芩、白糖，拌黑芝麻。", "12460": "（案21）咳逆日久，至五更更剧。《经》云：五更嗽者，火浮于肺也。寒热胸闷，不欲食，脉浮而滑。风逆肺腑，久则伤脾。补土生金为治，非劳瘵也。", "12461": "（案22）肝火冲肺，咳逆作热，热久伤胃，口无味，不欲食，难于大解，脉软神疲。肝脾肺三经受恙。", "12462": "（案3）幼年哮喘，秋冬举发，发则不能安枕，痰豁乃平，脉弦兼滑。风痰郁肺，已历多年，极难脱体。先以小青龙汤加味。", "12463": "（案4）脉滑而数，郁热郁痰，清肃不行，大哮痰喘，似宜清燥救肺。但久病肺虚，苦寒虽效，不宜常服，恐伤生发之气。先哲明论，年少病深，难于奏捷。", "12464": "服药后，胃口渐开，夜能安卧，头痛已痊，胃口已开。哮喘未作，惟早间稍有咳嗽，气不舒畅，脉之滑数较平。仍清气分之热。", "12465": "（案5）肺为娇脏，清空之所，内配胸中，为五脏六腑之华盖。六叶两耳，二十四节。按二十四气，主百脉之气、至娇之脏，不耐邪侵，犯之毫毛，必咳寅辰。寒客肺腧，宜服小青龙、小建中，化邪外达。邪郁肺络，变生哮喘，发则声如曳锯，不能安卧。已延四载，终身之累也。", "12466": "（案6）童年哮喘，其自风寒。冬令即发，间或咳逆，痰中带血，白沫较多，气急不能平卧，难以安枕。近年愈发愈勤，正气肾气皆亏，脉来软细，所谓形丰脉空，外强中弱，少壮若此，衰年何堪。骤补则郁痰，伏邪不化，疏则正气更伤。补土生金，金来生水，病急药缓，又值火令司权，温补燥热，俱宜暂停，恐火气发喘之变。", "12467": "脉来沉滑而疾，右得涩象。幼年哮喘，病入肺络，延今多载，正气肾气俱亏，不能化邪外达。前进补土生金。久病已和，调养肺胃。至于三子养亲、苏子降气、小青龙宁嗽法，取效于一时，非常服之方。太阴湿土司命，湿侵积肺，又当一论，非泛泛风哮之治。现将火气发泄之时，用药尤难，拟方多酌。", "12468": "脉来沉滑而疾，右之濡象俱透，似有火象。气闷作嘈，气升则头汗，喉中有声，不能见风。但久病正气肺气俱亏，难于速效。", "12469": "（案1）中伤肺虚，咳嗽失血，红紫不一，痰中带血，形消发热，脉来虚数。慎防喉痛音哑，变生肺痿。", "12470": "（案2）咳出于肺，有痰为嗽，火灼金伤，始因风伏于肺络，咳嗽失红。前年三月，迎风伐肺，由此音哑。肺气郁而音不开，手足发热，口干心悸，浮火时升，饥则尤甚，脉来细虚。金伤成痿，恐难奏效。", "12471": "（案4）久咳音哑，喉痛作干，形神日瘦，饮食日少。金水两伤，阴不上潮，肺痿已著。所服导火归原，金水相生，是其法程。时值午火司权，金水益亏，脉来沉数。沉者郁也；数者，火也。七情不适，郁结化火，火灼金伤，理当补阴。奈饮食减少，寒热往来，暂从木郁达之。营出于中焦，资生于胃。诸虚百损，全赖脾胃。资生化源，补土生金。拟补阴益气加味。病势深沉，虑难奏捷。", "12472": "咳嗽已平，喉痛未减，三日声音未开。憎寒虽止，蒸热未退，脉来沉数。郁结化火，火灼金伤，真阴随之消耗，病深难以为力。再拟一方，回府多酌明哲。", "12473": "（案6）咳病经年，形神稍变，午后发热，又增喉痛难食。脉来细数不宁，右寸不来。金水交亏，中伤肺痿，极难奏捷。", "12474": "久咳喉痛，脉形神俱亏，午后发热，饮食不思，苔黄，火燥金痿，金水交伤。经补肺喉痛稍轻，咳嗽虽平，脉未起色，究属不宜。再拟千金方合前法，有效乃吉，否则另请高明。", "12475": "服药虽效，脉无起色，终属不宜。再拟一方，以观如何。", "12476": "中伤肺损，木火上冲，始而背痛，左腋亦然。伤力蓄瘀，气血紊乱，昼夜无眠，咳嗽气喘，痰带花红，且有腥秽，肺痈已著。脉来芤象，殊属不宜。勉拟一方，是否，备政于通明。", "12477": "（案1）年经三九，幼年失血。今岁三月，举发红虽止，咳嗽不宁，天明尤甚，脉滑痰多，食不甘味。肺胃中伤，难于速效。", "12478": "（案2）始由阴虚伤风，咳嗽白痰，四月间痰带红点，四五日即止。肾虚耳鸣、盗汗、脱肛，脉来虚数。肺肾两伤，此属内损。速远房帷，独居静养。真阴来复，方能有济。", "12479": "（案4）肺无因而不咳，络不伤血不出。客秋感冒，呛咳不已，呕恶，饮食不香，逮至冬日，吐血甚多，其色鲜红。今春又吐，咳不能寐，身痛麻木，脉不安静。气分有火，血分有热。", "12480": "（案5）失血多年，朝暮呛咳，交节尤甚。现三五日一发，吐血不止，胸次作胀，气阻中宫，不饥不纳，身热巅疼，脉象沉弦，思虑烦心。肝郁中伤，肺胃交病。", "12481": "（案6）《经》以大怒则形气绝，而血菀于上。郁结化火，火载血上，狂吐之后，咳嗽不已，旬日必遗泄，脉来弦数。水不养肝，木击金鸣，肝虚制胃，久延非宜。", "12482": "（案7）三阴内亏，酒湿兼伤，下有漏危，火载血上，咳嗽食少，脉来虚数。三焦俱损，必得静养，保守太真，生气来复，方克有济。", "12483": "进补土生金，饮食未增，咳嗽仍然，脉神形色未起，殊堪大虑。亏损之病，又值暑热伤阴，伤阴尤为棘手。再拟一方，有效则吉。", "12484": "服药后身体较前尚属平静。子午咳嗽稍轻，形消，脉夺，亏损已极。补土生金，或可有济。", "12485": "（案10）年逾花甲，二气就衰。客冬风冷，咳嗽延至今夏。痰带红紫，夜不能寐，身痛气喘，动劳尤甚，饮食不香，足跗浮肿，蔓延于上。寒生湿，湿生热，湿热内困，土败金伤。脉来参伍不调，生气大损，胃败中伤，暂养心脾胃。胃开纳食，方能转机。", "12486": "（案13）年甫十八，咯血载余，干咳血上，脉来细涩。先天本弱，脏阴营液俱耗。素有走泄，肺肾两亏，极难调治。", "12487": "咯血略减，仍有紫色，脉之细涩较和，仍守原意。", "12488": "三日未见血迹，咳势大减，左脉涩象渐和。原方加减。", "12489": "（案14）肝藏诸经之血，肺司百脉之气。年逾五六，饮食少纳，体生疹块。客岁右肩作痛，四肢无力，今正咳嗽带红。惊蛰节后气逆，右胁痛胀，周身筋骨不和，脉来虚大而弦。肝为起病之源，肺为传病之所。木扣金鸣，阳明不司束筋骨以利机关。春分节令，慎防气喘血溢。", "12490": "（案16）恙由前岁疟后腹胀，胀后音哑。客夏失血，咳嗽延今不已，午后气逆，丹田上冲，呕吐白沫，痰涎间有血点，卧则喉内痰声即咳醒，每夜数十次。饮食不香，脉来细涩。金水交伤，肾气不纳，殊堪大虑。拟附都气，引火归元，纳气归窟。", "12491": "（案17）脉象闪烁，咳甚痰嘶，且不易出，岚音不振，面无华色，唇白舌白，气不生阴，阴不上潮，积痰化饮，似宜真武法。春分节令，二气平分，且以猪肤甘桔，服一二帖，再议回府，慎调可也。", "12492": "音声不开，痰声略减，饮食不增，脉来细涩不起。拟孙真人法，再拟郭元先生琼玉膏。回府静养，不动肝怒，不起心阳，返观内守。庶可挽神明于冲漠，请诸名哲斟酌。", "12493": "（案19）失血之脉，缓静为顺，洪大为逆。半产后气血紊乱，血随气上，脉来洪大而弦。血不养肝，肝不藏血，气火升腾莫制。慎防喘汗血脱。拟引血归经法。", "12494": "（案21）脉弦而数，肝郁化火，火灼金伤。咳嗽发热，客夏失血，红紫不一，血止后咳嗽不宁，木扣金鸣。拟以解郁疏肝法。", "12495": "脉仍弦数，木火刑金，失红后咳嗽不宁，蒸热带下。气虚阴亏，肝火失达。", "12496": "（案22）客秋寒热干呛，或愈或发，九月吐血十余日，腊月又发寒热咳嗽，今正咳嗽带红，昼少夜多，脉来虚数，中虚肺虚，湿热郁痰为患。", "12497": "（案32）幼年失血，频频举发，延今多载，屡愈屡发，客冬吐红十余口。血止之后，今春兼忧思动怒，肝不藏血，火载血上，咳嗽口干。木扣金鸣，脉来虚数。肝不平宁，又值火令司权，谨防喉痛音哑。", "12498": "肺司百脉之气，肝藏诸经之血，肾司生命之本。咳嗽失血，痰中又带。午后浮火时升，常多走泄，欲图生机，必得下关速闭，舍此无济。", "12499": "（案33）三月初旬，风湿上受，发热三日，吐血鲜红。四月中旬，血又复来，至今不断，两胁微痛，胸次亦然，仍防涌逆。失血之脉，贵乎宁静，脉来滑数，火犯阳络，极难奏效。"});